export type Account = ReturnType<typeof decodeAccount>;

export interface ListPage<T> {
  readonly data: readonly T[];
  readonly hasMore: boolean;
}

export interface SearchPage<T> extends ListPage<T> {
  readonly nextPage: string | null;
}

export function listOf<T>(item: Decoder<T>): Decoder<ListPage<T>> {
  const decode = object({ object: field("object", literal("list")), data: field("data", array(item)), hasMore: field("has_more", bool) });
  return (value, path) => {
    const { data, hasMore } = decode(value, path);
    return { data, hasMore };
  };
}

export function searchOf<T>(item: Decoder<T>): Decoder<SearchPage<T>> {
  const decode = object({
    object: field("object", literal("search_result")),
    data: field("data", array(item)),
    hasMore: field("has_more", bool),
    nextPage: field("next_page", nullableOrAbsent(str)),
  });
  return (value, path) => {
    const { data, hasMore, nextPage } = decode(value, path);
    return { data, hasMore, nextPage };
  };
}

export const decodeEventEnvelope = object({
  id: field("id", str),
  object: field("object", literal("event")),
  type: field("type", str),
  created: field("created", int),
  livemode: field("livemode", bool),
  apiVersion: field("api_version", nullable(str)),
  data: field("data", (value, path) => {
    const data = asRecord(value, path);
    const inner = asRecord(data["object"], `${path}.object`);
    return { objectType: str(inner["object"], `${path}.object.object`), objectId: str(inner["id"], `${path}.object.id`), object: inner };
  }),
});

export interface StripeEvent {
  readonly id: string;
  readonly type: string;
  readonly created: number;
  readonly livemode: boolean;
  readonly apiVersion: string | null;
  readonly objectType: string;
  readonly objectId: string;
  readonly object: Readonly<Record<string, unknown>>;
}

export class ConnectEventError extends StripeDecodeError {
  constructor() { super("$.account", "Connect events are not accepted"); }
}

export function decodeEvent(value: unknown): StripeEvent {
  const record = asRecord(value, "$");
  if (record["account"] !== undefined) throw new ConnectEventError();
  const { id, type, created, livemode, apiVersion, data } = decodeEventEnvelope(value, "$");
  return { id, type, created, livemode, apiVersion, objectType: data.objectType, objectId: data.objectId, object: data.object };
}

export function decodeEventText(text: string): StripeEvent {
  return decodeEvent(parseJson(text, null));
}

export const decodeErrorBody = object({
  error: field("error", object({
    type: field("type", str),
    code: field("code", nullableOrAbsent(str)),
    message: field("message", nullableOrAbsent(str)),
    param: field("param", nullableOrAbsent(str)),
  })),
});
