import { Schema } from "effect";
import { ShapeProblems } from "../catalog/edit.ts";
import { Integer } from "../storefront/queries.ts";

const Digest = Schema.String.check(Schema.makeFilter<string>((value) => /^[0-9a-f]{64}$/.test(value) || "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(Schema.makeFilter<number>((value) => (value >= 0 && Number.isSafeInteger(value)) || "must be a non-negative integer number of seconds"));
const Purpose = Schema.String.check(Schema.makeFilter<string>((value) => (/^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= 128) || "must be a purpose label"));

export const StatusSchema = Schema.Literals(["draft", "active", "archived"]);

const ProductFields = { title: Schema.String, handle: Schema.String, vendor: Schema.NullOr(Schema.String), description: Schema.String };
const CollectionFields = { title: Schema.String, handle: Schema.String, description: Schema.String };

export const CatalogChangeSchema = Schema.Union([
  Schema.Struct({ action: Schema.Literal("product.create"), ...ProductFields, price: Schema.String }),
  Schema.Struct({ action: Schema.Literal("product.update"), productId: Integer, expectedRevision: Integer, ...ProductFields }),
  Schema.Struct({ action: Schema.Literal("product.status"), productId: Integer, expectedRevision: Integer, status: StatusSchema }),
  Schema.Struct({ action: Schema.Literal("product.duplicate"), productId: Integer }),
  Schema.Struct({ action: Schema.Literal("products.status"), productIds: Schema.Array(Integer), status: StatusSchema }),
  Schema.Struct({ action: Schema.Literal("variant.update"), productId: Integer, expectedRevision: Integer, variantId: Integer, title: Schema.NullOr(Schema.String), price: Schema.String, available: Schema.Boolean }),
  Schema.Struct({ action: Schema.Literal("variant.add"), productId: Integer, expectedRevision: Integer, title: Schema.NullOr(Schema.String), price: Schema.String, available: Schema.Boolean, selections: Schema.Array(Schema.Struct({ optionId: Integer, valueId: Integer })) }),
  Schema.Struct({ action: Schema.Literal("variant.remove"), productId: Integer, expectedRevision: Integer, variantId: Integer }),
  Schema.Struct({ action: Schema.Literal("option.add"), productId: Integer, expectedRevision: Integer, name: Schema.String, value: Schema.String }),
  Schema.Struct({ action: Schema.Literal("option.remove"), productId: Integer, expectedRevision: Integer, optionId: Integer }),
  Schema.Struct({ action: Schema.Literal("value.add"), productId: Integer, expectedRevision: Integer, optionId: Integer, value: Schema.String }),
  Schema.Struct({ action: Schema.Literal("value.remove"), productId: Integer, expectedRevision: Integer, valueId: Integer }),
  Schema.Struct({ action: Schema.Literal("image.add"), productId: Integer, expectedRevision: Integer, detailMediaId: Integer, cardMediaId: Schema.NullOr(Integer), alt: Schema.String }),
  Schema.Struct({ action: Schema.Literal("image.remove"), productId: Integer, expectedRevision: Integer, imageId: Integer }),
  Schema.Struct({ action: Schema.Literal("image.alt"), productId: Integer, expectedRevision: Integer, imageId: Integer, alt: Schema.String }),
  Schema.Struct({ action: Schema.Literal("image.move"), productId: Integer, expectedRevision: Integer, imageId: Integer, direction: Schema.Literals(["up", "down"]) }),
  Schema.Struct({ action: Schema.Literal("collection.create"), ...CollectionFields }),
  Schema.Struct({ action: Schema.Literal("collection.update"), collectionId: Integer, expectedRevision: Integer, ...CollectionFields }),
  Schema.Struct({ action: Schema.Literal("collection.status"), collectionId: Integer, expectedRevision: Integer, status: StatusSchema }),
  Schema.Struct({ action: Schema.Literal("collection.member_add"), collectionId: Integer, expectedRevision: Integer, productId: Integer }),
  Schema.Struct({ action: Schema.Literal("collection.member_remove"), collectionId: Integer, expectedRevision: Integer, productId: Integer }),
  Schema.Struct({ action: Schema.Literal("collection.member_move"), collectionId: Integer, expectedRevision: Integer, productId: Integer, direction: Schema.Literals(["up", "down"]) }),
]);
export type CatalogChange = typeof CatalogChangeSchema.Type;

export const CatalogRejections = [
  ...ShapeProblems,
  "unknown_product",
  "unknown_collection",
  "handle_taken",
  "invalid_input",
  "invalid_price",
  "status_unchanged",
  "in_cart",
  "commercial_reference",
  "not_member",
  "already_member",
  "at_edge",
  "media_unavailable",
  "unknown_image",
] as const;
export type CatalogRejection = (typeof CatalogRejections)[number];

export const CatalogMutateCommand = Schema.Struct({
  kind: Schema.Literal("catalog.mutate"),
  sessionDigest: Digest,
  formTokenDigest: Digest,
  purpose: Purpose,
  actor: Schema.String,
  nowSeconds: Seconds,
  change: CatalogChangeSchema,
});

const Currency = Schema.Struct({ code: Schema.String, exponent: Schema.Int });
export type CurrencyView = typeof Currency.Type;
const AuditEntry = Schema.Struct({ id: Integer, actor: Schema.String, action: Schema.String, entityRevision: Schema.NullOr(Integer), summary: Schema.String, createdAt: Integer });
const StockSummary = Schema.Struct({ onHand: Integer, held: Integer, allocated: Integer });

export const ProductListView = Schema.Struct({
  currency: Currency,
  items: Schema.Array(Schema.Struct({ id: Integer, handle: Schema.String, title: Schema.String, status: StatusSchema, revision: Integer, variantCount: Integer, minPrice: Schema.NullOr(Integer), maxPrice: Schema.NullOr(Integer) })),
  hasMore: Schema.Boolean,
});
export type ProductListViewModel = typeof ProductListView.Type;

export const ProductEditView = Schema.Struct({
  currency: Currency,
  product: Schema.Struct({ id: Integer, handle: Schema.String, title: Schema.String, vendor: Schema.NullOr(Schema.String), description: Schema.String, status: StatusSchema, revision: Integer }),
  options: Schema.Array(Schema.Struct({ id: Integer, name: Schema.String, values: Schema.Array(Schema.Struct({ id: Integer, value: Schema.String })) })),
  variants: Schema.Array(Schema.Struct({ id: Integer, title: Schema.NullOr(Schema.String), priceMinor: Integer, available: Schema.Boolean, labels: Schema.Array(Schema.String), stock: Schema.NullOr(StockSummary), cartLines: Integer })),
  images: Schema.Array(Schema.Struct({ id: Integer, url: Schema.String, altText: Schema.String, width: Schema.NullOr(Integer), height: Schema.NullOr(Integer), managed: Schema.Boolean })),
  details: Schema.Array(Schema.Struct({ key: Schema.String, title: Schema.String, body: Schema.String })),
  collections: Schema.Array(Schema.Struct({ id: Integer, title: Schema.String, status: StatusSchema })),
  audit: Schema.Array(AuditEntry),
});
export type ProductEditViewModel = typeof ProductEditView.Type;

export const CollectionListView = Schema.Struct({
  items: Schema.Array(Schema.Struct({ id: Integer, handle: Schema.String, title: Schema.String, status: StatusSchema, revision: Integer, memberCount: Integer })),
  hasMore: Schema.Boolean,
});
export type CollectionListViewModel = typeof CollectionListView.Type;

export const CollectionEditView = Schema.Struct({
  collection: Schema.Struct({ id: Integer, handle: Schema.String, title: Schema.String, description: Schema.String, status: StatusSchema, revision: Integer }),
  members: Schema.Array(Schema.Struct({ productId: Integer, handle: Schema.String, title: Schema.String, status: StatusSchema })),
  memberCount: Integer,
  audit: Schema.Array(AuditEntry),
});
export type CollectionEditViewModel = typeof CollectionEditView.Type;

export const CatalogQuerySchema = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("catalog.products"), after: Integer, status: Schema.Literals(["", "draft", "active", "archived"]) }),
  Schema.Struct({ kind: Schema.Literal("catalog.product"), productId: Integer }),
  Schema.Struct({ kind: Schema.Literal("catalog.collections"), after: Integer }),
  Schema.Struct({ kind: Schema.Literal("catalog.collection"), collectionId: Integer }),
  Schema.Struct({ kind: Schema.Literal("catalog.new") }),
]);
export type CatalogQuery = typeof CatalogQuerySchema.Type;

export const CatalogQueryResultSchema = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("catalog.products"), view: ProductListView }),
  Schema.Struct({ kind: Schema.Literal("catalog.product"), view: Schema.NullOr(ProductEditView) }),
  Schema.Struct({ kind: Schema.Literal("catalog.collections"), view: CollectionListView }),
  Schema.Struct({ kind: Schema.Literal("catalog.collection"), view: Schema.NullOr(CollectionEditView) }),
  Schema.Struct({ kind: Schema.Literal("catalog.new"), currency: Schema.NullOr(Currency) }),
]);
export type CatalogQueryResult = typeof CatalogQueryResultSchema.Type;

export const CatalogMutateResult = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("catalog.mutate"), outcome: Schema.Literal("applied"), entityId: Integer }),
  Schema.Struct({ kind: Schema.Literal("catalog.mutate"), outcome: Schema.Literals(["session_invalid", "token_invalid", "stale"]) }),
  Schema.Struct({ kind: Schema.Literal("catalog.mutate"), outcome: Schema.Literal("rejected"), rejection: Schema.Literals(CatalogRejections) }),
]);
