import { digestBytes, guardedMutation, type Mutation } from "../admin/guard.ts";
import { searchDigestOf } from "../admin/orders_search.ts";
import { all, audit, get, run, type Program } from "../admin/program.ts";
import {
  AccessLifetimeSeconds, decideBegin, EmailSendKind, emailSendKey, isEmailKind, isEmailState, LookupLimit, LookupWindowSeconds, mayResend, UnknownWindowSeconds,
  type EmailKind,
} from "./email.ts";
import type { EmailCommand, EmailCommandResult, EmailFacts, EmailMessageView, EmailQuery, EmailQueryResult } from "./email_operations.ts";

type Of<K extends EmailCommand["kind"]> = Extract<EmailCommand, { readonly kind: K }>;
type ResultOf<K extends EmailCommandResult["kind"]> = Extract<EmailCommandResult, { readonly kind: K }>;

export const EmailActor = "email";

export type EmailSubject =
  | { readonly kind: Exclude<EmailKind, "late_void">; readonly orderId: bigint; readonly subjectId: bigint }
  | { readonly kind: "late_void"; readonly attemptId: bigint };

function* scheduleSend(messageId: bigint, generation: bigint, now: bigint): Program<void> {
  yield* run("ScheduleWork", [EmailSendKind, emailSendKey(messageId, generation), JSON.stringify({ message: messageId.toString(), generation: generation.toString() }), now, now, now]);
}

export function* queueEmail(subject: EmailSubject, now: bigint): Program<bigint | null> {
  const orderId = subject.kind === "late_void" ? null : subject.orderId;
  const attemptId = subject.kind === "late_void" ? subject.attemptId : null;
  const subjectId = subject.kind === "late_void" ? 0n : subject.subjectId;
  const inserted = yield* run("InsertEmailMessage", [subject.kind, orderId, attemptId, subjectId, now, now]);
  if (inserted === 0n) return null;
  const row = subject.kind === "late_void"
    ? yield* get("GetEmailMessageBySubject", [subject.kind, subject.attemptId, 0n])
    : subject.kind === "access_link"
      ? yield* get("GetNewestEmailMessage", [subject.kind, subject.orderId])
      : yield* get("GetEmailMessageBySubject", [subject.kind, subject.orderId, subject.subjectId]);
  if (row === null) throw new Error(`email: the ${subject.kind} message was not written`);
  yield* scheduleSend(row.id, row.generation, now);
  return row.id;
}

function* orderRevision(orderId: bigint): Program<bigint> {
  const row = yield* get("GetOrderRevisionById", [orderId]);
  if (row === null) throw new Error(`email: order ${orderId} does not exist`);
  return row.revision;
}

export function* queueConfirmation(orderId: bigint, now: bigint): Program<void> {
  yield* queueEmail({ kind: "order_confirmation", orderId, subjectId: 0n }, now);
}

export function* queueShipment(orderId: bigint, sequence: bigint, now: bigint): Program<void> {
  yield* queueEmail({ kind: "shipment", orderId, subjectId: sequence }, now);
}

export function* queueCancellation(orderId: bigint, voided: boolean, now: bigint): Program<void> {
  yield* queueEmail({ kind: voided ? "cancellation_voided" : "cancellation_items", orderId, subjectId: yield* orderRevision(orderId) }, now);
}

export function* queueRefund(orderId: bigint, refundId: bigint, now: bigint): Program<void> {
  yield* queueEmail({ kind: "refund", orderId, subjectId: refundId }, now);
}

export function* queueLateVoid(attemptId: bigint, now: bigint): Program<void> {
  yield* queueEmail({ kind: "late_void", attemptId }, now);
}

function* factsOf(kind: EmailKind, orderId: bigint | null, attemptId: bigint | null, subjectId: bigint): Program<EmailFacts> {
  if (kind === "late_void") {
    const attempt = attemptId === null ? null : yield* get("GetEmailAttempt", [attemptId]);
    if (attempt === null) throw new Error("email: the attempt of a late-void message no longer exists");
    return {
      kind, to: attempt.contact_email, shopName: attempt.shop_name, orderNumber: null, currency: attempt.currency_code, exponent: Number(attempt.currency_exponent),
      totalMinor: attempt.total_minor, destination: null, lines: [], shipment: null, refundMinor: null,
    };
  }
  const order = orderId === null ? null : yield* get("GetEmailOrder", [orderId]);
  if (order === null || orderId === null) throw new Error("email: the order of a message no longer exists");
  const lines = yield* all("ListOrderLineStates", [orderId]);
  const titles = new Map(lines.map((line) => [line.position, { title: line.title, variantLabel: line.variant_label }]));
  let shipment: EmailFacts["shipment"] = null;
  if (kind === "shipment") {
    const shipments = yield* all("ListOrderShipments", [orderId]);
    const row = shipments.find((candidate) => candidate.sequence === subjectId);
    if (row === undefined) throw new Error(`email: shipment ${subjectId} of order ${order.number} does not exist`);
    const shipped = (yield* all("ListOrderShipmentLines", [orderId])).filter((line) => line.fulfillment_id === row.id);
    shipment = {
      sequence: row.sequence, carrier: row.carrier, trackingNumber: row.tracking_number, trackingUrl: row.tracking_url,
      lines: shipped.map((line) => ({ ...(titles.get(line.position) ?? { title: "Item", variantLabel: "" }), quantity: line.quantity })),
    };
  }
  let refundMinor: bigint | null = null;
  if (kind === "refund") {
    const refund = yield* get("GetEmailRefund", [subjectId, orderId]);
    if (refund === null) throw new Error(`email: refund ${subjectId} of order ${order.number} does not exist`);
    refundMinor = refund.amount_minor;
  }
  return {
    kind, to: order.contact_email, shopName: order.shop_name, orderNumber: order.number, currency: order.currency_code, exponent: Number(order.currency_exponent),
    totalMinor: order.total_minor, destination: order.fulfillment === "ship" && order.city !== null && order.region !== null ? `${order.city}, ${order.region}` : null,
    lines: lines.map((line) => ({ title: line.title, variantLabel: line.variant_label, quantity: line.quantity, unitPriceMinor: line.unit_price_minor, lineTotalMinor: line.line_total_minor })),
    shipment, refundMinor,
  };
}

function* beginEmail(command: Of<"email.begin">): Program<ResultOf<"email.begin">> {
  const skip = (reason: Extract<ResultOf<"email.begin">, { readonly outcome: "skip" }>["reason"]): ResultOf<"email.begin"> => ({ kind: "email.begin", outcome: "skip", reason });
  const now = BigInt(command.nowSeconds);
  const row = yield* get("GetEmailMessage", [command.id]);
  if (row === null) return skip("not_found");
  if (row.generation !== command.generation) return skip("superseded");
  const state = row.state;
  if (!isEmailState(state) || !isEmailKind(row.kind)) throw new Error(`email: message ${row.id} has an unknown state or kind`);
  const decision = decideBegin(state, row.first_attempt_at, now);
  if (decision.kind === "skip") {
    if (decision.reason === "window_closed") yield* run("ExpireUnknownEmail", ["no definite answer within 24 hours; not resent automatically", now, row.id, row.generation]);
    return skip(decision.reason);
  }
  if ((yield* run("BeginEmailAttempt", [now, now, now, row.id, row.generation])) !== 1n) throw new Error(`email: message ${row.id} changed while its attempt began`);
  const facts = yield* factsOf(row.kind, row.order_id, row.attempt_id, row.subject_id);
  if (row.order_id !== null) {
    yield* run("InsertOrderAccess", [digestBytes(command.accessDigest), row.order_id, row.id, now, now + BigInt(AccessLifetimeSeconds)]);
  }
  return { kind: "email.begin", outcome: "send", attempts: row.attempts + 1n, facts };
}

function* settleEmail(command: Of<"email.settle">): Program<ResultOf<"email.settle">> {
  const changed = yield* run("SettleEmailMessage", [command.state, command.providerId, command.error, BigInt(command.nowSeconds), command.id, command.generation]);
  return { kind: "email.settle", changed: changed > 0n };
}

function* resendEmail(command: Of<"email.resend">): Program<ResultOf<"email.resend">> {
  const guarded = yield* guardedMutation<null, "not_found" | "not_resendable">(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    function* (): Program<Mutation<null, "not_found" | "not_resendable">> {
      const order = yield* get("GetOrderLookupTarget", [command.number]);
      const row = yield* get("GetEmailMessage", [command.messageId]);
      if (order === null || row === null || row.order_id !== order.id) return { applied: false, result: "not_found" };
      const now = BigInt(command.nowSeconds);
      if (!isEmailState(row.state) || !mayResend(row.state, row.first_attempt_at, now)) return { applied: false, result: "not_resendable" };
      const requeued = yield* run("RequeueEmailMessage", [now, row.id, order.id, now - BigInt(UnknownWindowSeconds)]);
      if (requeued !== 1n) return { applied: false, result: "not_resendable" };
      yield* scheduleSend(row.id, row.generation + 1n, now);
      yield* audit({
        actor: command.actor, action: "email.resend", entityKind: "order", entityId: order.id.toString(), entityRevision: null,
        summary: `message ${row.id} (${row.kind}, ${row.state}) resent as generation ${row.generation + 1n}`,
      }, now);
      return { applied: true, result: null };
    },
  );
  if (guarded.outcome !== "done") return { kind: "email.resend", outcome: guarded.outcome };
  return { kind: "email.resend", outcome: guarded.mutation.applied ? "applied" : guarded.mutation.result };
}

function* revokeAccess(command: Of<"order.access_revoke">): Program<ResultOf<"order.access_revoke">> {
  const guarded = yield* guardedMutation<{ readonly revoked: bigint }, "not_found">(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    function* (): Program<Mutation<{ readonly revoked: bigint }, "not_found">> {
      const order = yield* get("GetOrderLookupTarget", [command.number]);
      if (order === null) return { applied: false, result: "not_found" };
      const now = BigInt(command.nowSeconds);
      const revoked = yield* run("RevokeOrderAccess", [now, order.id]);
      yield* audit({
        actor: command.actor, action: "order.access_revoke", entityKind: "order", entityId: order.id.toString(), entityRevision: null,
        summary: `${revoked} customer order link${revoked === 1n ? "" : "s"} revoked`,
      }, now);
      return { applied: true, result: { revoked } };
    },
  );
  if (guarded.outcome !== "done") return { kind: "order.access_revoke", outcome: guarded.outcome };
  return guarded.mutation.applied
    ? { kind: "order.access_revoke", outcome: "applied", revoked: guarded.mutation.result.revoked }
    : { kind: "order.access_revoke", outcome: guarded.mutation.result };
}

function sameDigest(left: Uint8Array, right: Uint8Array): boolean {
  if (left.length !== right.length) return false;
  let difference = 0;
  for (let index = 0; index < left.length; index++) difference |= left[index]! ^ right[index]!;
  return difference === 0;
}

function* lookupOrder(command: Of<"order.lookup">): Program<ResultOf<"order.lookup">> {
  const now = BigInt(command.nowSeconds);
  const since = now - BigInt(LookupWindowSeconds);
  yield* run("DeleteStaleOrderLookups", [since]);
  const recent = yield* get("CountOrderLookups", [command.number, since]);
  if ((recent?.n ?? 0n) >= BigInt(LookupLimit)) return { kind: "order.lookup" };
  yield* run("InsertOrderLookup", [command.number, now]);
  const order = yield* get("GetOrderLookupTarget", [command.number]);
  if (order === null || order.email_digest === null) return { kind: "order.lookup" };
  if (sameDigest(order.email_digest, yield* searchDigestOf(command.email))) yield* queueEmail({ kind: "access_link", orderId: order.id, subjectId: 0n }, now);
  return { kind: "order.lookup" };
}

export function* emailCommandProgram(command: EmailCommand): Program<EmailCommandResult> {
  switch (command.kind) {
    case "email.begin": return yield* beginEmail(command);
    case "email.settle": return yield* settleEmail(command);
    case "email.resend": return yield* resendEmail(command);
    case "order.access_revoke": return yield* revokeAccess(command);
    case "order.lookup": return yield* lookupOrder(command);
  }
}

export function* emailQueryProgram(query: EmailQuery): Program<EmailQueryResult> {
  const grant = yield* get("GetOrderAccessGrant", [digestBytes(query.accessDigest), BigInt(query.nowSeconds)]);
  return { kind: "order.access", number: grant?.number ?? null };
}

export function* orderEmailViews(orderId: bigint): Program<readonly EmailMessageView[]> {
  const rows = yield* all("ListOrderEmails", [orderId]);
  return rows.map((row) => {
    if (!isEmailKind(row.kind) || !isEmailState(row.state)) throw new Error(`email: message ${row.id} has an unknown state or kind`);
    return {
      id: row.id, kind: row.kind, generation: row.generation, state: row.state, attempts: row.attempts, firstAttemptAt: row.first_attempt_at, lastError: row.last_error,
      createdAt: row.created_at,
    };
  });
}
