import { formatMoney } from "../catalog/money.ts";
import { unfulfilled } from "../commerce/fulfillment.ts";
import { lineFulfillmentOf } from "../commerce/fulfillment_program.ts";
import { adminPath } from "../routes/admin.ts";
import { fragments, html, type Html } from "./html.ts";
import type { OrderDetailView } from "./orders_operations.ts";
import { fieldError, type FieldErrors } from "./pages.ts";

export const OrderActions = ["refund", "cancel", "return", "restock"] as const;
export type OrderAction = (typeof OrderActions)[number];

export interface ActionInput {
  readonly quantities: ReadonlyMap<string, string>;
  readonly shipping: boolean;
  readonly reason: string;
}

export const BlankActionInput: ActionInput = { quantities: new Map(), shipping: false, reason: "" };

export interface ActionsState {
  readonly view: OrderDetailView;
  readonly tokens: Readonly<Record<OrderAction, string>>;
  readonly inputs: Readonly<Partial<Record<OrderAction, ActionInput>>>;
  readonly errors: FieldErrors;
  readonly needsReauth: boolean;
}

type Line = OrderDetailView["lines"][number];

const actionPath = (view: OrderDetailView, action: OrderAction): string =>
  adminPath(action === "refund" ? "admin-order-refund" : action === "cancel" ? "admin-order-cancel" : action === "return" ? "admin-order-return" : "admin-order-restock", [view.number.toString()]);

export const actionPurpose = (action: OrderAction, number: bigint): string => `order.${action}:${number}`;

function money(view: OrderDetailView, minor: bigint): string {
  return formatMoney(minor, view.currency, view.exponent);
}

function quantityFields(state: ActionsState, action: OrderAction, lines: readonly { readonly line: Line; readonly left: bigint; readonly noun: string }[]): Html {
  const input = state.inputs[action] ?? BlankActionInput;
  return html`<ul class="cards">${fragments(lines.map(({ line, left, noun }) => {
    const field = `qty_${line.position}`;
    const id = `${action}-${field}`;
    return html`<li><label for="${id}">${line.title}${line.variantLabel === "" ? "" : ` - ${line.variantLabel}`}: quantity to ${noun} (${left} left)</label>
<input id="${id}" class="quantity" name="${field}" inputmode="numeric" autocomplete="off" value="${input.quantities.get(field) ?? ""}" aria-describedby="${action}.${field}-error">${fieldError(state.errors, `${action}.${field}`)}</li>`;
  }))}</ul>`;
}

function form(state: ActionsState, action: OrderAction, legend: string, button: string, body: Html, hint: Html): Html {
  const input = state.inputs[action] ?? BlankActionInput;
  const id = `${action}-reason`;
  return html`<form method="post" action="${actionPath(state.view, action)}">
<input type="hidden" name="form_token" value="${state.tokens[action]}">
<input type="hidden" name="revision" value="${state.view.revision}">
<fieldset><legend>${legend}</legend>
${hint}
${fieldError(state.errors, `${action}.quantities`)}
${body}
<label for="${id}">Reason (kept in the order history)</label><input id="${id}" name="reason" maxlength="500" autocomplete="off" value="${input.reason}" aria-describedby="${action}.reason-error" required>${fieldError(state.errors, `${action}.reason`)}
<p><button type="submit">${button}</button></p>
</fieldset>
</form>`;
}

function refundForm(state: ActionsState): Html {
  const { view } = state;
  if (view.payment.state !== "captured") return html`<p role="status">Refunds start once the payment is captured. Cancel the order to release an uncaptured payment.</p>`;
  if (view.refundableMinor <= 0n) return html`<p role="status">The whole captured amount has been refunded or is being refunded.</p>`;
  const open = view.lines.map((line) => ({ line, left: line.quantity - line.refunded, noun: "refund" })).filter((entry) => entry.left > 0n);
  const shippingLeft = view.shippingRefundableMinor + view.shippingTaxRefundableMinor;
  const input = state.inputs.refund ?? BlankActionInput;
  const shipping = shippingLeft <= 0n
    ? html``
    : html`<p><label><input type="checkbox" name="shipping" value="1"${input.shipping ? html` checked` : html``}> Refund shipping (${money(view, shippingLeft)} including tax)</label></p>`;
  return form(state, "refund", "Refund", "Refund through Stripe",
    html`${quantityFields(state, "refund", open)}${shipping}`,
    html`<p>Up to ${money(view, view.refundableMinor)} can still be refunded. Each item refunds its price and its share of the tax; Stripe returns the money to the customer's card. A refund that Stripe rejects stays on this page and can be requested again.</p>${state.needsReauth ? reauthNote(view) : html``}`);
}

function reauthNote(view: OrderDetailView): Html {
  const target = `${adminPath("admin-reauth")}?return=${encodeURIComponent(adminPath("admin-order", [view.number.toString()]))}`;
  return html`<p role="status">Refunds, cancellations, and restocks need a recent sign-in. <a href="${target}">Sign in again</a> before submitting.</p>`;
}

function cancelForm(state: ActionsState): Html {
  const { view } = state;
  const open = view.lines.map((line) => ({ line, left: unfulfilled(lineFulfillmentOf(line)), noun: "cancel" })).filter((entry) => entry.left > 0n);
  if (open.length === 0) return html``;
  if (view.cancelBlock !== null) return html`<p role="status">This order cannot be canceled while Stripe is capturing its payment. Check back in a moment.</p>`;
  const captured = view.payment.state === "captured";
  return form(state, "cancel", "Cancel items", "Cancel items",
    quantityFields(state, "cancel", open),
    html`<p>${captured ? "Canceling frees the reserved stock and does not refund the customer. Refund the canceled items separately." : "This payment is not captured yet, so canceling releases the authorization at Stripe. Cancel every item to do that."}</p>`);
}

function returnForm(state: ActionsState): Html {
  const open = state.view.lines.map((line) => ({ line, left: line.shipped - line.returned, noun: "record as returned" })).filter((entry) => entry.left > 0n);
  if (open.length === 0) return html``;
  return form(state, "return", "Record a return", "Record return", quantityFields(state, "return", open), html`<p>Recording a return does not put anything back in stock and does not refund the customer.</p>`);
}

function restockForm(state: ActionsState): Html {
  const open = state.view.lines.map((line) => ({ line, left: line.returned - line.restocked, noun: "restock" })).filter((entry) => entry.left > 0n);
  if (open.length === 0) return html``;
  const tracked = open.filter((entry) => entry.line.tracked);
  if (tracked.length === 0) return html`<p role="status">The returned items are not stock-tracked, so there is nothing to put back.</p>`;
  return form(state, "restock", "Restock returned items", "Put back in stock", quantityFields(state, "restock", tracked), html`<p>Adds the returned items back to the quantity on hand. It does not refund the customer.</p>`);
}

export function actionsSection(state: ActionsState): Html {
  return html`<h2>Cancel, refund, and restock</h2>
${cancelForm(state)}
${refundForm(state)}
${returnForm(state)}
${restockForm(state)}`;
}
