import type { Html } from "./html.ts";

export function adminHeaders(contentType: string | null): Headers {
  const headers = new Headers({ "Cache-Control": "private, no-store", "X-Frame-Options": "DENY", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "same-origin" });
  if (contentType !== null) headers.set("Content-Type", contentType);
  return headers;
}

export function page(request: Request, status: number, body: Html, extra?: Headers): Response {
  const headers = adminHeaders("text/html; charset=utf-8");
  extra?.forEach((value, key) => headers.append(key, value));
  return new Response(request.method === "HEAD" ? null : body.text, { status, headers });
}

export function redirect(location: string, cookies: readonly string[] = []): Response {
  const headers = adminHeaders(null);
  headers.set("Location", location);
  for (const cookie of cookies) headers.append("Set-Cookie", cookie);
  return new Response(null, { status: 303, headers });
}

export function withCookies(cookies: readonly string[]): Headers {
  const headers = new Headers();
  for (const cookie of cookies) headers.append("Set-Cookie", cookie);
  return headers;
}

