import { escapeHtml } from "../email/content.ts";
import { routePath } from "../routes/routes.ts";

export type LookupState = "form" | "invalid" | "requested";

const messages: Readonly<Record<LookupState, string | null>> = {
  form: null,
  invalid: "Enter your order number, digits only, and the email address you used at checkout.",
  requested: "If those details match an order, we have emailed a new link to it. The email can take a few minutes to arrive.",
};

export function lookupPage(shopName: string, state: LookupState): Uint8Array {
  const message = messages[state];
  const title = escapeHtml(`Find your order - ${shopName}`);
  const notice = message === null ? "" : `<p role="${state === "invalid" ? "alert" : "status"}">${escapeHtml(message)}</p>`;
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, nofollow"><title>${title}</title></head><body><main><h1>Find your order</h1>` +
    `<p>Enter your order number and the email address you used at checkout, and we will email you a new link to your order.</p>${notice}` +
    `<form method="post" action="${escapeHtml(routePath("order-lookup-request"))}"><p><label for="order_number">Order number</label><br><input id="order_number" name="order_number" inputmode="numeric" autocomplete="off" required></p>` +
    `<p><label for="email">Email address</label><br><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required></p><p><button type="submit">Email me a link</button></p></form>` +
    `<p><a href="/">Back to the shop</a></p></main></body></html>`;
  return new TextEncoder().encode(html);
}
