import { Schema } from "effect";
import { DatabaseError, type SQLBoundValue, type SQLValue } from "../storefront/persistence.ts";
import { bindParam, inspectQuerySQL, Integer } from "../storefront/queries.ts";
import { checkoutRowSchemas, checkoutWriteQueries } from "../checkout/queries.ts";
import { catalogRowSchemas, catalogWriteQueries } from "./catalog_queries.ts";
import { mediaRowSchemas, mediaWriteQueries } from "./media_queries.ts";
import { workRowSchemas, workWriteQueries } from "../commerce/work_queries.ts";
import { settingsRowSchemas, settingsWriteQueries } from "./settings_queries.ts";
import { shopRowSchemas, shopWriteQueries } from "./pages_shop_queries.ts";
import { paymentRowSchemas, paymentWriteQueries } from "../commerce/payment_queries.ts";
import { orderRowSchemas, orderWriteQueries } from "./orders_queries.ts";
import { refundRowSchemas, refundWriteQueries } from "../commerce/refund_queries.ts";
import { emailRowSchemas, emailWriteQueries } from "../commerce/email_queries.ts";

const Text = Schema.String;
const NullableText = Schema.NullOr(Text);

const rowSchemas = {
  GetAdminSession: Schema.Struct({ issuer: Text, subject: Text, email: NullableText, created_at: Integer, authenticated_at: Integer, last_seen_at: Integer, expires_at: Integer }),
  GetFormToken: Schema.Struct({ purpose: Text, expires_at: Integer }),
  GetStockVariant: Schema.Struct({ variant_id: Integer, product_title: Text, variant_title: NullableText }),
  ListRecentStockAdjustments: Schema.Struct({ id: Integer, kind: Text, delta: Integer, on_hand_after: Integer, reason: Text, actor: Text, created_at: Integer }),
  ListRecentAuditEvents: Schema.Struct({ id: Integer, actor: Text, action: Text, entity_revision: Schema.NullOr(Integer), summary: Text, created_at: Integer }),
  ...catalogRowSchemas,
  ...checkoutRowSchemas,
  ...mediaRowSchemas,
  ...workRowSchemas,
  ...settingsRowSchemas,
  ...shopRowSchemas,
  ...paymentRowSchemas,
  ...orderRowSchemas,
  ...refundRowSchemas,
  ...emailRowSchemas,
} as const;
export type AdminRowQueryName = keyof typeof rowSchemas;
export type AdminQueryRow<N extends AdminRowQueryName> = typeof rowSchemas[N]["Type"];

const writeQueries = [
  "InsertAdminSession", "TouchAdminSession", "SetAdminSessionAuthentication", "DeleteAdminSession", "DeleteAdminSessionsByPrincipal",
  "DeleteAllAdminSessions", "DeleteExpiredAdminSessions", "InsertFormToken", "DeleteFormToken", "DeleteExpiredFormTokens", "TrimFormTokens",
  ...catalogWriteQueries,
  ...checkoutWriteQueries,
  ...mediaWriteQueries,
  ...workWriteQueries,
  ...settingsWriteQueries,
  ...shopWriteQueries,
  ...paymentWriteQueries,
  ...orderWriteQueries,
  ...refundWriteQueries,
  ...emailWriteQueries,
] as const;
export type AdminWriteQueryName = typeof writeQueries[number];
type AdminQueryName = AdminRowQueryName | AdminWriteQueryName;

export const AdminQueryFiles = ["admin.sql", "catalog_admin.sql", "checkout.sql", "media.sql", "settings.sql", "shop.sql", "work.sql", "payments.sql", "orders.sql", "refunds.sql", "email.sql"] as const;

export class AdminQueries {
  readonly #definitions: ReadonlyMap<AdminQueryName, { readonly sql: string; readonly parameters: number }>;
  constructor(definitions: ReadonlyMap<AdminQueryName, { readonly sql: string; readonly parameters: number }>) { this.#definitions = definitions; }

  prepare(name: AdminQueryName, params: readonly SQLValue[]): { readonly sql: string; readonly params: readonly SQLBoundValue[] } {
    const definition = this.#definitions.get(name);
    if (definition === undefined || definition.parameters !== params.length) {
      throw new DatabaseError(`admin queries: ${name} requires ${definition?.parameters ?? "unknown"} parameters, received ${params.length}`);
    }
    return { sql: definition.sql, params: params.map(bindParam) };
  }

  decodeRow<N extends AdminRowQueryName>(name: N, input: unknown): AdminQueryRow<N> {
    try {
      return Schema.decodeUnknownSync(rowSchemas[name], { onExcessProperty: "error" })(input) as AdminQueryRow<N>;
    } catch (cause) {
      throw new DatabaseError(`admin queries: invalid ${name} row`, cause);
    }
  }

  isRowQuery(name: AdminQueryName): name is AdminRowQueryName {
    return Object.hasOwn(rowSchemas, name);
  }
}

export function buildAdminQueries(sources: ReadonlyMap<string, string>): AdminQueries {
  const known = new Set<string>([...Object.keys(rowSchemas), ...writeQueries]);
  const definitions = new Map<AdminQueryName, { readonly sql: string; readonly parameters: number }>();
  for (const file of AdminQueryFiles) {
    const source = sources.get(file);
    if (source === undefined) throw new DatabaseError(`admin queries: missing ${file}`);
    const markers = [...source.matchAll(/^-- name: ([A-Za-z][A-Za-z0-9]*) :(one|many|exec|execrows)\s*$/gm)];
    for (const [index, marker] of markers.entries()) {
      const name = marker[1] ?? "";
      if (!known.has(name) || definitions.has(name as AdminQueryName)) throw new DatabaseError(`admin queries: unknown or duplicate ${name}`);
      const raw = source.slice((marker.index ?? 0) + marker[0].length, markers[index + 1]?.index ?? source.length).trim();
      definitions.set(name as AdminQueryName, { sql: raw, parameters: inspectQuerySQL(raw) });
    }
  }
  for (const name of known) if (!definitions.has(name as AdminQueryName)) throw new DatabaseError(`admin queries: missing ${name}`);
  return new AdminQueries(definitions);
}
