import type { ImageKind } from "./format.ts";

export const ImageProblems = [
  "empty",
  "unsupported_type",
  "malformed",
  "truncated",
  "unsupported_variant",
  "animated",
  "rotated",
  "trailing_data",
] as const;
export type ImageProblem = (typeof ImageProblems)[number];

export interface InspectedImage {
  readonly kind: ImageKind;
  readonly width: number;
  readonly height: number;
  readonly bytes: Uint8Array;
}

export type Inspection =
  | { readonly ok: true; readonly image: InspectedImage }
  | { readonly ok: false; readonly problem: ImageProblem; readonly message: string };

const messages: Readonly<Record<Exclude<ImageProblem, "rotated">, string>> = {
  empty: "Choose an image file.",
  unsupported_type: "Only JPEG, PNG, and WebP images are accepted. SVG, GIF, HEIC, and other formats are not.",
  malformed: "The file is not a well-formed image of its type. Export it again from your image editor.",
  truncated: "The file ends before the image does. Upload it again; it may have been cut off.",
  unsupported_variant: "This kind of JPEG, PNG, or WebP is not supported. Export it as a standard baseline or progressive JPEG, PNG, or WebP.",
  animated: "Animated images are not accepted. Export a single still frame.",
  trailing_data: "The file has extra data after the image. Export the image again so it contains only the picture.",
};

export function describeProblem(problem: ImageProblem, orientation?: number): string {
  if (problem === "rotated") {
    return `The photo is stored sideways or flipped (EXIF orientation ${String(orientation ?? 0)}) and the shop cannot apply that. Rotate it upright in an image editor and export it again.`;
  }
  return messages[problem];
}

class Refusal extends Error {
  readonly problem: ImageProblem;
  readonly orientation: number | undefined;
  constructor(problem: ImageProblem, orientation?: number) {
    super(problem);
    this.problem = problem;
    this.orientation = orientation;
  }
}

function refuse(problem: ImageProblem, orientation?: number): never {
  throw new Refusal(problem, orientation);
}

function startsWith(bytes: Uint8Array, offset: number, text: string): boolean {
  if (offset + text.length > bytes.length) return false;
  for (let index = 0; index < text.length; index++) {
    if (bytes[offset + index] !== text.charCodeAt(index)) return false;
  }
  return true;
}

function u16be(bytes: Uint8Array, offset: number): number {
  return (bytes[offset]! << 8) | bytes[offset + 1]!;
}

function u32be(bytes: Uint8Array, offset: number): number {
  return ((bytes[offset]! << 24) | (bytes[offset + 1]! << 16) | (bytes[offset + 2]! << 8) | bytes[offset + 3]!) >>> 0;
}

function u16le(bytes: Uint8Array, offset: number): number {
  return bytes[offset]! | (bytes[offset + 1]! << 8);
}

function u24le(bytes: Uint8Array, offset: number): number {
  return bytes[offset]! | (bytes[offset + 1]! << 8) | (bytes[offset + 2]! << 16);
}

function u32le(bytes: Uint8Array, offset: number): number {
  return (bytes[offset]! | (bytes[offset + 1]! << 8) | (bytes[offset + 2]! << 16) | (bytes[offset + 3]! << 24)) >>> 0;
}

function concat(parts: readonly Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((sum, part) => sum + part.length, 0));
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/** Reads IFD0 of a TIFF block for the orientation tag; a block it cannot read yields null. */
function tiffOrientation(bytes: Uint8Array, start: number, end: number): number | null {
  if (end - start < 8) return null;
  const little = bytes[start] === 0x49 && bytes[start + 1] === 0x49;
  const big = bytes[start] === 0x4d && bytes[start + 1] === 0x4d;
  if (!little && !big) return null;
  const read16 = (offset: number): number => (little ? u16le(bytes, offset) : u16be(bytes, offset));
  const read32 = (offset: number): number => (little ? u32le(bytes, offset) : u32be(bytes, offset));
  if (read16(start + 2) !== 42) return null;
  const ifd = start + read32(start + 4);
  if (ifd + 2 > end) return null;
  const count = read16(ifd);
  for (let index = 0; index < count; index++) {
    const entry = ifd + 2 + index * 12;
    if (entry + 12 > end) return null;
    if (read16(entry) === 0x0112 && read16(entry + 2) === 3 && read32(entry + 4) === 1) return read16(entry + 8);
  }
  return null;
}

function requireUpright(orientation: number | null): void {
  if (orientation !== null && orientation !== 1) refuse("rotated", orientation);
}

function inspectJpeg(bytes: Uint8Array): InspectedImage {
  if (bytes.length < 4 || bytes[0] !== 0xff || bytes[1] !== 0xd8) refuse("malformed");
  const kept: Uint8Array[] = [bytes.subarray(0, 2)];
  let position = 2;
  let frame: { readonly width: number; readonly height: number } | null = null;
  let scans = 0;
  for (;;) {
    if (position + 1 >= bytes.length) refuse("truncated");
    if (bytes[position] !== 0xff) refuse("malformed");
    while (bytes[position + 1] === 0xff) {
      position++;
      if (position + 1 >= bytes.length) refuse("truncated");
    }
    const marker = bytes[position + 1]!;
    const segmentStart = position;
    position += 2;
    if (marker === 0xd9) {
      if (frame === null || scans === 0) refuse("malformed");
      kept.push(bytes.subarray(segmentStart, position));
      if (position !== bytes.length) refuse("trailing_data");
      return { kind: "jpeg", width: frame.width, height: frame.height, bytes: concat(kept) };
    }
    if (marker === 0x00 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd8) || (marker >= 0xf0 && marker <= 0xfd)) refuse("malformed");
    if (position + 2 > bytes.length) refuse("truncated");
    const length = u16be(bytes, position);
    const dataStart = position + 2;
    const segmentEnd = position + length;
    if (length < 2) refuse("malformed");
    if (segmentEnd > bytes.length) refuse("truncated");
    const keepSegment = (): void => {
      kept.push(bytes.subarray(segmentStart, segmentEnd));
    };
    if (marker === 0xc0 || marker === 0xc1 || marker === 0xc2) {
      if (frame !== null || length < 8) refuse("malformed");
      const components = bytes[dataStart + 5]!;
      if (length !== 8 + 3 * components) refuse("malformed");
      if (bytes[dataStart] !== 8 || (components !== 1 && components !== 3)) refuse("unsupported_variant");
      const height = u16be(bytes, dataStart + 1);
      const width = u16be(bytes, dataStart + 3);
      if (width === 0 || height === 0) refuse("malformed");
      frame = { width, height };
      keepSegment();
    } else if (marker === 0xc3 || (marker >= 0xc5 && marker <= 0xc7) || (marker >= 0xc9 && marker <= 0xcb) || (marker >= 0xcd && marker <= 0xcf) || marker === 0xdc) {
      refuse("unsupported_variant");
    } else if (marker === 0xda) {
      if (frame === null) refuse("malformed");
      let scan = segmentEnd;
      for (;;) {
        if (scan + 1 >= bytes.length) refuse("truncated");
        if (bytes[scan] !== 0xff) {
          scan++;
          continue;
        }
        const next = bytes[scan + 1]!;
        if (next === 0x00 || (next >= 0xd0 && next <= 0xd7)) scan += 2;
        else if (next === 0xff) scan++;
        else break;
      }
      kept.push(bytes.subarray(segmentStart, scan));
      scans++;
      position = scan;
      continue;
    } else if (marker === 0xe1) {
      if (startsWith(bytes, dataStart, "Exif\0\0")) requireUpright(tiffOrientation(bytes, dataStart + 6, segmentEnd));
    } else if (marker === 0xe0 || marker === 0xc4 || marker === 0xdb || marker === 0xdd) {
      keepSegment();
    } else if (marker === 0xe2) {
      if (startsWith(bytes, dataStart, "ICC_PROFILE\0")) keepSegment();
    } else if (marker === 0xee) {
      if (startsWith(bytes, dataStart, "Adobe")) keepSegment();
    } else if (!(marker >= 0xe3 && marker <= 0xef) && marker !== 0xfe) {
      refuse("malformed");
    }
    position = segmentEnd;
  }
}

const crcTable = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(bytes: Uint8Array, start: number, end: number): number {
  let crc = 0xffffffff;
  for (let index = start; index < end; index++) crc = crcTable[(crc ^ bytes[index]!) & 0xff]! ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

const pngKeptAncillary = new Set(["tRNS", "gAMA", "cHRM", "sRGB", "iCCP", "sBIT"]);
const pngBitDepths: Readonly<Record<number, readonly number[]>> = { 0: [1, 2, 4, 8, 16], 2: [8, 16], 3: [1, 2, 4, 8], 4: [8, 16], 6: [8, 16] };

function inspectPng(bytes: Uint8Array): InspectedImage {
  if (bytes.length < 8 || !startsWith(bytes, 0, "\x89PNG\r\n\x1a\n")) refuse("malformed");
  const kept: Uint8Array[] = [bytes.subarray(0, 8)];
  let position = 8;
  let width = 0;
  let height = 0;
  let colorType = -1;
  let first = true;
  let idats = 0;
  let idatEnded = false;
  let palette = false;
  for (;;) {
    if (position + 12 > bytes.length) refuse("truncated");
    const length = u32be(bytes, position);
    if (length > 0x7fffffff) refuse("malformed");
    const end = position + 12 + length;
    if (end > bytes.length) refuse("truncated");
    const typeStart = position + 4;
    const type = String.fromCharCode(bytes[typeStart]!, bytes[typeStart + 1]!, bytes[typeStart + 2]!, bytes[typeStart + 3]!);
    if (!/^[A-Za-z]{4}$/.test(type)) refuse("malformed");
    if (crc32(bytes, typeStart, end - 4) !== u32be(bytes, end - 4)) refuse("malformed");
    const dataStart = position + 8;
    if (first && type !== "IHDR") refuse("malformed");
    if (type === "IHDR") {
      if (!first || length !== 13) refuse("malformed");
      first = false;
      width = u32be(bytes, dataStart);
      height = u32be(bytes, dataStart + 4);
      const depth = bytes[dataStart + 8]!;
      colorType = bytes[dataStart + 9]!;
      if (width === 0 || height === 0 || width > 0x7fffffff || height > 0x7fffffff) refuse("malformed");
      if (!(pngBitDepths[colorType] ?? []).includes(depth)) refuse("malformed");
      if (bytes[dataStart + 10] !== 0 || bytes[dataStart + 11] !== 0 || bytes[dataStart + 12]! > 1) refuse("malformed");
      kept.push(bytes.subarray(position, end));
    } else if (type === "IDAT") {
      if (idatEnded || (colorType === 3 && !palette)) refuse("malformed");
      idats++;
      kept.push(bytes.subarray(position, end));
    } else {
      if (idats > 0) idatEnded = true;
      if (type === "IEND") {
        if (length !== 0 || idats === 0) refuse("malformed");
        kept.push(bytes.subarray(position, end));
        if (end !== bytes.length) refuse("trailing_data");
        return { kind: "png", width, height, bytes: concat(kept) };
      }
      if (type === "PLTE") {
        if (palette || idats > 0 || colorType === 0 || colorType === 4 || length === 0 || length % 3 !== 0 || length > 768) refuse("malformed");
        palette = true;
        kept.push(bytes.subarray(position, end));
      } else if (type === "eXIf") {
        requireUpright(tiffOrientation(bytes, dataStart, end - 4));
      } else if (pngKeptAncillary.has(type)) {
        if (idats > 0) refuse("malformed");
        kept.push(bytes.subarray(position, end));
      } else if (type.charCodeAt(0) < 0x61) {
        refuse("unsupported_variant");
      }
    }
    position = end;
  }
}

interface WebpChunk {
  readonly type: string;
  readonly start: number;
  readonly dataStart: number;
  readonly size: number;
  readonly end: number;
}

function webpFrame(bytes: Uint8Array, chunk: WebpChunk): { readonly width: number; readonly height: number } {
  const data = chunk.dataStart;
  if (chunk.type === "VP8 ") {
    if (chunk.size < 10 || (bytes[data]! & 1) !== 0 || bytes[data + 3] !== 0x9d || bytes[data + 4] !== 0x01 || bytes[data + 5] !== 0x2a) refuse("malformed");
    return { width: u16le(bytes, data + 6) & 0x3fff, height: u16le(bytes, data + 8) & 0x3fff };
  }
  if (chunk.size < 5 || bytes[data] !== 0x2f) refuse("malformed");
  const bits = u32le(bytes, data + 1);
  if (bits >>> 29 !== 0) refuse("unsupported_variant");
  return { width: (bits & 0x3fff) + 1, height: ((bits >>> 14) & 0x3fff) + 1 };
}

function inspectWebp(bytes: Uint8Array): InspectedImage {
  if (bytes.length < 20 || !startsWith(bytes, 0, "RIFF") || !startsWith(bytes, 8, "WEBP")) refuse("malformed");
  const declared = u32le(bytes, 4) + 8;
  if (declared > bytes.length) refuse("truncated");
  if (declared < bytes.length) refuse("trailing_data");
  const chunks: WebpChunk[] = [];
  let position = 12;
  while (position < bytes.length) {
    if (position + 8 > bytes.length) refuse("truncated");
    const size = u32le(bytes, position + 4);
    const end = position + 8 + size + (size & 1);
    if (end > bytes.length) refuse("truncated");
    const type = String.fromCharCode(bytes[position]!, bytes[position + 1]!, bytes[position + 2]!, bytes[position + 3]!);
    chunks.push({ type, start: position, dataStart: position + 8, size, end });
    position = end;
  }
  const head = chunks[0];
  if (head === undefined || (head.type !== "VP8X" && head.type !== "VP8 " && head.type !== "VP8L")) refuse("malformed");
  const kept: Uint8Array[] = [];
  let canvas: { readonly width: number; readonly height: number } | null = null;
  let image: WebpChunk | null = null;
  for (const chunk of chunks) {
    if (chunk.type === "VP8X") {
      if (chunk !== head || chunk.size < 10) refuse("malformed");
      if ((bytes[chunk.dataStart]! & 0x02) !== 0) refuse("animated");
      canvas = { width: u24le(bytes, chunk.dataStart + 4) + 1, height: u24le(bytes, chunk.dataStart + 7) + 1 };
      const rewritten = bytes.slice(chunk.start, chunk.end);
      rewritten[8] = rewritten[8]! & ~0x0c;
      kept.push(rewritten);
    } else if (chunk.type === "VP8 " || chunk.type === "VP8L") {
      if (image !== null) refuse("malformed");
      image = chunk;
      kept.push(bytes.subarray(chunk.start, chunk.end));
    } else if (chunk.type === "ANIM" || chunk.type === "ANMF") {
      refuse("animated");
    } else if (chunk.type === "ICCP" || chunk.type === "ALPH") {
      kept.push(bytes.subarray(chunk.start, chunk.end));
    } else if (chunk.type === "EXIF") {
      const prefixed = startsWith(bytes, chunk.dataStart, "Exif\0\0") ? 6 : 0;
      requireUpright(tiffOrientation(bytes, chunk.dataStart + prefixed, chunk.dataStart + chunk.size));
    }
  }
  if (image === null) refuse("malformed");
  const frame = webpFrame(bytes, image);
  if (frame.width === 0 || frame.height === 0) refuse("malformed");
  if (canvas !== null && (canvas.width !== frame.width || canvas.height !== frame.height)) refuse("malformed");
  const body = concat(kept);
  const out = new Uint8Array(12 + body.length);
  out.set(bytes.subarray(0, 12));
  out.set(body, 12);
  new DataView(out.buffer).setUint32(4, out.length - 8, true);
  return { kind: "webp", width: frame.width, height: frame.height, bytes: out };
}

/**
 * Checks the magic bytes and walks the container structure of a JPEG, PNG, or
 * WebP file without decoding any pixels, reads the dimensions from the header,
 * and returns the same image with EXIF, XMP, text, and other metadata
 * segments removed. The input is never modified.
 */
export function inspectImage(input: Uint8Array): Inspection {
  if (input.length === 0) return { ok: false, problem: "empty", message: describeProblem("empty") };
  try {
    if (input[0] === 0xff && input[1] === 0xd8) return { ok: true, image: inspectJpeg(input) };
    if (startsWith(input, 0, "\x89PNG\r\n\x1a\n")) return { ok: true, image: inspectPng(input) };
    if (startsWith(input, 0, "RIFF") && startsWith(input, 8, "WEBP")) return { ok: true, image: inspectWebp(input) };
    return { ok: false, problem: "unsupported_type", message: describeProblem("unsupported_type") };
  } catch (error) {
    if (error instanceof Refusal) return { ok: false, problem: error.problem, message: describeProblem(error.problem, error.orientation) };
    throw error;
  }
}
