export class SecurityError extends Error {
  readonly status: 400 | 403 | 421;
  constructor(status: 400 | 403 | 421, message: string) { super(message); this.name = "SecurityError"; this.status = status; }
}

export function normalizeHost(authority: string): string {
  if (authority === "" || authority.length > 260) throw new SecurityError(400, "Malformed Host");
  const colon = authority.lastIndexOf(":");
  const name = (colon < 0 ? authority : authority.slice(0, colon)).toLowerCase();
  const port = colon < 0 ? "" : authority.slice(colon + 1);
  if (colon >= 0 && (!/^[1-9][0-9]*$/.test(port) || Number(port) > 65535)) throw new SecurityError(400, "Malformed Host");
  if (name.length > 253 || !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$/.test(name) || isIPv4(name)) {
    throw new SecurityError(400, "Malformed Host");
  }
  return name + (port === "" ? "" : `:${port}`);
}
function isIPv4(name: string): boolean {
  const parts = name.split(".");
  return parts.length === 4 && parts.every((part) => /^(?:0|[1-9][0-9]{0,2})$/.test(part) && Number(part) <= 255);
}

export function exactTenant<T>(host: string, tenants: ReadonlyMap<string, T>): T {
  const normalized = normalizeHost(host);
  const tenant = tenants.get(normalized);
  if (tenant === undefined) throw new SecurityError(421, "Unknown host");
  return tenant;
}

export function checkOrigin(headers: Headers, configuredOrigin: string): void {
  const origin = headers.get("origin");
  const site = headers.get("sec-fetch-site");
  if ((origin === null && site === null) || (origin !== null && (origin.includes(",") || origin !== configuredOrigin)) || (site !== null && (site.includes(",") || site !== "same-origin"))) {
    throw new SecurityError(403, "Cross-origin or unverifiable submission");
  }
}

export function baseHeaders(): Headers {
  return new Headers({ "X-Content-Type-Options": "nosniff", "Referrer-Policy": "strict-origin-when-cross-origin", "X-Frame-Options": "DENY", "Cross-Origin-Opener-Policy": "same-origin" });
}
export function securityHeaders(origin: string, imageHosts: readonly string[] = [], formActionOrigin: string | null = null): Headers {
  const headers = baseHeaders();
  const images = ["'self'", ...imageHosts.map((host) => `https://${normalizeHost(host)}`)].join(" ");
  const formAction = formActionOrigin === null ? "'self'" : `'self' ${new URL(formActionOrigin).origin}`;
  headers.set("Content-Security-Policy", `default-src 'self'; img-src ${images}; script-src 'self'; style-src 'self'; object-src 'none'; base-uri 'none'; form-action ${formAction}; frame-ancestors 'none'`);
  if (origin.startsWith("https://")) headers.set("Strict-Transport-Security", "max-age=31536000");
  return headers;
}
