export interface Position { readonly file: string; readonly line: number; readonly column: number }

export class Diagnostic extends Error {
  readonly position: Position;
  readonly detail: string;
  constructor(position: Position, detail: string) {
    super(`${position.file}:${position.line}:${position.column}: ${detail}`);
    this.name = "Diagnostic";
    this.position = position;
    this.detail = detail;
  }
}

export type Expression =
  | { readonly kind: "literal"; readonly position: Position; readonly value: string | number | boolean | null }
  | { readonly kind: "path"; readonly position: Position; readonly parts: readonly string[] }
  | { readonly kind: "call"; readonly position: Position; readonly name: string; readonly args: readonly Expression[] }
  | { readonly kind: "not"; readonly position: Position; readonly value: Expression }
  | { readonly kind: "binary"; readonly position: Position; readonly operator: "&&" | "||" | "==" | "!="; readonly left: Expression; readonly right: Expression };

export type Part = { readonly kind: "literal"; readonly value: string } | { readonly kind: "expression"; readonly expression: Expression };
export interface Attribute {
  readonly position: Position;
  readonly name: string;
  readonly hasValue: boolean;
  readonly bare: boolean;
  readonly parts: readonly Part[];
}
export interface Element {
  readonly kind: "element";
  readonly position: Position;
  readonly tag: string;
  readonly attributes: readonly Attribute[];
  readonly children: readonly Node[];
  readonly selfClosing: boolean;
}
export type Node = Element
  | { readonly kind: "text"; readonly position: Position; readonly parts: readonly Part[] }
  | { readonly kind: "comment"; readonly position: Position; readonly text: string }
  | { readonly kind: "doctype"; readonly position: Position };

export function literalAttribute(attribute: Attribute): string | undefined {
  if (attribute.bare || !attribute.hasValue || attribute.parts.some((part) => part.kind === "expression")) return undefined;
  return attribute.parts.map((part) => part.kind === "literal" ? part.value : "").join("");
}
export function isBlank(node: Node): boolean {
  return node.kind === "text" && node.parts.every((part) => part.kind === "literal" && part.value.trim() === "");
}
export function hasContent(nodes: readonly Node[]): boolean { return nodes.some((node) => node.kind !== "comment" && !isBlank(node)); }
