export const IsolatePageCacheBudgetBytes = 8 << 20;

export interface CloudflareWorkerEnv {
  readonly TENANT_STORE: {
    idFromName(name: string): unknown;
    get(id: unknown): TenantStoreRpcStub & CommerceRpcStub;
  };
  readonly ASSETS?: {
    fetch(request: Request): Promise<Response>;
  };
  readonly MEDIA: R2BucketLike;
}

export type CloudflareWorkerRuntimeEnv = CloudflareWorkerEnv & StripeSecretsEnv;

class EmbeddedTenantRevision implements TenantRevision {
  readonly id: string;
  readonly #pages: ReadonlyMap<string, Program>;

  constructor(id: string, pages: Readonly<Record<string, Program>>) {
    this.id = id;
    const map = new Map<string, Program>();
    for (const [entry, program] of Object.entries(pages)) {
      map.set(entry, freezeView(structuredClone(program)));
    }
    this.#pages = map;
    Object.freeze(this);
  }

  page(entry: string): Program | undefined {
    return this.#pages.get(entry);
  }

  asset(_path: string): TenantAsset | undefined {
    return undefined;
  }
}

export function renderAssetHeadersFile(
  origin: { readonly scheme: "http" | "https"; readonly host: string },
  imageHosts: readonly string[],
): string {
  const normalizedOrigin = `${origin.scheme}://${normalizeHost(origin.host)}`;
  const sec = securityHeaders(normalizedOrigin, imageHosts);
  const sharedLines: string[] = [];
  sec.forEach((value, key) => {
    sharedLines.push(`  ${key}: ${value}`);
  });
  const staticBlock = [
    "/static/*",
    "  Cache-Control: public, max-age=31536000, immutable",
    ...sharedLines,
  ].join("\n");
  const mediaBlock = [
    "/assets/*",
    "  Cache-Control: public, max-age=300",
    ...sharedLines,
  ].join("\n");
  return `${staticBlock}\n\n${mediaBlock}\n`;
}

export interface AdminMountAccess {
  readonly env: () => CloudflareWorkerEnv;
  readonly manifest: EmbeddedTenantManifest;
}
export type AdminMountFactory = (access: AdminMountAccess) => AdminMount;

export interface CloudflareTenantWorker {
  readonly manifest: EmbeddedTenantManifest;
  readonly pageCache: PageCache;
  readonly store: CloudflareTenantStore;
  readonly application: TenantApplication;
  fetch(request: Request, env: CloudflareWorkerRuntimeEnv, ctx?: unknown): Promise<Response>;
  scheduled(controller: unknown, env: CloudflareWorkerRuntimeEnv, ctx?: unknown): Promise<void>;
}

export function createCloudflareWorker(manifest: EmbeddedTenantManifest, observer: InvocationObserver, hook?: OperationHook, adminMount?: AdminMountFactory): CloudflareTenantWorker {
  const operation = hook === undefined ? undefined : isolateOperationHook(hook, (error) => console.error(`cloudflare worker [${manifest.id}]: operation hook failed`, error));
  let activeEnv: CloudflareWorkerRuntimeEnv | null = null;
  const { queries } = getEmbeddedPersistenceBundle();
  const pageCache = new PageCache(IsolatePageCacheBudgetBytes);
  const store = new CloudflareTenantStore(() => {
    if (activeEnv === null) {
      throw new Error("cloudflare: worker environment is not active");
    }
    const id = activeEnv.TENANT_STORE.idFromName(manifest.id);
    return activeEnv.TENANT_STORE.get(id);
  }, queries, { catalogFreshnessMs: CatalogFreshnessMs, reportCaught: observer.reportCaught, ...(operation === undefined ? {} : { operation }) });
  const media: BlobReader = {
    get(key) {
      if (activeEnv === null) throw new Error("cloudflare: worker environment is not active");
      return r2BlobStore(activeEnv.MEDIA).get(key);
    },
  };
  const revision = new EmbeddedTenantRevision(manifest.revision.id, manifest.revision.pages);
  const admin = adminMount?.({
    manifest,
    env: () => {
      if (activeEnv === null) throw new Error("cloudflare: worker environment is not active");
      return activeEnv;
    },
  });
  const tenantStub = (): CommerceRpcStub => {
    if (activeEnv === null) throw new Error("cloudflare: worker environment is not active");
    return activeEnv.TENANT_STORE.get(activeEnv.TENANT_STORE.idFromName(manifest.id));
  };
  const payments = cloudflarePayments({ tenantId: manifest.id, origin: `${manifest.origin.scheme}://${manifest.origin.host}` }, () => activeEnv?.STRIPE_SECRET_KEY);
  const paymentsMode = getEmbeddedPayments();
  const observedBackend = (backend: AdminBackend): AdminBackend => operation === undefined ? backend : observeCommerceBackend(backend, operation);
  const webhook = paymentsMode === null ? undefined : createWebhookMount({
    backend: observedBackend(cloudflareAdminBackend(tenantStub)),
    secrets: async () => {
      if (activeEnv === null) throw new Error("cloudflare: worker environment is not active");
      const current = activeEnv.STRIPE_WEBHOOK_SECRET;
      if (current === undefined || current === "") return null;
      const previous = activeEnv.STRIPE_WEBHOOK_SECRET_PREVIOUS;
      return { current, previous: previous === undefined || previous === "" ? null : previous };
    },
    expectLivemode: paymentsMode.mode === "live",
    now: () => new Date(),
    onError: (message, error) => {
      console.error(`cloudflare worker [${manifest.id}]: ${message}`, error);
    },
    ...(operation === undefined ? {} : { operation }),
  });
  const application = new TenantApplication({
    id: manifest.id,
    checkout: {
      backend: observedBackend(cloudflareAdminBackend(tenantStub)),
      tenantId: manifest.id,
      sessions: payments.sessions,
      checkoutOrigin: payments.checkoutOrigin,
      now: () => new Date(),
      onError: (message, error) => {
        console.error(`cloudflare worker [${manifest.id}]: ${message}`, error);
      },
    },
    origin: manifest.origin,
    imageHosts: manifest.imageHosts,
    store,
    revision,
    render: renderPage,
    media,
    ...(webhook === undefined ? {} : { webhook }),
    pages: pageCache.tenantView(manifest.id),
    requestTimeoutMs: 20_000,
    ...(admin === undefined ? {} : { admin }),
    ...(operation === undefined ? {} : { operation }),
    logger: {
      info: () => {},
      error: (msg, fields) => {
        console.error(`cloudflare worker [${manifest.id}]: ${msg}`, fields);
        if (msg === "request failed" && typeof fields["path"] === "string") {
          observer.reportCaught(requestOperation(fields["path"]), fields["error"]);
        }
      },
    },
  });
  const expectedHost = normalizeHost(manifest.origin.host);

  return {
    manifest,
    pageCache,
    store,
    application,
    async scheduled(_controller: unknown, env: CloudflareWorkerRuntimeEnv): Promise<void> {
      observer.markInvocation();
      activeEnv = env;
      await cloudflareAdminBackend(tenantStub).query({ kind: "work.next" });
    },
    async fetch(request: Request, env: CloudflareWorkerRuntimeEnv): Promise<Response> {
      observer.markInvocation();
      activeEnv = env;
      try {
        if (normalizeHost(request.headers.get("host") ?? "") !== expectedHost) {
          const headers = baseHeaders();
          headers.set("Cache-Control", "private, no-store");
          headers.set("Content-Type", "text/plain;charset=UTF-8");
          return new Response(request.method === "HEAD" ? null : "Misdirected Request\n", {
            status: 421,
            headers,
          });
        }
      } catch {
        const headers = baseHeaders();
        headers.set("Cache-Control", "private, no-store");
        headers.set("Content-Type", "text/plain;charset=UTF-8");
        return new Response(request.method === "HEAD" ? null : "Bad Request\n", {
          status: 400,
          headers,
        });
      }
      const pathname = new URL(request.url).pathname;
      if ((pathname.startsWith("/static/") || pathname.startsWith("/assets/")) && env.ASSETS !== undefined) {
        return await env.ASSETS.fetch(request);
      }
      return await application.respond(request);
    },
  };
}
