import { Schema } from "effect";
import { CatalogSchema, type Catalog } from "./schema.ts";
import { lookupCurrency } from "./money.ts";
import {
  MaxProducts, MaxCollections, MaxMembersPerCollect, MaxOptionsPerProduct,
  MaxValuesPerOption, MaxVariantsPerProduct, MaxImagesPerProduct, MaxDetailsPerProduct,
  MaxDimension, MaxLabelBytes, MaxProseBytes, MaxURLBytes,
} from "./scalars.ts";

const encoder = new TextEncoder();
function bounded(what: string, value: string, limit: number): void {
  const length = encoder.encode(value).length;
  if (length > limit) throw new Error(`catalog: ${what} is ${length} bytes, limit ${limit}`);
}
function count(what: string, actual: number, limit: number): void {
  if (actual > limit) throw new Error(`catalog: ${what} has ${actual} entries, limit ${limit}`);
}
function unique(seen: Set<string>, key: string, what: string): void {
  if (seen.has(key)) throw new Error(`catalog: duplicate ${what} ${JSON.stringify(key)}`);
  seen.add(key);
}
function handle(value: string): void {
  if (!/^[a-z0-9](?:[a-z0-9-]{0,198}[a-z0-9])?$/.test(value)) throw new Error(`catalog: invalid handle ${JSON.stringify(value)}`);
}

/** Validates complete real variant tuples; sparse option combinations remain valid. */
export function validateCatalog(catalog: Catalog, imageHosts: readonly string[] = []): void {
  Schema.decodeUnknownSync(CatalogSchema, { onExcessProperty: "error" })(catalog);
  bounded("store name", catalog.store.name, MaxLabelBytes);
  lookupCurrency(catalog.store.currencyCode, catalog.store.currencyExponent);
  count("products", catalog.products.length, MaxProducts);
  count("collections", catalog.collections.length, MaxCollections);
  const productIDs = new Set<string>();
  const productHandles = new Set<string>();
  const optionIDs = new Set<string>();
  const valueIDs = new Set<string>();
  const variantIDs = new Set<string>();
  const imageIDs = new Set<string>();
  for (const product of catalog.products) {
    const where = `product ${JSON.stringify(product.handle)}`;
    unique(productIDs, product.id, "product id");
    unique(productHandles, product.handle, "product handle");
    handle(product.handle);
    bounded(`${where} title`, product.title, MaxLabelBytes);
    bounded(`${where} vendor`, product.vendor ?? "", MaxLabelBytes);
    bounded(`${where} description`, product.description, MaxProseBytes);
    count(`${where} options`, product.options.length, MaxOptionsPerProduct);
    count(`${where} variants`, product.variants.length, MaxVariantsPerProduct);
    count(`${where} images`, product.images.length, MaxImagesPerProduct);
    count(`${where} details`, product.details.length, MaxDetailsPerProduct);
    if (product.variants.length === 0) throw new Error(`catalog: ${where} has no variants`);
    if (product.options.length === 0 && product.variants.length !== 1) throw new Error(`catalog: ${where} must have exactly one default variant`);
    const detailKeys = new Set<string>();
    for (const detail of product.details) {
      unique(detailKeys, detail.key, "detail key");
      bounded(`${where} detail key`, detail.key, MaxLabelBytes);
      bounded(`${where} detail title`, detail.title, MaxLabelBytes);
      bounded(`${where} detail ${JSON.stringify(detail.key)} body`, detail.body, MaxProseBytes);
    }
    const names = new Set<string>();
    const options = new Set<string>();
    const owners = new Map<string, string>();
    for (const option of product.options) {
      unique(optionIDs, option.id, "option id");
      unique(names, option.name, "option name");
      options.add(option.id);
      bounded(`${where} option name`, option.name, MaxLabelBytes);
      if (option.values.length === 0) throw new Error(`catalog: ${where} option ${JSON.stringify(option.name)} has no values`);
      count(`${where} option values`, option.values.length, MaxValuesPerOption);
      const values = new Set<string>();
      for (const value of option.values) {
        unique(valueIDs, value.id, "option value id");
        unique(values, value.value, "option value");
        bounded(`${where} option ${JSON.stringify(option.name)} value`, value.value, MaxLabelBytes);
        owners.set(value.id, option.id);
      }
    }
    const tuples = new Set<string>();
    for (const variant of product.variants) {
      unique(variantIDs, variant.id, "variant id");
      bounded(`${where} variant title`, variant.title ?? "", MaxLabelBytes);
      if (variant.selections.length !== product.options.length) throw new Error(`catalog: ${where} variant ${variant.id} must select exactly one value for EVERY option`);
      const selected = new Set<string>();
      for (const selection of variant.selections) {
        if (!options.has(selection.optionId)) throw new Error(`catalog: ${where} variant ${variant.id} selects foreign option ${selection.optionId}`);
        unique(selected, selection.optionId, "selected option");
        if (owners.get(selection.valueId) !== selection.optionId) throw new Error(`catalog: ${where} value ${selection.valueId} does not belong to option ${selection.optionId}`);
      }
      const tuple = variant.selections.map((selection) => `${selection.optionId}:${selection.valueId}`).sort().join("\x00");
      if (tuples.has(tuple)) throw new Error(`catalog: ${where} variant ${variant.id} duplicates the selection tuple`);
      tuples.add(tuple);
    }
    for (const image of product.images) {
      unique(imageIDs, image.id, "image id");
      if ((image.width === null) !== (image.height === null)) throw new Error(`catalog: ${where} image ${image.id} has half-specified dimensions`);
      if (image.width !== null && image.height !== null) {
        if (image.width <= 0 || image.height <= 0) throw new Error(`catalog: ${where} image ${image.id} has non-positive dimensions`);
        if (image.width > MaxDimension || image.height > MaxDimension) throw new Error(`catalog: ${where} image ${image.id} exceeds dimension limit`);
      }
      bounded(`${where} image ${JSON.stringify(image.id)} URL`, image.url, MaxURLBytes);
      bounded(`${where} image alt text`, image.altText, MaxLabelBytes);
      validateImageURL(image.url, imageHosts);
    }
  }
  const collectionIDs = new Set<string>();
  const collectionHandles = new Set<string>();
  for (const collection of catalog.collections) {
    unique(collectionIDs, collection.id, "collection id");
    unique(collectionHandles, collection.handle, "collection handle");
    handle(collection.handle);
    bounded(`collection ${JSON.stringify(collection.handle)} title`, collection.title, MaxLabelBytes);
    bounded(`collection ${JSON.stringify(collection.handle)} description`, collection.description, MaxProseBytes);
    count("collection members", collection.products.length, MaxMembersPerCollect);
    const members = new Set<string>();
    for (const member of collection.products) {
      unique(members, member, "collection member");
      if (!productIDs.has(member)) throw new Error(`catalog: collection ${collection.handle} lists unknown product ${member}`);
    }
  }
}

function checkURLPath(path: string): void {
  if (!path.startsWith("/")) throw new Error("image path must be absolute");
  if (/%(?:2e|2f|5c|00)/i.test(path)) throw new Error("image path must not contain encoded traversal");
  if (path.includes("\\")) throw new Error("image path must not contain backslashes");
  if (path.includes("//") || (path !== "/" && path.endsWith("/")) || path.split("/").some((part) => part === "." || part === "..")) throw new Error("image path is not clean");
}

/** Checks raw paths before URL parsing can normalize traversal or default ports. */
export function validateImageURL(raw: string, hosts: readonly string[] = []): void {
  if (raw === "" || /[\u0000-\u0020\u007f]/.test(raw)) throw new Error("image URL is empty or contains whitespace/control characters");
  if (raw.startsWith("/")) { checkURLPath(raw); return; }
  const parts = /^https:\/\/([^/?#]+)([^?#]*)(?:[?#].*)?$/.exec(raw);
  if (parts === null) throw new Error("image URL must use https or be a tenant-local path");
  const authority = parts[1] ?? "";
  if (authority.includes("@")) throw new Error("image URL must not carry userinfo");
  // Configured hosts are bare DNS names; ports and alternate URL host syntax are rejected.
  if (authority.includes(":") || authority.includes("\\")) throw new Error("image URL must be a bare host without port");
  let parsed: URL;
  try { parsed = new URL(raw); } catch { throw new Error("image URL does not parse"); }
  if (parsed.hostname !== authority.toLowerCase()) throw new Error("image URL host must be a bare configured hostname");
  if (!hosts.some((host) => host.toLowerCase() === authority.toLowerCase())) throw new Error(`image URL host ${JSON.stringify(authority)} is not configured for this tenant`);
  checkURLPath(parts[2] ?? "");
}
