import { Diagnostic, type Position } from "./ast.ts";
import type { ContractType } from "./contract.ts";
import { CSSContext, escapeCSS, filterCSS } from "./css.ts";
import { attributeContext, htmlElements, textContext, voidElements } from "./html.ts";
import { maxExpandedNodes, maxFeaturedLimit, maxInvokeDepth, maxRenderSteps, programVersion, type Program, type RenderAttribute, type RenderExpression, type RenderNode, type RenderPart } from "./program.ts";

export const maxRenderBytes = 4 << 20;
const encoder = new TextEncoder();
const rejectedURL = "#ZgotmplZ";
const htmlSpace = /[\t\n\f\r ]/;

export class RenderLimitError extends Error {
  readonly limit: "output" | "steps" | "invocation" | "data";
  constructor(limit: "output" | "steps" | "invocation" | "data") {
    super(`theme: render ${limit} limit exceeded`);
    this.name = "RenderLimitError";
    this.limit = limit;
  }
}

// Every append is bounded before its bytes are retained. UTF-8 chunks are
// small even when a single input string is much larger than the output cap.
export class BoundedByteWriter {
  private readonly chunks: Uint8Array[] = [];
  private size = 0;
  readonly maximum: number;
  readonly signal: AbortSignal | undefined;
  constructor(maximum = maxRenderBytes, signal?: AbortSignal) {
    if (!Number.isSafeInteger(maximum) || maximum < 0 || maximum > maxRenderBytes) throw new Error(`theme: output limit must be 0..${maxRenderBytes}`);
    this.maximum = maximum;
    this.signal = signal;
  }
  get length(): number { return this.size; }
  get remaining(): number { return this.maximum - this.size; }
  checkCancellation(): void {
    if (this.signal?.aborted) throw this.signal.reason ?? new DOMException("render canceled", "AbortError");
  }
  write(text: string): void {
    this.checkCancellation();
    if (text.length > this.remaining) throw new RenderLimitError("output");
    for (let start = 0; start < text.length;) {
      this.checkCancellation();
      let end = Math.min(start + 4096, text.length);
      const last = text.charCodeAt(end - 1);
      if (end < text.length && last >= 0xd800 && last <= 0xdbff) end--;
      const bytes = encoder.encode(text.slice(start, end));
      if (bytes.length > this.remaining) throw new RenderLimitError("output");
      this.chunks.push(bytes);
      this.size += bytes.length;
      start = end;
    }
  }
  bytes(): Uint8Array {
    this.checkCancellation();
    const result = new Uint8Array(this.size);
    let offset = 0;
    for (const chunk of this.chunks) { result.set(chunk, offset); offset += chunk.length; }
    return result;
  }
}

export interface RenderOptions {
  readonly routes: { path(name: string, parameters: readonly string[]): string };
  readonly featured: readonly unknown[];
  // The platform encoder owns the registered browser wire shape. The
  // interpreter checks that shape first and applies HTML attribute escaping.
  readonly encodeJSON: (type: ContractType, value: unknown) => string;
  readonly signal?: AbortSignal;
  readonly maxOutputBytes?: number;
  readonly maxSteps?: number;
}

function escapeHTML(writer: BoundedByteWriter, value: string, escapePlus = true): void {
  writer.checkCancellation();
  if (value.length > writer.remaining) throw new RenderLimitError("output");
  let start = 0;
  for (let index = 0; index < value.length; index++) {
    let replacement: string | undefined;
    switch (value[index]) {
      case "\0": replacement = "\uFFFD"; break;
      case '"': replacement = "&#34;"; break;
      case "'": replacement = "&#39;"; break;
      case "&": replacement = "&amp;"; break;
      case "+": if (escapePlus) replacement = "&#43;"; break;
      case "<": replacement = "&lt;"; break;
      case ">": replacement = "&gt;"; break;
    }
    if (replacement !== undefined) {
      writer.write(value.slice(start, index));
      writer.write(replacement);
      start = index + 1;
    }
    if (index % 4096 === 0) writer.checkCancellation();
  }
  writer.write(value.slice(start));
}

function safeURL(value: string): boolean {
  const colon = value.indexOf(":");
  if (colon < 0 || value.slice(0, colon).includes("/")) return true;
  return ["http", "https", "mailto"].includes(value.slice(0, colon).toLowerCase());
}
function filterURL(value: string): string { return safeURL(value) ? value : rejectedURL; }

// Source attributes remain byte-preserving, but their context follows what
// the HTML parser sees after resolving character references. Only ASCII
// references can affect URL delimiters, whitespace, or refresh markers.
function contextText(source: string): string {
  const named: Readonly<Record<string, string>> = { Tab: "\t", NewLine: "\n", quest: "?", num: "#", semi: ";", equals: "=", amp: "&", AMP: "&", colon: ":", sol: "/", quot: '"', QUOT: '"', apos: "'", lpar: "(", rpar: ")", bsol: "\\", ast: "*", grave: "`", lcub: "{", rcub: "}" };
  return source.replace(/&#(?:[xX][0-9a-fA-F]+|[0-9]+);?|&(?:Tab|NewLine|quest|num|semi|equals|amp|AMP|colon|sol|quot|QUOT|apos|lpar|rpar|bsol|ast|grave|lcub|rcub);/g, (entity) => {
    if (entity.startsWith("&#")) {
      const text = entity.slice(2).replace(/;$/, "");
      const value = text[0]?.toLowerCase() === "x" ? Number.parseInt(text.slice(1), 16) : Number.parseInt(text, 10);
      return value > 0 && value < 128 ? String.fromCharCode(value) : "\uFFFD";
    }
    return named[entity.slice(1, -1)] ?? entity;
  });
}

// URL normalization preserves valid percent escapes and URL delimiters;
// query/fragment escaping encodes delimiters and percent signs as data.
function writeURL(writer: BoundedByteWriter, value: string, normalize: boolean): void {
  const allowed = normalize ? /^[A-Za-z0-9_.~!#$&*+,/:;=?@\[\]-]$/ : /^[A-Za-z0-9_.~-]$/;
  let start = 0;
  for (let index = 0; index < value.length; index++) {
    const character = value[index] ?? "";
    if (allowed.test(character) || (normalize && character === "%" && /^[0-9A-Fa-f]{2}$/.test(value.slice(index + 1, index + 3)))) continue;
    if (start < index) escapeHTML(writer, value.slice(start, index));
    const point = value.codePointAt(index);
    if (point === undefined) break;
    const scalar = String.fromCodePoint(point);
    for (const byte of encoder.encode(scalar)) writer.write(`%${byte.toString(16).padStart(2, "0")}`);
    index += scalar.length - 1;
    start = index + 1;
  }
  escapeHTML(writer, value.slice(start));
}

function writeSrcset(writer: BoundedByteWriter, value: string): void {
  let left = 0;
  for (let cursor = 0; cursor <= value.length; cursor++) {
    if (cursor < value.length && value[cursor] !== ",") continue;
    let start = left;
    while (start < cursor && htmlSpace.test(value[start] ?? "")) start++;
    let end = start;
    while (end < cursor && !htmlSpace.test(value[end] ?? "")) end++;
    const url = value.slice(start, end);
    const metadata = value.slice(end, cursor);
    if (safeURL(url) && /^[A-Za-z0-9\t\n\f\r ]*$/.test(metadata)) {
      escapeHTML(writer, value.slice(left, start));
      writeURL(writer, url, true);
      escapeHTML(writer, metadata);
    } else writer.write(rejectedURL);
    if (cursor < value.length) writer.write(",");
    left = cursor + 1;
  }
}

function ownValue(value: unknown, field: string): unknown {
  if (typeof value !== "object" || value === null) throw new Error(`theme: cannot read field ${JSON.stringify(field)} from a non-record`);
  const descriptor = Object.getOwnPropertyDescriptor(value, field);
  if (descriptor === undefined || !("value" in descriptor)) throw new Error(`theme: missing data field ${JSON.stringify(field)}`);
  return descriptor.value;
}
function scalar(value: unknown): string {
  if (typeof value === "string") return value;
  if (typeof value === "number" && Number.isSafeInteger(value)) return String(value);
  throw new Error("theme: printable value must be string or a safe integer");
}
function truth(value: unknown): boolean {
  if (typeof value !== "boolean") throw new Error("theme: condition must be bool");
  return value;
}

export function render(program: Program, frame: Readonly<Record<string, unknown>>, options: RenderOptions): Uint8Array {
  return new Interpreter(program, options).render(frame);
}

class Interpreter {
  private readonly program: Program;
  private readonly options: RenderOptions;
  private readonly writer: BoundedByteWriter;
  private remainingSteps: number;
  constructor(program: Program, options: RenderOptions) {
    if (options.signal?.aborted) throw options.signal.reason ?? new DOMException("render canceled", "AbortError");
    if (program.version !== programVersion) throw new Error(`theme: unsupported program version ${program.version}`);
    if (program.renderSteps !== maxRenderSteps) throw new Error("theme: invalid render step contract");
    const maximum = options.maxSteps ?? maxRenderSteps;
    if (!Number.isSafeInteger(maximum) || maximum < 0 || maximum > maxRenderSteps) throw new Error(`theme: step limit must be 0..${maxRenderSteps}`);
    if (options.featured.length !== program.featured.length) throw new Error("theme: featured data does not match declared bindings");
    for (const reference of program.featured) if (!Number.isSafeInteger(reference.limit) || reference.limit < 1 || reference.limit > maxFeaturedLimit) throw new Error("theme: invalid featured limit");
    this.program = program;
    this.options = options;
    this.writer = new BoundedByteWriter(options.maxOutputBytes ?? maxRenderBytes, options.signal);
    this.remainingSteps = maximum;
  }
  render(frame: Readonly<Record<string, unknown>>): Uint8Array {
    this.writer.checkCancellation();
    const bindings = new Map<string, unknown>();
    for (const input of this.program.inputs) {
      if (bindings.has(input.binding)) throw new Error("theme: duplicate input binding");
      bindings.set(input.binding, ownValue(frame, input.field));
    }
    this.nodes(this.program.nodes, bindings, 0, "text");
    return this.writer.bytes();
  }
  private expression(expression: RenderExpression, bindings: ReadonlyMap<string, unknown>, depth = 0): unknown {
    this.writer.checkCancellation();
    if (depth > 1024) throw new RenderLimitError("data");
    const evaluate = (value: RenderExpression) => this.expression(value, bindings, depth + 1);
    switch (expression.kind) {
      case "literal": return expression.value;
      case "binding": {
        if (!bindings.has(expression.name)) throw new Error(`theme: missing lexical binding ${JSON.stringify(expression.name)}`);
        let value = bindings.get(expression.name);
        for (const field of expression.fields) value = ownValue(value, field);
        return value;
      }
      case "not": return !truth(evaluate(expression.value));
      case "binary": {
        if (expression.operator === "&&") return truth(evaluate(expression.left)) && truth(evaluate(expression.right));
        if (expression.operator === "||") return truth(evaluate(expression.left)) || truth(evaluate(expression.right));
        const left = evaluate(expression.left);
        const right = evaluate(expression.right);
        if (left === undefined || right === undefined) throw new Error("theme: missing comparison value");
        return expression.operator === "==" ? left === right : left !== right;
      }
      case "concat": {
        const value = new BoundedByteWriter(this.writer.maximum, this.options.signal);
        for (const item of expression.values) value.write(scalar(evaluate(item)));
        return new TextDecoder().decode(value.bytes());
      }
      case "len": {
        const value = evaluate(expression.array);
        if (!Array.isArray(value)) throw new Error("theme: len needs an array");
        return value.length;
      }
      case "plural": {
        const count = evaluate(expression.count);
        if (typeof count !== "number" || !Number.isSafeInteger(count)) throw new Error("theme: plural count must be a safe integer");
        const value = evaluate(count === 1 ? expression.one : expression.many);
        if (typeof value !== "string") throw new Error("theme: plural forms must be strings");
        return value;
      }
      case "route": {
        const args = expression.args.map((argument) => {
          const value = evaluate(argument);
          if (typeof value !== "string") throw new Error("theme: route parameters must be strings or IDs");
          return value;
        });
        const path = this.options.routes.path(expression.route, args);
        if (typeof path !== "string") throw new Error("theme: route path must be a string");
        this.writer.checkCancellation();
        return path;
      }
      case "featured": {
        if (!Number.isSafeInteger(expression.index) || expression.index < 0 || expression.index >= this.options.featured.length) throw new Error("theme: undeclared featured binding");
        const value = ownValue(this.options.featured, String(expression.index));
        if (value === undefined) throw new Error("theme: missing featured value");
        return value;
      }
    }
  }
  private nodes(nodes: readonly RenderNode[], bindings: ReadonlyMap<string, unknown>, invocationDepth: number, context: "text" | "rcdata"): void {
    if (invocationDepth > maxInvokeDepth) throw new RenderLimitError("invocation");
    for (const node of nodes) {
      this.writer.checkCancellation();
      switch (node.kind) {
        case "doctype":
          this.writer.write("<!doctype html>");
          break;
        case "text":
          if (node.context !== context) throw new Diagnostic(node.position, "text escaping context does not match its element");
          for (const part of node.parts) {
            if (part.kind === "literal") this.writer.write(context === "rcdata" ? part.value.replace(/<(?!\!doctype)/gi, "&lt;") : part.value);
            else escapeHTML(this.writer, scalar(this.expression(part.expression, bindings)), part.constantText !== true);
          }
          break;
        case "if": this.nodes(truth(this.expression(node.test, bindings)) ? node.children : node.otherwise, bindings, invocationDepth, context); break;
        case "with": {
          const value = this.expression(node.value, bindings);
          if (value === undefined) throw new Error("theme: nullable value cannot be absent");
          if (value === null) this.nodes(node.otherwise, bindings, invocationDepth, context);
          else {
            const inner = new Map(bindings);
            inner.set(node.binding, value);
            this.nodes(node.children, inner, invocationDepth, context);
          }
          break;
        }
        case "for": {
          const values = this.expression(node.array, bindings);
          if (!Array.isArray(values)) throw new Error("theme: loop needs a non-null array");
          if (node.chargeStep !== true) throw new Error("theme: loop work charge is missing");
          if (values.length === 0) this.nodes(node.otherwise, bindings, invocationDepth, context);
          for (let index = 0; index < values.length; index++) {
            this.writer.checkCancellation();
            if (this.remainingSteps === 0) throw new RenderLimitError("steps");
            this.remainingSteps--;
            const inner = new Map(bindings);
            inner.set(node.binding, ownValue(values, String(index)));
            if (node.index !== null) inner.set(node.index, index);
            this.nodes(node.children, inner, invocationDepth, context);
          }
          break;
        }
        case "let": {
          const inner = new Map(bindings);
          for (const binding of node.bindings) inner.set(binding.name, this.expression(binding.value, bindings));
          this.nodes(node.children, inner, invocationDepth + 1, context);
          break;
        }
        case "element": {
          if (!htmlElements.has(node.tag) || context === "rcdata" && textContext(node.tag) === "rcdata") throw new Diagnostic(node.position, "unsafe element in render program");
          this.writer.write(`${context === "rcdata" ? "&lt;" : "<"}${node.tag}`);
          for (const attribute of node.attributes) this.attribute(node.tag, attribute, bindings, node.position, context === "rcdata");
          this.writer.write(">");
          if (!voidElements.has(node.tag)) {
            this.nodes(node.children, bindings, invocationDepth, context === "rcdata" ? "rcdata" : textContext(node.tag));
            this.writer.write(`${context === "rcdata" ? "&lt;" : "<"}/${node.tag}>`);
          } else if (node.children.length !== 0) throw new Diagnostic(node.position, "void element cannot have children");
          break;
        }
        case "scripts":
          for (const script of this.program.scripts) {
            if (!script.startsWith("/static/") || /[\x00-\x20]/.test(script)) throw new Diagnostic(node.position, "scripts must use local /static/ URLs");
            this.writer.write(`${context === "rcdata" ? "&lt;" : "<"}script type="module" src="`);
            writeURL(this.writer, script, true);
            this.writer.write(`">${context === "rcdata" ? "&lt;" : "<"}/script>`);
          }
          break;
      }
    }
  }
  private attribute(tag: string, attribute: RenderAttribute, bindings: ReadonlyMap<string, unknown>, position: Position, rcdata = false): void {
    if (!/^[a-z][a-z0-9-]*(?::[a-z][a-z0-9-]*)?$/.test(attribute.name) || attribute.name.startsWith("on") || attribute.name === "srcdoc") throw new Diagnostic(position, "unsafe attribute in render program");
    if (attribute.kind === "boolean") {
      if (truth(this.expression(attribute.expression, bindings))) this.writer.write(` ${attribute.name}`);
      return;
    }
    if (attribute.kind === "flag") { this.writer.write(` ${attribute.name}`); return; }
    const expected = attribute.name === "data-props" ? "json" : tag === "meta" && attribute.name === "content" ? "meta" : attributeContext(attribute.name);
    if (attribute.context !== expected) throw new Diagnostic(position, `attribute ${JSON.stringify(attribute.name)} has an invalid escaping context`);
    if (attribute.name === "style" && attribute.parts.some((part) => part.kind !== "literal")) throw new Diagnostic(position, "style attributes must contain authored literals only");
    this.writer.write(` ${attribute.name}="`);
    if (attribute.context === "json") {
      const part = attribute.parts[0];
      if (attribute.parts.length !== 1 || part?.kind !== "expression") throw new Diagnostic(position, "behavior props require one data expression");
      const value = this.expression(part.expression, bindings);
      this.validateData(attribute.type, value);
      const encoded = this.options.encodeJSON(attribute.type, value);
      if (typeof encoded !== "string") throw new Error("theme: browser encoder must return JSON text");
      escapeHTML(this.writer, encoded);
    } else if (!rcdata && attribute.context === "style") this.cssParts(attribute.parts, bindings);
    else if (!rcdata && attribute.context === "url") this.urlParts(attribute.parts, bindings);
    else if (!rcdata && attribute.context === "meta") this.metaParts(attribute.parts, bindings);
    else for (const part of attribute.parts) {
      if (part.kind === "literal") this.writer.write((rcdata ? part.value.replace(/<(?!\!doctype)/gi, "&lt;") : part.value).replaceAll('"', "&#34;"));
      else {
        const value = scalar(this.expression(part.expression, bindings));
        if (!rcdata && attribute.context === "srcset") writeSrcset(this.writer, value);
        else escapeHTML(this.writer, value);
      }
    }
    this.writer.write('"');
  }
  private cssParts(parts: readonly RenderPart[], bindings: ReadonlyMap<string, unknown>): void {
    const context = new CSSContext();
    for (const part of parts) {
      if (part.kind === "literal") {
        context.advance(contextText(part.value));
        this.writer.write(part.value.replaceAll('"', "&#34;"));
      } else {
        const value = scalar(this.expression(part.expression, bindings));
        if (context.state === "value") escapeHTML(this.writer, filterCSS(value));
        else if (context.state === "string" || context.state === "url") {
          const filtered = context.phase === "start" ? filterURL(value) : value;
          if (context.state === "string" && context.phase !== "query") escapeHTML(this.writer, escapeCSS(filtered));
          else writeURL(this.writer, filtered, context.phase !== "query");
        }
      }
    }
  }
  private urlParts(parts: readonly RenderPart[], bindings: ReadonlyMap<string, unknown>): void {
    let phase: "start" | "path" | "query" = "start";
    for (const part of parts) {
      if (part.kind === "literal") {
        this.writer.write(part.value.replaceAll('"', "&#34;"));
        const decoded = contextText(part.value);
        if (/[?#]/.test(decoded)) phase = "query";
        else if (phase === "start" && /[^\t\n\f\r ]/.test(decoded)) phase = "path";
      } else {
        const value = scalar(this.expression(part.expression, bindings));
        writeURL(this.writer, phase === "start" ? filterURL(value) : value, phase !== "query");
      }
    }
  }
  private metaParts(parts: readonly RenderPart[], bindings: ReadonlyMap<string, unknown>): void {
    let source = "";
    for (const part of parts) {
      if (part.kind === "literal") {
        source += contextText(part.value);
        this.writer.write(part.value.replaceAll('"', "&#34;"));
      } else {
        const prefix = source.slice(source.lastIndexOf(";") + 1);
        const value = scalar(this.expression(part.expression, bindings));
        escapeHTML(this.writer, /url[\t\n\f\r ]*=/.test(prefix.toLowerCase()) ? filterURL(value) : value);
      }
    }
  }
  private validateData(type: ContractType, value: unknown): void {
    let visited = 0;
    const validate = (current: ContractType, data: unknown, depth: number): void => {
      this.writer.checkCancellation();
      if (++visited > maxExpandedNodes || depth > 64) throw new RenderLimitError("data");
      if (current.kind === "nullable") { if (data !== null) validate(current.element, data, depth + 1); return; }
      if (current.kind === "string") { if (typeof data !== "string") throw new Error("theme: browser string is missing or invalid"); return; }
      if (current.kind === "bool") { truth(data); return; }
      if (current.kind === "int") { if (typeof data !== "number" || !Number.isSafeInteger(data)) throw new Error("theme: browser integer is missing or unsafe"); return; }
      if (current.kind === "ID") { if (typeof data !== "string" || !/^[1-9][0-9]{0,18}$/.test(data) || BigInt(data) > 9223372036854775807n) throw new Error("theme: browser ID is invalid"); return; }
      if (current.kind === "enum") { if (typeof data !== "string" || !current.members.includes(data)) throw new Error("theme: browser enum member is invalid"); return; }
      if (current.kind === "array") {
        if (!Array.isArray(data)) throw new Error("theme: browser arrays must be present and non-null");
        for (let index = 0; index < data.length; index++) validate(current.element, ownValue(data, String(index)), depth + 1);
        return;
      }
      if (current.kind !== "record") throw new Error("theme: invalid browser contract type");
      if (typeof data !== "object" || data === null || Array.isArray(data)) throw new Error("theme: browser record is missing or invalid");
      const keys = Object.keys(data);
      if (keys.length !== Object.keys(current.fields).length || keys.some((key) => !Object.hasOwn(current.fields, key))) throw new Error("theme: browser record has missing or extra keys");
      for (const [field, fieldType] of Object.entries(current.fields)) validate(fieldType, ownValue(data, field), depth + 1);
    };
    validate(type, value, 0);
  }
}
