import { IdempotencyWindowMs, type SendOutcome } from "../email/resend.ts";
import { MaxAttempts } from "./work.ts";

export const EmailKinds = ["order_confirmation", "shipment", "cancellation_voided", "cancellation_items", "refund", "late_void", "access_link"] as const;
export type EmailKind = (typeof EmailKinds)[number];

export const EmailStates = ["queued", "sending", "sent", "failed", "unknown"] as const;
export type EmailState = (typeof EmailStates)[number];

export const EmailSendKind = "email_send";
export const emailSendKey = (messageId: bigint, generation: bigint): string => `email:${messageId}:${generation}`;

export const AccessLifetimeSeconds = 90 * 24 * 3600;
export const UnknownWindowSeconds = IdempotencyWindowMs / 1000;
export const LookupLimit = 5;
export const LookupWindowSeconds = 3600;
export const MaxEmailErrorLength = 500;

export function isEmailKind(value: string): value is EmailKind {
  return (EmailKinds as readonly string[]).includes(value);
}

export function isEmailState(value: string): value is EmailState {
  return (EmailStates as readonly string[]).includes(value);
}

export type BeginDecision =
  | { readonly kind: "send" }
  | { readonly kind: "skip"; readonly reason: "sent" | "failed" | "window_closed" };

export function decideBegin(state: EmailState, firstAttemptAt: bigint | null, nowSeconds: bigint): BeginDecision {
  if (state === "sent") return { kind: "skip", reason: "sent" };
  if (state === "failed") return { kind: "skip", reason: "failed" };
  if (firstAttemptAt !== null && nowSeconds - firstAttemptAt >= BigInt(UnknownWindowSeconds)) return { kind: "skip", reason: "window_closed" };
  return { kind: "send" };
}

export function mayResend(state: EmailState, firstAttemptAt: bigint | null, nowSeconds: bigint): boolean {
  if (state === "failed") return true;
  return state === "unknown" && firstAttemptAt !== null && nowSeconds - firstAttemptAt >= BigInt(UnknownWindowSeconds);
}

export type Settlement =
  | { readonly state: "sent"; readonly providerId: string }
  | { readonly state: "failed" | "queued" | "unknown"; readonly error: string; readonly next: "done" | "retry" | "blocked" };

function clamp(text: string): string {
  return text.length <= MaxEmailErrorLength ? text : `${text.slice(0, MaxEmailErrorLength - 3)}...`;
}

export function settlementFor(outcome: SendOutcome, claimAttempt: number): Settlement {
  const exhausted = claimAttempt >= MaxAttempts;
  switch (outcome.kind) {
    case "sent": return { state: "sent", providerId: outcome.providerId };
    case "permanent": {
      const error = clamp(`${outcome.error.name}: ${outcome.error.message}`);
      return outcome.reason === "configuration" ? { state: "queued", error, next: "blocked" } : { state: "failed", error, next: "done" };
    }
    case "retryable": {
      const error = clamp(`${outcome.error.name}: ${outcome.error.message}`);
      return exhausted ? { state: "failed", error, next: "done" } : { state: "queued", error, next: "retry" };
    }
    case "unknown": {
      const error = `no definite answer from the mail provider (${outcome.cause})`;
      return { state: "unknown", error, next: exhausted ? "done" : "retry" };
    }
    case "idempotency_mismatch": return { state: "failed", error: clamp(`${outcome.error.name}: ${outcome.error.message}`), next: "done" };
    case "idempotency_in_flight": {
      const error = clamp(`${outcome.error.name}: ${outcome.error.message}`);
      return { state: "unknown", error, next: exhausted ? "done" : "retry" };
    }
  }
}
