import { Schema } from "effect";

export const InfoKinds = ["about", "shipping", "returns", "privacy", "terms"] as const;
export type InfoKind = (typeof InfoKinds)[number];

export const InfoTitles: Readonly<Record<InfoKind, string>> = Object.freeze({
  about: "About us",
  shipping: "Shipping",
  returns: "Returns",
  privacy: "Privacy policy",
  terms: "Terms of service",
});

export function isInfoKind(value: string): value is InfoKind {
  return (InfoKinds as readonly string[]).includes(value);
}

export const MaxBlocks = 40;
export const MaxHeadingBytes = 200;
export const MaxParagraphBytes = 4000;
export const MaxListItems = 30;
export const MaxListItemBytes = 400;
export const MaxPageTextBytes = 16 * 1024;
export const MaxShopNameBytes = 100;
export const MaxDescriptionBytes = 300;
export const MaxPhoneBytes = 40;
export const MinPhoneBytes = 3;
export const MaxEmailBytes = 254;

const encoder = new TextEncoder();
const bytes = (value: string): number => encoder.encode(value).length;

export const StoredBlockSchema = Schema.Union([
  Schema.Struct({ type: Schema.Literal("heading"), text: Schema.String }),
  Schema.Struct({ type: Schema.Literal("paragraph"), text: Schema.String }),
  Schema.Struct({ type: Schema.Literal("list"), items: Schema.Array(Schema.String) }),
]);
const BlocksSchema = Schema.Array(StoredBlockSchema);
export type InfoBlock = typeof StoredBlockSchema.Type;

export const BlockProblemKinds = ["empty", "too_long", "bad_text", "too_many_blocks", "too_many_items", "page_too_long"] as const;
export type BlockProblem = (typeof BlockProblemKinds)[number];

export interface BlockIssue {
  readonly index: number;
  readonly problem: BlockProblem;
}

const blank = (value: string): boolean => value.trim() === "";
const unprintable = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f\u2028\u2029\ud800-\udfff]/u;
const lineBreak = /[\n]/;

function lineProblem(value: string, limit: number): BlockProblem | null {
  if (blank(value)) return "empty";
  if (unprintable.test(value) || lineBreak.test(value)) return "bad_text";
  return bytes(value) > limit ? "too_long" : null;
}

export function blockIssues(blocks: readonly InfoBlock[]): readonly BlockIssue[] {
  const issues: BlockIssue[] = [];
  if (blocks.length > MaxBlocks) issues.push({ index: MaxBlocks, problem: "too_many_blocks" });
  let total = 0;
  for (const [index, block] of blocks.entries()) {
    if (block.type === "list") {
      if (block.items.length === 0) issues.push({ index, problem: "empty" });
      else if (block.items.length > MaxListItems) issues.push({ index, problem: "too_many_items" });
      else {
        const problem = block.items.map((item) => lineProblem(item, MaxListItemBytes)).find((found) => found !== null);
        if (problem !== undefined && problem !== null) issues.push({ index, problem });
      }
      total += block.items.reduce((sum, item) => sum + bytes(item), 0);
    } else {
      const problem = lineProblem(block.text, block.type === "heading" ? MaxHeadingBytes : MaxParagraphBytes);
      if (problem !== null) issues.push({ index, problem });
      total += bytes(block.text);
    }
  }
  if (total > MaxPageTextBytes) issues.push({ index: Math.max(0, blocks.length - 1), problem: "page_too_long" });
  return issues;
}

export function encodeBlocks(blocks: readonly InfoBlock[]): string {
  const issues = blockIssues(blocks);
  if (issues.length > 0) throw new RangeError(`info: invalid blocks (${issues[0]?.problem})`);
  return JSON.stringify(blocks);
}

export function decodeBlocks(text: string): readonly InfoBlock[] {
  const blocks = Schema.decodeUnknownSync(BlocksSchema, { onExcessProperty: "error" })(JSON.parse(text));
  const issues = blockIssues(blocks);
  if (issues.length > 0) throw new RangeError(`info: stored blocks are invalid (${issues[0]?.problem})`);
  return blocks;
}

export function validShopName(value: string): boolean {
  return !blank(value) && value === value.trim() && bytes(value) <= MaxShopNameBytes && !unprintable.test(value) && !lineBreak.test(value);
}

export function validDescription(value: string): boolean {
  return value === value.trim() && bytes(value) <= MaxDescriptionBytes && !unprintable.test(value) && !lineBreak.test(value);
}

export function validContactEmail(value: string): boolean {
  return bytes(value) <= MaxEmailBytes && /^[!-~]+@[!-~]+\.[!-~]+$/.test(value);
}

export function validContactPhone(value: string): boolean {
  return bytes(value) >= MinPhoneBytes && bytes(value) <= MaxPhoneBytes && value === value.trim() && !unprintable.test(value) && !lineBreak.test(value);
}
