import {
  decodeAccount, decodeCheckoutSession, decodeDispute, decodeErrorBody, decodePaymentIntent, decodeRefund, decodeRetrievedPaymentIntent, decodeReview,
  listOf, searchOf, decodeEvent, CancellationReasons,
  type Account, type CheckoutSession, type Dispute, type ListPage, type PaymentIntent, type Refund, type RetrievedPaymentIntent, type Review, type SearchPage, type StripeEvent, type StripeMetadata,
} from "./objects.ts";
import type { Decoder } from "./decode.ts";
import { parseJson } from "./decode.ts";
import { StripeApiError, StripeConfigError, StripeDecodeError, StripeTransportError } from "./errors.ts";
import { encodeForm, type FormObject } from "./form.ts";
import { STRIPE_API_BASE, STRIPE_VERSION, StripeMaxAmountMinor } from "./version.ts";

export type StripeMode = "test" | "live";

export interface StripeClientConfig {
  readonly secretKey: string;
  readonly mode: StripeMode;
  readonly fetch: typeof fetch;
  readonly apiBase?: string;
  readonly timeoutMs?: number;
}

const defaultTimeoutMs = 20_000;
const maxLineItems = 100;
const maxMetadataKeys = 50;

export function isLoopbackHostname(hostname: string): boolean {
  const bare = hostname.startsWith("[") && hostname.endsWith("]") ? hostname.slice(1, -1) : hostname;
  if (bare === "localhost" || bare.endsWith(".localhost") || bare === "::1") return true;
  return /^127(\.[0-9]{1,3}){3}$/.test(bare);
}

export function resolveApiBase(override: string | undefined): string {
  if (override === undefined) return STRIPE_API_BASE;
  let url: URL;
  try {
    url = new URL(override);
  } catch {
    throw new StripeConfigError("apiBase is not a URL");
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") throw new StripeConfigError("apiBase must be http or https");
  if (!isLoopbackHostname(url.hostname)) throw new StripeConfigError(`apiBase host ${url.hostname} is not loopback`);
  if (url.username !== "" || url.password !== "" || url.search !== "" || url.hash !== "") throw new StripeConfigError("apiBase must be a bare origin");
  return url.origin;
}

function checkKey(secretKey: string, mode: StripeMode): void {
  const prefixes = mode === "test" ? ["sk_test_", "rk_test_"] : ["sk_live_", "rk_live_"];
  if (!prefixes.some((prefix) => secretKey.startsWith(prefix)) || secretKey.length < prefixes[0]!.length + 8) {
    throw new StripeConfigError(`secret key does not match mode ${mode}`);
  }
}

function checkId(id: string, what: string): string {
  if (!/^[A-Za-z0-9_]{1,255}$/.test(id)) throw new StripeConfigError(`invalid ${what} id`);
  return id;
}

function checkIdempotencyKey(key: string): string {
  if (!/^[\x21-\x7e]{1,255}$/.test(key)) throw new StripeConfigError("idempotency key must be 1-255 printable ASCII characters");
  return key;
}

function checkMetadata(metadata: StripeMetadata): StripeMetadata {
  const entries = Object.entries(metadata);
  if (entries.length > maxMetadataKeys) throw new StripeConfigError("metadata exceeds 50 keys");
  for (const [key, value] of entries) {
    if (key.length === 0 || key.length > 40 || value.length > 500) throw new StripeConfigError(`metadata entry ${key} exceeds Stripe limits`);
  }
  return metadata;
}

export interface CheckoutLineInput {
  readonly name: string;
  readonly unitAmount: bigint;
  readonly quantity: number;
}

export interface CreateCheckoutSessionParams {
  readonly currency: string;
  readonly lines: readonly CheckoutLineInput[];
  readonly customerEmail: string;
  readonly successUrl: string;
  readonly cancelUrl: string;
  readonly expiresAt: number;
  readonly clientReferenceId: string;
  readonly metadata: StripeMetadata;
}

export interface ListCheckoutSessionsParams {
  readonly paymentIntentId?: string;
  readonly status?: "open" | "complete" | "expired";
  readonly createdGte?: number;
  readonly limit?: number;
  readonly startingAfter?: string;
}

export interface CreateRefundParams {
  readonly paymentIntentId: string;
  readonly amount: bigint;
  readonly metadata: StripeMetadata;
  readonly reason?: "duplicate" | "fraudulent" | "requested_by_customer";
}

export interface ListRefundsParams {
  readonly paymentIntentId: string;
  readonly limit?: number;
  readonly startingAfter?: string;
}

export interface SearchPaymentIntentsParams {
  readonly query: string;
  readonly limit?: number;
  readonly page?: string;
}

export type CancellationReason = (typeof CancellationReasons)[number];

export interface StripeClient {
  createCheckoutSession(params: CreateCheckoutSessionParams, idempotencyKey: string): Promise<CheckoutSession>;
  retrieveCheckoutSession(id: string): Promise<CheckoutSession>;
  expireCheckoutSession(id: string, idempotencyKey: string): Promise<CheckoutSession>;
  listCheckoutSessions(params: ListCheckoutSessionsParams): Promise<ListPage<CheckoutSession>>;
  retrievePaymentIntent(id: string): Promise<RetrievedPaymentIntent>;
  capturePaymentIntent(id: string, params: { readonly amountToCapture?: bigint }, idempotencyKey: string): Promise<PaymentIntent>;
  cancelPaymentIntent(id: string, params: { readonly cancellationReason?: CancellationReason }, idempotencyKey: string): Promise<PaymentIntent>;
  searchPaymentIntents(params: SearchPaymentIntentsParams): Promise<SearchPage<PaymentIntent>>;
  createRefund(params: CreateRefundParams, idempotencyKey: string): Promise<Refund>;
  retrieveRefund(id: string): Promise<Refund>;
  listRefunds(params: ListRefundsParams): Promise<ListPage<Refund>>;
  retrieveEvent(id: string): Promise<StripeEvent>;
  retrieveDispute(id: string): Promise<Dispute>;
  retrieveReview(id: string): Promise<Review>;
  retrieveAccount(): Promise<Account>;
}

function limitParam(limit: number | undefined, out: Record<string, string | number>): void {
  if (limit === undefined) return;
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 100) throw new StripeConfigError("limit must be 1-100");
  out["limit"] = limit;
}

export function createStripeClient(config: StripeClientConfig): StripeClient {
  checkKey(config.secretKey, config.mode);
  const base = resolveApiBase(config.apiBase);
  const timeoutMs = config.timeoutMs ?? defaultTimeoutMs;

  async function call<T>(method: "GET" | "POST", path: string, decode: Decoder<T>, options: { readonly form?: FormObject; readonly idempotencyKey?: string } = {}): Promise<T> {
    const headers: Record<string, string> = {
      Authorization: `Bearer ${config.secretKey}`,
      "Stripe-Version": STRIPE_VERSION,
    };
    let url = `${base}${path}`;
    let body: string | undefined;
    const encoded = options.form === undefined ? "" : encodeForm(options.form);
    if (method === "GET") {
      if (encoded !== "") url += `?${encoded}`;
    } else {
      headers["Content-Type"] = "application/x-www-form-urlencoded";
      body = encoded;
      if (options.idempotencyKey !== undefined) headers["Idempotency-Key"] = checkIdempotencyKey(options.idempotencyKey);
    }
    const signal = AbortSignal.timeout(timeoutMs);
    let status: number;
    let requestId: string | null;
    let text: string;
    try {
      const init: RequestInit = { method, headers, redirect: "manual", signal };
      if (body !== undefined) init.body = body;
      const response = await config.fetch(url, init);
      status = response.status;
      requestId = response.headers.get("request-id");
      text = await response.text();
    } catch (error) {
      throw new StripeTransportError(signal.aborted ? "timeout" : "network", method, path, { cause: error });
    }
    if (status < 200 || status >= 300) throw apiError(status, requestId, text);
    const parsed = parseJson(text, status);
    try {
      return decode(parsed, "$");
    } catch (error) {
      if (error instanceof StripeDecodeError) throw new StripeDecodeError(error.path, error.detail, status);
      throw error;
    }
  }

  function apiError(status: number, requestId: string | null, text: string): StripeApiError {
    try {
      const { error } = decodeErrorBody(parseJson(text, status), "$");
      return new StripeApiError(status, error.type, error.code, error.param, requestId, error.message ?? "");
    } catch {
      return new StripeApiError(status, "unparseable_error", null, null, requestId, "error body was not a Stripe error");
    }
  }

  const sessionPath = (id: string) => `/v1/checkout/sessions/${checkId(id, "checkout session")}`;
  const intentPath = (id: string) => `/v1/payment_intents/${checkId(id, "payment intent")}`;

  return {
    createCheckoutSession(params, idempotencyKey) {
      if (!/^[a-z]{3}$/.test(params.currency)) throw new StripeConfigError("currency must be a lowercase ISO code");
      if (params.lines.length < 1 || params.lines.length > maxLineItems) throw new StripeConfigError("line items must number 1-100");
      const metadata = checkMetadata(params.metadata);
      const form: FormObject = {
        mode: "payment",
        ui_mode: "hosted_page",
        payment_method_types: ["card"],
        payment_intent_data: { capture_method: "manual", metadata },
        line_items: params.lines.map((line) => ({
          quantity: line.quantity,
          price_data: { currency: params.currency, unit_amount: line.unitAmount, product_data: { name: line.name } },
        })),
        customer_email: params.customerEmail,
        success_url: params.successUrl,
        cancel_url: params.cancelUrl,
        expires_at: params.expiresAt,
        client_reference_id: params.clientReferenceId,
        metadata,
      };
      return call("POST", "/v1/checkout/sessions", decodeCheckoutSession, { form, idempotencyKey });
    },
    retrieveCheckoutSession: (id) => call("GET", sessionPath(id), decodeCheckoutSession),
    expireCheckoutSession: (id, idempotencyKey) => call("POST", `${sessionPath(id)}/expire`, decodeCheckoutSession, { idempotencyKey }),
    listCheckoutSessions(params) {
      const form: Record<string, string | number | FormObject> = {};
      if (params.paymentIntentId !== undefined) form["payment_intent"] = checkId(params.paymentIntentId, "payment intent");
      if (params.status !== undefined) form["status"] = params.status;
      if (params.createdGte !== undefined) form["created"] = { gte: params.createdGte };
      if (params.startingAfter !== undefined) form["starting_after"] = checkId(params.startingAfter, "cursor");
      limitParam(params.limit, form as Record<string, string | number>);
      return call("GET", "/v1/checkout/sessions", listOf(decodeCheckoutSession), { form });
    },
    retrievePaymentIntent: (id) => call("GET", intentPath(id), decodeRetrievedPaymentIntent, { form: { expand: ["latest_charge"] } }),
    capturePaymentIntent(id, params, idempotencyKey) {
      const form: FormObject = params.amountToCapture === undefined ? {} : { amount_to_capture: params.amountToCapture };
      return call("POST", `${intentPath(id)}/capture`, decodePaymentIntent, { form, idempotencyKey });
    },
    cancelPaymentIntent(id, params, idempotencyKey) {
      const form: FormObject = params.cancellationReason === undefined ? {} : { cancellation_reason: params.cancellationReason };
      return call("POST", `${intentPath(id)}/cancel`, decodePaymentIntent, { form, idempotencyKey });
    },
    searchPaymentIntents(params) {
      const form: Record<string, string | number> = { query: params.query };
      if (params.page !== undefined) form["page"] = params.page;
      limitParam(params.limit, form);
      return call("GET", "/v1/payment_intents/search", searchOf(decodePaymentIntent), { form });
    },
    createRefund(params, idempotencyKey) {
      if (params.amount < 1n || params.amount > StripeMaxAmountMinor) throw new StripeConfigError("refund amount outside 1..max");
      const form: FormObject = {
        payment_intent: checkId(params.paymentIntentId, "payment intent"),
        amount: params.amount,
        metadata: checkMetadata(params.metadata),
        ...(params.reason === undefined ? {} : { reason: params.reason }),
      };
      return call("POST", "/v1/refunds", decodeRefund, { form, idempotencyKey });
    },
    retrieveRefund: (id) => call("GET", `/v1/refunds/${checkId(id, "refund")}`, decodeRefund),
    listRefunds(params) {
      const form: Record<string, string | number> = { payment_intent: checkId(params.paymentIntentId, "payment intent") };
      if (params.startingAfter !== undefined) form["starting_after"] = checkId(params.startingAfter, "cursor");
      limitParam(params.limit, form);
      return call("GET", "/v1/refunds", listOf(decodeRefund), { form });
    },
    retrieveEvent: (id) => call("GET", `/v1/events/${checkId(id, "event")}`, (value) => decodeEvent(value)),
    retrieveDispute: (id) => call("GET", `/v1/disputes/${checkId(id, "dispute")}`, decodeDispute),
    retrieveReview: (id) => call("GET", `/v1/reviews/${checkId(id, "review")}`, decodeReview),
    retrieveAccount: () => call("GET", "/v1/account", decodeAccount),
  };
}
