import { EmailValidationError, type EmailContent } from "./message.ts";

declare const linkBrand: unique symbol;

export interface EmailLink {
  readonly [linkBrand]: true;
  readonly label: string;
  readonly href: string;
}

export type InlinePart = string | EmailLink;

export interface EmailContentBuilder {
  link(label: string, target: string): EmailLink;
  heading(text: string): EmailContentBuilder;
  paragraph(...parts: readonly InlinePart[]): EmailContentBuilder;
  list(items: readonly (readonly InlinePart[])[]): EmailContentBuilder;
  build(): EmailContent;
}

type Block =
  | { readonly kind: "heading"; readonly text: string }
  | { readonly kind: "paragraph"; readonly parts: readonly InlinePart[] }
  | { readonly kind: "list"; readonly items: readonly (readonly InlinePart[])[] };

export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      default: return "&#39;";
    }
  });
}

function parseLinkOrigin(origin: string): string {
  let url: URL;
  try {
    url = new URL(origin);
  } catch {
    throw new EmailValidationError("link origin is not a URL");
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") throw new EmailValidationError("link origin must be http or https");
  if (url.origin !== origin) throw new EmailValidationError("link origin must be a bare origin");
  return url.origin;
}

function isLink(part: InlinePart): part is EmailLink {
  return typeof part !== "string";
}

function plainInline(parts: readonly InlinePart[]): string {
  return parts.map((part) => isLink(part) ? (part.label === part.href ? part.href : `${part.label} <${part.href}>`) : part).join("");
}

function htmlInline(parts: readonly InlinePart[]): string {
  return parts.map((part) => isLink(part) ? `<a href="${escapeHtml(part.href)}">${escapeHtml(part.label)}</a>` : escapeHtml(part)).join("");
}

export function createEmailContentBuilder(linkOrigin: string): EmailContentBuilder {
  const origin = parseLinkOrigin(linkOrigin);
  const blocks: Block[] = [];
  const builder: EmailContentBuilder = {
    link(label, target) {
      if (label.length === 0) throw new EmailValidationError("link label is empty");
      let url: URL;
      try {
        url = new URL(target, origin);
      } catch {
        throw new EmailValidationError("link is not a URL");
      }
      if (url.origin !== origin) throw new EmailValidationError("link is outside the configured origin");
      if (url.username !== "" || url.password !== "") throw new EmailValidationError("link carries credentials");
      return { label, href: url.href } as EmailLink;
    },
    heading(text) {
      blocks.push({ kind: "heading", text });
      return builder;
    },
    paragraph(...parts) {
      blocks.push({ kind: "paragraph", parts });
      return builder;
    },
    list(items) {
      blocks.push({ kind: "list", items });
      return builder;
    },
    build() {
      const text = blocks.map((block) => {
        switch (block.kind) {
          case "heading": return block.text;
          case "paragraph": return plainInline(block.parts);
          case "list": return block.items.map((item) => `- ${plainInline(item)}`).join("\n");
        }
      }).join("\n\n");
      const html = blocks.map((block) => {
        switch (block.kind) {
          case "heading": return `<h1>${escapeHtml(block.text)}</h1>`;
          case "paragraph": return `<p>${htmlInline(block.parts)}</p>`;
          case "list": return `<ul>${block.items.map((item) => `<li>${htmlInline(item)}</li>`).join("")}</ul>`;
        }
      }).join("");
      return { text, html: `<!doctype html><html><body>${html}</body></html>` };
    },
  };
  return builder;
}
