import { parseID } from "../routes/routes.ts";

export const MAX_QUERY_BYTES = 2048;
export const MAX_FORM_BYTES = 4096;
export const MAX_FIELD_BYTES = 400;
export const MAX_QUERY_TEXT_BYTES = 200;
export const MAX_PAGE = 10000;
const encoder = new TextEncoder();
const decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });

export class BadInput extends Error {
  readonly status = 400;
  constructor(message: string) { super(message); this.name = "BadInput"; }
}

function decodeComponent(raw: string): string {
  try {
    // decodeURIComponent rejects malformed escapes and invalid UTF-8 sequences.
    return decodeURIComponent(raw.replaceAll("+", " "));
  } catch {
    throw new BadInput("The request could not be read.");
  }
}

export function decodeFields(raw: string, allowed: readonly string[]): ReadonlyMap<string, string> {
  const out = new Map<string, string>();
  for (const pair of raw.split("&")) {
    if (pair === "") continue;
    if (pair.includes(";")) throw new BadInput("The request could not be read.");
    const separator = pair.indexOf("=");
    const key = decodeComponent(separator < 0 ? pair : pair.slice(0, separator));
    const value = decodeComponent(separator < 0 ? "" : pair.slice(separator + 1));
    if (!allowed.includes(key)) throw new BadInput(`Unexpected parameter ${JSON.stringify(key)}.`);
    if (out.has(key)) throw new BadInput(`Parameter ${JSON.stringify(key)} was given more than once.`);
    if (encoder.encode(value).length > MAX_FIELD_BYTES || /[\p{Cc}\p{Cs}]/u.test(value)) {
      throw new BadInput(`Parameter ${JSON.stringify(key)} is not valid text.`);
    }
    out.set(key, value);
  }
  return out;
}

export function queryFields(rawQuery: string, allowed: readonly string[] = []): ReadonlyMap<string, string> {
  if (encoder.encode(rawQuery).length > MAX_QUERY_BYTES) throw new BadInput("The query is too long.");
  return decodeFields(rawQuery, allowed);
}

function formContentType(raw: string): boolean {
  const separator = raw.indexOf(";");
  const mediaType = (separator < 0 ? raw : raw.slice(0, separator)).trim().toLowerCase();
  if (mediaType !== "application/x-www-form-urlencoded") return false;
  if (separator < 0) return true;
  let remaining = raw.slice(separator);
  const parameters = new Map<string, string>();
  for (;;) {
    remaining = remaining.slice(1).trim();
    if (remaining === "") return true;
    const match = /^([!#$%&'*+.^_`|~\w-]+)\s*=\s*([!#$%&'*+.^_`|~\w-]+|"(?:[^"\\\r\n]|\\[^\r\n])*")\s*/.exec(remaining);
    if (match === null) return false;
    const name = match[1]!.toLowerCase();
    const encoded = match[2]!;
    const value = encoded.startsWith('"') ? encoded.slice(1, -1).replace(/\\(.)/g, "$1") : encoded;
    const previous = parameters.get(name);
    if (previous !== undefined && previous !== value) return false;
    parameters.set(name, value);
    remaining = remaining.slice(match[0].length);
    if (remaining === "") return true;
    if (!remaining.startsWith(";")) return false;
  }
}

export async function formFields(request: Request, allowed: readonly string[], signal: AbortSignal = request.signal): Promise<ReadonlyMap<string, string>> {
  signal.throwIfAborted();
  if (new URL(request.url).search !== "") throw new BadInput("Form submissions take no query parameters.");
  const contentType = request.headers.get("content-type") ?? "";
  if (!formContentType(contentType)) {
    throw new BadInput("Submit this form from the store page.");
  }
  const chunks: Uint8Array[] = [];
  let size = 0;
  const reader = request.body?.getReader();
  if (reader !== undefined) {
    const aborted = (): void => { void reader.cancel(signal.reason).catch(() => undefined); };
    signal.addEventListener("abort", aborted, { once: true });
    try {
      if (signal.aborted) aborted();
      for (;;) {
        signal.throwIfAborted();
        const result = await reader.read();
        signal.throwIfAborted();
        if (result.done) break;
        size += result.value.length;
        if (size > MAX_FORM_BYTES) {
          await reader.cancel();
          throw new BadInput("The form is too large.");
        }
        chunks.push(result.value);
      }
    } catch (error) {
      if (signal.aborted) throw signal.reason;
      if (error instanceof BadInput) throw error;
      throw new BadInput("The form could not be read.");
    } finally {
      signal.removeEventListener("abort", aborted);
      reader.releaseLock();
    }
  }
  signal.throwIfAborted();
  const body = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) { body.set(chunk, offset); offset += chunk.length; }
  let raw: string;
  try { raw = decoder.decode(body); } catch { throw new BadInput("The form could not be read."); }
  return decodeFields(raw, allowed);
}

export function positiveInt(raw: string, name: string, maximum: number): number {
  const value = Number(raw);
  if (!/^[1-9][0-9]*$/.test(raw) || !Number.isSafeInteger(value) || value > maximum) {
    throw new BadInput(`${name} must be a whole number from 1 to ${maximum}.`);
  }
  return value;
}
export function idParam(raw: string, name: string): bigint {
  try { return parseID(raw); } catch { throw new BadInput(`${name} is not a valid identifier.`); }
}
export function validHandle(raw: string): boolean { return /^[a-z0-9-]{1,200}$/.test(raw); }
export type Availability = "all" | "true" | "false";
export type Sort = "featured" | "title-asc" | "price-asc" | "price-desc";
export interface ListingQuery {
  readonly query: string; readonly vendor: string; readonly available: Availability; readonly sort: Sort; readonly page: number;
}
export function listingQuery(rawQuery: string): ListingQuery {
  const fields = queryFields(rawQuery, ["q", "vendor", "available", "sort", "page"]);
  const query = fields.get("q") ?? "";
  const vendor = fields.get("vendor") ?? "";
  if (encoder.encode(query).length > MAX_QUERY_TEXT_BYTES || encoder.encode(vendor).length > MAX_QUERY_TEXT_BYTES) throw new BadInput("Search text is too long.");
  const available = fields.get("available") || "all";
  if (available !== "all" && available !== "true" && available !== "false") throw new BadInput("Unknown availability filter.");
  const sort = fields.get("sort") || "featured";
  if (sort !== "featured" && sort !== "title-asc" && sort !== "price-asc" && sort !== "price-desc") throw new BadInput("Unknown sort order.");
  return { query, vendor, available, sort, page: fields.has("page") ? positiveInt(fields.get("page")!, "Page", MAX_PAGE) : 1 };
}
