import type { AdminBackend } from "../admin/backend.ts";
import type { CheckoutBlock, CheckoutCartLine, QuoteView } from "../checkout/operations.ts";
import type { HostedSessionCreator } from "../checkout/session_creator.ts";
import type { AttemptState } from "../commerce/attempt.ts";
import { operationIdempotencyKey } from "../commerce/operation.ts";
import { presentedDigestHex } from "../commerce/order_access.ts";
import type { PaymentState } from "../commerce/payment.ts";
import { MaxAddressFieldLength } from "../commerce/shipping.ts";
import type { Fulfillment } from "../commerce/shipping.ts";
import type {
  CheckoutAttemptPage, CheckoutErrors, CheckoutFields, CheckoutLine, CheckoutPage, CheckoutReviewPage, LineStatus, OrderPage, OrderStatus,
} from "../contracts/views.ts";
import { CHECKOUT_ACTIONS, routePath } from "../routes/routes.ts";
import { prepareSessionToken } from "../storefront/cart.ts";
import { BadInput, formFields } from "./decode.ts";

export interface CheckoutPort {
  readonly tenantId: string;
  readonly backend: AdminBackend;
  readonly sessions: HostedSessionCreator;
  readonly checkoutOrigin: string;
  readonly now: () => Date;
  readonly onError: (message: string, error: unknown) => void;
}

export interface Money {
  formatMoney(minor: bigint): string;
}

export type CheckoutOutcome =
  | { readonly kind: "redirect"; readonly location: string }
  | { readonly kind: "page"; readonly entry: "checkout" | "checkout-review" | "checkout-attempt" | "order"; readonly page: CheckoutPage | CheckoutReviewPage | CheckoutAttemptPage | OrderPage; readonly status: number; readonly formAction: string | null }
  | { readonly kind: "not_found" };

const emptyFields: CheckoutFields = { email: "", fulfillment: "ship", recipient: "", line1: "", line2: "", city: "", region: "", postalCode: "" };
const noErrors: CheckoutErrors = { email: null, recipient: null, line1: null, line2: null, city: null, region: null, postalCode: null };

const fieldLabels: Readonly<Record<keyof CheckoutErrors, string>> = {
  email: "email address", recipient: "recipient name", line1: "address", line2: "address line 2", city: "city", region: "state", postalCode: "ZIP code",
};

function hex(bytes: Uint8Array): string {
  return [...bytes].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

export function newRef(): string {
  return hex(crypto.getRandomValues(new Uint8Array(16)));
}

function seconds(now: Date): number {
  return Math.floor(now.getTime() / 1000);
}

function lineViews(lines: readonly CheckoutCartLine[], money: Money): readonly CheckoutLine[] {
  return lines.map((line) => ({
    productTitle: line.title,
    variantLabel: line.variantLabel,
    quantity: Number(line.quantity),
    unitPrice: money.formatMoney(line.unitPriceMinor),
    lineTotal: line.status === "available" ? money.formatMoney(line.unitPriceMinor * line.quantity) : null,
    status: line.status satisfies LineStatus,
  }));
}

function parseForm(fields: ReadonlyMap<string, string>): { readonly echo: CheckoutFields; readonly email: string; readonly fulfillment: Fulfillment } {
  const value = (name: string): string => (fields.get(name) ?? "").trim();
  const choice = fields.get("fulfillment") ?? "ship";
  if (choice !== "ship" && choice !== "pickup") throw new BadInput("Choose delivery or pickup.");
  const echo: CheckoutFields = {
    email: value("email"), fulfillment: choice, recipient: value("recipient"), line1: value("line1"), line2: value("line2"),
    city: value("city"), region: value("region").toUpperCase(), postalCode: value("postal_code"),
  };
  const fulfillment: Fulfillment = choice === "pickup"
    ? { kind: "pickup" }
    : { kind: "ship", address: { recipient: echo.recipient, line1: echo.line1, line2: echo.line2 === "" ? null : echo.line2, city: echo.city, region: echo.region, postalCode: echo.postalCode, country: "US" } };
  return { echo, email: echo.email, fulfillment };
}

function problemText(field: keyof CheckoutErrors, problem: string): string {
  if (problem === "required") return `Enter a ${fieldLabels[field]}.`;
  if (problem === "too_long") return `Use at most ${MaxAddressFieldLength} characters.`;
  if (problem === "unsupported") return "We do not ship to that state.";
  if (field === "email") return "Enter a valid email address.";
  return "Enter a ZIP code like 12345 or 12345-6789.";
}

const errorKeys: Readonly<Record<string, keyof CheckoutErrors>> = {
  email: "email", recipient: "recipient", line1: "line1", line2: "line2", city: "city", region: "region", postalCode: "postalCode",
};

function blockPresentation(block: CheckoutBlock, money: Money): { readonly problem: string; readonly errors: CheckoutErrors } {
  const errors: { -readonly [K in keyof CheckoutErrors]: string | null } = { ...noErrors };
  for (const entry of block.problems) {
    const key = errorKeys[entry.field];
    if (key !== undefined && errors[key] === null) errors[key] = problemText(key, entry.problem);
  }
  switch (block.reason) {
    case "address_invalid": return { problem: "Check the highlighted address fields.", errors };
    case "contact_invalid": return { problem: "Check your email address.", errors };
    case "destination_unsupported":
    case "tax_region_unsupported": return { problem: `We do not ship to ${block.region ?? "that destination"} yet.`, errors: { ...errors, region: "We do not ship to that state." } };
    case "pickup_unavailable": return { problem: "This shop does not offer local pickup.", errors };
    case "line_unavailable": return { problem: `${block.title ?? "An item"} is no longer available. Remove it from your cart to continue.`, errors };
    case "amount_not_purchasable":
      return { problem: block.amountProblem === "below_minimum" ? `Orders must total at least ${money.formatMoney(50n)}.` : block.amountProblem === "above_maximum" ? "This order is too large to pay for online." : "This shop's currency cannot be used at checkout yet.", errors };
    case "amount_out_of_range": return { problem: "This order is too large to calculate exactly.", errors };
    case "invalid_line": return { problem: "A cart line has an invalid quantity or price.", errors };
    case "empty_cart": return { problem: "Your cart is empty.", errors };
    default: return { problem: "Checkout is not available yet because this shop has not finished setting up taxes and shipping.", errors };
  }
}

function percent(ratePpm: bigint): string {
  return `${Number(ratePpm) / 10000}%`;
}

interface ReviewSource {
  readonly quote: QuoteView;
  readonly status: CheckoutReviewPage["status"];
  readonly attemptRef: string | null;
}

function reviewPage(view: ReviewSource, money: Money, problem: string | null): CheckoutReviewPage {
  const quote = view.quote;
  const taxByRate = new Map<bigint, bigint>();
  for (const tax of quote.taxLines) if (tax.taxMinor > 0n) taxByRate.set(tax.ratePpm, (taxByRate.get(tax.ratePpm) ?? 0n) + tax.taxMinor);
  const address = quote.fulfillment.kind === "ship" ? quote.fulfillment.address : null;
  return {
    status: view.status,
    quoteRef: quote.ref,
    lines: quote.lines.map((line) => ({
      productTitle: line.title, variantLabel: line.variantLabel === "" ? null : line.variantLabel, quantity: Number(line.quantity),
      unitPrice: money.formatMoney(line.unitPriceMinor), lineTotal: money.formatMoney(line.lineTotalMinor), status: "available",
    })),
    email: quote.email,
    fulfillment: quote.fulfillment.kind,
    shipTo: address === null ? [] : [address.recipient, address.line1, ...(address.line2 === null ? [] : [address.line2]), `${address.city}, ${address.region} ${address.postalCode}`],
    shippingLabel: quote.fulfillment.kind === "pickup" ? "Local pickup" : quote.shippingFreeByThreshold ? `Shipping to ${quote.shippingZone ?? ""} (free)` : `Shipping to ${quote.shippingZone ?? ""}`,
    merchandise: money.formatMoney(quote.merchandiseMinor),
    shipping: money.formatMoney(quote.shippingMinor),
    taxes: [...taxByRate].map(([rate, amount]) => ({ label: `Tax at ${percent(rate)}`, amount: money.formatMoney(amount) })),
    tax: money.formatMoney(quote.taxMinor),
    total: money.formatMoney(quote.totalMinor),
    expires: `${new Date(Number(quote.expiresAt) * 1000).toISOString().slice(11, 16)} UTC`,
    problem,
    attemptUrl: view.attemptRef === null ? null : routePath("checkout-attempt", [view.attemptRef]),
  };
}

const attemptMessages: Readonly<Record<AttemptState, { readonly status: CheckoutAttemptPage["status"]; readonly message: string }>> = {
  quoted: { status: "pending", message: "Your order is not placed yet." },
  accepted: { status: "pending", message: "We are preparing your secure payment page. Refresh this page in a moment." },
  handed_off: { status: "pending", message: "Waiting for your payment to be confirmed. If you have paid, refresh this page in a moment." },
  authorized: { status: "success", message: "Thank you. Your payment is authorized and the shop is preparing your order. We emailed you a private link to your order." },
  expired: { status: "failure", message: "This payment window expired and nothing was charged. Your items are no longer held." },
  superseded: { status: "failure", message: "You started a newer checkout, so this one was replaced. Nothing was charged for it." },
  voided_late: { status: "failure", message: "The payment arrived after the items were released, so it was cancelled and nothing was charged. We emailed you about it." },
  blocked: { status: "failure", message: "This payment needs review by the shop. Nothing is lost; the shop will follow up." },
};

const orderMessages: Readonly<Record<PaymentState, { readonly status: OrderStatus; readonly message: string }>> = {
  authorized: { status: "placed", message: "Your order is placed. Your payment is authorized and is being completed." },
  in_review: { status: "placed", message: "Your order is placed. The shop is confirming your payment before it is completed." },
  capture_pending: { status: "placed", message: "Your order is placed. Your payment is being completed." },
  capture_unknown: { status: "placed", message: "Your order is placed. Your payment is being completed." },
  captured: { status: "paid", message: "Your order is paid. The shop is preparing it." },
  void_unknown: { status: "placed", message: "Your order needs attention from the shop. Nothing more will be charged." },
  voided: { status: "canceled", message: "The payment for this order was cancelled and nothing was charged. The shop will contact you." },
};

export class Checkout {
  readonly #port: CheckoutPort;

  constructor(port: CheckoutPort) {
    this.#port = port;
  }

  get checkoutOrigin(): string { return this.#port.checkoutOrigin; }

  async #digest(token: string | null): Promise<string | null> {
    const bytes = await prepareSessionToken(token);
    return bytes === null ? null : hex(bytes);
  }

  async #formPage(digest: string | null, money: Money, fields: CheckoutFields, errors: CheckoutErrors, problem: string | null, status: number): Promise<CheckoutOutcome> {
    const form = digest === null
      ? null
      : await this.#port.backend.query({ kind: "checkout.form", sessionDigest: digest, nowSeconds: seconds(this.#port.now()) });
    const lines = form === null ? [] : lineViews(form.lines, money);
    const buyable = form === null ? [] : form.lines.filter((line) => line.status === "available");
    const page: CheckoutPage = {
      lines,
      itemCount: buyable.reduce((sum, line) => sum + Number(line.quantity), 0),
      subtotal: buyable.length === 0 ? null : money.formatMoney(buyable.reduce((sum, line) => sum + line.unitPriceMinor * line.quantity, 0n)),
      fields,
      errors,
      problem: problem ?? (form?.paused === true ? "Checkout is paused right now. Please try again later." : form !== null && !form.ready ? "Checkout is not available yet because this shop has not finished setting up taxes and shipping." : null),
      available: form !== null && !form.paused && form.ready && buyable.length > 0,
      offersPickup: form?.offersPickup ?? false,
      regions: form?.regions ?? [],
    };
    return { kind: "page", entry: "checkout", page, status, formAction: null };
  }

  async form(token: string | null, money: Money): Promise<CheckoutOutcome> {
    return await this.#formPage(await this.#digest(token), money, emptyFields, noErrors, null, 200);
  }

  async review(request: Request, token: string | null, money: Money, signal: AbortSignal): Promise<CheckoutOutcome> {
    const fields = await formFields(request, CHECKOUT_ACTIONS.review.fields, signal);
    const parsed = parseForm(fields);
    const digest = await this.#digest(token);
    if (digest === null) return { kind: "redirect", location: routePath("cart") };
    const result = await this.#port.backend.command({
      kind: "checkout.quote", sessionDigest: digest, quoteRef: newRef(), email: parsed.email, fulfillment: parsed.fulfillment, nowSeconds: seconds(this.#port.now()),
    });
    if (result.outcome === "blocked") {
      const shown = blockPresentation(result.block, money);
      return await this.#formPage(digest, money, parsed.echo, shown.errors, shown.problem, 422);
    }
    if (result.outcome === "quoted") return { kind: "redirect", location: routePath("checkout-quote", [result.quoteRef]) };
    if (result.outcome === "paused") return await this.#formPage(digest, money, parsed.echo, noErrors, "Checkout is paused right now. Please try again later.", 409);
    return { kind: "redirect", location: routePath("cart") };
  }

  async quote(ref: string, token: string | null, money: Money): Promise<CheckoutOutcome> {
    const digest = await this.#digest(token);
    if (digest === null) return { kind: "not_found" };
    return await this.#quotePage(ref, digest, money, null, 200);
  }

  async #quotePage(ref: string, digest: string, money: Money, problem: string | null, status: number): Promise<CheckoutOutcome> {
    const result = await this.#port.backend.query({ kind: "checkout.quote_view", sessionDigest: digest, quoteRef: ref, nowSeconds: seconds(this.#port.now()) });
    if (result.view === null) return { kind: "not_found" };
    const view = result.view;
    const message = problem ?? (view.status === "expired" ? "This quote expired. Review the order again for a new total." : view.status === "changed" ? "Your cart or its prices changed after this review. Review the order again to see the new total." : null);
    return { kind: "page", entry: "checkout-review", page: reviewPage(view, money, message), status, formAction: view.status === "open" ? this.#port.checkoutOrigin : null };
  }

  async refresh(ref: string, token: string | null, money: Money): Promise<CheckoutOutcome> {
    const digest = await this.#digest(token);
    if (digest === null) return { kind: "not_found" };
    const result = await this.#port.backend.command({ kind: "checkout.requote", sessionDigest: digest, fromQuoteRef: ref, quoteRef: newRef(), nowSeconds: seconds(this.#port.now()) });
    if (result.outcome === "blocked") return await this.#quotePage(ref, digest, money, blockPresentation(result.block, money).problem, 422);
    if (result.outcome === "quoted") return { kind: "redirect", location: routePath("checkout-quote", [result.quoteRef]) };
    if (result.outcome === "not_found") return { kind: "not_found" };
    if (result.outcome === "paused") return await this.#quotePage(ref, digest, money, "Checkout is paused right now. Please try again later.", 409);
    return { kind: "redirect", location: routePath("cart") };
  }

  async accept(ref: string, token: string | null, money: Money): Promise<CheckoutOutcome> {
    const digest = await this.#digest(token);
    if (digest === null) return { kind: "not_found" };
    const acceptedAt = seconds(this.#port.now());
    const result = await this.#port.backend.command({ kind: "checkout.accept", tenantId: this.#port.tenantId, sessionDigest: digest, quoteRef: ref, attemptRef: newRef(), nowSeconds: acceptedAt });
    switch (result.outcome) {
      case "accepted": return await this.#handoff(result, acceptedAt);
      case "not_found": return { kind: "not_found" };
      case "paused": return await this.#quotePage(ref, digest, money, "Checkout is paused right now. Please try again later.", 409);
      case "expired": return await this.#quotePage(ref, digest, money, "This quote expired. Review the order again for a new total.", 409);
      case "changed": return await this.#quotePage(ref, digest, money, "Your cart or its prices changed after this review. Review the order again to see the new total.", 409);
      case "holds_full": return await this.#quotePage(ref, digest, money, "Many shoppers are checking out right now. Please try again in a few minutes.", 409);
      case "insufficient_stock": return await this.#quotePage(ref, digest, money, `${result.title} is no longer available in the quantity you chose.`, 409);
      case "blocked": return await this.#quotePage(ref, digest, money, blockPresentation(result.block, money).problem, 422);
    }
  }

  async #handoff(accepted: { readonly attemptRef: string; readonly state: AttemptState; readonly replay: boolean; readonly sessionUrl: string | null; readonly quote: QuoteView }, acceptedAt: number): Promise<CheckoutOutcome> {
    const attemptPage: CheckoutOutcome = { kind: "redirect", location: routePath("checkout-attempt", [accepted.attemptRef]) };
    if (accepted.sessionUrl !== null) return accepted.state === "handed_off" ? { kind: "redirect", location: this.#trusted(accepted.sessionUrl) } : attemptPage;
    if (accepted.replay) return attemptPage;
    try {
      const session = await this.#port.sessions.create({
        attemptRef: accepted.attemptRef, idempotencyKey: operationIdempotencyKey(this.#port.tenantId, "create_session", accepted.attemptRef), quote: accepted.quote, acceptedAtSeconds: acceptedAt,
      });
      const recorded = await this.#port.backend.command({
        kind: "checkout.session.record", attemptRef: accepted.attemptRef, sessionId: session.sessionId, sessionUrl: this.#trusted(session.url), sessionExpiresAt: session.expiresAtSeconds, nowSeconds: seconds(this.#port.now()),
      });
      return recorded.outcome === "handed_off" ? { kind: "redirect", location: this.#trusted(session.url) } : attemptPage;
    } catch (error) {
      this.#port.onError("checkout session creation failed", error);
      return attemptPage;
    }
  }

  #trusted(url: string): string {
    if (new URL(url).origin !== this.#port.checkoutOrigin) throw new Error("checkout: the hosted session URL is outside the configured Checkout origin");
    return url;
  }

  async attempt(ref: string, money: Money): Promise<CheckoutOutcome> {
    const result = await this.#port.backend.query({ kind: "checkout.attempt_view", attemptRef: ref });
    if (result.view === null) return { kind: "not_found" };
    const view = result.view;
    const presentation = attemptMessages[view.state];
    const page: CheckoutAttemptPage = {
      status: presentation.status,
      message: presentation.message,
      lines: view.lines.map((line) => ({
        productTitle: line.title, variantLabel: line.variantLabel === "" ? null : line.variantLabel, quantity: Number(line.quantity),
        unitPrice: money.formatMoney(line.unitPriceMinor), lineTotal: money.formatMoney(line.lineTotalMinor), status: "available",
      })),
      total: money.formatMoney(view.totalMinor),
      continueUrl: view.state === "handed_off" && view.sessionUrl !== null ? this.#trusted(view.sessionUrl) : null,
      orderUrl: view.orderNumber === null ? null : routePath("order-lookup"),
    };
    return { kind: "page", entry: "checkout-attempt", page, status: 200, formAction: null };
  }

  async access(token: string): Promise<{ readonly kind: "granted"; readonly number: bigint } | { readonly kind: "not_found" }> {
    const accessDigest = await presentedDigestHex(token);
    if (accessDigest === null) return { kind: "not_found" };
    const { number } = await this.#port.backend.query({ kind: "order.access", accessDigest, nowSeconds: seconds(this.#port.now()) });
    return number === null ? { kind: "not_found" } : { kind: "granted", number };
  }

  async lookup(fields: ReadonlyMap<string, string>): Promise<"requested" | "invalid"> {
    const rawNumber = (fields.get("order_number") ?? "").trim().replace(/^#/, "");
    const email = (fields.get("email") ?? "").trim();
    if (!/^[1-9][0-9]{0,17}$/.test(rawNumber) || email.length < 3 || email.length > 254 || !email.includes("@")) return "invalid";
    await this.#port.backend.command({ kind: "order.lookup", number: BigInt(rawNumber), email, nowSeconds: seconds(this.#port.now()) });
    return "requested";
  }

  async order(number: bigint, token: string | null, money: Money): Promise<CheckoutOutcome> {
    const accessDigest = token === null ? null : await presentedDigestHex(token);
    if (accessDigest === null) return { kind: "not_found" };
    const { order } = await this.#port.backend.query({ kind: "order.status", accessDigest, number, nowSeconds: seconds(this.#port.now()) });
    if (order === null) return { kind: "not_found" };
    const presentation = orderMessages[order.paymentState];
    const page: OrderPage = {
      number: order.number.toString(),
      status: presentation.status,
      message: presentation.message,
      lines: order.lines.map((line) => ({
        productTitle: line.title, variantLabel: line.variantLabel === "" ? null : line.variantLabel, quantity: Number(line.quantity),
        unitPrice: money.formatMoney(line.unitPriceMinor), lineTotal: money.formatMoney(line.lineTotalMinor), status: "available",
      })),
      total: money.formatMoney(order.totalMinor),
      placed: `${new Date(Number(order.placedAt) * 1000).toISOString().slice(0, 16).replace("T", " ")} UTC`,
      destination: order.destination,
    };
    return { kind: "page", entry: "order", page, status: 200, formAction: null };
  }
}
