import { digestBytes } from "../admin/guard.ts";
import { all, audit, get, run, stock, type Program } from "../admin/program.ts";
import { indexOrderEmail } from "../admin/orders_search.ts";
import type { AdminQueryRow } from "../admin/queries.ts";
import { quoteView, storedQuote } from "../checkout/program.ts";
import type { CancellationReason } from "../stripe/index.ts";
import { AttemptMachine, holdIsPinned, type AttemptState } from "./attempt.ts";
import { queueConfirmation, queueLateVoid } from "./email_program.ts";
import { canTransition } from "./machine.ts";
import { canTransitionOperation, operationIdempotencyKey, type ProviderOperationKind, type ProviderOperationState } from "./operation.ts";
import { observePayment, paymentPath, verifyAuthorization, type IntentFacts, type PaymentState } from "./payment.ts";
import type {
  AttemptPaymentView, AuthorizeOutcome, OperationView, OrderExceptionKind, PaymentCommand, PaymentCommandResult, PaymentQuery, PaymentQueryResult,
} from "./payment_operations.ts";

export const PaymentActor = "payments";
export const CaptureKind = "capture";
export const CancelIntentKind = "cancel_pi";
export const HoldExpiryKind = "hold_expiry";
export const PaymentReconcileKind = "periodic_payment_reconcile";
export const captureKey = (paymentIntentId: string): string => `${CaptureKind}:${paymentIntentId}`;
export const cancelIntentKey = (paymentIntentId: string): string => `${CancelIntentKind}:${paymentIntentId}`;
export const holdExpiryKey = (attemptRef: string): string => `${HoldExpiryKind}:${attemptRef}`;
export const MaxSweepObjects = 100;
export const SweepSlackSeconds = 600;

type Of<C extends PaymentCommand["kind"]> = Extract<PaymentCommand, { readonly kind: C }>;
type ResultOf<C extends PaymentCommand["kind"]> = Extract<PaymentCommandResult, { readonly kind: C }>;
type AttemptRow = AdminQueryRow<"GetPaymentAttempt">;
type OperationRow = AdminQueryRow<"GetOperation">;
type PaymentRow = AdminQueryRow<"GetPaymentByIntent">;

function operationView(row: OperationRow): OperationView {
  return { state: row.state as ProviderOperationState, key: row.idempotency_key, attempts: row.attempts, providerObjectId: row.provider_object_id, createdAt: Number(row.created_at) };
}

function* operation(kind: ProviderOperationKind, subject: string): Program<OperationRow | null> {
  return yield* get("GetOperation", [kind, subject]);
}

export function* insertOperation(tenantId: string, kind: ProviderOperationKind, subject: string, state: "pending" | "in_flight", now: bigint): Program<void> {
  yield* run("InsertOperation", [kind, subject, operationIdempotencyKey(tenantId, kind, subject), state, state === "in_flight" ? 1n : 0n, now, now]);
}

export function* settleRow(row: OperationRow, to: ProviderOperationState, providerObjectId: string | null, error: string | null, now: bigint): Program<boolean> {
  if (!canTransitionOperation(row.state as ProviderOperationState, to)) return false;
  return (yield* run("SetOperationState", [to, row.attempts, providerObjectId, error, now, row.id, row.state])) > 0n;
}

function* requireAttempt(row: AttemptRow, to: AttemptState, now: bigint): Program<void> {
  if (!(yield* moveAttempt(row, to, now))) throw new Error(`payments: attempt ${row.ref} cannot move from ${row.state} to ${to}`);
}

function* moveAttempt(row: AttemptRow, to: AttemptState, now: bigint): Program<boolean> {
  const from = row.state as AttemptState;
  if (from === to) return true;
  if (!canTransition(AttemptMachine, from, to)) return false;
  return (yield* run("SetAttemptState", [to, now, row.id, from])) > 0n;
}

function* movePayment(row: PaymentRow, to: PaymentState, capturedMinor: bigint, reviewId: string | null, now: bigint): Program<boolean> {
  const from = row.state as PaymentState;
  if (from === to && reviewId === null) return false;
  if (from !== to && paymentPath(from, to) === null) return false;
  return (yield* run("SetPaymentState", [to, capturedMinor, reviewId, now, row.id, from])) > 0n;
}

export function* exception(
  attemptId: bigint, orderId: bigint | null, kind: OrderExceptionKind, objectId: string, open: boolean, detail: string, now: bigint,
): Program<void> {
  yield* run("UpsertOrderException", [attemptId, orderId, kind, objectId, open ? "open" : "closed", detail.slice(0, 500), now, open ? null : now, now]);
  if (orderId !== null) {
    yield* audit({ actor: PaymentActor, action: "payment.exception", entityKind: "order", entityId: orderId.toString(), entityRevision: null, summary: `${kind} ${open ? "open" : "closed"}: ${detail}`.slice(0, 1000) }, now);
  }
}

function* releaseHolds(row: AttemptRow, now: bigint): Program<boolean> {
  if (!holdIsPinned(row.state as AttemptState)) return false;
  const reservations = yield* all("ListAttemptReservations", [row.id]);
  const tracked = reservations.filter((reservation) => reservation.state === "held" && reservation.tracked === 1n);
  if (tracked.length > 0) {
    const released = yield* stock(tracked.map((reservation) => ({ kind: "release_hold", variantId: reservation.variant_id, quantity: reservation.quantity })), { nowSeconds: now, actor: PaymentActor });
    if (released.outcome === "rejected") throw new Error(`payments: releasing the holds of attempt ${row.ref} was rejected (${released.rejection})`);
  }
  yield* run("SetReservationsState", ["released", now, row.id, "held"]);
  return yield* moveAttempt(row, "expired", now);
}

function* allocate(row: AttemptRow, late: boolean, now: bigint): Program<boolean> {
  const from = late ? "released" : "held";
  const reservations = (yield* all("ListAttemptReservations", [row.id])).filter((reservation) => reservation.state === from);
  const tracked = reservations.filter((reservation) => reservation.tracked === 1n);
  if (tracked.length > 0) {
    const allocated = yield* stock(tracked.map((reservation) => ({ kind: late ? "allocate_late" : "allocate", variantId: reservation.variant_id, quantity: reservation.quantity })), { nowSeconds: now, actor: PaymentActor });
    if (allocated.outcome === "rejected") {
      if (late && allocated.rejection === "insufficient_stock") return false;
      throw new Error(`payments: allocating attempt ${row.ref} was rejected (${allocated.rejection})`);
    }
  }
  yield* run("SetReservationsState", ["allocated", now, row.id, from]);
  return true;
}

export function* scheduleCancel(tenantId: string, intentId: string, attemptRef: string, now: bigint, reason: CancellationReason = "abandoned"): Program<void> {
  yield* insertOperation(tenantId, "cancel_pi", intentId, "pending", now);
  yield* run("ScheduleWork", [CancelIntentKind, cancelIntentKey(intentId), JSON.stringify({ intent: intentId, attempt: attemptRef, reason }), now, now, now]);
}

function* placeOrder(command: Of<"payment.authorize">, row: AttemptRow, allocation: "hold" | "late", now: bigint): Program<bigint> {
  const intent = command.intent;
  yield* run("InsertOrder", [row.id, allocation, now, row.quote_id]);
  yield* run("InsertOrderLines", [row.id]);
  yield* run("InsertPayment", [intent.id, intent.reviewOpen ? "in_review" : "authorized", intent.reviewId, now, now, row.id]);
  yield* insertOperation(command.tenantId, "capture", intent.id, "pending", now);
  if (!intent.reviewOpen && intent.status === "requires_capture") yield* run("ScheduleWork", [CaptureKind, captureKey(intent.id), JSON.stringify({ intent: intent.id }), now, now, now]);
  yield* requireAttempt(row, "authorized", now);
  const order = yield* get("GetOrderForAttempt", [row.id]);
  if (order === null) throw new Error(`payments: the order for attempt ${row.ref} was not written`);
  yield* indexOrderEmail(order.id);
  yield* queueConfirmation(order.id, now);
  yield* audit({ actor: PaymentActor, action: "order.place", entityKind: "order", entityId: order.id.toString(), entityRevision: null, summary: `order ${order.number} placed from attempt ${row.ref} (${allocation === "late" ? "late allocation" : "held stock"})` }, now);
  if (intent.reviewOpen && intent.reviewId !== null) yield* exception(row.id, order.id, "review", intent.reviewId, true, "Radar review is open; capture waits for approval", now);
  return order.number;
}

export function* voidLateAuthorization(tenantId: string, row: AttemptRow, intentId: string, now: bigint): Program<void> {
  yield* requireAttempt(row, "voided_late", now);
  yield* scheduleCancel(tenantId, intentId, row.ref, now);
  yield* queueLateVoid(row.id, now);
}

function* authorize(command: Of<"payment.authorize">): Program<ResultOf<"payment.authorize">> {
  const now = BigInt(command.nowSeconds);
  const result = (outcome: AuthorizeOutcome, orderNumber: bigint | null = null): ResultOf<"payment.authorize"> => ({ kind: "payment.authorize", outcome, orderNumber });
  const row = yield* get("GetPaymentAttempt", [command.attemptRef]);
  if (row === null) return result("not_found");
  const intent: IntentFacts = command.intent;
  const verdict = verifyAuthorization(intent, { tenantId: command.tenantId, attemptRef: row.ref, totalMinor: row.total_minor, currency: row.currency_code, livemode: command.livemode });
  if (verdict.kind === "foreign" || verdict.kind === "not_yet" || verdict.kind === "canceled") return result(verdict.kind);
  const existing = yield* get("GetOrderForAttempt", [row.id]);
  if (existing !== null) {
    if (existing.payment_intent_id === intent.id) return result("already", existing.number);
    if (intent.status === "requires_capture") yield* scheduleCancel(command.tenantId, intent.id, row.ref, now);
    yield* exception(row.id, existing.id, "payment_mismatch", intent.id, true, "a second PaymentIntent for an attempt that already has an order; it is canceled and never captured", now);
    return result("mismatch", existing.number);
  }
  if (verdict.kind === "mismatch") {
    if (verdict.cancelable) yield* scheduleCancel(command.tenantId, intent.id, row.ref, now);
    yield* exception(row.id, null, "payment_mismatch", intent.id, true,
      `PaymentIntent failed verification (${verdict.mismatches.join(", ")}); ${verdict.cancelable ? "the authorization is canceled" : "it cannot be canceled automatically and needs review in the Stripe dashboard"}`, now);
    yield* moveAttempt(row, "blocked", now);
    return result("mismatch");
  }
  const state = row.state as AttemptState;
  if (state === "voided_late") {
    yield* scheduleCancel(command.tenantId, intent.id, row.ref, now);
    return result("voided_late");
  }
  if (state === "authorized" || state === "quoted") throw new Error(`payments: attempt ${row.ref} is ${state} without an order`);
  if (holdIsPinned(state)) {
    yield* allocate(row, false, now);
    return result("placed", yield* placeVerified(command, row, "hold", verdict.captured, now));
  }
  if (yield* allocate(row, true, now)) return result("placed_late", yield* placeVerified(command, row, "late", verdict.captured, now));
  if (verdict.captured) {
    yield* exception(row.id, null, "unmapped_state", intent.id, true, "the payment was captured at Stripe after its stock was released and no stock is left; refund it in the Stripe dashboard", now);
    yield* requireAttempt(row, "blocked", now);
    return result("mismatch");
  }
  yield* voidLateAuthorization(command.tenantId, row, intent.id, now);
  return result("voided_late");
}

function* placeVerified(command: Of<"payment.authorize">, row: AttemptRow, allocation: "hold" | "late", captured: boolean, now: bigint): Program<bigint> {
  const number = yield* placeOrder(command, row, allocation, now);
  if (captured) yield* observe({ kind: "payment.observe", intent: command.intent, nowSeconds: command.nowSeconds });
  return number;
}

function* beginOperation(command: Of<"payment.op.begin">): Program<ResultOf<"payment.op.begin">> {
  const now = BigInt(command.nowSeconds);
  const row = yield* operation(command.opKind, command.subject);
  if (row === null) {
    yield* insertOperation(command.tenantId, command.opKind, command.subject, "in_flight", now);
    const inserted = yield* operation(command.opKind, command.subject);
    if (inserted === null) throw new Error("payments: the operation row was not written");
    return { kind: "payment.op.begin", outcome: "started", previous: null, operation: operationView(inserted) };
  }
  const state = row.state as ProviderOperationState;
  if (state === "succeeded" || state === "blocked") return { kind: "payment.op.begin", outcome: state, operation: operationView(row) };
  yield* run("SetOperationState", ["in_flight", row.attempts + 1n, null, null, now, row.id, state]);
  return { kind: "payment.op.begin", outcome: "started", previous: state, operation: { ...operationView(row), state: "in_flight", attempts: row.attempts + 1n } };
}

function* settleOperation(command: Of<"payment.op.settle">): Program<ResultOf<"payment.op.settle">> {
  const now = BigInt(command.nowSeconds);
  const row = yield* operation(command.opKind, command.subject);
  if (row === null) return { kind: "payment.op.settle", changed: false };
  const changed = yield* settleRow(row, command.to, command.providerObjectId, command.error, now);
  if (!changed) return { kind: "payment.op.settle", changed };
  const detail = `${command.opKind} needs operator review: ${command.error ?? "no detail"}`;
  if (command.opKind === "capture") {
    const payment = yield* get("GetPaymentByIntent", [command.subject]);
    if (payment !== null) {
      if (command.to === "unknown") yield* movePayment(payment, "capture_unknown", 0n, null, now);
      if (command.to === "failed" || command.to === "blocked") yield* movePayment(payment, "authorized", 0n, null, now);
      if (command.to === "blocked") yield* exception(payment.attempt_id, payment.order_id, "operation_blocked", `${command.opKind}:${command.subject}`, true, detail, now);
    }
  } else if (command.to === "blocked" && command.attemptRef !== null) {
    const attempt = yield* get("GetPaymentAttempt", [command.attemptRef]);
    if (attempt !== null) {
      const order = yield* get("GetOrderForAttempt", [attempt.id]);
      yield* exception(attempt.id, order?.id ?? null, "operation_blocked", `${command.opKind}:${command.subject}`, true, detail, now);
      if (command.opKind !== "cancel_pi") yield* moveAttempt(attempt, "blocked", now);
    }
  }
  if (command.opKind === "cancel_pi" && command.to === "succeeded" && command.attemptRef !== null) {
    const attempt = yield* get("GetPaymentAttempt", [command.attemptRef]);
    if (attempt !== null && (yield* get("GetOrderForAttempt", [attempt.id])) === null) yield* releaseHolds(attempt, now);
  }
  return { kind: "payment.op.settle", changed };
}

function* beginCapture(command: Of<"payment.capture.begin">): Program<ResultOf<"payment.capture.begin">> {
  const now = BigInt(command.nowSeconds);
  const payment = yield* get("GetPaymentByIntent", [command.paymentIntentId]);
  if (payment === null) return { kind: "payment.capture.begin", outcome: "not_found" };
  const state = payment.state as PaymentState;
  if (state === "captured" || state === "voided" || state === "void_unknown") return { kind: "payment.capture.begin", outcome: "done" };
  if (state === "in_review") return { kind: "payment.capture.begin", outcome: "review" };
  let row = yield* operation("capture", command.paymentIntentId);
  if (row === null) {
    yield* insertOperation(command.tenantId, "capture", command.paymentIntentId, "pending", now);
    row = yield* operation("capture", command.paymentIntentId);
    if (row === null) throw new Error("payments: the capture operation row was not written");
  }
  const previous = row.state as ProviderOperationState;
  if (previous === "succeeded") return { kind: "payment.capture.begin", outcome: "done" };
  if (previous === "blocked") return { kind: "payment.capture.begin", outcome: "blocked" };
  yield* run("SetOperationState", ["in_flight", row.attempts + 1n, null, null, now, row.id, previous]);
  if (state !== "capture_pending") yield* movePayment(payment, "capture_pending", 0n, null, now);
  return { kind: "payment.capture.begin", outcome: "capture", previous, key: row.idempotency_key, amountMinor: payment.amount_authorized_minor };
}

function* observe(command: Of<"payment.observe">): Program<ResultOf<"payment.observe">> {
  const now = BigInt(command.nowSeconds);
  const intent = command.intent;
  const payment = yield* get("GetPaymentByIntent", [intent.id]);
  if (payment === null) return { kind: "payment.observe", outcome: "not_found", state: null };
  const state = payment.state as PaymentState;
  const observed = observePayment(intent);
  const capture = yield* operation("capture", intent.id);
  switch (observed.kind) {
    case "captured": {
      if (state !== "captured" && (yield* movePayment(payment, "captured", observed.amountMinor, null, now))) {
        if (capture !== null && capture.state !== "failed") yield* settleRow(capture, "succeeded", intent.id, null, now);
        yield* audit({ actor: PaymentActor, action: "payment.capture", entityKind: "order", entityId: payment.order_id.toString(), entityRevision: null, summary: `captured ${observed.amountMinor} ${payment.currency_code} on order ${payment.number}` }, now);
      }
      return { kind: "payment.observe", outcome: "captured", state: "captured" };
    }
    case "voided": {
      if (state !== "voided" && (yield* movePayment(payment, "voided", 0n, null, now))) {
        if (capture !== null && capture.state !== "failed") yield* settleRow(capture, "failed", null, "the PaymentIntent was canceled before capture", now);
        yield* audit({ actor: PaymentActor, action: "payment.void", entityKind: "order", entityId: payment.order_id.toString(), entityRevision: null, summary: `authorization for order ${payment.number} canceled at Stripe` }, now);
        const order = yield* get("GetOrderDetail", [payment.number]);
        if (order?.fulfillment_status !== "canceled") {
          yield* exception(payment.attempt_id, payment.order_id, "payment_canceled", intent.id, true, "the authorization was canceled at Stripe before capture; the order needs cancellation", now);
        }
      }
      return { kind: "payment.observe", outcome: "voided", state: "voided" };
    }
    case "capturable": {
      if (intent.reviewOpen && state === "authorized") {
        yield* movePayment(payment, "in_review", 0n, intent.reviewId, now);
        if (intent.reviewId !== null) yield* exception(payment.attempt_id, payment.order_id, "review", intent.reviewId, true, "Radar review is open; capture waits for approval", now);
        return { kind: "payment.observe", outcome: "capturable", state: "in_review" };
      }
      return { kind: "payment.observe", outcome: "capturable", state };
    }
    case "unmapped": {
      yield* exception(payment.attempt_id, payment.order_id, "unmapped_state", intent.id, true, `PaymentIntent status ${intent.status} has no payment transition`, now);
      return { kind: "payment.observe", outcome: "unmapped", state };
    }
  }
}

function* review(command: Of<"payment.review">): Program<ResultOf<"payment.review">> {
  const now = BigInt(command.nowSeconds);
  const payment = yield* get("GetPaymentByIntent", [command.paymentIntentId]);
  if (payment === null) return { kind: "payment.review", outcome: "not_found" };
  const state = payment.state as PaymentState;
  if (command.open) {
    if (state === "authorized") yield* movePayment(payment, "in_review", 0n, command.reviewId, now);
    yield* exception(payment.attempt_id, payment.order_id, "review", command.reviewId, true, "Radar review is open; capture waits for approval", now);
    return { kind: "payment.review", outcome: "in_review" };
  }
  if (command.closedReason === "approved") {
    yield* exception(payment.attempt_id, payment.order_id, "review", command.reviewId, false, "Radar review approved", now);
    if (state === "in_review" && (yield* movePayment(payment, "authorized", 0n, command.reviewId, now))) {
      yield* run("ScheduleWork", [CaptureKind, captureKey(command.paymentIntentId), JSON.stringify({ intent: command.paymentIntentId }), now, now, now]);
    }
    return { kind: "payment.review", outcome: "approved" };
  }
  yield* exception(payment.attempt_id, payment.order_id, "review", command.reviewId, true, `Radar review closed as ${command.closedReason ?? "unknown"}; capture stays blocked`, now);
  return { kind: "payment.review", outcome: "held" };
}

function* flag(command: Of<"payment.flag">): Program<ResultOf<"payment.flag">> {
  const payment = yield* get("GetPaymentByIntent", [command.paymentIntentId]);
  if (payment === null) return { kind: "payment.flag", outcome: "not_found" };
  yield* exception(payment.attempt_id, payment.order_id, command.exception, command.objectId, command.open, command.detail, BigInt(command.nowSeconds));
  return { kind: "payment.flag", outcome: "recorded" };
}

function* sweep(command: Of<"payment.sweep">): Program<ResultOf<"payment.sweep">> {
  const now = BigInt(command.nowSeconds);
  const cutoff = BigInt(Math.max(0, command.nowSeconds - SweepSlackSeconds));
  const attempts = yield* all("ListStalledAttempts", [cutoff, BigInt(MaxSweepObjects)]);
  for (const attempt of attempts) yield* run("ScheduleWork", [HoldExpiryKind, holdExpiryKey(attempt.ref), JSON.stringify({ attempt: attempt.ref }), now, now, now]);
  const room = MaxSweepObjects - attempts.length;
  const payments = room > 0 ? yield* all("ListStalledPayments", [cutoff, BigInt(room)]) : [];
  for (const payment of payments) yield* run("ScheduleWork", [CaptureKind, captureKey(payment.payment_intent_id), JSON.stringify({ intent: payment.payment_intent_id }), now, now, now]);
  return { kind: "payment.sweep", holds: BigInt(attempts.length), captures: BigInt(payments.length) };
}

export function* paymentCommandProgram(command: PaymentCommand): Program<PaymentCommandResult> {
  const now = BigInt(command.nowSeconds);
  switch (command.kind) {
    case "payment.authorize": return yield* authorize(command);
    case "payment.op.begin": return yield* beginOperation(command);
    case "payment.op.settle": return yield* settleOperation(command);
    case "payment.capture.begin": return yield* beginCapture(command);
    case "payment.observe": return yield* observe(command);
    case "payment.review": return yield* review(command);
    case "payment.flag": return yield* flag(command);
    case "payment.release": {
      const row = yield* get("GetPaymentAttempt", [command.attemptRef]);
      if (row === null) return { kind: "payment.release", outcome: "not_found" };
      return { kind: "payment.release", outcome: (yield* releaseHolds(row, now)) ? "released" : "not_pinned" };
    }
    case "payment.block": {
      const row = yield* get("GetPaymentAttempt", [command.attemptRef]);
      if (row === null) return { kind: "payment.block", outcome: "not_found" };
      const order = yield* get("GetOrderForAttempt", [row.id]);
      yield* exception(row.id, order?.id ?? null, command.exception, command.objectId, true, command.detail, now);
      if (order === null) yield* moveAttempt(row, "blocked", now);
      return { kind: "payment.block", outcome: "blocked" };
    }
    case "payment.sweep": return yield* sweep(command);
  }
}

function* attemptView(ref: string): Program<AttemptPaymentView | null> {
  const row = yield* get("GetPaymentAttempt", [ref]);
  if (row === null) return null;
  const stored = yield* storedQuote(row.quote_ref);
  if (stored === null) throw new Error(`payments: attempt ${ref} references a missing quote`);
  const create = yield* operation("create_session", ref);
  const expire = yield* operation("expire_session", ref);
  const order = yield* get("GetOrderForAttempt", [row.id]);
  return {
    ref: row.ref,
    state: row.state as AttemptState,
    sessionId: row.provider_session_id,
    sessionExpiresAt: row.provider_session_expires_at,
    holdReleaseAfter: row.hold_release_after,
    acceptedAt: row.accepted_at,
    totalMinor: row.total_minor,
    currency: row.currency_code,
    orderNumber: order?.number ?? null,
    quote: quoteView(stored.row.ref, stored.row.contact_email, stored.quote),
    createSession: create === null ? null : operationView(create),
    expireSession: expire === null ? null : operationView(expire),
  };
}

export function* paymentQueryProgram(query: PaymentQuery): Program<PaymentQueryResult> {
  switch (query.kind) {
    case "payment.attempt": return { kind: "payment.attempt", attempt: yield* attemptView(query.attemptRef) };
    case "payment.intent": {
      const row = yield* get("GetPaymentByIntent", [query.paymentIntentId]);
      if (row === null) return { kind: "payment.intent", payment: null };
      const capture = yield* operation("capture", query.paymentIntentId);
      return {
        kind: "payment.intent",
        payment: {
          attemptRef: row.attempt_ref, orderNumber: row.number, state: row.state as PaymentState, amountAuthorizedMinor: row.amount_authorized_minor,
          amountCapturedMinor: row.amount_captured_minor, currency: row.currency_code, reviewId: row.review_id, capture: capture === null ? null : operationView(capture),
        },
      };
    }
    case "order.status": {
      const row = yield* get("GetOrderStatus", [query.number, digestBytes(query.accessDigest), BigInt(query.nowSeconds)]);
      if (row === null) return { kind: "order.status", order: null };
      const lines = yield* all("ListOrderLines", [row.id]);
      return {
        kind: "order.status",
        order: {
          number: row.number, attemptRef: row.attempt_ref, paymentState: row.payment_state as PaymentState, currency: row.currency_code, totalMinor: row.total_minor,
          placedAt: row.placed_at, openExceptions: row.open_exceptions, destination: row.fulfillment === "ship" && row.city !== null && row.region !== null ? `${row.city}, ${row.region}` : null,
          lines: lines.map((line) => ({ title: line.title, variantLabel: line.variant_label, unitPriceMinor: line.unit_price_minor, quantity: line.quantity, lineTotalMinor: line.line_total_minor })),
        },
      };
    }
  }
}
