import type { Position } from "./ast.ts";
import type { ContractType } from "./contract.ts";
import type { AttributeContext, TextContext } from "./html.ts";

export const programVersion = 1;
export const maxExpandedNodes = 200_000;
export const maxProgramBytes = 4 << 20;
export const maxInvokeDepth = 32;
export const maxFeaturedLimit = 24;
export const maxRenderSteps = 100_000;

export type RenderExpression =
  | { readonly kind: "literal"; readonly value: string | number | boolean | null }
  | { readonly kind: "binding"; readonly name: string; readonly fields: readonly string[] }
  | { readonly kind: "not"; readonly value: RenderExpression }
  | { readonly kind: "binary"; readonly operator: "&&" | "||" | "==" | "!="; readonly left: RenderExpression; readonly right: RenderExpression }
  | { readonly kind: "concat"; readonly values: readonly RenderExpression[] }
  | { readonly kind: "len"; readonly array: RenderExpression }
  | { readonly kind: "plural"; readonly count: RenderExpression; readonly one: RenderExpression; readonly many: RenderExpression }
  | { readonly kind: "route"; readonly route: string; readonly args: readonly RenderExpression[] }
  | { readonly kind: "featured"; readonly index: number };

export type RenderPart = { readonly kind: "literal"; readonly value: string } | { readonly kind: "expression"; readonly expression: RenderExpression; readonly constantText?: true };
export type RenderAttribute =
  | { readonly kind: "flag"; readonly name: string }
  | { readonly kind: "boolean"; readonly name: string; readonly expression: RenderExpression }
  | { readonly kind: "value"; readonly name: string; readonly context: Exclude<AttributeContext, "json">; readonly parts: readonly RenderPart[] }
  | { readonly kind: "value"; readonly name: string; readonly context: "json"; readonly type: ContractType; readonly parts: readonly RenderPart[] };

// Every loop charges one step before evaluating its body, including bodies
// that emit no output. The renderer also observes request cancellation.
export type RenderNode =
  | { readonly kind: "text"; readonly position: Position; readonly context: TextContext; readonly parts: readonly RenderPart[] }
  | { readonly kind: "doctype"; readonly position: Position }
  | { readonly kind: "element"; readonly position: Position; readonly tag: string; readonly attributes: readonly RenderAttribute[]; readonly children: readonly RenderNode[] }
  | { readonly kind: "if"; readonly position: Position; readonly test: RenderExpression; readonly children: readonly RenderNode[]; readonly otherwise: readonly RenderNode[] }
  | { readonly kind: "with"; readonly position: Position; readonly value: RenderExpression; readonly binding: string; readonly children: readonly RenderNode[]; readonly otherwise: readonly RenderNode[] }
  | { readonly kind: "for"; readonly position: Position; readonly array: RenderExpression; readonly binding: string; readonly index: string | null; readonly chargeStep: true; readonly children: readonly RenderNode[]; readonly otherwise: readonly RenderNode[] }
  | { readonly kind: "let"; readonly position: Position; readonly bindings: readonly { readonly name: string; readonly value: RenderExpression }[]; readonly children: readonly RenderNode[] }
  | { readonly kind: "scripts"; readonly position: Position };

export interface FeaturedRef { readonly handle: string; readonly limit: number }
export interface Program {
  readonly version: typeof programVersion;
  readonly entry: string;
  readonly contract: string;
  readonly inputs: readonly { readonly binding: string; readonly field: string; readonly type: ContractType }[];
  readonly nodes: readonly RenderNode[];
  readonly featured: readonly FeaturedRef[];
  readonly behaviors: readonly string[];
  readonly scripts: readonly string[];
  readonly renderSteps: typeof maxRenderSteps;
}
