for (const route of Object.values(adminRouteDefinitions)) { Object.freeze(route.params); Object.freeze(route); }
export const ADMIN_ROUTES = Object.freeze(adminRouteDefinitions);
export type AdminRouteName = keyof typeof ADMIN_ROUTES;

export function isAdminPath(segments: readonly string[]): boolean {
  return segments[0] === "admin";
}

export type AdminRouteMatch =
  | { readonly kind: "matched"; readonly name: AdminRouteName; readonly params: ReadonlyMap<string, string> }
  | { readonly kind: "method"; readonly allow: string }
  | { readonly kind: "none" };

export function matchAdminRoute(segments: readonly string[], method: string): AdminRouteMatch {
  const allowed: string[] = [];
  let found: { readonly name: AdminRouteName; readonly params: ReadonlyMap<string, string> } | null = null;
  for (const name of Object.keys(ADMIN_ROUTES) as AdminRouteName[]) {
    const route = ADMIN_ROUTES[name];
    const pattern = route.pattern.slice(1).split("/");
    if (pattern.length !== segments.length) continue;
    const params = new Map<string, string>();
    const matches = pattern.every((part, index) => {
      const value = segments[index]!;
      if (part.startsWith("{")) { if (value === "") return false; params.set(part.slice(1, -1), value); return true; }
      return part === value;
    });
    if (!matches) continue;
    allowed.push(route.method);
    if (route.method === method || (route.method === "GET" && method === "HEAD")) found = found ?? { name, params };
  }
  if (found !== null) return { kind: "matched", ...found };
  return allowed.length === 0 ? { kind: "none" } : { kind: "method", allow: [...new Set(allowed)].join(", ") };
}

export function adminPath(name: AdminRouteName, params: readonly string[] = []): string {
  const route = ADMIN_ROUTES[name];
  if (params.length !== route.params.length) throw new Error(`Admin route ${name} takes ${route.params.length} parameters`);
  let path: string = route.pattern;
  route.params.forEach((key, index) => {
    const value = params[index]!;
    if (!/^[A-Za-z0-9_-]+$/.test(value)) throw new Error(`Admin route parameter ${key} must be URL-safe`);
    path = path.replace(`{${key}}`, value);
  });
  return path;
}

export function safeAdminReturn(candidate: string | null): string {
  if (candidate === null || candidate.length > 200 || !/^\/admin(?:\/[A-Za-z0-9_-]+)*$/.test(candidate)) return "/admin";
  return candidate;
}
