import type { BlobObject } from "./blob.ts";
import { contentTypeOf, type MediaAddress } from "./format.ts";
import { PublicMaxAgeSeconds } from "./limits.ts";

export type MediaAudience = "public" | "admin";

function matches(header: string | null, etag: string): boolean {
  if (header === null) return false;
  return header.split(",").some((candidate) => {
    const token = candidate.trim().replace(/^W\//, "");
    return token === "*" || token === etag;
  });
}

/**
 * The response for one stored media object. Public media is cacheable for a
 * day with a strong ETag, so unpublication converges within a day; admin
 * media is never stored by a cache. Returns null when the stored object is
 * not what its key says.
 */
export function mediaResponse(request: Request, address: MediaAddress, object: BlobObject, audience: MediaAudience, base: Headers): Response | null {
  if (object.contentType !== contentTypeOf(address.kind)) return null;
  const headers = new Headers(base);
  headers.set("Content-Type", object.contentType);
  headers.set("Content-Length", String(object.bytes.length));
  if (audience === "public") {
    const etag = `"${address.sha256}"`;
    headers.set("Cache-Control", `public, max-age=${PublicMaxAgeSeconds}`);
    headers.set("ETag", etag);
    if (matches(request.headers.get("if-none-match"), etag)) {
      headers.delete("Content-Length");
      headers.delete("Content-Type");
      return new Response(null, { status: 304, headers });
    }
  } else {
    headers.set("Cache-Control", "private, no-store");
  }
  return new Response(request.method === "HEAD" ? null : object.bytes.slice(), { status: 200, headers });
}
