export class EmailValidationError extends Error {
  readonly _tag = "EmailValidationError";
  constructor(message: string) { super(`email: ${message}`); }
}

declare const outgoingBrand: unique symbol;

export interface OutgoingEmail {
  readonly [outgoingBrand]: true;
  readonly from: string;
  readonly to: string;
  readonly subject: string;
  readonly replyTo: string | null;
  readonly text: string;
  readonly html: string;
}

export interface EmailContent {
  readonly text: string;
  readonly html: string;
}

export interface EmailDraft {
  readonly from: string;
  readonly to: string;
  readonly subject: string;
  readonly replyTo?: string;
  readonly content: EmailContent;
}

const controlCharacters = /[\u0000-\u001f\u007f\u0085\u2028\u2029]/;
const mailbox = /^(?:[^<>@,;"\\]*<[^\s<>@,;"\\]+@[^\s<>@,;"\\]+>|[^\s<>@,;"\\]+@[^\s<>@,;"\\]+)$/;
const maxHeaderLength = 998;

export function assertHeaderField(name: string, value: string): void {
  if (value.length === 0) throw new EmailValidationError(`${name} is empty`);
  if (value.length > maxHeaderLength) throw new EmailValidationError(`${name} is longer than ${maxHeaderLength} characters`);
  if (controlCharacters.test(value)) throw new EmailValidationError(`${name} contains a control character`);
}

function assertMailbox(name: string, value: string): void {
  assertHeaderField(name, value);
  if (!mailbox.test(value.trim())) throw new EmailValidationError(`${name} is not a single address`);
}

export function composeEmail(draft: EmailDraft): OutgoingEmail {
  assertMailbox("from", draft.from);
  assertMailbox("to", draft.to);
  assertHeaderField("subject", draft.subject);
  if (draft.replyTo !== undefined) assertMailbox("reply-to", draft.replyTo);
  if (draft.content.text.length === 0) throw new EmailValidationError("text body is empty");
  return {
    from: draft.from,
    to: draft.to,
    subject: draft.subject,
    replyTo: draft.replyTo ?? null,
    text: draft.content.text,
    html: draft.content.html,
  } as OutgoingEmail;
}
