import { formatPriceInput, parsePriceInput } from "../catalog/edit.ts";
import { PpmDenominator } from "../commerce/tax.ts";
import { UsRegions } from "../commerce/shipping.ts";
import type { FormValues } from "./catalog_form.ts";
import type { FieldErrors } from "./pages.ts";
import type { PolicyProblemView, SettingsViewModel, ShippingPolicyInput, TaxPolicyInput } from "./settings_operations.ts";

export const MaxShippingZones = 10;
export const MaxZoneNameLength = 100;
export const SortedRegions: readonly string[] = [...UsRegions].sort();

const PpmPerPercentUnit = 10_000n;

export function parseRatePercent(text: string): bigint | null {
  const match = /^([0-9]{1,3})(?:\.([0-9]{1,4}))?$/.exec(text.trim());
  if (match === null) return null;
  const ppm = BigInt(match[1] ?? "") * PpmPerPercentUnit + BigInt((match[2] ?? "").padEnd(4, "0"));
  return ppm > PpmDenominator ? null : ppm;
}

export function formatRatePercent(ppm: bigint): string {
  const whole = ppm / PpmPerPercentUnit;
  const fraction = (ppm % PpmPerPercentUnit).toString().padStart(4, "0").replace(/0+$/, "");
  return fraction === "" ? whole.toString() : `${whole}.${fraction}`;
}

export function parseRegionList(text: string): readonly string[] {
  return text.split(/[\s,]+/).filter((token) => token !== "").map((token) => token.toUpperCase());
}

export interface TaxRow {
  readonly rate: string;
  readonly lines: boolean;
  readonly shipping: boolean;
}

export interface TaxForm {
  readonly mode: "no_tax_collected" | "rate_table";
  readonly rows: ReadonlyMap<string, TaxRow>;
}

const blankRow: TaxRow = { rate: "", lines: true, shipping: false };

export function taxFormFromView(tax: SettingsViewModel["tax"]): TaxForm {
  const rows = new Map<string, TaxRow>();
  for (const rate of tax?.rates ?? []) rows.set(rate.region, { rate: formatRatePercent(rate.ratePpm), lines: rate.taxesLines, shipping: rate.taxesShipping });
  return { mode: tax?.mode ?? "rate_table", rows };
}

export function taxFormFromFields(fields: FormValues): TaxForm {
  const rows = new Map<string, TaxRow>();
  for (const region of SortedRegions) {
    rows.set(region, { rate: (fields.get(`rate_${region}`) ?? "").trim(), lines: fields.get(`lines_${region}`) === "on", shipping: fields.get(`shipping_${region}`) === "on" });
  }
  return { mode: fields.get("mode") === "no_tax_collected" ? "no_tax_collected" : "rate_table", rows };
}

export function taxRow(form: TaxForm, region: string): TaxRow {
  return form.rows.get(region) ?? blankRow;
}

export type TaxParse = { readonly ok: true; readonly policy: TaxPolicyInput } | { readonly ok: false; readonly errors: FieldErrors };

export function parseTaxForm(form: TaxForm): TaxParse {
  if (form.mode === "no_tax_collected") return { ok: true, policy: { mode: "no_tax_collected" } };
  const errors: Record<string, string> = {};
  const rates: Extract<TaxPolicyInput, { mode: "rate_table" }>["rates"][number][] = [];
  for (const region of SortedRegions) {
    const row = taxRow(form, region);
    if (row.rate === "") continue;
    const ratePpm = parseRatePercent(row.rate);
    if (ratePpm === null) errors[`rate_${region}`] = "Enter a percentage from 0 to 100 with up to 4 decimals, for example 7.25.";
    else rates.push({ region, ratePpm, taxesLines: row.lines, taxesShipping: row.shipping });
  }
  if (Object.keys(errors).length === 0 && rates.length === 0) errors["mode"] = "Enter a rate for at least one region, or choose no tax collected.";
  return Object.keys(errors).length > 0 ? { ok: false, errors } : { ok: true, policy: { mode: "rate_table", rates } };
}

export function describeTaxProblems(problems: readonly PolicyProblemView[]): FieldErrors {
  const errors: Record<string, string> = {};
  for (const problem of problems) {
    if (problem.subject === null) continue;
    errors[`rate_${problem.subject}`] = problem.kind === "unknown_region" ? "That region is not supported." : problem.kind === "duplicate_region" ? "That region is listed twice." : "The rate must be from 0 to 100 percent.";
  }
  return errors;
}

export interface ZoneRow {
  readonly name: string;
  readonly rate: string;
  readonly regions: string;
}

export interface ShippingForm {
  readonly origin: string;
  readonly threshold: string;
  readonly pickup: boolean;
  readonly zones: readonly ZoneRow[];
}

export function shippingFormFromView(shipping: SettingsViewModel["shipping"], exponent: number): ShippingForm {
  if (shipping === null) return { origin: "", threshold: "", pickup: false, zones: [] };
  return {
    origin: shipping.originRegion,
    threshold: shipping.freeShippingThresholdMinor === null ? "" : formatPriceInput(shipping.freeShippingThresholdMinor, exponent),
    pickup: shipping.localPickup,
    zones: shipping.zones.map((zone) => ({ name: zone.name, rate: formatPriceInput(zone.flatRateMinor, exponent), regions: zone.regions.join(" ") })),
  };
}

export function shippingFormFromFields(fields: FormValues): ShippingForm {
  const zones: ZoneRow[] = [];
  for (let slot = 0; slot < MaxShippingZones; slot++) {
    zones.push({ name: (fields.get(`zone_${slot}_name`) ?? "").trim(), rate: (fields.get(`zone_${slot}_rate`) ?? "").trim(), regions: (fields.get(`zone_${slot}_regions`) ?? "").trim() });
  }
  return { origin: (fields.get("origin") ?? "").trim(), threshold: (fields.get("threshold") ?? "").trim(), pickup: fields.get("pickup") === "on", zones };
}

export function zoneSlots(form: ShippingForm): number {
  const filled = form.zones.filter((zone) => zone.name !== "" || zone.rate !== "" || zone.regions !== "").length;
  return Math.min(MaxShippingZones, Math.max(1, filled + 1));
}

export type ShippingParse =
  | { readonly ok: true; readonly policy: ShippingPolicyInput; readonly slots: readonly number[] }
  | { readonly ok: false; readonly errors: FieldErrors };

export function parseShippingForm(form: ShippingForm, exponent: number): ShippingParse {
  const errors: Record<string, string> = {};
  const origin = form.origin.toUpperCase();
  if (origin === "") errors["origin"] = "Enter the two-letter state code you ship from, for example WA.";
  let threshold: bigint | null = null;
  if (form.threshold !== "") {
    threshold = parsePriceInput(form.threshold, exponent);
    if (threshold === null) errors["threshold"] = "Enter an amount such as 75 or 75.00, or leave it blank.";
  }
  const zones: ShippingPolicyInput["zones"][number][] = [];
  const slots: number[] = [];
  for (const [slot, zone] of form.zones.entries()) {
    if (zone.name === "" && zone.rate === "" && zone.regions === "") continue;
    if (zone.name === "" || zone.name.length > MaxZoneNameLength) errors[`zone_${slot}_name`] = `Enter a zone name of at most ${MaxZoneNameLength} characters.`;
    const flatRateMinor = parsePriceInput(zone.rate, exponent);
    if (flatRateMinor === null) errors[`zone_${slot}_rate`] = "Enter a rate such as 7 or 7.50.";
    const regions = parseRegionList(zone.regions);
    if (regions.length === 0) errors[`zone_${slot}_regions`] = "Enter at least one state code, separated by spaces or commas.";
    if (flatRateMinor !== null) {
      zones.push({ name: zone.name, regions, flatRateMinor });
      slots.push(slot);
    }
  }
  return Object.keys(errors).length > 0
    ? { ok: false, errors }
    : { ok: true, slots, policy: { originRegion: origin, zones, freeShippingThresholdMinor: threshold, localPickup: form.pickup } };
}

export function describeShippingProblems(problems: readonly PolicyProblemView[], parsed: Extract<ShippingParse, { ok: true }>): FieldErrors {
  const errors: Record<string, string> = {};
  const slotOf = (match: (zone: ShippingPolicyInput["zones"][number]) => boolean): number | undefined => {
    const index = parsed.policy.zones.findIndex(match);
    return index < 0 ? undefined : parsed.slots[index];
  };
  for (const problem of problems) {
    switch (problem.kind) {
      case "unknown_origin_region": errors["origin"] = "That is not a supported state code."; break;
      case "duplicate_zone": {
        const slot = slotOf((zone) => zone.name === problem.subject);
        if (slot !== undefined) errors[`zone_${slot}_name`] = "Zone names must be different.";
        break;
      }
      case "unknown_region":
      case "duplicate_region": {
        const slot = slotOf((zone) => zone.regions.includes(problem.subject ?? ""));
        if (slot !== undefined) errors[`zone_${slot}_regions`] = problem.kind === "unknown_region" ? `${problem.subject} is not a supported state code.` : `${problem.subject} is in more than one zone.`;
        break;
      }
      case "amount_out_of_range": {
        if (problem.subject === null) errors["threshold"] = "That amount is too large.";
        else {
          const slot = slotOf((zone) => zone.name === problem.subject);
          if (slot !== undefined) errors[`zone_${slot}_rate`] = "That amount is too large.";
        }
        break;
      }
      default: break;
    }
  }
  return errors;
}
