export const MaxIssuerLength = 72;
export const MaxSubjectLength = 127;
export const MaxLabelLength = 100;
export const MaxEmailLength = 254;

export interface PrincipalRef {
  readonly issuer: string;
  readonly subject: string;
}

export interface Principal extends PrincipalRef {
  readonly email: string | null;
}

export interface Grant extends PrincipalRef {
  readonly label: string;
}

export type PrincipalId = string & { readonly __principalId: never };

const issuerPattern = /^[a-z][a-z0-9+.-]*:\/\/[^\s#?\u0000-\u001f\u007f]+$/;
const emailPattern = /^[^\s@\u0000-\u001f\u007f]+@[^\s@\u0000-\u001f\u007f]+$/;

export function validIssuer(value: string): boolean {
  return value.length <= MaxIssuerLength && issuerPattern.test(value);
}

export function validSubject(value: string): boolean {
  return value.length >= 1 && value.length <= MaxSubjectLength && value.trim() === value && !/[\u0000-\u001f\u007f]/.test(value);
}

export function validEmail(value: string): boolean {
  return value.length <= MaxEmailLength && emailPattern.test(value);
}

export function validLabel(value: string): boolean {
  return value.trim().length > 0 && value.length <= MaxLabelLength && !/[\u0000-\u001f\u007f]/.test(value);
}

export function principalId(ref: PrincipalRef): PrincipalId {
  if (!validIssuer(ref.issuer) || !validSubject(ref.subject)) throw new RangeError("identity: malformed principal");
  return `${ref.issuer}#${ref.subject}` as PrincipalId;
}

export function samePrincipal(left: PrincipalRef, right: PrincipalRef): boolean {
  return left.issuer === right.issuer && left.subject === right.subject;
}

export interface TenantGrants {
  readonly owners: readonly Grant[];
  readonly operators: readonly Grant[];
}

export type Role = "owner" | "operator" | "none";

export function authorize(principal: PrincipalRef, grants: TenantGrants): Role {
  if (grants.owners.some((grant) => samePrincipal(grant, principal))) return "owner";
  if (grants.operators.some((grant) => samePrincipal(grant, principal))) return "operator";
  return "none";
}
