import type { PreparedResponse } from "./response.ts";

export const DEFAULT_PAGE_CACHE_BYTES = 64 << 20;
const SHARDS = 64;
const ENTRY_OVERHEAD = 256;
interface Entry { readonly response: PreparedResponse; readonly size: number }
interface Shard { readonly entries: Map<string, Entry>; bytes: number }
export interface CacheStats { readonly hits: number; readonly misses: number; readonly bytes: number; readonly entries: number }
export interface TenantPages {
  get(revision: string, generation: bigint, key: string): PreparedResponse | undefined;
  put(revision: string, generation: bigint, key: string, response: PreparedResponse): void;
  purge(): void;
}

export class PageCache {
  readonly #shards: Shard[] = Array.from({ length: SHARDS }, () => ({ entries: new Map(), bytes: 0 }));
  readonly #shardBytes: number;
  #hits = 0;
  #misses = 0;
  constructor(maximum = DEFAULT_PAGE_CACHE_BYTES) {
    if (!Number.isSafeInteger(maximum) || maximum < 0) throw new Error("Invalid page cache budget");
    this.#shardBytes = Math.floor(maximum / SHARDS);
  }
  get stats(): CacheStats {
    return { hits: this.#hits, misses: this.#misses, bytes: this.#shards.reduce((sum, shard) => sum + shard.bytes, 0), entries: this.#shards.reduce((sum, shard) => sum + shard.entries.size, 0) };
  }
  #shard(key: string): Shard {
    let hash = 2166136261;
    for (const byte of new TextEncoder().encode(key)) hash = Math.imul(hash ^ byte, 16777619);
    return this.#shards[(hash >>> 0) % SHARDS]!;
  }
  tenantView(tenant: string): TenantPages {
    if (tenant === "" || tenant.includes("\0")) throw new Error("Invalid tenant cache namespace");
    const prefix = `${tenant}\0`;
    const canonical = (revision: string, generation: bigint, key: string): string => {
      if (revision.includes("\0") || generation < 0n) throw new Error("Invalid cache version");
      return `${prefix}${revision}\0${generation}\0${key}`;
    };
    return Object.freeze({
      get: (revision: string, generation: bigint, key: string): PreparedResponse | undefined => {
        const name = canonical(revision, generation, key);
        const shard = this.#shard(name);
        const entry = shard.entries.get(name);
        if (entry === undefined) { this.#misses++; return undefined; }
        this.#hits++;
        shard.entries.delete(name);
        shard.entries.set(name, entry);
        return entry.response;
      },
      put: (revision: string, generation: bigint, key: string, response: PreparedResponse): void => {
        if (response.status !== 200 || response.cache !== "public") return;
        const name = canonical(revision, generation, key);
        const size = new TextEncoder().encode(name).length + response.byteLength + ENTRY_OVERHEAD;
        if (size > this.#shardBytes / 4) return;
        const shard = this.#shard(name);
        const previous = shard.entries.get(name);
        if (previous !== undefined) { shard.bytes -= previous.size; shard.entries.delete(name); }
        shard.entries.set(name, { response, size });
        shard.bytes += size;
        while (shard.bytes > this.#shardBytes) {
          const oldest = shard.entries.keys().next().value!;
          shard.bytes -= shard.entries.get(oldest)!.size;
          shard.entries.delete(oldest);
        }
      },
      purge: (): void => {
        for (const shard of this.#shards) for (const [name, entry] of shard.entries) if (name.startsWith(prefix)) { shard.entries.delete(name); shard.bytes -= entry.size; }
      },
    });
  }
}
