import { MAX_QUANTITY } from "../session/session.ts";

const routeDefinitions = {
  home: { method: "GET", pattern: "/", params: [] },
  products: { method: "GET", pattern: "/products", params: [] },
  search: { method: "GET", pattern: "/search", params: [] },
  collections: { method: "GET", pattern: "/collections", params: [] },
  collection: { method: "GET", pattern: "/collections/{handle}", params: ["handle"] },
  product: { method: "GET", pattern: "/products/{handle}", params: ["handle"] },
  cart: { method: "GET", pattern: "/cart", params: [] },
  "cart-add": { method: "POST", pattern: "/cart/items", params: [] },
  "cart-set": { method: "POST", pattern: "/cart/items/{variant_id}", params: ["variant_id"] },
  "cart-remove": { method: "POST", pattern: "/cart/items/{variant_id}/remove", params: ["variant_id"] },
  checkout: { method: "GET", pattern: "/checkout", params: [] },
  "checkout-review": { method: "POST", pattern: "/checkout/review", params: [] },
  "checkout-quote": { method: "GET", pattern: "/checkout/quotes/{ref}", params: ["ref"] },
  "checkout-refresh": { method: "POST", pattern: "/checkout/quotes/{ref}/refresh", params: ["ref"] },
  "checkout-accept": { method: "POST", pattern: "/checkout/quotes/{ref}/accept", params: ["ref"] },
  "checkout-attempt": { method: "GET", pattern: "/checkout/attempts/{ref}", params: ["ref"] },
  "order-lookup": { method: "GET", pattern: "/orders/lookup", params: [] },
  "order-lookup-request": { method: "POST", pattern: "/orders/lookup/request", params: [] },
  "order-access": { method: "GET", pattern: "/orders/access/{token}", params: ["token"] },
  order: { method: "GET", pattern: "/orders/{number}", params: ["number"] },
  info: { method: "GET", pattern: "/pages/{slug}", params: ["slug"] },
  sitemap: { method: "GET", pattern: "/sitemap.xml", params: [] },
  robots: { method: "GET", pattern: "/robots.txt", params: [] },
} as const;
for (const route of Object.values(routeDefinitions)) { Object.freeze(route.params); Object.freeze(route); }
export const ROUTES = Object.freeze(routeDefinitions);
export type RouteName = keyof typeof ROUTES;

export function isRouteName(name: string): name is RouteName {
  return Object.hasOwn(ROUTES, name);
}

export function parseRouteName(name: string): RouteName {
  if (!isRouteName(name)) throw new Error(`Unknown route ${JSON.stringify(name)}`);
  return name;
}

export type CartActionName = "cart-add" | "cart-set" | "cart-remove";
const cartActionDefinitions = {
  "cart-add": { method: "POST", fields: ["variant_id", "quantity"], pathVariant: false, successStatus: 303, successLocation: "cart" },
  "cart-set": { method: "POST", fields: ["quantity"], pathVariant: true, successStatus: 303, successLocation: "cart" },
  "cart-remove": { method: "POST", fields: [], pathVariant: true, successStatus: 303, successLocation: "cart" },
} as const;
for (const action of Object.values(cartActionDefinitions)) { Object.freeze(action.fields); Object.freeze(action); }
export const CART_ACTIONS = Object.freeze(cartActionDefinitions);

export type CheckoutActionName = "review" | "refresh" | "accept";
export const CheckoutFields = ["email", "fulfillment", "recipient", "line1", "line2", "city", "region", "postal_code"] as const;
const checkoutActionDefinitions = {
  review: { route: "checkout-review", method: "POST", pathRef: false, fields: CheckoutFields },
  refresh: { route: "checkout-refresh", method: "POST", pathRef: true, fields: [] },
  accept: { route: "checkout-accept", method: "POST", pathRef: true, fields: [] },
} as const;
for (const action of Object.values(checkoutActionDefinitions)) { Object.freeze(action.fields); Object.freeze(action); }
export const CHECKOUT_ACTIONS = Object.freeze(checkoutActionDefinitions);

export function parseID(raw: string): bigint {
  if (!/^[1-9][0-9]*$/.test(raw) || raw.length > 19) throw new Error("Item is not a valid identifier");
  const id = BigInt(raw);
  if (id > 9223372036854775807n) throw new Error("Item is not a valid identifier");
  return id;
}

export function routePath(name: RouteName, params: readonly string[] = []): string {
  const route = ROUTES[name];
  if (params.length !== route.params.length) throw new Error(`Route ${name} takes ${route.params.length} parameters`);
  let path: string = route.pattern;
  route.params.forEach((key, index) => {
    const value = params[index]!;
    if (value === "") throw new Error(`Route parameter ${key} is empty`);
    const escaped = encodeURIComponent(value).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`).replace(/%(?:2B|3A|40|24|26|3D)/g, (escape) => decodeURIComponent(escape));
    path = path.replace(`{${key}}`, () => escaped);
  });
  return path;
}

export function withQuery(path: string, fields: Readonly<Record<string, string>>): string {
  const query: string[] = [];
  const escape = (value: string): string => encodeURIComponent(value).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`).replaceAll("%20", "+");
  for (const key of Object.keys(fields).sort()) {
    const value = fields[key]!;
    if (value !== "") query.push(`${escape(key)}=${escape(value)}`);
  }
  const encoded = query.join("&");
  return encoded === "" ? path : `${path}?${encoded}`;
}

export interface AddCartInput { readonly variantId: bigint; readonly quantity: number }
export interface SetCartInput { readonly variantId: bigint; readonly quantity: number }
export interface RemoveCartInput { readonly variantId: bigint }

function checkedFields(fields: ReadonlyMap<string, string>, allowed: readonly string[]): void {
  for (const key of fields.keys()) if (!allowed.includes(key)) throw new Error(`Unexpected form field ${key}`);
  for (const key of allowed) if (!fields.has(key)) throw new Error(`${key} is required`);
}

function quantity(raw: string): number {
  if (!/^[1-9][0-9]*$/.test(raw)) throw new Error(`Quantity must be a whole number from 1 to ${MAX_QUANTITY}`);
  const value = Number(raw);
  if (value > MAX_QUANTITY) throw new Error(`Quantity must be a whole number from 1 to ${MAX_QUANTITY}`);
  return value;
}

export function parseAddCartInput(fields: ReadonlyMap<string, string>): AddCartInput {
  checkedFields(fields, CART_ACTIONS["cart-add"].fields);
  return { variantId: parseID(fields.get("variant_id")!), quantity: quantity(fields.get("quantity")!) };
}
export function parseSetCartInput(pathVariant: string, fields: ReadonlyMap<string, string>): SetCartInput {
  checkedFields(fields, CART_ACTIONS["cart-set"].fields);
  return { variantId: parseID(pathVariant), quantity: quantity(fields.get("quantity")!) };
}
export function parseRemoveCartInput(pathVariant: string, fields: ReadonlyMap<string, string>): RemoveCartInput {
  checkedFields(fields, CART_ACTIONS["cart-remove"].fields);
  return { variantId: parseID(pathVariant) };
}
