import type { AdminBackend } from "../admin/backend.ts";
import {
  decodeAdminCommandResult,
  decodeAdminQueryResult,
  encodeAdminCommand,
  encodeAdminQuery,
  type AdminCommand,
  type AdminQuery,
  type CommandResultFor,
  type QueryResultFor,
} from "../admin/operations.ts";
import { unwrapRpcResult, type RpcResult } from "./rpc.ts";

export interface CommerceRpcStub {
  commerceCommand(requestText: string): Promise<RpcResult<string>>;
  commerceQuery(requestText: string): Promise<RpcResult<string>>;
}

export function cloudflareAdminBackend(stub: () => CommerceRpcStub): AdminBackend {
  return {
    async command<C extends AdminCommand>(command: C): Promise<CommandResultFor<C>> {
      const result = decodeAdminCommandResult(unwrapRpcResult(await stub().commerceCommand(encodeAdminCommand(command))));
      if (result.kind !== command.kind) throw new Error(`cloudflare: ${command.kind} returned ${result.kind}`);
      return result as CommandResultFor<C>;
    },
    async query<Q extends AdminQuery>(query: Q): Promise<QueryResultFor<Q>> {
      const result = decodeAdminQueryResult(unwrapRpcResult(await stub().commerceQuery(encodeAdminQuery(query))));
      if (result.kind !== query.kind) throw new Error(`cloudflare: ${query.kind} returned ${result.kind}`);
      return result as QueryResultFor<Q>;
    },
  };
}
