import { BadInput } from "../web/decode.ts";

export const MaxCatalogFormBytes = 64 * 1024;
export const MaxCatalogFieldBytes = 20 * 1024;

const encoder = new TextEncoder();
const decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });

function formContentType(raw: string): boolean {
  const mediaType = (raw.split(";")[0] ?? "").trim().toLowerCase();
  return mediaType === "application/x-www-form-urlencoded";
}

function decodeComponent(raw: string): string {
  try {
    return decodeURIComponent(raw.replaceAll("+", " "));
  } catch {
    throw new BadInput("The request could not be read.");
  }
}

export type FormValues = ReadonlyMap<string, string>;

/**
 * Reads an urlencoded admin form that may carry long text and a dynamic set of
 * checkbox names. Keys outside `allowed` and repeated keys are refused, text is
 * limited to printable characters plus line breaks and tabs, and line breaks
 * are normalized to LF.
 */
export async function readCatalogForm(request: Request, allowed: (key: string) => boolean, signal: AbortSignal): Promise<FormValues> {
  signal.throwIfAborted();
  if (new URL(request.url).search !== "") throw new BadInput("Form submissions take no query parameters.");
  if (!formContentType(request.headers.get("content-type") ?? "")) throw new BadInput("Submit this form from the store admin.");
  const reader = request.body?.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  if (reader !== undefined) {
    for (;;) {
      signal.throwIfAborted();
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MaxCatalogFormBytes) {
        await reader.cancel();
        throw new BadInput("The form is too large.");
      }
      chunks.push(value);
    }
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  let text: string;
  try {
    text = decoder.decode(bytes);
  } catch {
    throw new BadInput("The request could not be read.");
  }
  const out = new Map<string, string>();
  for (const pair of text.split("&")) {
    if (pair === "") continue;
    if (pair.includes(";")) throw new BadInput("The request could not be read.");
    const separator = pair.indexOf("=");
    const key = decodeComponent(separator < 0 ? pair : pair.slice(0, separator));
    const value = decodeComponent(separator < 0 ? "" : pair.slice(separator + 1)).replaceAll("\r\n", "\n").replaceAll("\r", "\n");
    if (!allowed(key)) throw new BadInput(`Unexpected parameter ${JSON.stringify(key)}.`);
    if (out.has(key)) throw new BadInput(`Parameter ${JSON.stringify(key)} was given more than once.`);
    if (encoder.encode(value).length > MaxCatalogFieldBytes || /[\u0000-\u0008\u000b-\u001f\u007f-\u009f\ud800-\udfff]/u.test(value)) throw new BadInput(`Parameter ${JSON.stringify(key)} is not valid text.`);
    out.set(key, value);
  }
  return out;
}
