import { Effect } from "effect";
import { DatabaseError, type SyncTransaction, type Transaction } from "../storefront/persistence.ts";
import { InventoryInvariantError } from "./inventory.ts";
import type { CommerceQueries, CommerceQueryRow } from "./queries.ts";
import { decideStock, type StockCommand, type StockCommandRejection, type StockContext, type StockDecision, type StockLevelRecord, type StockRead, type StockRow, type StockWrite } from "./stock.ts";

export type StockResult =
  | { readonly outcome: "applied"; readonly levels: readonly StockLevelRecord[] }
  | { readonly outcome: "rejected"; readonly rejection: StockCommandRejection; readonly variantId: bigint; readonly commandIndex: number };

function readFromRow(row: CommerceQueryRow<"GetStockRead"> | null): StockRead {
  if (row === null) return { variantExists: false, row: null };
  if (row.on_hand === null || row.held === null || row.allocated === null || row.revision === null) {
    if (row.on_hand !== null || row.held !== null || row.allocated !== null || row.revision !== null) throw new DatabaseError("commerce: partial inventory row");
    return { variantExists: true, row: null };
  }
  const stock: StockRow = { onHand: row.on_hand, held: row.held, allocated: row.allocated, revision: row.revision };
  return { variantExists: true, row: stock };
}

function distinctVariants(commands: readonly StockCommand[]): bigint[] {
  return [...new Set(commands.map((command) => command.variantId))];
}

function toResult(decision: StockDecision): StockResult {
  return decision.ok
    ? { outcome: "applied", levels: decision.levels }
    : { outcome: "rejected", rejection: decision.rejection, variantId: decision.variantId, commandIndex: decision.commandIndex };
}

function levelParams(write: StockWrite): readonly bigint[] {
  return write.kind === "insert"
    ? [write.variantId, write.level.onHand, write.level.held, write.level.allocated]
    : [write.level.onHand, write.level.held, write.level.allocated, write.variantId];
}

function asInvariant(error: unknown): unknown {
  return error instanceof DatabaseError && /CHECK constraint failed/i.test(error.message)
    ? new InventoryInvariantError(error.message, { cause: error })
    : error;
}

export function executeStockSync(tx: SyncTransaction, queries: CommerceQueries, commands: readonly StockCommand[], context: StockContext): StockResult {
  const reads = new Map<bigint, StockRead>();
  for (const variantId of distinctVariants(commands)) reads.set(variantId, readFromRow(queries.getSync(tx, "GetStockRead", [variantId])));
  const decision = decideStock(reads, commands, context);
  if (!decision.ok) return toResult(decision);
  for (const write of decision.writes) {
    try {
      queries.runSync(tx, write.kind === "insert" ? "InsertInventoryLevel" : "UpdateInventoryLevel", levelParams(write));
    } catch (error) {
      throw asInvariant(error);
    }
  }
  for (const a of decision.adjustments) queries.runSync(tx, "InsertStockAdjustment", [a.variantId, a.kind, a.delta, a.onHandAfter, a.reason, a.actor, a.createdAt]);
  for (const e of decision.audit) queries.runSync(tx, "InsertAuditEvent", [e.actor, e.action, e.entityKind, e.entityId, e.entityRevision, e.summary, context.nowSeconds]);
  return toResult(decision);
}

export function executeStock(
  tx: Transaction,
  queries: CommerceQueries,
  commands: readonly StockCommand[],
  context: StockContext,
): Effect.Effect<StockResult, DatabaseError | InventoryInvariantError> {
  return Effect.gen(function* () {
    const reads = new Map<bigint, StockRead>();
    for (const variantId of distinctVariants(commands)) {
      const row = yield* queries.get(tx, "GetStockRead", [variantId]);
      reads.set(variantId, yield* Effect.try({ try: () => readFromRow(row), catch: (cause) => cause as DatabaseError }));
    }
    const decision = yield* Effect.try({
      try: () => decideStock(reads, commands, context),
      catch: (cause) => cause instanceof InventoryInvariantError ? cause : new DatabaseError("commerce: stock decision failed", cause),
    });
    if (!decision.ok) return toResult(decision);
    for (const write of decision.writes) {
      yield* Effect.mapError(
        queries.run(tx, write.kind === "insert" ? "InsertInventoryLevel" : "UpdateInventoryLevel", levelParams(write)),
        (error) => asInvariant(error) as DatabaseError | InventoryInvariantError,
      );
    }
    for (const a of decision.adjustments) yield* queries.run(tx, "InsertStockAdjustment", [a.variantId, a.kind, a.delta, a.onHandAfter, a.reason, a.actor, a.createdAt]);
    for (const e of decision.audit) yield* queries.run(tx, "InsertAuditEvent", [e.actor, e.action, e.entityKind, e.entityId, e.entityRevision, e.summary, context.nowSeconds]);
    return toResult(decision);
  });
}
