import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";
import { EmailKinds, MaxEmailErrorLength } from "./email.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Purpose = Schema.String.check(filter<string>((value) => /^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= 128, "must be a purpose label"));
const LookupEmail = Schema.String.check(filter<string>((value) => value.length >= 1 && value.length <= 254, "must be an email of 1 to 254 characters"));
const ErrorText = Schema.String.check(filter<string>((value) => value.length <= MaxEmailErrorLength, `must be at most ${MaxEmailErrorLength} characters`));
const ProviderId = Schema.String.check(filter<string>((value) => value.length >= 1 && value.length <= 255, "must be 1 to 255 characters"));

export const EmailFactsSchema = Schema.Struct({
  kind: Schema.Literals(EmailKinds),
  to: Schema.String,
  shopName: Schema.String,
  orderNumber: Schema.NullOr(Integer),
  currency: Schema.String,
  exponent: Schema.Int,
  totalMinor: Integer,
  destination: Schema.NullOr(Schema.String),
  lines: Schema.Array(Schema.Struct({ title: Schema.String, variantLabel: Schema.String, quantity: Integer, unitPriceMinor: Integer, lineTotalMinor: Integer })),
  shipment: Schema.NullOr(Schema.Struct({
    sequence: Integer, carrier: Schema.String, trackingNumber: Schema.NullOr(Schema.String), trackingUrl: Schema.NullOr(Schema.String),
    lines: Schema.Array(Schema.Struct({ title: Schema.String, variantLabel: Schema.String, quantity: Integer })),
  })),
  refundMinor: Schema.NullOr(Integer),
});
export type EmailFacts = typeof EmailFactsSchema.Type;

export const EmailMessageViewSchema = Schema.Struct({
  id: Integer, kind: Schema.Literals(EmailKinds), generation: Integer, state: Schema.Literals(["queued", "sending", "sent", "failed", "unknown"]),
  attempts: Integer, firstAttemptAt: Schema.NullOr(Integer), lastError: Schema.NullOr(Schema.String), createdAt: Integer,
});
export type EmailMessageView = typeof EmailMessageViewSchema.Type;

export const EmailCommandSchemas = [
  Schema.Struct({ kind: Schema.Literal("email.begin"), id: Integer, generation: Integer, accessDigest: Digest, nowSeconds: Seconds }),
  Schema.Struct({
    kind: Schema.Literal("email.settle"), id: Integer, generation: Integer, state: Schema.Literals(["sent", "failed", "queued", "unknown"]),
    providerId: Schema.NullOr(ProviderId), error: Schema.NullOr(ErrorText), nowSeconds: Seconds,
  }),
  Schema.Struct({
    kind: Schema.Literal("email.resend"), sessionDigest: Digest, formTokenDigest: Digest, purpose: Purpose, actor: Schema.String, nowSeconds: Seconds,
    number: Integer, messageId: Integer,
  }),
  Schema.Struct({
    kind: Schema.Literal("order.access_revoke"), sessionDigest: Digest, formTokenDigest: Digest, purpose: Purpose, actor: Schema.String, nowSeconds: Seconds, number: Integer,
  }),
  Schema.Struct({ kind: Schema.Literal("order.lookup"), number: Integer, email: LookupEmail, nowSeconds: Seconds }),
] as const;

export const EmailResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("email.begin"), outcome: Schema.Literal("send"), attempts: Integer, facts: EmailFactsSchema }),
  Schema.Struct({ kind: Schema.Literal("email.begin"), outcome: Schema.Literal("skip"), reason: Schema.Literals(["not_found", "superseded", "sent", "failed", "window_closed"]) }),
  Schema.Struct({ kind: Schema.Literal("email.settle"), changed: Schema.Boolean }),
  Schema.Struct({ kind: Schema.Literal("email.resend"), outcome: Schema.Literals(["applied", "session_invalid", "token_invalid", "not_found", "not_resendable"]) }),
  Schema.Struct({ kind: Schema.Literal("order.access_revoke"), outcome: Schema.Literal("applied"), revoked: Integer }),
  Schema.Struct({ kind: Schema.Literal("order.access_revoke"), outcome: Schema.Literals(["session_invalid", "token_invalid", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("order.lookup") }),
] as const;

export const EmailQuerySchemas = [
  Schema.Struct({ kind: Schema.Literal("order.access"), accessDigest: Digest, nowSeconds: Seconds }),
] as const;

export const EmailQueryResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("order.access"), number: Schema.NullOr(Integer) }),
] as const;

export type EmailCommand = (typeof EmailCommandSchemas)[number]["Type"];
export type EmailCommandResult = (typeof EmailResultSchemas)[number]["Type"];
export type EmailQuery = (typeof EmailQuerySchemas)[number]["Type"];
export type EmailQueryResult = (typeof EmailQueryResultSchemas)[number]["Type"];
