function cartRejection(error: Error): CartRejection | undefined {
  const reason = (error as { readonly reason?: unknown }).reason;
  return CART_REJECTIONS.find((candidate) => candidate === reason);
}
class NotFound extends Error { readonly _tag = "StorefrontNotFound"; }
class MethodError extends Error {
  readonly allow: string;
  constructor(allow: string) { super("Method not allowed"); this.allow = allow; }
}
