    this.#localHTTP = options.origin.scheme === "http";
    this.#store = options.store;
    this.#revision = options.revision;
    this.#render = options.render;
    this.#compressor = options.compressor;
    this.admission = options.admission ?? unlimitedAdmission;
    this.events = options.events ?? null;
    this.#pages = options.pages;
    this.#requestTarget = options.rawRequestTarget;
    this.#headers = securityHeaders(this.#origin, options.imageHosts);
    this.#logger = options.logger;
    this.#operation = options.operation;
    this.#admin = options.admin;
    this.#checkout = options.checkout === undefined ? undefined : new Checkout(options.checkout);
    this.#webhook = options.webhook;
    this.#imageHosts = options.imageHosts ?? [];
