    const catalog = await this.#catalog(signal);
    const cached = this.#pages?.get(revision.id, catalog.cacheVersion, key);
    if (this.#pages !== undefined) this.#operation?.(cached === undefined ? "page-cache.miss" : "page-cache.hit", {});
    if (cached !== undefined) return cached;
    const response = await build(catalog);
    if (response.status === 200 && response.cache === "public") this.#pages?.put(revision.id, catalog.cacheVersion, key, response);
