import { EmailValidationError, type OutgoingEmail } from "./message.ts";

export const ResendDefaultBaseUrl = "https://api.resend.com";
export const IdempotencyWindowMs = 24 * 60 * 60 * 1000;
export const MaxIdempotencyKeyLength = 256;
export const DefaultSendTimeoutMs = 15_000;

const tenantIdPattern = /^[a-z0-9][a-z0-9-]{0,62}$/;
const messageIdPattern = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/;
const maxResponseChars = 64 * 1024;

export interface EmailClock {
  now(): number;
}

export type FetchFunction = (input: string, init: RequestInit) => Promise<Response>;

export type RejectionReason = "request" | "configuration";

export type UnknownCause = "timeout" | "transport" | "response_lost" | "malformed_response";

export interface ProviderError {
  readonly status: number;
  readonly name: string;
  readonly message: string;
}

export type SendOutcome =
  | { readonly kind: "sent"; readonly providerId: string; readonly at: number }
  | { readonly kind: "permanent"; readonly reason: RejectionReason; readonly error: ProviderError; readonly at: number }
  | { readonly kind: "retryable"; readonly error: ProviderError; readonly retryAfterMs: number | null; readonly at: number }
  | { readonly kind: "unknown"; readonly cause: UnknownCause; readonly at: number }
  | { readonly kind: "idempotency_mismatch"; readonly error: ProviderError; readonly at: number }
  | { readonly kind: "idempotency_in_flight"; readonly error: ProviderError; readonly retryAfterMs: number | null; readonly at: number };

export interface ResendOptions {
  readonly apiKey: string;
  readonly tenantId: string;
  readonly fetch: FetchFunction;
  readonly clock: EmailClock;
  readonly baseUrl?: string;
  readonly timeoutMs?: number;
}

export interface ResendClient {
  send(messageId: string, email: OutgoingEmail): Promise<SendOutcome>;
}

export function isLoopbackHostname(hostname: string): boolean {
  const host = hostname.toLowerCase();
  if (host === "localhost" || host.endsWith(".localhost") || host === "[::1]") return true;
  const octets = host.split(".");
  return octets.length === 4 && octets[0] === "127" && octets.every((octet) => /^(?:0|[1-9][0-9]{0,2})$/.test(octet) && Number(octet) <= 255);
}

export function resolveBaseUrl(override: string | undefined): string {
  if (override === undefined) return ResendDefaultBaseUrl;
  let url: URL;
  try {
    url = new URL(override);
  } catch {
    throw new EmailValidationError("base URL is not a URL");
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") throw new EmailValidationError("base URL must be http or https");
  if (!isLoopbackHostname(url.hostname)) throw new EmailValidationError("base URL override is accepted only for loopback hosts");
  if (url.username !== "" || url.password !== "" || url.search !== "" || url.hash !== "" || url.pathname !== "/") {
    throw new EmailValidationError("base URL must be a bare origin");
  }
  return url.origin;
}

export function idempotencyKey(tenantId: string, messageId: string): string {
  if (!tenantIdPattern.test(tenantId)) throw new EmailValidationError("tenant id is not valid in an idempotency key");
  if (!messageIdPattern.test(messageId)) throw new EmailValidationError("message id is not valid in an idempotency key");
  const key = `${tenantId}:${messageId}`;
  if (key.length > MaxIdempotencyKeyLength) throw new EmailValidationError("idempotency key is longer than 256 characters");
  return key;
}

export function mayRetryUnknownWithSameKey(firstAttemptAt: number, now: number): boolean {
  return now - firstAttemptAt < IdempotencyWindowMs;
}

function parseJsonObject(text: string): Record<string, unknown> | null {
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return null;
  }
  return typeof value === "object" && value !== null && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

function decodeSuccess(text: string): string | null {
  const id = parseJsonObject(text)?.["id"];
  return typeof id === "string" && id.length > 0 ? id : null;
}

function decodeError(status: number, text: string): ProviderError {
  const record = parseJsonObject(text);
  const name = record?.["name"];
  const message = record?.["message"];
  const statusCode = record?.["statusCode"];
  if (typeof name !== "string" || typeof message !== "string" || (statusCode !== undefined && statusCode !== status)) {
    return { status, name: "unrecognized_error_body", message: "response body is not a provider error" };
  }
  return { status, name, message: message.slice(0, 500) };
}

function parseRetryAfterMs(response: Response): number | null {
  const header = response.headers.get("retry-after");
  if (header === null || !/^[0-9]{1,6}$/.test(header)) return null;
  return Number(header) * 1000;
}

function classify(response: Response, text: string, at: number): SendOutcome {
  const status = response.status;
  if (status >= 200 && status < 300) {
    const providerId = decodeSuccess(text);
    return providerId === null ? { kind: "unknown", cause: "malformed_response", at } : { kind: "sent", providerId, at };
  }
  const error = decodeError(status, text);
  if (status === 409) {
    if (error.name === "invalid_idempotent_request") return { kind: "idempotency_mismatch", error, at };
    if (error.name === "concurrent_idempotent_requests") return { kind: "idempotency_in_flight", error, retryAfterMs: parseRetryAfterMs(response), at };
    return { kind: "retryable", error, retryAfterMs: parseRetryAfterMs(response), at };
  }
  if (status === 429 || status >= 500) return { kind: "retryable", error, retryAfterMs: parseRetryAfterMs(response), at };
  if (status === 401 || status === 403) return { kind: "permanent", reason: "configuration", error, at };
  return { kind: "permanent", reason: "request", error, at };
}

export function createResendClient(options: ResendOptions): ResendClient {
  if (options.apiKey.length === 0 || /[\u0000- \u007f]/.test(options.apiKey)) {
    throw new EmailValidationError("api key is empty or contains whitespace or control characters");
  }
  const endpoint = `${resolveBaseUrl(options.baseUrl)}/emails`;
  const timeoutMs = options.timeoutMs ?? DefaultSendTimeoutMs;
  if (!Number.isInteger(timeoutMs) || timeoutMs <= 0) throw new EmailValidationError("timeout must be a positive integer");
  const { fetch: sendRequest, clock } = options;

  return {
    async send(messageId, email) {
      const key = idempotencyKey(options.tenantId, messageId);
      const body = JSON.stringify({
        from: email.from,
        to: [email.to],
        subject: email.subject,
        text: email.text,
        html: email.html,
        ...(email.replyTo === null ? {} : { reply_to: [email.replyTo] }),
      });
      const abort = new AbortController();
      const timer = setTimeout(() => abort.abort(), timeoutMs);
      try {
        let response: Response;
        try {
          response = await sendRequest(endpoint, {
            method: "POST",
            redirect: "manual",
            signal: abort.signal,
            headers: {
              authorization: `Bearer ${options.apiKey}`,
              "content-type": "application/json",
              "idempotency-key": key,
            },
            body,
          });
        } catch {
          return { kind: "unknown", cause: abort.signal.aborted ? "timeout" : "transport", at: clock.now() };
        }
        let text: string;
        try {
          text = await response.text();
          if (text.length > maxResponseChars) throw new RangeError("response body too large");
        } catch {
          return { kind: "unknown", cause: abort.signal.aborted ? "timeout" : "response_lost", at: clock.now() };
        }
        return classify(response, text, clock.now());
      } finally {
        clearTimeout(timer);
      }
    },
  };
}
