import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";
import { FailureClasses, MaxErrorLength } from "./work.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Count = Schema.Int.check(filter<number>((value) => value >= 0 && value <= 1000, "must be an integer from 0 to 1000"));
const Owner = Schema.String.check(filter<string>((value) => /^[A-Za-z0-9_.:-]{1,100}$/.test(value), "must be a lease owner label"));
const KindName = Schema.String.check(filter<string>((value) => /^[a-z_]{3,64}$/.test(value), "must be a work kind name"));
const WorkKey = Schema.String.check(filter<string>((value) => value.length >= 1 && value.length <= 200, "must be 1 to 200 characters"));
const Payload = Schema.String.check(filter<string>((value) => value.length <= 2000, "must be at most 2000 characters"));
const FailureText = Schema.String.check(filter<string>((value) => value.length <= MaxErrorLength, `must be at most ${MaxErrorLength} characters`));
const EventId = Schema.String.check(filter<string>((value) => /^[A-Za-z0-9_]{5,255}$/.test(value), "must be a Stripe event id"));
const EventType = Schema.String.check(filter<string>((value) => value.length >= 1 && value.length <= 100, "must be 1 to 100 characters"));
const ObjectId = Schema.String.check(filter<string>((value) => value.length >= 1 && value.length <= 255, "must be 1 to 255 characters"));
export const MaxWebhookBodyBytes = 512 * 1024;
const RawBody = Schema.String.check(filter<string>((value) => new TextEncoder().encode(value).length <= MaxWebhookBodyBytes, "must be at most 512 KiB"));

export const WorkCommandSchemas = [
  Schema.Struct({ kind: Schema.Literal("work.claim"), owner: Owner, limit: Count, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("work.complete"), id: Integer, owner: Owner, attempts: Count, nowSeconds: Seconds, reschedule: Schema.NullOr(Schema.Struct({ at: Seconds, payload: Payload })) }),
  Schema.Struct({ kind: Schema.Literal("work.fail"), id: Integer, owner: Owner, attempts: Count, nowSeconds: Seconds, failureClass: Schema.Literals(FailureClasses), message: FailureText }),
  Schema.Struct({ kind: Schema.Literal("work.requeue"), id: Integer, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("work.ensure_periodic"), items: Schema.Array(Schema.Struct({ kind: KindName, key: WorkKey })), nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("work.purge"), nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("work.event_processed"), eventId: EventId, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("restore.reconciled"), nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("restore.resume"), nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("webhook.ingest"), eventId: EventId, eventType: EventType, objectId: ObjectId, eventCreatedAt: Seconds, subscribed: Schema.Boolean, rawBody: RawBody, nowSeconds: Seconds }),
] as const;

export const WorkQuerySchemas = [
  Schema.Struct({ kind: Schema.Literal("work.next") }),
  Schema.Struct({ kind: Schema.Literal("work.dead") }),
  Schema.Struct({ kind: Schema.Literal("work.provider_event"), eventId: EventId }),
  Schema.Struct({ kind: Schema.Literal("restore.targets") }),
  Schema.Struct({ kind: Schema.Literal("operations.status"), nowSeconds: Seconds }),
] as const;

const ClaimedItem = Schema.Struct({ id: Integer, kind: KindName, key: WorkKey, payload: Payload, attempts: Count });
export type ClaimedWorkItem = typeof ClaimedItem.Type;
const DeadItem = Schema.Struct({ id: Integer, kind: KindName, key: WorkKey, attempts: Count, failureClass: Schema.NullOr(Schema.Literals(FailureClasses)), lastError: Schema.NullOr(Schema.String), updatedAt: Seconds });
export type DeadWorkItem = typeof DeadItem.Type;

export const WorkResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("work.claim"), items: Schema.Array(ClaimedItem), dead: Count }),
  Schema.Struct({ kind: Schema.Literal("work.complete"), outcome: Schema.Literals(["completed", "lost"]) }),
  Schema.Struct({ kind: Schema.Literal("work.fail"), outcome: Schema.Literals(["retry", "dead", "lost"]), nextRunAt: Schema.NullOr(Seconds) }),
  Schema.Struct({ kind: Schema.Literal("work.requeue"), requeued: Schema.Boolean }),
  Schema.Struct({ kind: Schema.Literal("work.ensure_periodic"), created: Count }),
  Schema.Struct({ kind: Schema.Literal("work.purge"), bodies: Integer, items: Integer }),
  Schema.Struct({ kind: Schema.Literal("work.event_processed"), marked: Schema.Boolean }),
  Schema.Struct({ kind: Schema.Literal("restore.reconciled"), marked: Schema.Boolean }),
  Schema.Struct({ kind: Schema.Literal("restore.resume"), outcome: Schema.Literals(["resumed", "not_held", "unreconciled"]) }),
  Schema.Struct({ kind: Schema.Literal("webhook.ingest"), outcome: Schema.Literals(["stored", "duplicate"]) }),
] as const;

export const StalledRefundSeconds = 24 * 3600;

const Backlog = Schema.Struct({ count: Schema.Int, oldestAgeSeconds: Schema.NullOr(Seconds) });
export type Backlog = typeof Backlog.Type;
export const OperationsStatus = Schema.Struct({
  held: Schema.Boolean,
  pendingPayments: Backlog,
  unknownOperations: Backlog,
  unprocessedEvents: Backlog,
  dueWork: Backlog,
  deadWork: Backlog,
  openRefunds: Backlog,
  stalledRefunds: Schema.Int,
});
export type OperationsStatus = typeof OperationsStatus.Type;

const RestoredPayment = Schema.Struct({ intentId: ObjectId, state: Schema.String });
const RestoredRefund = Schema.Struct({ id: Integer, intentId: ObjectId, state: Schema.String });

export const WorkQueryResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("work.next"), nextAt: Schema.NullOr(Seconds) }),
  Schema.Struct({ kind: Schema.Literal("work.dead"), items: Schema.Array(DeadItem) }),
  Schema.Struct({
    kind: Schema.Literal("work.provider_event"),
    event: Schema.NullOr(Schema.Struct({ eventId: EventId, eventType: EventType, objectId: ObjectId, eventCreatedAt: Seconds, receivedAt: Seconds, processedAt: Schema.NullOr(Seconds) })),
  }),
  Schema.Struct({
    kind: Schema.Literal("restore.targets"),
    held: Schema.Boolean,
    reconciledAt: Schema.NullOr(Seconds),
    payments: Schema.Array(RestoredPayment),
    refunds: Schema.Array(RestoredRefund),
  }),
  Schema.Struct({ kind: Schema.Literal("operations.status"), nowSeconds: Seconds, status: OperationsStatus }),
] as const;
