import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const NullableText = Schema.NullOr(Text);

export const workRowSchemas = {
  ListClaimableWork: Schema.Struct({ id: Integer, kind: Text, unique_key: Text, payload: Text, attempts: Integer }),
  GetNextWorkAt: Schema.Struct({ next_at: Schema.NullOr(Integer) }),
  ListDeadWork: Schema.Struct({ id: Integer, kind: Text, unique_key: Text, attempts: Integer, failure_class: NullableText, last_error: NullableText, updated_at: Integer }),
  CountWorkByState: Schema.Struct({ state: Text, n: Integer }),
  GetRestoreHold: Schema.Struct({ payload: Text }),
  ListRestorePayments: Schema.Struct({ payment_intent_id: Text, state: Text }),
  ListRestoreRefunds: Schema.Struct({ id: Integer, payment_intent_id: Text, state: Text }),
  GetOperationsStatus: Schema.Struct({
    pending_payments: Integer, pending_payments_since: Schema.NullOr(Integer), unknown_operations: Integer, unknown_operations_since: Schema.NullOr(Integer),
    unprocessed_events: Integer, unprocessed_events_since: Schema.NullOr(Integer), due_work: Integer, due_work_since: Schema.NullOr(Integer),
    dead_work: Integer, dead_work_since: Schema.NullOr(Integer), open_refunds: Integer, open_refunds_since: Schema.NullOr(Integer), stalled_refunds: Integer, held: Integer,
  }),
  GetProviderEvent: Schema.Struct({
    stripe_event_id: Text, event_type: Text, object_id: Text, event_created_at: Integer, received_at: Integer, processed_at: Schema.NullOr(Integer),
  }),
} as const;

export const workWriteQueries = [
  "ClaimWorkItem", "CompleteWorkItem", "RescheduleWorkItem", "FailWorkItem", "KillWorkItem", "RequeueWorkItem", "EnsureWorkItem",
  "DeleteSucceededWork", "InsertProviderEvent", "MarkProviderEventProcessed", "PurgeProviderEventBodies",
  "MarkRestoreReconciled", "ReleaseRestoreHold",
] as const;
