import type { AdminBackend } from "../admin/backend.ts";
import { isWorkKind, type OperationHook } from "../observe/operations.ts";
import { ClaimBatch, failureOf, WorkError } from "./work.ts";
import type { ClaimedWorkItem } from "./work_operations.ts";

export type WorkItem = ClaimedWorkItem;

export interface WorkContext {
  readonly backend: AdminBackend;
  readonly nowSeconds: () => number;
  readonly signal: AbortSignal | undefined;
}

export interface PeriodicResult {
  readonly payload: string;
}

export type WorkHandler = (item: WorkItem, context: WorkContext) => Promise<PeriodicResult | void>;

export interface WorkKindOptions {
  readonly periodicSeconds?: number;
}

interface Registered {
  readonly handler: WorkHandler;
  readonly periodicSeconds: number | null;
}

export const periodicKey = (kind: string): string => `periodic:${kind}`;

export class WorkRegistry {
  readonly #kinds = new Map<string, Registered>();

  register(kind: string, handler: WorkHandler, options: WorkKindOptions = {}): this {
    if (!/^[a-z_]{3,64}$/.test(kind)) throw new RangeError(`work: ${JSON.stringify(kind)} is not a valid work kind name`);
    if (this.#kinds.has(kind)) throw new Error(`work: kind ${kind} is already registered`);
    const periodicSeconds = options.periodicSeconds ?? null;
    if (periodicSeconds !== null && (!Number.isSafeInteger(periodicSeconds) || periodicSeconds < 60)) throw new RangeError("work: a periodic kind needs an interval of at least 60 seconds");
    this.#kinds.set(kind, { handler, periodicSeconds });
    return this;
  }

  kinds(): readonly string[] {
    return [...this.#kinds.keys()];
  }

  handler(kind: string): WorkHandler | undefined {
    return this.#kinds.get(kind)?.handler;
  }

  periodicSeconds(kind: string): number | null {
    return this.#kinds.get(kind)?.periodicSeconds ?? null;
  }

  periodicItems(): readonly { readonly kind: string; readonly key: string }[] {
    return [...this.#kinds].filter(([, registered]) => registered.periodicSeconds !== null).map(([kind]) => ({ kind, key: periodicKey(kind) }));
  }
}

export interface RunOptions {
  readonly backend: AdminBackend;
  readonly registry: WorkRegistry;
  readonly owner: string;
  readonly nowMs: () => number;
  readonly signal?: AbortSignal;
  readonly maxBatches?: number;
  readonly onError?: (item: WorkItem, error: unknown) => void;
  readonly operation?: OperationHook;
}

export interface RunReport {
  readonly succeeded: number;
  readonly retried: number;
  readonly dead: number;
  readonly lost: number;
}

const seconds = (nowMs: () => number): number => Math.floor(nowMs() / 1000);

export async function runDueWork(options: RunOptions): Promise<RunReport> {
  const { backend, registry, owner, signal } = options;
  const nowSeconds = (): number => seconds(options.nowMs);
  const context: WorkContext = { backend, nowSeconds, signal };
  const periodic = registry.periodicItems();
  if (periodic.length > 0) await backend.command({ kind: "work.ensure_periodic", items: periodic, nowSeconds: nowSeconds() }, signal);
  let succeeded = 0, retried = 0, dead = 0, lost = 0;
  for (let batch = 0; batch < (options.maxBatches ?? 50); batch++) {
    signal?.throwIfAborted();
    const claimed = await backend.command({ kind: "work.claim", owner, limit: ClaimBatch, nowSeconds: nowSeconds() }, signal);
    dead += claimed.dead;
    for (const item of claimed.items) {
      signal?.throwIfAborted();
      let result: PeriodicResult | void;
      const startedMs = options.nowMs();
      const ran = (ok: 0 | 1): void => {
        if (options.operation !== undefined && isWorkKind(item.kind)) options.operation(`work.run.${item.kind}`, { ok, durationMs: Math.max(0, Math.round(options.nowMs() - startedMs)) });
      };
      try {
        const handler = registry.handler(item.kind);
        if (handler === undefined) throw new WorkError("blocked", `no handler is registered for work kind ${item.kind}`);
        result = await handler(item, context);
        ran(1);
      } catch (error) {
        if (signal?.aborted === true) throw error;
        ran(0);
        options.onError?.(item, error);
        const failure = failureOf(error);
        const failed = await backend.command({ kind: "work.fail", id: item.id, owner, attempts: item.attempts, nowSeconds: nowSeconds(), failureClass: failure.failureClass, message: failure.message }, signal);
        if (failed.outcome === "retry") retried += 1;
        else if (failed.outcome === "dead") dead += 1;
        else lost += 1;
        continue;
      }
      const interval = registry.periodicSeconds(item.kind);
      const reschedule = interval === null ? null : { at: nowSeconds() + interval, payload: result?.payload ?? item.payload };
      const completed = await backend.command({ kind: "work.complete", id: item.id, owner, attempts: item.attempts, nowSeconds: nowSeconds(), reschedule }, signal);
      if (completed.outcome === "completed") succeeded += 1;
      else lost += 1;
    }
    if (claimed.items.length === 0 && claimed.dead === 0) break;
  }
  return { succeeded, retried, dead, lost };
}
