import { Effect } from "effect";
import { CatalogInputError } from "../storefront/import.ts";
import { DatabaseError, type SQLValue, type SyncTransaction, type Transaction } from "../storefront/persistence.ts";
import { emailSearchDigest } from "./keyed_digest.ts";
import { CommerceTables, MediaTable, RestoreHoldKey, RestoreHoldKind, RestoreHoldLeaseSeconds, type Column, type TableSpec } from "./export_tables.ts";

export type CommerceRow = Readonly<Record<string, string | null>>;
export type CommerceState = Readonly<Record<string, readonly CommerceRow[]>>;

export const CommerceStateTables: readonly TableSpec[] = [MediaTable, ...CommerceTables];

type SqlStep = { readonly kind: "all" | "run"; readonly sql: string; readonly params: readonly SQLValue[] };
type SqlProgram<T> = Generator<SqlStep, T, unknown>;
type Rows = readonly Readonly<Record<string, SQLValue>>[];

function* all(sql: string, params: readonly SQLValue[] = []): SqlProgram<Rows> {
  return (yield { kind: "all", sql, params }) as Rows;
}

function* run(sql: string, params: readonly SQLValue[] = []): SqlProgram<void> {
  yield { kind: "run", sql, params };
}

export function runSqlSync<T>(tx: SyncTransaction, program: SqlProgram<T>): T {
  let next = program.next();
  while (next.done !== true) {
    const step = next.value;
    next = program.next(step.kind === "all" ? tx.all(step.sql, step.params) : tx.run(step.sql, step.params));
  }
  return next.value;
}

export function runSqlEffect<T>(tx: Transaction, program: SqlProgram<T>): Effect.Effect<T, DatabaseError> {
  return Effect.gen(function* () {
    let next = yield* Effect.try({ try: () => program.next(), catch: (cause) => asDatabaseError(cause) });
    while (next.done !== true) {
      const step = next.value;
      const result: unknown = yield* step.kind === "all" ? tx.all(step.sql, step.params) : tx.run(step.sql, step.params);
      next = yield* Effect.try({ try: () => program.next(result), catch: (cause) => asDatabaseError(cause) });
    }
    return next.value;
  });
}

function asDatabaseError(cause: unknown): DatabaseError {
  return cause instanceof DatabaseError ? cause : new DatabaseError("state: commerce transfer failed", cause);
}

const Int64Pattern = /^(?:0|-?[1-9][0-9]{0,18})$/;

function validInt64(value: string): boolean {
  if (!Int64Pattern.test(value)) return false;
  const parsed = BigInt(value);
  return parsed >= -9223372036854775808n && parsed <= 9223372036854775807n;
}

function selectList(table: TableSpec): string {
  return table.columns
    .map((column) => {
      if (column.exportExpression !== undefined) return `${column.exportExpression} AS ${column.name}`;
      if (column.kind === "int") return `CAST(${column.name} AS TEXT) AS ${column.name}`;
      if (column.kind === "blob") return `lower(hex(${column.name})) AS ${column.name}`;
      return column.name;
    })
    .join(", ");
}

const exportSql = (table: TableSpec): string =>
  `SELECT ${selectList(table)} FROM ${table.name}${table.where === undefined ? "" : ` WHERE ${table.where}`} ORDER BY ${table.orderBy}`;

function exportedCell(table: TableSpec, column: Column, value: SQLValue | undefined): string | null {
  if (value === null) {
    if (!column.nullable) throw new DatabaseError(`state: ${table.name}.${column.name} is NULL but not nullable`);
    return null;
  }
  if (typeof value !== "string") throw new DatabaseError(`state: ${table.name}.${column.name} did not export as text`);
  return value;
}

export function* exportCommerce(): SqlProgram<CommerceState> {
  const state: Record<string, readonly CommerceRow[]> = {};
  for (const table of CommerceStateTables) {
    const rows = yield* all(exportSql(table));
    state[table.name] = rows.map((row) => Object.fromEntries(table.columns.map((column) => [column.name, exportedCell(table, column, row[column.name])])));
  }
  return state;
}

export function emptyCommerceState(): CommerceState {
  return Object.fromEntries(CommerceStateTables.map((table) => [table.name, []]));
}

function validateRow(table: TableSpec, row: unknown, index: number): CommerceRow {
  const label = `state: commerce.${table.name}[${index}]`;
  if (typeof row !== "object" || row === null || Array.isArray(row)) throw new CatalogInputError(`${label} must be an object`);
  const record = row as Record<string, unknown>;
  const names = new Set(table.columns.map((column) => column.name));
  for (const key of Object.keys(record)) if (!names.has(key)) throw new CatalogInputError(`${label} has unknown column ${JSON.stringify(key)}`);
  const ordered: Record<string, string | null> = {};
  for (const column of table.columns) {
    const value = record[column.name];
    if (value === undefined) throw new CatalogInputError(`${label} is missing column ${column.name}`);
    if (value === null) {
      if (!column.nullable) throw new CatalogInputError(`${label}.${column.name} must not be null`);
      ordered[column.name] = null;
      continue;
    }
    if (typeof value !== "string") throw new CatalogInputError(`${label}.${column.name} must be a string`);
    if (column.kind === "int" && !validInt64(value)) throw new CatalogInputError(`${label}.${column.name} must be a canonical int64 string`);
    if (column.kind === "blob" && !/^(?:[0-9a-f]{2})*$/.test(value)) throw new CatalogInputError(`${label}.${column.name} must be lowercase hex`);
    ordered[column.name] = value;
  }
  return ordered;
}

export function validateCommerceState(input: unknown): CommerceState {
  if (typeof input !== "object" || input === null || Array.isArray(input)) throw new CatalogInputError("state: commerce must be an object");
  const record = input as Record<string, unknown>;
  const names = new Set(CommerceStateTables.map((table) => table.name));
  for (const key of Object.keys(record)) if (!names.has(key)) throw new CatalogInputError(`state: commerce has unknown table ${JSON.stringify(key)}`);
  const state: Record<string, readonly CommerceRow[]> = {};
  for (const table of CommerceStateTables) {
    const rows = record[table.name];
    if (!Array.isArray(rows)) throw new CatalogInputError(`state: commerce.${table.name} must be an array`);
    state[table.name] = rows.map((row, index) => validateRow(table, row, index));
  }
  if ((state["work_items"] ?? []).some((row) => row["unique_key"] === RestoreHoldKey)) throw new CatalogInputError(`state: work item key ${RestoreHoldKey} is reserved`);
  return state;
}

function hexToBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let index = 0; index < hex.length; index += 2) bytes[index / 2] = Number.parseInt(hex.slice(index, index + 2), 16);
  return bytes;
}

const placeholder = (column: Column): string => (column.kind === "int" ? "CAST(? AS INTEGER)" : "?");

function insertSql(table: TableSpec): string {
  return `INSERT INTO ${table.name} (${table.columns.map((column) => column.name).join(", ")}) VALUES (${table.columns.map(placeholder).join(", ")})`;
}

function bind(table: TableSpec, row: CommerceRow): readonly SQLValue[] {
  return table.columns.map((column) => {
    const value = row[column.name] ?? null;
    return value !== null && column.kind === "blob" ? hexToBytes(value) : value;
  });
}

function* insertRows(table: TableSpec, rows: readonly CommerceRow[]): SqlProgram<void> {
  const sql = insertSql(table);
  for (const row of rows) yield* run(sql, bind(table, row));
}

const NotStagedTables = new Set(["shop_settings", "shop_profile", "shop_pages", "cart_revisions", "line_fulfillment"]);

export function* assertCommerceTargetEmpty(state: CommerceState): SqlProgram<void> {
  if ((state["work_items"] ?? []).length > 0) yield* run("DELETE FROM work_items WHERE unique_key LIKE 'periodic:%'");
  for (const table of CommerceTables) {
    if (NotStagedTables.has(table.name) || (state[table.name] ?? []).length === 0) continue;
    const [row] = yield* all(`SELECT EXISTS (SELECT 1 FROM ${table.name}) AS present`);
    if (row?.["present"] !== 0 && row?.["present"] !== 0n) throw new CatalogInputError(`state: cannot restore ${table.name}: the target already has rows in it`);
  }
}

export function* clearMedia(): SqlProgram<void> {
  yield* run("DELETE FROM media_assets");
}

export function* importMedia(state: CommerceState): SqlProgram<void> {
  const rows = state[MediaTable.name] ?? [];
  yield* insertRows(MediaTable, rows.filter((row) => row["card_id"] === null));
  yield* insertRows(MediaTable, rows.filter((row) => row["card_id"] !== null));
}

export function holdsOutboundWork(state: CommerceState): boolean {
  return ["payments", "provider_operations", "refunds", "work_items"].some((name) => (state[name] ?? []).length > 0);
}

export function* importCommerce(state: CommerceState): SqlProgram<void> {
  yield* assertCommerceTargetEmpty(state);
  for (const table of CommerceTables) {
    const rows = state[table.name] ?? [];
    if (table.name === "shop_settings") {
      for (const row of rows) {
        yield* run(
          "UPDATE shop_settings SET checkout_paused = CAST(? AS INTEGER), max_active_holds = CAST(? AS INTEGER), revision = CAST(? AS INTEGER) WHERE id = CAST(? AS INTEGER)",
          [row["checkout_paused"] ?? null, row["max_active_holds"] ?? null, row["revision"] ?? null, row["id"] ?? null],
        );
      }
    } else if (table.name === "shop_profile") {
      for (const row of rows) {
        yield* run(
          "UPDATE shop_profile SET description = ?, contact_email = ?, contact_phone = ?, revision = CAST(? AS INTEGER), updated_at = CAST(? AS INTEGER) WHERE id = CAST(? AS INTEGER)",
          [row["description"] ?? null, row["contact_email"] ?? null, row["contact_phone"] ?? null, row["revision"] ?? null, row["updated_at"] ?? null, row["id"] ?? null],
        );
      }
    } else if (table.name === "shop_pages") {
      for (const row of rows) {
        yield* run(
          "UPDATE shop_pages SET blocks = ?, revision = CAST(? AS INTEGER), updated_at = CAST(? AS INTEGER) WHERE kind = ?",
          [row["blocks"] ?? null, row["revision"] ?? null, row["updated_at"] ?? null, row["kind"] ?? null],
        );
      }
    } else if (table.name === "cart_revisions") {
      for (const row of rows) {
        yield* run(
          "INSERT INTO cart_revisions (session_hash, revision) VALUES (?, CAST(? AS INTEGER)) ON CONFLICT (session_hash) DO UPDATE SET revision = excluded.revision",
          bind(table, row),
        );
      }
    } else if (table.name === "line_fulfillment") {
      for (const row of rows) {
        if (row["shipped"] === "0" && row["canceled"] === "0" && row["returned"] === "0") continue;
        yield* run(
          "UPDATE line_fulfillment SET shipped = CAST(? AS INTEGER), canceled = CAST(? AS INTEGER), returned = CAST(? AS INTEGER) WHERE order_id = CAST(? AS INTEGER) AND position = CAST(? AS INTEGER)",
          [row["shipped"] ?? null, row["canceled"] ?? null, row["returned"] ?? null, row["order_id"] ?? null, row["position"] ?? null],
        );
      }
    } else {
      yield* insertRows(table, rows);
    }
  }
  yield* indexRestoredOrders(state);
  if (holdsOutboundWork(state)) yield* placeRestoreHold();
}

function* indexRestoredOrders(state: CommerceState): SqlProgram<void> {
  const orders = state["orders"] ?? [];
  if (orders.length === 0) return;
  const [key] = yield* all("SELECT key FROM order_search_key WHERE id = 1");
  if (key === undefined || !(key["key"] instanceof Uint8Array)) throw new DatabaseError("state: the order search key is missing");
  for (const order of orders) {
    const email = order["contact_email"];
    if (email === null || email === undefined) continue;
    yield* run("UPDATE orders SET email_digest = ? WHERE id = CAST(? AS INTEGER)", [emailSearchDigest(key["key"], email), order["id"] ?? null]);
  }
}

function* placeRestoreHold(): SqlProgram<void> {
  yield* run(
    `INSERT INTO work_items (kind, unique_key, payload, state, attempts, next_run_at, lease_owner, lease_expires_at, created_at, updated_at)
     VALUES ('${RestoreHoldKind}', '${RestoreHoldKey}', '{"reconciledAt":null}', 'leased', 0, 0, 'restore', ${RestoreHoldLeaseSeconds}, 0, 0)
     ON CONFLICT (unique_key) DO NOTHING`,
  );
}
