import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const RefundRow = Schema.Struct({
  id: Integer, order_id: Integer, number: Integer, state: Text, amount_minor: Integer, provider_refund_id: Schema.NullOr(Text),
  payment_intent_id: Text, currency_code: Text, created_at: Integer,
});

export const refundRowSchemas = {
  GetRefund: RefundRow,
  GetRefundByProviderId: RefundRow,
  GetNewestRefund: Schema.Struct({ id: Integer }),
  GetRefundTotals: Schema.Struct({ active_minor: Integer, shipping_minor: Integer, shipping_tax_minor: Integer }),
  ListRefundLineQuantities: Schema.Struct({ position: Integer, quantity: Integer }),
} as const;

export const refundWriteQueries = [
  "InsertRefund", "InsertExternalRefund", "InsertRefundLine", "SetRefundState", "AddLineCanceled", "AddLineReturned", "InsertRestock",
] as const;
