// Attribute contexts belong to the checked program, so the renderer cannot
// accidentally treat a URL, srcset candidate, or behavior JSON as plain text.
export type AttributeContext = "attribute" | "url" | "srcset" | "style" | "json" | "meta";
export type TextContext = "text" | "rcdata";
const urlAttributes = new Set("action archive background cite classid codebase data formaction href icon longdesc manifest poster profile src usemap xlink:href xmlns".split(" "));
export function attributeContext(name: string): Exclude<AttributeContext, "json" | "meta"> {
  if (name.startsWith("xmlns:")) return "url";
  const normalized = name.startsWith("data-") ? name.slice(5) : name.includes(":") ? name.slice(name.indexOf(":") + 1) : name;
  if (normalized === "srcset") return "srcset";
  if (normalized === "style") return "style";
  if (urlAttributes.has(normalized) || normalized.includes("src") || normalized.includes("uri") || normalized.includes("url")) return "url";
  return "attribute";
}
export function textContext(tag: string): TextContext { return tag === "textarea" || tag === "title" ? "rcdata" : "text"; }
