import { ADMIN_ROUTES, type AdminRouteName } from "../routes/admin.ts";
import { ROUTES, type RouteName } from "../routes/routes.ts";
import { CART_REJECTIONS, type CartRejection } from "../storefront/errors.ts";

export const RPC_METHODS = ["syncCatalog", "readCart", "addToCart", "setCartQuantity", "removeCartItem"] as const;
export type RpcMethod = (typeof RPC_METHODS)[number];

export const CHECKOUT_REJECTIONS = ["paused", "no-cart", "not-found", "blocked", "expired", "holds-full", "changed", "insufficient-stock"] as const;
export type CheckoutRejection = (typeof CHECKOUT_REJECTIONS)[number];

export const WEBHOOK_REJECTIONS = ["method", "too-large", "unreadable", "unconfigured", "invalid", "unstored"] as const;
export type WebhookRejection = (typeof WEBHOOK_REJECTIONS)[number];

export const WORK_KINDS = [
  "create_session", "hold_expiry", "capture", "cancel_pi", "refund", "periodic_payment_reconcile",
  "provider_event", "periodic_media_maintenance", "periodic_provider_event_purge", "email_send",
] as const;
export type WorkKind = (typeof WORK_KINDS)[number];

export function isWorkKind(kind: string): kind is WorkKind {
  return (WORK_KINDS as readonly string[]).includes(kind);
}

export const COMMERCE_EXCEPTIONS = ["payment.unknown", "payment.blocked", "work.dead", "inventory.invariant", "email.failed", "provider.error"] as const;
export type CommerceException = (typeof COMMERCE_EXCEPTIONS)[number];

export type CommerceOperation =
  | "checkout.quote"
  | "checkout.accept"
  | `checkout.rejected.${CheckoutRejection}`
  | "payment.handoff"
  | "payment.authorize"
  | "payment.capture"
  | "webhook.accepted"
  | "webhook.duplicate"
  | `webhook.rejected.${WebhookRejection}`
  | `work.run.${WorkKind}`
  | "refund.request"
  | "fulfillment.create"
  | "media.upload"
  | "inventory.conflict";

export type OperationName =
  | `request.${RouteName}`
  | `request.${AdminRouteName}`
  | "request.unmatched"
  | "request.asset"
  | `cart.rejected.${CartRejection}`
  | "page-cache.hit"
  | "page-cache.miss"
  | "catalog.load"
  | "catalog.unchanged"
  | "catalog.rejected"
  | `store.rpc.${RpcMethod}`
  | CommerceOperation;

export type CounterName = "status" | "durationMs" | "responseBytes" | "rows" | "textBytes" | "estimatedBytes" | "ok";

export type OperationCounters = Readonly<Partial<Record<CounterName, number>>>;
export type OperationHook = (name: OperationName, counters: OperationCounters) => void;

const requestCounters: readonly CounterName[] = ["status", "durationMs", "responseBytes"];

function buildCatalog(): ReadonlyMap<OperationName, readonly CounterName[]> {
  const catalog = new Map<OperationName, readonly CounterName[]>();
  for (const route of Object.keys(ROUTES) as RouteName[]) catalog.set(`request.${route}`, requestCounters);
  for (const route of Object.keys(ADMIN_ROUTES) as AdminRouteName[]) catalog.set(`request.${route}`, ["status", "durationMs"]);
  catalog.set("request.unmatched", requestCounters);
  catalog.set("request.asset", ["status"]);
  for (const reason of CART_REJECTIONS) catalog.set(`cart.rejected.${reason}`, ["status"]);
  catalog.set("page-cache.hit", []);
  catalog.set("page-cache.miss", []);
  catalog.set("catalog.load", ["rows", "textBytes", "estimatedBytes", "durationMs"]);
  catalog.set("catalog.unchanged", []);
  catalog.set("catalog.rejected", []);
  for (const method of RPC_METHODS) catalog.set(`store.rpc.${method}`, ["durationMs", "ok"]);
  for (const name of ["checkout.quote", "checkout.accept", "payment.handoff", "payment.authorize", "payment.capture", "webhook.accepted", "webhook.duplicate", "refund.request", "fulfillment.create", "media.upload", "inventory.conflict"] as const) catalog.set(name, []);
  for (const reason of CHECKOUT_REJECTIONS) catalog.set(`checkout.rejected.${reason}`, []);
  for (const reason of WEBHOOK_REJECTIONS) catalog.set(`webhook.rejected.${reason}`, ["status"]);
  for (const kind of WORK_KINDS) catalog.set(`work.run.${kind}`, ["ok", "durationMs"]);
  return catalog;
}

export const OPERATION_COUNTERS: ReadonlyMap<OperationName, readonly CounterName[]> = buildCatalog();

export function operationNames(): readonly OperationName[] {
  return [...OPERATION_COUNTERS.keys()];
}

export function assertValidOperation(name: string, counters: Readonly<Record<string, number>>): asserts name is OperationName {
  const allowed = OPERATION_COUNTERS.get(name as OperationName);
  if (allowed === undefined) throw new Error(`observe: unknown operation ${JSON.stringify(name)}`);
  for (const [counter, value] of Object.entries(counters)) {
    if (!(allowed as readonly string[]).includes(counter)) throw new Error(`observe: operation ${name} has no counter ${JSON.stringify(counter)}`);
    if (!Number.isSafeInteger(value) || value < 0) throw new Error(`observe: operation ${name} counter ${counter} is not a non-negative integer`);
  }
}

export function isolateOperationHook(hook: OperationHook, reportFailure: (error: unknown) => void): OperationHook {
  return (name, counters) => {
    try {
      hook(name, counters);
    } catch (error) {
      reportFailure(error);
    }
  };
}

export interface OperationTotals {
  readonly count: number;
  readonly counters: Readonly<Partial<Record<CounterName, number>>>;
}

export class OperationRecorder {
  readonly #totals = new Map<OperationName, { count: number; counters: Partial<Record<CounterName, number>> }>();
  readonly hook: OperationHook = (name, counters) => {
    assertValidOperation(name, counters as Readonly<Record<string, number>>);
    let entry = this.#totals.get(name);
    if (entry === undefined) { entry = { count: 0, counters: {} }; this.#totals.set(name, entry); }
    entry.count += 1;
    for (const [counter, value] of Object.entries(counters) as [CounterName, number][]) entry.counters[counter] = (entry.counters[counter] ?? 0) + value;
  };
  count(name: OperationName): number { return this.#totals.get(name)?.count ?? 0; }
  total(name: OperationName, counter: CounterName): number { return this.#totals.get(name)?.counters[counter] ?? 0; }
  snapshot(): ReadonlyMap<OperationName, OperationTotals> {
    return new Map([...this.#totals].map(([name, entry]) => [name, { count: entry.count, counters: { ...entry.counters } }]));
  }
  reset(): void { this.#totals.clear(); }
}
