import type { CancelRejection, LinePlanRejection } from "../commerce/cancel.ts";
import { validRefundReason, type RefundRejection } from "../commerce/refund.ts";
import type { RestockRejection } from "../commerce/refund_restock.ts";
import { principalId } from "../identity/principal.ts";
import { reauthRequired } from "../identity/policy.ts";
import { adminPath } from "../routes/admin.ts";
import { parseToken, tokenDigest } from "../session/session.ts";
import { BadInput } from "../web/decode.ts";
import type { AdminBackend } from "./backend.ts";
import { readCatalogForm } from "./catalog_form.ts";
import { digestHex } from "./operations.ts";
import type { OrdersAuth } from "./orders_handler.ts";
import { redirect } from "./response.ts";
import type { FieldErrors, Notice } from "./pages.ts";
import { actionPurpose, type ActionInput, type OrderAction } from "./refunds_pages.ts";

export const error = (message: string): Notice => ({ kind: "error", message });
export const unverified = error("This form could not be verified. Review the current values and submit again.");
export const spent = error("This form was already submitted or has expired, so nothing was changed. Review the current values and submit again if needed.");
export const changed = error("This order changed after you opened the form, so nothing was changed. Compare the values and submit again.");

export const ActionDoneNotices: Readonly<Record<string, string>> = {
  refund: "Refund requested. It is sent to Stripe in the background, and its status is shown below.",
  cancel: "Items canceled.",
  "cancel-void": "Items canceled. The payment authorization is being released at Stripe.",
  return: "Return recorded.",
  restock: "Items put back in stock.",
  "email-resent": "Email queued to send again.",
  "access-revoked": "Every customer order link was revoked.",
};

const rejectionMessages: Readonly<Record<RefundRejection | CancelRejection | LinePlanRejection | RestockRejection, string>> = {
  not_captured: "Only a captured payment can be refunded.",
  invalid_reason: "Enter a reason of at most 500 characters.",
  empty_refund: "Choose at least one item or the shipping to refund.",
  empty_request: "Enter a quantity for at least one item.",
  too_many_lines: "That request has too many items.",
  unknown_line: "That item is not on this order.",
  duplicate_line: "An item appeared twice in the form.",
  invalid_quantity: "Enter a whole number of at least 1.",
  exceeds_line_quantity: "A quantity is more than is left to refund for that item.",
  exceeds_unfulfilled: "A quantity is more than is left unshipped.",
  exceeds_shipped: "A quantity is more than was shipped and not yet returned.",
  exceeds_returned: "A quantity is more than was returned and not yet restocked.",
  no_shipping_left: "The shipping has already been refunded.",
  exceeds_balance: "That is more than is left to refund on this payment, for example because of a refund made in the Stripe dashboard.",
  payment_settling: "Stripe is still capturing this payment, so it cannot be canceled yet. Try again in a moment.",
  partial_before_capture: "This payment is not captured yet, so it can only be canceled in full. Cancel every item.",
  untracked_line: "That item is not stock-tracked, so there is no stock to restore.",
};

const quantityShape = /^(?:0|[1-9][0-9]{0,9})$/;
const revisionShape = /^[1-9][0-9]{0,18}$/;
const MaxInt64 = 9223372036854775807n;

export interface ActionShown {
  readonly status: number;
  readonly notice: Notice | null;
  readonly errors: FieldErrors;
  readonly conflict: boolean;
  readonly inputs: Readonly<Partial<Record<OrderAction, ActionInput>>>;
}

export interface RefundsHandlerOptions {
  readonly backend: AdminBackend;
  readonly tenantId: string;
  readonly nowSeconds: () => number;
  readonly clearCookies: () => readonly string[];
  readonly redraw: (request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal, shown: ActionShown) => Promise<Response>;
  readonly notFound: (request: Request, auth: OrdersAuth) => Response;
}

function field(action: OrderAction, key: string): string {
  return `${action}.${key}`;
}

function rejectionField(action: OrderAction, rejection: string): string {
  if (rejection === "invalid_reason") return field(action, "reason");
  return field(action, "quantities");
}

export function createRefundsHandler(options: RefundsHandlerOptions): { submit(action: OrderAction, request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> } {
  const { backend } = options;
  const orderPath = (number: bigint): string => adminPath("admin-order", [number.toString()]);

  async function submit(action: OrderAction, request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> {
    if (reauthRequired(auth.session.authenticatedAt, options.nowSeconds())) {
      return redirect(`${adminPath("admin-reauth")}?return=${encodeURIComponent(orderPath(number))}`);
    }
    const fields = await readCatalogForm(request, (key) => key === "form_token" || key === "revision" || key === "reason" || (action === "refund" && key === "shipping") || /^qty_[0-9]{1,6}$/.test(key), signal);
    const quantities = new Map([...fields].filter(([key]) => key.startsWith("qty_")).map(([key, value]) => [key, value.trim()] as const));
    const input: ActionInput = { quantities, shipping: fields.get("shipping") === "1", reason: (fields.get("reason") ?? "").trim() };
    const inputs = { [action]: input };
    const show = (status: number, notice: Notice, errors: FieldErrors = {}, conflict = false) => options.redraw(request, auth, number, signal, { status, notice, errors, conflict, inputs });

    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await show(409, unverified, {}, true);
    const rawRevision = fields.get("revision") ?? "";
    if (!revisionShape.test(rawRevision) || BigInt(rawRevision) > MaxInt64) throw new BadInput("The form is missing its revision.");

    const errors: Record<string, string> = {};
    const lines: { position: bigint; quantity: bigint }[] = [];
    for (const [key, raw] of quantities) {
      if (raw !== "" && !quantityShape.test(raw)) { errors[field(action, key)] = "Enter a whole number, zero or more."; continue; }
      const quantity = raw === "" ? 0n : BigInt(raw);
      if (quantity > 0n) lines.push({ position: BigInt(key.slice(4)), quantity });
    }
    if (!validRefundReason(input.reason)) errors[field(action, "reason")] = rejectionMessages.invalid_reason;
    if (Object.keys(errors).length === 0 && lines.length === 0 && !input.shipping) errors[field(action, "quantities")] = rejectionMessages.empty_request;
    if (Object.keys(errors).length > 0) return await show(422, error("Fix the highlighted fields and submit again."), errors);

    const base = {
      sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: actionPurpose(action, number), actor: principalId(auth.session),
      nowSeconds: options.nowSeconds(), number, expectedRevision: BigInt(rawRevision), lines, reason: input.reason,
    };
    const result = action === "refund" ? await backend.command({ kind: "order.refund", ...base, shipping: input.shipping }, signal)
      : action === "cancel" ? await backend.command({ kind: "order.cancel", ...base, tenantId: options.tenantId }, signal)
      : action === "return" ? await backend.command({ kind: "order.return", ...base }, signal)
      : await backend.command({ kind: "order.restock", ...base }, signal);
    if (result.kind !== `order.${action}`) throw new Error(`admin: ${action} answered ${result.kind}`);
    if (!("outcome" in result)) throw new Error(`admin: ${action} answered without an outcome`);

    switch (result.outcome) {
      case "applied": {
        const done = action === "cancel" && "voided" in result && result.voided ? "cancel-void" : action;
        return redirect(`${orderPath(number)}?done=${done}`);
      }
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "not_found": return options.notFound(request, auth);
      case "token_invalid": return await show(409, spent, {}, true);
      case "stale": return await show(409, changed, {}, true);
      case "rejected": {
        if (!("rejection" in result)) throw new Error(`admin: ${action} was rejected without a reason`);
        const message = rejectionMessages[result.rejection];
        const blocked = result.rejection === "payment_settling" || result.rejection === "not_captured";
        return await show(blocked ? 409 : 422, error(message), blocked ? {} : { [rejectionField(action, result.rejection)]: message });
      }
    }
  }

  return { submit };
}
