import { formatMoney } from "../catalog/money.ts";
import { createEmailContentBuilder, type EmailLink, type InlinePart } from "../email/content.ts";
import type { EmailContent } from "../email/message.ts";
import { routePath } from "../routes/routes.ts";
import type { EmailFacts } from "./email_operations.ts";

export interface RenderedEmail {
  readonly subject: string;
  readonly content: EmailContent;
}

const MaxShopNameInSubject = 80;

function subjectSafe(text: string): string {
  return text.replace(/[\u0000-\u001f\u007f\u0085\u2028\u2029]+/g, " ").trim().slice(0, MaxShopNameInSubject);
}

function itemLabel(title: string, variantLabel: string): string {
  return variantLabel === "" ? title : `${title} - ${variantLabel}`;
}

export function renderEmail(facts: EmailFacts, options: { readonly linkOrigin: string; readonly accessToken: string | null }): RenderedEmail {
  const body = createEmailContentBuilder(options.linkOrigin);
  const money = (minor: bigint): string => formatMoney(minor, facts.currency, facts.exponent);
  const shop = subjectSafe(facts.shopName);
  const order = facts.orderNumber === null ? "" : `#${facts.orderNumber}`;
  const orderLink = (): readonly InlinePart[] => {
    if (options.accessToken === null) return [];
    const link: EmailLink = body.link("View your order", routePath("order-access", [options.accessToken]));
    return [link];
  };
  const items = (): void => {
    body.list(facts.lines.map((line) => [`${line.quantity} x ${itemLabel(line.title, line.variantLabel)}: ${money(line.lineTotalMinor)}`]));
  };
  const closing = (): void => {
    const link = orderLink();
    if (link.length > 0) body.paragraph("Follow this private link to see your order at any time. Anyone with the link can see the order, so do not forward this email.", " ", ...link);
    if (shop !== "") body.paragraph(shop);
  };
  const suffix = shop === "" ? "" : ` - ${shop}`;

  switch (facts.kind) {
    case "order_confirmation": {
      body.heading(`Thank you for your order ${order}`);
      body.paragraph(`We received your order ${order} and your payment.`);
      items();
      body.paragraph(`Total: ${money(facts.totalMinor)}`);
      body.paragraph(facts.destination === null ? "Fulfillment: local pickup." : `Shipping to: ${facts.destination}.`);
      closing();
      return { subject: `Order ${order} confirmed${suffix}`, content: body.build() };
    }
    case "shipment": {
      const shipment = facts.shipment;
      if (shipment === null) throw new Error("email: a shipment message has no shipment");
      body.heading(`Your order ${order} has shipped`);
      body.list(shipment.lines.map((line) => [`${line.quantity} x ${itemLabel(line.title, line.variantLabel)}`]));
      body.paragraph(`Carrier: ${shipment.carrier}`);
      if (shipment.trackingNumber !== null) body.paragraph(`Tracking number: ${shipment.trackingNumber}`);
      if (shipment.trackingUrl !== null) body.paragraph(`Tracking page: ${shipment.trackingUrl}`);
      closing();
      return { subject: `Order ${order} has shipped${suffix}`, content: body.build() };
    }
    case "cancellation_voided": {
      body.heading(`Order ${order} was canceled`);
      body.paragraph("The shop canceled this order. Your card was not charged, and the hold on your card is being released. It can take a few days to disappear from your statement.");
      closing();
      return { subject: `Order ${order} canceled${suffix}`, content: body.build() };
    }
    case "cancellation_items": {
      body.heading(`Items on order ${order} were canceled`);
      body.paragraph("The shop canceled some or all of the items that had not shipped. If you were charged for them, the shop will refund you separately and you will get another email when that happens.");
      closing();
      return { subject: `Items canceled on order ${order}${suffix}`, content: body.build() };
    }
    case "refund": {
      if (facts.refundMinor === null) throw new Error("email: a refund message has no amount");
      body.heading(`Refund for order ${order}`);
      body.paragraph(`The shop refunded ${money(facts.refundMinor)} to your original payment method. It can take several business days to appear on your statement.`);
      closing();
      return { subject: `Refund issued for order ${order}${suffix}`, content: body.build() };
    }
    case "late_void": {
      body.heading("Your payment was not completed");
      body.paragraph(`Your payment of ${money(facts.totalMinor)} arrived after the shop had released your items, so the shop canceled it. You were not charged. The hold on your card is being released and can take a few days to disappear. You are welcome to check out again.`);
      closing();
      return { subject: `Your payment was not completed${suffix}`, content: body.build() };
    }
    case "access_link": {
      body.heading(`Your link to order ${order}`);
      body.paragraph("You asked for a new link to your order.");
      closing();
      return { subject: `Your link to order ${order}${suffix}`, content: body.build() };
    }
  }
}
