import { composeEmail, EmailValidationError, type OutgoingEmail } from "../email/message.ts";
import { createResendClient, type FetchFunction, type ResendClient } from "../email/resend.ts";
import { EmailSendKind, settlementFor } from "./email.ts";
import { renderEmail } from "./email_render.ts";
import { accessCredential, MinAccessKeyLength } from "./order_access.ts";
import { WorkError } from "./work.ts";
import type { WorkHandler, WorkRegistry } from "./work_runner.ts";

export interface EmailConnection {
  readonly tenantId: string;
  readonly linkOrigin: string;
  readonly from: string | undefined;
  readonly replyTo: string | null;
  readonly apiBase: string | null;
  readonly resendApiKey: string | undefined;
  readonly accessKey: string | undefined;
  readonly fetch: FetchFunction;
}

export interface EmailSender {
  readonly linkOrigin: string;
  readonly from: string;
  readonly replyTo: string | null;
  readonly accessKey: string;
  readonly client: ResendClient;
}

export interface EmailDependencies {
  readonly sender: () => EmailSender;
}

export function lazyEmailSender(connection: EmailConnection): () => EmailSender {
  let sender: EmailSender | undefined;
  return () => {
    if (sender !== undefined) return sender;
    if (connection.from === undefined) throw new WorkError("blocked", "email is not configured for this shop");
    if (connection.resendApiKey === undefined) throw new WorkError("blocked", "RESEND_API_KEY is not configured for this shop");
    if (connection.accessKey === undefined || connection.accessKey.length < MinAccessKeyLength) {
      throw new WorkError("blocked", `ORDER_ACCESS_KEY is not configured for this shop or is shorter than ${MinAccessKeyLength} characters`);
    }
    try {
      sender = {
        linkOrigin: connection.linkOrigin, from: connection.from, replyTo: connection.replyTo, accessKey: connection.accessKey,
        client: createResendClient({
          apiKey: connection.resendApiKey, tenantId: connection.tenantId, fetch: connection.fetch, clock: { now: () => Date.now() },
          ...(connection.apiBase === null ? {} : { baseUrl: connection.apiBase }),
        }),
      };
    } catch (cause) {
      if (cause instanceof EmailValidationError) throw new WorkError("blocked", cause.message, { cause });
      throw cause;
    }
    return sender;
  };
}

function payloadIds(payload: string): { readonly id: bigint; readonly generation: bigint } {
  let parsed: unknown;
  try { parsed = JSON.parse(payload); } catch (cause) { throw new WorkError("permanent", "email work payload is not JSON", { cause }); }
  const record = typeof parsed === "object" && parsed !== null ? parsed as Record<string, unknown> : {};
  const id = record["message"];
  const generation = record["generation"];
  if (typeof id !== "string" || typeof generation !== "string" || !/^[1-9][0-9]{0,18}$/.test(id) || !/^[1-9][0-9]{0,18}$/.test(generation)) {
    throw new WorkError("permanent", "email work payload has no message and generation");
  }
  return { id: BigInt(id), generation: BigInt(generation) };
}

function emailSendHandler(dependencies: EmailDependencies): WorkHandler {
  return async (item, context) => {
    const { id, generation } = payloadIds(item.payload);
    const sender = dependencies.sender();
    const credential = accessCredential(sender.accessKey, id, generation);
    const begun = await context.backend.command({ kind: "email.begin", id, generation, accessDigest: credential.digestHex, nowSeconds: context.nowSeconds() }, context.signal);
    if (begun.outcome === "skip") return;
    const settle = async (state: "sent" | "failed" | "queued" | "unknown", providerId: string | null, error: string | null): Promise<void> => {
      await context.backend.command({ kind: "email.settle", id, generation, state, providerId, error, nowSeconds: context.nowSeconds() }, context.signal);
    };

    let email: OutgoingEmail;
    try {
      const rendered = renderEmail(begun.facts, { linkOrigin: sender.linkOrigin, accessToken: begun.facts.orderNumber === null ? null : credential.token });
      email = composeEmail({ from: sender.from, to: begun.facts.to, subject: rendered.subject, content: rendered.content, ...(sender.replyTo === null ? {} : { replyTo: sender.replyTo }) });
    } catch (error) {
      if (!(error instanceof EmailValidationError)) throw error;
      await settle("failed", null, error.message.slice(0, 500));
      return;
    }

    const outcome = await sender.client.send(`m${id}g${generation}`, email);
    const settlement = settlementFor(outcome, item.attempts);
    if (settlement.state === "sent") {
      await settle("sent", settlement.providerId, null);
      return;
    }
    await settle(settlement.state, null, settlement.error);
    if (settlement.next === "retry") throw new WorkError("retryable", settlement.error);
    if (settlement.next === "blocked") throw new WorkError("blocked", settlement.error);
  };
}

export function registerEmailKinds(registry: WorkRegistry, dependencies: EmailDependencies): WorkRegistry {
  return registry.register(EmailSendKind, emailSendHandler(dependencies));
}
