import { MaxStockQuantity, quoteExpiresAt } from "./limits.ts";
import { addMinor, checkCheckoutAmount, MoneyRangeError, mulMinor, sumMinor, type CheckoutAmountProblem } from "./money.ts";
import type { PolicyVersion, ShippingPolicy, TaxPolicy } from "./policy.ts";
import { chargeShipping, validateShippingPolicy, type AddressProblem, type Fulfillment, type ShippingPolicyProblem, type ShippingService } from "./shipping.ts";
import { computeTax, validateTaxPolicy, type TaxLine, type TaxPolicyProblem } from "./tax.ts";

export interface QuoteLineInput {
  readonly productId: bigint;
  readonly variantId: bigint;
  readonly title: string;
  readonly variantLabel: string;
  readonly unitPriceMinor: bigint;
  readonly quantity: bigint;
}

export interface QuoteLine extends QuoteLineInput {
  readonly lineTotalMinor: bigint;
}

export interface QuoteInput {
  readonly revision: bigint;
  readonly cartRevision: bigint;
  readonly lines: readonly QuoteLineInput[];
  readonly fulfillment: Fulfillment;
  readonly currency: string;
  readonly taxPolicy: TaxPolicy | null;
  readonly shippingPolicy: ShippingPolicy | null;
  readonly nowSeconds: bigint;
}

export interface Quote {
  readonly revision: bigint;
  readonly cartRevision: bigint;
  readonly currency: string;
  readonly lines: readonly QuoteLine[];
  readonly fulfillment: Fulfillment;
  readonly shippingService: ShippingService;
  readonly shippingFreeByThreshold: boolean;
  readonly taxMode: TaxPolicy["mode"];
  readonly taxLines: readonly TaxLine[];
  readonly merchandiseMinor: bigint;
  readonly shippingMinor: bigint;
  readonly taxMinor: bigint;
  readonly totalMinor: bigint;
  readonly taxPolicyVersion: PolicyVersion;
  readonly shippingPolicyVersion: PolicyVersion;
  readonly createdAtSeconds: bigint;
  readonly expiresAtSeconds: bigint;
}

export type QuoteBlock =
  | { readonly reason: "empty_cart" }
  | { readonly reason: "invalid_line"; readonly lineIndex: number }
  | { readonly reason: "tax_not_configured" }
  | { readonly reason: "shipping_not_configured" }
  | { readonly reason: "tax_policy_invalid"; readonly problems: readonly TaxPolicyProblem[] }
  | { readonly reason: "shipping_policy_invalid"; readonly problems: readonly ShippingPolicyProblem[] }
  | { readonly reason: "tax_region_unsupported"; readonly region: string }
  | { readonly reason: "address_invalid"; readonly problems: readonly AddressProblem[] }
  | { readonly reason: "destination_unsupported"; readonly region: string }
  | { readonly reason: "pickup_unavailable" }
  | { readonly reason: "amount_out_of_range" }
  | { readonly reason: "amount_not_purchasable"; readonly problem: CheckoutAmountProblem };

export type QuoteResult =
  | { readonly ok: true; readonly quote: Quote }
  | { readonly ok: false; readonly block: QuoteBlock };

function blocked(block: QuoteBlock): QuoteResult {
  return { ok: false, block };
}

function lineIsValid(line: QuoteLineInput): boolean {
  return line.quantity >= 1n && line.quantity <= MaxStockQuantity && line.unitPriceMinor >= 0n;
}

export function buildQuote(input: QuoteInput): QuoteResult {
  if (input.lines.length === 0) return blocked({ reason: "empty_cart" });
  const invalid = input.lines.findIndex((line) => !lineIsValid(line));
  if (invalid >= 0) return blocked({ reason: "invalid_line", lineIndex: invalid });
  if (input.taxPolicy === null) return blocked({ reason: "tax_not_configured" });
  if (input.shippingPolicy === null) return blocked({ reason: "shipping_not_configured" });
  const taxProblems = validateTaxPolicy(input.taxPolicy);
  if (taxProblems.length > 0) return blocked({ reason: "tax_policy_invalid", problems: taxProblems });
  const shippingProblems = validateShippingPolicy(input.shippingPolicy);
  if (shippingProblems.length > 0) return blocked({ reason: "shipping_policy_invalid", problems: shippingProblems });

  try {
    const lines: QuoteLine[] = input.lines.map((line) => ({ ...line, lineTotalMinor: mulMinor(line.unitPriceMinor, line.quantity) }));
    const merchandiseMinor = sumMinor(lines.map((line) => line.lineTotalMinor));
    const shipping = chargeShipping(input.shippingPolicy, input.fulfillment, merchandiseMinor);
    if (!shipping.ok) return blocked(shipping.block);
    const tax = computeTax(input.taxPolicy, shipping.charge.taxRegion, {
      lineTotalsMinor: lines.map((line) => line.lineTotalMinor),
      shippingMinor: shipping.charge.amountMinor,
    });
    if (!tax.ok) return blocked(tax.block);
    const totalMinor = addMinor(addMinor(merchandiseMinor, shipping.charge.amountMinor), tax.totalMinor);
    const problem = checkCheckoutAmount(totalMinor, input.currency);
    if (problem !== null) return blocked({ reason: "amount_not_purchasable", problem });
    return {
      ok: true,
      quote: {
        revision: input.revision,
        cartRevision: input.cartRevision,
        currency: input.currency,
        lines,
        fulfillment: input.fulfillment,
        shippingService: shipping.charge.service,
        shippingFreeByThreshold: shipping.charge.freeByThreshold,
        taxMode: input.taxPolicy.mode,
        taxLines: tax.lines,
        merchandiseMinor,
        shippingMinor: shipping.charge.amountMinor,
        taxMinor: tax.totalMinor,
        totalMinor,
        taxPolicyVersion: input.taxPolicy.version,
        shippingPolicyVersion: input.shippingPolicy.version,
        createdAtSeconds: input.nowSeconds,
        expiresAtSeconds: quoteExpiresAt(input.nowSeconds),
      },
    };
  } catch (error) {
    if (error instanceof MoneyRangeError) return blocked({ reason: "amount_out_of_range" });
    throw error;
  }
}

export function quoteIsExpired(quote: Pick<Quote, "expiresAtSeconds">, nowSeconds: bigint): boolean {
  return nowSeconds >= quote.expiresAtSeconds;
}

export type QuoteMismatch =
  | "currency"
  | "cart_revision"
  | "policy_versions"
  | "lines"
  | "fulfillment"
  | "shipping"
  | "tax"
  | "totals";

export type QuoteComparison = { readonly same: true } | { readonly same: false; readonly mismatch: QuoteMismatch };

function canonical(value: unknown): string {
  return JSON.stringify(value, (_key, item: unknown) => (typeof item === "bigint" ? `${item}n` : item));
}

export function compareQuotes(accepted: Quote, recomputed: Quote): QuoteComparison {
  const checks: readonly [QuoteMismatch, unknown, unknown][] = [
    ["currency", accepted.currency, recomputed.currency],
    ["cart_revision", accepted.cartRevision, recomputed.cartRevision],
    ["policy_versions", [accepted.taxPolicyVersion, accepted.shippingPolicyVersion], [recomputed.taxPolicyVersion, recomputed.shippingPolicyVersion]],
    ["lines", accepted.lines, recomputed.lines],
    ["fulfillment", accepted.fulfillment, recomputed.fulfillment],
    ["shipping", [accepted.shippingService, accepted.shippingMinor, accepted.shippingFreeByThreshold], [recomputed.shippingService, recomputed.shippingMinor, recomputed.shippingFreeByThreshold]],
    ["tax", [accepted.taxMode, accepted.taxLines], [recomputed.taxMode, recomputed.taxLines]],
    ["totals", [accepted.merchandiseMinor, accepted.taxMinor, accepted.totalMinor], [recomputed.merchandiseMinor, recomputed.taxMinor, recomputed.totalMinor]],
  ];
  for (const [mismatch, left, right] of checks) {
    if (canonical(left) !== canonical(right)) return { same: false, mismatch };
  }
  return { same: true };
}
