import type { AdminBackend } from "../admin/backend.ts";
import { isSubscribedEventType } from "../commerce/work_kinds.ts";
import { MaxWebhookBodyBytes } from "../commerce/work_operations.ts";
import type { OperationHook, WebhookRejection } from "../observe/operations.ts";
import { verifyWebhook } from "../stripe/index.ts";
import type { WebhookMount } from "./tenant.ts";

export interface WebhookSecrets {
  readonly current: string;
  readonly previous: string | null;
}

export interface WebhookPort {
  readonly backend: Pick<AdminBackend, "command">;
  readonly secrets: () => Promise<WebhookSecrets | null>;
  readonly expectLivemode: boolean;
  readonly now: () => Date;
  readonly onError: (message: string, error: unknown) => void;
  readonly operation?: OperationHook;
}

class BodyTooLarge extends Error {}

async function readBounded(request: Request): Promise<Uint8Array> {
  const declared = request.headers.get("content-length");
  if (declared !== null && (!/^[0-9]+$/.test(declared) || Number(declared) > MaxWebhookBodyBytes)) throw new BodyTooLarge();
  if (request.body === null) return new Uint8Array();
  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > MaxWebhookBodyBytes) {
      await reader.cancel();
      throw new BodyTooLarge();
    }
    chunks.push(value);
  }
  const body = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return body;
}

function plain(status: number, text: string, headers: Headers, extra: Readonly<Record<string, string>> = {}): Response {
  const response = new Headers(headers);
  response.set("Cache-Control", "private, no-store");
  response.set("Content-Type", "text/plain; charset=utf-8");
  for (const [name, value] of Object.entries(extra)) response.set(name, value);
  return new Response(text, { status, headers: response });
}

async function handleWebhook(port: WebhookPort, request: Request, headers: Headers): Promise<Response> {
  const reject = (reason: WebhookRejection, status: number, text: string, extra: Readonly<Record<string, string>> = {}): Response => {
    port.operation?.(`webhook.rejected.${reason}`, { status });
    return plain(status, text, headers, extra);
  };
  if (request.method !== "POST") return reject("method", 405, "Method Not Allowed\n", { Allow: "POST" });
  let rawBody: Uint8Array;
  try {
    rawBody = await readBounded(request);
  } catch (error) {
    if (error instanceof BodyTooLarge) return reject("too-large", 413, "Payload Too Large\n");
    port.onError("webhook body could not be read", error);
    return reject("unreadable", 400, "Bad Request\n");
  }
  let secrets: WebhookSecrets | null;
  try {
    secrets = await port.secrets();
  } catch (error) {
    port.onError("webhook secrets could not be read", error);
    return reject("unconfigured", 500, "Internal Server Error\n");
  }
  if (secrets === null) {
    port.onError("webhook secret is not configured for this shop", new Error("missing STRIPE_WEBHOOK_SECRET"));
    return reject("unconfigured", 500, "Internal Server Error\n");
  }
  const nowMs = port.now().getTime();
  const verified = await verifyWebhook({
    rawBody,
    signatureHeader: request.headers.get("stripe-signature"),
    secrets: secrets.previous === null ? [secrets.current] : [secrets.current, secrets.previous],
    nowSeconds: Math.floor(nowMs / 1000),
    expectLivemode: port.expectLivemode,
  });
  if (!verified.ok) return reject("invalid", 400, "Invalid webhook\n");
  const { event } = verified;
  try {
    await port.backend.command({
      kind: "webhook.ingest",
      eventId: event.id,
      eventType: event.type,
      objectId: event.objectId,
      eventCreatedAt: event.created,
      subscribed: isSubscribedEventType(event.type),
      rawBody: new TextDecoder().decode(rawBody),
      nowSeconds: Math.floor(nowMs / 1000),
    });
  } catch (error) {
    port.onError("webhook event could not be stored", error);
    return reject("unstored", 500, "Internal Server Error\n");
  }
  return plain(200, "ok\n", headers);
}

export function createWebhookMount(port: WebhookPort): WebhookMount {
  return { handle: (request, headers) => handleWebhook(port, request, headers) };
}
