export const MaxStockQuantity = 1_000_000_000n;
export const MaxReasonLength = 500;
export const MaxActorLength = 200;

export const QuoteLifetimeSeconds = 30n * 60n;
export const HoldGraceSeconds = 5n * 60n;

export const MinActiveHolds = 50;
export const MaxActiveHoldsCeiling = 500;
export const DefaultMaxActiveHolds = 100;

export function parseMaxActiveHolds(value: number): number {
  if (!Number.isInteger(value) || value < MinActiveHolds || value > MaxActiveHoldsCeiling) {
    throw new RangeError(`commerce: MaxActiveHolds must be an integer from ${MinActiveHolds} to ${MaxActiveHoldsCeiling}`);
  }
  return value;
}

export function quoteExpiresAt(createdAtSeconds: bigint): bigint {
  return createdAtSeconds + QuoteLifetimeSeconds;
}

export function holdExpiresAt(sessionExpiresAtSeconds: bigint): bigint {
  return sessionExpiresAtSeconds + HoldGraceSeconds;
}

export function hasHoldCapacity(activeHolds: bigint, maxActiveHolds: number): boolean {
  return activeHolds < BigInt(parseMaxActiveHolds(maxActiveHolds));
}
