export const ProviderOperationKinds = ["create_session", "capture", "cancel_pi", "expire_session", "refund"] as const;
export type ProviderOperationKind = (typeof ProviderOperationKinds)[number];

export const ProviderOperationStates = ["pending", "in_flight", "succeeded", "failed", "unknown", "blocked"] as const;
export type ProviderOperationState = (typeof ProviderOperationStates)[number];

const transitions: Readonly<Record<ProviderOperationState, readonly ProviderOperationState[]>> = {
  pending: ["in_flight", "succeeded", "failed", "blocked"],
  in_flight: ["succeeded", "failed", "unknown", "blocked"],
  unknown: ["in_flight", "succeeded", "failed", "blocked"],
  failed: ["in_flight", "blocked"],
  succeeded: [],
  blocked: ["in_flight", "succeeded", "failed"],
};

export const IdempotencyWindowSeconds = 24 * 3600;

export function canTransitionOperation(from: ProviderOperationState, to: ProviderOperationState): boolean {
  return transitions[from].includes(to);
}

export function needsReconciliation(state: ProviderOperationState): boolean {
  return state === "in_flight" || state === "unknown";
}

export function operationIdempotencyKey(tenantId: string, kind: ProviderOperationKind, subjectId: string): string {
  return `nanoshop:${tenantId}:${kind}:${subjectId}`;
}
