import { applyFulfillment, unfulfilled, type FulfillmentAction, type FulfillmentRejection, type LineFulfillment } from "./fulfillment.ts";
import type { PaymentState } from "./payment.ts";

export const MaxOrderLines = 100;

export interface QuantityRequest {
  readonly position: bigint;
  readonly quantity: bigint;
}

export interface LineState {
  readonly position: bigint;
  readonly variantId: bigint;
  readonly tracked: boolean;
  readonly fulfillment: LineFulfillment;
}

export const LinePlanRejections = ["empty_request", "too_many_lines", "unknown_line", "duplicate_line", "invalid_quantity", "exceeds_unfulfilled", "exceeds_shipped", "exceeds_returned", "invalid_reason"] as const satisfies readonly (FulfillmentRejection | "empty_request" | "too_many_lines" | "unknown_line" | "duplicate_line" | "invalid_reason")[];
export type LinePlanRejection = (typeof LinePlanRejections)[number];

export interface PlannedLine {
  readonly position: bigint;
  readonly variantId: bigint;
  readonly tracked: boolean;
  readonly quantity: bigint;
  readonly before: LineFulfillment;
  readonly after: LineFulfillment;
}

export type LinePlan =
  | { readonly ok: true; readonly lines: readonly PlannedLine[] }
  | { readonly ok: false; readonly rejection: LinePlanRejection };

export function planLines(lines: readonly LineState[], request: readonly QuantityRequest[], action: Exclude<FulfillmentAction, "ship">): LinePlan {
  if (request.length === 0) return { ok: false, rejection: "empty_request" };
  if (request.length > MaxOrderLines) return { ok: false, rejection: "too_many_lines" };
  const byPosition = new Map(lines.map((line) => [line.position, line]));
  const seen = new Set<bigint>();
  const planned: PlannedLine[] = [];
  for (const wanted of request) {
    const line = byPosition.get(wanted.position);
    if (line === undefined) return { ok: false, rejection: "unknown_line" };
    if (seen.has(wanted.position)) return { ok: false, rejection: "duplicate_line" };
    seen.add(wanted.position);
    const outcome = applyFulfillment(line.fulfillment, action, wanted.quantity);
    if (!outcome.ok) return { ok: false, rejection: outcome.rejection };
    planned.push({ position: line.position, variantId: line.variantId, tracked: line.tracked, quantity: wanted.quantity, before: line.fulfillment, after: outcome.line });
  }
  return { ok: true, lines: planned };
}

export const CancelRejections = [...LinePlanRejections, "payment_settling", "partial_before_capture"] as const;
export type CancelRejection = (typeof CancelRejections)[number];

export type CancelPaymentAction = "none" | "void";

export type CancelDecision =
  | { readonly ok: true; readonly lines: readonly PlannedLine[]; readonly payment: CancelPaymentAction }
  | { readonly ok: false; readonly rejection: CancelRejection };

export function cancelPaymentAction(state: PaymentState): CancelPaymentAction | "settling" {
  switch (state) {
    case "authorized":
    case "in_review": return "void";
    case "capture_pending":
    case "capture_unknown": return "settling";
    case "captured":
    case "void_unknown":
    case "voided": return "none";
  }
}

export function decideCancel(order: { readonly paymentState: PaymentState; readonly lines: readonly LineState[] }, request: readonly QuantityRequest[]): CancelDecision {
  const action = cancelPaymentAction(order.paymentState);
  if (action === "settling") return { ok: false, rejection: "payment_settling" };
  const plan = planLines(order.lines, request, "cancel");
  if (!plan.ok) return plan;
  if (action === "void") {
    const touched = new Map(plan.lines.map((line) => [line.position, line]));
    const everything = order.lines.every((line) => touched.get(line.position)?.quantity === unfulfilled(line.fulfillment));
    if (!everything) return { ok: false, rejection: "partial_before_capture" };
  }
  return { ok: true, lines: plan.lines, payment: action };
}
