import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Ref = Schema.String.check(filter<string>((value) => /^[0-9a-f]{32}$/.test(value), "must be a 32-character lowercase hex reference"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Text = Schema.String.check(filter<string>((value) => value.length <= 2048, "must be at most 2048 characters"));
const TenantId = Schema.String.check(filter<string>((value) => /^[a-z0-9][a-z0-9-]{0,62}$/.test(value), "must be a tenant id"));

export const AddressSchema = Schema.Struct({
  recipient: Schema.String,
  line1: Schema.String,
  line2: Schema.NullOr(Schema.String),
  city: Schema.String,
  region: Schema.String,
  postalCode: Schema.String,
  country: Schema.String,
});

export const FulfillmentSchema = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("ship"), address: AddressSchema }),
  Schema.Struct({ kind: Schema.Literal("pickup") }),
]);

export const CheckoutBlockReasons = [
  "empty_cart", "invalid_line", "tax_not_configured", "shipping_not_configured", "tax_policy_invalid", "shipping_policy_invalid",
  "tax_region_unsupported", "address_invalid", "destination_unsupported", "pickup_unavailable", "amount_out_of_range",
  "amount_not_purchasable", "line_unavailable", "contact_invalid",
] as const;
export type CheckoutBlockReason = (typeof CheckoutBlockReasons)[number];

export const BlockSchema = Schema.Struct({
  reason: Schema.Literals(CheckoutBlockReasons),
  region: Schema.NullOr(Schema.String),
  title: Schema.NullOr(Schema.String),
  amountProblem: Schema.NullOr(Schema.Literals(["unsupported_currency", "below_minimum", "above_maximum"])),
  problems: Schema.Array(Schema.Struct({ field: Schema.String, problem: Schema.String })),
});
export type CheckoutBlock = typeof BlockSchema.Type;

export const AttemptStates = ["quoted", "accepted", "handed_off", "authorized", "expired", "superseded", "voided_late", "blocked"] as const;

const QuoteLineView = Schema.Struct({ title: Schema.String, variantLabel: Schema.String, unitPriceMinor: Integer, quantity: Integer, lineTotalMinor: Integer });
const TaxLineView = Schema.Struct({ lineIndex: Schema.NullOr(Integer), taxableMinor: Integer, ratePpm: Integer, taxMinor: Integer });

export const QuoteViewSchema = Schema.Struct({
  ref: Ref,
  revision: Integer,
  email: Schema.String,
  fulfillment: FulfillmentSchema,
  shippingZone: Schema.NullOr(Schema.String),
  shippingFreeByThreshold: Schema.Boolean,
  taxMode: Schema.Literals(["rate_table", "no_tax_collected"]),
  currency: Schema.String,
  lines: Schema.Array(QuoteLineView),
  taxLines: Schema.Array(TaxLineView),
  merchandiseMinor: Integer,
  shippingMinor: Integer,
  taxMinor: Integer,
  totalMinor: Integer,
  createdAt: Integer,
  expiresAt: Integer,
});
export type QuoteView = typeof QuoteViewSchema.Type;

export const CheckoutCommandSchema = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("checkout.quote"), sessionDigest: Digest, quoteRef: Ref, email: Text, fulfillment: FulfillmentSchema, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("checkout.requote"), sessionDigest: Digest, fromQuoteRef: Ref, quoteRef: Ref, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("checkout.accept"), tenantId: TenantId, sessionDigest: Digest, quoteRef: Ref, attemptRef: Ref, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("checkout.session.record"), attemptRef: Ref, sessionId: Text, sessionUrl: Text, sessionExpiresAt: Seconds, nowSeconds: Seconds }),
]);
export type CheckoutCommand = typeof CheckoutCommandSchema.Type;

export const CheckoutQuerySchema = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("checkout.form"), sessionDigest: Digest, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("checkout.quote_view"), sessionDigest: Digest, quoteRef: Ref, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("checkout.attempt_view"), attemptRef: Ref }),
]);
export type CheckoutQuery = typeof CheckoutQuerySchema.Type;

const CartLineView = Schema.Struct({
  title: Schema.String,
  variantLabel: Schema.NullOr(Schema.String),
  quantity: Integer,
  unitPriceMinor: Integer,
  status: Schema.Literals(["available", "sold-out", "unpublished"]),
});
export type CheckoutCartLine = typeof CartLineView.Type;

export const QuoteStatuses = ["open", "expired", "changed", "accepted"] as const;

export const CheckoutCommandResultSchema = Schema.Union([
  Schema.Struct({ kind: Schema.Literal("checkout.quote"), outcome: Schema.Literal("quoted"), quoteRef: Ref }),
  Schema.Struct({ kind: Schema.Literal("checkout.quote"), outcome: Schema.Literals(["paused", "no_cart", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("checkout.quote"), outcome: Schema.Literal("blocked"), block: BlockSchema }),
  Schema.Struct({ kind: Schema.Literal("checkout.requote"), outcome: Schema.Literal("quoted"), quoteRef: Ref }),
  Schema.Struct({ kind: Schema.Literal("checkout.requote"), outcome: Schema.Literals(["paused", "no_cart", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("checkout.requote"), outcome: Schema.Literal("blocked"), block: BlockSchema }),
  Schema.Struct({ kind: Schema.Literal("checkout.accept"), outcome: Schema.Literal("accepted"), attemptRef: Ref, state: Schema.Literals(AttemptStates), replay: Schema.Boolean, sessionUrl: Schema.NullOr(Schema.String), quote: QuoteViewSchema }),
  Schema.Struct({ kind: Schema.Literal("checkout.accept"), outcome: Schema.Literals(["paused", "not_found", "expired", "holds_full"]) }),
  Schema.Struct({ kind: Schema.Literal("checkout.accept"), outcome: Schema.Literal("changed"), mismatch: Schema.String }),
  Schema.Struct({ kind: Schema.Literal("checkout.accept"), outcome: Schema.Literal("blocked"), block: BlockSchema }),
  Schema.Struct({ kind: Schema.Literal("checkout.accept"), outcome: Schema.Literal("insufficient_stock"), title: Schema.String }),
  Schema.Struct({ kind: Schema.Literal("checkout.session.record"), outcome: Schema.Literals(["handed_off", "not_recorded"]) }),
]);
export type CheckoutCommandResult = typeof CheckoutCommandResultSchema.Type;

export const CheckoutQueryResultSchema = Schema.Union([
  Schema.Struct({
    kind: Schema.Literal("checkout.form"),
    paused: Schema.Boolean,
    ready: Schema.Boolean,
    offersPickup: Schema.Boolean,
    regions: Schema.Array(Schema.String),
    currency: Schema.String,
    lines: Schema.Array(CartLineView),
  }),
  Schema.Struct({
    kind: Schema.Literal("checkout.quote_view"),
    view: Schema.NullOr(Schema.Struct({
      quote: QuoteViewSchema,
      status: Schema.Literals(QuoteStatuses),
      mismatch: Schema.NullOr(Schema.String),
      attemptRef: Schema.NullOr(Ref),
      attemptState: Schema.NullOr(Schema.Literals(AttemptStates)),
      sessionUrl: Schema.NullOr(Schema.String),
    })),
  }),
  Schema.Struct({
    kind: Schema.Literal("checkout.attempt_view"),
    view: Schema.NullOr(Schema.Struct({
      ref: Ref,
      state: Schema.Literals(AttemptStates),
      sessionUrl: Schema.NullOr(Schema.String),
      currency: Schema.String,
      totalMinor: Integer,
      orderNumber: Schema.NullOr(Integer),
      lines: Schema.Array(QuoteLineView),
    })),
  }),
]);
export type CheckoutQueryResult = typeof CheckoutQueryResultSchema.Type;
