import { Effect, Semaphore } from "effect";
import { lookupCurrency, formatMoney } from "../catalog/money.ts";
import { MaxProducts, MaxCollections, parseID } from "../catalog/scalars.ts";
import type { Availability, Sort, Shop, ProductCard, ProductPage, Image, Option, Variant, DetailPanel, Collection, CollectionsPage, FeaturedCollection, InfoBlock, InfoLink, InfoPage, ListingPage, SearchResults } from "../contracts/views.ts";
import { formatPriceInput } from "../catalog/edit.ts";
import { DatabaseError, type Transaction } from "./persistence.ts";
import { routePath, withQuery } from "../routes/routes.ts";
import { BadVariantError, CatalogTooLargeError, StorefrontNotFound } from "./errors.ts";
import { StorefrontQueries, type QueryRow } from "./queries.ts";
import { decodeBlocks, InfoKinds, InfoTitles, isInfoKind, type InfoKind } from "./info.ts";
import { fold, relevance, SearchIndex } from "./search.ts";

export const PageSize = 24, MaxPage = 10000, MaxQueryLen = 200, SearchLimit = 8;
export const MaxPublishedRows = 750000, MaxPublishedTextBytes = 96 << 20, MaxCatalogSnapshotBytes = 192 << 20;
const loadPermits = Semaphore.makeUnsafe(2);
export interface ListingQuery { readonly query: string; readonly vendor: string; readonly available: Availability; readonly sort: Sort; readonly page: number; }
interface ProductRecord {
  readonly id: bigint; readonly card: ProductCard; readonly minimum: bigint; readonly description: string;
  readonly details: readonly DetailPanel[]; readonly options: readonly Option[]; readonly variants: readonly Variant[]; readonly images: readonly Image[];
}
interface CollectionRecord { readonly view: Collection; readonly members: readonly number[]; readonly memberSet: ReadonlySet<number>; }
export interface CatalogRows {
  readonly products: readonly QueryRow<"ListPublishedProducts">[];
  readonly variants: readonly QueryRow<"ListPublishedVariants">[];
  readonly selections: readonly QueryRow<"ListPublishedSelections">[];
  readonly options: readonly QueryRow<"ListPublishedOptionValues">[];
  readonly images: readonly QueryRow<"ListPublishedImages">[];
  readonly details: readonly QueryRow<"ListPublishedDetails">[];
  readonly collections: readonly QueryRow<"ListPublishedCollections">[];
  readonly members: readonly QueryRow<"ListPublishedMembers">[];
  readonly profile: QueryRow<"GetShopProfile">;
  readonly pages: readonly QueryRow<"ListShopPages">[];
  readonly redirects: readonly QueryRow<"ListPublishedRedirects">[];
}
export function freezeView<T>(value: T): T {
  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) freezeView(child);
  return Object.freeze(value);
}
/** Scalar order matches UTF-8 lexical ordering, including supplementary characters. */
function compareText(left: string, right: string): number {
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    const a = left.codePointAt(i) ?? 0, b = right.codePointAt(j) ?? 0;
    if (a !== b) return a < b ? -1 : 1;
    i += a > 65535 ? 2 : 1; j += b > 65535 ? 2 : 1;
  }
  return i === left.length ? j === right.length ? 0 : -1 : 1;
}
function compareInteger(left: bigint, right: bigint): number { return left < right ? -1 : left > right ? 1 : 0; }
export function imageView(url: string | null, alt: string | null, width: bigint | null, height: bigint | null): Image | null {
  if (url === null) return null;
  if (width !== null && height !== null && (width <= 0n || height <= 0n || width > BigInt(Number.MAX_SAFE_INTEGER) || height > BigInt(Number.MAX_SAFE_INTEGER))) throw new DatabaseError("storefront: image dimension outside safe range");
  return { url, alt: alt ?? "", size: width === null || height === null ? null : { width: Number(width), height: Number(height) } };
}
export function variantLabel(title: string | null, values: readonly string[]): string | null { return title ?? (values.length === 0 ? null : values.join(" / ")); }

/** Published view records are frozen; request-specific variant selection never mutates them. */
export class CatalogSnapshot {
  readonly generation: bigint;
  readonly stockVersion: bigint;
  readonly cacheVersion: bigint;
  readonly shop: Shop;
  readonly currencyExponent: number;
  readonly estimatedBytes: number;
  readonly rowCount: number;
  readonly textBytes: number;
  private readonly products: readonly ProductRecord[];
  private readonly mediaPaths: ReadonlySet<string>;
  private readonly infoPages: ReadonlyMap<InfoKind, InfoPage>;
  private readonly redirects: ReadonlyMap<string, string>;
  private readonly variantMinor: ReadonlyMap<string, bigint>;
  private readonly byHandle: ReadonlyMap<string, number>;
  private readonly collectionRecords: ReadonlyMap<string, CollectionRecord>;
  private readonly collectionIndex: readonly Collection[];
  private readonly vendors: readonly string[];
  private readonly orders: Readonly<Record<Sort, readonly number[]>>;
  private readonly index: SearchIndex;
  constructor(generation: bigint, stockVersion: bigint, store: QueryRow<"GetStore">, rows: CatalogRows, footprint: QueryRow<"GetPublishedCatalogFootprint">) {
    const currency = lookupCurrency(store.currency_code, Number(store.currency_exponent));
    this.generation = generation; this.stockVersion = stockVersion; this.cacheVersion = generation + stockVersion; this.currencyExponent = currency.exponent;
    const infoPages = new Map<InfoKind, InfoPage>(), info: InfoLink[] = [];
    const storedPages = new Map(rows.pages.map((row) => [row.kind, row.blocks]));
    for (const kind of InfoKinds) {
      const blocks = decodeBlocks(storedPages.get(kind) ?? "[]").map((block): InfoBlock => block.type === "list" ? { kind: "list", text: "", items: block.items } : { kind: block.type, text: block.text, items: [] });
      if (blocks.length === 0) continue;
      infoPages.set(kind, freezeView({ title: InfoTitles[kind], blocks }));
      info.push({ title: InfoTitles[kind], url: routePath("info", [kind]) });
    }
    this.infoPages = infoPages;
    this.shop = freezeView({ name: store.name, currency: currency.code, search: { endpoint: routePath("search"), action: routePath("products") }, description: rows.profile.description, contactEmail: rows.profile.contact_email, contactPhone: rows.profile.contact_phone, info });
    const models = rows.products.map((row) => ({ id: row.id, description: row.description, card: { id: row.id.toString(), handle: row.handle, title: row.title, vendor: row.vendor, url: routePath("product", [row.handle]), price: "", available: false, image: null as Image | null }, details: [] as DetailPanel[], options: [] as Option[], variants: [] as Variant[], images: [] as Image[], minimum: 0n, maximum: 0n }));
    const byID = new Map<bigint, typeof models[number]>(), byHandle = new Map<string, number>();
    models.forEach((model, index) => { parseID(model.id.toString()); byID.set(model.id, model); byHandle.set(model.card.handle, index); });
    const product = (id: bigint) => { const result = byID.get(id); if (result === undefined) throw new DatabaseError("storefront: row references unpublished product"); return result; };
    for (const row of rows.details) product(row.product_id).details.push({ key: row.key, title: row.title, body: row.body });
    const valueText = new Map<bigint, string>();
    for (const row of rows.options) {
      const model = product(row.product_id);
      let option = model.options.at(-1);
      if (option === undefined || option.id !== row.option_id.toString()) {
        option = { id: row.option_id.toString(), name: row.option_name, values: [] };
        model.options.push(option);
      }
      // This builder owns mutable arrays until the snapshot is frozen.
      (option.values as Array<{ id: string; value: string; selected: boolean }>).push({ id: row.value_id.toString(), value: row.value, selected: false });
      valueText.set(row.value_id, row.value);
    }
    const variantMinor = new Map<string, bigint>();
    this.variantMinor = variantMinor;
    const tuples = new Map<bigint, bigint[]>();
    for (const row of rows.selections) { const values = tuples.get(row.variant_id) ?? []; values.push(row.option_value_id); tuples.set(row.variant_id, values); }
    for (const row of rows.variants) {
      const model = product(row.product_id), ids = tuples.get(row.id) ?? [];
      const labels = ids.map((id) => { const label = valueText.get(id); if (label === undefined) throw new DatabaseError("storefront: variant selects missing value"); return label; });
      const price = formatMoney(row.price_minor, currency.code, currency.exponent);
      if (model.variants.length === 0) model.minimum = model.maximum = row.price_minor;
      else { if (row.price_minor < model.minimum) model.minimum = row.price_minor; if (row.price_minor > model.maximum) model.maximum = row.price_minor; }
      variantMinor.set(row.id.toString(), row.price_minor);
      model.variants.push({ id: row.id.toString(), label: variantLabel(row.title, labels) ?? "Default", price, available: row.available === 1n, selected: false, values: ids.map(String) });
      model.card.available ||= row.available === 1n;
    }
    const cardImages = new Map<bigint, Image>();
    const mediaPaths = new Set<string>();
    for (const row of rows.images) {
      const image = imageView(row.url, row.alt_text, row.width, row.height);
      const owner = product(row.product_id);
      if (image !== null) {
        if (owner.images.length === 0) {
          const card = imageView(row.card_url, row.alt_text, row.card_width, row.card_height);
          if (card !== null) cardImages.set(row.product_id, card);
        }
        owner.images.push(image);
      }
      if (row.url.startsWith("/media/")) mediaPaths.add(row.url);
      if (row.card_url !== null) mediaPaths.add(row.card_url);
    }
    this.mediaPaths = mediaPaths;
    for (const model of models) {
      if (model.variants.length === 0) throw new DatabaseError(`storefront: product ${model.id} has no variants`);
      const minimum = formatMoney(model.minimum, currency.code, currency.exponent);
      model.card.price = model.minimum === model.maximum ? minimum : `${minimum} – ${formatMoney(model.maximum, currency.code, currency.exponent)}`;
      model.card.image = cardImages.get(model.id) ?? model.images[0] ?? null;
      freezeView(model);
    }
    this.products = Object.freeze(models); this.byHandle = byHandle;
    const featured = models.map((_, index) => index);
    const sorted = (compare: (left: ProductRecord, right: ProductRecord) => number): readonly number[] => Object.freeze([...featured].sort((a, b) => {
      const left = models[a], right = models[b];
      if (left === undefined || right === undefined) throw new DatabaseError("storefront: invalid product index");
      return compare(left, right) || compareInteger(left.id, right.id);
    }));
    this.orders = Object.freeze({ featured: Object.freeze(featured), "title-asc": sorted((a, b) => compareText(a.card.title, b.card.title)), "price-asc": sorted((a, b) => compareInteger(a.minimum, b.minimum)), "price-desc": sorted((a, b) => compareInteger(b.minimum, a.minimum)) });
    this.vendors = Object.freeze([...new Set(models.map((model) => model.card.vendor ?? "").filter(Boolean))].sort(compareText).slice(0, 200));
    const productIndexes = new Map(models.map((model, index) => [model.id, index]));
    const collectionModels = new Map<bigint, { view: Collection; members: number[]; memberSet: Set<number> }>();
    const collectionHandles = new Map<string, CollectionRecord>();
    for (const row of rows.collections) {
      const record = { view: freezeView({ handle: row.handle, title: row.title, description: row.description, url: routePath("collection", [row.handle]) }), members: [] as number[], memberSet: new Set<number>() };
      collectionModels.set(row.id, record); collectionHandles.set(row.handle, record);
    }
    for (const row of rows.members) {
      const record = collectionModels.get(row.collection_id), index = productIndexes.get(row.product_id);
      if (record === undefined || index === undefined) throw new DatabaseError("storefront: invalid published membership");
      record.members.push(index); record.memberSet.add(index);
    }
    for (const record of collectionModels.values()) Object.freeze(record.members);
    this.collectionRecords = collectionHandles;
    const redirects = new Map<string, string>();
    for (const row of rows.redirects) {
      if (row.kind === "product" && !byHandle.has(row.old_handle) && byHandle.has(row.target_handle)) redirects.set(`product\0${row.old_handle}`, routePath("product", [row.target_handle]));
      else if (row.kind === "collection" && !collectionHandles.has(row.old_handle) && collectionHandles.has(row.target_handle)) redirects.set(`collection\0${row.old_handle}`, routePath("collection", [row.target_handle]));
    }
    this.redirects = redirects;
    this.collectionIndex = Object.freeze([...collectionModels.values()].slice(0, 500).map((record) => record.view));
    this.index = new SearchIndex(models.map((model) => ({ title: model.card.title, vendor: model.card.vendor ?? "", description: model.description })));
    const rowCount = footprint.products + footprint.variants + footprint.selections + footprint.option_values + footprint.images + footprint.details + footprint.collections + footprint.members;
    this.rowCount = Number(rowCount);
    this.textBytes = Number(footprint.text_bytes);
    this.estimatedBytes = Number(footprint.text_bytes) * 4 + models.length * 2048 + rows.collections.length * 1024 + Number(rowCount) * 96 + this.index.estimatedBytes;
    if (this.estimatedBytes > MaxCatalogSnapshotBytes) throw new CatalogTooLargeError(`estimated snapshot ${this.estimatedBytes} bytes exceeds ${MaxCatalogSnapshotBytes}`);
    Object.freeze(this);
  }
  formatMoney(minor: bigint): string { return formatMoney(minor, this.shop.currency, this.currencyExponent); }
  product(handle: string, variantID: bigint | null = null): ProductPage {
    const position = this.byHandle.get(handle), model = position === undefined ? undefined : this.products[position];
    if (model === undefined) throw new StorefrontNotFound();
    let selected = variantID === null ? model.variants.findIndex((variant) => variant.available) : model.variants.findIndex((variant) => variant.id === variantID.toString());
    if (variantID !== null && selected < 0) throw new BadVariantError();
    if (selected < 0) selected = 0;
    const variants = model.variants.map((variant, index) => ({ ...variant, selected: index === selected }));
    const variant = variants[selected]; if (variant === undefined) throw new DatabaseError("storefront: product has no variant");
    const options = model.options.map((option) => ({ ...option, values: option.values.map((value) => ({ ...value, selected: variant.values.includes(value.id) })) }));
    return freezeView({ product: model.card, description: model.description, details: model.details, options, variants, selected: variant, images: model.images, picker: { options, variants, selected: variant.id }, gallery: { images: model.images }, multiVariant: variants.length > 1 });
  }
  listing(handle: string, query: ListingQuery): ListingPage {
    if (!Number.isSafeInteger(query.page) || query.page < 1 || query.page > MaxPage) throw new Error("storefront: page out of range");
    const collection = handle === "" ? undefined : this.collectionRecords.get(handle);
    if (handle !== "" && collection === undefined) throw new StorefrontNotFound();
    const order = collection !== undefined && query.sort === "featured" ? collection.members : this.orders[query.sort];
    const matches = query.query === "" ? null : new Set(this.index.matches(fold(query.query)));
    const indexes = order.filter((index) => {
      const model = this.products[index];
      return model !== undefined && (collection === undefined || collection.memberSet.has(index)) && (matches === null || matches.has(index)) && (query.vendor === "" || model.card.vendor === query.vendor) && (query.available === "all" || model.card.available === (query.available === "true"));
    });
    const total = indexes.length, pageCount = Math.ceil(total / PageSize), action = collection?.view.url ?? routePath("products");
    const link = (page: number) => withQuery(action, { q: query.query, vendor: query.vendor, available: query.available === "all" ? "" : query.available, sort: query.sort === "featured" ? "" : query.sort, page: page === 1 ? "" : String(page) });
    const first = (query.page - 1) * PageSize;
    return freezeView({ title: collection?.view.title ?? "All products", collection: collection?.view ?? null, action, products: indexes.slice(first, first + PageSize).map((index) => this.products[index]!.card), total, page: query.page, pageCount, pages: Array.from({ length: Math.max(0, Math.min(pageCount, query.page + 3) - Math.max(1, query.page - 3) + 1) }, (_, index) => { const number = Math.max(1, query.page - 3) + index; return { number, url: link(number), current: number === query.page }; }), prevUrl: query.page > 1 && query.page <= pageCount + 1 ? link(query.page - 1) : null, nextUrl: query.page < pageCount ? link(query.page + 1) : null, firstUrl: link(1), query: query.query, vendor: query.vendor, available: query.available, sort: query.sort, vendors: this.vendors, filtered: query.query !== "" || query.vendor !== "" || query.available !== "all" });
  }
  search(raw: string): SearchResults {
    const query = raw.replace(/^[\u0009-\u000d\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+|[\u0009-\u000d\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+$/g, "");
    const needle = fold(query), matches = query === "" ? [] : this.index.matches(needle);
    const best: number[] = [];
    const compare = (a: number, b: number): number => {
      const left = this.products[a]!, right = this.products[b]!;
      return relevance(this.index.documents[a]!, needle) - relevance(this.index.documents[b]!, needle) || compareText(left.card.title, right.card.title) || compareInteger(left.id, right.id);
    };
    for (const index of matches) {
      let position = 0;
      while (position < best.length && compare(best[position]!, index) <= 0) position++;
      if (position < SearchLimit) { best.splice(position, 0, index); if (best.length > SearchLimit) best.pop(); }
    }
    return freezeView({ query, total: matches.length, products: best.map((index) => this.products[index]!.card), moreUrl: withQuery(routePath("products"), { q: query }) });
  }
  publishesMedia(path: string): boolean { return this.mediaPaths.has(path); }
  info(slug: string): InfoPage {
    const page = isInfoKind(slug) ? this.infoPages.get(slug) : undefined;
    if (page === undefined) throw new StorefrontNotFound();
    return page;
  }
  redirectTarget(kind: "product" | "collection", handle: string): string | null { return this.redirects.get(`${kind}\0${handle}`) ?? null; }
  /** The exact decimal price of a variant of a published product, for structured data. */
  offerPrice(variantId: string): string {
    const minor = this.variantMinor.get(variantId);
    if (minor === undefined) throw new StorefrontNotFound();
    return formatPriceInput(minor, this.currencyExponent);
  }
  /** Site paths of every active resource, in a stable order. */
  sitemapPaths(): readonly string[] {
    const paths = [routePath("home"), routePath("products")];
    if (this.collectionRecords.size > 0) paths.push(routePath("collections"));
    for (const collection of this.collectionRecords.values()) paths.push(collection.view.url);
    for (const product of this.products) paths.push(product.card.url);
    for (const link of this.shop.info) paths.push(link.url);
    return paths;
  }
  collections(): CollectionsPage { return freezeView({ collections: this.collectionIndex }); }
  featured(handle: string, limit: number): FeaturedCollection | null {
    if (!Number.isSafeInteger(limit) || limit < 1 || limit > PageSize) throw new Error("storefront: featured limit out of range");
    const collection = this.collectionRecords.get(handle);
    return collection === undefined ? null : freezeView({ collection: collection.view, products: collection.members.slice(0, limit).map((index) => this.products[index]!.card) });
  }
}

function validatePublishedFootprint(footprint: QueryRow<"GetPublishedCatalogFootprint">): void {
  const counts = [footprint.products, footprint.variants, footprint.selections, footprint.option_values, footprint.images, footprint.details, footprint.collections, footprint.members];
  if (counts.some((count) => count < 0n) || footprint.text_bytes < 0n || footprint.products > BigInt(MaxProducts) || footprint.collections > BigInt(MaxCollections) || counts.reduce((a, b) => a + b, 0n) > BigInt(MaxPublishedRows) || footprint.text_bytes > BigInt(MaxPublishedTextBytes)) {
    throw new CatalogTooLargeError("published row or text footprint");
  }
}

export function loadPublishedCatalog(tx: Transaction, queries: StorefrontQueries): Effect.Effect<CatalogSnapshot, DatabaseError | CatalogTooLargeError> {
  return loadPermits.withPermit(Effect.gen(function* () {
    const footprint = yield* queries.required(tx, "GetPublishedCatalogFootprint");
    yield* Effect.try({ try: () => validatePublishedFootprint(footprint), catch: (cause) => cause as CatalogTooLargeError });
    const { generation, stock_version: stockVersion } = yield* queries.required(tx, "GetCatalogVersions");
    const store = yield* queries.get(tx, "GetStore");
    if (store === null) return yield* Effect.fail(new DatabaseError("storefront: no store row; load a catalog first"));
    const rows: CatalogRows = {
      products: yield* queries.all(tx, "ListPublishedProducts"), variants: yield* queries.all(tx, "ListPublishedVariants"), selections: yield* queries.all(tx, "ListPublishedSelections"),
      options: yield* queries.all(tx, "ListPublishedOptionValues"), images: yield* queries.all(tx, "ListPublishedImages"), details: yield* queries.all(tx, "ListPublishedDetails"),
      collections: yield* queries.all(tx, "ListPublishedCollections"), members: yield* queries.all(tx, "ListPublishedMembers"),
      profile: yield* queries.required(tx, "GetShopProfile"), pages: yield* queries.all(tx, "ListShopPages"), redirects: yield* queries.all(tx, "ListPublishedRedirects"),
    };
    return yield* Effect.try({ try: () => new CatalogSnapshot(generation, stockVersion, store, rows, footprint), catch: (cause) => cause instanceof CatalogTooLargeError ? cause : new DatabaseError(cause instanceof Error ? cause.message : "storefront: catalog construction failed", cause) });
  }));
}
