import { MaxInt64 } from "./scalars.ts";

const currencies = [
  { code: "USD", exponent: 2, symbol: "$" },
  { code: "EUR", exponent: 2, symbol: "€" },
  { code: "GBP", exponent: 2, symbol: "£" },
  { code: "JPY", exponent: 0, symbol: "¥" },
] as const;
export type Currency = typeof currencies[number];
export function lookupCurrency(code: string, exponent: number): Currency {
  const currency = currencies.find((currency) => currency.code === code && currency.exponent === exponent);
  if (currency === undefined) throw new Error(`catalog: unsupported currency ${code}/${exponent}`);
  return currency;
}
/** Formats exact minor units using the store currency without float conversion. */
export function formatMoney(minor: bigint, code: string, exponent: number): string {
  const currency = lookupCurrency(code, exponent);
  if (minor < 0n || minor > MaxInt64) throw new Error("catalog: money outside non-negative signed int64");
  const digits = minor.toString().padStart(exponent + 1, "0");
  return currency.symbol + (exponent === 0 ? digits : `${digits.slice(0, -exponent)}.${digits.slice(-exponent)}`);
}
