import { BadVariantError, CartError, type CartRejection, CatalogTooLargeError, StorefrontNotFound } from "../storefront/errors.ts";
import { CatalogInputError, type ImportSummary } from "../storefront/import.ts";
import { DatabaseError, type SQLRow } from "../storefront/persistence.ts";

export const MaxImportChunkBytes = 8 << 20;
export const DefaultImportChunkBytes = 256 << 10;

export type RpcErrorTag =
  | "CartError"
  | "StorefrontNotFound"
  | "BadVariantError"
  | "CatalogTooLargeError"
  | "CatalogInputError"
  | "DatabaseError";

export type RpcResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly tag: "CartError"; readonly message: string; readonly reason: CartRejection }
  | { readonly ok: false; readonly tag: Exclude<RpcErrorTag, "CartError">; readonly message: string };

export function catalogVersion(generation: string | bigint, stockVersion: string | bigint): string {
  return `${generation.toString()}.${stockVersion.toString()}`;
}

export interface RawCatalogPayload {
  readonly generation: string;
  readonly stockVersion: string;
  readonly footprint: SQLRow;
  readonly store: SQLRow;
  readonly products: readonly SQLRow[];
  readonly variants: readonly SQLRow[];
  readonly selections: readonly SQLRow[];
  readonly options: readonly SQLRow[];
  readonly images: readonly SQLRow[];
  readonly details: readonly SQLRow[];
  readonly collections: readonly SQLRow[];
  readonly members: readonly SQLRow[];
  readonly profile: SQLRow;
  readonly pages: readonly SQLRow[];
  readonly redirects: readonly SQLRow[];
}

export type SyncCatalogRpcResponse =
  | { readonly unchanged: true; readonly version: string }
  | { readonly unchanged: false; readonly version: string; readonly payload: RawCatalogPayload };

export interface ReadCartRpcRequest {
  readonly tokenHash: Uint8Array | null;
  readonly nowSeconds: string;
  readonly knownVersion: string | null;
}

export interface ReadCartRpcResponse {
  readonly version: string;
  readonly payload: RawCatalogPayload | null;
  readonly cartRows: readonly SQLRow[];
  readonly selectionRows: readonly SQLRow[];
}

export interface AddCartRpcRequest {
  readonly tokenHash: Uint8Array | null;
  readonly variantID: string;
  readonly quantity: number;
  readonly nowSeconds: string;
  readonly freshToken: string;
  readonly freshExpiresMs: number;
  readonly freshHash: Uint8Array;
  readonly expiresSeconds: string;
}

export interface AddCartRpcResponse {
  readonly session: { readonly token: string; readonly expiresMs: number } | null;
}

export interface SetCartRpcRequest {
  readonly tokenHash: Uint8Array | null;
  readonly variantID: string;
  readonly quantity: number;
  readonly nowSeconds: string;
}

export interface RemoveCartRpcRequest {
  readonly tokenHash: Uint8Array | null;
  readonly variantID: string;
  readonly nowSeconds: string;
}

export interface ImportSummaryRpc {
  readonly products: number;
  readonly variants: number;
  readonly images: number;
  readonly collections: number;
  readonly members: number;
  readonly replaced: boolean;
  readonly sessionsCleared: string;
  readonly cartLinesCleared: string;
}

function classifyError(error: unknown): Exclude<RpcResult<never>, { readonly ok: true }> {
  if (error instanceof CartError) return { ok: false, tag: "CartError", message: error.message, reason: error.reason };
  if (error instanceof Error && "_tag" in error && typeof error._tag === "string") {
    const tag = error._tag;
    if (
      tag === "StorefrontNotFound" ||
      tag === "BadVariantError" ||
      tag === "CatalogTooLargeError" ||
      tag === "CatalogInputError" ||
      tag === "DatabaseError"
    ) {
      return { ok: false, tag, message: error.message };
    }
  }
  return {
    ok: false,
    tag: "DatabaseError",
    message: error instanceof Error ? error.message : String(error),
  };
}

export function isDomainRejection(error: unknown): boolean {
  return error instanceof CartError || (error instanceof Error && "_tag" in error && (error._tag === "StorefrontNotFound" || error._tag === "BadVariantError"));
}

export function wrapRpcResult<T>(operation: () => T, onUnexpected?: (error: unknown) => void): RpcResult<T> {
  try {
    return { ok: true, value: operation() };
  } catch (error) {
    if (onUnexpected !== undefined && !isDomainRejection(error)) onUnexpected(error);
    return classifyError(error);
  }
}

export function unwrapRpcResult<T>(result: RpcResult<T>): T {
  if (result.ok) return result.value;
  switch (result.tag) {
    case "CartError":
      throw new CartError(result.message, result.reason);
    case "StorefrontNotFound":
      throw new StorefrontNotFound();
    case "BadVariantError":
      throw new BadVariantError();
    case "CatalogTooLargeError":
      throw new CatalogTooLargeError(result.message);
    case "CatalogInputError":
      throw new CatalogInputError(result.message);
    case "DatabaseError":
      throw new DatabaseError(result.message);
  }
}

export function serializeImportSummary(summary: ImportSummary): ImportSummaryRpc {
  return {
    products: summary.products,
    variants: summary.variants,
    images: summary.images,
    collections: summary.collections,
    members: summary.members,
    replaced: summary.replaced,
    sessionsCleared: summary.sessionsCleared.toString(),
    cartLinesCleared: summary.cartLinesCleared.toString(),
  };
}

export function deserializeImportSummary(summary: ImportSummaryRpc): ImportSummary {
  return {
    products: summary.products,
    variants: summary.variants,
    images: summary.images,
    collections: summary.collections,
    members: summary.members,
    replaced: summary.replaced,
    sessionsCleared: BigInt(summary.sessionsCleared),
    cartLinesCleared: BigInt(summary.cartLinesCleared),
  };
}
