import { MaxBlocks, MaxDescriptionBytes, MaxHeadingBytes, MaxListItemBytes, MaxListItems, MaxPageTextBytes, type InfoBlock } from "../storefront/info.ts";
import type { FormValues } from "./catalog_form.ts";
import type { ShopRejection, ShopViewModel } from "./pages_shop_operations.ts";
import type { FieldErrors } from "./pages.ts";

export type SlotType = "heading" | "paragraph" | "list";
export const SlotTypes: readonly SlotType[] = ["paragraph", "heading", "list"];
export const SlotLabels: Readonly<Record<SlotType, string>> = { paragraph: "Paragraphs (one per line)", heading: "Heading", list: "List (one item per line)" };

export interface IdentityForm {
  readonly name: string;
  readonly description: string;
  readonly contactEmail: string;
  readonly contactPhone: string;
}

export function identityFromView(view: ShopViewModel): IdentityForm {
  return { name: view.name, description: view.description, contactEmail: view.contactEmail ?? "", contactPhone: view.contactPhone ?? "" };
}

export function identityFromFields(fields: FormValues): IdentityForm {
  const read = (name: string): string => (fields.get(name) ?? "").trim();
  return { name: read("name"), description: read("description"), contactEmail: read("contact_email"), contactPhone: read("contact_phone") };
}

export function describeIdentityRejections(rejections: readonly ShopRejection[]): FieldErrors {
  const errors: Record<string, string> = {};
  for (const rejection of rejections) {
    errors[rejection.subject] = rejection.subject === "name" ? `Enter a shop name of 1 to 100 bytes on one line.`
      : rejection.subject === "description" ? `Use at most ${MaxDescriptionBytes} bytes on one line, or leave it blank.`
      : rejection.subject === "contact_email" ? "Enter an address such as help@example.com, or leave it blank."
      : "Enter 3 to 40 characters on one line, or leave it blank.";
  }
  return errors;
}

export interface BlockSlot {
  readonly type: SlotType;
  readonly text: string;
}

export const PageFormKeys = /^block_(?:[0-9]|[1-3][0-9])_(?:type|text)$/;

export function blockSlotsFromView(blocks: readonly InfoBlock[]): readonly BlockSlot[] {
  return blocks.map((block) => block.type === "list" ? { type: "list", text: block.items.join("\n") } : { type: block.type, text: block.text });
}

export function blockSlotsFromFields(fields: FormValues): readonly BlockSlot[] {
  const slots: BlockSlot[] = [];
  for (let slot = 0; slot < MaxBlocks; slot++) {
    const type = fields.get(`block_${slot}_type`);
    slots.push({ type: type === "heading" || type === "list" ? type : "paragraph", text: fields.get(`block_${slot}_text`) ?? "" });
  }
  return slots;
}

export function visibleSlots(slots: readonly BlockSlot[]): number {
  let last = -1;
  slots.forEach((slot, index) => { if (slot.text.trim() !== "") last = index; });
  return Math.min(MaxBlocks, last + 4);
}

export interface PageParse {
  readonly blocks: readonly InfoBlock[];
  readonly slotOf: readonly number[];
}

export function parsePageSlots(slots: readonly BlockSlot[]): PageParse {
  const blocks: InfoBlock[] = [];
  const slotOf: number[] = [];
  slots.forEach((slot, index) => {
    const text = slot.text.trim();
    if (text === "") return;
    const lines = text.split("\n").map((line) => line.trim()).filter((line) => line !== "");
    if (slot.type === "list") {
      blocks.push({ type: "list", items: lines });
      slotOf.push(index);
    } else if (slot.type === "heading") {
      blocks.push({ type: "heading", text: lines.join(" ") });
      slotOf.push(index);
    } else {
      for (const line of lines) {
        blocks.push({ type: "paragraph", text: line });
        slotOf.push(index);
      }
    }
  });
  return { blocks, slotOf };
}

export function describePageRejections(rejections: readonly ShopRejection[], slotOf: readonly number[]): FieldErrors {
  const errors: Record<string, string> = {};
  for (const rejection of rejections) {
    if (rejection.subject === "page") {
      errors["page"] = rejection.kind === "too_many_blocks" ? `A page holds at most ${MaxBlocks} blocks.` : rejection.kind === "nothing_to_review" ? "Write the page before marking it reviewed." : `A page holds at most ${MaxPageTextBytes / 1024} KiB of text.`;
      continue;
    }
    const index = Number(rejection.subject.slice("block_".length));
    const slot = slotOf[index];
    if (slot === undefined) continue;
    errors[`block_${slot}_text`] = rejection.kind === "too_many_items" ? `A list holds at most ${MaxListItems} items.`
      : rejection.kind === "too_long" ? `A heading holds at most ${MaxHeadingBytes} bytes and a list item ${MaxListItemBytes}; a paragraph holds at most 4000.`
      : "Remove control characters. Headings and list items must each fit on one line.";
  }
  return errors;
}
