import { Schema } from "effect";
import { FulfillmentStatuses } from "../commerce/fulfillment.ts";
import { ShipmentBlocks, ShipmentRejections } from "../commerce/fulfillment_ship.ts";
import { PaymentStates } from "../commerce/payment.ts";
import { EmailMessageViewSchema } from "../commerce/email_operations.ts";
import { Integer } from "../storefront/queries.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Purpose = Schema.String.check(filter<string>((value) => /^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= 128, "must be a purpose label"));

export const MaxOrderPage = 50;
export const MaxOrderSearchEmailLength = 254;
export const MaxOrderNoteLength = 2000;

export const OrderListFilterSchema = Schema.Struct({
  number: Schema.NullOr(Integer),
  placedFrom: Schema.NullOr(Seconds),
  placedBefore: Schema.NullOr(Seconds),
  paymentState: Schema.NullOr(Schema.Literals(PaymentStates)),
  fulfillmentStatus: Schema.NullOr(Schema.Literals(FulfillmentStatuses)),
  email: Schema.NullOr(Schema.String.check(filter<string>((value) => value.length >= 1 && value.length <= MaxOrderSearchEmailLength, "must be an email search"))),
  before: Schema.NullOr(Integer),
});
export type OrderListFilter = typeof OrderListFilterSchema.Type;

export const ShipLineSchema = Schema.Struct({ position: Integer, quantity: Integer });

export const OrderCommandSchemas = [
  Schema.Struct({
    kind: Schema.Literal("order.form"), sessionDigest: Digest, number: Integer, nowSeconds: Seconds,
    tokens: Schema.Array(Schema.Struct({ tokenDigest: Digest, purpose: Purpose })),
  }),
  Schema.Struct({
    kind: Schema.Literal("order.ship"), sessionDigest: Digest, formTokenDigest: Digest, purpose: Purpose, actor: Schema.String, nowSeconds: Seconds,
    number: Integer, expectedRevision: Integer, lines: Schema.Array(ShipLineSchema), carrier: Schema.String,
    trackingNumber: Schema.NullOr(Schema.String), trackingUrl: Schema.NullOr(Schema.String),
  }),
  Schema.Struct({
    kind: Schema.Literal("order.note"), sessionDigest: Digest, formTokenDigest: Digest, purpose: Purpose, actor: Schema.String, nowSeconds: Seconds,
    number: Integer, body: Schema.String,
  }),
] as const;

export const OrderQuerySchemas = [
  Schema.Struct({ kind: Schema.Literal("order.list"), filter: OrderListFilterSchema }),
  Schema.Struct({ kind: Schema.Literal("order.detail"), number: Integer }),
] as const;

const Address = Schema.Struct({
  recipient: Schema.String, line1: Schema.String, line2: Schema.NullOr(Schema.String), city: Schema.String, region: Schema.String, postalCode: Schema.String, country: Schema.String,
});

export const OrderDetailSchema = Schema.Struct({
  number: Integer,
  revision: Integer,
  contactEmail: Schema.String,
  currency: Schema.String,
  exponent: Schema.Int,
  fulfillment: Schema.Literals(["ship", "pickup"]),
  fulfillmentStatus: Schema.Literals(FulfillmentStatuses),
  address: Schema.NullOr(Address),
  shippingZone: Schema.NullOr(Schema.String),
  merchandiseMinor: Integer,
  shippingMinor: Integer,
  shippingTaxMinor: Integer,
  taxMinor: Integer,
  totalMinor: Integer,
  allocation: Schema.Literals(["hold", "late"]),
  placedAt: Integer,
  payment: Schema.Struct({ intentId: Schema.String, state: Schema.Literals(PaymentStates), authorizedMinor: Integer, capturedMinor: Integer }),
  shipBlock: Schema.NullOr(Schema.Literals(ShipmentBlocks)),
  cancelBlock: Schema.NullOr(Schema.Literal("payment_settling")),
  refundableMinor: Integer,
  shippingRefundableMinor: Integer,
  shippingTaxRefundableMinor: Integer,
  lines: Schema.Array(Schema.Struct({
    position: Integer, title: Schema.String, variantLabel: Schema.String, unitPriceMinor: Integer, quantity: Integer, lineTotalMinor: Integer, taxMinor: Integer,
    shipped: Integer, canceled: Integer, returned: Integer, restocked: Integer, refunded: Integer, tracked: Schema.Boolean,
  })),
  shipments: Schema.Array(Schema.Struct({
    sequence: Integer, carrier: Schema.String, trackingNumber: Schema.NullOr(Schema.String), trackingUrl: Schema.NullOr(Schema.String), actor: Schema.String, shippedAt: Integer,
    lines: Schema.Array(Schema.Struct({ position: Integer, quantity: Integer })),
  })),
  exceptions: Schema.Array(Schema.Struct({ kind: Schema.String, state: Schema.Literals(["open", "closed"]), detail: Schema.String, openedAt: Integer, closedAt: Schema.NullOr(Integer) })),
  notes: Schema.Array(Schema.Struct({ id: Integer, body: Schema.String, actor: Schema.String, createdAt: Integer })),
  timeline: Schema.Array(Schema.Struct({ actor: Schema.String, action: Schema.String, summary: Schema.String, createdAt: Integer })),
  refunds: Schema.Array(Schema.Struct({ id: Integer, state: Schema.String, amountMinor: Integer, reason: Schema.String, failureReason: Schema.NullOr(Schema.String), createdAt: Integer })),
  emails: Schema.Array(EmailMessageViewSchema),
});
export type OrderDetailView = typeof OrderDetailSchema.Type;

export const OrderListRowSchema = Schema.Struct({
  number: Integer, placedAt: Integer, contactEmail: Schema.String, currency: Schema.String, exponent: Schema.Int, totalMinor: Integer, fulfillment: Schema.Literals(["ship", "pickup"]),
  fulfillmentStatus: Schema.Literals(FulfillmentStatuses), paymentState: Schema.Literals(PaymentStates), openExceptions: Integer, itemCount: Integer,
});
export type OrderListRow = typeof OrderListRowSchema.Type;

export const OrderResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("order.form"), issued: Schema.Boolean, view: Schema.NullOr(OrderDetailSchema) }),
  Schema.Struct({ kind: Schema.Literal("order.ship"), outcome: Schema.Literal("applied"), sequence: Integer }),
  Schema.Struct({ kind: Schema.Literal("order.ship"), outcome: Schema.Literals(["session_invalid", "token_invalid", "stale", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("order.ship"), outcome: Schema.Literal("rejected"), rejection: Schema.Literals(ShipmentRejections) }),
  Schema.Struct({ kind: Schema.Literal("order.note"), outcome: Schema.Literals(["applied", "session_invalid", "token_invalid", "not_found", "invalid_note"]) }),
] as const;

export const OrderQueryResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("order.list"), rows: Schema.Array(OrderListRowSchema), next: Schema.NullOr(Integer) }),
  Schema.Struct({ kind: Schema.Literal("order.detail"), view: Schema.NullOr(OrderDetailSchema) }),
] as const;

export type OrderCommand = (typeof OrderCommandSchemas)[number]["Type"];
export type OrderCommandResult = (typeof OrderResultSchemas)[number]["Type"];
export type OrderQuery = (typeof OrderQuerySchemas)[number]["Type"];
export type OrderQueryResult = (typeof OrderQueryResultSchemas)[number]["Type"];
