import { Effect } from "effect";
import { DatabaseError, type DatabaseBackend, type SQLRow, type SyncTransaction, type Transaction } from "./persistence.ts";

export interface MigrationSpec { readonly version: number; readonly name: string; readonly sql: string; }
export interface Migration extends MigrationSpec { readonly checksum: string; }

export async function migrationChecksum(bytes: Uint8Array): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", Uint8Array.from(bytes)));
  return [...digest].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

export async function createMigrationRunner(specs: readonly MigrationSpec[]): Promise<MigrationRunner> {
  const migrations: Migration[] = [];
  for (const spec of specs) migrations.push({ ...spec, checksum: await migrationChecksum(new TextEncoder().encode(spec.sql)) });
  return new MigrationRunner(migrations);
}

const CREATE_MIGRATIONS_TABLE_SQL = `CREATE TABLE IF NOT EXISTS schema_migrations (
  version INTEGER PRIMARY KEY CHECK (version > 0),
  checksum TEXT NOT NULL CHECK (length(checksum) > 0),
  applied_at INTEGER NOT NULL CHECK (applied_at >= 0)
) STRICT`;

const SELECT_APPLIED_SQL = "SELECT CAST(version AS TEXT) AS version, checksum FROM schema_migrations";
const INSERT_APPLIED_SQL = "INSERT INTO schema_migrations (version, checksum, applied_at) VALUES (CAST(? AS INTEGER), ?, CAST(? AS INTEGER))";

function appliedRows(rows: readonly SQLRow[]): Map<number, string> {
  const applied = new Map<number, string>();
  for (const row of rows) {
    const rawVersion = row["version"], digest = row["checksum"];
    if (typeof rawVersion !== "string" || !/^[1-9][0-9]{0,14}$/.test(rawVersion) || typeof digest !== "string") {
      throw new DatabaseError("migrate: invalid recorded migration");
    }
    const version = Number(rawVersion);
    if (!Number.isSafeInteger(version) || version <= 0) throw new DatabaseError("migrate: invalid recorded migration");
    applied.set(version, digest);
  }
  return applied;
}

function readApplied(transaction: Transaction): Effect.Effect<Map<number, string>, DatabaseError> {
  return Effect.flatMap(
    transaction.all(SELECT_APPLIED_SQL),
    (rows) => Effect.try({ try: () => appliedRows(rows), catch: (cause) => new DatabaseError("migrate: invalid migration records", cause) }),
  );
}

function readAppliedSync(transaction: SyncTransaction): Map<number, string> {
  try {
    return appliedRows(transaction.all(SELECT_APPLIED_SQL));
  } catch (cause) {
    if (cause instanceof DatabaseError && cause.message.includes("no such table")) {
      throw new DatabaseError("migrate: database is not migrated; run db migrate first", cause);
    }
    throw cause instanceof DatabaseError ? cause : new DatabaseError("migrate: invalid migration records", cause);
  }
}

export class MigrationRunner {
  readonly migrations: readonly Migration[];
  constructor(migrations: readonly Migration[]) {
    this.migrations = Object.freeze([...migrations].sort((left, right) => left.version - right.version).map((migration) => Object.freeze({ ...migration })));
    if (this.migrations.length === 0) throw new DatabaseError("migrate: no migrations");
    this.migrations.forEach((migration, index) => {
      if (migration.version !== index + 1) throw new DatabaseError(`migrate: ${migration.name} has version ${migration.version}, want ${index + 1}`);
      if (!/^[0-9a-f]{64}$/.test(migration.checksum)) throw new DatabaseError(`migrate: ${migration.name} has invalid checksum`);
    });
  }
  private checkSync(applied: ReadonlyMap<number, string>): void {
    for (const [version, digest] of applied) {
      const known = this.migrations.find((migration) => migration.version === version);
      if (known === undefined) throw new DatabaseError(`migrate: unknown applied migration version ${version}`);
      if (known.checksum !== digest) throw new DatabaseError(`migrate: applied migration ${known.name} does not match recorded checksum`);
    }
  }
  private check(applied: ReadonlyMap<number, string>): Effect.Effect<void, DatabaseError> {
    return Effect.try({
      try: () => this.checkSync(applied),
      catch: (cause) => cause instanceof DatabaseError ? cause : new DatabaseError("migrate: check failed", cause),
    });
  }
  apply(database: DatabaseBackend): Effect.Effect<readonly number[], DatabaseError> {
    return database.write((transaction) => Effect.gen({ self: this }, function* () {
      yield* transaction.script(CREATE_MIGRATIONS_TABLE_SQL);
      const applied = yield* readApplied(transaction);
      yield* this.check(applied);
      const done: number[] = [];
      const now = String(Math.floor(Date.now() / 1000));
      for (const migration of this.migrations) {
        if (applied.has(migration.version)) continue;
        yield* transaction.script(migration.sql).pipe(Effect.mapError((error) => new DatabaseError(`migrate: ${migration.name}: ${error.message}`, error)));
        yield* transaction.run(INSERT_APPLIED_SQL, [String(migration.version), migration.checksum, now]);
        done.push(migration.version);
      }
      return done;
    }));
  }
  verify(database: DatabaseBackend): Effect.Effect<void, DatabaseError> {
    return database.read((transaction) => Effect.gen({ self: this }, function* () {
      const applied = yield* readApplied(transaction).pipe(Effect.mapError((error) => error.message.includes("no such table") ? new DatabaseError("migrate: database is not migrated; run db migrate first", error) : error));
      yield* this.check(applied);
      for (const migration of this.migrations) if (!applied.has(migration.version)) return yield* Effect.fail(new DatabaseError(`migrate: database lacks migration ${migration.name}; run db migrate first`));
    }));
  }
  applySync(transaction: SyncTransaction, nowSeconds = Math.floor(Date.now() / 1000)): readonly number[] {
    transaction.script(CREATE_MIGRATIONS_TABLE_SQL);
    const applied = readAppliedSync(transaction);
    this.checkSync(applied);
    const done: number[] = [];
    const now = String(nowSeconds);
    for (const migration of this.migrations) {
      if (applied.has(migration.version)) continue;
      try {
        transaction.script(migration.sql);
      } catch (error) {
        throw new DatabaseError(`migrate: ${migration.name}: ${error instanceof Error ? error.message : String(error)}`, error);
      }
      transaction.run(INSERT_APPLIED_SQL, [String(migration.version), migration.checksum, now]);
      done.push(migration.version);
    }
    return done;
  }
  verifySync(transaction: SyncTransaction): void {
    const applied = readAppliedSync(transaction);
    this.checkSync(applied);
    for (const migration of this.migrations) {
      if (!applied.has(migration.version)) throw new DatabaseError(`migrate: database lacks migration ${migration.name}; run db migrate first`);
    }
  }
}
