import { Effect } from "effect";
import { MaxInt64 } from "../catalog/scalars.ts";
import type { CartLine, CartPage } from "../contracts/views.ts";
import { routePath, withQuery } from "../routes/routes.ts";
import { LIFETIME_MS, MAX_LINES, MAX_QUANTITY, newToken, parseToken, tokenDigest } from "../session/session.ts";
import { type CatalogSnapshot, freezeView, imageView, variantLabel } from "./catalog.ts";
import { CartError, StorefrontNotFound } from "./errors.ts";
import { DatabaseError, type SyncTransaction, type Transaction } from "./persistence.ts";
import type { QueryRow, StorefrontQueries } from "./queries.ts";

export const ExpiredSessionCleanupLimit = 50n;

export interface NewSession {
  readonly token: string;
  readonly expires: Date;
}

export interface PreparedCartRead {
  readonly tokenHash: Uint8Array | null;
  readonly nowSeconds: bigint;
}

export interface PreparedAddCart {
  readonly tokenHash: Uint8Array | null;
  readonly variantID: bigint;
  readonly quantity: number;
  readonly nowSeconds: bigint;
  readonly freshSession: NewSession;
  readonly freshHash: Uint8Array;
  readonly expiresSeconds: bigint;
}

export interface PreparedSetCart {
  readonly tokenHash: Uint8Array | null;
  readonly variantID: bigint;
  readonly quantity: number;
  readonly nowSeconds: bigint;
}

export interface PreparedRemoveCart {
  readonly tokenHash: Uint8Array | null;
  readonly variantID: bigint;
  readonly nowSeconds: bigint;
}

export interface AddCartDecision {
  readonly createSession: {
    readonly hash: Uint8Array;
    readonly createdAt: bigint;
    readonly expiresAt: bigint;
    readonly session: NewSession;
  } | null;
  readonly upsert: {
    readonly hash: Uint8Array;
    readonly variantID: bigint;
    readonly quantity: bigint;
    readonly addedAt: bigint;
  };
}

export interface SetCartDecision {
  readonly upsert: {
    readonly hash: Uint8Array;
    readonly variantID: bigint;
    readonly quantity: bigint;
    readonly addedAt: bigint;
  } | null;
}

export interface RemoveCartDecision {
  readonly deleteItem: {
    readonly hash: Uint8Array;
    readonly variantID: bigint;
  } | null;
}

export interface CartReadRows {
  readonly rows: readonly QueryRow<"ListCartLines">[];
  readonly labels: readonly QueryRow<"ListVariantSelectionLabels">[];
}

export function clockSeconds(date: Date): bigint {
  if (!(date instanceof Date) || !Number.isFinite(date.getTime()) || date.getTime() < 0) {
    throw new DatabaseError("storefront: invalid clock");
  }
  const value = BigInt(Math.floor(date.getTime() / 1000));
  if (value > MaxInt64) throw new DatabaseError("storefront: clock exceeds int64");
  return value;
}

export function validateVariantID(variantID: bigint): void {
  if (typeof variantID !== "bigint" || variantID < 1n || variantID > MaxInt64) {
    throw new CartError("Invalid variant ID.", "invalid-variant");
  }
}

export function validateQuantity(quantity: number): void {
  if (!Number.isSafeInteger(quantity) || quantity < 1 || quantity > MAX_QUANTITY) {
    throw new CartError(`Quantity must be between 1 and ${MAX_QUANTITY}.`, "invalid-quantity");
  }
}

export async function prepareSessionToken(token: string | null): Promise<Uint8Array | null> {
  if (token === null || parseToken(token) === null) return null;
  try {
    return await tokenDigest(token);
  } catch (cause) {
    throw new DatabaseError("storefront: session digest", cause);
  }
}

export async function prepareCartRead(token: string | null, now: Date): Promise<PreparedCartRead> {
  const nowSeconds = clockSeconds(now);
  const tokenHash = await prepareSessionToken(token);
  return { tokenHash, nowSeconds };
}

export async function prepareAddCart(token: string | null, variantID: bigint, quantity: number, now: Date): Promise<PreparedAddCart> {
  validateVariantID(variantID);
  validateQuantity(quantity);
  const nowSeconds = clockSeconds(now);
  const expires = new Date(now.getTime() + LIFETIME_MS);
  const expiresSeconds = clockSeconds(expires);
  const freshToken = newToken();
  const [tokenHash, freshHash] = await Promise.all([
    prepareSessionToken(token),
    tokenDigest(freshToken).catch((cause) => { throw new DatabaseError("storefront: new token digest", cause); }),
  ]);
  return {
    tokenHash,
    variantID,
    quantity,
    nowSeconds,
    freshSession: { token: freshToken, expires },
    freshHash,
    expiresSeconds,
  };
}

export async function prepareSetCart(token: string | null, variantID: bigint, quantity: number, now: Date): Promise<PreparedSetCart> {
  validateVariantID(variantID);
  validateQuantity(quantity);
  const nowSeconds = clockSeconds(now);
  const tokenHash = await prepareSessionToken(token);
  return { tokenHash, variantID, quantity, nowSeconds };
}

export async function prepareRemoveCart(token: string | null, variantID: bigint, now: Date): Promise<PreparedRemoveCart> {
  validateVariantID(variantID);
  const nowSeconds = clockSeconds(now);
  const tokenHash = await prepareSessionToken(token);
  return { tokenHash, variantID, nowSeconds };
}

export function decideVariantSellable(variant: QueryRow<"GetVariantForCart"> | null): void {
  if (variant === null || variant.product_status !== "active") {
    throw new CartError("That item is not available in this shop.", "unavailable");
  }
  if (variant.available !== 1n) {
    throw new CartError("That item is sold out.", "sold-out");
  }
}

export function decideAddToCart(input: {
  readonly prepared: PreparedAddCart;
  readonly variant: QueryRow<"GetVariantForCart"> | null;
  readonly liveSessionHash: Uint8Array | null;
  readonly existingQuantity: bigint | null;
  readonly lineCount: bigint;
}): AddCartDecision {
  decideVariantSellable(input.variant);
  const createSession = input.liveSessionHash === null
    ? {
        hash: input.prepared.freshHash,
        createdAt: input.prepared.nowSeconds,
        expiresAt: input.prepared.expiresSeconds,
        session: input.prepared.freshSession,
      }
    : null;
  const hash = input.liveSessionHash ?? input.prepared.freshHash;
  if (input.existingQuantity === null && input.lineCount >= BigInt(MAX_LINES)) {
    throw new CartError(`A cart can hold at most ${MAX_LINES} different items.`, "line-cap");
  }
  const total = (input.existingQuantity ?? 0n) + BigInt(input.prepared.quantity);
  if (total > BigInt(MAX_QUANTITY)) {
    throw new CartError(`You can have at most ${MAX_QUANTITY} of one item in your cart.`, "quantity-cap");
  }
  return {
    createSession,
    upsert: {
      hash,
      variantID: input.prepared.variantID,
      quantity: total,
      addedAt: input.prepared.nowSeconds,
    },
  };
}

export function decideSetCartQuantity(input: {
  readonly prepared: PreparedSetCart;
  readonly liveSessionHash: Uint8Array | null;
  readonly existingQuantity: bigint | null;
  readonly variant: QueryRow<"GetVariantForCart"> | null;
}): SetCartDecision {
  if (input.liveSessionHash === null || input.existingQuantity === null) {
    throw new StorefrontNotFound();
  }
  decideVariantSellable(input.variant);
  const target = BigInt(input.prepared.quantity);
  if (input.existingQuantity === target) {
    return { upsert: null };
  }
  return {
    upsert: {
      hash: input.liveSessionHash,
      variantID: input.prepared.variantID,
      quantity: target,
      addedAt: input.prepared.nowSeconds,
    },
  };
}

export function decideRemoveCartItem(input: {
  readonly prepared: PreparedRemoveCart;
  readonly liveSessionHash: Uint8Array | null;
}): RemoveCartDecision {
  if (input.liveSessionHash === null) {
    return { deleteItem: null };
  }
  return {
    deleteItem: {
      hash: input.liveSessionHash,
      variantID: input.prepared.variantID,
    },
  };
}

export function buildCartPage(
  catalog: CatalogSnapshot,
  rows: readonly QueryRow<"ListCartLines">[],
  selections: readonly QueryRow<"ListVariantSelectionLabels">[],
): CartPage {
  const labels = new Map<bigint, string[]>();
  for (const selection of selections) {
    const values = labels.get(selection.variant_id) ?? [];
    values.push(selection.value);
    labels.set(selection.variant_id, values);
  }
  let subtotal = 0n, overflow = false, itemCount = 0, hasExcluded = false;
  const lines: CartLine[] = [];
  for (const row of rows) {
    if (row.price_minor < 0n || row.price_minor > MaxInt64 || row.quantity < 1n || row.quantity > BigInt(MAX_QUANTITY)) {
      throw new DatabaseError("storefront: cart row out of bounds");
    }
    const label = variantLabel(row.variant_title, labels.get(row.variant_id) ?? []);
    const status = row.product_status !== "active" ? "unpublished" : row.available === 1n ? "available" : "sold-out";
    const url = status === "unpublished" ? null : label === null ? routePath("product", [row.handle]) : withQuery(routePath("product", [row.handle]), { variant: row.variant_id.toString() });
    const total = row.price_minor * row.quantity;
    const lineTotal = status !== "available" || total > MaxInt64 ? null : catalog.formatMoney(total);
    itemCount += Number(row.quantity);
    if (status !== "available") hasExcluded = true;
    else if (total > MaxInt64) overflow = true;
    else { subtotal += total; if (subtotal > MaxInt64) overflow = true; }
    lines.push({
      variantId: row.variant_id.toString(),
      productTitle: row.product_title,
      variantLabel: label,
      url,
      image: status === "unpublished" ? null : imageView(row.image_url, row.image_alt, row.image_width, row.image_height),
      unitPrice: catalog.formatMoney(row.price_minor),
      quantity: Number(row.quantity),
      lineTotal,
      status,
    });
  }
  return freezeView({
    lines,
    itemCount,
    subtotal: overflow ? null : catalog.formatMoney(subtotal),
    hasExcluded,
    problem: overflow ? "This cart's total is too large to calculate exactly, so it cannot be purchased. Reduce quantities or remove items." : null,
    maxQuantity: MAX_QUANTITY,
  });
}

function liveSessionEffect(tx: Transaction, queries: StorefrontQueries, tokenHash: Uint8Array | null, nowSeconds: bigint): Effect.Effect<Uint8Array | null, DatabaseError> {
  if (tokenHash === null) return Effect.succeed(null);
  return Effect.map(queries.get(tx, "GetLiveSession", [tokenHash, nowSeconds]), (row) => row?.token_hash ?? null);
}

export function executeAddToCartEffect(tx: Transaction, queries: StorefrontQueries, prepared: PreparedAddCart): Effect.Effect<NewSession | null, DatabaseError | CartError> {
  return Effect.gen(function* () {
    yield* queries.run(tx, "DeleteExpiredSessions", [prepared.nowSeconds, ExpiredSessionCleanupLimit]);
    const variant = yield* queries.get(tx, "GetVariantForCart", [prepared.variantID]);
    yield* Effect.try({ try: () => decideVariantSellable(variant), catch: (error) => error as CartError });
    const liveSessionHash = yield* liveSessionEffect(tx, queries, prepared.tokenHash, prepared.nowSeconds);
    const hash = liveSessionHash ?? prepared.freshHash;
    const existing = liveSessionHash === null ? null : yield* queries.get(tx, "GetCartQuantity", [hash, prepared.variantID]);
    const lineCount = liveSessionHash === null || existing !== null ? 0n : yield* queries.count(tx, "CountCartLines", [hash]);
    const decision = yield* Effect.try({
      try: () => decideAddToCart({ prepared, variant, liveSessionHash, existingQuantity: existing?.quantity ?? null, lineCount }),
      catch: (error) => error as CartError,
    });
    if (decision.createSession !== null) {
      yield* queries.run(tx, "InsertSession", [decision.createSession.hash, decision.createSession.createdAt, decision.createSession.expiresAt]);
    }
    yield* queries.run(tx, "UpsertCartItem", [decision.upsert.hash, decision.upsert.variantID, decision.upsert.quantity, decision.upsert.addedAt]);
    return decision.createSession?.session ?? null;
  });
}

export function executeSetCartQuantityEffect(tx: Transaction, queries: StorefrontQueries, prepared: PreparedSetCart): Effect.Effect<void, DatabaseError | CartError | StorefrontNotFound> {
  return Effect.gen(function* () {
    const liveSessionHash = yield* liveSessionEffect(tx, queries, prepared.tokenHash, prepared.nowSeconds);
    if (liveSessionHash === null) return yield* Effect.fail(new StorefrontNotFound());
    const existing = yield* queries.get(tx, "GetCartQuantity", [liveSessionHash, prepared.variantID]);
    if (existing === null) return yield* Effect.fail(new StorefrontNotFound());
    const variant = yield* queries.get(tx, "GetVariantForCart", [prepared.variantID]);
    const decision = yield* Effect.try({
      try: () => decideSetCartQuantity({ prepared, liveSessionHash, existingQuantity: existing.quantity, variant }),
      catch: (error) => error as CartError | StorefrontNotFound,
    });
    if (decision.upsert !== null) {
      yield* queries.run(tx, "UpsertCartItem", [decision.upsert.hash, decision.upsert.variantID, decision.upsert.quantity, decision.upsert.addedAt]);
    }
  });
}

export function executeRemoveCartItemEffect(tx: Transaction, queries: StorefrontQueries, prepared: PreparedRemoveCart): Effect.Effect<void, DatabaseError> {
  return Effect.gen(function* () {
    const liveSessionHash = yield* liveSessionEffect(tx, queries, prepared.tokenHash, prepared.nowSeconds);
    const decision = decideRemoveCartItem({ prepared, liveSessionHash });
    if (decision.deleteItem !== null) {
      yield* queries.run(tx, "DeleteCartItem", [decision.deleteItem.hash, decision.deleteItem.variantID]);
    }
  });
}

export function readCartRowsEffect(tx: Transaction, queries: StorefrontQueries, prepared: PreparedCartRead): Effect.Effect<CartReadRows, DatabaseError> {
  return Effect.gen(function* () {
    const liveSessionHash = yield* liveSessionEffect(tx, queries, prepared.tokenHash, prepared.nowSeconds);
    if (liveSessionHash === null) return { rows: [], labels: [] };
    const rows = yield* queries.all(tx, "ListCartLines", [liveSessionHash]);
    const labels = yield* queries.all(tx, "ListVariantSelectionLabels", [liveSessionHash]);
    return { rows, labels };
  });
}

function liveSessionSync(tx: SyncTransaction, queries: StorefrontQueries, tokenHash: Uint8Array | null, nowSeconds: bigint): Uint8Array | null {
  if (tokenHash === null) return null;
  return queries.getSync(tx, "GetLiveSession", [tokenHash, nowSeconds])?.token_hash ?? null;
}

export function executeAddToCartSync(tx: SyncTransaction, queries: StorefrontQueries, prepared: PreparedAddCart): NewSession | null {
  queries.runSync(tx, "DeleteExpiredSessions", [prepared.nowSeconds, ExpiredSessionCleanupLimit]);
  const variant = queries.getSync(tx, "GetVariantForCart", [prepared.variantID]);
  decideVariantSellable(variant);
  const liveSessionHash = liveSessionSync(tx, queries, prepared.tokenHash, prepared.nowSeconds);
  const hash = liveSessionHash ?? prepared.freshHash;
  const existing = liveSessionHash === null ? null : queries.getSync(tx, "GetCartQuantity", [hash, prepared.variantID]);
  const lineCount = liveSessionHash === null || existing !== null ? 0n : queries.countSync(tx, "CountCartLines", [hash]);
  const decision = decideAddToCart({ prepared, variant, liveSessionHash, existingQuantity: existing?.quantity ?? null, lineCount });
  if (decision.createSession !== null) {
    queries.runSync(tx, "InsertSession", [decision.createSession.hash, decision.createSession.createdAt, decision.createSession.expiresAt]);
  }
  queries.runSync(tx, "UpsertCartItem", [decision.upsert.hash, decision.upsert.variantID, decision.upsert.quantity, decision.upsert.addedAt]);
  return decision.createSession?.session ?? null;
}

export function executeSetCartQuantitySync(tx: SyncTransaction, queries: StorefrontQueries, prepared: PreparedSetCart): void {
  const liveSessionHash = liveSessionSync(tx, queries, prepared.tokenHash, prepared.nowSeconds);
  if (liveSessionHash === null) throw new StorefrontNotFound();
  const existing = queries.getSync(tx, "GetCartQuantity", [liveSessionHash, prepared.variantID]);
  if (existing === null) throw new StorefrontNotFound();
  const variant = queries.getSync(tx, "GetVariantForCart", [prepared.variantID]);
  const decision = decideSetCartQuantity({ prepared, liveSessionHash, existingQuantity: existing.quantity, variant });
  if (decision.upsert !== null) {
    queries.runSync(tx, "UpsertCartItem", [decision.upsert.hash, decision.upsert.variantID, decision.upsert.quantity, decision.upsert.addedAt]);
  }
}

export function executeRemoveCartItemSync(tx: SyncTransaction, queries: StorefrontQueries, prepared: PreparedRemoveCart): void {
  const liveSessionHash = liveSessionSync(tx, queries, prepared.tokenHash, prepared.nowSeconds);
  const decision = decideRemoveCartItem({ prepared, liveSessionHash });
  if (decision.deleteItem !== null) {
    queries.runSync(tx, "DeleteCartItem", [decision.deleteItem.hash, decision.deleteItem.variantID]);
  }
}
