import { StalledRefundSeconds, type Backlog, type OperationsStatus } from "./work_operations.ts";

export interface OperationsStatusRow {
  readonly label: string;
  readonly count: number;
  readonly oldest: string;
}

export function formatAge(seconds: number | null): string {
  if (seconds === null) return "none";
  if (seconds < 120) return `${seconds} s`;
  if (seconds < 7200) return `${Math.floor(seconds / 60)} min`;
  if (seconds < 172_800) return `${Math.floor(seconds / 3600)} h`;
  return `${Math.floor(seconds / 86_400)} d`;
}

export function operationsStatusRows(status: OperationsStatus): readonly OperationsStatusRow[] {
  const row = (label: string, backlog: Backlog): OperationsStatusRow => ({ label, count: backlog.count, oldest: formatAge(backlog.oldestAgeSeconds) });
  return [
    row("Payments awaiting capture (age since authorization)", status.pendingPayments),
    row("Provider operations with an unknown outcome", status.unknownOperations),
    row("Webhook events not yet processed (lag)", status.unprocessedEvents),
    row("Background work due and not yet run (lag)", status.dueWork),
    row("Dead letters", status.deadWork),
    row("Refunds not yet settled", status.openRefunds),
    { label: `Refunds unsettled for more than ${StalledRefundSeconds / 3600} h`, count: status.stalledRefunds, oldest: status.stalledRefunds === 0 ? "none" : formatAge(status.openRefunds.oldestAgeSeconds) },
  ];
}

export function operationsStatusLines(status: OperationsStatus): readonly string[] {
  return [
    ...(status.held ? ["processing is held until ops reconcile and ops resume"] : []),
    ...operationsStatusRows(status).map((row) => `${row.label}: ${row.count}${row.count === 0 ? "" : `, oldest ${row.oldest}`}`),
  ];
}
