import type { AdminBackend } from "../admin/backend.ts";
import type { StripeClient, StripeEvent, Refund } from "../stripe/index.ts";
import { isOutcomeUnknown, StripeApiError } from "../stripe/index.ts";
import { IdempotencyWindowSeconds } from "./operation.ts";
import type { PaymentSettings } from "./payment_handlers.ts";
import type { RefundFacts } from "./refund_operations.ts";
import { WorkError } from "./work.ts";
import { asWorkError, type ProviderEventContext } from "./work_kinds.ts";
import type { WorkHandler } from "./work_runner.ts";

export const RefundListLimit = 100;

export interface RefundDependencies {
  readonly settings: PaymentSettings;
  readonly stripe: () => StripeClient;
}

function message(error: unknown): string {
  return (error instanceof Error ? error.message : String(error)).slice(0, 500);
}

function isRejection(error: unknown): boolean {
  return error instanceof StripeApiError && !isOutcomeUnknown(error) && !error.isIdempotencyMismatch && [400, 402, 404].includes(error.status);
}

export function refundFactsOf(refund: Refund): RefundFacts {
  const localId = refund.metadata["nanoshop_refund"];
  return {
    id: refund.id,
    status: refund.status,
    amount: refund.amount,
    currency: refund.currency,
    paymentIntentId: refund.paymentIntentId,
    localId: localId !== undefined && /^[1-9][0-9]{0,18}$/.test(localId) ? localId : null,
    failureReason: refund.failureReason,
  };
}

async function observe(backend: AdminBackend, refund: Refund, nowSeconds: () => number, signal: AbortSignal | undefined): Promise<void> {
  await backend.command({ kind: "refund.observe", refund: refundFactsOf(refund), nowSeconds: nowSeconds() }, signal);
}

async function fail(backend: AdminBackend, refundId: bigint, to: "failed" | "blocked", error: string, nowSeconds: () => number, signal: AbortSignal | undefined): Promise<void> {
  await backend.command({ kind: "refund.fail", refundId, to, error, nowSeconds: nowSeconds() }, signal);
}

function refundIdOf(payload: string): bigint {
  let parsed: unknown;
  try { parsed = JSON.parse(payload); } catch (cause) { throw new WorkError("permanent", "work payload is not JSON", { cause }); }
  const value = typeof parsed === "object" && parsed !== null ? (parsed as Record<string, unknown>)["refund"] : undefined;
  if (typeof value !== "string" || !/^[1-9][0-9]{0,18}$/.test(value)) throw new WorkError("permanent", "work payload has no refund id");
  return BigInt(value);
}

export function refundWork(dependencies: RefundDependencies): WorkHandler {
  return async (item, context) => {
    const refundId = refundIdOf(item.payload);
    const { backend, nowSeconds, signal } = context;
    const { refund: view } = await backend.query({ kind: "refund.view", refundId }, signal);
    if (view === null) throw new WorkError("permanent", `refund ${refundId} does not exist`);
    if (view.state !== "pending" && view.state !== "requires_action") return;
    const stripe = dependencies.stripe();
    const begun = await backend.command({ kind: "payment.op.begin", tenantId: dependencies.settings.tenantId, opKind: "refund", subject: refundId.toString(), nowSeconds: nowSeconds() }, signal);
    if (begun.outcome !== "started") return;

    try {
      if (begun.previous === "in_flight" || begun.previous === "unknown") {
        const page = await stripe.listRefunds({ paymentIntentId: view.paymentIntentId, limit: RefundListLimit });
        const found = page.data.find((candidate) => candidate.metadata["nanoshop_refund"] === refundId.toString());
        if (found !== undefined) {
          await observe(backend, found, nowSeconds, signal);
          return;
        }
        if (page.hasMore) {
          await fail(backend, refundId, "blocked", "the refund could not be found in the first page of this payment's refunds; check the Stripe dashboard before retrying", nowSeconds, signal);
          return;
        }
        if (nowSeconds() - begun.operation.createdAt >= IdempotencyWindowSeconds) {
          await fail(backend, refundId, "blocked", "no refund was found at Stripe more than 24 hours after the request; check the Stripe dashboard before retrying", nowSeconds, signal);
          return;
        }
      }
      let created: Refund;
      try {
        created = await stripe.createRefund(
          { paymentIntentId: view.paymentIntentId, amount: view.amountMinor, metadata: { nanoshop_tenant: dependencies.settings.tenantId, nanoshop_refund: refundId.toString() } },
          begun.operation.key,
        );
      } catch (error) {
        if (isOutcomeUnknown(error)) {
          await backend.command({ kind: "payment.op.settle", opKind: "refund", subject: refundId.toString(), to: "unknown", providerObjectId: null, error: message(error), attemptRef: null, nowSeconds: nowSeconds() }, signal);
          throw error;
        }
        if (isRejection(error)) {
          await fail(backend, refundId, "failed", message(error), nowSeconds, signal);
          return;
        }
        if (error instanceof StripeApiError && error.isIdempotencyMismatch) {
          await fail(backend, refundId, "blocked", message(error), nowSeconds, signal);
          return;
        }
        throw error;
      }
      await observe(backend, created, nowSeconds, signal);
    } catch (error) {
      throw asWorkError(error);
    }
  };
}

export function refundEventHandler(): (event: StripeEvent, context: ProviderEventContext) => Promise<void> {
  return async (event, context) => {
    const refund = await context.stripe.retrieveRefund(event.objectId);
    await observe(context.backend, refund, context.nowSeconds, context.signal);
  };
}
