import type { AdminBackend } from "../admin/backend.ts";
import { runMediaMaintenance } from "../admin/media_maintenance.ts";
import type { BlobStore } from "../media/blob.ts";
import type { StripeClient, StripeEvent, StripeMode } from "../stripe/index.ts";
import { createStripeClient, StripeApiError, StripeConfigError, StripeDecodeError, StripeTransportError } from "../stripe/index.ts";
import { WorkError } from "./work.ts";
import { ProviderEventKind } from "./work_program.ts";
import type { WorkHandler, WorkRegistry } from "./work_runner.ts";

export const MediaMaintenanceKind = "periodic_media_maintenance";
export const ProviderEventPurgeKind = "periodic_provider_event_purge";
export const MediaMaintenanceIntervalSeconds = 15 * 60;
export const ProviderEventPurgeIntervalSeconds = 24 * 3600;

export const SubscribedEventTypes = [
  "checkout.session.completed", "checkout.session.expired", "checkout.session.async_payment_succeeded", "checkout.session.async_payment_failed",
  "payment_intent.amount_capturable_updated", "payment_intent.succeeded", "payment_intent.canceled", "payment_intent.payment_failed",
  "refund.created", "refund.updated", "refund.failed",
  "charge.dispute.created", "charge.dispute.updated", "charge.dispute.closed",
  "radar.early_fraud_warning.created", "review.opened", "review.closed",
] as const;

export function isSubscribedEventType(type: string): boolean {
  return (SubscribedEventTypes as readonly string[]).includes(type);
}

export interface ProviderEventContext {
  readonly backend: AdminBackend;
  readonly stripe: StripeClient;
  readonly nowSeconds: () => number;
  readonly signal: AbortSignal | undefined;
}

export type ProviderEventHandler = (event: StripeEvent, context: ProviderEventContext) => Promise<void>;

export class ProviderEventHandlers {
  readonly #handlers = new Map<string, ProviderEventHandler>();

  on(type: (typeof SubscribedEventTypes)[number], handler: ProviderEventHandler): this {
    if (this.#handlers.has(type)) throw new Error(`work: an event handler for ${type} is already registered`);
    this.#handlers.set(type, handler);
    return this;
  }

  handler(type: string): ProviderEventHandler | undefined {
    return this.#handlers.get(type);
  }
}

export function asWorkError(error: unknown): unknown {
  if (error instanceof WorkError) return error;
  if (error instanceof StripeConfigError) return new WorkError("blocked", error.message, { cause: error });
  if (error instanceof StripeTransportError) return new WorkError("retryable", error.message, { cause: error });
  if (error instanceof StripeDecodeError) return new WorkError("permanent", error.message, { cause: error });
  if (error instanceof StripeApiError) {
    if (error.status === 401 || error.status === 403) return new WorkError("blocked", error.message, { cause: error });
    if (error.status >= 500 || error.status === 408 || error.status === 409 || error.status === 429) return new WorkError("retryable", error.message, { cause: error });
    return new WorkError("permanent", error.message, { cause: error });
  }
  return error;
}

function payloadField(payload: string, field: string, fallback?: string): string {
  let parsed: unknown;
  try { parsed = JSON.parse(payload); } catch (cause) { throw new WorkError("permanent", "work payload is not JSON", { cause }); }
  const value = typeof parsed === "object" && parsed !== null ? (parsed as Record<string, unknown>)[field] : undefined;
  if (value === undefined && fallback !== undefined) return fallback;
  if (typeof value !== "string") throw new WorkError("permanent", `work payload has no ${field}`);
  return value;
}

export interface StripeConnection {
  readonly secretKey: string | undefined;
  readonly mode: StripeMode;
  readonly apiBase: string | null;
}

export function lazyStripeClient(connection: StripeConnection): () => StripeClient {
  let client: StripeClient | undefined;
  return () => {
    if (client !== undefined) return client;
    if (connection.secretKey === undefined) throw new WorkError("blocked", "STRIPE_SECRET_KEY is not configured for this shop");
    client = createStripeClient({
      secretKey: connection.secretKey, mode: connection.mode, fetch: (input, init) => fetch(input, init),
      ...(connection.apiBase === null ? {} : { apiBase: connection.apiBase }),
    });
    return client;
  };
}

export interface StandardKindDependencies {
  readonly stripe: () => StripeClient;
  readonly blobs: BlobStore;
  readonly providerEvents: ProviderEventHandlers;
}

function providerEventHandler(dependencies: StandardKindDependencies): WorkHandler {
  return async (item, context) => {
    const eventId = payloadField(item.payload, "event");
    const { event: row } = await context.backend.query({ kind: "work.provider_event", eventId }, context.signal);
    if (row === null) throw new WorkError("permanent", `provider event ${eventId} was never received`);
    if (row.processedAt !== null) return;
    const handler = dependencies.providerEvents.handler(row.eventType);
    if (handler === undefined) throw new WorkError("blocked", `no handler is registered for provider event type ${row.eventType}`);
    try {
      const stripe = dependencies.stripe();
      const event = await stripe.retrieveEvent(eventId);
      if (event.id !== eventId || event.type !== row.eventType) throw new WorkError("permanent", `retrieved event ${event.id} does not match received event ${eventId}`);
      await handler(event, { backend: context.backend, stripe, nowSeconds: context.nowSeconds, signal: context.signal });
    } catch (error) {
      throw asWorkError(error);
    }
    await context.backend.command({ kind: "work.event_processed", eventId, nowSeconds: context.nowSeconds() }, context.signal);
  };
}

function mediaMaintenanceHandler(dependencies: StandardKindDependencies): WorkHandler {
  return async (item, context) => {
    const cursor = payloadField(item.payload, "cursor", "");
    const report = await runMediaMaintenance({
      backend: context.backend, blobs: dependencies.blobs, nowSeconds: context.nowSeconds(), orphanCursor: cursor === "" ? null : cursor,
      ...(context.signal === undefined ? {} : { signal: context.signal }),
    });
    return { payload: JSON.stringify({ cursor: report.orphanCursor ?? "" }) };
  };
}

export function registerStandardKinds(registry: WorkRegistry, dependencies: StandardKindDependencies): WorkRegistry {
  return registry
    .register(ProviderEventKind, providerEventHandler(dependencies))
    .register(MediaMaintenanceKind, mediaMaintenanceHandler(dependencies), { periodicSeconds: MediaMaintenanceIntervalSeconds })
    .register(ProviderEventPurgeKind, async (_item, context) => {
      await context.backend.command({ kind: "work.purge", nowSeconds: context.nowSeconds() }, context.signal);
    }, { periodicSeconds: ProviderEventPurgeIntervalSeconds });
}
