import { checkoutOrigin, type HostedSessionCreator } from "../checkout/session_creator.ts";
import { StripeHostedSessionCreator } from "../checkout/stripe_session_creator.ts";
import { lazyEmailSender, registerEmailKinds } from "../commerce/email_handlers.ts";
import { registerPaymentKinds, type PaymentSettings } from "../commerce/payment_handlers.ts";
import type { ProviderEventHandlers } from "../commerce/work_kinds.ts";
import { lazyStripeClient, registerStandardKinds } from "../commerce/work_kinds.ts";
import { WorkRegistry } from "../commerce/work_runner.ts";
import type { StripeClient } from "../stripe/index.ts";
import { r2BlobStore, type R2BucketLike } from "./blob_r2.ts";
import { getEmbeddedEmail, getEmbeddedPayments, getEmbeddedShop, type EmbeddedShop } from "./embedded.ts";

export interface StripeSecretsEnv {
  readonly STRIPE_SECRET_KEY?: string;
  readonly STRIPE_WEBHOOK_SECRET?: string;
  readonly STRIPE_WEBHOOK_SECRET_PREVIOUS?: string;
}

export interface EmailSecretsEnv {
  readonly RESEND_API_KEY?: string;
  readonly ORDER_ACCESS_KEY?: string;
}

export interface TenantStoreEnv extends StripeSecretsEnv, EmailSecretsEnv {
  readonly MEDIA: R2BucketLike;
}

export interface CloudflarePayments {
  readonly settings: PaymentSettings;
  readonly stripe: () => StripeClient;
  readonly sessions: HostedSessionCreator;
  readonly checkoutOrigin: string;
}

export function cloudflarePayments(shop: EmbeddedShop, secretKey: () => string | undefined): CloudflarePayments {
  const payments = getEmbeddedPayments();
  let client: (() => StripeClient) | null = null;
  const stripe = (): StripeClient => {
    client ??= lazyStripeClient({ secretKey: secretKey(), mode: payments?.mode ?? "test", apiBase: payments?.apiBase ?? null });
    return client();
  };
  return {
    settings: { tenantId: shop.tenantId, livemode: payments?.mode === "live" },
    stripe,
    sessions: new StripeHostedSessionCreator(stripe, shop),
    checkoutOrigin: checkoutOrigin(payments?.apiBase ?? null),
  };
}

export function cloudflareWorkRegistry(env: TenantStoreEnv, providerEvents: (settings: PaymentSettings) => ProviderEventHandlers): WorkRegistry {
  const payments = cloudflarePayments(getEmbeddedShop(), () => env.STRIPE_SECRET_KEY);
  const registry = registerStandardKinds(new WorkRegistry(), {
    stripe: payments.stripe,
    blobs: r2BlobStore(env.MEDIA),
    providerEvents: providerEvents(payments.settings),
  });
  const shop = getEmbeddedShop();
  const email = getEmbeddedEmail();
  return registerEmailKinds(registerPaymentKinds(registry, payments), {
    sender: lazyEmailSender({
      tenantId: shop.tenantId, linkOrigin: shop.origin, from: email?.from, replyTo: email?.replyTo ?? null, apiBase: email?.apiBase ?? null,
      resendApiKey: env.RESEND_API_KEY, accessKey: env.ORDER_ACCESS_KEY, fetch: (input, init) => fetch(input, init),
    }),
  });
}
