import { Effect } from "effect";
import type { AuditRecord } from "../commerce/audit.ts";
import type { CommerceQueries, CommerceQueryRow } from "../commerce/queries.ts";
import type { InventoryInvariantError } from "../commerce/inventory.ts";
import { executeStock, executeStockSync, type StockResult } from "../commerce/stock_store.ts";
import type { StockCommand, StockContext } from "../commerce/stock.ts";
import { DatabaseError, type SQLValue, type SyncTransaction, type Transaction } from "../storefront/persistence.ts";
import type { AdminQueries, AdminQueryRow, AdminRowQueryName, AdminWriteQueryName } from "./queries.ts";

export interface ProgramQueries {
  readonly admin: AdminQueries;
  readonly commerce: CommerceQueries;
}

type Step =
  | { readonly kind: "get"; readonly name: AdminRowQueryName; readonly params: readonly SQLValue[] }
  | { readonly kind: "all"; readonly name: AdminRowQueryName; readonly params: readonly SQLValue[] }
  | { readonly kind: "run"; readonly name: AdminWriteQueryName; readonly params: readonly SQLValue[] }
  | { readonly kind: "stock-read"; readonly variantId: bigint }
  | { readonly kind: "audit"; readonly record: AuditRecord; readonly nowSeconds: bigint }
  | { readonly kind: "stock"; readonly commands: readonly StockCommand[]; readonly context: StockContext };

export type Program<T> = Generator<Step, T, unknown>;

export function* get<N extends AdminRowQueryName>(name: N, params: readonly SQLValue[]): Program<AdminQueryRow<N> | null> {
  return (yield { kind: "get", name, params }) as AdminQueryRow<N> | null;
}

export function* all<N extends AdminRowQueryName>(name: N, params: readonly SQLValue[]): Program<readonly AdminQueryRow<N>[]> {
  return (yield { kind: "all", name, params }) as readonly AdminQueryRow<N>[];
}

export function* run(name: AdminWriteQueryName, params: readonly SQLValue[]): Program<bigint> {
  return (yield { kind: "run", name, params }) as bigint;
}

export function* stockRead(variantId: bigint): Program<CommerceQueryRow<"GetStockRead"> | null> {
  return (yield { kind: "stock-read", variantId }) as CommerceQueryRow<"GetStockRead"> | null;
}

export function* audit(record: AuditRecord, nowSeconds: bigint): Program<void> {
  yield { kind: "audit", record, nowSeconds };
}

export function* stock(commands: readonly StockCommand[], context: StockContext): Program<StockResult> {
  return (yield { kind: "stock", commands, context }) as StockResult;
}

function auditParams(record: AuditRecord, nowSeconds: bigint): readonly SQLValue[] {
  return [record.actor, record.action, record.entityKind, record.entityId, record.entityRevision, record.summary, nowSeconds];
}

function stepSync(tx: SyncTransaction, queries: ProgramQueries, step: Step): unknown {
  switch (step.kind) {
    case "get": {
      const { sql, params } = queries.admin.prepare(step.name, step.params);
      const row = tx.get(sql, params);
      return row === null ? null : queries.admin.decodeRow(step.name, row);
    }
    case "all": {
      const { sql, params } = queries.admin.prepare(step.name, step.params);
      return tx.all(sql, params).map((row) => queries.admin.decodeRow(step.name, row));
    }
    case "run": {
      const { sql, params } = queries.admin.prepare(step.name, step.params);
      return tx.run(sql, params).changes;
    }
    case "stock-read": return queries.commerce.getSync(tx, "GetStockRead", [step.variantId]);
    case "audit": return queries.commerce.runSync(tx, "InsertAuditEvent", auditParams(step.record, step.nowSeconds));
    case "stock": return executeStockSync(tx, queries.commerce, step.commands, step.context);
  }
}

export function runProgramSync<T>(tx: SyncTransaction, queries: ProgramQueries, program: Program<T>): T {
  let next = program.next();
  while (next.done !== true) next = program.next(stepSync(tx, queries, next.value));
  return next.value;
}

function stepEffect(tx: Transaction, queries: ProgramQueries, step: Step): Effect.Effect<unknown, DatabaseError | InventoryInvariantError> {
  switch (step.kind) {
    case "get":
    case "all":
    case "run":
      return Effect.flatMap(
        Effect.try({ try: () => queries.admin.prepare(step.name, step.params), catch: (cause) => cause as DatabaseError }),
        ({ sql, params }) => {
          if (step.kind === "run") return Effect.map(tx.run(sql, params), (result) => result.changes as unknown);
          if (step.kind === "get") {
            return Effect.flatMap(tx.get(sql, params), (row) => row === null ? Effect.succeed(null as unknown) : Effect.try({ try: () => queries.admin.decodeRow(step.name as AdminRowQueryName, row) as unknown, catch: (cause) => cause as DatabaseError }));
          }
          return Effect.flatMap(tx.all(sql, params), (rows) => Effect.try({ try: () => rows.map((row) => queries.admin.decodeRow(step.name as AdminRowQueryName, row)) as unknown, catch: (cause) => cause as DatabaseError }));
        },
      );
    case "stock-read": return queries.commerce.get(tx, "GetStockRead", [step.variantId]);
    case "audit": return queries.commerce.run(tx, "InsertAuditEvent", auditParams(step.record, step.nowSeconds));
    case "stock": return executeStock(tx, queries.commerce, step.commands, step.context);
  }
}

export function runProgramEffect<T>(tx: Transaction, queries: ProgramQueries, program: Program<T>): Effect.Effect<T, DatabaseError | InventoryInvariantError> {
  return Effect.gen(function* () {
    let next = yield* Effect.try({ try: () => program.next(), catch: (cause) => cause instanceof DatabaseError ? cause : new DatabaseError("admin: program failed", cause) });
    while (next.done !== true) {
      const result: unknown = yield* stepEffect(tx, queries, next.value);
      next = yield* Effect.try({ try: () => program.next(result), catch: (cause) => cause instanceof DatabaseError ? cause : new DatabaseError("admin: program failed", cause) });
    }
    return next.value;
  });
}
