import { Schema } from "effect";
import { ContentTypes } from "../media/format.ts";
import { MaintenanceBatch } from "../media/limits.ts";
import { Integer } from "../storefront/queries.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Purpose = Schema.String.check(filter<string>((value) => /^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= 128, "must be a purpose label"));
const ContentType = Schema.Literals(ContentTypes as readonly [string, ...string[]]);

const MediaFile = Schema.Struct({ sha256: Digest, bytes: Integer, width: Integer, height: Integer, contentType: ContentType });
const Collected = Schema.Struct({ id: Integer, sha256: Digest, contentType: ContentType });
export type CollectedMedia = typeof Collected.Type;

export const MediaReserveRejections = ["too_many_pending", "library_full", "unknown_product", "image_limit"] as const;
export type MediaReserveRejection = (typeof MediaReserveRejections)[number];

export const MediaCommandSchemas = [
  Schema.Struct({
    kind: Schema.Literal("media.reserve"),
    sessionDigest: Digest,
    formTokenDigest: Digest,
    purpose: Purpose,
    productId: Integer,
    expectedRevision: Integer,
    nowSeconds: Seconds,
    files: Schema.Array(MediaFile).check(filter((files) => files.length >= 1 && files.length <= 2, "reserve one or two files")),
  }),
  Schema.Struct({ kind: Schema.Literal("media.expire"), nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("media.collect"), nowSeconds: Seconds }),
  Schema.Struct({
    kind: Schema.Literal("media.orphans"),
    ids: Schema.Array(Integer).check(filter((ids) => ids.length <= MaintenanceBatch, "too many ids")),
  }),
] as const;

export const MediaResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("media.reserve"), outcome: Schema.Literal("reserved"), ids: Schema.Array(Integer) }),
  Schema.Struct({ kind: Schema.Literal("media.reserve"), outcome: Schema.Literals(["session_invalid", "token_invalid", "stale"]) }),
  Schema.Struct({ kind: Schema.Literal("media.reserve"), outcome: Schema.Literal("rejected"), rejection: Schema.Literals(MediaReserveRejections) }),
  Schema.Struct({ kind: Schema.Literal("media.expire"), removed: Schema.Array(Collected) }),
  Schema.Struct({ kind: Schema.Literal("media.collect"), removed: Schema.Array(Collected) }),
  Schema.Struct({ kind: Schema.Literal("media.orphans"), orphans: Schema.Array(Integer) }),
] as const;

export const MediaQuerySchema = Schema.Struct({ kind: Schema.Literal("media.asset"), mediaId: Integer });
export const MediaQueryResultSchema = Schema.Struct({
  kind: Schema.Literal("media.asset"),
  asset: Schema.NullOr(Schema.Struct({ sha256: Digest, contentType: ContentType, state: Schema.Literals(["pending", "ready"]) })),
});
