import { Schema } from "effect";
import { BlockProblemKinds, InfoKinds, StoredBlockSchema } from "../storefront/info.ts";
import { Integer } from "../storefront/queries.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Purpose = Schema.String.check(filter<string>((value) => /^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= 128, "must be a purpose label"));

const Kind = Schema.Literals(InfoKinds);

export const ShopRejectionKinds = [...BlockProblemKinds, "invalid", "nothing_to_review"] as const;
export type ShopRejectionKind = (typeof ShopRejectionKinds)[number];
const Rejection = Schema.Struct({ subject: Schema.String, kind: Schema.Literals(ShopRejectionKinds) });
export type ShopRejection = typeof Rejection.Type;

export const ShopChangeSchema = Schema.Union([
  Schema.Struct({
    action: Schema.Literal("identity.save"), expectedRevision: Integer,
    name: Schema.String, description: Schema.String, contactEmail: Schema.NullOr(Schema.String), contactPhone: Schema.NullOr(Schema.String),
  }),
  Schema.Struct({ action: Schema.Literal("page.save"), kind: Kind, expectedRevision: Integer, blocks: Schema.Array(StoredBlockSchema) }),
  Schema.Struct({ action: Schema.Literal("page.review"), kind: Kind, expectedRevision: Integer }),
]);
export type ShopChange = typeof ShopChangeSchema.Type;

export const ShopMutateCommand = Schema.Struct({
  kind: Schema.Literal("shop.mutate"),
  sessionDigest: Digest,
  formTokenDigest: Digest,
  purpose: Purpose,
  actor: Schema.String,
  nowSeconds: Seconds,
  change: ShopChangeSchema,
});

export const ShopFormCommand = Schema.Struct({
  kind: Schema.Literal("shop.form"),
  tokenDigest: Digest,
  sessionDigest: Digest,
  purpose: Purpose,
  nowSeconds: Seconds,
});

const Review = Schema.Struct({ by: Schema.String, revision: Integer, at: Integer });
const PageView = Schema.Struct({
  kind: Kind,
  blocks: Schema.Array(StoredBlockSchema),
  revision: Integer,
  updatedAt: Integer,
  review: Schema.NullOr(Review),
});
export type ShopPageView = typeof PageView.Type;

export const ShopView = Schema.NullOr(Schema.Struct({
  name: Schema.String,
  description: Schema.String,
  contactEmail: Schema.NullOr(Schema.String),
  contactPhone: Schema.NullOr(Schema.String),
  revision: Integer,
  updatedAt: Integer,
  pages: Schema.Array(PageView),
}));
export type ShopViewModel = NonNullable<typeof ShopView.Type>;

export const ShopQuerySchema = Schema.Struct({ kind: Schema.Literal("shop.view") });
export const ShopQueryResultSchema = Schema.Struct({ kind: Schema.Literal("shop.view"), view: ShopView });

export const ShopResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("shop.form"), issued: Schema.Boolean, view: ShopView }),
  Schema.Struct({ kind: Schema.Literal("shop.mutate"), outcome: Schema.Literal("applied"), revision: Integer }),
  Schema.Struct({ kind: Schema.Literal("shop.mutate"), outcome: Schema.Literals(["session_invalid", "token_invalid", "stale", "missing_store"]) }),
  Schema.Struct({ kind: Schema.Literal("shop.mutate"), outcome: Schema.Literal("rejected"), rejections: Schema.Array(Rejection) }),
] as const;
