import type { Mutation } from "../admin/guard.ts";
import { all, audit, get, run, type Program } from "../admin/program.ts";
import type { AdminQueryRow } from "../admin/queries.ts";
import { queueRefund } from "./email_program.ts";
import type { PaymentState } from "./payment.ts";
import { exception, settleRow } from "./payment_program.ts";
import {
  canObserveRefund, decideRefund, externalRefundFits, MaxRefundMinor, refundCounts, refundSettled,
  type RefundOrderFacts, type RefundRejection, type RefundState,
} from "./refund.ts";
import type { QuantityRequest } from "./cancel.ts";
import type { RefundFacts, RefundQueryResult } from "./refund_operations.ts";
import type { ProviderOperationState } from "./operation.ts";

export const RefundKind = "refund";
export const RefundActor = "payments";
export const refundKey = (refundId: bigint): string => `${RefundKind}:${refundId}`;

export interface SettledRefund {
  readonly orderId: bigint;
  readonly orderNumber: bigint;
  readonly refundId: bigint;
  readonly state: RefundState;
  readonly amountMinor: bigint;
  readonly nowSeconds: bigint;
}

export function* afterRefundSettled(refund: SettledRefund): Program<void> {
  if (refund.state === "succeeded") yield* queueRefund(refund.orderId, refund.refundId, refund.nowSeconds);
}

export interface RefundChange {
  readonly number: bigint;
  readonly expectedRevision: bigint;
  readonly lines: readonly QuantityRequest[];
  readonly shipping: boolean;
  readonly reason: string;
}

export interface RefundContext {
  readonly actor: string;
  readonly nowSeconds: bigint;
}

export type RefundRefusal =
  | { readonly kind: "not_found" }
  | { readonly kind: "stale" }
  | { readonly kind: "rejected"; readonly rejection: RefundRejection };

type OrderRow = AdminQueryRow<"GetOrderDetail">;

export function* readRefundFacts(order: OrderRow): Program<RefundOrderFacts> {
  const totals = yield* get("GetRefundTotals", [order.id]);
  if (totals === null) throw new Error("refunds: the refund totals aggregate returned no row");
  const lines = yield* all("ListOrderLineStates", [order.id]);
  const refunded = new Map((yield* all("ListRefundLineQuantities", [order.id])).map((row) => [row.position, row.quantity]));
  return {
    paymentState: order.payment_state as PaymentState,
    capturedMinor: order.amount_captured_minor,
    activeRefundedMinor: totals.active_minor,
    shippingMinor: order.shipping_minor,
    shippingTaxMinor: order.shipping_tax_minor,
    activeShippingRefundedMinor: totals.shipping_minor,
    activeShippingTaxRefundedMinor: totals.shipping_tax_minor,
    lines: lines.map((row) => ({
      position: row.position, orderedQuantity: row.quantity, unitPriceMinor: row.unit_price_minor, lineTaxMinor: row.tax_minor, refundedQuantity: refunded.get(row.position) ?? 0n,
    })),
  };
}

export function* refundEffect(change: RefundChange, context: RefundContext): Program<Mutation<{ readonly refundId: bigint }, RefundRefusal>> {
  const refused = (refusal: RefundRefusal): Mutation<{ readonly refundId: bigint }, RefundRefusal> => ({ applied: false, result: refusal });
  const order = yield* get("GetOrderDetail", [change.number]);
  if (order === null) return refused({ kind: "not_found" });
  if (order.revision !== change.expectedRevision) return refused({ kind: "stale" });
  const decision = decideRefund(yield* readRefundFacts(order), change);
  if (!decision.ok) return refused({ kind: "rejected", rejection: decision.rejection });
  const { plan } = decision;
  const now = context.nowSeconds;

  yield* run("InsertRefund", [order.id, plan.amountMinor, plan.itemsMinor, plan.itemTaxMinor, plan.shippingMinor, plan.shippingTaxMinor, change.reason, context.actor, now, now]);
  const refundId = (yield* get("GetNewestRefund", [order.id]))?.id;
  if (refundId === undefined) throw new Error(`refunds: the refund for order ${order.number} was not written`);
  for (const line of plan.lines) yield* run("InsertRefundLine", [refundId, order.id, line.position, line.quantity, line.itemMinor, line.taxMinor]);
  yield* run("ScheduleWork", [RefundKind, refundKey(refundId), JSON.stringify({ refund: refundId.toString() }), now, now, now]);
  if ((yield* run("BumpOrderRevision", [order.id, order.revision])) !== 1n) throw new Error(`refunds: order ${order.number} changed during the refund request`);
  yield* audit({
    actor: context.actor, action: "refund.request", entityKind: "order", entityId: order.id.toString(), entityRevision: order.revision + 1n,
    summary: `refund ${refundId} of ${plan.amountMinor} ${order.currency_code} requested: ${change.reason}`.slice(0, 1000),
  }, now);
  return { applied: true, result: { refundId } };
}

export type ObserveOutcome = "unchanged" | "advanced" | "recorded" | "unmapped" | "ignored";

function failureText(facts: RefundFacts): string | null {
  if (facts.status !== "failed" && facts.status !== "canceled") return null;
  return (facts.failureReason ?? `Stripe reported the refund as ${facts.status}`).slice(0, 500);
}

function* settledHook(orderId: bigint, orderNumber: bigint, refundId: bigint, state: RefundState, amountMinor: bigint, now: bigint, actor: string, detail: string): Program<void> {
  if (!refundSettled(state)) return;
  yield* audit({
    actor, action: "refund.settle", entityKind: "order", entityId: orderId.toString(), entityRevision: null,
    summary: `refund ${refundId} of ${amountMinor} is ${state}${detail === "" ? "" : `: ${detail}`}`.slice(0, 1000),
  }, now);
  yield* afterRefundSettled({ orderId, orderNumber, refundId, state, amountMinor, nowSeconds: now });
}

export function* observeRefund(facts: RefundFacts, now: bigint): Program<ObserveOutcome> {
  if (facts.paymentIntentId === null) return "ignored";
  const payment = yield* get("GetPaymentByIntent", [facts.paymentIntentId]);
  if (payment === null) return "ignored";
  const flag = function* (detail: string): Program<ObserveOutcome> {
    yield* exception(payment.attempt_id, payment.order_id, "unmapped_state", facts.id, true, detail, now);
    return "unmapped";
  };
  if (facts.currency.toLowerCase() !== payment.currency_code.toLowerCase()) return yield* flag(`refund ${facts.id} is in ${facts.currency}, not the order currency`);

  let row = yield* get("GetRefundByProviderId", [facts.id]);
  if (row === null && facts.localId !== null) {
    const local = yield* get("GetRefund", [BigInt(facts.localId)]);
    if (local !== null && local.payment_intent_id === facts.paymentIntentId) row = local;
  }

  if (row === null) {
    if (facts.amount < 1n || facts.amount > MaxRefundMinor) return yield* flag(`refund ${facts.id} has an amount outside the supported range`);
    const totals = yield* get("GetRefundTotals", [payment.order_id]);
    if (totals === null) throw new Error("refunds: the refund totals aggregate returned no row");
    const fits = externalRefundFits({ paymentState: payment.state as PaymentState, capturedMinor: payment.amount_captured_minor, activeRefundedMinor: totals.active_minor, amountMinor: facts.amount });
    if (refundCounts(facts.status) && !fits) {
      return yield* flag(`refund ${facts.id} for ${facts.amount} ${payment.currency_code} was not requested by Nanoshop and does not fit the captured balance; reconcile it in the Stripe dashboard`);
    }
    yield* run("InsertExternalRefund", [payment.order_id, facts.status, facts.amount, facts.amount, facts.id, failureText(facts), now, now]);
    const created = yield* get("GetRefundByProviderId", [facts.id]);
    if (created === null) throw new Error(`refunds: the external refund ${facts.id} was not written`);
    yield* audit({
      actor: RefundActor, action: "refund.record", entityKind: "order", entityId: payment.order_id.toString(), entityRevision: null,
      summary: `refund ${created.id} of ${facts.amount} ${payment.currency_code} created in the Stripe dashboard is ${facts.status}`,
    }, now);
    yield* settledHook(payment.order_id, payment.number, created.id, facts.status, facts.amount, now, RefundActor, "");
    return "recorded";
  }

  if (row.provider_refund_id !== null && row.provider_refund_id !== facts.id) return yield* flag(`refund ${row.id} is already bound to ${row.provider_refund_id}, not ${facts.id}`);
  if (row.amount_minor !== facts.amount) return yield* flag(`refund ${facts.id} is for ${facts.amount} but local refund ${row.id} is for ${row.amount_minor}`);

  const current = row.state as RefundState;
  let outcome: ObserveOutcome = "unchanged";
  if (current !== facts.status) {
    if (!canObserveRefund(current, facts.status)) return yield* flag(`refund ${row.id} is ${current} here but Stripe reports ${facts.status}`);
    if ((yield* run("SetRefundState", [facts.status, facts.id, failureText(facts), now, row.id, current])) < 1n) throw new Error(`refunds: refund ${row.id} changed during observation`);
    yield* settledHook(row.order_id, row.number, row.id, facts.status, row.amount_minor, now, RefundActor, failureText(facts) ?? "");
    outcome = "advanced";
  } else if (row.provider_refund_id === null) {
    yield* run("SetRefundState", [current, facts.id, null, now, row.id, current]);
  }
  const operation = yield* get("GetOperation", ["refund", row.id.toString()]);
  if (operation !== null && operation.state !== "succeeded") yield* settleRow(operation, "succeeded", facts.id, null, now);
  return outcome;
}

export function* failRefund(refundId: bigint, to: "failed" | "blocked", error: string, now: bigint): Program<boolean> {
  const row = yield* get("GetRefund", [refundId]);
  if (row === null) return false;
  const detail = error.slice(0, 500);
  let changed = false;
  const state = row.state as RefundState;
  if (state === "pending" || state === "requires_action") {
    changed = (yield* run("SetRefundState", ["failed", null, detail, now, row.id, state])) > 0n;
    if (changed) yield* settledHook(row.order_id, row.number, row.id, "failed", row.amount_minor, now, RefundActor, detail);
  }
  const operation = yield* get("GetOperation", ["refund", row.id.toString()]);
  if (operation !== null) yield* settleRow(operation, to, null, detail, now);
  if (to === "blocked") {
    const payment = yield* get("GetPaymentByIntent", [row.payment_intent_id]);
    if (payment !== null) {
      yield* exception(payment.attempt_id, payment.order_id, "operation_blocked", `refund:${row.id}`, true, `refund ${row.id} needs operator review: ${detail}`, now);
    }
  }
  return changed;
}

export function* refundViewProgram(refundId: bigint): Program<RefundQueryResult> {
  const row = yield* get("GetRefund", [refundId]);
  if (row === null) return { kind: "refund.view", refund: null };
  const operation = yield* get("GetOperation", ["refund", row.id.toString()]);
  return {
    kind: "refund.view",
    refund: {
      id: row.id, orderNumber: row.number, state: row.state as RefundState, amountMinor: row.amount_minor, paymentIntentId: row.payment_intent_id,
      currency: row.currency_code, providerRefundId: row.provider_refund_id,
      operation: operation === null ? null : {
        state: operation.state as ProviderOperationState, key: operation.idempotency_key, attempts: operation.attempts, providerObjectId: operation.provider_object_id, createdAt: Number(operation.created_at),
      },
    },
  };
}
