import { parseRouteName, routePath } from "../routes/routes.ts";
import { render } from "../dsl/render.ts";
import type { PageRenderer } from "../web/tenant.ts";

function encodeBehaviorJSON(value: unknown): string {
  const encoded = JSON.stringify(value);
  if (encoded === undefined) throw new Error("theme: behavior payload is not JSON encodable");
  return encoded.replace(/[<>&\u2028\u2029]/g, (character) => {
    switch (character) {
      case "<": return "\\u003c";
      case ">": return "\\u003e";
      case "&": return "\\u0026";
      case "\u2028": return "\\u2028";
      case "\u2029": return "\\u2029";
      default: return character;
    }
  });
}

/** Bridges immutable view frames to the closed theme program interpreter. */
export const renderPage: PageRenderer = (program, frame, options) => render(
  program,
  { Shop: frame.shop, Page: frame.page },
  {
    routes: { path: (name, parameters) => routePath(parseRouteName(name), parameters) },
    featured: frame.featured,
    encodeJSON: (_type, value) => encodeBehaviorJSON(value),
    signal: options.signal,
    maxOutputBytes: options.maxBytes,
    maxSteps: options.maxSteps,
  },
);
