import { adminPath } from "../routes/admin.ts";
import { fragments, html, type Html } from "./html.ts";
import { fieldError, layout, noticeBlock, type FieldErrors, type Notice } from "./pages.ts";
import { shippingFormFromView, SortedRegions, taxFormFromView, taxRow, zoneSlots, type ShippingForm, type TaxForm } from "./settings_form.ts";
import type { SettingsViewModel } from "./settings_operations.ts";

export interface SettingsPageBase {
  readonly principalLabel: string;
  readonly formToken: string;
  readonly view: SettingsViewModel;
  readonly notice: Notice | null;
  readonly errors: FieldErrors;
}

function stamp(seconds: bigint): string {
  return new Date(Number(seconds) * 1000).toISOString();
}

function provenance(entry: { readonly version: bigint; readonly createdAt: bigint; readonly createdBy: string | null }): Html {
  return html`Version ${entry.version}, saved <time datetime="${stamp(entry.createdAt)}">${stamp(entry.createdAt)}</time> by ${entry.createdBy ?? "an unrecorded author"}.`;
}

export interface CheckoutInput {
  readonly paused: boolean;
  readonly maxActiveHolds: string;
}

export function checkoutInputFromView(view: SettingsViewModel): CheckoutInput {
  return { paused: view.checkout.paused, maxActiveHolds: view.checkout.maxActiveHolds.toString() };
}

export function settingsPage(state: SettingsPageBase & { readonly input: CheckoutInput; readonly conflict: boolean }): Html {
  const { view, input } = state;
  const taxLine = view.tax === null
    ? html`<p>Not configured. Until a tax policy is saved, checkout answers that it is not available.</p>`
    : html`<p>${view.tax.mode === "rate_table" ? `Rate table, ${view.tax.rates.length} regions.` : "No tax collected."} ${provenance(view.tax)}</p>`;
  const shippingLine = view.shipping === null
    ? html`<p>Not configured. Until a shipping policy is saved, checkout answers that it is not available.</p>`
    : html`<p>Ships from ${view.shipping.originRegion}, ${view.shipping.zones.length} zones${view.shipping.localPickup ? ", local pickup" : ""}. ${provenance(view.shipping)}</p>`;
  const current = state.conflict
    ? html`<section aria-label="Conflict"><h2>Compare</h2><div><h3>Your input</h3><dl><dt>Checkout</dt><dd>${input.paused ? "Paused" : "Open"}</dd><dt>Max active holds</dt><dd>${input.maxActiveHolds}</dd></dl></div><div><h3>Current values</h3><dl><dt>Checkout</dt><dd>${view.checkout.paused ? "Paused" : "Open"}</dd><dt>Max active holds</dt><dd>${view.checkout.maxActiveHolds}</dd></dl></div></section>`
    : html``;
  return layout("Settings", state.principalLabel, html`${noticeBlock(state.notice)}${current}
<h2>Checkout</h2>
<p>Checkout is <strong>${view.checkout.paused ? "paused" : "open"}</strong>. Pausing refuses new quotes and acceptances only; payments already in progress, webhooks, orders, and refunds keep working.</p>
<form method="post" action="${adminPath("admin-settings-checkout")}">
<input type="hidden" name="form_token" value="${state.formToken}">
<input type="hidden" name="revision" value="${view.checkout.revision}">
<p><label><input type="checkbox" name="paused" value="on"${input.paused ? html` checked` : html``}> Pause checkout</label></p>
<p><label>Most active stock holds (50 to 500) <input name="max_active_holds" inputmode="numeric" autocomplete="off" value="${input.maxActiveHolds}" aria-describedby="max_active_holds-error" required></label></p>
${fieldError(state.errors, "max_active_holds")}
<button type="submit">Save checkout settings</button>
</form>
<h2>Shop identity and pages</h2>
<p><a href="${adminPath("admin-settings-identity")}">Shop name, description, and contact</a></p>
<p><a href="${adminPath("admin-pages")}">About, shipping, returns, privacy, and terms pages</a></p>
<h2>Tax</h2>
${taxLine}
<p><a href="${adminPath("admin-settings-tax")}">${view.tax === null ? "Set up tax" : "Edit tax policy"}</a></p>
<h2>Shipping</h2>
${shippingLine}
<p><a href="${adminPath("admin-settings-shipping")}">${view.shipping === null ? "Set up shipping" : "Edit shipping policy"}</a></p>`);
}

function taxSummary(form: TaxForm): Html {
  if (form.mode === "no_tax_collected") return html`<p>No tax collected.</p>`;
  const rows = SortedRegions.filter((region) => taxRow(form, region).rate !== "");
  return html`<ul>${fragments(rows.map((region) => {
    const row = taxRow(form, region);
    return html`<li>${region}: ${row.rate}%${row.lines ? ", products" : ""}${row.shipping ? ", shipping" : ""}</li>`;
  }))}</ul>`;
}

export function taxPage(state: SettingsPageBase & { readonly form: TaxForm; readonly conflict: boolean }): Html {
  const { view, form } = state;
  const heading = view.tax === null
    ? html`<p>No tax policy is saved yet. Checkout stays unavailable until you save one.</p>`
    : html`<p>Current policy. ${provenance(view.tax)}</p>`;
  const conflict = state.conflict
    ? html`<section aria-label="Conflict"><h2>Compare</h2><div><h3>Your input</h3>${taxSummary(form)}</div><div><h3>Current values</h3>${taxSummary(taxFormFromView(view.tax))}</div></section>`
    : html``;
  const rows = SortedRegions.map((region) => {
    const row = taxRow(form, region);
    return html`<fieldset><legend>${region}</legend>
<p><label>Rate in percent <input name="rate_${region}" inputmode="decimal" autocomplete="off" value="${row.rate}" aria-describedby="rate_${region}-error"></label></p>
${fieldError(state.errors, `rate_${region}`)}
<p><label><input type="checkbox" name="lines_${region}" value="on"${row.lines ? html` checked` : html``}> Tax products</label></p>
<p><label><input type="checkbox" name="shipping_${region}" value="on"${row.shipping ? html` checked` : html``}> Tax shipping</label></p>
</fieldset>`;
  });
  return layout("Tax policy", state.principalLabel, html`<p><a href="${adminPath("admin-settings")}">Settings</a></p>${noticeBlock(state.notice)}${conflict}${heading}
<p>Saving creates a new version. Quotes already made keep the version they were priced with. A ZIP code does not establish tax jurisdiction; rates are per state.</p>
<form method="post" action="${adminPath("admin-settings-tax-save")}">
<input type="hidden" name="form_token" value="${state.formToken}">
<input type="hidden" name="version" value="${view.tax?.version ?? 0n}">
<fieldset><legend>Tax treatment</legend>
<p><label><input type="radio" name="mode" value="rate_table"${form.mode === "rate_table" ? html` checked` : html``}> Collect tax at the rates below</label></p>
<p><label><input type="radio" name="mode" value="no_tax_collected"${form.mode === "no_tax_collected" ? html` checked` : html``}> I confirm no tax is collected on orders</label></p>
</fieldset>
${fieldError(state.errors, "mode")}
<h2>Rates by state</h2>
<p>Enter a percentage with up to 4 decimals, for example 7.25. Leave a state blank to refuse orders shipped there.</p>
${fragments(rows)}
<button type="submit">Save tax policy</button>
</form>`);
}

function shippingSummary(form: ShippingForm, currency: string): Html {
  const zones = form.zones.filter((zone) => zone.name !== "");
  return html`<dl><dt>Ships from</dt><dd>${form.origin}</dd><dt>Free shipping from</dt><dd>${form.threshold === "" ? "never" : `${form.threshold} ${currency}`}</dd><dt>Local pickup</dt><dd>${form.pickup ? "yes" : "no"}</dd></dl>
<ul>${fragments(zones.map((zone) => html`<li>${zone.name}: ${zone.rate} ${currency}, ${zone.regions}</li>`))}</ul>`;
}

export function shippingPage(state: SettingsPageBase & { readonly form: ShippingForm; readonly conflict: boolean }): Html {
  const { view, form } = state;
  const currency = view.currency?.code ?? "";
  const heading = view.shipping === null
    ? html`<p>No shipping policy is saved yet. Checkout stays unavailable until you save one.</p>`
    : html`<p>Current policy. ${provenance(view.shipping)}</p>`;
  const conflict = state.conflict
    ? html`<section aria-label="Conflict"><h2>Compare</h2><div><h3>Your input</h3>${shippingSummary(form, currency)}</div><div><h3>Current values</h3>${shippingSummary(shippingFormFromView(view.shipping, view.currency?.exponent ?? 2), currency)}</div></section>`
    : html``;
  const slots = zoneSlots(form);
  const zones = Array.from({ length: slots }, (_, slot) => {
    const zone = form.zones[slot] ?? { name: "", rate: "", regions: "" };
    return html`<fieldset><legend>Zone ${slot + 1}</legend>
<p><label>Name <input name="zone_${slot}_name" maxlength="100" autocomplete="off" value="${zone.name}" aria-describedby="zone_${slot}_name-error"></label></p>
${fieldError(state.errors, `zone_${slot}_name`)}
<p><label>Flat rate in ${currency} <input name="zone_${slot}_rate" inputmode="decimal" autocomplete="off" value="${zone.rate}" aria-describedby="zone_${slot}_rate-error"></label></p>
${fieldError(state.errors, `zone_${slot}_rate`)}
<p><label>State codes, for example WA OR CA <input name="zone_${slot}_regions" maxlength="400" autocomplete="off" value="${zone.regions}" aria-describedby="zone_${slot}_regions-error"></label></p>
${fieldError(state.errors, `zone_${slot}_regions`)}
</fieldset>`;
  });
  return layout("Shipping policy", state.principalLabel, html`<p><a href="${adminPath("admin-settings")}">Settings</a></p>${noticeBlock(state.notice)}${conflict}${heading}
<p>Saving creates a new version. Quotes already made keep the version they were priced with. A state belongs to at most one zone. To remove a zone, clear its three fields.</p>
<form method="post" action="${adminPath("admin-settings-shipping-save")}">
<input type="hidden" name="form_token" value="${state.formToken}">
<input type="hidden" name="version" value="${view.shipping?.version ?? 0n}">
<p><label>Ship from (state code) <input name="origin" maxlength="2" autocomplete="off" value="${form.origin}" aria-describedby="origin-error" required></label></p>
${fieldError(state.errors, "origin")}
<p><label>Free shipping when merchandise reaches, in ${currency} (blank for never) <input name="threshold" inputmode="decimal" autocomplete="off" value="${form.threshold}" aria-describedby="threshold-error"></label></p>
${fieldError(state.errors, "threshold")}
<p><label><input type="checkbox" name="pickup" value="on"${form.pickup ? html` checked` : html``}> Offer local pickup</label></p>
<h2>Zones</h2>
${fragments(zones)}
<button type="submit">Save shipping policy</button>
</form>`);
}
