export interface StateMachine<S extends string> {
  readonly initial: S;
  readonly edges: Readonly<Record<S, readonly S[]>>;
}

export type Transition<S extends string> =
  | { readonly ok: true; readonly state: S }
  | { readonly ok: false; readonly from: S; readonly to: S };

export function canTransition<S extends string>(machine: StateMachine<S>, from: S, to: S): boolean {
  return machine.edges[from].includes(to);
}

export function transition<S extends string>(machine: StateMachine<S>, from: S, to: S): Transition<S> {
  return canTransition(machine, from, to) ? { ok: true, state: to } : { ok: false, from, to };
}

export function isTerminal<S extends string>(machine: StateMachine<S>, state: S): boolean {
  return machine.edges[state].length === 0;
}

export function statesOf<S extends string>(machine: StateMachine<S>): readonly S[] {
  return Object.keys(machine.edges) as S[];
}
