import { BadInput, formFields } from "../web/decode.ts";
import { checkOrigin, SecurityError } from "../web/security.ts";
import { principalId, authorize, type TenantGrants } from "../identity/principal.ts";
import { AssertionError } from "../identity/assertion.ts";
import type { Authenticator } from "../identity/authenticator.ts";
import {
  adminSessionCookie,
  clearedAdminCookie,
  clearedSignInStateCookie,
  newSignInState,
  readAdminToken,
  readSignInState,
  signInStateCookie,
  type SignInPurpose,
} from "../identity/cookie.ts";
import { reauthRequired } from "../identity/policy.ts";
import { adminPath, matchAdminRoute, safeAdminReturn, type AdminRouteName } from "../routes/admin.ts";
import { newToken, parseToken, tokenDigest } from "../session/session.ts";
import type { AdminBackend } from "./backend.ts";
import { MaxPurposeLength, digestHex, type AdminSessionView, type StockLevelView } from "./operations.ts";
import { page, redirect, withCookies } from "./response.ts";
import type { BlobStore } from "../media/blob.ts";
import { createCatalogHandler } from "./catalog_handler.ts";
import { createSettingsHandler } from "./settings_handler.ts";
import { createShopHandler } from "./pages_shop_handler.ts";
import { createOrdersHandler } from "./orders_handler.ts";
import { OrdersStylesheet } from "./orders_styles.ts";
import { assetResponse, createMediaHandler, type AdminAsset } from "./media_handler.ts";
import { continuePage, describeRejection, homePage, messagePage, operationsPage, signInPage, stockPage, unauthorizedPage, type FieldErrors, type Notice } from "./pages.ts";

export interface AdminHandlerOptions {
  readonly tenantId: string;
  readonly origin: string;
  readonly localHTTP: boolean;
  readonly grants: TenantGrants;
  readonly authenticator: Authenticator;
  readonly backend: AdminBackend;
  readonly blobs: BlobStore;
  readonly uploader?: AdminAsset;
  readonly nowMs?: () => number;
}

export interface AdminRequest {
  readonly request: Request;
  readonly segments: readonly string[];
  readonly signal: AbortSignal;
}

export interface AdminHandler {
  handle(input: AdminRequest): Promise<Response>;
}

interface Authenticated {
  readonly session: AdminSessionView;
  readonly digest: string;
  readonly label: string;
}

const variantShape = /^[1-9][0-9]{0,18}$/;
const MaxInt64 = 9223372036854775807n;

function stockPurpose(variantId: bigint): string {
  const purpose = `stock.adjust:${variantId}`;
  if (purpose.length > MaxPurposeLength) throw new RangeError("admin: purpose too long");
  return purpose;
}

export function createAdminHandler(options: AdminHandlerOptions): AdminHandler {
  const { backend, authenticator, grants, localHTTP } = options;
  const nowSeconds = (): number => Math.floor((options.nowMs ?? Date.now)() / 1000);
  const uploader = options.uploader ?? null;
  const catalog = createCatalogHandler({ backend, nowSeconds, clearCookies: () => [clearedAdminCookie(localHTTP)], blobs: options.blobs, uploaderPath: uploader === null ? null : `/admin/assets/${uploader.file}` });
  const settings = createSettingsHandler({ backend, nowSeconds, clearCookies: () => [clearedAdminCookie(localHTTP)] });
  const shop = createShopHandler({ backend, nowSeconds, clearCookies: () => [clearedAdminCookie(localHTTP)] });
  const orders = createOrdersHandler({ backend, tenantId: options.tenantId, nowSeconds, clearCookies: () => [clearedAdminCookie(localHTTP)] });
  const media = createMediaHandler({ backend, blobs: options.blobs });

  async function authenticate(request: Request, signal: AbortSignal): Promise<{ readonly auth: Authenticated | null; readonly clear: readonly string[] }> {
    const token = readAdminToken(request.headers, localHTTP);
    if (token === null) return { auth: null, clear: [] };
    const digest = digestHex(await tokenDigest(token));
    const resolved = await backend.command({ kind: "session.resolve", tokenDigest: digest, nowSeconds: nowSeconds() }, signal);
    if (resolved.status !== "valid") return { auth: null, clear: [clearedAdminCookie(localHTTP)] };
    return { auth: { session: resolved.session, digest, label: resolved.session.email ?? resolved.session.subject }, clear: [] };
  }

  function isOwner(auth: Authenticated): boolean {
    return authorize(auth.session, grants) === "owner";
  }

  function reauthRedirect(returnTo: string): Response {
    return redirect(`${adminPath("admin-reauth")}?return=${encodeURIComponent(returnTo)}`);
  }

  async function startSignIn(purpose: SignInPurpose, returnTo: string, sessionDigest: string | null = null): Promise<Response> {
    const state = newSignInState(purpose, returnTo, sessionDigest);
    return redirect(authenticator.begin({ audience: options.origin, nonce: state.nonce, purpose }), [signInStateCookie(state, localHTTP)]);
  }

  async function callback(request: Request, signal: AbortSignal): Promise<Response> {
    const clearState = clearedSignInStateCookie(localHTTP);
    const state = readSignInState(request.headers, localHTTP);
    const refused = (message: string): Response => page(request, 403, messagePage("Sign-in failed", message, null), withCookies([clearState]));
    if (state === null) return refused("This sign-in was not started from this browser. Start again from the store admin.");
    let verified;
    try {
      verified = await authenticator.complete(new URL(request.url), { audience: options.origin, nowSeconds: nowSeconds() });
    } catch (error) {
      if (error instanceof AssertionError) return refused(`The sign-in could not be verified (${error.reason}).`);
      throw error;
    }
    if (verified.nonce !== state.nonce) return refused("This sign-in was not started from this browser. Start again from the store admin.");
    const returnTo = safeAdminReturn(state.returnTo);
    if (state.purpose === "reauth") {
      const reauthenticated = await backend.command({
        kind: "session.reauthenticate", tokenDigest: state.sessionDigest!, issuer: verified.principal.issuer, subject: verified.principal.subject,
        authenticatedAt: verified.authTime, nowSeconds: nowSeconds(),
      }, signal);
      if (!reauthenticated.updated) return refused("Re-authentication must use the identity that is signed in.");
      return page(request, 200, continuePage(returnTo), withCookies([clearState]));
    }
    const token = newToken();
    await backend.command({
      kind: "session.create", tokenDigest: digestHex(await tokenDigest(token)), issuer: verified.principal.issuer, subject: verified.principal.subject,
      email: verified.principal.email, authenticatedAt: verified.authTime, nowSeconds: nowSeconds(),
    }, signal);
    return page(request, 200, continuePage(returnTo), withCookies([adminSessionCookie(token, localHTTP), clearState]));
  }

  async function signOut(request: Request, signal: AbortSignal): Promise<Response> {
    const token = readAdminToken(request.headers, localHTTP);
    if (token !== null) await backend.command({ kind: "session.revoke", tokenDigest: digestHex(await tokenDigest(token)) }, signal);
    return redirect(adminPath("admin-home"), [clearedAdminCookie(localHTTP)]);
  }

  function parseVariant(raw: string): bigint | null {
    if (!variantShape.test(raw)) return null;
    const id = BigInt(raw);
    return id > MaxInt64 ? null : id;
  }

  function notFound(request: Request, label: string | null): Response {
    return page(request, 404, messagePage("Not found", "That page does not exist.", label));
  }

  async function stockGet(request: Request, auth: Authenticated, rawVariant: string, signal: AbortSignal): Promise<Response> {
    const variantId = parseVariant(rawVariant);
    if (variantId === null) return notFound(request, auth.label);
    const path = adminPath("admin-stock", [variantId.toString()]);
    if (reauthRequired(auth.session.authenticatedAt, nowSeconds())) return reauthRedirect(path);
    const token = newToken();
    const result = await backend.command({
      kind: "stock.form", tokenDigest: digestHex(await tokenDigest(token)), sessionDigest: auth.digest, purpose: stockPurpose(variantId), variantId, nowSeconds: nowSeconds(),
    }, signal);
    if (result.view === null) return notFound(request, auth.label);
    const saved = new URL(request.url).searchParams.get("saved") === "1";
    return page(request, 200, stockPage({
      view: result.view, principalLabel: auth.label, formToken: token, revision: result.view.level?.revision ?? 0n,
      input: { delta: "", reason: "" }, errors: {}, conflict: null, notice: saved ? { kind: "info", message: "Stock updated." } : null,
    }));
  }

  async function stockPost(request: Request, auth: Authenticated, rawVariant: string, signal: AbortSignal): Promise<Response> {
    const variantId = parseVariant(rawVariant);
    if (variantId === null) return notFound(request, auth.label);
    const path = adminPath("admin-stock", [variantId.toString()]);
    if (reauthRequired(auth.session.authenticatedAt, nowSeconds())) return reauthRedirect(path);
    const fields = await formFields(request, ["form_token", "revision", "delta", "reason"], signal);
    const rawToken = fields.get("form_token") ?? "";
    const rawRevision = fields.get("revision") ?? "";
    const rawDelta = (fields.get("delta") ?? "").trim();
    const reason = (fields.get("reason") ?? "").trim();
    const formToken = parseToken(rawToken);
    if (!variantShape.test(rawRevision) || BigInt(rawRevision) > MaxInt64) throw new BadInput("The form is missing its revision.");
    const revision = BigInt(rawRevision);
    const input = { delta: rawDelta, reason };
    const errors: { delta?: string; reason?: string } = {};
    if (!/^-?[1-9][0-9]{0,9}$/.test(rawDelta)) errors.delta = "Enter a whole number that is not zero, for example 5 or -2.";
    if (reason === "" || reason.length > 500) errors.reason = "Enter a reason of at most 500 characters.";
    const rerender = async (status: number, notice: Notice | null, fieldErrors: FieldErrors, conflict: StockLevelView | null, token: string, shownRevision: bigint): Promise<Response> => {
      const view = (await backend.query({ kind: "stock.view", variantId }, signal)).view;
      if (view === null) return notFound(request, auth.label);
      return page(request, status, stockPage({ view, principalLabel: auth.label, formToken: token, revision: shownRevision, input, errors: fieldErrors, notice, conflict }));
    };
    if (formToken === null) {
      const fresh = newToken();
      const result = await backend.command({ kind: "stock.form", tokenDigest: digestHex(await tokenDigest(fresh)), sessionDigest: auth.digest, purpose: stockPurpose(variantId), variantId, nowSeconds: nowSeconds() }, signal);
      if (result.view === null) return notFound(request, auth.label);
      return page(request, 409, stockPage({ view: result.view, principalLabel: auth.label, formToken: fresh, revision: result.view.level?.revision ?? 0n, input, errors: {}, conflict: null, notice: { kind: "error", message: "This form could not be verified. Review the current values and submit again." } }));
    }
    if (errors.delta !== undefined || errors.reason !== undefined) {
      return await rerender(422, { kind: "error", message: "Fix the highlighted fields and submit again." }, errors, null, formToken, revision);
    }
    const outcome = await backend.command({
      kind: "stock.adjust", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: stockPurpose(variantId),
      variantId, delta: BigInt(rawDelta), reason, expectedRevision: revision, actor: principalId(auth.session), nowSeconds: nowSeconds(),
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${path}?saved=1`);
      case "session_invalid": return redirect(adminPath("admin-home"), [clearedAdminCookie(localHTTP)]);
      case "token_invalid": {
        const fresh = newToken();
        const result = await backend.command({ kind: "stock.form", tokenDigest: digestHex(await tokenDigest(fresh)), sessionDigest: auth.digest, purpose: stockPurpose(variantId), variantId, nowSeconds: nowSeconds() }, signal);
        if (result.view === null) return notFound(request, auth.label);
        return page(request, 409, stockPage({ view: result.view, principalLabel: auth.label, formToken: fresh, revision: result.view.level?.revision ?? 0n, input, errors: {}, conflict: result.view.level, notice: { kind: "error", message: "This form was already submitted or has expired, so nothing was changed. Review the current values and submit again if needed." } }));
      }
      case "stale":
        return await rerender(409, { kind: "error", message: "This stock level changed after you opened the form, so nothing was changed. Compare the values and submit again." }, {}, outcome.current, formToken, outcome.current?.revision ?? revision);
      case "rejected": {
        const detail = describeRejection(outcome.rejection);
        return await rerender(422, { kind: "error", message: detail.field === null ? detail.message : "The stock change was refused." }, detail.field === null ? {} : { [detail.field]: detail.message }, null, formToken, revision);
      }
    }
  }

  async function stockTrackPost(request: Request, auth: Authenticated, rawVariant: string, signal: AbortSignal): Promise<Response> {
    const variantId = parseVariant(rawVariant);
    if (variantId === null) return notFound(request, auth.label);
    const path = adminPath("admin-stock", [variantId.toString()]);
    if (reauthRequired(auth.session.authenticatedAt, nowSeconds())) return reauthRedirect(path);
    const fields = await formFields(request, ["form_token", "on_hand", "reason"], signal);
    const rawOnHand = (fields.get("on_hand") ?? "").trim();
    const reason = (fields.get("reason") ?? "").trim();
    const formToken = parseToken(fields.get("form_token") ?? "");
    const input = { delta: rawOnHand, reason };
    const errors: { on_hand?: string; reason?: string } = {};
    if (!/^(?:0|[1-9][0-9]{0,9})$/.test(rawOnHand)) errors.on_hand = "Enter a whole number, zero or more.";
    if (reason === "" || reason.length > 500) errors.reason = "Enter a reason of at most 500 characters.";
    const fresh = async (status: number, notice: Notice, fieldErrors: FieldErrors): Promise<Response> => {
      const token = newToken();
      const result = await backend.command({ kind: "stock.form", tokenDigest: digestHex(await tokenDigest(token)), sessionDigest: auth.digest, purpose: stockPurpose(variantId), variantId, nowSeconds: nowSeconds() }, signal);
      if (result.view === null) return notFound(request, auth.label);
      return page(request, status, stockPage({ view: result.view, principalLabel: auth.label, formToken: token, revision: result.view.level?.revision ?? 0n, input, errors: fieldErrors, conflict: null, notice }));
    };
    if (formToken === null) return await fresh(409, { kind: "error", message: "This form could not be verified. Review the current values and submit again." }, {});
    if (errors.on_hand !== undefined || errors.reason !== undefined) {
      const view = (await backend.query({ kind: "stock.view", variantId }, signal)).view;
      if (view === null) return notFound(request, auth.label);
      return page(request, 422, stockPage({ view, principalLabel: auth.label, formToken, revision: 0n, input, errors, conflict: null, notice: { kind: "error", message: "Fix the highlighted fields and submit again." } }));
    }
    const outcome = await backend.command({
      kind: "stock.track", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: stockPurpose(variantId),
      variantId, onHand: BigInt(rawOnHand), reason, actor: principalId(auth.session), nowSeconds: nowSeconds(),
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${path}?saved=1`);
      case "session_invalid": return redirect(adminPath("admin-home"), [clearedAdminCookie(localHTTP)]);
      case "token_invalid": return await fresh(409, { kind: "error", message: "This form was already submitted or has expired, so nothing was changed. Review the current values and submit again if needed." }, {});
      case "rejected": {
        const detail = describeRejection(outcome.rejection);
        const view = (await backend.query({ kind: "stock.view", variantId }, signal)).view;
        if (view === null) return notFound(request, auth.label);
        const field = detail.field === "delta" ? "on_hand" : detail.field;
        return page(request, 422, stockPage({ view, principalLabel: auth.label, formToken, revision: 0n, input, errors: field === null ? {} : { [field]: detail.message }, conflict: null, notice: { kind: "error", message: field === null ? detail.message : "Stock could not be tracked." } }));
      }
    }
  }

  async function dispatch(name: AdminRouteName, params: ReadonlyMap<string, string>, request: Request, signal: AbortSignal): Promise<Response> {
    if (name === "admin-sign-in-callback") return await callback(request, signal);
    if (name === "admin-sign-out") return await signOut(request, signal);
    if (name === "admin-asset") {
      const file = params.get("file");
      if (file === OrdersStylesheet.file) return assetResponse(request, OrdersStylesheet);
      return uploader !== null && file === uploader.file ? assetResponse(request, uploader) : notFound(request, null);
    }
    const { auth, clear } = await authenticate(request, signal);
    const finish = (response: Response): Response => {
      for (const cookie of clear) response.headers.append("Set-Cookie", cookie);
      return response;
    };
    if (name === "admin-sign-in") return finish(await startSignIn("sign-in", "/admin"));
    if (auth === null) {
      return finish(name === "admin-home" ? page(request, 200, signInPage(null)) : redirect(adminPath("admin-home")));
    }
    if (!isOwner(auth)) return finish(page(request, 403, unauthorizedPage(auth.session)));
    if (name === "admin-media") return finish(await media.serveMedia(params, request, auth.label, signal));
    const catalogResponse = await catalog.handle(name, params, request, auth, signal);
    if (catalogResponse !== null) return finish(catalogResponse);
    const settingsResponse = await settings.handle(name, request, auth, signal);
    if (settingsResponse !== null) return finish(settingsResponse);
    const shopResponse = await shop.handle(name, params, request, auth, signal);
    if (shopResponse !== null) return finish(shopResponse);
    const ordersResponse = await orders.handle(name, params, request, auth, signal);
    if (ordersResponse !== null) return finish(ordersResponse);
    switch (name) {
      case "admin-home": return finish(page(request, 200, homePage(options.tenantId, auth.label)));
      case "admin-operations": {
        const { status } = await options.backend.query({ kind: "operations.status", nowSeconds: nowSeconds() }, signal);
        return finish(page(request, 200, operationsPage(status, auth.label)));
      }
      case "admin-reauth": return finish(await startSignIn("reauth", safeAdminReturn(new URL(request.url).searchParams.get("return")), auth.digest));
      case "admin-stock": return finish(await stockGet(request, auth, params.get("variant_id")!, signal));
      case "admin-stock-adjust": return finish(await stockPost(request, auth, params.get("variant_id")!, signal));
      case "admin-stock-track": return finish(await stockTrackPost(request, auth, params.get("variant_id")!, signal));
      default: return notFound(request, auth.label);
    }
  }

  return {
    async handle({ request, segments, signal }) {
      const match = matchAdminRoute(segments, request.method);
      if (match.kind === "none") return notFound(request, null);
      if (match.kind === "method") {
        const headers = new Headers({ Allow: match.allow });
        return page(request, 405, messagePage("Not allowed", "That action is not available here.", null), headers);
      }
      try {
        if (request.method === "POST") checkOrigin(request.headers, options.origin);
        return await dispatch(match.name, match.params, request, signal);
      } catch (error) {
        if (error instanceof SecurityError) return page(request, error.status === 403 ? 403 : 400, messagePage("Request refused", "This form must be submitted from this store's own admin pages.", null));
        if (error instanceof BadInput) return page(request, 400, messagePage("Bad request", error.message, null));
        throw error;
      }
    },
  };
}
