const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Issuer = Schema.String.check(filter<string>(validIssuer, "must be a valid issuer"));
const Subject = Schema.String.check(filter<string>(validSubject, "must be a valid subject"));
const Email = Schema.String.check(filter<string>(validEmail, "must be a valid email"));
export const MaxPurposeLength = 128;
const Purpose = Schema.String.check(filter<string>((value) => /^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= MaxPurposeLength, "must be a purpose label"));
const Level = Schema.Struct({ onHand: Integer, held: Integer, allocated: Integer, revision: Integer });
export type StockLevelView = typeof Level.Type;

