function* resolveSession(command: Extract<AdminCommand, { kind: "session.resolve" }>): Program<AdminCommandResult> {
  const digest = digestBytes(command.tokenDigest);
  const row = yield* get("GetAdminSession", [digest]);
  if (row === null) return { kind: "session.resolve", status: "missing" };
  const expiresAt = Number(row.expires_at);
  const lastSeenAt = Number(row.last_seen_at);
  const status = sessionStatus({ expiresAt, lastSeenAt }, command.nowSeconds);
  if (status !== "valid") {
    yield* run("DeleteAdminSession", [digest]);
    return { kind: "session.resolve", status };
  }
  if (command.nowSeconds - lastSeenAt >= TouchIntervalSeconds) yield* run("TouchAdminSession", [BigInt(command.nowSeconds), digest]);
  return {
    kind: "session.resolve",
    status: "valid",
    session: { issuer: row.issuer, subject: row.subject, email: row.email, authenticatedAt: Number(row.authenticated_at), expiresAt },
  };
}

function* adjustStock(command: Extract<AdminCommand, { kind: "stock.adjust" }>): Program<AdminCommandResult> {
  const guarded = yield* guardedMutation<StockLevelView, { readonly rejection: (typeof StockCommandRejections)[number]; readonly current: StockLevelView | null }>(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    function* () {
      const result = yield* stock(
        [{ kind: "adjust", variantId: command.variantId, delta: command.delta, reason: command.reason, expectedRevision: command.expectedRevision }],
        { nowSeconds: BigInt(command.nowSeconds), actor: command.actor },
      );
      if (result.outcome === "applied") {
        const level = result.levels.find((candidate) => candidate.variantId === command.variantId);
        if (level === undefined) throw new Error("admin: stock adjustment returned no level");
        return { applied: true, result: { onHand: level.onHand, held: level.held, allocated: level.allocated, revision: level.revision } };
      }
      const row = result.rejection === "stale_revision" ? yield* stockRead(command.variantId) : null;
      const current = row === null || row.on_hand === null || row.held === null || row.allocated === null || row.revision === null
        ? null
        : { onHand: row.on_hand, held: row.held, allocated: row.allocated, revision: row.revision };
      return { applied: false, result: { rejection: result.rejection, current } };
    },
  );
  if (guarded.outcome !== "done") return { kind: "stock.adjust", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "stock.adjust", outcome: "applied", level: guarded.mutation.result };
  const { rejection, current } = guarded.mutation.result;
  return rejection === "stale_revision"
    ? { kind: "stock.adjust", outcome: "stale", current }
    : { kind: "stock.adjust", outcome: "rejected", rejection };
}

function* trackStock(command: Extract<AdminCommand, { kind: "stock.track" }>): Program<AdminCommandResult> {
  const guarded = yield* guardedMutation<StockLevelView, (typeof StockCommandRejections)[number]>(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    function* () {
      const result = yield* stock([{ kind: "track", variantId: command.variantId, onHand: command.onHand, reason: command.reason }], { nowSeconds: BigInt(command.nowSeconds), actor: command.actor });
      if (result.outcome !== "applied") return { applied: false, result: result.rejection };
      const level = result.levels.find((candidate) => candidate.variantId === command.variantId);
      if (level === undefined) throw new Error("admin: stock tracking returned no level");
      return { applied: true, result: { onHand: level.onHand, held: level.held, allocated: level.allocated, revision: level.revision } };
    },
  );
  if (guarded.outcome !== "done") return { kind: "stock.track", outcome: guarded.outcome };
  return guarded.mutation.applied
    ? { kind: "stock.track", outcome: "applied", level: guarded.mutation.result }
    : { kind: "stock.track", outcome: "rejected", rejection: guarded.mutation.result };
}

function* catalogMutate(command: Extract<AdminCommand, { kind: "catalog.mutate" }>): Program<AdminCommandResult> {
  const guarded = yield* guardedMutation(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    () => catalogEffect(command.change, { actor: command.actor, nowSeconds: BigInt(command.nowSeconds) }),
  );
  if (guarded.outcome !== "done") return { kind: "catalog.mutate", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "catalog.mutate", outcome: "applied", entityId: guarded.mutation.result.entityId };
  const refusal = guarded.mutation.result;
  return refusal.kind === "stale" ? { kind: "catalog.mutate", outcome: "stale" } : { kind: "catalog.mutate", outcome: "rejected", rejection: refusal.rejection };
}

function* settingsMutate(command: Extract<AdminCommand, { kind: "settings.mutate" }>): Program<AdminCommandResult> {
  const guarded = yield* guardedMutation(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    () => settingsEffect(command.change, { actor: command.actor, nowSeconds: BigInt(command.nowSeconds) }),
  );
  if (guarded.outcome !== "done") return { kind: "settings.mutate", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "settings.mutate", outcome: "applied", version: guarded.mutation.result.version };
  const refusal = guarded.mutation.result;
  return refusal.kind === "stale" ? { kind: "settings.mutate", outcome: "stale" } : { kind: "settings.mutate", outcome: "rejected", problems: refusal.problems };
}

function* settingsForm(command: Extract<AdminCommand, { kind: "settings.form" }>): Program<AdminCommandResult> {
  const issued = yield* issueFormToken({ tokenDigest: command.tokenDigest, sessionDigest: command.sessionDigest, purpose: command.purpose, nowSeconds: command.nowSeconds });
  return { kind: "settings.form", issued, view: yield* settingsViewProgram() };
}

function* shopMutate(command: Extract<AdminCommand, { kind: "shop.mutate" }>): Program<AdminCommandResult> {
  const guarded = yield* guardedMutation(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    () => shopEffect(command.change, { actor: command.actor, nowSeconds: BigInt(command.nowSeconds) }),
  );
  if (guarded.outcome !== "done") return { kind: "shop.mutate", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "shop.mutate", outcome: "applied", revision: guarded.mutation.result.revision };
  const refusal = guarded.mutation.result;
  return refusal.kind === "rejected" ? { kind: "shop.mutate", outcome: "rejected", rejections: refusal.rejections } : { kind: "shop.mutate", outcome: refusal.kind };
}

function* shopForm(command: Extract<AdminCommand, { kind: "shop.form" }>): Program<AdminCommandResult> {
  const issued = yield* issueFormToken({ tokenDigest: command.tokenDigest, sessionDigest: command.sessionDigest, purpose: command.purpose, nowSeconds: command.nowSeconds });
  return { kind: "shop.form", issued, view: yield* shopViewProgram() };
}

function* pageForm(command: Extract<AdminCommand, { kind: "page.form" }>): Program<AdminCommandResult> {
  const issued = yield* issueFormToken({ tokenDigest: command.tokenDigest, sessionDigest: command.sessionDigest, purpose: command.purpose, nowSeconds: command.nowSeconds });
  return { kind: "page.form", issued, result: yield* catalogQueryProgram(command.query) };
}

function* stockForm(command: Extract<AdminCommand, { kind: "stock.form" }>): Program<AdminCommandResult> {
  const issued = yield* issueFormToken({ tokenDigest: command.tokenDigest, sessionDigest: command.sessionDigest, purpose: command.purpose, nowSeconds: command.nowSeconds });
  const result = yield* stockViewProgram(command.variantId);
  return { kind: "stock.form", view: result.view, issued };
}

export function* adminCommandProgram(command: AdminCommand): Program<AdminCommandResult> {
  switch (command.kind) {
    case "session.create": {
      const now = BigInt(command.nowSeconds);
      yield* run("DeleteExpiredAdminSessions", [now, BigInt(command.nowSeconds - AdminSessionIdleSeconds)]);
      const expiresAt = command.nowSeconds + AdminSessionAbsoluteSeconds;
      yield* run("InsertAdminSession", [digestBytes(command.tokenDigest), command.issuer, command.subject, command.email, now, BigInt(command.authenticatedAt), now, BigInt(expiresAt)]);
      return { kind: "session.create", expiresAt };
    }
    case "session.resolve": return yield* resolveSession(command);
    case "session.reauthenticate": {
      const changes = yield* run("SetAdminSessionAuthentication", [BigInt(command.authenticatedAt), BigInt(command.nowSeconds), digestBytes(command.tokenDigest), command.issuer, command.subject]);
      return { kind: "session.reauthenticate", updated: changes > 0n };
    }
    case "session.revoke": return { kind: "session.revoke", revoked: yield* run("DeleteAdminSession", [digestBytes(command.tokenDigest)]) };
    case "session.revoke_principal": return { kind: "session.revoke_principal", revoked: yield* run("DeleteAdminSessionsByPrincipal", [command.issuer, command.subject]) };
    case "session.revoke_all": return { kind: "session.revoke_all", revoked: yield* run("DeleteAllAdminSessions", []) };
    case "form_token.issue": return { kind: "form_token.issue", issued: yield* issueFormToken(command) };
    case "stock.form": return yield* stockForm(command);
    case "stock.adjust": return yield* adjustStock(command);
    case "stock.track": return yield* trackStock(command);
    case "page.form": return yield* pageForm(command);
    case "catalog.mutate": return yield* catalogMutate(command);
    case "checkout.quote":
    case "checkout.requote":
    case "checkout.accept":
    case "checkout.session.record": return yield* checkoutCommandProgram(command);
    case "settings.form": return yield* settingsForm(command);
    case "settings.mutate": return yield* settingsMutate(command);
    case "shop.form": return yield* shopForm(command);
    case "shop.mutate": return yield* shopMutate(command);
    case "media.reserve": return yield* reserveMedia(command);
    case "media.expire": return yield* expirePendingMedia(command.nowSeconds);
    case "media.collect": return yield* collectUnreferencedMedia(command.nowSeconds);
    case "media.orphans": return yield* findOrphans(command.ids);
    case "work.claim":
    case "work.complete":
    case "work.fail":
    case "work.requeue":
    case "work.ensure_periodic":
    case "work.purge":
    case "work.event_processed":
    case "restore.reconciled":
    case "restore.resume":
    case "webhook.ingest": return yield* workCommandProgram(command);
    case "payment.authorize":
    case "payment.op.begin":
    case "payment.op.settle":
    case "payment.capture.begin":
    case "payment.observe":
    case "payment.review":
    case "payment.flag":
    case "payment.release":
    case "payment.block":
    case "payment.sweep": return yield* paymentCommandProgram(command);
    case "order.form":
    case "order.ship":
    case "order.note": return yield* orderCommandProgram(command);
    case "order.refund":
    case "order.cancel":
    case "order.return":
    case "order.restock":
    case "refund.observe":
    case "refund.fail": return yield* refundCommandProgram(command);
    case "email.begin":
    case "email.settle":
    case "email.resend":
    case "order.access_revoke":
    case "order.lookup": return yield* emailCommandProgram(command);
  }
}

export function* adminQueryProgram(query: AdminQuery): Program<AdminQueryResult> {
  if (query.kind === "checkout.form" || query.kind === "checkout.quote_view" || query.kind === "checkout.attempt_view") return yield* checkoutQueryProgram(query);
  if (query.kind === "stock.view") return yield* stockViewProgram(query.variantId);
  if (query.kind === "settings.view") return { kind: "settings.view", view: yield* settingsViewProgram() };
  if (query.kind === "shop.view") return { kind: "shop.view", view: yield* shopViewProgram() };
  if (query.kind === "media.asset") return yield* mediaAssetView(query);
  if (query.kind === "payment.attempt" || query.kind === "payment.intent" || query.kind === "order.status") return yield* paymentQueryProgram(query);
  if (query.kind === "order.list") {
    const listed = yield* orderListProgram(query.filter);
    return { kind: "order.list", rows: listed.rows, next: listed.next };
  }
  if (query.kind === "order.detail") return { kind: "order.detail", view: yield* orderDetailProgram(query.number) };
  if (query.kind === "refund.view") return yield* refundQueryProgram(query);
  if (query.kind === "order.access") return yield* emailQueryProgram(query);
  if (query.kind === "work.next" || query.kind === "work.dead" || query.kind === "work.provider_event" || query.kind === "restore.targets" || query.kind === "operations.status") return yield* workQueryProgram(query);
  return yield* catalogQueryProgram(query);
}

function* stockViewProgram(variantId: bigint): Program<Extract<AdminQueryResult, { readonly kind: "stock.view" }>> {
  const variant = yield* get("GetStockVariant", [variantId]);
  if (variant === null) return { kind: "stock.view", view: null };
  const row = yield* stockRead(variantId);
  const adjustments = yield* all("ListRecentStockAdjustments", [variantId]);
  const audit = yield* all("ListRecentAuditEvents", ["variant", variantId.toString()]);
  const tracked = row !== null && row.on_hand !== null && row.held !== null && row.allocated !== null && row.revision !== null;
  return {
    kind: "stock.view",
    view: {
      variantId: variant.variant_id,
      productTitle: variant.product_title,
      variantTitle: variant.variant_title,
      level: tracked ? { onHand: row.on_hand!, held: row.held!, allocated: row.allocated!, revision: row.revision! } : null,
      adjustments: adjustments.map((entry) => ({ id: entry.id, kind: entry.kind, delta: entry.delta, onHandAfter: entry.on_hand_after, reason: entry.reason, actor: entry.actor, createdAt: entry.created_at })),
      audit: audit.map((entry) => ({ id: entry.id, actor: entry.actor, action: entry.action, entityRevision: entry.entity_revision, summary: entry.summary, createdAt: entry.created_at })),
    },
  };
}
