export const AdminSessionAbsoluteSeconds = 12 * 60 * 60;
export const AdminSessionIdleSeconds = 2 * 60 * 60;
export const ReauthMaxAgeSeconds = 10 * 60;
export const FormTokenLifetimeSeconds = 60 * 60;
export const SignInStateSeconds = 10 * 60;
export const TouchIntervalSeconds = 60;
export const AssertionLeewaySeconds = 60;
export const AssertionMaxLifetimeSeconds = 300;

export interface SessionTimes {
  readonly expiresAt: number;
  readonly lastSeenAt: number;
}

export type SessionStatus = "valid" | "expired" | "idle";

export function sessionStatus(times: SessionTimes, nowSeconds: number): SessionStatus {
  if (nowSeconds >= times.expiresAt) return "expired";
  if (nowSeconds - times.lastSeenAt >= AdminSessionIdleSeconds) return "idle";
  return "valid";
}

export function reauthRequired(authenticatedAt: number, nowSeconds: number): boolean {
  return nowSeconds - authenticatedAt > ReauthMaxAgeSeconds || authenticatedAt > nowSeconds + AssertionLeewaySeconds;
}
