import { cancelPaymentAction } from "../commerce/cancel.ts";
import { refundableMinor } from "../commerce/refund.ts";
import { readRefundFacts } from "../commerce/refund_program.ts";
import { orderEmailViews } from "../commerce/email_program.ts";
import { shipEffect, type ShipRefusal } from "../commerce/fulfillment_program.ts";
import { lineFulfillmentOf } from "../commerce/fulfillment_program.ts";
import { shipmentBlock } from "../commerce/fulfillment_ship.ts";
import type { PaymentState } from "../commerce/payment.ts";
import type { FulfillmentStatus } from "../commerce/fulfillment.ts";
import { guardedMutation, issueFormToken, type Mutation } from "./guard.ts";
import { MaxOrderNoteLength, MaxOrderPage, type OrderCommandResult, type OrderDetailView, type OrderListFilter, type OrderListRow } from "./orders_operations.ts";
import { searchDigestOf } from "./orders_search.ts";
import { all, audit, get, run, type Program } from "./program.ts";
import type { OrderCommand } from "./orders_operations.ts";

export function* orderDetailProgram(number: bigint): Program<OrderDetailView | null> {
  const order = yield* get("GetOrderDetail", [number]);
  if (order === null) return null;
  const exceptions = yield* all("ListOrderExceptions", [order.id]);
  const lines = yield* all("ListOrderLineStates", [order.id]);
  const shipments = yield* all("ListOrderShipments", [order.id]);
  const shipmentLines = yield* all("ListOrderShipmentLines", [order.id]);
  const notes = yield* all("ListOrderNotes", [order.id]);
  const timeline = yield* all("ListOrderTimeline", [order.id.toString()]);
  const refunds = yield* all("ListOrderRefunds", [order.id]);
  const refundFacts = yield* readRefundFacts(order);
  const reservations = yield* all("ListAttemptReservations", [order.attempt_id]);
  const trackedVariants = new Set(reservations.filter((reservation) => reservation.tracked === 1n).map((reservation) => reservation.variant_id));
  const refundedByPosition = new Map(refundFacts.lines.map((line) => [line.position, line.refundedQuantity]));
  const reviewOpen = exceptions.some((entry) => entry.kind === "review" && entry.state === "open");
  const ships = order.fulfillment === "ship";
  return {
    number: order.number,
    revision: order.revision,
    contactEmail: order.contact_email,
    currency: order.currency_code,
    exponent: Number(order.currency_exponent),
    fulfillment: ships ? "ship" : "pickup",
    fulfillmentStatus: order.fulfillment_status as FulfillmentStatus,
    address: ships && order.recipient !== null && order.line1 !== null && order.city !== null && order.region !== null && order.postal_code !== null && order.country !== null
      ? { recipient: order.recipient, line1: order.line1, line2: order.line2, city: order.city, region: order.region, postalCode: order.postal_code, country: order.country }
      : null,
    shippingZone: order.shipping_zone,
    merchandiseMinor: order.merchandise_minor,
    shippingMinor: order.shipping_minor,
    shippingTaxMinor: order.shipping_tax_minor,
    taxMinor: order.tax_minor,
    totalMinor: order.total_minor,
    allocation: order.allocation === "late" ? "late" : "hold",
    placedAt: order.placed_at,
    payment: { intentId: order.payment_intent_id, state: order.payment_state as PaymentState, authorizedMinor: order.amount_authorized_minor, capturedMinor: order.amount_captured_minor },
    shipBlock: shipmentBlock(order.payment_state as PaymentState, reviewOpen),
    cancelBlock: cancelPaymentAction(order.payment_state as PaymentState) === "settling" ? "payment_settling" : null,
    refundableMinor: refundableMinor(refundFacts),
    shippingRefundableMinor: order.shipping_minor - refundFacts.activeShippingRefundedMinor,
    shippingTaxRefundableMinor: order.shipping_tax_minor - refundFacts.activeShippingTaxRefundedMinor,
    lines: lines.map((row) => ({
      position: row.position, title: row.title, variantLabel: row.variant_label, unitPriceMinor: row.unit_price_minor, quantity: row.quantity,
      lineTotalMinor: row.line_total_minor, taxMinor: row.tax_minor, ...lineCounts(row),
      refunded: refundedByPosition.get(row.position) ?? 0n, tracked: trackedVariants.has(row.variant_id),
    })),
    shipments: shipments.map((row) => ({
      sequence: row.sequence, carrier: row.carrier, trackingNumber: row.tracking_number, trackingUrl: row.tracking_url, actor: row.actor, shippedAt: row.shipped_at,
      lines: shipmentLines.filter((line) => line.fulfillment_id === row.id).map((line) => ({ position: line.position, quantity: line.quantity })),
    })),
    exceptions: exceptions.map((row) => ({ kind: row.kind, state: row.state === "open" ? "open" : "closed", detail: row.detail, openedAt: row.opened_at, closedAt: row.closed_at })),
    notes: notes.map((row) => ({ id: row.id, body: row.body, actor: row.actor, createdAt: row.created_at })),
    timeline: timeline.map((row) => ({ actor: row.actor, action: row.action, summary: row.summary, createdAt: row.created_at })),
    refunds: refunds.map((row) => ({ id: row.id, state: row.state, amountMinor: row.amount_minor, reason: row.reason, failureReason: row.failure_reason, createdAt: row.created_at })),
    emails: yield* orderEmailViews(order.id),
  };
}

function lineCounts(row: { readonly quantity: bigint; readonly shipped: bigint; readonly canceled: bigint; readonly returned: bigint; readonly restocked: bigint }) {
  const line = lineFulfillmentOf(row);
  return { shipped: line.shipped, canceled: line.canceled, returned: line.returned, restocked: line.restocked };
}

export function* orderListProgram(filter: OrderListFilter): Program<{ readonly rows: readonly OrderListRow[]; readonly next: bigint | null }> {
  const digest = filter.email === null ? null : yield* searchDigestOf(filter.email);
  const rows = yield* all("ListOrders", [
    filter.before, filter.before, filter.number, filter.number, filter.placedFrom === null ? null : BigInt(filter.placedFrom), filter.placedFrom === null ? null : BigInt(filter.placedFrom),
    filter.placedBefore === null ? null : BigInt(filter.placedBefore), filter.placedBefore === null ? null : BigInt(filter.placedBefore),
    filter.paymentState, filter.paymentState, filter.fulfillmentStatus, filter.fulfillmentStatus, digest, digest, BigInt(MaxOrderPage + 1),
  ]);
  const page = rows.slice(0, MaxOrderPage);
  return {
    rows: page.map((row) => ({
      number: row.number, placedAt: row.placed_at, contactEmail: row.contact_email, currency: row.currency_code, exponent: Number(row.currency_exponent), totalMinor: row.total_minor,
      fulfillment: row.fulfillment === "pickup" ? "pickup" : "ship", fulfillmentStatus: row.fulfillment_status as FulfillmentStatus, paymentState: row.payment_state as PaymentState,
      openExceptions: row.open_exceptions, itemCount: row.item_count,
    })),
    next: rows.length > MaxOrderPage ? page[page.length - 1]?.number ?? null : null,
  };
}

type Of<K extends OrderCommand["kind"]> = Extract<OrderCommand, { readonly kind: K }>;
type ResultOf<K extends OrderCommand["kind"]> = Extract<OrderCommandResult, { readonly kind: K }>;

function* orderForm(command: Of<"order.form">): Program<ResultOf<"order.form">> {
  let issued = true;
  for (const token of command.tokens) {
    issued = (yield* issueFormToken({ tokenDigest: token.tokenDigest, sessionDigest: command.sessionDigest, purpose: token.purpose, nowSeconds: command.nowSeconds })) && issued;
  }
  return { kind: "order.form", issued, view: yield* orderDetailProgram(command.number) };
}

function* shipOrder(command: Of<"order.ship">): Program<ResultOf<"order.ship">> {
  const guarded = yield* guardedMutation<{ readonly sequence: bigint }, ShipRefusal>(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    () => shipEffect(command, { actor: command.actor, nowSeconds: BigInt(command.nowSeconds) }),
  );
  if (guarded.outcome !== "done") return { kind: "order.ship", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "order.ship", outcome: "applied", sequence: guarded.mutation.result.sequence };
  const refusal = guarded.mutation.result;
  if (refusal.kind === "rejected") return { kind: "order.ship", outcome: "rejected", rejection: refusal.rejection };
  return { kind: "order.ship", outcome: refusal.kind };
}

function validNote(body: string): boolean {
  return body.length >= 1 && body.length <= MaxOrderNoteLength && body.trim() === body;
}

function* addNote(command: Of<"order.note">): Program<ResultOf<"order.note">> {
  const guarded = yield* guardedMutation<null, "not_found" | "invalid_note">(
    { sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds },
    function* (): Program<Mutation<null, "not_found" | "invalid_note">> {
      if (!validNote(command.body)) return { applied: false, result: "invalid_note" };
      const order = yield* get("GetOrderDetail", [command.number]);
      if (order === null) return { applied: false, result: "not_found" };
      const now = BigInt(command.nowSeconds);
      yield* run("InsertOrderNote", [order.id, command.body, command.actor, now]);
      yield* audit({ actor: command.actor, action: "order.note", entityKind: "order", entityId: order.id.toString(), entityRevision: null, summary: `note added (${command.body.length} characters)` }, now);
      return { applied: true, result: null };
    },
  );
  if (guarded.outcome !== "done") return { kind: "order.note", outcome: guarded.outcome };
  return { kind: "order.note", outcome: guarded.mutation.applied ? "applied" : guarded.mutation.result };
}

export function* orderCommandProgram(command: OrderCommand): Program<OrderCommandResult> {
  switch (command.kind) {
    case "order.form": return yield* orderForm(command);
    case "order.ship": return yield* shipOrder(command);
    case "order.note": return yield* addNote(command);
  }
}
