import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const NullableText = Schema.NullOr(Text);
const NullableInteger = Schema.NullOr(Integer);
const Digest = Schema.instanceOf(Uint8Array);

export const paymentRowSchemas = {
  GetPaymentAttempt: Schema.Struct({
    id: Integer, ref: Text, state: Text, session_hash: Digest, provider_session_id: NullableText, provider_session_url: NullableText,
    provider_session_expires_at: NullableInteger, hold_release_after: Integer, accepted_at: Integer, quote_id: Integer, quote_ref: Text,
    total_minor: Integer, currency_code: Text,
  }),
  ListAttemptReservations: Schema.Struct({ variant_id: Integer, quantity: Integer, tracked: Integer, state: Text }),
  GetOperation: Schema.Struct({ id: Integer, state: Text, idempotency_key: Text, attempts: Integer, provider_object_id: NullableText, created_at: Integer, updated_at: Integer }),
  GetOrderForAttempt: Schema.Struct({ id: Integer, number: Integer, payment_intent_id: Text }),
  GetPaymentByIntent: Schema.Struct({
    id: Integer, order_id: Integer, number: Integer, attempt_id: Integer, attempt_ref: Text, state: Text,
    amount_authorized_minor: Integer, amount_captured_minor: Integer, currency_code: Text, review_id: NullableText,
  }),
  GetOrderStatus: Schema.Struct({
    id: Integer, number: Integer, attempt_ref: Text, payment_state: Text, currency_code: Text, total_minor: Integer,
    placed_at: Integer, open_exceptions: Integer, fulfillment: Text, city: NullableText, region: NullableText,
  }),
  ListOrderLines: Schema.Struct({
    product_id: Integer, variant_id: Integer, title: Text, variant_label: Text, unit_price_minor: Integer, quantity: Integer, line_total_minor: Integer,
    taxable_minor: Integer, tax_rate_ppm: Integer, tax_minor: Integer, image_media_id: NullableInteger,
  }),
  ListOrderExceptions: Schema.Struct({ id: Integer, kind: Text, provider_object_id: Text, state: Text, detail: Text, opened_at: Integer, closed_at: NullableInteger }),
  ListAttemptExceptions: Schema.Struct({ id: Integer, kind: Text, provider_object_id: Text, state: Text, detail: Text, opened_at: Integer, closed_at: NullableInteger }),
  ListStalledAttempts: Schema.Struct({ ref: Text }),
  ListStalledPayments: Schema.Struct({ payment_intent_id: Text, state: Text }),
} as const;

export const paymentWriteQueries = [
  "SetAttemptState", "SetReservationsState", "InsertOperation", "SetOperationState", "InsertOrder", "InsertOrderLines", "InsertPayment",
  "SetPaymentState", "UpsertOrderException", "ScheduleWork", "SetPendingWorkDue",
] as const;
