import { Schema } from "effect";
import { AttemptStates, QuoteViewSchema } from "../checkout/operations.ts";
import { Integer } from "../storefront/queries.ts";
import { ProviderOperationKinds, ProviderOperationStates } from "./operation.ts";
import { IntentStatuses, PaymentStates } from "./payment.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Ref = Schema.String.check(filter<string>((value) => /^[0-9a-f]{32}$/.test(value), "must be a 32-character lowercase hex reference"));
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
export const TenantId = Schema.String.check(filter<string>((value) => /^[a-z0-9][a-z0-9-]{0,62}$/.test(value), "must be a tenant id"));
const ProviderId = Schema.String.check(filter<string>((value) => /^[A-Za-z0-9_]{1,255}$/.test(value), "must be a Stripe object id"));
const ExceptionObject = Schema.String.check(filter<string>((value) => /^[A-Za-z0-9_:-]{1,255}$/.test(value), "must name the object an exception is about"));
const Detail = Schema.String.check(filter<string>((value) => value.length <= 500, "must be at most 500 characters"));
const Short = Schema.NullOr(Schema.String.check(filter<string>((value) => value.length <= 255, "must be at most 255 characters")));

export const OrderExceptionKinds = ["review", "dispute", "early_fraud_warning", "payment_mismatch", "payment_canceled", "unmapped_state", "operation_blocked"] as const;
export type OrderExceptionKind = (typeof OrderExceptionKinds)[number];

export const IntentFactsSchema = Schema.Struct({
  id: ProviderId,
  status: Schema.Literals(IntentStatuses),
  amountCapturable: Integer,
  amountReceived: Integer,
  currency: Schema.String,
  livemode: Schema.Boolean,
  captureMethod: Schema.String,
  paymentMethodTypes: Schema.Array(Schema.String),
  usedPaymentMethodType: Short,
  metadataTenant: Short,
  metadataAttempt: Short,
  reviewId: Short,
  reviewOpen: Schema.Boolean,
});

export const AuthorizeOutcomes = ["placed", "placed_late", "already", "voided_late", "mismatch", "not_yet", "canceled", "foreign", "not_found"] as const;
export type AuthorizeOutcome = (typeof AuthorizeOutcomes)[number];

export const PaymentCommandSchemas = [
  Schema.Struct({ kind: Schema.Literal("payment.authorize"), tenantId: TenantId, livemode: Schema.Boolean, attemptRef: Ref, intent: IntentFactsSchema, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("payment.op.begin"), tenantId: TenantId, opKind: Schema.Literals(ProviderOperationKinds), subject: Schema.String, nowSeconds: Seconds }),
  Schema.Struct({
    kind: Schema.Literal("payment.op.settle"), opKind: Schema.Literals(ProviderOperationKinds), subject: Schema.String,
    to: Schema.Literals(["succeeded", "failed", "unknown", "blocked"]), providerObjectId: Short, error: Schema.NullOr(Detail), attemptRef: Schema.NullOr(Ref), nowSeconds: Seconds,
  }),
  Schema.Struct({ kind: Schema.Literal("payment.capture.begin"), tenantId: TenantId, paymentIntentId: ProviderId, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("payment.observe"), intent: IntentFactsSchema, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("payment.review"), paymentIntentId: ProviderId, reviewId: ProviderId, open: Schema.Boolean, closedReason: Short, nowSeconds: Seconds }),
  Schema.Struct({
    kind: Schema.Literal("payment.flag"), paymentIntentId: ProviderId, exception: Schema.Literals(["dispute", "early_fraud_warning", "unmapped_state"]), objectId: ProviderId,
    open: Schema.Boolean, detail: Detail, nowSeconds: Seconds,
  }),
  Schema.Struct({ kind: Schema.Literal("payment.release"), attemptRef: Ref, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("payment.block"), attemptRef: Ref, exception: Schema.Literals(["operation_blocked", "unmapped_state"]), objectId: ExceptionObject, detail: Detail, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("payment.sweep"), nowSeconds: Seconds }),
] as const;

export const OperationView = Schema.Struct({ state: Schema.Literals(ProviderOperationStates), key: Schema.String, attempts: Integer, providerObjectId: Schema.NullOr(Schema.String), createdAt: Seconds });
export type OperationView = typeof OperationView.Type;

export const PaymentResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("payment.authorize"), outcome: Schema.Literals(AuthorizeOutcomes), orderNumber: Schema.NullOr(Integer) }),
  Schema.Struct({ kind: Schema.Literal("payment.op.begin"), outcome: Schema.Literal("started"), previous: Schema.NullOr(Schema.Literals(ProviderOperationStates)), operation: OperationView }),
  Schema.Struct({ kind: Schema.Literal("payment.op.begin"), outcome: Schema.Literals(["succeeded", "blocked"]), operation: OperationView }),
  Schema.Struct({ kind: Schema.Literal("payment.op.settle"), changed: Schema.Boolean }),
  Schema.Struct({ kind: Schema.Literal("payment.capture.begin"), outcome: Schema.Literal("capture"), previous: Schema.NullOr(Schema.Literals(ProviderOperationStates)), key: Schema.String, amountMinor: Integer }),
  Schema.Struct({ kind: Schema.Literal("payment.capture.begin"), outcome: Schema.Literals(["reconcile", "review", "done", "not_found", "blocked"]) }),
  Schema.Struct({ kind: Schema.Literal("payment.observe"), outcome: Schema.Literals(["captured", "voided", "capturable", "unmapped", "not_found"]), state: Schema.NullOr(Schema.Literals(PaymentStates)) }),
  Schema.Struct({ kind: Schema.Literal("payment.review"), outcome: Schema.Literals(["in_review", "approved", "held", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("payment.flag"), outcome: Schema.Literals(["recorded", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("payment.release"), outcome: Schema.Literals(["released", "not_pinned", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("payment.block"), outcome: Schema.Literals(["blocked", "not_found"]) }),
  Schema.Struct({ kind: Schema.Literal("payment.sweep"), holds: Integer, captures: Integer }),
] as const;

export const PaymentQuerySchemas = [
  Schema.Struct({ kind: Schema.Literal("payment.attempt"), attemptRef: Ref }),
  Schema.Struct({ kind: Schema.Literal("payment.intent"), paymentIntentId: ProviderId }),
  Schema.Struct({ kind: Schema.Literal("order.status"), accessDigest: Digest, number: Integer, nowSeconds: Seconds }),
] as const;

const AttemptPaymentView = Schema.Struct({
  ref: Ref,
  state: Schema.Literals(AttemptStates),
  sessionId: Schema.NullOr(Schema.String),
  sessionExpiresAt: Schema.NullOr(Integer),
  holdReleaseAfter: Integer,
  acceptedAt: Integer,
  totalMinor: Integer,
  currency: Schema.String,
  orderNumber: Schema.NullOr(Integer),
  quote: QuoteViewSchema,
  createSession: Schema.NullOr(OperationView),
  expireSession: Schema.NullOr(OperationView),
});
export type AttemptPaymentView = typeof AttemptPaymentView.Type;

const IntentPaymentView = Schema.Struct({
  attemptRef: Ref,
  orderNumber: Integer,
  state: Schema.Literals(PaymentStates),
  amountAuthorizedMinor: Integer,
  amountCapturedMinor: Integer,
  currency: Schema.String,
  reviewId: Schema.NullOr(Schema.String),
  capture: Schema.NullOr(OperationView),
});
export type IntentPaymentView = typeof IntentPaymentView.Type;

const OrderLineView = Schema.Struct({ title: Schema.String, variantLabel: Schema.String, unitPriceMinor: Integer, quantity: Integer, lineTotalMinor: Integer });

export const OrderStatusSchema = Schema.Struct({
  number: Integer,
  attemptRef: Ref,
  paymentState: Schema.Literals(PaymentStates),
  currency: Schema.String,
  totalMinor: Integer,
  placedAt: Integer,
  openExceptions: Integer,
  destination: Schema.NullOr(Schema.String),
  lines: Schema.Array(OrderLineView),
});
export type OrderStatusView = typeof OrderStatusSchema.Type;

export const PaymentQueryResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("payment.attempt"), attempt: Schema.NullOr(AttemptPaymentView) }),
  Schema.Struct({ kind: Schema.Literal("payment.intent"), payment: Schema.NullOr(IntentPaymentView) }),
  Schema.Struct({ kind: Schema.Literal("order.status"), order: Schema.NullOr(OrderStatusSchema) }),
] as const;

export type PaymentCommand = (typeof PaymentCommandSchemas)[number]["Type"];
export type PaymentCommandResult = (typeof PaymentResultSchemas)[number]["Type"];
export type PaymentQuery = (typeof PaymentQuerySchemas)[number]["Type"];
export type PaymentQueryResult = (typeof PaymentQueryResultSchemas)[number]["Type"];
export type IntentFactsInput = typeof IntentFactsSchema.Type;
