import { planLines, type LinePlan, type LineState, type QuantityRequest } from "./cancel.ts";

export const RestockRejections = ["untracked_line"] as const;
export type RestockRejection = (typeof RestockRejections)[number];

export function decideReturn(lines: readonly LineState[], request: readonly QuantityRequest[]): LinePlan {
  return planLines(lines, request, "return");
}

export function decideRestock(lines: readonly LineState[], request: readonly QuantityRequest[]): LinePlan | { readonly ok: false; readonly rejection: RestockRejection } {
  const plan = planLines(lines, request, "restock");
  if (!plan.ok) return plan;
  return plan.lines.some((line) => !line.tracked) ? { ok: false, rejection: "untracked_line" } : plan;
}
