import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";
import { CancelRejections, LinePlanRejections } from "./cancel.ts";
import { RefundRejections, RefundStates } from "./refund.ts";
import { RestockRejections } from "./refund_restock.ts";
import { OperationView, TenantId } from "./payment_operations.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Purpose = Schema.String.check(filter<string>((value) => /^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= 128, "must be a purpose label"));
const ProviderId = Schema.String.check(filter<string>((value) => /^[A-Za-z0-9_]{1,255}$/.test(value), "must be a Stripe object id"));
const Detail = Schema.String.check(filter<string>((value) => value.length <= 500, "must be at most 500 characters"));
const LocalRefundId = Schema.String.check(filter<string>((value) => /^[1-9][0-9]{0,18}$/.test(value), "must be a local refund id"));

const LineQuantity = Schema.Struct({ position: Integer, quantity: Integer });

const guard = {
  sessionDigest: Digest, formTokenDigest: Digest, purpose: Purpose, actor: Schema.String, nowSeconds: Seconds,
  number: Integer, expectedRevision: Integer, lines: Schema.Array(LineQuantity), reason: Schema.String,
} as const;

export const RefundFactsSchema = Schema.Struct({
  id: ProviderId,
  status: Schema.Literals(RefundStates),
  amount: Integer,
  currency: Schema.String,
  paymentIntentId: Schema.NullOr(ProviderId),
  localId: Schema.NullOr(LocalRefundId),
  failureReason: Schema.NullOr(Detail),
});
export type RefundFacts = typeof RefundFactsSchema.Type;

export const RefundCommandSchemas = [
  Schema.Struct({ kind: Schema.Literal("order.refund"), ...guard, shipping: Schema.Boolean }),
  Schema.Struct({ kind: Schema.Literal("order.cancel"), ...guard, tenantId: TenantId }),
  Schema.Struct({ kind: Schema.Literal("order.return"), ...guard }),
  Schema.Struct({ kind: Schema.Literal("order.restock"), ...guard }),
  Schema.Struct({ kind: Schema.Literal("refund.observe"), refund: RefundFactsSchema, nowSeconds: Seconds }),
  Schema.Struct({ kind: Schema.Literal("refund.fail"), refundId: Integer, to: Schema.Literals(["failed", "blocked"]), error: Detail, nowSeconds: Seconds }),
] as const;

const refusals = ["session_invalid", "token_invalid", "stale", "not_found"] as const;

export const RefundResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("order.refund"), outcome: Schema.Literal("applied"), refundId: Integer }),
  Schema.Struct({ kind: Schema.Literal("order.refund"), outcome: Schema.Literals(refusals) }),
  Schema.Struct({ kind: Schema.Literal("order.refund"), outcome: Schema.Literal("rejected"), rejection: Schema.Literals(RefundRejections) }),
  Schema.Struct({ kind: Schema.Literal("order.cancel"), outcome: Schema.Literal("applied"), voided: Schema.Boolean }),
  Schema.Struct({ kind: Schema.Literal("order.cancel"), outcome: Schema.Literals(refusals) }),
  Schema.Struct({ kind: Schema.Literal("order.cancel"), outcome: Schema.Literal("rejected"), rejection: Schema.Literals(CancelRejections) }),
  Schema.Struct({ kind: Schema.Literal("order.return"), outcome: Schema.Literal("applied") }),
  Schema.Struct({ kind: Schema.Literal("order.return"), outcome: Schema.Literals(refusals) }),
  Schema.Struct({ kind: Schema.Literal("order.return"), outcome: Schema.Literal("rejected"), rejection: Schema.Literals(LinePlanRejections) }),
  Schema.Struct({ kind: Schema.Literal("order.restock"), outcome: Schema.Literal("applied") }),
  Schema.Struct({ kind: Schema.Literal("order.restock"), outcome: Schema.Literals(refusals) }),
  Schema.Struct({ kind: Schema.Literal("order.restock"), outcome: Schema.Literal("rejected"), rejection: Schema.Literals([...LinePlanRejections, ...RestockRejections]) }),
  Schema.Struct({ kind: Schema.Literal("refund.observe"), outcome: Schema.Literals(["unchanged", "advanced", "recorded", "unmapped", "ignored"]) }),
  Schema.Struct({ kind: Schema.Literal("refund.fail"), changed: Schema.Boolean }),
] as const;

const RefundWorkView = Schema.Struct({
  id: Integer,
  orderNumber: Integer,
  state: Schema.Literals(RefundStates),
  amountMinor: Integer,
  paymentIntentId: ProviderId,
  currency: Schema.String,
  providerRefundId: Schema.NullOr(ProviderId),
  operation: Schema.NullOr(OperationView),
});
export type RefundWorkView = typeof RefundWorkView.Type;

export const RefundQuerySchemas = [
  Schema.Struct({ kind: Schema.Literal("refund.view"), refundId: Integer }),
] as const;

export const RefundQueryResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("refund.view"), refund: Schema.NullOr(RefundWorkView) }),
] as const;

export type RefundCommand = (typeof RefundCommandSchemas)[number]["Type"];
export type RefundCommandResult = (typeof RefundResultSchemas)[number]["Type"];
export type RefundQuery = (typeof RefundQuerySchemas)[number]["Type"];
export type RefundQueryResult = (typeof RefundQueryResultSchemas)[number]["Type"];
