import {
  AdminPageSize, BulkRowLimit, checkCollectionText, checkLabel, checkProductText, isStatus, parsePriceInput, statusAuditAction,
  withOption, withoutOption, withoutValue, withoutVariant, withValue, withVariant,
  type ProductStructure, type EditResult,
} from "../catalog/edit.ts";
import { MaxCollections, MaxImagesPerProduct, MaxLabelBytes, MaxMembersPerCollect, MaxProducts } from "../catalog/scalars.ts";
import type { Status } from "../catalog/schema.ts";
import { PendingTtlSeconds } from "../media/limits.ts";
import type { Mutation } from "./guard.ts";
import { pathOfAsset } from "./media.ts";
import { all, audit, get, run, type Program } from "./program.ts";
import type { AdminQueryRow } from "./queries.ts";
import type {
  CatalogChange, CatalogQuery, CatalogQueryResult, CatalogRejection, CollectionEditViewModel, ProductEditViewModel,
} from "./catalog_operations.ts";

export interface CatalogContext {
  readonly actor: string;
  readonly nowSeconds: bigint;
}

type Refusal = { readonly kind: "stale" } | { readonly kind: "rejected"; readonly rejection: CatalogRejection };
type Outcome = Mutation<{ readonly entityId: bigint }, Refusal>;

const done = (entityId: bigint): Outcome => ({ applied: true, result: { entityId } });
const refuse = (rejection: CatalogRejection): Outcome => ({ applied: false, result: { kind: "rejected", rejection } });
const stale: Outcome = { applied: false, result: { kind: "stale" } };

const encoder = new TextEncoder();
function utf8Length(text: string): number {
  return encoder.encode(text).length;
}

function status(value: string): Status {
  if (!isStatus(value)) throw new Error(`catalog: stored status ${JSON.stringify(value)} is not a status`);
  return value;
}

function* readStructure(productId: bigint): Program<ProductStructure> {
  const options = yield* all("ListCatalogProductOptions", [productId]);
  const values = yield* all("ListCatalogProductValues", [productId]);
  const variants = yield* all("ListCatalogProductVariants", [productId]);
  const selections = yield* all("ListCatalogProductSelections", [productId]);
  return {
    options: options.map((option) => ({ id: option.id, name: option.name, values: values.filter((value) => value.option_id === option.id).map((value) => ({ id: value.id, value: value.value })) })),
    variants: variants.map((variant) => ({ id: variant.id, selections: new Map(selections.filter((selection) => selection.variant_id === variant.id).map((selection) => [selection.option_id, selection.value_id])) })),
  };
}

function* auditProduct(context: CatalogContext, action: Parameters<typeof audit>[0]["action"], productId: bigint, summary: string): Program<void> {
  const row = yield* get("GetCatalogProduct", [productId]);
  yield* audit({ actor: context.actor, action, entityKind: "product", entityId: productId.toString(), entityRevision: row?.revision ?? null, summary }, context.nowSeconds);
}

function* auditCollection(context: CatalogContext, action: Parameters<typeof audit>[0]["action"], collectionId: bigint, summary: string): Program<void> {
  const row = yield* get("GetCatalogCollection", [collectionId]);
  yield* audit({ actor: context.actor, action, entityKind: "collection", entityId: collectionId.toString(), entityRevision: row?.revision ?? null, summary }, context.nowSeconds);
}

function* withProduct(productId: bigint, expectedRevision: bigint, body: (row: AdminQueryRow<"GetCatalogProduct">) => Program<Outcome>): Program<Outcome> {
  const row = yield* get("GetCatalogProduct", [productId]);
  if (row === null) return refuse("unknown_product");
  if (row.revision !== expectedRevision) return stale;
  return yield* body(row);
}

function* withCollection(collectionId: bigint, expectedRevision: bigint, body: (row: AdminQueryRow<"GetCatalogCollection">) => Program<Outcome>): Program<Outcome> {
  const row = yield* get("GetCatalogCollection", [collectionId]);
  if (row === null) return refuse("unknown_collection");
  if (row.revision !== expectedRevision) return stale;
  return yield* body(row);
}

function* writeStructureEdit(context: CatalogContext, productId: bigint, result: EditResult, action: Parameters<typeof audit>[0]["action"], summary: string, apply: () => Program<void>): Program<Outcome> {
  if (!result.ok) return refuse(result.problem);
  yield* apply();
  yield* run("TouchCatalogProduct", [productId]);
  yield* auditProduct(context, action, productId, summary);
  return done(productId);
}

function* priceMinor(text: string): Program<bigint | null> {
  const store = yield* get("GetCatalogStore", []);
  return store === null ? null : parsePriceInput(text, Number(store.currency_exponent));
}

function* productAction(change: Extract<CatalogChange, { action: `product.${string}` | `variant.${string}` | `option.${string}` | `value.${string}` | `image.${string}` | "products.status" }>, context: CatalogContext): Program<Outcome> {
  switch (change.action) {
    case "product.create": {
      if (Object.keys(checkProductText(change)).length > 0) return refuse("invalid_input");
      const price = yield* priceMinor(change.price);
      if (price === null) return refuse("invalid_price");
      if ((yield* get("CountCatalogProducts", []))!.n >= BigInt(MaxProducts)) return refuse("limit");
      if ((yield* get("FindCatalogProductByHandle", [change.handle])) !== null) return refuse("handle_taken");
      const ids = (yield* get("CatalogNextIds", []))!;
      yield* run("InsertCatalogProduct", [ids.product, change.handle, change.title, change.vendor, change.description, "draft"]);
      yield* run("InsertCatalogVariant", [ids.variant, ids.product, null, price, 1n, 0n]);
      yield* auditProduct(context, "product.create", ids.product, `created draft ${change.handle}`);
      return done(ids.product);
    }
    case "product.update":
      return yield* withProduct(change.productId, change.expectedRevision, function* (row) {
        if (Object.keys(checkProductText(change)).length > 0) return refuse("invalid_input");
        const owner = yield* get("FindCatalogProductByHandle", [change.handle]);
        if (owner !== null && owner.id !== change.productId) return refuse("handle_taken");
        const changed = [
          row.title !== change.title ? "title" : null, row.handle !== change.handle ? "handle" : null,
          row.vendor !== change.vendor ? "vendor" : null, row.description !== change.description ? "description" : null,
        ].filter((name): name is string => name !== null);
        if (changed.length === 0) return done(change.productId);
        yield* run("UpdateCatalogProduct", [change.handle, change.title, change.vendor, change.description, change.productId]);
        yield* auditProduct(context, "product.update", change.productId, `changed ${changed.join(", ")}`);
        return done(change.productId);
      });
    case "product.status":
      return yield* withProduct(change.productId, change.expectedRevision, function* (row) {
        if (row.status === change.status) return refuse("status_unchanged");
        yield* run("SetCatalogProductStatus", [change.status, change.productId]);
        yield* auditProduct(context, "product.status", change.productId, `${statusAuditAction(status(row.status), change.status)}: ${row.status} -> ${change.status}`);
        return done(change.productId);
      });
    case "products.status": {
      const ids = [...new Set(change.productIds)];
      if (ids.length === 0 || ids.length > BulkRowLimit) return refuse("invalid_input");
      const rows = [];
      for (const id of ids) {
        const row = yield* get("GetCatalogProduct", [id]);
        if (row === null) return refuse("unknown_product");
        rows.push(row);
      }
      const targets = rows.filter((row) => row.status !== change.status);
      if (targets.length === 0) return refuse("status_unchanged");
      for (const row of targets) {
        yield* run("SetCatalogProductStatus", [change.status, row.id]);
        yield* auditProduct(context, "product.status", row.id, `${statusAuditAction(status(row.status), change.status)}: ${row.status} -> ${change.status} (bulk)`);
      }
      return done(BigInt(targets.length));
    }
    case "product.duplicate": {
      const source = yield* get("GetCatalogProduct", [change.productId]);
      if (source === null) return refuse("unknown_product");
      if ((yield* get("CountCatalogProducts", []))!.n >= BigInt(MaxProducts)) return refuse("limit");
      let handle = "";
      for (let attempt = 1; attempt <= 50 && handle === ""; attempt++) {
        const candidate = `${source.handle.slice(0, 190)}-copy${attempt === 1 ? "" : `-${attempt}`}`;
        if ((yield* get("FindCatalogProductByHandle", [candidate])) === null) handle = candidate;
      }
      const title = `${source.title} (copy)`;
      if (handle === "" || Object.keys(checkProductText({ title, handle, vendor: source.vendor, description: source.description })).length > 0) return refuse("limit");
      const ids = (yield* get("CatalogNextIds", []))!;
      const options = yield* all("ListCatalogProductOptions", [source.id]);
      const values = yield* all("ListCatalogProductValues", [source.id]);
      const variants = yield* all("ListCatalogProductVariants", [source.id]);
      const selections = yield* all("ListCatalogProductSelections", [source.id]);
      yield* run("InsertCatalogProduct", [ids.product, handle, title, source.vendor, source.description, "draft"]);
      const optionIds = new Map<bigint, bigint>();
      const valueIds = new Map<bigint, bigint>();
      const variantIds = new Map<bigint, bigint>();
      for (const [position, option] of options.entries()) {
        const id = ids.option + BigInt(position);
        optionIds.set(option.id, id);
        yield* run("InsertCatalogOption", [id, ids.product, option.name, BigInt(position)]);
      }
      const valuePositions = new Map<bigint, bigint>();
      for (const [index, value] of values.entries()) {
        const id = ids.value + BigInt(index);
        valueIds.set(value.id, id);
        const position = valuePositions.get(value.option_id) ?? 0n;
        valuePositions.set(value.option_id, position + 1n);
        yield* run("InsertCatalogOptionValue", [id, optionIds.get(value.option_id)!, value.value, position]);
      }
      for (const [index, variant] of variants.entries()) {
        const id = ids.variant + BigInt(index);
        variantIds.set(variant.id, id);
        yield* run("InsertCatalogVariant", [id, ids.product, variant.title, variant.price_minor, variant.available, variant.position]);
      }
      for (const selection of selections) {
        yield* run("InsertCatalogSelection", [variantIds.get(selection.variant_id)!, ids.product, optionIds.get(selection.option_id)!, valueIds.get(selection.value_id)!]);
      }
      for (const image of yield* all("ListCatalogProductImages", [source.id])) yield* run("InsertCatalogImage", [ids.product, image.url, image.alt_text, image.width, image.height, image.position]);
      for (const detail of yield* all("ListCatalogProductDetails", [source.id])) yield* run("InsertCatalogDetail", [ids.product, detail.key, detail.title, detail.body, detail.position]);
      yield* auditProduct(context, "product.duplicate", ids.product, `copied from product ${source.id} as draft ${handle}`);
      return done(ids.product);
    }
    case "image.add":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        if (change.alt !== "" && utf8Length(change.alt) > MaxLabelBytes) return refuse("invalid_input");
        if ((yield* get("CountCatalogProductImages", [change.productId]))!.n >= BigInt(MaxImagesPerProduct)) return refuse("limit");
        const detail = yield* get("GetMediaAsset", [change.detailMediaId]);
        const card = change.cardMediaId === null ? null : yield* get("GetMediaAsset", [change.cardMediaId]);
        const cutoff = context.nowSeconds - BigInt(PendingTtlSeconds);
        const usable = (row: typeof detail): boolean => row !== null && row.state === "pending" && row.created_at > cutoff;
        if (!usable(detail) || (change.cardMediaId !== null && (!usable(card) || change.cardMediaId === change.detailMediaId))) return refuse("media_unavailable");
        if (card !== null) yield* run("MarkMediaReady", [context.nowSeconds, null, card.id]);
        yield* run("MarkMediaReady", [context.nowSeconds, change.cardMediaId, detail!.id]);
        const position = (yield* get("CatalogNextImagePosition", [change.productId]))!.position;
        yield* run("InsertCatalogMediaImage", [change.productId, pathOfAsset(detail!), change.alt, detail!.width, detail!.height, detail!.id, position]);
        yield* run("TouchCatalogProduct", [change.productId]);
        yield* auditProduct(context, "product.image_add", change.productId, `added image from media ${detail!.id}`);
        return done(change.productId);
      });
    case "image.remove":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        const image = yield* get("GetCatalogProductImage", [change.imageId]);
        if (image === null || image.product_id !== change.productId) return refuse("unknown_image");
        yield* run("DeleteCatalogProductImage", [change.imageId]);
        yield* run("TouchCatalogProduct", [change.productId]);
        yield* auditProduct(context, "product.image_remove", change.productId, `removed image ${change.imageId}`);
        return done(change.productId);
      });
    case "image.alt":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        const image = yield* get("GetCatalogProductImage", [change.imageId]);
        if (image === null || image.product_id !== change.productId) return refuse("unknown_image");
        if (utf8Length(change.alt) > MaxLabelBytes) return refuse("invalid_input");
        yield* run("SetCatalogImageAlt", [change.alt, change.imageId]);
        yield* run("TouchCatalogProduct", [change.productId]);
        yield* auditProduct(context, "product.image_alt", change.productId, `changed alt text of image ${change.imageId}`);
        return done(change.productId);
      });
    case "image.move":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        const image = yield* get("GetCatalogProductImage", [change.imageId]);
        if (image === null || image.product_id !== change.productId) return refuse("unknown_image");
        const neighbor = yield* get(change.direction === "up" ? "GetCatalogImageAbove" : "GetCatalogImageBelow", [change.productId, image.position]);
        if (neighbor === null) return refuse("at_edge");
        const parking = (yield* get("CatalogNextImagePosition", [change.productId]))!.position;
        yield* run("SetCatalogImagePosition", [parking, image.id]);
        yield* run("SetCatalogImagePosition", [image.position, neighbor.id]);
        yield* run("SetCatalogImagePosition", [neighbor.position, image.id]);
        yield* run("TouchCatalogProduct", [change.productId]);
        yield* auditProduct(context, "product.image_move", change.productId, `moved image ${change.imageId} ${change.direction}`);
        return done(change.productId);
      });
    case "variant.update":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        const variant = yield* get("GetCatalogVariant", [change.variantId]);
        if (variant === null || variant.product_id !== change.productId) return refuse("unknown_variant");
        if (change.title !== null && Object.keys(checkLabel(change.title, "title")).length > 0) return refuse("invalid_input");
        const price = yield* priceMinor(change.price);
        if (price === null) return refuse("invalid_price");
        yield* run("UpdateCatalogVariant", [change.title, price, change.available ? 1n : 0n, change.variantId]);
        yield* run("TouchCatalogProduct", [change.productId]);
        yield* auditProduct(context, "variant.update", change.productId, `variant ${change.variantId}: price ${price}, ${change.available ? "available" : "unavailable"}`);
        return done(change.productId);
      });
    case "variant.add":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        if (change.title !== null && Object.keys(checkLabel(change.title, "title")).length > 0) return refuse("invalid_input");
        const price = yield* priceMinor(change.price);
        if (price === null) return refuse("invalid_price");
        const structure = yield* readStructure(change.productId);
        const ids = (yield* get("CatalogNextIds", []))!;
        const positions = (yield* get("CatalogNextPositions", [change.productId, change.productId]))!;
        const chosen = structure.options.map((option) => change.selections.filter((selection) => selection.optionId === option.id));
        const complete = chosen.every((entries) => entries.length === 1) && change.selections.length === structure.options.length;
        const valueIds = chosen.map((entries) => entries[0]?.valueId ?? 0n);
        const result: EditResult = complete ? withVariant(structure, ids.variant, valueIds) : { ok: false, problem: "selection_incomplete" };
        return yield* writeStructureEdit(context, change.productId, result, "variant.add", `variant ${ids.variant}: price ${price}`, function* () {
          yield* run("InsertCatalogVariant", [ids.variant, change.productId, change.title, price, change.available ? 1n : 0n, positions.variant]);
          for (const [index, option] of structure.options.entries()) yield* run("InsertCatalogSelection", [ids.variant, change.productId, option.id, valueIds[index]!]);
        });
      });
    case "variant.remove":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        const variant = yield* get("GetCatalogVariant", [change.variantId]);
        if (variant === null || variant.product_id !== change.productId) return refuse("unknown_variant");
        if ((yield* get("CountVariantCartLines", [change.variantId]))!.n > 0n) return refuse("in_cart");
        if ((yield* get("CountVariantCommercialReferences", [change.variantId]))!.n > 0n) return refuse("commercial_reference");
        const result = withoutVariant(yield* readStructure(change.productId), change.variantId);
        return yield* writeStructureEdit(context, change.productId, result, "variant.remove", `variant ${change.variantId}`, function* () {
          yield* run("DeleteCatalogVariant", [change.variantId]);
        });
      });
    case "option.add":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        if (Object.keys(checkLabel(change.name, "name")).length > 0 || Object.keys(checkLabel(change.value, "value")).length > 0) return refuse("invalid_input");
        const structure = yield* readStructure(change.productId);
        const ids = (yield* get("CatalogNextIds", []))!;
        const positions = (yield* get("CatalogNextPositions", [change.productId, change.productId]))!;
        const result = withOption(structure, ids.option, change.name, ids.value, change.value);
        return yield* writeStructureEdit(context, change.productId, result, "option.add", `option ${change.name}`, function* () {
          yield* run("InsertCatalogOption", [ids.option, change.productId, change.name, positions.option]);
          yield* run("InsertCatalogOptionValue", [ids.value, ids.option, change.value, 0n]);
          for (const variant of structure.variants) yield* run("InsertCatalogSelection", [variant.id, change.productId, ids.option, ids.value]);
        });
      });
    case "option.remove":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        const result = withoutOption(yield* readStructure(change.productId), change.optionId);
        return yield* writeStructureEdit(context, change.productId, result, "option.remove", `option ${change.optionId}`, function* () {
          yield* run("DeleteCatalogSelectionsOfOption", [change.optionId]);
          yield* run("DeleteCatalogOption", [change.optionId]);
        });
      });
    case "value.add":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        if (Object.keys(checkLabel(change.value, "value")).length > 0) return refuse("invalid_input");
        const ids = (yield* get("CatalogNextIds", []))!;
        const result = withValue(yield* readStructure(change.productId), change.optionId, ids.value, change.value);
        const position = result.ok ? (yield* get("CatalogNextValuePosition", [change.optionId]))!.position : 0n;
        return yield* writeStructureEdit(context, change.productId, result, "value.add", `value ${change.value} on option ${change.optionId}`, function* () {
          yield* run("InsertCatalogOptionValue", [ids.value, change.optionId, change.value, position]);
        });
      });
    case "value.remove":
      return yield* withProduct(change.productId, change.expectedRevision, function* () {
        const result = withoutValue(yield* readStructure(change.productId), change.valueId);
        return yield* writeStructureEdit(context, change.productId, result, "value.remove", `value ${change.valueId}`, function* () {
          yield* run("DeleteCatalogOptionValue", [change.valueId]);
        });
      });
  }
}

function* collectionAction(change: Extract<CatalogChange, { action: `collection.${string}` }>, context: CatalogContext): Program<Outcome> {
  switch (change.action) {
    case "collection.create": {
      if (Object.keys(checkCollectionText(change)).length > 0) return refuse("invalid_input");
      if ((yield* get("CountCatalogCollections", []))!.n >= BigInt(MaxCollections)) return refuse("limit");
      if ((yield* get("FindCatalogCollectionByHandle", [change.handle])) !== null) return refuse("handle_taken");
      const ids = (yield* get("CatalogNextIds", []))!;
      yield* run("InsertCatalogCollection", [ids.collection, change.handle, change.title, change.description, "draft"]);
      yield* auditCollection(context, "collection.create", ids.collection, `created draft ${change.handle}`);
      return done(ids.collection);
    }
    case "collection.update":
      return yield* withCollection(change.collectionId, change.expectedRevision, function* (row) {
        if (Object.keys(checkCollectionText(change)).length > 0) return refuse("invalid_input");
        const owner = yield* get("FindCatalogCollectionByHandle", [change.handle]);
        if (owner !== null && owner.id !== change.collectionId) return refuse("handle_taken");
        const changed = [
          row.title !== change.title ? "title" : null, row.handle !== change.handle ? "handle" : null, row.description !== change.description ? "description" : null,
        ].filter((name): name is string => name !== null);
        if (changed.length === 0) return done(change.collectionId);
        yield* run("UpdateCatalogCollection", [change.handle, change.title, change.description, change.collectionId]);
        yield* auditCollection(context, "collection.update", change.collectionId, `changed ${changed.join(", ")}`);
        return done(change.collectionId);
      });
    case "collection.status":
      return yield* withCollection(change.collectionId, change.expectedRevision, function* (row) {
        if (row.status === change.status) return refuse("status_unchanged");
        yield* run("SetCatalogCollectionStatus", [change.status, change.collectionId]);
        yield* auditCollection(context, "collection.status", change.collectionId, `${row.status} -> ${change.status}`);
        return done(change.collectionId);
      });
    case "collection.member_add":
      return yield* withCollection(change.collectionId, change.expectedRevision, function* () {
        if ((yield* get("GetCatalogProduct", [change.productId])) === null) return refuse("unknown_product");
        if ((yield* get("GetCatalogMember", [change.collectionId, change.productId])) !== null) return refuse("already_member");
        if ((yield* get("CountCatalogCollectionMembers", [change.collectionId]))!.n >= BigInt(MaxMembersPerCollect)) return refuse("limit");
        const position = (yield* get("CatalogNextMemberPosition", [change.collectionId]))!.position;
        yield* run("InsertCatalogMember", [change.collectionId, change.productId, position]);
        yield* run("TouchCatalogCollection", [change.collectionId]);
        yield* auditCollection(context, "collection.member_add", change.collectionId, `added product ${change.productId}`);
        return done(change.collectionId);
      });
    case "collection.member_remove":
      return yield* withCollection(change.collectionId, change.expectedRevision, function* () {
        if ((yield* get("GetCatalogMember", [change.collectionId, change.productId])) === null) return refuse("not_member");
        yield* run("DeleteCatalogMember", [change.collectionId, change.productId]);
        yield* run("TouchCatalogCollection", [change.collectionId]);
        yield* auditCollection(context, "collection.member_remove", change.collectionId, `removed product ${change.productId}`);
        return done(change.collectionId);
      });
    case "collection.member_move":
      return yield* withCollection(change.collectionId, change.expectedRevision, function* () {
        const member = yield* get("GetCatalogMember", [change.collectionId, change.productId]);
        if (member === null) return refuse("not_member");
        const neighbor = yield* get(change.direction === "up" ? "GetCatalogMemberAbove" : "GetCatalogMemberBelow", [change.collectionId, member.position]);
        if (neighbor === null) return refuse("at_edge");
        const parking = (yield* get("CatalogNextMemberPosition", [change.collectionId]))!.position;
        yield* run("SetCatalogMemberPosition", [parking, change.collectionId, change.productId]);
        yield* run("SetCatalogMemberPosition", [member.position, change.collectionId, neighbor.product_id]);
        yield* run("SetCatalogMemberPosition", [neighbor.position, change.collectionId, change.productId]);
        yield* run("TouchCatalogCollection", [change.collectionId]);
        yield* auditCollection(context, "collection.member_move", change.collectionId, `moved product ${change.productId} ${change.direction}`);
        return done(change.collectionId);
      });
  }
}

export function* catalogEffect(change: CatalogChange, context: CatalogContext): Program<Outcome> {
  if (change.action.startsWith("collection.")) return yield* collectionAction(change as Extract<CatalogChange, { action: `collection.${string}` }>, context);
  return yield* productAction(change as Parameters<typeof productAction>[0], context);
}

export function* catalogQueryProgram(query: CatalogQuery): Program<CatalogQueryResult> {
  switch (query.kind) {
    case "catalog.new": {
      const store = yield* get("GetCatalogStore", []);
      return { kind: "catalog.new", currency: store === null ? null : { code: store.currency_code, exponent: Number(store.currency_exponent) } };
    }
    case "catalog.products": {
      const store = (yield* get("GetCatalogStore", []))!;
      const rows = yield* all("ListCatalogProducts", [query.after, query.status, query.status]);
      return {
        kind: "catalog.products",
        view: {
          currency: { code: store.currency_code, exponent: Number(store.currency_exponent) },
          hasMore: rows.length > AdminPageSize,
          items: rows.slice(0, AdminPageSize).map((row) => ({ id: row.id, handle: row.handle, title: row.title, status: status(row.status), revision: row.revision, variantCount: row.variant_count, minPrice: row.min_price, maxPrice: row.max_price })),
        },
      };
    }
    case "catalog.product": return { kind: "catalog.product", view: yield* readProductView(query.productId) };
    case "catalog.collections": {
      const rows = yield* all("ListCatalogCollections", [query.after]);
      return {
        kind: "catalog.collections",
        view: { hasMore: rows.length > AdminPageSize, items: rows.slice(0, AdminPageSize).map((row) => ({ id: row.id, handle: row.handle, title: row.title, status: status(row.status), revision: row.revision, memberCount: row.member_count })) },
      };
    }
    case "catalog.collection": return { kind: "catalog.collection", view: yield* readCollectionView(query.collectionId) };
  }
}

function* readProductView(productId: bigint): Program<ProductEditViewModel | null> {
  const product = yield* get("GetCatalogProduct", [productId]);
  const store = yield* get("GetCatalogStore", []);
  if (product === null || store === null) return null;
  const structure = yield* readStructure(productId);
  const variants = yield* all("ListCatalogProductVariants", [productId]);
  const valueNames = new Map(structure.options.flatMap((option) => option.values.map((value) => [value.id, value.value] as const)));
  const images = yield* all("ListCatalogProductImages", [productId]);
  const details = yield* all("ListCatalogProductDetails", [productId]);
  const collections = yield* all("ListCatalogProductCollections", [productId]);
  const events = yield* all("ListRecentAuditEvents", ["product", productId.toString()]);
  return {
    currency: { code: store.currency_code, exponent: Number(store.currency_exponent) },
    product: { id: product.id, handle: product.handle, title: product.title, vendor: product.vendor, description: product.description, status: status(product.status), revision: product.revision },
    options: structure.options.map((option) => ({ id: option.id, name: option.name, values: option.values.map((value) => ({ id: value.id, value: value.value })) })),
    variants: variants.map((variant) => {
      const selections = structure.variants.find((candidate) => candidate.id === variant.id)?.selections ?? new Map<bigint, bigint>();
      return {
        id: variant.id, title: variant.title, priceMinor: variant.price_minor, available: variant.available === 1n,
        labels: structure.options.map((option) => valueNames.get(selections.get(option.id) ?? 0n) ?? ""),
        stock: variant.on_hand === null || variant.held === null || variant.allocated === null ? null : { onHand: variant.on_hand, held: variant.held, allocated: variant.allocated },
        cartLines: variant.cart_lines,
      };
    }),
    images: images.map((image) => ({ id: image.id, url: image.url, altText: image.alt_text, width: image.width, height: image.height, managed: image.media_id !== null })),
    details: details.map((detail) => ({ key: detail.key, title: detail.title, body: detail.body })),
    collections: collections.map((collection) => ({ id: collection.id, title: collection.title, status: status(collection.status) })),
    audit: events.map((event) => ({ id: event.id, actor: event.actor, action: event.action, entityRevision: event.entity_revision, summary: event.summary, createdAt: event.created_at })),
  };
}

function* readCollectionView(collectionId: bigint): Program<CollectionEditViewModel | null> {
  const collection = yield* get("GetCatalogCollection", [collectionId]);
  if (collection === null) return null;
  const members = yield* all("ListCatalogCollectionMembers", [collectionId]);
  const count = (yield* get("CountCatalogCollectionMembers", [collectionId]))!.n;
  const events = yield* all("ListRecentAuditEvents", ["collection", collectionId.toString()]);
  return {
    collection: { id: collection.id, handle: collection.handle, title: collection.title, description: collection.description, status: status(collection.status), revision: collection.revision },
    members: members.map((member) => ({ productId: member.product_id, handle: member.handle, title: member.title, status: status(member.status) })),
    memberCount: count,
    audit: events.map((event) => ({ id: event.id, actor: event.actor, action: event.action, entityRevision: event.entity_revision, summary: event.summary, createdAt: event.created_at })),
  };
}
