export { DefaultImportChunkBytes, MaxImportChunkBytes };

interface StagedImport {
  readonly replace: boolean;
  readonly chunks: Uint8Array[];
  bytes: number;
}

function concatChunks(chunks: readonly Uint8Array[], totalBytes: number): Uint8Array {
  const combined = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    combined.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return combined;
}

function readRawCatalogPayloadSync(tx: SyncTransaction, queries: StorefrontQueries): RawCatalogPayload {
  const footprintRow = tx.get(queries.prepare("GetPublishedCatalogFootprint").sql);
  if (footprintRow === null) throw new DatabaseError("GetPublishedCatalogFootprint returned no rows");
  queries.decodeRow("GetPublishedCatalogFootprint", footprintRow);

  const versions = queries.requiredSync(tx, "GetCatalogVersions");
  const generation = versions.generation.toString();
  const stockVersion = versions.stock_version.toString();

  const storeRow = tx.get(queries.prepare("GetStore").sql);
  if (storeRow === null) throw new DatabaseError("storefront: no store row; load a catalog first");
  queries.decodeRow("GetStore", storeRow);

  const products = tx.all(queries.prepare("ListPublishedProducts").sql);
  const variants = tx.all(queries.prepare("ListPublishedVariants").sql);
  const selections = tx.all(queries.prepare("ListPublishedSelections").sql);
  const options = tx.all(queries.prepare("ListPublishedOptionValues").sql);
  const images = tx.all(queries.prepare("ListPublishedImages").sql);
  const details = tx.all(queries.prepare("ListPublishedDetails").sql);
  const collections = tx.all(queries.prepare("ListPublishedCollections").sql);
  const members = tx.all(queries.prepare("ListPublishedMembers").sql);
  const profile = tx.get(queries.prepare("GetShopProfile").sql);
  if (profile === null) throw new DatabaseError("GetShopProfile returned no rows");
  const pages = tx.all(queries.prepare("ListShopPages").sql);
  const redirects = tx.all(queries.prepare("ListPublishedRedirects").sql);

  return {
    generation,
    stockVersion,
    footprint: footprintRow,
    store: storeRow,
    products,
    variants,
    selections,
    options,
    images,
    details,
    collections,
    members,
    profile,
    pages,
    redirects,
  };
}

export class TenantStore extends DurableObject<TenantStoreEnv> {
  protected readonly sqlAdapter: DurableObjectSqlAdapter;
  readonly #stagedImports = new Map<string, StagedImport>();
  #migrationsVerified = false;
  #armedAtMs: number | null = null;
  #registry: WorkRegistry | null = null;

  constructor(ctx: DurableObjectState, env: TenantStoreEnv) {
    super(ctx, env);
    this.sqlAdapter = new DurableObjectSqlAdapter(ctx.storage.sql);
  }

  protected get queries(): StorefrontQueries {
    return getEmbeddedPersistenceBundle().queries;
  }

  protected get migrations(): MigrationRunner {
    return getEmbeddedPersistenceBundle().migrations;
  }

  protected ensureMigrationsVerified(tx: SyncTransaction): void {
    if (!this.#migrationsVerified) {
      this.migrations.verifySync(tx);
      this.#migrationsVerified = true;
    }
  }

  protected invalidateMigrationsVerified(): void {
    this.#migrationsVerified = false;
  }

  protected runReadTransaction<T>(operation: (tx: SyncTransaction) => T): T {
    return this.ctx.storage.transactionSync(() => operation(this.sqlAdapter));
  }

  protected runWriteTransaction<T>(operation: (tx: SyncTransaction) => T): T {
    return this.ctx.storage.transactionSync(() => operation(this.sqlAdapter));
  }

  protected observed<T>(method: RpcMethod, operation: () => T): RpcResult<T> {
    markInvocation();
    return wrapRpcResult(operation, (error) => reportCaught(`store.rpc.${method}`, error));
  }

  protected observedCommerce<T>(operation: Extract<ErrorOperation, `store.rpc.commerce${string}`>, body: () => T): RpcResult<T> {
    markInvocation();
    return wrapRpcResult(body, (error) => {
      if (thrownException(error) !== "inventory.invariant") reportCaught(operation, error);
    });
  }

  protected providerEventHandlers(settings: PaymentSettings): ProviderEventHandlers {
    return defaultProviderEventHandlers(settings);
  }

  protected workRegistry(): WorkRegistry {
    this.#registry ??= cloudflareWorkRegistry(this.env, (settings) => this.providerEventHandlers(settings));
    return this.#registry;
  }

  protected applyCommand(command: AdminCommand): AdminCommandResult {
    let armed: number | null = null;
    let result: AdminCommandResult;
    try {
      result = this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        const queries = getEmbeddedProgramQueries();
        const outcome = runProgramSync(tx, queries, adminCommandProgram(command));
        armed = this.armAlarm(tx, queries.admin.prepare("GetNextWorkAt", []));
        return outcome;
      });
    } catch (error) {
      if (thrownException(error) === "inventory.invariant") reportCaught("inventory.invariant", error);
      throw error;
    }
    if (armed !== null) this.#armedAtMs = armed;
    for (const exception of commerceExceptions(command, result)) reportCaught(exception.exception, exception);
    return result;
  }

  protected applyQuery(query: AdminQuery): AdminQueryResult {
    return this.runReadTransaction((tx) => {
      this.ensureMigrationsVerified(tx);
      return runProgramSync(tx, getEmbeddedProgramQueries(), adminQueryProgram(query));
    });
  }

  private armAlarm(tx: SyncTransaction, prepared: { readonly sql: string; readonly params: readonly SQLBoundValue[] }): number | null {
    const row = tx.get(prepared.sql, prepared.params);
    if (row === null) throw new DatabaseError("GetNextWorkAt returned no rows");
    const nextAt = getEmbeddedProgramQueries().admin.decodeRow("GetNextWorkAt", row).next_at;
    if (nextAt === null) return null;
    const target = Number(nextAt) * 1000;
    if (target === this.#armedAtMs) return null;
    void this.ctx.storage.setAlarm(target);
    return target;
  }

  private localBackend(): AdminBackend {
    return {
      command: async <C extends AdminCommand>(command: C): Promise<CommandResultFor<C>> => this.applyCommand(command) as CommandResultFor<C>,
      query: async <Q extends AdminQuery>(query: Q): Promise<QueryResultFor<Q>> => this.applyQuery(query) as QueryResultFor<Q>,
    };
  }

  async commerceCommand(requestText: string): Promise<RpcResult<string>> {
    return this.observedCommerce("store.rpc.commerceCommand", () => encodeAdminCommandResult(this.applyCommand(decodeAdminCommand(requestText))));
  }

  async commerceQuery(requestText: string): Promise<RpcResult<string>> {
    markInvocation();
    try {
      const result = this.applyQuery(decodeAdminQuery(requestText));
      await this.ensureAlarm();
      return wrapRpcResult(() => encodeAdminQueryResult(result));
    } catch (error) {
      if (!isDomainRejection(error)) reportCaught("store.rpc.commerceQuery", error);
      return wrapRpcResult<string>(() => { throw error; });
    }
  }

  private async ensureAlarm(): Promise<void> {
    const queries = getEmbeddedProgramQueries();
    const prepared = queries.admin.prepare("GetNextWorkAt", []);
    const nextAt = this.runReadTransaction((tx) => {
      this.ensureMigrationsVerified(tx);
      const row = tx.get(prepared.sql, prepared.params);
      if (row === null) throw new DatabaseError("GetNextWorkAt returned no rows");
      return queries.admin.decodeRow("GetNextWorkAt", row).next_at;
    });
    if (nextAt === null) return;
    const target = Number(nextAt) * 1000;
    const current = await this.ctx.storage.getAlarm();
    if (current === null || current > target) await this.ctx.storage.setAlarm(target);
    this.#armedAtMs = current === null || current > target ? target : current;
  }

  override async alarm(): Promise<void> {
    this.#armedAtMs = null;
    markInvocation();
    try {
      await runDueWork({
        backend: this.localBackend(), registry: this.workRegistry(), owner: `do-${crypto.randomUUID()}`, nowMs: () => Date.now(),
        onError: (_item, error) => { if (thrownException(error) === "provider.error") reportCaught("provider.error", error); },
      });
    } catch (error) {
      reportCaught("store.alarm", error);
      throw error;
    }
  }

  async migrate(nowSeconds?: number): Promise<RpcResult<readonly number[]>> {
    return wrapRpcResult(() =>
      this.runWriteTransaction((tx) => {
        try {
          const applied = this.migrations.applySync(tx, nowSeconds);
          this.#migrationsVerified = true;
          return applied;
        } catch (error) {
          this.#migrationsVerified = false;
          throw error;
        }
      }),
    );
  }

  async verifyMigrations(): Promise<RpcResult<void>> {
    return wrapRpcResult(() =>
      this.runReadTransaction((tx) => {
        try {
          this.migrations.verifySync(tx);
          this.#migrationsVerified = true;
        } catch (error) {
          this.#migrationsVerified = false;
          throw error;
        }
      }),
    );
  }

  async catalogGeneration(): Promise<RpcResult<string>> {
    return wrapRpcResult(() =>
      this.runReadTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        return this.queries.requiredSync(tx, "GetCatalogGeneration").generation.toString();
      }),
    );
  }

  private currentCatalogVersion(tx: SyncTransaction): string {
    const versions = this.queries.requiredSync(tx, "GetCatalogVersions");
    return catalogVersion(versions.generation, versions.stock_version);
  }

  async syncCatalog(knownVersion: string | null): Promise<RpcResult<SyncCatalogRpcResponse>> {
    return this.observed("syncCatalog", () =>
      this.runReadTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        const currentVersion = this.currentCatalogVersion(tx);
        if (knownVersion !== null && knownVersion === currentVersion) {
          return { unchanged: true, version: currentVersion };
        }
        const payload = readRawCatalogPayloadSync(tx, this.queries);
        return { unchanged: false, version: catalogVersion(payload.generation, payload.stockVersion), payload };
      }),
    );
  }

  async readCart(request: ReadCartRpcRequest): Promise<RpcResult<ReadCartRpcResponse>> {
    return this.observed("readCart", () =>
      this.runReadTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        const currentVersion = this.currentCatalogVersion(tx);
        const payload =
          request.knownVersion !== null && request.knownVersion === currentVersion
            ? null
            : readRawCatalogPayloadSync(tx, this.queries);
        const nowSeconds = BigInt(request.nowSeconds);
        let cartRows: readonly SQLRow[] = [];
        let selectionRows: readonly SQLRow[] = [];
        if (request.tokenHash !== null) {
          const live = this.queries.getSync(tx, "GetLiveSession", [request.tokenHash, nowSeconds]);
          if (live !== null) {
            const preparedCart = this.queries.prepare("ListCartLines", [live.token_hash]);
            cartRows = tx.all(preparedCart.sql, preparedCart.params);
            for (const row of cartRows) this.queries.decodeRow("ListCartLines", row);
            const preparedSel = this.queries.prepare("ListVariantSelectionLabels", [live.token_hash]);
            selectionRows = tx.all(preparedSel.sql, preparedSel.params);
            for (const row of selectionRows) this.queries.decodeRow("ListVariantSelectionLabels", row);
          }
        }
        return {
          version: currentVersion,
          payload,
          cartRows,
          selectionRows,
        };
      }),
    );
  }

  async addToCart(request: AddCartRpcRequest): Promise<RpcResult<AddCartRpcResponse>> {
    return this.observed("addToCart", () => {
      const prepared: PreparedAddCart = {
        tokenHash: request.tokenHash === null ? null : new Uint8Array(request.tokenHash),
        variantID: BigInt(request.variantID),
        quantity: request.quantity,
        nowSeconds: BigInt(request.nowSeconds),
        freshSession: {
          token: request.freshToken,
          expires: new Date(request.freshExpiresMs),
        },
        freshHash: new Uint8Array(request.freshHash),
        expiresSeconds: BigInt(request.expiresSeconds),
      };
      const created = this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        return executeAddToCartSync(tx, this.queries, prepared);
      });
      return {
        session: created === null ? null : { token: created.token, expiresMs: created.expires.getTime() },
      };
    });
  }

  async setCartQuantity(request: SetCartRpcRequest): Promise<RpcResult<void>> {
    return this.observed("setCartQuantity", () => {
      const prepared: PreparedSetCart = {
        tokenHash: request.tokenHash === null ? null : new Uint8Array(request.tokenHash),
        variantID: BigInt(request.variantID),
        quantity: request.quantity,
        nowSeconds: BigInt(request.nowSeconds),
      };
      this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        executeSetCartQuantitySync(tx, this.queries, prepared);
      });
    });
  }

  async removeCartItem(request: RemoveCartRpcRequest): Promise<RpcResult<void>> {
    return this.observed("removeCartItem", () => {
      const prepared: PreparedRemoveCart = {
        tokenHash: request.tokenHash === null ? null : new Uint8Array(request.tokenHash),
        variantID: BigInt(request.variantID),
        nowSeconds: BigInt(request.nowSeconds),
      };
      this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        executeRemoveCartItemSync(tx, this.queries, prepared);
      });
    });
  }

  async beginImport(replace: boolean): Promise<RpcResult<string>> {
    return wrapRpcResult(() => {
      const importId = crypto.randomUUID();
      this.#stagedImports.set(importId, { replace, chunks: [], bytes: 0 });
      return importId;
    });
  }

  async appendImportChunk(importId: string, chunk: Uint8Array): Promise<RpcResult<void>> {
    return wrapRpcResult(() => {
      const staged = this.#stagedImports.get(importId);
      if (staged === undefined) {
        throw new CatalogInputError(`import: unknown or expired staged import ${importId}`);
      }
      const copy = new Uint8Array(chunk);
      if (copy.byteLength === 0 || copy.byteLength > MaxImportChunkBytes) {
        this.#stagedImports.delete(importId);
        throw new CatalogInputError(`import: chunk of ${copy.byteLength} bytes exceeds limit ${MaxImportChunkBytes}`);
      }
      if (staged.bytes + copy.byteLength > MaxImportBytes) {
        this.#stagedImports.delete(importId);
        throw new CatalogInputError(`import: staged catalog exceeds ${MaxImportBytes}-byte limit`);
      }
      staged.chunks.push(copy);
      staged.bytes += copy.byteLength;
    });
  }

  async commitImport(importId: string, imageHosts: readonly string[]): Promise<RpcResult<ImportSummaryRpc>> {
    return wrapRpcResult(() => {
      const staged = this.#stagedImports.get(importId);
      this.#stagedImports.delete(importId);
      if (staged === undefined) {
        throw new CatalogInputError(`import: unknown or expired staged import ${importId}`);
      }
      if (staged.bytes === 0) {
        throw new CatalogInputError("import: staged catalog is empty");
      }
      const input = concatChunks(staged.chunks, staged.bytes);
      const catalog = parseAndValidateCatalog(input, imageHosts);
      const summary = this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        return writeCatalogSync(tx, this.queries, catalog, staged.replace);
      });
      return serializeImportSummary(summary);
    });
  }

  async abortImport(importId: string): Promise<RpcResult<void>> {
    return wrapRpcResult(() => {
      this.#stagedImports.delete(importId);
    });
  }

  async importCatalog(
    chunks: readonly Uint8Array[],
    imageHosts: readonly string[],
    replace: boolean,
  ): Promise<RpcResult<ImportSummaryRpc>> {
    return wrapRpcResult(() => {
      const id = unwrapRpcResult(this.beginImportSync(replace));
      for (const chunk of chunks) {
        unwrapRpcResult(this.appendImportChunkSync(id, chunk));
      }
      return unwrapRpcResult(this.commitImportSync(id, imageHosts));
    });
  }

  private beginImportSync(replace: boolean): RpcResult<string> {
    return wrapRpcResult(() => {
      const importId = crypto.randomUUID();
      this.#stagedImports.set(importId, { replace, chunks: [], bytes: 0 });
      return importId;
    });
  }

  private appendImportChunkSync(importId: string, chunk: Uint8Array): RpcResult<void> {
    return wrapRpcResult(() => {
      const staged = this.#stagedImports.get(importId);
      if (staged === undefined) throw new CatalogInputError(`import: unknown staged import ${importId}`);
      const copy = new Uint8Array(chunk);
      if (copy.byteLength === 0 || copy.byteLength > MaxImportChunkBytes) {
        this.#stagedImports.delete(importId);
        throw new CatalogInputError(`import: chunk of ${copy.byteLength} bytes exceeds limit ${MaxImportChunkBytes}`);
      }
      if (staged.bytes + copy.byteLength > MaxImportBytes) {
        this.#stagedImports.delete(importId);
        throw new CatalogInputError(`import: staged catalog exceeds ${MaxImportBytes}-byte limit`);
      }
      staged.chunks.push(copy);
      staged.bytes += copy.byteLength;
    });
  }

  private commitImportSync(importId: string, imageHosts: readonly string[]): RpcResult<ImportSummaryRpc> {
    return wrapRpcResult(() => {
      const staged = this.#stagedImports.get(importId);
      this.#stagedImports.delete(importId);
      if (staged === undefined) throw new CatalogInputError(`import: unknown staged import ${importId}`);
      if (staged.bytes === 0) throw new CatalogInputError("import: staged catalog is empty");
      const input = concatChunks(staged.chunks, staged.bytes);
      const catalog = parseAndValidateCatalog(input, imageHosts);
      const summary = this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        return writeCatalogSync(tx, this.queries, catalog, staged.replace);
      });
      return serializeImportSummary(summary);
    });
  }

  async disposableReset(): Promise<RpcResult<void>> {
    const originHost = getEmbeddedOriginHost();
    if (originHost === null || !isLocalhostHost(originHost)) {
      return wrapRpcResult<void>(() => { throw new Error(`disposable reset refused: this object's tenant origin ${originHost === null ? "is not configured" : JSON.stringify(originHost)} is not localhost or *.localhost`); });
    }
    try {
      await this.ctx.storage.deleteAll();
    } catch (error) {
      return wrapRpcResult<void>(() => { throw error; });
    }
    return wrapRpcResult(() => {
      this.invalidateMigrationsVerified();
      this.#stagedImports.clear();
    });
  }

  async exportState(): Promise<RpcResult<Uint8Array>> {
    return wrapRpcResult(() =>
      this.runReadTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        return marshalTenantState(exportTenantStateSync(tx));
      }),
    );
  }

  async importState(
    bytes: Uint8Array,
    imageHosts: readonly string[],
    replace: boolean,
  ): Promise<RpcResult<ImportSummaryRpc>> {
    return wrapRpcResult(() => {
      const state = decodeTenantState(new Uint8Array(bytes), imageHosts);
      const summary = this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        return writeTenantStateSync(tx, this.queries, state, replace);
      });
      return serializeImportSummary(summary);
    });
  }
}
