import { AssertionLeewaySeconds, AssertionMaxLifetimeSeconds } from "./policy.ts";
import { validEmail, validIssuer, validSubject, type Principal } from "./principal.ts";

export const AssertionRejections = [
  "malformed",
  "unsupported_algorithm",
  "unknown_key",
  "bad_signature",
  "wrong_issuer",
  "wrong_audience",
  "expired",
  "not_yet_valid",
  "bad_claims",
] as const;
export type AssertionRejection = (typeof AssertionRejections)[number];

export class AssertionError extends Error {
  readonly reason: AssertionRejection;
  constructor(reason: AssertionRejection) {
    super(`identity: assertion rejected (${reason})`);
    this.name = "AssertionError";
    this.reason = reason;
  }
}

export interface AssertionVerifier {
  readonly issuer: string;
  readonly keys: ReadonlyMap<string, CryptoKey>;
}

export interface VerifiedAssertion {
  readonly principal: Principal;
  readonly authTime: number;
  readonly nonce: string;
}

export const AssertionAlgorithm = "ES256";
export const MaxAssertionBytes = 4096;
const ecdsa = { name: "ECDSA", hash: "SHA-256" } as const;
const nonceShape = /^[A-Za-z0-9_-]{43}$/;

export function encodeBase64Url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
}

export function decodeBase64Url(text: string): Uint8Array | null {
  if (!/^[A-Za-z0-9_-]*$/.test(text) || text.length % 4 === 1) return null;
  try {
    const binary = atob(text.replaceAll("-", "+").replaceAll("_", "/") + "=".repeat((4 - (text.length % 4)) % 4));
    return Uint8Array.from(binary, (character) => character.charCodeAt(0));
  } catch {
    return null;
  }
}

export async function importAssertionKey(jwk: JsonWebKey): Promise<CryptoKey> {
  return await crypto.subtle.importKey("jwk", jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["verify"]);
}

function parseSegment(segment: string): Record<string, unknown> {
  const bytes = decodeBase64Url(segment);
  if (bytes === null) throw new AssertionError("malformed");
  let value: unknown;
  try {
    value = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bytes));
  } catch {
    throw new AssertionError("malformed");
  }
  if (typeof value !== "object" || value === null || Array.isArray(value)) throw new AssertionError("malformed");
  return value as Record<string, unknown>;
}

function integerClaim(claims: Record<string, unknown>, name: string): number {
  const value = claims[name];
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0) throw new AssertionError("bad_claims");
  return value;
}

export async function verifyAssertion(
  token: string,
  verifier: AssertionVerifier,
  expected: { readonly audience: string; readonly nowSeconds: number },
): Promise<VerifiedAssertion> {
  if (token.length > MaxAssertionBytes) throw new AssertionError("malformed");
  const parts = token.split(".");
  if (parts.length !== 3) throw new AssertionError("malformed");
  const [headerSegment, payloadSegment, signatureSegment] = parts as [string, string, string];
  const header = parseSegment(headerSegment);
  if (header["alg"] !== AssertionAlgorithm) throw new AssertionError("unsupported_algorithm");
  const kid = header["kid"];
  const key = typeof kid === "string" ? verifier.keys.get(kid) : undefined;
  if (key === undefined) throw new AssertionError("unknown_key");
  const signature = decodeBase64Url(signatureSegment);
  if (signature === null || signature.length !== 64) throw new AssertionError("bad_signature");
  const signed = new TextEncoder().encode(`${headerSegment}.${payloadSegment}`);
  if (!(await crypto.subtle.verify(ecdsa, key, Uint8Array.from(signature), signed))) throw new AssertionError("bad_signature");

  const claims = parseSegment(payloadSegment);
  if (claims["iss"] !== verifier.issuer) throw new AssertionError("wrong_issuer");
  if (claims["aud"] !== expected.audience) throw new AssertionError("wrong_audience");
  const iat = integerClaim(claims, "iat");
  const nbf = integerClaim(claims, "nbf");
  const exp = integerClaim(claims, "exp");
  const authTime = integerClaim(claims, "auth_time");
  if (exp <= iat || exp - iat > AssertionMaxLifetimeSeconds) throw new AssertionError("bad_claims");
  if (expected.nowSeconds > exp + AssertionLeewaySeconds) throw new AssertionError("expired");
  if (nbf > expected.nowSeconds + AssertionLeewaySeconds || iat > expected.nowSeconds + AssertionLeewaySeconds) throw new AssertionError("not_yet_valid");
  if (authTime > expected.nowSeconds + AssertionLeewaySeconds) throw new AssertionError("not_yet_valid");
  const subject = claims["sub"];
  const email = claims["email"] ?? null;
  const nonce = claims["nonce"];
  if (typeof subject !== "string" || !validSubject(subject)) throw new AssertionError("bad_claims");
  if (email !== null && (typeof email !== "string" || !validEmail(email))) throw new AssertionError("bad_claims");
  if (typeof nonce !== "string" || !nonceShape.test(nonce)) throw new AssertionError("bad_claims");
  if (!validIssuer(verifier.issuer)) throw new AssertionError("wrong_issuer");
  return { principal: { issuer: verifier.issuer, subject, email }, authTime, nonce };
}
