import { BlobPageSize, type BlobObject, type BlobPage, type BlobStore } from "../media/blob.ts";
import { contentTypeOf, parseMediaKey } from "../media/format.ts";

export interface R2ObjectBodyLike {
  arrayBuffer(): Promise<ArrayBuffer>;
}

export interface R2BucketLike {
  put(key: string, value: Uint8Array, options: { readonly httpMetadata: { readonly contentType: string } }): Promise<unknown>;
  get(key: string): Promise<R2ObjectBodyLike | null>;
  delete(key: string): Promise<void>;
  list(options: { readonly prefix: string; readonly cursor?: string; readonly limit: number }): Promise<{
    readonly objects: readonly { readonly key: string }[];
    readonly truncated: boolean;
    readonly cursor?: string;
  }>;
}

function addressOf(key: string): NonNullable<ReturnType<typeof parseMediaKey>> {
  const address = parseMediaKey(key);
  if (address === null) throw new Error(`media: ${JSON.stringify(key)} is not a media key`);
  return address;
}

/**
 * Media in the tenant's private R2 bucket (the `MEDIA` binding). The content
 * type is derived from the key on read, so what a key serves cannot depend on
 * object metadata.
 */
export function r2BlobStore(bucket: R2BucketLike): BlobStore {
  return {
    async put(key, bytes, contentType) {
      if (contentType !== contentTypeOf(addressOf(key).kind)) throw new Error(`media: ${contentType} does not match ${key}`);
      await bucket.put(key, bytes, { httpMetadata: { contentType } });
    },
    async get(key): Promise<BlobObject | null> {
      const address = addressOf(key);
      const object = await bucket.get(key);
      return object === null ? null : { bytes: new Uint8Array(await object.arrayBuffer()), contentType: contentTypeOf(address.kind) };
    },
    async delete(key) {
      addressOf(key);
      await bucket.delete(key);
    },
    async list(prefix, cursor): Promise<BlobPage> {
      if (prefix !== "m/") throw new Error("media: only the m/ prefix is listed");
      const page = await bucket.list({ prefix, limit: BlobPageSize, ...(cursor === null ? {} : { cursor }) });
      return { keys: page.objects.map((object) => object.key), next: page.truncated ? (page.cursor ?? null) : null };
    },
  };
}
