import { ConnectEventError, decodeEvent, type StripeEvent } from "./objects.ts";

export const WebhookToleranceSeconds = 300;

export type WebhookRejection =
  | "missing_signature_header"
  | "malformed_signature_header"
  | "no_v1_signature"
  | "timestamp_outside_tolerance"
  | "signature_mismatch"
  | "malformed_event"
  | "livemode_mismatch"
  | "connect_event";

export type WebhookVerification =
  | { readonly ok: true; readonly event: StripeEvent }
  | { readonly ok: false; readonly reason: WebhookRejection };

export interface WebhookInput {
  readonly rawBody: Uint8Array;
  readonly signatureHeader: string | null;
  readonly secrets: readonly string[];
  readonly nowSeconds: number;
  readonly expectLivemode: boolean;
  readonly toleranceSeconds?: number;
}

const encoder = new TextEncoder();
const decoder = new TextDecoder("utf-8", { fatal: true });

interface ParsedHeader {
  readonly timestamp: number;
  readonly signatures: readonly Uint8Array<ArrayBuffer>[];
}

function hexToBytes(hex: string): Uint8Array<ArrayBuffer> | null {
  if (hex.length === 0 || hex.length % 2 !== 0 || !/^[0-9a-fA-F]+$/.test(hex)) return null;
  const out = new Uint8Array(hex.length / 2);
  for (let index = 0; index < out.length; index += 1) out[index] = Number.parseInt(hex.slice(index * 2, index * 2 + 2), 16);
  return out;
}

function bytesToHex(bytes: Uint8Array): string {
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function parseHeader(header: string): ParsedHeader | "malformed" | "no_v1" {
  let timestamp: number | null = null;
  const signatures: Uint8Array<ArrayBuffer>[] = [];
  for (const part of header.split(",")) {
    const separator = part.indexOf("=");
    if (separator <= 0) return "malformed";
    const key = part.slice(0, separator).trim();
    const value = part.slice(separator + 1).trim();
    if (key === "t") {
      if (timestamp !== null || !/^[0-9]{1,15}$/.test(value)) return "malformed";
      timestamp = Number(value);
    } else if (key === "v1") {
      const bytes = hexToBytes(value);
      if (bytes !== null) signatures.push(bytes);
    }
  }
  if (timestamp === null) return "malformed";
  if (signatures.length === 0) return "no_v1";
  return { timestamp, signatures };
}

function signedPayload(timestamp: number, rawBody: Uint8Array): Uint8Array<ArrayBuffer> {
  const prefix = encoder.encode(`${timestamp}.`);
  const message = new Uint8Array(prefix.length + rawBody.length);
  message.set(prefix, 0);
  message.set(rawBody, prefix.length);
  return message;
}

async function hmacKey(secret: string): Promise<CryptoKey> {
  return await crypto.subtle.importKey("raw", encoder.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
}

export async function signWebhook(rawBody: Uint8Array, secret: string, timestamp: number): Promise<string> {
  const mac = await crypto.subtle.sign("HMAC", await hmacKey(secret), signedPayload(timestamp, rawBody));
  return `t=${timestamp},v1=${bytesToHex(new Uint8Array(mac))}`;
}

async function matchesAnySecret(parsed: ParsedHeader, rawBody: Uint8Array, secrets: readonly string[]): Promise<boolean> {
  const message = signedPayload(parsed.timestamp, rawBody);
  let matched = false;
  for (const secret of secrets) {
    const key = await hmacKey(secret);
    for (const signature of parsed.signatures) {
      if (await crypto.subtle.verify("HMAC", key, signature, message)) matched = true;
    }
  }
  return matched;
}

export async function verifyWebhook(input: WebhookInput): Promise<WebhookVerification> {
  if (input.signatureHeader === null || input.signatureHeader === "") return { ok: false, reason: "missing_signature_header" };
  const parsed = parseHeader(input.signatureHeader);
  if (parsed === "malformed") return { ok: false, reason: "malformed_signature_header" };
  if (parsed === "no_v1") return { ok: false, reason: "no_v1_signature" };
  if (!(await matchesAnySecret(parsed, input.rawBody, input.secrets))) return { ok: false, reason: "signature_mismatch" };
  const tolerance = input.toleranceSeconds ?? WebhookToleranceSeconds;
  if (Math.abs(input.nowSeconds - parsed.timestamp) > tolerance) return { ok: false, reason: "timestamp_outside_tolerance" };
  let event: StripeEvent;
  try {
    event = decodeEvent(JSON.parse(decoder.decode(input.rawBody)));
  } catch (error) {
    return { ok: false, reason: error instanceof ConnectEventError ? "connect_event" : "malformed_event" };
  }
  if (event.livemode !== input.expectLivemode) return { ok: false, reason: "livemode_mismatch" };
  return { ok: true, event };
}
