import { Schema } from "effect";
import { CatalogVersion, IDSchema, MoneySchema, isNonblank } from "./scalars.ts";

const Nonblank = Schema.String.check(Schema.makeFilter<string>((value) => isNonblank(value) || "must not be blank"));
const Integer = Schema.Number.check(Schema.makeFilter<number>((value) => Number.isSafeInteger(value) || "must be a safe integer"));
export const StatusSchema = Schema.Literals(["draft", "active", "archived"]);
export type Status = typeof StatusSchema.Type;
export const StoreSchema = Schema.Struct({ name: Nonblank, currencyCode: Nonblank, currencyExponent: Integer });
export const DetailSchema = Schema.Struct({ key: Nonblank, title: Nonblank, body: Nonblank });
export const OptionValueSchema = Schema.Struct({ id: IDSchema, value: Nonblank });
export const OptionSchema = Schema.Struct({ id: IDSchema, name: Nonblank, values: Schema.Array(OptionValueSchema) });
export const SelectionSchema = Schema.Struct({ optionId: IDSchema, valueId: IDSchema });
export const VariantSchema = Schema.Struct({ id: IDSchema, title: Schema.NullOr(Nonblank), priceMinor: MoneySchema, available: Schema.Boolean, selections: Schema.Array(SelectionSchema) });
export const ImageSchema = Schema.Struct({ id: IDSchema, url: Schema.String, altText: Schema.String, width: Schema.NullOr(Integer), height: Schema.NullOr(Integer) });
export const ProductSchema = Schema.Struct({
  id: IDSchema, handle: Nonblank, title: Nonblank, vendor: Schema.NullOr(Nonblank), description: Schema.String, status: StatusSchema,
  details: Schema.Array(DetailSchema), options: Schema.Array(OptionSchema), variants: Schema.Array(VariantSchema), images: Schema.Array(ImageSchema),
});
export const CollectionSchema = Schema.Struct({ id: IDSchema, handle: Nonblank, title: Nonblank, description: Schema.String, status: StatusSchema, products: Schema.Array(IDSchema) });
/** Array order supplies persistence positions; nullable fields are always present. */
export const CatalogSchema = Schema.Struct({ version: Schema.Literal(CatalogVersion), store: StoreSchema, products: Schema.Array(ProductSchema), collections: Schema.Array(CollectionSchema) });
export type Catalog = typeof CatalogSchema.Type;
export type Store = typeof StoreSchema.Type;
export type Product = typeof ProductSchema.Type;
export type Detail = typeof DetailSchema.Type;
export type Option = typeof OptionSchema.Type;
export type OptionValue = typeof OptionValueSchema.Type;
export type Selection = typeof SelectionSchema.Type;
export type Variant = typeof VariantSchema.Type;
export type Image = typeof ImageSchema.Type;
export type Collection = typeof CollectionSchema.Type;
