import { StripeConfigError } from "./errors.ts";
import { StripeMaxAmountMinor } from "./version.ts";

export type FormValue = string | bigint | number | boolean | FormObject | readonly FormValue[];
export interface FormObject { readonly [key: string]: FormValue }

function scalar(value: string | bigint | number | boolean, key: string): string {
  if (typeof value === "string") return value;
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "bigint") {
    if (value < 0n || value > StripeMaxAmountMinor) throw new StripeConfigError(`amount at ${key} outside 0..${StripeMaxAmountMinor}`);
    return value.toString();
  }
  if (!Number.isSafeInteger(value)) throw new StripeConfigError(`non-integer number at ${key}`);
  return String(value);
}

function flatten(value: FormValue, key: string, out: [string, string][]): void {
  if (Array.isArray(value)) {
    value.forEach((item, index) => flatten(item as FormValue, `${key}[${index}]`, out));
  } else if (typeof value === "object") {
    for (const [name, entry] of Object.entries(value as FormObject)) {
      if (entry === undefined) throw new StripeConfigError(`undefined value at ${key}[${name}]`);
      flatten(entry, `${key}[${name}]`, out);
    }
  } else {
    out.push([key, scalar(value, key)]);
  }
}

export function encodeForm(params: FormObject): string {
  const pairs: [string, string][] = [];
  for (const [name, entry] of Object.entries(params)) {
    if (entry === undefined) throw new StripeConfigError(`undefined value at ${name}`);
    flatten(entry, name, pairs);
  }
  return new URLSearchParams(pairs).toString();
}
