import { FulfillmentStatuses, type FulfillmentStatus } from "../commerce/fulfillment.ts";
import { validCarrier, validTrackingNumber, validTrackingUrl, type ShipmentRejection } from "../commerce/fulfillment_ship.ts";
import { PaymentStates, type PaymentState } from "../commerce/payment.ts";
import { principalId } from "../identity/principal.ts";
import { reauthRequired } from "../identity/policy.ts";
import { adminPath } from "../routes/admin.ts";
import { newToken, parseToken, tokenDigest } from "../session/session.ts";
import { BadInput } from "../web/decode.ts";
import type { AdminBackend } from "./backend.ts";
import { readCatalogForm, type FormValues } from "./catalog_form.ts";
import { digestHex, type AdminSessionView } from "./operations.ts";
import { MaxOrderNoteLength, MaxOrderSearchEmailLength, type OrderListFilter } from "./orders_operations.ts";
import {
  orderPage, ordersListPage, packingSlipPage, shipInputFor, type OrderFilterInput, type ShipInput,
} from "./orders_pages.ts";
import { accessPurpose, emailPurpose } from "./emails_pages.ts";
import { messagePage, type FieldErrors, type Notice } from "./pages.ts";
import { ActionDoneNotices, changed, createRefundsHandler, error, spent, unverified, type ActionShown } from "./refunds_handler.ts";
import { actionPurpose, OrderActions, type ActionInput, type OrderAction } from "./refunds_pages.ts";
import { page, redirect } from "./response.ts";

export interface OrdersAuth {
  readonly session: AdminSessionView;
  readonly digest: string;
  readonly label: string;
}

export interface OrdersHandlerOptions {
  readonly backend: AdminBackend;
  readonly tenantId: string;
  readonly nowSeconds: () => number;
  readonly clearCookies: () => readonly string[];
}

export interface OrdersHandler {
  handle(name: string, params: ReadonlyMap<string, string>, request: Request, auth: OrdersAuth, signal: AbortSignal): Promise<Response | null>;
}

const numberShape = /^[1-9][0-9]{0,18}$/;
const quantityShape = /^(?:0|[1-9][0-9]{0,9})$/;
const dateShape = /^\d{4}-\d{2}-\d{2}$/;
const MaxInt64 = 9223372036854775807n;
const SecondsPerDay = 86_400;
const filterNames = ["number", "email", "from", "to", "payment", "fulfillment", "before"] as const;

function parseNumber(raw: string): bigint | null {
  if (!numberShape.test(raw)) return null;
  const value = BigInt(raw);
  return value > MaxInt64 ? null : value;
}

function dayStart(raw: string): number | null {
  if (!dateShape.test(raw)) return null;
  const milliseconds = Date.parse(`${raw}T00:00:00Z`);
  if (!Number.isFinite(milliseconds) || new Date(milliseconds).toISOString().slice(0, 10) !== raw) return null;
  return milliseconds / 1000;
}

function isPaymentState(value: string): value is PaymentState {
  return (PaymentStates as readonly string[]).includes(value);
}

function isFulfillmentStatus(value: string): value is FulfillmentStatus {
  return (FulfillmentStatuses as readonly string[]).includes(value);
}

function parseFilter(params: URLSearchParams): { readonly input: OrderFilterInput; readonly filter: OrderListFilter | null; readonly errors: FieldErrors; readonly before: bigint | null } {
  for (const name of params.keys()) if (!(filterNames as readonly string[]).includes(name)) throw new BadInput(`Unexpected parameter ${JSON.stringify(name)}.`);
  const read = (name: string): string => (params.getAll(name).length > 1 ? "" : params.get(name) ?? "").trim();
  const input: OrderFilterInput = { number: read("number"), email: read("email"), from: read("from"), to: read("to"), payment: read("payment"), fulfillment: read("fulfillment") };
  const rawBefore = read("before");
  const errors: Record<string, string> = {};
  const number = input.number === "" ? null : parseNumber(input.number);
  if (input.number !== "" && number === null) errors["number"] = "Enter an order number, digits only.";
  if (input.email.length > MaxOrderSearchEmailLength || (input.email !== "" && !input.email.includes("@"))) errors["email"] = "Enter the full email address the customer used.";
  const from = input.from === "" ? null : dayStart(input.from);
  if (input.from !== "" && from === null) errors["from"] = "Enter a date as YYYY-MM-DD.";
  const through = input.to === "" ? null : dayStart(input.to);
  if (input.to !== "" && through === null) errors["to"] = "Enter a date as YYYY-MM-DD.";
  if (input.payment !== "" && !isPaymentState(input.payment)) errors["payment"] = "Choose one of the listed payment states.";
  if (input.fulfillment !== "" && !isFulfillmentStatus(input.fulfillment)) errors["fulfillment"] = "Choose one of the listed fulfillment states.";
  const before = rawBefore === "" ? null : parseNumber(rawBefore);
  if (rawBefore !== "" && before === null) throw new BadInput("The page marker is not valid.");
  if (Object.keys(errors).length > 0) return { input, filter: null, errors, before };
  return {
    input,
    errors,
    before,
    filter: {
      number, before,
      placedFrom: from,
      placedBefore: through === null ? null : through + SecondsPerDay,
      paymentState: input.payment === "" ? null : (input.payment as PaymentState),
      fulfillmentStatus: input.fulfillment === "" ? null : (input.fulfillment as FulfillmentStatus),
      email: input.email === "" ? null : input.email,
    },
  };
}

const shipPurpose = (number: bigint): string => `order.ship:${number}`;
const notePurpose = (number: bigint): string => `order.note:${number}`;


const rejectionMessages: Readonly<Record<ShipmentRejection, string>> = {
  payment_not_captured: "This order cannot ship until its payment is captured.",
  review_open: "This order cannot ship while a Radar review is open.",
  empty_shipment: "Enter a quantity to send for at least one item.",
  too_many_lines: "That shipment has too many lines.",
  invalid_carrier: "Enter the carrier name, up to 60 characters.",
  invalid_tracking_number: "Use letters, digits, spaces, and . _ / : # - only, up to 100 characters.",
  invalid_tracking_url: "Enter a full https:// or http:// link without a username or password.",
  unknown_line: "That item is not on this order.",
  duplicate_line: "An item appeared twice in the form.",
  invalid_quantity: "Enter a whole number of at least 1 for the items you are sending.",
  exceeds_unfulfilled: "A quantity is more than is left to send.",
};

export function createOrdersHandler(options: OrdersHandlerOptions): OrdersHandler {
  const { backend } = options;
  const notFound = (request: Request, auth: OrdersAuth): Response => page(request, 404, messagePage("Not found", "That order does not exist.", auth.label));

  async function listing(request: Request, auth: OrdersAuth, signal: AbortSignal): Promise<Response> {
    const parsed = parseFilter(new URL(request.url).searchParams);
    if (parsed.filter === null) {
      return page(request, 422, ordersListPage({ principalLabel: auth.label, input: parsed.input, errors: parsed.errors, rows: [], next: null, filter: null }));
    }
    const result = await backend.query({ kind: "order.list", filter: parsed.filter }, signal);
    return page(request, 200, ordersListPage({ principalLabel: auth.label, input: parsed.input, errors: {}, rows: result.rows, next: result.next, filter: parsed.filter }));
  }

  interface Shown {
    readonly status: number;
    readonly notice: Notice | null;
    readonly errors: FieldErrors;
    readonly conflict: boolean;
    readonly ship: ShipInput | null;
    readonly note: string;
    readonly actions: Readonly<Partial<Record<OrderAction, ActionInput>>>;
  }

  async function draw(request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal, shown: Shown): Promise<Response> {
    const shipToken = newToken();
    const noteToken = newToken();
    const emailToken = newToken();
    const accessToken = newToken();
    const actionTokens = Object.fromEntries(OrderActions.map((action) => [action, newToken()])) as Record<OrderAction, string>;
    const result = await backend.command({
      kind: "order.form", sessionDigest: auth.digest, number, nowSeconds: options.nowSeconds(),
      tokens: [
        { tokenDigest: digestHex(await tokenDigest(shipToken)), purpose: shipPurpose(number) },
        { tokenDigest: digestHex(await tokenDigest(noteToken)), purpose: notePurpose(number) },
        { tokenDigest: digestHex(await tokenDigest(emailToken)), purpose: emailPurpose(number) },
        { tokenDigest: digestHex(await tokenDigest(accessToken)), purpose: accessPurpose(number) },
        ...await Promise.all(OrderActions.map(async (action) => ({ tokenDigest: digestHex(await tokenDigest(actionTokens[action])), purpose: actionPurpose(action, number) }))),
      ],
    }, signal);
    if (!result.issued) return redirect(adminPath("admin-home"), options.clearCookies());
    if (result.view === null) return notFound(request, auth);
    return page(request, shown.status, orderPage({
      view: result.view, principalLabel: auth.label, shipToken, noteToken, emailToken, accessToken, nowSeconds: BigInt(options.nowSeconds()), ship: shown.ship ?? shipInputFor(result.view), noteInput: shown.note,
      actionTokens, actionInputs: shown.actions, needsReauth: reauthRequired(auth.session.authenticatedAt, options.nowSeconds()),
      errors: shown.errors, notice: shown.notice, conflict: shown.conflict,
    }));
  }

  const plain = (status: number, notice: Notice | null, extra: Partial<Shown> = {}): Shown => ({ status, notice, errors: {}, conflict: false, ship: null, note: "", actions: {}, ...extra });

  async function show(request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> {
    const query = new URL(request.url).searchParams;
    const done = ActionDoneNotices[query.get("done") ?? ""];
    const notice: Notice | null = query.get("shipped") === "1" ? { kind: "info", message: "Shipment recorded." } : query.get("noted") === "1" ? { kind: "info", message: "Note added." } : done === undefined ? null : { kind: "info", message: done };
    return await draw(request, auth, number, signal, plain(200, notice));
  }

  async function slip(request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> {
    const { view } = await backend.query({ kind: "order.detail", number }, signal);
    if (view === null) return notFound(request, auth);
    const raw = new URL(request.url).searchParams.get("shipment");
    const sequence = raw === null ? null : parseNumber(raw);
    if (raw !== null && (sequence === null || !view.shipments.some((shipment) => shipment.sequence === sequence))) return notFound(request, auth);
    return page(request, 200, packingSlipPage(view, sequence));
  }

  function integer(fields: FormValues, name: string, what: string): bigint {
    const raw = fields.get(name) ?? "";
    if (!/^(?:0|[1-9][0-9]{0,18})$/.test(raw) || BigInt(raw) > MaxInt64) throw new BadInput(`The form is missing its ${what}.`);
    return BigInt(raw);
  }

  async function ship(request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => ["form_token", "revision", "carrier", "tracking_number", "tracking_url"].includes(key) || /^qty_[0-9]{1,6}$/.test(key), signal);
    const quantities = new Map([...fields].filter(([key]) => key.startsWith("qty_")).map(([key, value]) => [key, value.trim()] as const));
    const input: ShipInput = { quantities, carrier: (fields.get("carrier") ?? "").trim(), trackingNumber: (fields.get("tracking_number") ?? "").trim(), trackingUrl: (fields.get("tracking_url") ?? "").trim() };
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, number, signal, plain(409, unverified, { ship: input, conflict: true }));
    const expectedRevision = integer(fields, "revision", "revision");

    const errors: Record<string, string> = {};
    const lines: { position: bigint; quantity: bigint }[] = [];
    for (const [key, raw] of quantities) {
      if (raw !== "" && !quantityShape.test(raw)) { errors[key] = "Enter a whole number, zero or more."; continue; }
      const quantity = raw === "" ? 0n : BigInt(raw);
      if (quantity > 0n) lines.push({ position: BigInt(key.slice(4)), quantity });
    }
    if (!validCarrier(input.carrier)) errors["carrier"] = rejectionMessages.invalid_carrier;
    if (input.trackingNumber !== "" && !validTrackingNumber(input.trackingNumber)) errors["tracking_number"] = rejectionMessages.invalid_tracking_number;
    if (input.trackingUrl !== "" && !validTrackingUrl(input.trackingUrl)) errors["tracking_url"] = rejectionMessages.invalid_tracking_url;
    if (Object.keys(errors).length === 0 && lines.length === 0) errors["quantities"] = rejectionMessages.empty_shipment;
    if (Object.keys(errors).length > 0) return await draw(request, auth, number, signal, plain(422, error("Fix the highlighted fields and submit again."), { errors, ship: input }));

    const outcome = await backend.command({
      kind: "order.ship", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: shipPurpose(number), actor: principalId(auth.session),
      nowSeconds: options.nowSeconds(), number, expectedRevision, lines, carrier: input.carrier,
      trackingNumber: input.trackingNumber === "" ? null : input.trackingNumber, trackingUrl: input.trackingUrl === "" ? null : input.trackingUrl,
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${adminPath("admin-order", [number.toString()])}?shipped=1`);
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "not_found": return notFound(request, auth);
      case "token_invalid": return await draw(request, auth, number, signal, plain(409, spent, { ship: input, conflict: true }));
      case "stale": return await draw(request, auth, number, signal, plain(409, changed, { ship: input, conflict: true }));
      case "rejected": {
        const field = outcome.rejection === "invalid_carrier" ? "carrier" : outcome.rejection === "invalid_tracking_number" ? "tracking_number" : outcome.rejection === "invalid_tracking_url" ? "tracking_url" : "quantities";
        const blocked = outcome.rejection === "payment_not_captured" || outcome.rejection === "review_open";
        return await draw(request, auth, number, signal, plain(blocked ? 409 : 422, error(rejectionMessages[outcome.rejection]), { errors: blocked ? {} : { [field]: rejectionMessages[outcome.rejection] }, ship: input }));
      }
    }
  }

  async function note(request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => key === "form_token" || key === "note", signal);
    const body = (fields.get("note") ?? "").trim();
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, number, signal, plain(409, unverified, { note: body }));
    if (body === "" || body.length > MaxOrderNoteLength) {
      return await draw(request, auth, number, signal, plain(422, error("Fix the highlighted fields and submit again."), { errors: { note: `Enter a note of 1 to ${MaxOrderNoteLength} characters.` }, note: body }));
    }
    const outcome = await backend.command({
      kind: "order.note", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: notePurpose(number), actor: principalId(auth.session),
      nowSeconds: options.nowSeconds(), number, body,
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${adminPath("admin-order", [number.toString()])}?noted=1`);
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "not_found": return notFound(request, auth);
      case "token_invalid": return await draw(request, auth, number, signal, plain(409, spent, { note: body }));
      case "invalid_note": return await draw(request, auth, number, signal, plain(422, error("Fix the highlighted fields and submit again."), { errors: { note: `Enter a note of 1 to ${MaxOrderNoteLength} characters.` }, note: body }));
    }
  }

  async function resend(request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => key === "form_token" || key === "message", signal);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, number, signal, plain(409, unverified));
    const messageId = integer(fields, "message", "message");
    const outcome = await backend.command({
      kind: "email.resend", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: emailPurpose(number), actor: principalId(auth.session),
      nowSeconds: options.nowSeconds(), number, messageId,
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${adminPath("admin-order", [number.toString()])}?done=email-resent`);
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "not_found": return notFound(request, auth);
      case "token_invalid": return await draw(request, auth, number, signal, plain(409, spent));
      case "not_resendable": return await draw(request, auth, number, signal, plain(409, error("That email cannot be resent right now. Its state changed, so nothing was sent.")));
    }
  }

  async function revokeAccess(request: Request, auth: OrdersAuth, number: bigint, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => key === "form_token", signal);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, number, signal, plain(409, unverified));
    const outcome = await backend.command({
      kind: "order.access_revoke", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: accessPurpose(number), actor: principalId(auth.session),
      nowSeconds: options.nowSeconds(), number,
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${adminPath("admin-order", [number.toString()])}?done=access-revoked`);
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "not_found": return notFound(request, auth);
      case "token_invalid": return await draw(request, auth, number, signal, plain(409, spent));
    }
  }

  const actions = createRefundsHandler({
    backend, tenantId: options.tenantId, nowSeconds: options.nowSeconds, clearCookies: options.clearCookies, notFound,
    redraw: (request, auth, number, signal, shown: ActionShown) => draw(request, auth, number, signal, plain(shown.status, shown.notice, { errors: shown.errors, conflict: shown.conflict, actions: shown.inputs })),
  });

  return {
    async handle(name, params, request, auth, signal) {
      if (name === "admin-orders") return await listing(request, auth, signal);
      if (!name.startsWith("admin-order")) return null;
      const number = parseNumber(params.get("number") ?? "");
      if (number === null) return notFound(request, auth);
      switch (name) {
        case "admin-order": return await show(request, auth, number, signal);
        case "admin-order-ship": return await ship(request, auth, number, signal);
        case "admin-order-note": return await note(request, auth, number, signal);
        case "admin-order-slip": return await slip(request, auth, number, signal);
        case "admin-order-email": return await resend(request, auth, number, signal);
        case "admin-order-access-revoke": return await revokeAccess(request, auth, number, signal);
        case "admin-order-refund": return await actions.submit("refund", request, auth, number, signal);
        case "admin-order-cancel": return await actions.submit("cancel", request, auth, number, signal);
        case "admin-order-return": return await actions.submit("return", request, auth, number, signal);
        case "admin-order-restock": return await actions.submit("restock", request, auth, number, signal);
        default: return null;
      }
    },
  };
}
