export const MaxJSONDepth = 128;

/** Parses operator JSON without losing duplicate keys or numeric spellings. */
export function parseStrictJSON(input: string | Uint8Array, options: { integersOnly?: boolean } = {}): unknown {
  let text: string;
  try { text = typeof input === "string" ? input : new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(input); }
  catch { throw new Error("strictjson: invalid UTF-8"); }
  let offset = 0;
  const fail = (message: string, path: string): never => {
    throw new Error(`strictjson: ${message} at ${path} (byte offset ${new TextEncoder().encode(text.slice(0, offset)).length})`);
  };
  const space = () => { while (/[\x20\t\r\n]/.test(text[offset] ?? "x")) offset++; };
  const string = (path: string): string => {
    const start = offset++;
    while (offset < text.length) {
      const char = text[offset++];
      if (char === "\\") { offset++; continue; }
      if (char === '"') {
        try {
          const decoded = JSON.parse(text.slice(start, offset)) as string;
          // JSON's isolated surrogate escapes decode as replacement characters.
          return decoded.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, "\uFFFD");
        }
        catch { fail("malformed JSON string", path); }
      }
    }
    return fail("unterminated string", path);
  };
  const value = (path: string, depth = 0): unknown => {
    // Operator documents have shallow schemas; bound recursion before the JS stack fails.
    if (depth > MaxJSONDepth) fail(`nesting exceeds limit ${MaxJSONDepth}`, path);
    space();
    const char = text[offset];
    if (char === '"') return string(path);
    if (char === "{") {
      offset++;
      const object: Record<string, unknown> = {};
      const keys = new Set<string>();
      space();
      if (text[offset] === "}") { offset++; return object; }
      while (true) {
        space();
        if (text[offset] !== '"') fail("expected object key", path);
        const key = string(path);
        if (keys.has(key)) fail(`duplicate key ${JSON.stringify(key)}`, path);
        keys.add(key);
        space();
        if (text[offset++] !== ":") fail("expected colon", path);
        // Define data properties explicitly so __proto__ remains a JSON key.
        Object.defineProperty(object, key, { value: value(`${path}.${key}`, depth + 1), enumerable: true, writable: true, configurable: true });
        space();
        const end = text[offset++];
        if (end === "}") return object;
        if (end !== ",") fail("expected comma or closing brace", path);
      }
    }
    if (char === "[") {
      offset++;
      const array: unknown[] = [];
      space();
      if (text[offset] === "]") { offset++; return array; }
      while (true) {
        array.push(value(`${path}[${array.length}]`, depth + 1));
        space();
        const end = text[offset++];
        if (end === "]") return array;
        if (end !== ",") fail("expected comma or closing bracket", path);
      }
    }
    for (const [token, result] of [["true", true], ["false", false], ["null", null]] as const) {
      if (text.startsWith(token, offset)) { offset += token.length; return result; }
    }
    const number = /^-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?/.exec(text.slice(offset))?.[0];
    if (number !== undefined) {
      offset += number.length;
      if (options.integersOnly && !/^-?(?:0|[1-9][0-9]*)$/.test(number)) fail("must be an integer", path);
      const result = Number(number);
      if (options.integersOnly && !Number.isSafeInteger(result)) fail("integer outside safe range", path);
      return result;
    }
    return fail("malformed JSON value", path);
  };
  const result = value("$");
  space();
  if (offset !== text.length) fail("trailing document after first JSON value", "$");
  return result;
}

