import type { SqlStorage, SqlStorageValue } from "cloudflare:workers";
import { DatabaseError, type SQLRow, type SQLValue, type SyncTransaction } from "../storefront/persistence.ts";

function normalizeBinding(value: SQLValue): null | string | Uint8Array {
  if (value === null || typeof value === "string") return value;
  if (value instanceof Uint8Array) return value;
  throw new DatabaseError(`cloudflare sql: invalid bound parameter type ${typeof value}`);
}

function normalizeCell(value: unknown): SQLValue {
  if (value === null || typeof value === "string" || typeof value === "number" || typeof value === "bigint") return value;
  if (value instanceof Uint8Array) return value;
  if (value instanceof ArrayBuffer) return new Uint8Array(value);
  if (ArrayBuffer.isView(value)) return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  throw new DatabaseError("cloudflare sql: unsupported cell value");
}

function normalizeRow(raw: Readonly<Record<string, SqlStorageValue>>): SQLRow {
  const row: Record<string, SQLValue> = {};
  for (const [key, value] of Object.entries(raw)) {
    row[key] = normalizeCell(value);
  }
  return row;
}

function stripSqlComments(source: string): string {
  let out = "";
  let i = 0;
  while (i < source.length) {
    const c = source[i]!;
    if (c === "'" || c === '"' || c === "`" || c === "[") {
      const close = c === "[" ? "]" : c;
      const start = i;
      i++;
      while (i < source.length) {
        const next = source[i++]!;
        if (next === close) {
          if (source[i] === close && close !== "]") {
            i++;
            continue;
          }
          break;
        }
      }
      out += source.slice(start, i);
      continue;
    }
    if (source.startsWith("--", i)) {
      const end = source.indexOf("\n", i);
      if (end < 0) break;
      i = end;
      continue;
    }
    if (source.startsWith("/*", i)) {
      const end = source.indexOf("*/", i + 2);
      if (end < 0) break;
      i = end + 2;
      continue;
    }
    out += c;
    i++;
  }
  return out.trim();
}

export class DurableObjectSqlAdapter implements SyncTransaction {
  statements = 0;
  rowsRead = 0;
  rowsWritten = 0;
  private readonly sql: SqlStorage;

  constructor(sql: SqlStorage) {
    this.sql = sql;
  }

  all(sql: string, params: readonly SQLValue[] = []): readonly SQLRow[] {
    const bindings = params.map(normalizeBinding);
    const cleaned = stripSqlComments(sql);
    try {
      const cursor = this.sql.exec(cleaned, ...bindings);
      const rawRows = cursor.toArray();
      this.statements++;
      this.rowsRead += cursor.rowsRead;
      this.rowsWritten += cursor.rowsWritten;
      return rawRows.map(normalizeRow);
    } catch (error) {
      if (error instanceof DatabaseError) throw error;
      throw new DatabaseError(error instanceof Error ? error.message : String(error), error);
    }
  }

  get(sql: string, params: readonly SQLValue[] = []): SQLRow | null {
    const rows = this.all(sql, params);
    return rows[0] ?? null;
  }

  run(sql: string, params: readonly SQLValue[] = []): { readonly changes: bigint; readonly lastInsertRowid: bigint } {
    const bindings = params.map(normalizeBinding);
    const cleaned = stripSqlComments(sql);
    try {
      const cursor = this.sql.exec(cleaned, ...bindings);
      cursor.toArray();
      this.statements++;
      this.rowsRead += cursor.rowsRead;
      this.rowsWritten += cursor.rowsWritten;
      return { changes: BigInt(cursor.rowsWritten), lastInsertRowid: 0n };
    } catch (error) {
      if (error instanceof DatabaseError) throw error;
      throw new DatabaseError(error instanceof Error ? error.message : String(error), error);
    }
  }

  script(sql: string): void {
    const cleaned = stripSqlComments(sql);
    if (cleaned === "") return;
    try {
      const cursor = this.sql.exec(cleaned);
      cursor.toArray();
      this.statements++;
      this.rowsRead += cursor.rowsRead;
      this.rowsWritten += cursor.rowsWritten;
    } catch (error) {
      if (error instanceof DatabaseError) throw error;
      throw new DatabaseError(error instanceof Error ? error.message : String(error), error);
    }
  }
}
