import { Effect, Schema } from "effect";
import { DatabaseError, type SQLBoundValue, type SQLValue, type SyncTransaction, type Transaction } from "../storefront/persistence.ts";
import { bindParam, inspectQuerySQL, Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const NullableInteger = Schema.NullOr(Integer);

const rowSchemas = {
  GetStockRead: Schema.Struct({ variant_id: Integer, on_hand: NullableInteger, held: NullableInteger, allocated: NullableInteger, revision: NullableInteger }),
  GetStockStateVersion: Schema.Struct({ version: Integer }),
  ListSoldOutVariants: Schema.Struct({ variant_id: Integer }),
  ListStockAdjustments: Schema.Struct({ id: Integer, variant_id: Integer, kind: Text, delta: Integer, on_hand_after: Integer, reason: Text, actor: Text, created_at: Integer }),
  ListAuditEvents: Schema.Struct({ id: Integer, actor: Text, action: Text, entity_kind: Text, entity_id: Text, entity_revision: NullableInteger, summary: Text, created_at: Integer }),
} as const;
export type CommerceRowQueryName = keyof typeof rowSchemas;
export type CommerceQueryRow<N extends CommerceRowQueryName> = typeof rowSchemas[N]["Type"];

const writeQueries = ["InsertInventoryLevel", "UpdateInventoryLevel", "InsertStockAdjustment", "InsertAuditEvent"] as const;
export type CommerceWriteQueryName = typeof writeQueries[number];
type CommerceQueryName = CommerceRowQueryName | CommerceWriteQueryName;

interface Definition { readonly sql: string; readonly parameters: number; }

export const CommerceQueryFiles = ["commerce.sql"] as const;

export class CommerceQueries {
  private readonly definitions: ReadonlyMap<CommerceQueryName, Definition>;
  constructor(definitions: ReadonlyMap<CommerceQueryName, Definition>) { this.definitions = definitions; }

  prepare(name: CommerceQueryName, params: readonly SQLValue[] = []): { readonly sql: string; readonly params: readonly SQLBoundValue[] } {
    const definition = this.definitions.get(name);
    if (definition === undefined || definition.parameters !== params.length) {
      throw new DatabaseError(`commerce queries: ${name} requires ${definition?.parameters ?? "unknown"} parameters, received ${params.length}`);
    }
    return { sql: definition.sql, params: params.map(bindParam) };
  }

  decodeRow<N extends CommerceRowQueryName>(name: N, input: unknown): CommerceQueryRow<N> {
    try {
      return Schema.decodeUnknownSync(rowSchemas[name], { onExcessProperty: "error" })(input) as CommerceQueryRow<N>;
    } catch (cause) {
      throw new DatabaseError(`commerce queries: invalid ${name} row`, cause);
    }
  }

  allSync<N extends CommerceRowQueryName>(tx: SyncTransaction, name: N, params: readonly SQLValue[] = []): readonly CommerceQueryRow<N>[] {
    const { sql, params: bound } = this.prepare(name, params);
    return tx.all(sql, bound).map((row) => this.decodeRow(name, row));
  }

  getSync<N extends CommerceRowQueryName>(tx: SyncTransaction, name: N, params: readonly SQLValue[] = []): CommerceQueryRow<N> | null {
    const { sql, params: bound } = this.prepare(name, params);
    const row = tx.get(sql, bound);
    return row === null ? null : this.decodeRow(name, row);
  }

  runSync(tx: SyncTransaction, name: CommerceWriteQueryName, params: readonly SQLValue[] = []): void {
    const { sql, params: bound } = this.prepare(name, params);
    tx.run(sql, bound);
  }

  private prepareEffect(name: CommerceQueryName, params: readonly SQLValue[]) {
    return Effect.try({ try: () => this.prepare(name, params), catch: (cause) => cause instanceof DatabaseError ? cause : new DatabaseError("commerce queries: parameter binding failed", cause) });
  }

  private decodeEffect<N extends CommerceRowQueryName>(name: N, input: unknown) {
    return Effect.try({ try: () => this.decodeRow(name, input), catch: (cause) => cause instanceof DatabaseError ? cause : new DatabaseError(`commerce queries: invalid ${name} row`, cause) });
  }

  all<N extends CommerceRowQueryName>(tx: Transaction, name: N, params: readonly SQLValue[] = []): Effect.Effect<readonly CommerceQueryRow<N>[], DatabaseError> {
    return Effect.flatMap(this.prepareEffect(name, params), ({ sql, params: bound }) => Effect.flatMap(tx.all(sql, bound), (rows) => Effect.forEach(rows, (row) => this.decodeEffect(name, row))));
  }

  get<N extends CommerceRowQueryName>(tx: Transaction, name: N, params: readonly SQLValue[] = []): Effect.Effect<CommerceQueryRow<N> | null, DatabaseError> {
    return Effect.flatMap(this.prepareEffect(name, params), ({ sql, params: bound }) => Effect.flatMap(tx.get(sql, bound), (row) => row === null ? Effect.succeed(null) : this.decodeEffect(name, row)));
  }

  run(tx: Transaction, name: CommerceWriteQueryName, params: readonly SQLValue[] = []): Effect.Effect<void, DatabaseError> {
    return Effect.flatMap(this.prepareEffect(name, params), ({ sql, params: bound }) => Effect.asVoid(tx.run(sql, bound)));
  }
}

export function buildCommerceQueries(sources: ReadonlyMap<string, string>): CommerceQueries {
  const known = new Set<string>([...Object.keys(rowSchemas), ...writeQueries]);
  const definitions = new Map<CommerceQueryName, Definition>();
  for (const file of CommerceQueryFiles) {
    const source = sources.get(file);
    if (source === undefined) throw new DatabaseError(`commerce queries: missing ${file}`);
    const markers = [...source.matchAll(/^-- name: ([A-Za-z][A-Za-z0-9]*) :(one|many|exec|execrows)\s*$/gm)];
    for (const [index, marker] of markers.entries()) {
      const name = marker[1] ?? "";
      if (!known.has(name) || definitions.has(name as CommerceQueryName)) throw new DatabaseError(`commerce queries: unknown or duplicate ${name}`);
      const raw = source.slice((marker.index ?? 0) + marker[0].length, markers[index + 1]?.index ?? source.length).trim();
      definitions.set(name as CommerceQueryName, { sql: raw, parameters: inspectQuerySQL(raw) });
    }
  }
  for (const name of known) if (!definitions.has(name as CommerceQueryName)) throw new DatabaseError(`commerce queries: missing ${name}`);
  return new CommerceQueries(definitions);
}
