import type { Mutation } from "../admin/guard.ts";
import { all, audit, get, run, stock, type Program } from "../admin/program.ts";
import type { AdminQueryRow } from "../admin/queries.ts";
import { decideCancel, type CancelRejection, type LinePlanRejection, type LineState, type PlannedLine, type QuantityRequest } from "./cancel.ts";
import { queueCancellation } from "./email_program.ts";
import { restockable } from "./fulfillment.ts";
import { lineFulfillmentOf } from "./fulfillment_program.ts";
import type { PaymentState } from "./payment.ts";
import { exception, scheduleCancel } from "./payment_program.ts";
import { validRefundReason } from "./refund.ts";
import { decideRestock, decideReturn, type RestockRejection } from "./refund_restock.ts";

type OrderRow = AdminQueryRow<"GetOrderDetail">;

export interface OrderChange {
  readonly number: bigint;
  readonly expectedRevision: bigint;
  readonly lines: readonly QuantityRequest[];
  readonly reason: string;
}

export interface OrderContext {
  readonly actor: string;
  readonly nowSeconds: bigint;
}

export type OrderRefusal<Rejection extends string> =
  | { readonly kind: "not_found" }
  | { readonly kind: "stale" }
  | { readonly kind: "rejected"; readonly rejection: Rejection };

export interface RecordedCancellation {
  readonly orderId: bigint;
  readonly orderNumber: bigint;
  readonly voided: boolean;
  readonly nowSeconds: bigint;
}

export function* afterCancellationRecorded(cancellation: RecordedCancellation): Program<void> {
  yield* queueCancellation(cancellation.orderId, cancellation.voided, cancellation.nowSeconds);
}

function* lineStates(order: OrderRow): Program<{ readonly lines: readonly LineState[]; readonly titles: ReadonlyMap<bigint, string> }> {
  const rows = yield* all("ListOrderLineStates", [order.id]);
  const reservations = yield* all("ListAttemptReservations", [order.attempt_id]);
  const tracked = new Set(reservations.filter((reservation) => reservation.tracked === 1n).map((reservation) => reservation.variant_id));
  return {
    lines: rows.map((row) => ({ position: row.position, variantId: row.variant_id, tracked: tracked.has(row.variant_id), fulfillment: lineFulfillmentOf(row) })),
    titles: new Map(rows.map((row) => [row.position, row.title])),
  };
}

function describe(lines: readonly PlannedLine[], titles: ReadonlyMap<bigint, string>): string {
  return lines.map((line) => `${line.quantity} x ${titles.get(line.position) ?? "item"}`).join(", ");
}

function* bump(order: OrderRow): Program<void> {
  if ((yield* run("BumpOrderRevision", [order.id, order.revision])) !== 1n) throw new Error(`orders: order ${order.number} changed during the update`);
}

export function* cancelEffect(change: OrderChange & { readonly tenantId: string }, context: OrderContext): Program<Mutation<{ readonly voided: boolean }, OrderRefusal<CancelRejection>>> {
  const refused = (refusal: OrderRefusal<CancelRejection>): Mutation<{ readonly voided: boolean }, OrderRefusal<CancelRejection>> => ({ applied: false, result: refusal });
  const order = yield* get("GetOrderDetail", [change.number]);
  if (order === null) return refused({ kind: "not_found" });
  if (order.revision !== change.expectedRevision) return refused({ kind: "stale" });
  if (!validRefundReason(change.reason)) return refused({ kind: "rejected", rejection: "invalid_reason" });
  const { lines, titles } = yield* lineStates(order);
  const decision = decideCancel({ paymentState: order.payment_state as PaymentState, lines }, change.lines);
  if (!decision.ok) return refused({ kind: "rejected", rejection: decision.rejection });
  const now = context.nowSeconds;

  const tracked = decision.lines.filter((line) => line.tracked);
  if (tracked.length > 0) {
    const released = yield* stock(tracked.map((line) => ({ kind: "cancel_allocation" as const, variantId: line.variantId, quantity: line.quantity })), { nowSeconds: now, actor: context.actor });
    if (released.outcome === "rejected") throw new Error(`orders: canceling order ${order.number} was rejected by inventory (${released.rejection})`);
  }
  for (const line of decision.lines) yield* run("AddLineCanceled", [line.quantity, order.id, line.position]);

  const voided = decision.payment === "void";
  const payment = yield* get("GetPaymentByIntent", [order.payment_intent_id]);
  if (payment === null) throw new Error(`orders: order ${order.number} has no payment`);
  if (voided) {
    if ((yield* run("SetPaymentState", ["void_unknown", 0n, null, now, payment.id, payment.state])) < 1n) throw new Error(`orders: the payment of order ${order.number} changed during cancellation`);
    yield* scheduleCancel(change.tenantId, order.payment_intent_id, payment.attempt_ref, now, "requested_by_customer");
  }
  const open = (yield* all("ListOrderExceptions", [order.id])).find((entry) => entry.kind === "payment_canceled" && entry.state === "open");
  if (open !== undefined) yield* exception(payment.attempt_id, order.id, "payment_canceled", open.provider_object_id, false, "the order was canceled", now);

  yield* bump(order);
  const outcome = voided ? "the authorization is being released" : "the payment was not changed";
  yield* audit({
    actor: context.actor, action: "order.cancel", entityKind: "order", entityId: order.id.toString(), entityRevision: order.revision + 1n,
    summary: `canceled ${describe(decision.lines, titles)}; ${outcome}: ${change.reason}`.slice(0, 1000),
  }, now);
  yield* afterCancellationRecorded({ orderId: order.id, orderNumber: order.number, voided, nowSeconds: now });
  return { applied: true, result: { voided } };
}

export function* returnEffect(change: OrderChange, context: OrderContext): Program<Mutation<null, OrderRefusal<LinePlanRejection>>> {
  const refused = (refusal: OrderRefusal<LinePlanRejection>): Mutation<null, OrderRefusal<LinePlanRejection>> => ({ applied: false, result: refusal });
  const order = yield* get("GetOrderDetail", [change.number]);
  if (order === null) return refused({ kind: "not_found" });
  if (order.revision !== change.expectedRevision) return refused({ kind: "stale" });
  if (!validRefundReason(change.reason)) return refused({ kind: "rejected", rejection: "invalid_reason" });
  const { lines, titles } = yield* lineStates(order);
  const decision = decideReturn(lines, change.lines);
  if (!decision.ok) return refused({ kind: "rejected", rejection: decision.rejection });
  for (const line of decision.lines) yield* run("AddLineReturned", [line.quantity, order.id, line.position]);
  yield* bump(order);
  yield* audit({
    actor: context.actor, action: "order.return", entityKind: "order", entityId: order.id.toString(), entityRevision: order.revision + 1n,
    summary: `returned ${describe(decision.lines, titles)}: ${change.reason}`.slice(0, 1000),
  }, context.nowSeconds);
  return { applied: true, result: null };
}

export function* restockEffect(change: OrderChange, context: OrderContext): Program<Mutation<null, OrderRefusal<LinePlanRejection | RestockRejection>>> {
  const refused = (refusal: OrderRefusal<LinePlanRejection | RestockRejection>): Mutation<null, OrderRefusal<LinePlanRejection | RestockRejection>> => ({ applied: false, result: refusal });
  const order = yield* get("GetOrderDetail", [change.number]);
  if (order === null) return refused({ kind: "not_found" });
  if (order.revision !== change.expectedRevision) return refused({ kind: "stale" });
  if (!validRefundReason(change.reason)) return refused({ kind: "rejected", rejection: "invalid_reason" });
  const { lines, titles } = yield* lineStates(order);
  const decision = decideRestock(lines, change.lines);
  if (!decision.ok) return refused({ kind: "rejected", rejection: decision.rejection });
  const now = context.nowSeconds;
  const restocked = yield* stock(
    decision.lines.map((line) => ({ kind: "restock" as const, variantId: line.variantId, quantity: line.quantity, restockable: restockable(line.before), reason: `Order ${order.number}: ${change.reason}`.slice(0, 500) })),
    { nowSeconds: now, actor: context.actor },
  );
  if (restocked.outcome === "rejected") throw new Error(`orders: restocking order ${order.number} was rejected by inventory (${restocked.rejection})`);
  for (const line of decision.lines) yield* run("InsertRestock", [order.id, line.position, line.quantity, change.reason, context.actor, now]);
  yield* bump(order);
  yield* audit({
    actor: context.actor, action: "order.restock", entityKind: "order", entityId: order.id.toString(), entityRevision: order.revision + 1n,
    summary: `restocked ${describe(decision.lines, titles)}: ${change.reason}`.slice(0, 1000),
  }, now);
  return { applied: true, result: null };
}
