import { MoneyRangeError, StripeMaxAmountMinor } from "./money.ts";
import type { ShippingPolicy } from "./policy.ts";

const stateCodes = [
  "AL", "AK", "AZ", "AR", "CA", "CO", "CT", "DE", "DC", "FL", "GA", "HI", "ID", "IL", "IN", "IA", "KS", "KY", "LA", "ME",
  "MD", "MA", "MI", "MN", "MS", "MO", "MT", "NE", "NV", "NH", "NJ", "NM", "NY", "NC", "ND", "OH", "OK", "OR", "PA", "RI",
  "SC", "SD", "TN", "TX", "UT", "VT", "VA", "WA", "WV", "WI", "WY",
] as const;

export const UsRegions: ReadonlySet<string> = new Set(stateCodes);

export const MaxAddressFieldLength = 100;

export interface ShippingAddress {
  readonly recipient: string;
  readonly line1: string;
  readonly line2: string | null;
  readonly city: string;
  readonly region: string;
  readonly postalCode: string;
  readonly country: string;
}

export type AddressField = "recipient" | "line1" | "line2" | "city" | "region" | "postalCode" | "country";
export type AddressProblem = { readonly field: AddressField; readonly problem: "required" | "too_long" | "unsupported" | "invalid_format" };

const postalCodePattern = /^\d{5}(-\d{4})?$/;

export function validateAddress(address: ShippingAddress): readonly AddressProblem[] {
  const problems: AddressProblem[] = [];
  const required: readonly [AddressField, string][] = [
    ["recipient", address.recipient], ["line1", address.line1], ["city", address.city],
    ["region", address.region], ["postalCode", address.postalCode], ["country", address.country],
  ];
  for (const [field, value] of required) {
    if (value.trim() === "") problems.push({ field, problem: "required" });
  }
  const bounded: readonly [AddressField, string][] = [...required, ["line2", address.line2 ?? ""]];
  for (const [field, value] of bounded) {
    if (value.length > MaxAddressFieldLength) problems.push({ field, problem: "too_long" });
  }
  if (address.country.trim() !== "" && address.country !== "US") problems.push({ field: "country", problem: "unsupported" });
  if (address.region.trim() !== "" && !UsRegions.has(address.region)) problems.push({ field: "region", problem: "unsupported" });
  if (address.postalCode.trim() !== "" && !postalCodePattern.test(address.postalCode)) problems.push({ field: "postalCode", problem: "invalid_format" });
  return problems;
}

export type ShippingPolicyProblem =
  | { readonly kind: "unknown_origin_region" }
  | { readonly kind: "unknown_region"; readonly region: string }
  | { readonly kind: "duplicate_region"; readonly region: string }
  | { readonly kind: "duplicate_zone"; readonly zone: string }
  | { readonly kind: "amount_out_of_range"; readonly zone: string | null };

function amountInRange(value: bigint): boolean {
  return value >= 0n && value <= StripeMaxAmountMinor;
}

export function validateShippingPolicy(policy: ShippingPolicy): readonly ShippingPolicyProblem[] {
  const problems: ShippingPolicyProblem[] = [];
  if (!UsRegions.has(policy.originRegion)) problems.push({ kind: "unknown_origin_region" });
  const regions = new Set<string>();
  const zones = new Set<string>();
  for (const zone of policy.zones) {
    if (zones.has(zone.name)) problems.push({ kind: "duplicate_zone", zone: zone.name });
    zones.add(zone.name);
    if (!amountInRange(zone.flatRateMinor)) problems.push({ kind: "amount_out_of_range", zone: zone.name });
    for (const region of zone.regions) {
      if (!UsRegions.has(region)) problems.push({ kind: "unknown_region", region });
      else if (regions.has(region)) problems.push({ kind: "duplicate_region", region });
      regions.add(region);
    }
  }
  if (policy.freeShippingThresholdMinor !== null && !amountInRange(policy.freeShippingThresholdMinor)) {
    problems.push({ kind: "amount_out_of_range", zone: null });
  }
  return problems;
}

export type Fulfillment =
  | { readonly kind: "ship"; readonly address: ShippingAddress }
  | { readonly kind: "pickup" };

export type ShippingService =
  | { readonly kind: "flat_rate"; readonly zone: string }
  | { readonly kind: "pickup" };

export interface ShippingCharge {
  readonly service: ShippingService;
  readonly amountMinor: bigint;
  readonly freeByThreshold: boolean;
  readonly taxRegion: string;
}

export type ShippingBlock =
  | { readonly reason: "address_invalid"; readonly problems: readonly AddressProblem[] }
  | { readonly reason: "destination_unsupported"; readonly region: string }
  | { readonly reason: "pickup_unavailable" };

export type ShippingResult =
  | { readonly ok: true; readonly charge: ShippingCharge }
  | { readonly ok: false; readonly block: ShippingBlock };

export function chargeShipping(policy: ShippingPolicy, fulfillment: Fulfillment, merchandiseMinor: bigint): ShippingResult {
  if (merchandiseMinor < 0n) throw new MoneyRangeError("merchandise subtotal outside non-negative signed int64");
  if (fulfillment.kind === "pickup") {
    if (!policy.localPickup) return { ok: false, block: { reason: "pickup_unavailable" } };
    return { ok: true, charge: { service: { kind: "pickup" }, amountMinor: 0n, freeByThreshold: false, taxRegion: policy.originRegion } };
  }
  const problems = validateAddress(fulfillment.address);
  if (problems.length > 0) return { ok: false, block: { reason: "address_invalid", problems } };
  const region = fulfillment.address.region;
  const zone = policy.zones.find((candidate) => candidate.regions.includes(region));
  if (zone === undefined) return { ok: false, block: { reason: "destination_unsupported", region } };
  const free = policy.freeShippingThresholdMinor !== null && merchandiseMinor >= policy.freeShippingThresholdMinor;
  return {
    ok: true,
    charge: { service: { kind: "flat_rate", zone: zone.name }, amountMinor: free ? 0n : zone.flatRateMinor, freeByThreshold: free, taxRegion: region },
  };
}
