export interface CatalogAuth {
  readonly session: AdminSessionView;
  readonly digest: string;
  readonly label: string;
}

export interface CatalogHandlerOptions {
  readonly backend: AdminBackend;
  readonly nowSeconds: () => number;
  readonly clearCookies: () => readonly string[];
  readonly blobs: BlobStore;
  readonly uploaderPath: string | null;
}

export interface CatalogHandler {
  handle(name: string, params: ReadonlyMap<string, string>, request: Request, auth: CatalogAuth, signal: AbortSignal): Promise<Response | null>;
}

const idShape = /^[1-9][0-9]{0,18}$/;
const MaxInt64 = 9223372036854775807n;
const knownKeys = new Set([
  "form_token", "revision", "action", "title", "handle", "vendor", "description", "price", "status", "variant_id", "option_id", "value_id",
  "name", "value", "available", "product_id", "image_id", "alt",
]);
const allowedKey = (key: string): boolean => knownKeys.has(key) || /^(?:option|select)_[0-9]+$/.test(key);
const reauthActions = new Set(["product.status", "collection.status", "products.status"]);

function parseId(raw: string | undefined): bigint | null {
  if (raw === undefined || !idShape.test(raw)) return null;
  const id = BigInt(raw);
  return id > MaxInt64 ? null : id;
}

function need(raw: string | undefined, what: string): bigint {
  const id = parseId(raw);
  if (id === null) throw new BadInput(`The form is missing its ${what}.`);
  return id;
}

function trimmed(fields: FormValues, name: string): string {
  return (fields.get(name) ?? "").trim();
}

function blankToNull(value: string): string | null {
  return value === "" ? null : value;
}

type Built =
  | { readonly ok: true; readonly form: string; readonly change: CatalogChange; readonly landing: "same" | "entity" | "count" }
  | { readonly ok: false; readonly form: string; readonly errors: FieldErrors; readonly message: string };

function invalid(form: string, errors: FieldErrors, message = "Fix the highlighted fields and submit again."): Built {
  return { ok: false, form, errors, message };
}

function productText(fields: FormValues, deriveHandle: boolean): { readonly title: string; readonly handle: string; readonly vendor: string | null; readonly description: string } {
  const title = trimmed(fields, "title");
  const handle = trimmed(fields, "handle");
  return { title, handle: handle === "" && deriveHandle ? slugify(title) : handle, vendor: blankToNull(trimmed(fields, "vendor")), description: fields.get("description") ?? "" };
}

function buildProductChange(fields: FormValues, productId: bigint): Built {
  const action = fields.get("action") ?? "";
  const revision = (): bigint => need(fields.get("revision"), "revision");
  switch (action) {
    case "product.update": {
      const text = productText(fields, false);
      const errors = checkProductText(text);
      return Object.keys(errors).length > 0 ? invalid("product", errors) : { ok: true, form: "product", landing: "same", change: { action, productId, expectedRevision: revision(), ...text } };
    }
    case "product.status": {
      const status = fields.get("status") ?? "";
      if (!isStatus(status)) throw new BadInput("The form is missing its status.");
      return { ok: true, form: "status", landing: "same", change: { action, productId, expectedRevision: revision(), status } };
    }
    case "product.duplicate": return { ok: true, form: "duplicate", landing: "entity", change: { action, productId } };
    case "variant.update":
    case "variant.remove": {
      const variantId = need(fields.get("variant_id"), "variant");
      const form = `variant:${variantId}`;
      if (action === "variant.remove") return { ok: true, form, landing: "same", change: { action, productId, expectedRevision: revision(), variantId } };
      const title = trimmed(fields, "title");
      const errors = title === "" ? {} : checkLabel(title, "title");
      return Object.keys(errors).length > 0
        ? invalid(form, errors)
        : { ok: true, form, landing: "same", change: { action, productId, expectedRevision: revision(), variantId, title: blankToNull(title), price: trimmed(fields, "price"), available: fields.get("available") === "on" } };
    }
    case "variant.add": {
      const title = trimmed(fields, "title");
      const errors = title === "" ? {} : checkLabel(title, "title");
      if (Object.keys(errors).length > 0) return invalid("variant-add", errors);
      const selections = [...fields].flatMap(([key, value]) => {
        const match = /^option_([0-9]+)$/.exec(key);
        const optionId = match === null ? null : parseId(match[1]);
        const valueId = parseId(value);
        return optionId === null || valueId === null ? [] : [{ optionId, valueId }];
      });
      return { ok: true, form: "variant-add", landing: "same", change: { action, productId, expectedRevision: revision(), title: blankToNull(title), price: trimmed(fields, "price"), available: fields.get("available") === "on", selections } };
    }
    case "option.add": {
      const name = trimmed(fields, "name");
      const value = trimmed(fields, "value");
      const errors = { ...checkLabel(name, "name"), ...checkLabel(value, "value") };
      return Object.keys(errors).length > 0 ? invalid("option-add", errors) : { ok: true, form: "option-add", landing: "same", change: { action, productId, expectedRevision: revision(), name, value } };
    }
    case "option.remove": return { ok: true, form: "option-remove", landing: "same", change: { action, productId, expectedRevision: revision(), optionId: need(fields.get("option_id"), "option") } };
    case "value.add": {
      const optionId = need(fields.get("option_id"), "option");
      const value = trimmed(fields, "value");
      const errors = checkLabel(value, "value");
      return Object.keys(errors).length > 0 ? invalid(`value-add:${optionId}`, errors) : { ok: true, form: `value-add:${optionId}`, landing: "same", change: { action, productId, expectedRevision: revision(), optionId, value } };
    }
    case "value.remove": return { ok: true, form: "value-remove", landing: "same", change: { action, productId, expectedRevision: revision(), valueId: need(fields.get("value_id"), "value") } };
    default: return buildImageChange(fields, productId, action, revision);
  }
}

function buildImageChange(fields: FormValues, productId: bigint, rawAction: string, revision: () => bigint): Built {
  const [action, direction] = rawAction.split(":") as [string, string | undefined];
  const imageId = (): bigint => need(fields.get("image_id"), "image");
  const form = `image:${fields.get("image_id") ?? ""}`;
  switch (action) {
    case "image.remove": return { ok: true, form, landing: "same", change: { action, productId, expectedRevision: revision(), imageId: imageId() } };
    case "image.alt": {
      const alt = trimmed(fields, "alt");
      return new TextEncoder().encode(alt).length > MaxLabelBytes
        ? invalid(form, { alt: `Use at most ${MaxLabelBytes} bytes.` })
        : { ok: true, form, landing: "same", change: { action, productId, expectedRevision: revision(), imageId: imageId(), alt } };
    }
    case "image.move": {
      if (direction !== "up" && direction !== "down") throw new BadInput("That action is not available.");
      return { ok: true, form, landing: "same", change: { action, productId, expectedRevision: revision(), imageId: imageId(), direction } };
    }
    default: throw new BadInput("That action is not available.");
  }
}

function buildCollectionChange(fields: FormValues, collectionId: bigint): Built {
  const rawAction = fields.get("action") ?? "";
  const revision = (): bigint => need(fields.get("revision"), "revision");
  const [action, direction] = rawAction.split(":") as [string, string | undefined];
  switch (action) {
    case "collection.update": {
      const text = productText(fields, false);
      const errors = checkCollectionText({ title: text.title, handle: text.handle, description: text.description });
      return Object.keys(errors).length > 0 ? invalid("collection", errors) : { ok: true, form: "collection", landing: "same", change: { action, collectionId, expectedRevision: revision(), title: text.title, handle: text.handle, description: text.description } };
    }
    case "collection.status": {
      const status = fields.get("status") ?? "";
      if (!isStatus(status)) throw new BadInput("The form is missing its status.");
      return { ok: true, form: "status", landing: "same", change: { action, collectionId, expectedRevision: revision(), status } };
    }
    case "collection.member_add": {
      const productId = parseId(trimmed(fields, "product_id"));
      return productId === null ? invalid("member-add", { product_id: "Enter the number of an existing product." }) : { ok: true, form: "member-add", landing: "same", change: { action, collectionId, expectedRevision: revision(), productId } };
    }
    case "collection.member_remove": return { ok: true, form: "member", landing: "same", change: { action, collectionId, expectedRevision: revision(), productId: need(fields.get("product_id"), "product") } };
    case "collection.member_move": {
      if (direction !== "up" && direction !== "down") throw new BadInput("That action is not available.");
      return { ok: true, form: "member", landing: "same", change: { action, collectionId, expectedRevision: revision(), productId: need(fields.get("product_id"), "product"), direction } };
    }
    default: throw new BadInput("That action is not available.");
  }
}

interface Screen {
  readonly purpose: string;
  readonly path: string;
  readonly query: CatalogQuery;
  render(result: CatalogQueryResult, base: CatalogPageBase): Html | null;
}

export function createCatalogHandler(options: CatalogHandlerOptions): CatalogHandler {
  const { backend } = options;
  const now = (): number => options.nowSeconds();

  const productsScreen = (after: bigint, status: "" | "draft" | "active" | "archived", saved: number | null): Screen => ({
    purpose: "catalog.products", path: adminPath("admin-products"), query: { kind: "catalog.products", after, status },
    render: (result, base) => result.kind === "catalog.products" ? productListPage({ ...base, view: result.view, status, saved }) : null,
  });
  const newProductScreen: Screen = {
    purpose: "catalog.product.new", path: adminPath("admin-product-new"), query: { kind: "catalog.new" },
    render: (result, base) => result.kind === "catalog.new" && result.currency !== null ? productNewPage({ ...base, currency: result.currency }) : null,
  };
  const productScreen = (id: bigint, saved: boolean): Screen => ({
    purpose: `catalog.product:${id}`, path: adminPath("admin-product", [id.toString()]), query: { kind: "catalog.product", productId: id },
    render: (result, base) => result.kind === "catalog.product" && result.view !== null ? productEditPage({ ...base, view: result.view, saved, uploaderPath: options.uploaderPath }) : null,
  });
  const collectionsScreen = (after: bigint): Screen => ({
    purpose: "catalog.collections", path: adminPath("admin-collections"), query: { kind: "catalog.collections", after },
    render: (result, base) => result.kind === "catalog.collections" ? collectionListPage({ ...base, view: result.view }) : null,
  });
  const newCollectionScreen: Screen = {
    purpose: "catalog.collection.new", path: adminPath("admin-collection-new"), query: { kind: "catalog.new" },
    render: (result, base) => result.kind === "catalog.new" ? collectionNewPage(base) : null,
  };
  const collectionScreen = (id: bigint, saved: boolean): Screen => ({
    purpose: `catalog.collection:${id}`, path: adminPath("admin-collection", [id.toString()]), query: { kind: "catalog.collection", collectionId: id },
    render: (result, base) => result.kind === "catalog.collection" && result.view !== null ? collectionEditPage({ ...base, view: result.view, saved }) : null,
  });

  const notFound = (request: Request, auth: CatalogAuth): Response => page(request, 404, messagePage("Not found", "That page does not exist.", auth.label));

  async function show(request: Request, auth: CatalogAuth, screen: Screen, signal: AbortSignal, shown: { readonly status?: number; readonly notice?: Notice | null; readonly echo?: Echo; readonly conflict?: boolean } = {}): Promise<Response> {
    const token = newToken();
    const issued = await backend.command({ kind: "page.form", tokenDigest: digestHex(await tokenDigest(token)), sessionDigest: auth.digest, purpose: screen.purpose, nowSeconds: now(), query: screen.query }, signal);
    const body = screen.render(issued.result, { principalLabel: auth.label, formToken: token, notice: shown.notice ?? null, echo: shown.echo ?? noEcho, conflict: shown.conflict ?? false });
    return body === null ? notFound(request, auth) : page(request, shown.status ?? 200, body);
  }

  async function showAgain(request: Request, auth: CatalogAuth, screen: Screen, signal: AbortSignal, token: string, shown: { readonly status: number; readonly notice: Notice; readonly echo: Echo; readonly conflict: boolean }): Promise<Response> {
    const result = await backend.query(screen.query, signal) as CatalogQueryResult;
    const body = screen.render(result, { principalLabel: auth.label, formToken: token, notice: shown.notice, echo: shown.echo, conflict: shown.conflict });
    return body === null ? notFound(request, auth) : page(request, shown.status, body);
  }

  async function submit(request: Request, auth: CatalogAuth, screen: Screen, signal: AbortSignal, fields: FormValues, built: Built, landing: (entityId: bigint) => string): Promise<Response> {
    const formToken = parseToken(fields.get("form_token") ?? "");
    const echo = (errors: FieldErrors): Echo => ({ form: built.form, input: fields, errors });
    const error = (message: string): Notice => ({ kind: "error", message });
    if (formToken === null) {
      return await show(request, auth, screen, signal, { status: 409, notice: error("This form could not be verified. Review the current values and submit again."), echo: echo({}), conflict: true });
    }
    if (!built.ok) return await showAgain(request, auth, screen, signal, formToken, { status: 422, notice: error(built.message), echo: echo(built.errors), conflict: false });
    if (reauthRequired(auth.session.authenticatedAt, now()) && (reauthActions.has(built.change.action))) {
      return redirect(`${adminPath("admin-reauth")}?return=${encodeURIComponent(screen.path)}`);
    }
    const outcome = await backend.command({
      kind: "catalog.mutate", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: screen.purpose,
      actor: principalId(auth.session), nowSeconds: now(), change: built.change,
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(landing(outcome.entityId));
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "token_invalid":
        return await show(request, auth, screen, signal, { status: 409, notice: error("This form was already submitted or has expired, so nothing was changed. Review the current values and submit again if needed."), echo: echo({}), conflict: true });
      case "stale":
        return await showAgain(request, auth, screen, signal, formToken, { status: 409, notice: error("This changed after you opened the form, so nothing was changed. Compare the values and submit again."), echo: echo({}), conflict: true });
      case "rejected": {
        const detail = describeCatalogRejection(outcome.rejection);
        return await showAgain(request, auth, screen, signal, formToken, { status: 422, notice: error(detail.message), echo: echo(detail.field === null ? {} : { [detail.field]: detail.message }), conflict: false });
      }
    }
  }

  const savedPath = (path: string) => (): string => `${path}?saved=1`;

  async function products(request: Request, auth: CatalogAuth, signal: AbortSignal): Promise<Response> {
    const url = new URL(request.url);
    const after = parseId(url.searchParams.get("after") ?? undefined) ?? 0n;
    const rawStatus = url.searchParams.get("status") ?? "";
    const status = isStatus(rawStatus) ? rawStatus : "";
    const saved = /^[0-9]{1,4}$/.test(url.searchParams.get("saved") ?? "") ? Number(url.searchParams.get("saved")) : null;
    return await show(request, auth, productsScreen(after, status, saved), signal);
  }

  async function bulk(request: Request, auth: CatalogAuth, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, allowedKey, signal);
    const screen = productsScreen(0n, "", null);
    const ids = [...fields.keys()].flatMap((key) => {
      const match = /^select_([0-9]+)$/.exec(key);
      const id = match === null ? null : parseId(match[1]);
      return id === null ? [] : [id];
    });
    const status = fields.get("status") ?? "";
    if (!isStatus(status)) throw new BadInput("The form is missing its status.");
    const built: Built = ids.length === 0 || ids.length > BulkRowLimit
      ? invalid("bulk", {}, `Select between 1 and ${BulkRowLimit} products.`)
      : { ok: true, form: "bulk", landing: "count", change: { action: "products.status", productIds: ids, status } };
    return await submit(request, auth, screen, signal, fields, built, (count) => `${screen.path}?saved=${count}`);
  }

  async function createProduct(request: Request, auth: CatalogAuth, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, allowedKey, signal);
    const text = productText(fields, true);
    const errors = checkProductText(text);
    const built: Built = Object.keys(errors).length > 0 ? invalid("new", errors) : { ok: true, form: "new", landing: "entity", change: { action: "product.create", ...text, price: trimmed(fields, "price") } };
    return await submit(request, auth, newProductScreen, signal, fields, built, (id) => `${adminPath("admin-product", [id.toString()])}?saved=1`);
  }

  async function updateProduct(request: Request, auth: CatalogAuth, productId: bigint, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, allowedKey, signal);
    const screen = productScreen(productId, false);
    const built = buildProductChange(fields, productId);
    return await submit(request, auth, screen, signal, fields, built, (id) => `${adminPath("admin-product", [(built.ok && built.landing === "entity" ? id : productId).toString()])}?saved=1`);
  }

  async function createCollection(request: Request, auth: CatalogAuth, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, allowedKey, signal);
    const text = productText(fields, true);
    const errors = checkCollectionText({ title: text.title, handle: text.handle, description: text.description });
    const built: Built = Object.keys(errors).length > 0 ? invalid("new", errors) : { ok: true, form: "new", landing: "entity", change: { action: "collection.create", title: text.title, handle: text.handle, description: text.description } };
    return await submit(request, auth, newCollectionScreen, signal, fields, built, (id) => `${adminPath("admin-collection", [id.toString()])}?saved=1`);
  }

  async function updateCollection(request: Request, auth: CatalogAuth, collectionId: bigint, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, allowedKey, signal);
    const screen = collectionScreen(collectionId, false);
    return await submit(request, auth, screen, signal, fields, buildCollectionChange(fields, collectionId), savedPath(screen.path));
  }

  async function uploadImage(request: Request, auth: CatalogAuth, signal: AbortSignal): Promise<Response> {
    const form = await readUploadForm(request, signal);
    const productId = need(form.productId, "product");
    const revision = need(form.revision, "revision");
    const screen = productScreen(productId, false);
    const fields: FormValues = new Map([["form_token", form.formToken], ["alt", form.alt]]);
    const landing = savedPath(screen.path);
    const refused = (message: string): Promise<Response> => submit(request, auth, screen, signal, fields, invalid("upload", { file: message }), landing);
    const formToken = parseToken(form.formToken);
    if (formToken === null) return await refused("This form could not be verified.");
    const prepared = await prepareUpload(form);
    if (!prepared.ok) return await refused(prepared.message);
    const files: readonly PreparedFile[] = prepared.card === null ? [prepared.detail] : [prepared.detail, prepared.card];
    const reserved = await backend.command({
      kind: "media.reserve", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: screen.purpose,
      productId, expectedRevision: revision, nowSeconds: now(),
      files: files.map((file) => ({ sha256: file.sha256, bytes: BigInt(file.image.bytes.length), width: BigInt(file.image.width), height: BigInt(file.image.height), contentType: contentTypeOf(file.image.kind) })),
    }, signal);
    if (reserved.outcome !== "reserved") {
      switch (reserved.outcome) {
        case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
        case "token_invalid": return await show(request, auth, screen, signal, { status: 409, notice: { kind: "error", message: "This form was already submitted or has expired, so nothing was changed. Review the current values and submit again if needed." }, echo: { form: "upload", input: fields, errors: {} }, conflict: true });
        case "stale": return await showAgain(request, auth, screen, signal, formToken, { status: 409, notice: { kind: "error", message: "This changed after you opened the form, so nothing was changed. Compare the values and submit again." }, echo: { form: "upload", input: fields, errors: {} }, conflict: true });
        case "rejected": return await refused({ too_many_pending: "Too many uploads are waiting. Try again in an hour.", library_full: "The media library is full.", unknown_product: "That product no longer exists.", image_limit: "This product has the most images it can have." }[reserved.rejection]);
      }
    }
    for (const [index, file] of files.entries()) {
      await options.blobs.put(mediaKey({ id: reserved.ids[index]!, sha256: file.sha256, kind: file.image.kind }), file.image.bytes, contentTypeOf(file.image.kind));
    }
    const built: Built = { ok: true, form: "upload", landing: "same", change: { action: "image.add", productId, expectedRevision: revision, detailMediaId: reserved.ids[0]!, cardMediaId: prepared.card === null ? null : reserved.ids[1]!, alt: form.alt } };
    return await submit(request, auth, screen, signal, fields, built, landing);
  }

  async function preview(request: Request, auth: CatalogAuth, productId: bigint, signal: AbortSignal): Promise<Response> {
    const result = await backend.query({ kind: "catalog.product", productId }, signal);
    return result.view === null ? notFound(request, auth) : page(request, 200, productPreviewPage(result.view, auth.label));
  }

  return {
    async handle(name, params, request, auth, signal) {
      const productId = parseId(params.get("product_id"));
      const collectionId = parseId(params.get("collection_id"));
      const saved = new URL(request.url).searchParams.get("saved") === "1";
      switch (name) {
        case "admin-products": return await products(request, auth, signal);
        case "admin-products-bulk": return await bulk(request, auth, signal);
        case "admin-product-new": return await show(request, auth, newProductScreen, signal);
        case "admin-product-create": return await createProduct(request, auth, signal);
        case "admin-product": return productId === null ? notFound(request, auth) : await show(request, auth, productScreen(productId, saved), signal);
        case "admin-product-update": return productId === null ? notFound(request, auth) : await updateProduct(request, auth, productId, signal);
        case "admin-media-upload": return await uploadImage(request, auth, signal);
        case "admin-product-preview": return productId === null ? notFound(request, auth) : await preview(request, auth, productId, signal);
        case "admin-collections": return await show(request, auth, collectionsScreen(parseId(new URL(request.url).searchParams.get("after") ?? undefined) ?? 0n), signal);
        case "admin-collection-new": return await show(request, auth, newCollectionScreen, signal);
        case "admin-collection-create": return await createCollection(request, auth, signal);
        case "admin-collection": return collectionId === null ? notFound(request, auth) : await show(request, auth, collectionScreen(collectionId, saved), signal);
        case "admin-collection-update": return collectionId === null ? notFound(request, auth) : await updateCollection(request, auth, collectionId, signal);
        default: return null;
      }
    },
  };
}
