import { MaxInt64 } from "../catalog/scalars.ts";
import { lookupCurrency } from "../catalog/money.ts";

export const StripeMaxAmountMinor = 999_999_999_999n;

export class MoneyRangeError extends Error {
  readonly _tag = "MoneyRangeError";
  constructor(message: string) { super(`commerce: ${message}`); }
}

export class CurrencyLockedError extends Error {
  readonly _tag = "CurrencyLockedError";
  constructor() { super("commerce: store currency cannot change once quotes or orders exist"); }
}

function checkedRange(value: bigint, what: string): bigint {
  if (value < 0n || value > MaxInt64) throw new MoneyRangeError(`${what} outside non-negative signed int64`);
  return value;
}

export function addMinor(left: bigint, right: bigint): bigint {
  return checkedRange(checkedRange(left, "addend") + checkedRange(right, "addend"), "sum");
}

export function subMinor(left: bigint, right: bigint): bigint {
  return checkedRange(checkedRange(left, "minuend") - checkedRange(right, "subtrahend"), "difference");
}

export function mulMinor(unit: bigint, quantity: bigint): bigint {
  return checkedRange(checkedRange(unit, "unit amount") * checkedRange(quantity, "quantity"), "product");
}

export function sumMinor(values: readonly bigint[]): bigint {
  return values.reduce(addMinor, 0n);
}

const stripeMinimumMinor: Readonly<Record<string, bigint>> = { USD: 50n };

export type CheckoutAmountProblem = "unsupported_currency" | "below_minimum" | "above_maximum";

export function checkCheckoutAmount(totalMinor: bigint, currencyCode: string): CheckoutAmountProblem | null {
  const minimum = stripeMinimumMinor[currencyCode];
  if (minimum === undefined) return "unsupported_currency";
  if (totalMinor < minimum) return "below_minimum";
  if (totalMinor > StripeMaxAmountMinor) return "above_maximum";
  return null;
}

export interface StoreCurrency {
  readonly code: string;
  readonly exponent: number;
}

export function checkCurrencyChange(current: StoreCurrency, next: StoreCurrency, quotesOrOrdersExist: boolean): void {
  lookupCurrency(next.code, next.exponent);
  if (quotesOrOrdersExist && (current.code !== next.code || current.exponent !== next.exponent)) throw new CurrencyLockedError();
}

export interface RefundCapacity {
  readonly capturedMinor: bigint;
  readonly succeededOrPendingMinor: bigint;
}

export function remainingRefundable(capacity: RefundCapacity): bigint {
  const remaining = capacity.capturedMinor - capacity.succeededOrPendingMinor;
  return remaining < 0n ? 0n : remaining;
}

export function checkRefundAmount(capacity: RefundCapacity, requestedMinor: bigint): "ok" | "not_positive" | "exceeds_captured" {
  if (requestedMinor <= 0n) return "not_positive";
  return requestedMinor > remainingRefundable(capacity) ? "exceeds_captured" : "ok";
}
