import { cancelEffect, restockEffect, returnEffect } from "../commerce/cancel_program.ts";
import type { RefundCommand, RefundCommandResult, RefundQuery, RefundQueryResult } from "../commerce/refund_operations.ts";
import { failRefund, observeRefund, refundEffect, refundViewProgram } from "../commerce/refund_program.ts";
import { guardedMutation } from "./guard.ts";
import type { Program } from "./program.ts";

type Of<K extends RefundCommand["kind"]> = Extract<RefundCommand, { readonly kind: K }>;
type Guarded = Pick<Of<"order.refund">, "sessionDigest" | "formTokenDigest" | "purpose" | "nowSeconds" | "actor">;

const binding = (command: Guarded) => ({ sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds });
const context = (command: Guarded) => ({ actor: command.actor, nowSeconds: BigInt(command.nowSeconds) });

function* refundOrder(command: Of<"order.refund">): Program<RefundCommandResult> {
  const guarded = yield* guardedMutation(binding(command), () => refundEffect(command, context(command)));
  if (guarded.outcome !== "done") return { kind: "order.refund", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "order.refund", outcome: "applied", refundId: guarded.mutation.result.refundId };
  const refusal = guarded.mutation.result;
  return refusal.kind === "rejected" ? { kind: "order.refund", outcome: "rejected", rejection: refusal.rejection } : { kind: "order.refund", outcome: refusal.kind };
}

function* cancelOrder(command: Of<"order.cancel">): Program<RefundCommandResult> {
  const guarded = yield* guardedMutation(binding(command), () => cancelEffect(command, context(command)));
  if (guarded.outcome !== "done") return { kind: "order.cancel", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "order.cancel", outcome: "applied", voided: guarded.mutation.result.voided };
  const refusal = guarded.mutation.result;
  return refusal.kind === "rejected" ? { kind: "order.cancel", outcome: "rejected", rejection: refusal.rejection } : { kind: "order.cancel", outcome: refusal.kind };
}

function* returnOrder(command: Of<"order.return">): Program<RefundCommandResult> {
  const guarded = yield* guardedMutation(binding(command), () => returnEffect(command, context(command)));
  if (guarded.outcome !== "done") return { kind: "order.return", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "order.return", outcome: "applied" };
  const refusal = guarded.mutation.result;
  return refusal.kind === "rejected" ? { kind: "order.return", outcome: "rejected", rejection: refusal.rejection } : { kind: "order.return", outcome: refusal.kind };
}

function* restockOrder(command: Of<"order.restock">): Program<RefundCommandResult> {
  const guarded = yield* guardedMutation(binding(command), () => restockEffect(command, context(command)));
  if (guarded.outcome !== "done") return { kind: "order.restock", outcome: guarded.outcome };
  if (guarded.mutation.applied) return { kind: "order.restock", outcome: "applied" };
  const refusal = guarded.mutation.result;
  return refusal.kind === "rejected" ? { kind: "order.restock", outcome: "rejected", rejection: refusal.rejection } : { kind: "order.restock", outcome: refusal.kind };
}

export function* refundCommandProgram(command: RefundCommand): Program<RefundCommandResult> {
  switch (command.kind) {
    case "order.refund": return yield* refundOrder(command);
    case "order.cancel": return yield* cancelOrder(command);
    case "order.return": return yield* returnOrder(command);
    case "order.restock": return yield* restockOrder(command);
    case "refund.observe": return { kind: "refund.observe", outcome: yield* observeRefund(command.refund, BigInt(command.nowSeconds)) };
    case "refund.fail": return { kind: "refund.fail", changed: yield* failRefund(command.refundId, command.to, command.error, BigInt(command.nowSeconds)) };
  }
}

export function* refundQueryProgram(query: RefundQuery): Program<RefundQueryResult> {
  return yield* refundViewProgram(query.refundId);
}
