export interface Html {
  readonly text: string;
}

const issued = new WeakSet<object>();

function make(text: string): Html {
  const value = Object.freeze({ text });
  issued.add(value);
  return value;
}

export type Interpolation = string | number | bigint | Html | readonly Html[] | null | undefined | false;

export function escapeText(value: string): string {
  return value.replace(/[&<>"'`]/g, (character) => `&#${character.charCodeAt(0)};`);
}

function render(value: Interpolation): string {
  if (value === null || value === undefined || value === false) return "";
  if (typeof value === "string") return escapeText(value);
  if (typeof value === "number" || typeof value === "bigint") return escapeText(String(value));
  if (Array.isArray(value)) return (value as readonly Html[]).map((part) => render(part)).join("");
  const part = value as Html;
  if (typeof part !== "object" || !issued.has(part)) throw new TypeError("admin html: interpolation is not an escaped fragment");
  return part.text;
}

/**
 * Tagged template whose static text is trusted source and whose every
 * interpolation is escaped. Interpolate only into element text or into
 * double-quoted attribute values.
 */
export function html(strings: TemplateStringsArray, ...values: readonly Interpolation[]): Html {
  let text = strings[0] ?? "";
  values.forEach((value, index) => {
    text += render(value) + (strings[index + 1] ?? "");
  });
  return make(text);
}

export function fragments(parts: readonly Html[]): Html {
  return make(parts.map((part) => render(part)).join(""));
}
