export type ColumnKind = "int" | "text" | "blob";

export interface Column {
  readonly name: string;
  readonly kind: ColumnKind;
  readonly nullable: boolean;
  readonly exportExpression?: string;
}

export interface TableSpec {
  readonly name: string;
  readonly columns: readonly Column[];
  readonly orderBy: string;
  readonly where?: string;
}

const int = (name: string): Column => ({ name, kind: "int", nullable: false });
const intOrNull = (name: string): Column => ({ name, kind: "int", nullable: true });
const text = (name: string): Column => ({ name, kind: "text", nullable: false });
const textOrNull = (name: string): Column => ({ name, kind: "text", nullable: true });
const blob = (name: string): Column => ({ name, kind: "blob", nullable: false });

const address: readonly Column[] = [
  textOrNull("recipient"), textOrNull("line1"), textOrNull("line2"), textOrNull("city"), textOrNull("region"),
  textOrNull("postal_code"), textOrNull("country"), textOrNull("shipping_zone"),
];

export const MediaTable: TableSpec = {
  name: "media_assets",
  columns: [int("id"), text("sha256"), int("bytes"), int("width"), int("height"), text("content_type"), text("state"), int("created_at"), intOrNull("ready_at"), intOrNull("card_id")],
  orderBy: "id",
  where: "state = 'ready'",
};

