import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const filter = <T>(test: (value: T) => boolean, message: string) => Schema.makeFilter<T>((value) => test(value) || message);
const Digest = Schema.String.check(filter<string>((value) => /^[0-9a-f]{64}$/.test(value), "must be a 64-character lowercase hex digest"));
const Seconds = Schema.Int.check(filter<number>((value) => value >= 0 && Number.isSafeInteger(value), "must be a non-negative integer number of seconds"));
const Purpose = Schema.String.check(filter<string>((value) => /^[a-z][a-z0-9._:-]*$/.test(value) && value.length <= 128, "must be a purpose label"));

export const PolicyProblemKinds = [
  "unknown_region", "duplicate_region", "rate_out_of_range", "unknown_origin_region", "duplicate_zone", "amount_out_of_range", "holds_out_of_range",
] as const;
export type PolicyProblemKind = (typeof PolicyProblemKinds)[number];

const Problem = Schema.Struct({ kind: Schema.Literals(PolicyProblemKinds), subject: Schema.NullOr(Schema.String) });
export type PolicyProblemView = typeof Problem.Type;

const TaxRateInput = Schema.Struct({ region: Schema.String, ratePpm: Integer, taxesLines: Schema.Boolean, taxesShipping: Schema.Boolean });
export const TaxPolicyInputSchema = Schema.Union([
  Schema.Struct({ mode: Schema.Literal("no_tax_collected") }),
  Schema.Struct({ mode: Schema.Literal("rate_table"), rates: Schema.Array(TaxRateInput) }),
]);
export type TaxPolicyInput = typeof TaxPolicyInputSchema.Type;

const ZoneInput = Schema.Struct({ name: Schema.String, regions: Schema.Array(Schema.String), flatRateMinor: Integer });
export const ShippingPolicyInputSchema = Schema.Struct({
  originRegion: Schema.String,
  zones: Schema.Array(ZoneInput),
  freeShippingThresholdMinor: Schema.NullOr(Integer),
  localPickup: Schema.Boolean,
});
export type ShippingPolicyInput = typeof ShippingPolicyInputSchema.Type;

export const SettingsChangeSchema = Schema.Union([
  Schema.Struct({ action: Schema.Literal("checkout.update"), expectedRevision: Integer, paused: Schema.Boolean, maxActiveHolds: Integer }),
  Schema.Struct({ action: Schema.Literal("tax.save"), expectedVersion: Integer, policy: TaxPolicyInputSchema }),
  Schema.Struct({ action: Schema.Literal("shipping.save"), expectedVersion: Integer, policy: ShippingPolicyInputSchema }),
]);
export type SettingsChange = typeof SettingsChangeSchema.Type;

export const SettingsMutateCommand = Schema.Struct({
  kind: Schema.Literal("settings.mutate"),
  sessionDigest: Digest,
  formTokenDigest: Digest,
  purpose: Purpose,
  actor: Schema.String,
  nowSeconds: Seconds,
  change: SettingsChangeSchema,
});

export const SettingsFormCommand = Schema.Struct({
  kind: Schema.Literal("settings.form"),
  tokenDigest: Digest,
  sessionDigest: Digest,
  purpose: Purpose,
  nowSeconds: Seconds,
});

const Currency = Schema.Struct({ code: Schema.String, exponent: Schema.Int });
const Provenance = Schema.Struct({ createdAt: Integer, createdBy: Schema.NullOr(Schema.String) });

export const SettingsView = Schema.Struct({
  currency: Schema.NullOr(Currency),
  checkout: Schema.Struct({ paused: Schema.Boolean, maxActiveHolds: Integer, revision: Integer }),
  tax: Schema.NullOr(Schema.Struct({
    version: Integer,
    ...Provenance.fields,
    mode: Schema.Literals(["rate_table", "no_tax_collected"]),
    rates: Schema.Array(TaxRateInput),
  })),
  shipping: Schema.NullOr(Schema.Struct({
    version: Integer,
    ...Provenance.fields,
    originRegion: Schema.String,
    freeShippingThresholdMinor: Schema.NullOr(Integer),
    localPickup: Schema.Boolean,
    zones: Schema.Array(ZoneInput),
  })),
});
export type SettingsViewModel = typeof SettingsView.Type;

export const SettingsQuerySchema = Schema.Struct({ kind: Schema.Literal("settings.view") });
export const SettingsQueryResultSchema = Schema.Struct({ kind: Schema.Literal("settings.view"), view: SettingsView });

export const SettingsResultSchemas = [
  Schema.Struct({ kind: Schema.Literal("settings.form"), issued: Schema.Boolean, view: SettingsView }),
  Schema.Struct({ kind: Schema.Literal("settings.mutate"), outcome: Schema.Literal("applied"), version: Integer }),
  Schema.Struct({ kind: Schema.Literal("settings.mutate"), outcome: Schema.Literals(["session_invalid", "token_invalid", "stale"]) }),
  Schema.Struct({ kind: Schema.Literal("settings.mutate"), outcome: Schema.Literal("rejected"), problems: Schema.Array(Problem) }),
] as const;
