import { applyFulfillment, type LineFulfillment } from "./fulfillment.ts";
import type { PaymentState } from "./payment.ts";

export const MaxCarrierLength = 60;
export const MaxTrackingNumberLength = 100;
export const MaxTrackingUrlLength = 500;
export const MaxShipmentLines = 100;

export function validCarrier(carrier: string): boolean {
  return carrier.length >= 1 && carrier.length <= MaxCarrierLength && carrier.trim() === carrier && !/[\u0000-\u001f\u007f-\u009f<>]/u.test(carrier);
}

export function validTrackingNumber(trackingNumber: string): boolean {
  return trackingNumber.length >= 1 && trackingNumber.length <= MaxTrackingNumberLength && /^[A-Za-z0-9][A-Za-z0-9 ._/:#-]*$/u.test(trackingNumber) && trackingNumber.trim() === trackingNumber;
}

export function validTrackingUrl(trackingUrl: string): boolean {
  if (trackingUrl.length < 9 || trackingUrl.length > MaxTrackingUrlLength || !/^[!-~]+$/u.test(trackingUrl)) return false;
  let parsed: URL;
  try {
    parsed = new URL(trackingUrl);
  } catch {
    return false;
  }
  return (parsed.protocol === "https:" || parsed.protocol === "http:") && parsed.username === "" && parsed.password === "" && parsed.hostname.includes(".");
}

export const ShipmentBlocks = ["payment_not_captured", "review_open"] as const;
export type ShipmentBlock = (typeof ShipmentBlocks)[number];

export function shipmentBlock(paymentState: PaymentState, reviewOpen: boolean): ShipmentBlock | null {
  if (reviewOpen || paymentState === "in_review") return "review_open";
  return paymentState === "captured" ? null : "payment_not_captured";
}

export const ShipmentRejections = [
  ...ShipmentBlocks,
  "empty_shipment",
  "too_many_lines",
  "invalid_carrier",
  "invalid_tracking_number",
  "invalid_tracking_url",
  "unknown_line",
  "duplicate_line",
  "invalid_quantity",
  "exceeds_unfulfilled",
] as const;
export type ShipmentRejection = (typeof ShipmentRejections)[number];

export interface ShipmentLineState {
  readonly position: bigint;
  readonly variantId: bigint;
  readonly tracked: boolean;
  readonly fulfillment: LineFulfillment;
}

export interface ShipmentRequest {
  readonly lines: readonly { readonly position: bigint; readonly quantity: bigint }[];
  readonly carrier: string;
  readonly trackingNumber: string | null;
  readonly trackingUrl: string | null;
}

export interface ShipmentPlanLine {
  readonly position: bigint;
  readonly variantId: bigint;
  readonly quantity: bigint;
  readonly tracked: boolean;
  readonly after: LineFulfillment;
}

export type ShipmentDecision =
  | { readonly ok: true; readonly lines: readonly ShipmentPlanLine[] }
  | { readonly ok: false; readonly rejection: ShipmentRejection };

export function decideShipment(
  order: { readonly paymentState: PaymentState; readonly reviewOpen: boolean; readonly lines: readonly ShipmentLineState[] },
  request: ShipmentRequest,
): ShipmentDecision {
  const block = shipmentBlock(order.paymentState, order.reviewOpen);
  if (block !== null) return { ok: false, rejection: block };
  if (request.lines.length === 0) return { ok: false, rejection: "empty_shipment" };
  if (request.lines.length > MaxShipmentLines) return { ok: false, rejection: "too_many_lines" };
  if (!validCarrier(request.carrier)) return { ok: false, rejection: "invalid_carrier" };
  if (request.trackingNumber !== null && !validTrackingNumber(request.trackingNumber)) return { ok: false, rejection: "invalid_tracking_number" };
  if (request.trackingUrl !== null && !validTrackingUrl(request.trackingUrl)) return { ok: false, rejection: "invalid_tracking_url" };
  const byPosition = new Map(order.lines.map((line) => [line.position, line]));
  const seen = new Set<bigint>();
  const planned: ShipmentPlanLine[] = [];
  for (const wanted of request.lines) {
    const line = byPosition.get(wanted.position);
    if (line === undefined) return { ok: false, rejection: "unknown_line" };
    if (seen.has(wanted.position)) return { ok: false, rejection: "duplicate_line" };
    seen.add(wanted.position);
    const outcome = applyFulfillment(line.fulfillment, "ship", wanted.quantity);
    if (!outcome.ok) return { ok: false, rejection: outcome.rejection === "invalid_quantity" ? "invalid_quantity" : "exceeds_unfulfilled" };
    planned.push({ position: line.position, variantId: line.variantId, quantity: wanted.quantity, tracked: line.tracked, after: outcome.line });
  }
  return { ok: true, lines: planned };
}
