import { formatPriceInput, StatusLabels } from "../catalog/edit.ts";
import { formatMoney } from "../catalog/money.ts";
import type { Status } from "../catalog/schema.ts";
import { adminPath } from "../routes/admin.ts";
import type { CatalogRejection, CollectionEditViewModel, CollectionListViewModel, CurrencyView, ProductEditViewModel, ProductListViewModel } from "./catalog_operations.ts";
import { fragments, html, type Html } from "./html.ts";
import { fieldError, layout, noticeBlock, type FieldErrors, type Notice } from "./pages.ts";

export interface Echo {
  readonly form: string | null;
  readonly input: ReadonlyMap<string, string>;
  readonly errors: FieldErrors;
}

export const noEcho: Echo = { form: null, input: new Map(), errors: {} };

export interface CatalogPageBase {
  readonly principalLabel: string;
  readonly formToken: string;
  readonly notice: Notice | null;
  readonly echo: Echo;
  readonly conflict: boolean;
}

function echoed(echo: Echo, form: string, field: string, current: string): string {
  return echo.form === form ? (echo.input.get(field) ?? current) : current;
}

function errorFor(echo: Echo, form: string, field: string): Html {
  return echo.form === form ? fieldError(echo.errors, field) : html``;
}

function money(minor: bigint, currency: CurrencyView): string {
  return formatMoney(minor, currency.code, currency.exponent);
}

function priceRange(min: bigint | null, max: bigint | null, currency: CurrencyView): string {
  if (min === null || max === null) return "no price";
  return min === max ? money(min, currency) : `${money(min, currency)} - ${money(max, currency)}`;
}

function hidden(token: string, extra: Readonly<Record<string, string>> = {}): Html {
  return html`<input type="hidden" name="form_token" value="${token}">${fragments(Object.entries(extra).map(([name, value]) => html`<input type="hidden" name="${name}" value="${value}">`))}`;
}

function statusOptions(selected: string): Html {
  return fragments((["draft", "active", "archived"] as const).map((status) => html`<option value="${status}" ${status === selected ? html`selected` : html``}>${StatusLabels[status]}</option>`));
}

export function describeCatalogRejection(rejection: CatalogRejection): { readonly field: string | null; readonly message: string } {
  switch (rejection) {
    case "handle_taken": return { field: "handle", message: "Another item already uses this handle." };
    case "invalid_price": return { field: "price", message: "Enter a price such as 24 or 24.50 in the store currency." };
    case "invalid_input": return { field: null, message: "Some of the values were not accepted. Check the highlighted fields." };
    case "unknown_product": return { field: null, message: "That product no longer exists." };
    case "unknown_collection": return { field: null, message: "That collection no longer exists." };
    case "unknown_variant": return { field: null, message: "That variant no longer exists." };
    case "unknown_option": return { field: null, message: "That option no longer exists." };
    case "unknown_value": return { field: null, message: "That option value no longer exists." };
    case "status_unchanged": return { field: null, message: "Nothing to change: it already has that status." };
    case "in_cart": return { field: null, message: "A shopper has this variant in a cart, so it cannot be removed. Mark it unavailable instead; carts will show it as unavailable." };
    case "commercial_reference": return { field: null, message: "Stock or order records refer to this variant, so it cannot be removed. Mark it unavailable or archive the product instead." };
    case "needs_variant": return { field: null, message: "A product needs at least one variant." };
    case "needs_option_for_variants": return { field: null, message: "A product without options has exactly one variant. Add an option first." };
    case "selection_incomplete": return { field: null, message: "Choose one value for every option." };
    case "selection_duplicate": return { field: null, message: "A variant with these option values already exists." };
    case "needs_value": return { field: null, message: "An option needs at least one value." };
    case "value_in_use": return { field: null, message: "A variant uses this value. Remove or change those variants first." };
    case "name_taken": return { field: "name", message: "That name is already used here." };
    case "limit": return { field: null, message: "That would exceed a catalog limit." };
    case "not_member": return { field: null, message: "That product is not in this collection." };
    case "already_member": return { field: "product_id", message: "That product is already in this collection." };
    case "at_edge": return { field: null, message: "It is already at the end of the list." };
    case "media_unavailable": return { field: "file", message: "The upload expired or was already used. Choose the image and upload it again." };
    case "unknown_image": return { field: null, message: "That image no longer exists." };
  }
}

function textField(echo: Echo, form: string, label: string, name: string, current: string, options: { readonly required?: boolean; readonly inputmode?: string; readonly hint?: string } = {}): Html {
  return html`<p><label>${label} <input name="${name}" autocomplete="off" value="${echoed(echo, form, name, current)}" ${options.inputmode === undefined ? html`` : html`inputmode="${options.inputmode}"`} aria-describedby="${name}-error" ${options.required === false ? html`` : html`required`}></label>${options.hint === undefined ? html`` : html` <small>${options.hint}</small>`}</p>${errorFor(echo, form, name)}`;
}

function areaField(echo: Echo, form: string, label: string, name: string, current: string): Html {
  return html`<p><label>${label}<br><textarea name="${name}" rows="6" aria-describedby="${name}-error">${echoed(echo, form, name, current)}</textarea></label></p>${errorFor(echo, form, name)}`;
}

function inputPairs(echo: Echo): Html {
  const skipped = new Set(["form_token", "revision", "action", "variant_id", "option_id", "value_id"]);
  const pairs = [...echo.input].filter(([name]) => !skipped.has(name));
  return html`<dl>${fragments(pairs.map(([name, value]) => html`<dt>${name}</dt><dd>${value === "" ? "(empty)" : value}</dd>`))}</dl>`;
}

function conflictBlock(echo: Echo, current: readonly (readonly [string, string])[]): Html {
  if (echo.form === null) return html``;
  return html`<section aria-label="Conflict"><h2>Compare</h2><div><h3>Your input</h3>${inputPairs(echo)}</div><div><h3>Current values</h3><dl>${fragments(current.map(([name, value]) => html`<dt>${name}</dt><dd>${value === "" ? "(empty)" : value}</dd>`))}</dl></div></section>`;
}

export function productListPage(state: CatalogPageBase & { readonly view: ProductListViewModel; readonly status: Status | ""; readonly saved: number | null }): Html {
  const { view } = state;
  const filter = (status: Status | "", label: string): Html => status === state.status
    ? html`<strong>${label}</strong>`
    : html`<a href="${adminPath("admin-products")}${status === "" ? "" : `?status=${status}`}">${label}</a>`;
  const last = view.items.at(-1);
  const next = view.hasMore && last !== undefined
    ? html`<p><a href="${adminPath("admin-products")}?after=${last.id.toString()}${state.status === "" ? "" : `&status=${state.status}`}">Next products</a></p>`
    : html``;
  const rows = view.items.length === 0
    ? html`<p>No products here yet.</p>`
    : html`<form method="post" action="${adminPath("admin-products-bulk")}">${hidden(state.formToken)}
<ul>${fragments(view.items.map((item) => html`<li><input type="checkbox" name="select_${item.id.toString()}" value="on" aria-label="Select ${item.title}"> <a href="${adminPath("admin-product", [item.id.toString()])}">${item.title}</a><br><small>${StatusLabels[item.status]} - ${priceRange(item.minPrice, item.maxPrice, view.currency)} - ${item.variantCount.toString()} ${item.variantCount === 1n ? "variant" : "variants"}</small></li>`))}</ul>
<p><label>Set selected products to <select name="status">${statusOptions("active")}</select></label> <button type="submit">Apply to selected</button></p>
<p><small>Up to 100 products at a time.</small></p>
</form>`;
  const notice: Notice | null = state.notice ?? (state.saved === null ? null : { kind: "info", message: `${state.saved.toString()} ${state.saved === 1 ? "product" : "products"} updated.` });
  return layout("Products", state.principalLabel, html`${noticeBlock(notice)}<p><a href="${adminPath("admin-product-new")}">New product</a></p>
<p>Show: ${filter("", "All")} | ${filter("draft", "Drafts")} | ${filter("active", "Published")} | ${filter("archived", "Archived")}</p>${rows}${next}`);
}

export function productNewPage(state: CatalogPageBase & { readonly currency: CurrencyView }): Html {
  const form = "new";
  return layout("New product", state.principalLabel, html`${noticeBlock(state.notice)}<p>A new product starts as a draft with one variant. Add options, more variants, and publish afterwards.</p>
<form method="post" action="${adminPath("admin-product-create")}">${hidden(state.formToken)}
${textField(state.echo, form, "Title", "title", "")}
${textField(state.echo, form, "Handle (the web address; leave blank to use the title)", "handle", "", { required: false })}
${textField(state.echo, form, "Vendor", "vendor", "", { required: false })}
${areaField(state.echo, form, "Description", "description", "")}
${textField(state.echo, form, `Price (${state.currency.code})`, "price", "", { inputmode: "decimal" })}
<button type="submit">Create draft</button>
</form>`);
}

function variantName(variant: ProductEditViewModel["variants"][number]): string {
  const labels = variant.labels.join(" / ");
  return labels === "" ? (variant.title ?? "Default") : variant.title === null ? labels : `${labels} (${variant.title})`;
}

function currentValues(view: ProductEditViewModel, form: string | null): readonly (readonly [string, string])[] {
  if (form === "product") return [["title", view.product.title], ["handle", view.product.handle], ["vendor", view.product.vendor ?? ""], ["description", view.product.description]];
  if (form !== null && form.startsWith("variant:")) {
    const variant = view.variants.find((candidate) => `variant:${candidate.id.toString()}` === form);
    if (variant !== undefined) return [["title", variant.title ?? ""], ["price", formatPriceInput(variant.priceMinor, view.currency.exponent)], ["available", variant.available ? "on" : "off"]];
  }
  return [["revision", view.product.revision.toString()], ["status", StatusLabels[view.product.status]], ["variants", view.variants.length.toString()], ["options", view.options.map((option) => option.name).join(", ")]];
}

function statusButtons(status: Status): Html {
  const button = (to: Status, label: string): Html => html`<button type="submit" name="status" value="${to}">${label}</button>`;
  if (status === "draft") return html`${button("active", "Publish")} ${button("archived", "Archive")}`;
  if (status === "active") return html`${button("draft", "Unpublish")} ${button("archived", "Archive")}`;
  return html`${button("draft", "Restore as draft")}`;
}

export function productEditPage(state: CatalogPageBase & { readonly view: ProductEditViewModel; readonly saved: boolean; readonly uploaderPath: string | null }): Html {
  const { view, echo } = state;
  const { product, currency } = view;
  const revision = product.revision.toString();
  const productPath = adminPath("admin-product-update", [product.id.toString()]);
  const post = (extra: Readonly<Record<string, string>>): Html => hidden(state.formToken, { revision, ...extra });
  const notice: Notice | null = state.notice ?? (state.saved ? { kind: "info", message: "Saved." } : null);

  const variantForms = view.variants.map((variant) => {
    const form = `variant:${variant.id.toString()}`;
    const stock = variant.stock === null
      ? html`Stock: not tracked (always available)`
      : html`Stock: ${variant.stock.onHand.toString()} on hand, ${variant.stock.held.toString()} held, ${variant.stock.allocated.toString()} allocated`;
    return html`<li><form method="post" action="${productPath}">${post({ variant_id: variant.id.toString() })}
<h3>${variantName(variant)}</h3>
${textField(echo, form, "Label", "title", variant.title ?? "", { required: false })}
${textField(echo, form, `Price (${currency.code})`, "price", formatPriceInput(variant.priceMinor, currency.exponent), { inputmode: "decimal" })}
<p><label><input type="checkbox" name="available" value="on" ${echoed(echo, form, "available", variant.available ? "on" : "") === "on" ? html`checked` : html``}> Available for sale</label></p>
<p><small>${stock}. <a href="${adminPath("admin-stock", [variant.id.toString()])}">Stock</a>${variant.cartLines > 0n ? html`. In ${variant.cartLines.toString()} ${variant.cartLines === 1n ? "cart" : "carts"}` : html``}</small></p>
<button type="submit" name="action" value="variant.update">Save variant</button> <button type="submit" name="action" value="variant.remove">Remove variant</button>
</form></li>`;
  });

  const addVariant = view.options.length === 0
    ? html`<p>This product has a single default variant. Add an option (for example Size) to offer more.</p>`
    : html`<form method="post" action="${productPath}">${post({ action: "variant.add" })}
<h3>Add a variant</h3>
${fragments(view.options.map((option) => html`<p><label>${option.name} <select name="option_${option.id.toString()}">${fragments(option.values.map((value) => html`<option value="${value.id.toString()}" ${echoed(echo, "variant-add", `option_${option.id.toString()}`, "") === value.id.toString() ? html`selected` : html``}>${value.value}</option>`))}</select></label></p>`))}
${textField(echo, "variant-add", "Label", "title", "", { required: false })}
${textField(echo, "variant-add", `Price (${currency.code})`, "price", "", { inputmode: "decimal" })}
<p><label><input type="checkbox" name="available" value="on" checked> Available for sale</label></p>
<button type="submit">Add variant</button>
</form>`;

  const optionBlocks = view.options.map((option) => html`<li><strong>${option.name}</strong>
<ul>${fragments(option.values.map((value) => html`<li><form method="post" action="${productPath}">${post({ action: "value.remove", value_id: value.id.toString() })}${value.value} <button type="submit">Remove ${value.value}</button></form></li>`))}</ul>
<form method="post" action="${productPath}">${post({ action: "value.add", option_id: option.id.toString() })}
${textField(echo, `value-add:${option.id.toString()}`, `New ${option.name} value`, "value", "")}
<button type="submit">Add value</button>
</form>
<form method="post" action="${productPath}">${post({ action: "option.remove", option_id: option.id.toString() })}<button type="submit">Remove option ${option.name}</button></form></li>`);

  const imageForms = view.images.map((image) => {
    const form = `image:${image.id.toString()}`;
    const preview = image.managed ? html`<img src="/admin${image.url}" alt="${image.altText}" width="120">` : html`<code>${image.url}</code>`;
    return html`<li>${preview}
<form method="post" action="${productPath}">${post({ image_id: image.id.toString() })}
${textField(echo, form, "Alt text", "alt", image.altText, { required: false })}
<button type="submit" name="action" value="image.alt">Save alt text</button> <button type="submit" name="action" value="image.move:up">Move up</button> <button type="submit" name="action" value="image.move:down">Move down</button> <button type="submit" name="action" value="image.remove">Remove image</button>
</form></li>`;
  });
  const uploadForm = html`<form method="post" action="${adminPath("admin-media-upload")}" enctype="multipart/form-data" data-image-upload>${hidden(state.formToken, { revision, product_id: product.id.toString() })}
<h3>Add an image</h3>
<p><label>Image (JPEG, PNG, or WebP, up to 4 MiB and 4096 pixels) <input type="file" name="original" accept="image/jpeg,image/png,image/webp" required></label></p>
${errorFor(echo, "upload", "file")}
${textField(echo, "upload", "Alt text", "alt", "", { required: false })}
<button type="submit">Upload image</button>
</form>${state.uploaderPath === null ? html`` : html`<script type="module" src="${state.uploaderPath}"></script>`}`;
  const images = html`${view.images.length === 0 ? html`<p>No images.</p>` : html`<ul>${fragments(imageForms)}</ul>`}${uploadForm}`;
  const collections = view.collections.length === 0
    ? html`<p>Not in any collection.</p>`
    : html`<ul>${fragments(view.collections.map((collection) => html`<li><a href="${adminPath("admin-collection", [collection.id.toString()])}">${collection.title}</a> (${StatusLabels[collection.status]})</li>`))}</ul>`;
  const audit = view.audit.length === 0 ? html`` : html`<h2>Changes</h2><ul>${fragments(view.audit.map((entry) => html`<li>${entry.action} by ${entry.actor}: ${entry.summary}</li>`))}</ul>`;
  const publicLink = product.status === "active" ? html` <a href="/products/${product.handle}">View in the shop</a>` : html``;

  return layout(`Product: ${product.title}`, state.principalLabel, html`${noticeBlock(notice)}${state.conflict ? conflictBlock(echo, currentValues(view, echo.form)) : html``}
<p><strong>${StatusLabels[product.status]}</strong>. <a href="${adminPath("admin-product-preview", [product.id.toString()])}">Preview</a>${publicLink}</p>
<form method="post" action="${productPath}">${post({ action: "product.status" })}${statusButtons(product.status)}</form>
<h2>Details</h2>
<form method="post" action="${productPath}">${post({ action: "product.update" })}
${textField(echo, "product", "Title", "title", product.title)}
${textField(echo, "product", "Handle", "handle", product.handle)}
${textField(echo, "product", "Vendor", "vendor", product.vendor ?? "", { required: false })}
${areaField(echo, "product", "Description", "description", product.description)}
<button type="submit">Save details</button>
</form>
<h2>Variants</h2>
<ul>${fragments(variantForms)}</ul>
${addVariant}
<h2>Options</h2>
${view.options.length === 0 ? html`<p>No options.</p>` : html`<ul>${fragments(optionBlocks)}</ul>`}
<form method="post" action="${productPath}">${post({ action: "option.add" })}
<h3>Add an option</h3>
<p><small>Every existing variant takes the first value.</small></p>
${textField(echo, "option-add", "Option name (for example Size)", "name", "")}
${textField(echo, "option-add", "First value", "value", "")}
<button type="submit">Add option</button>
</form>
<h2>Collections</h2>${collections}
<h2>Images</h2>${images}
<h2>Copy</h2>
<form method="post" action="${productPath}">${post({ action: "product.duplicate" })}<button type="submit">Duplicate as draft</button></form>
${audit}`);
}

export function productPreviewPage(view: ProductEditViewModel, principalLabel: string): Html {
  const { product, currency } = view;
  const prices = view.variants.map((variant) => variant.priceMinor);
  const min = prices.length === 0 ? null : prices.reduce((a, b) => (a < b ? a : b));
  const max = prices.length === 0 ? null : prices.reduce((a, b) => (a > b ? a : b));
  const banner = product.status === "active" ? "This product is published." : `This product is ${StatusLabels[product.status].toLowerCase()} and is not visible to shoppers.`;
  return layout(`Preview: ${product.title}`, principalLabel, html`<p role="status">${banner} <a href="${adminPath("admin-product", [product.id.toString()])}">Back to editing</a></p>
<article>
<h2>${product.title}</h2>
${product.vendor === null ? html`` : html`<p>${product.vendor}</p>`}
<p>${priceRange(min, max, currency)}</p>
${fragments(product.description.split(/\n{2,}/).filter((part) => part.trim() !== "").map((part) => html`<p>${part}</p>`))}
<h3>Choices</h3>
<ul>${fragments(view.variants.map((variant) => html`<li>${variantName(variant)}: ${money(variant.priceMinor, currency)} - ${variant.available ? (variant.stock !== null && variant.stock.onHand - variant.stock.held - variant.stock.allocated <= 0n ? "sold out" : "available") : "unavailable"}</li>`))}</ul>
${view.details.length === 0 ? html`` : fragments(view.details.map((detail) => html`<h3>${detail.title}</h3><p>${detail.body}</p>`))}
</article>`);
}

export function collectionListPage(state: CatalogPageBase & { readonly view: CollectionListViewModel }): Html {
  const { view } = state;
  const last = view.items.at(-1);
  const rows = view.items.length === 0
    ? html`<p>No collections yet.</p>`
    : html`<ul>${fragments(view.items.map((item) => html`<li><a href="${adminPath("admin-collection", [item.id.toString()])}">${item.title}</a><br><small>${StatusLabels[item.status]} - ${item.memberCount.toString()} ${item.memberCount === 1n ? "product" : "products"}</small></li>`))}</ul>`;
  const next = view.hasMore && last !== undefined ? html`<p><a href="${adminPath("admin-collections")}?after=${last.id.toString()}">Next collections</a></p>` : html``;
  return layout("Collections", state.principalLabel, html`${noticeBlock(state.notice)}<p><a href="${adminPath("admin-collection-new")}">New collection</a></p>${rows}${next}`);
}

