export function collectionEditPage(state: CatalogPageBase & { readonly view: CollectionEditViewModel; readonly saved: boolean }): Html {
  const { view, echo } = state;
  const { collection } = view;
  const revision = collection.revision.toString();
  const path = adminPath("admin-collection-update", [collection.id.toString()]);
  const post = (extra: Readonly<Record<string, string>>): Html => hidden(state.formToken, { revision, ...extra });
  const notice: Notice | null = state.notice ?? (state.saved ? { kind: "info", message: "Saved." } : null);
  const button = (to: Status, label: string): Html => html`<button type="submit" name="status" value="${to}">${label}</button>`;
  const statusControls = collection.status === "draft" ? html`${button("active", "Publish")} ${button("archived", "Archive")}`
    : collection.status === "active" ? html`${button("draft", "Unpublish")} ${button("archived", "Archive")}` : button("draft", "Restore as draft");
  const members = view.members.length === 0
    ? html`<p>No products in this collection.</p>`
    : html`<ol>${fragments(view.members.map((member) => html`<li><a href="${adminPath("admin-product", [member.productId.toString()])}">${member.title}</a> (${StatusLabels[member.status]})
<form method="post" action="${path}">${post({ product_id: member.productId.toString() })}<button type="submit" name="action" value="collection.member_move:up">Move up</button> <button type="submit" name="action" value="collection.member_move:down">Move down</button> <button type="submit" name="action" value="collection.member_remove">Remove</button></form></li>`))}</ol>${view.memberCount > BigInt(view.members.length) ? html`<p><small>Showing the first ${view.members.length.toString()} of ${view.memberCount.toString()} products.</small></p>` : html``}`;
  const audit = view.audit.length === 0 ? html`` : html`<h2>Changes</h2><ul>${fragments(view.audit.map((entry) => html`<li>${entry.action} by ${entry.actor}: ${entry.summary}</li>`))}</ul>`;
  const current: readonly (readonly [string, string])[] = [["title", collection.title], ["handle", collection.handle], ["description", collection.description]];
  return layout(`Collection: ${collection.title}`, state.principalLabel, html`${noticeBlock(notice)}${state.conflict ? conflictBlock(echo, current) : html``}
<p><strong>${StatusLabels[collection.status]}</strong>${collection.status === "active" ? html` <a href="/collections/${collection.handle}">View in the shop</a>` : html``}</p>
<form method="post" action="${path}">${post({ action: "collection.status" })}${statusControls}</form>
<h2>Details</h2>
<form method="post" action="${path}">${post({ action: "collection.update" })}
${textField(echo, "collection", "Title", "title", collection.title)}
${textField(echo, "collection", "Handle", "handle", collection.handle)}
${areaField(echo, "collection", "Description", "description", collection.description)}
<button type="submit">Save details</button>
</form>
<h2>Products</h2>
${members}
<form method="post" action="${path}">${post({ action: "collection.member_add" })}
${textField(echo, "member-add", "Add the product with this number", "product_id", "", { inputmode: "numeric", hint: "The number is the last part of its admin address." })}
<button type="submit">Add product</button>
</form>
${audit}`);
}
