import { isNonblank, MaxInt64, MaxLabelBytes, MaxOptionsPerProduct, MaxProseBytes, MaxValuesPerOption, MaxVariantsPerProduct } from "./scalars.ts";
import type { Status } from "./schema.ts";

export const BulkRowLimit = 100;
export const AdminPageSize = 50;
export const CollectionMemberDisplayLimit = 200;

const encoder = new TextEncoder();
const byteLength = (value: string): number => encoder.encode(value).length;

export const HandlePattern = /^[a-z0-9](?:[a-z0-9-]{0,198}[a-z0-9])?$/;

export interface ProductText {
  readonly title: string;
  readonly handle: string;
  readonly vendor: string | null;
  readonly description: string;
}

export interface CollectionText {
  readonly title: string;
  readonly handle: string;
  readonly description: string;
}

export type TextProblems = { readonly [field: string]: string };

export function slugify(title: string): string {
  const slug = title
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 200)
    .replace(/-+$/g, "");
  return slug;
}

function checkTitle(title: string, problems: Record<string, string>): void {
  if (!isNonblank(title)) problems["title"] = "Enter a title.";
  else if (byteLength(title) > MaxLabelBytes) problems["title"] = `Use at most ${MaxLabelBytes} bytes.`;
}

function checkHandle(handle: string, problems: Record<string, string>): void {
  if (!HandlePattern.test(handle)) problems["handle"] = "Use lowercase letters, digits, and single hyphens inside; it must start and end with a letter or digit (at most 200 characters).";
}

function checkDescription(description: string, problems: Record<string, string>): void {
  if (byteLength(description) > MaxProseBytes) problems["description"] = `Use at most ${MaxProseBytes} bytes.`;
}

export function checkProductText(text: ProductText): TextProblems {
  const problems: Record<string, string> = {};
  checkTitle(text.title, problems);
  checkHandle(text.handle, problems);
  if (text.vendor !== null && (!isNonblank(text.vendor) || byteLength(text.vendor) > MaxLabelBytes)) problems["vendor"] = `Leave blank or use real text of at most ${MaxLabelBytes} bytes.`;
  checkDescription(text.description, problems);
  return problems;
}

export function checkCollectionText(text: CollectionText): TextProblems {
  const problems: Record<string, string> = {};
  checkTitle(text.title, problems);
  checkHandle(text.handle, problems);
  checkDescription(text.description, problems);
  return problems;
}

export function checkLabel(value: string, field: string): TextProblems {
  if (!isNonblank(value)) return { [field]: "Enter some text." };
  if (byteLength(value) > MaxLabelBytes) return { [field]: `Use at most ${MaxLabelBytes} bytes.` };
  return {};
}

/** Parses a merchant-typed price ("24", "24.5", "24.50") into exact minor units, or null when it is not a price. */
export function parsePriceInput(text: string, exponent: number): bigint | null {
  const match = /^([0-9]{1,15})(?:\.([0-9]{1,3}))?$/.exec(text.trim());
  if (match === null) return null;
  const whole = match[1] ?? "";
  const fraction = match[2] ?? "";
  if (fraction.length > exponent) return null;
  const minor = BigInt(whole + fraction.padEnd(exponent, "0"));
  return minor > MaxInt64 ? null : minor;
}

export function formatPriceInput(minor: bigint, exponent: number): string {
  if (exponent === 0) return minor.toString();
  const digits = minor.toString().padStart(exponent + 1, "0");
  return `${digits.slice(0, -exponent)}.${digits.slice(-exponent)}`;
}

export const StatusLabels: Readonly<Record<Status, string>> = { draft: "Draft", active: "Published", archived: "Archived" };

export function isStatus(value: string): value is Status {
  return value === "draft" || value === "active" || value === "archived";
}

export function statusAuditAction(from: Status, to: Status): string {
  if (to === "active") return "published";
  if (from === "active") return to === "archived" ? "archived" : "unpublished";
  return to === "archived" ? "archived" : "restored";
}

export interface StructureOption {
  readonly id: bigint;
  readonly name: string;
  readonly values: readonly { readonly id: bigint; readonly value: string }[];
}

export interface StructureVariant {
  readonly id: bigint;
  readonly selections: ReadonlyMap<bigint, bigint>;
}

export interface ProductStructure {
  readonly options: readonly StructureOption[];
  readonly variants: readonly StructureVariant[];
}

export const ShapeProblems = [
  "needs_variant",
  "needs_option_for_variants",
  "selection_incomplete",
  "selection_duplicate",
  "needs_value",
  "value_in_use",
  "name_taken",
  "limit",
  "unknown_option",
  "unknown_value",
  "unknown_variant",
] as const;
export type ShapeProblem = (typeof ShapeProblems)[number];

export type EditResult = { readonly ok: true; readonly structure: ProductStructure } | { readonly ok: false; readonly problem: ShapeProblem };

const tupleKey = (options: readonly StructureOption[], variant: StructureVariant): string => options.map((option) => String(variant.selections.get(option.id))).join("/");

/** The same final-state rules the catalog import enforces, so an edit can be refused before any row changes. */
export function checkShape(structure: ProductStructure): ShapeProblem | null {
  const { options, variants } = structure;
  if (variants.length === 0) return "needs_variant";
  if (variants.length > MaxVariantsPerProduct || options.length > MaxOptionsPerProduct) return "limit";
  if (options.length === 0 && variants.length !== 1) return "needs_option_for_variants";
  const names = new Set<string>();
  const owners = new Map<bigint, bigint>();
  for (const option of options) {
    if (names.has(option.name)) return "name_taken";
    names.add(option.name);
    if (option.values.length === 0) return "needs_value";
    if (option.values.length > MaxValuesPerOption) return "limit";
    const values = new Set<string>();
    for (const value of option.values) {
      if (values.has(value.value)) return "name_taken";
      values.add(value.value);
      owners.set(value.id, option.id);
    }
  }
  const seen = new Set<string>();
  for (const variant of variants) {
    if (variant.selections.size !== options.length) return "selection_incomplete";
    for (const option of options) {
      const chosen = variant.selections.get(option.id);
      if (chosen === undefined || owners.get(chosen) !== option.id) return "selection_incomplete";
    }
    const key = tupleKey(options, variant);
    if (seen.has(key)) return "selection_duplicate";
    seen.add(key);
  }
  return null;
}

function checked(structure: ProductStructure): EditResult {
  const problem = checkShape(structure);
  return problem === null ? { ok: true, structure } : { ok: false, problem };
}

export function withVariant(structure: ProductStructure, variantId: bigint, valueIds: readonly bigint[]): EditResult {
  if (valueIds.length !== structure.options.length) return { ok: false, problem: "selection_incomplete" };
  const selections = new Map<bigint, bigint>();
  structure.options.forEach((option, index) => selections.set(option.id, valueIds[index]!));
  return checked({ options: structure.options, variants: [...structure.variants, { id: variantId, selections }] });
}

export function withoutVariant(structure: ProductStructure, variantId: bigint): EditResult {
  if (!structure.variants.some((variant) => variant.id === variantId)) return { ok: false, problem: "unknown_variant" };
  return checked({ options: structure.options, variants: structure.variants.filter((variant) => variant.id !== variantId) });
}

export function withOption(structure: ProductStructure, optionId: bigint, name: string, valueId: bigint, value: string): EditResult {
  return checked({
    options: [...structure.options, { id: optionId, name, values: [{ id: valueId, value }] }],
    variants: structure.variants.map((variant) => ({ id: variant.id, selections: new Map([...variant.selections, [optionId, valueId]]) })),
  });
}

export function withoutOption(structure: ProductStructure, optionId: bigint): EditResult {
  if (!structure.options.some((option) => option.id === optionId)) return { ok: false, problem: "unknown_option" };
  return checked({
    options: structure.options.filter((option) => option.id !== optionId),
    variants: structure.variants.map((variant) => ({ id: variant.id, selections: new Map([...variant.selections].filter(([option]) => option !== optionId)) })),
  });
}

export function withValue(structure: ProductStructure, optionId: bigint, valueId: bigint, value: string): EditResult {
  if (!structure.options.some((option) => option.id === optionId)) return { ok: false, problem: "unknown_option" };
  return checked({
    options: structure.options.map((option) => option.id === optionId ? { ...option, values: [...option.values, { id: valueId, value }] } : option),
    variants: structure.variants,
  });
}

export function withoutValue(structure: ProductStructure, valueId: bigint): EditResult {
  const owner = structure.options.find((option) => option.values.some((value) => value.id === valueId));
  if (owner === undefined) return { ok: false, problem: "unknown_value" };
  if (structure.variants.some((variant) => variant.selections.get(owner.id) === valueId)) return { ok: false, problem: "value_in_use" };
  return checked({
    options: structure.options.map((option) => option.id === owner.id ? { ...option, values: option.values.filter((value) => value.id !== valueId) } : option),
    variants: structure.variants,
  });
}
