import { Effect, Schema } from "effect";
import { MaxInt64 } from "../catalog/scalars.ts";
import { DatabaseError, type SQLBoundValue, type SQLValue, type SyncTransaction, type Transaction } from "./persistence.ts";

export const MinInt64 = -9223372036854775808n;

const CanonicalInt64Text = Schema.String.check(Schema.makeFilter<string>((value) => {
  if (!/^(?:0|-?[1-9][0-9]{0,18})$/.test(value)) return "must be a canonical decimal int64 string";
  const parsed = BigInt(value);
  return (parsed >= MinInt64 && parsed <= MaxInt64) || "exceeds signed int64";
}));

export const Integer = CanonicalInt64Text.pipe(Schema.decodeTo(Schema.BigIntFromString));
const Text = Schema.String;
const NullableText = Schema.NullOr(Text);
const NullableInteger = Schema.NullOr(Integer);
const Count = Schema.Struct({ "COUNT(*)": Integer });
const rowSchemas = {
  GetStore: Schema.Struct({ id: Integer, name: Text, currency_code: Text, currency_exponent: Integer }),
  GetCatalogGeneration: Schema.Struct({ generation: Integer }),
  GetCatalogVersions: Schema.Struct({ generation: Integer, stock_version: Integer }),
  GetPublishedCatalogFootprint: Schema.Struct({ products: Integer, variants: Integer, selections: Integer, option_values: Integer, images: Integer, details: Integer, collections: Integer, members: Integer, text_bytes: Integer }),
  ListPublishedProducts: Schema.Struct({ id: Integer, handle: Text, title: Text, vendor: NullableText, description: Text }),
  ListPublishedVariants: Schema.Struct({ product_id: Integer, id: Integer, title: NullableText, price_minor: Integer, available: Integer }),
  ListPublishedSelections: Schema.Struct({ variant_id: Integer, option_value_id: Integer }),
  ListPublishedOptionValues: Schema.Struct({ product_id: Integer, option_id: Integer, option_name: Text, value_id: Integer, value: Text }),
  ListPublishedImages: Schema.Struct({ product_id: Integer, url: Text, alt_text: Text, width: NullableInteger, height: NullableInteger, card_url: NullableText, card_width: NullableInteger, card_height: NullableInteger }),
  ListPublishedDetails: Schema.Struct({ product_id: Integer, key: Text, title: Text, body: Text }),
  ListPublishedCollections: Schema.Struct({ id: Integer, handle: Text, title: Text, description: Text }),
  ListPublishedMembers: Schema.Struct({ collection_id: Integer, product_id: Integer }),
  GetShopProfile: Schema.Struct({ description: Text, contact_email: NullableText, contact_phone: NullableText }),
  ListShopPages: Schema.Struct({ kind: Text, blocks: Text }),
  ListPublishedRedirects: Schema.Struct({ kind: Text, old_handle: Text, target_handle: Text }),
  GetLiveSession: Schema.Struct({ token_hash: Schema.instanceOf(Uint8Array) }),
  GetVariantForCart: Schema.Struct({ id: Integer, available: Integer, product_status: Text }),
  GetCartQuantity: Schema.Struct({ quantity: Integer }),
  CountCommercialRecords: Schema.Struct({ variant_references: Integer, bound_rows: Integer }),
  CountCartLines: Count, CountStore: Count, CountSessions: Count, CountCartItems: Count,
  ListCartLines: Schema.Struct({ variant_id: Integer, quantity: Integer, variant_title: NullableText, price_minor: Integer, available: Integer, handle: Text, product_title: Text, product_status: Text, image_url: NullableText, image_alt: NullableText, image_width: NullableInteger, image_height: NullableInteger }),
  ListVariantSelectionLabels: Schema.Struct({ variant_id: Integer, value: Text }),
  ProductImportStats: Schema.Struct({ product_id: Integer, variants: Integer, options: Integer }),
  OptionImportStats: Schema.Struct({ option_id: Integer, opt_values: Integer }),
  VariantImportStats: Schema.Struct({ variant_id: Integer, product_id: Integer, selections: Integer, options: Integer }),
  ListVariantSelections: Schema.Struct({ variant_id: Integer, product_id: Integer, option_id: Integer, option_value_id: Integer }),
} as const;
export type RowQueryName = keyof typeof rowSchemas;
export type QueryRow<N extends RowQueryName> = typeof rowSchemas[N]["Type"];
export type CountQueryName = "CountStore" | "CountSessions" | "CountCartItems" | "CountCartLines";
const writeQueries = ["InsertStore", "DeleteStore", "DeleteAllProducts", "DeleteAllCollections", "DeleteAllSessions", "InsertProduct", "InsertProductDetail", "InsertProductOption", "InsertProductOptionValue", "InsertProductVariant", "InsertVariantOptionValue", "InsertProductImage", "InsertCollection", "InsertCollectionProduct", "InsertSession", "DeleteExpiredSessions", "UpsertCartItem", "DeleteCartItem"] as const;
export type WriteQueryName = typeof writeQueries[number];
export type QueryName = RowQueryName | WriteQueryName;
interface QueryDefinition { readonly sql: string; readonly parameters: number; readonly kind: "one" | "many" | "exec" | "execrows"; }

/** Counts positional SQLite parameters without counting placeholders in literals or comments. */
export function inspectQuerySQL(source: string): number {
  let parameters = 0, i = 0;
  while (i < source.length) {
    const c = source[i];
    if (c === "'" || c === '"' || c === "`" || c === "[") {
      const close = c === "[" ? "]" : c;
      i++;
      let closed = false;
      while (i < source.length) {
        const next = source[i++];
        if (next === close) {
          if (source[i] === close && close !== "]") { i++; continue; }
          closed = true; break;
        }
      }
      if (!closed) throw new DatabaseError("queries: unterminated quote");
      continue;
    }
    if (source.startsWith("--", i)) {
      const end = source.indexOf("\n", i);
      if (end < 0) break;
      i = end + 1; continue;
    }
    if (source.startsWith("/*", i)) {
      const end = source.indexOf("*/", i + 2);
      if (end < 0) throw new DatabaseError("queries: unterminated comment");
      i = end + 2; continue;
    }
    if (c === "?") parameters++;
    i++;
  }
  return parameters;
}

export function bindParam(value: SQLValue): SQLBoundValue {
  if (value === null || typeof value === "string" || value instanceof Uint8Array) return value;
  if (typeof value === "bigint") {
    if (value < MinInt64 || value > MaxInt64) throw new DatabaseError(`queries: bigint parameter ${String(value)} exceeds signed int64`);
    return value.toString();
  }
  throw new DatabaseError(`queries: invalid scalar parameter ${typeof value}`);
}

export class StorefrontQueries {
  private readonly definitions: ReadonlyMap<QueryName, QueryDefinition>;
  constructor(definitions: ReadonlyMap<QueryName, QueryDefinition>) { this.definitions = definitions; }
  prepare(name: QueryName, params: readonly SQLValue[] = []): { readonly sql: string; readonly params: readonly SQLBoundValue[] } {
    const definition = this.definitions.get(name);
    if (definition === undefined || definition.parameters !== params.length) {
      throw new DatabaseError(`queries: ${name} requires ${definition?.parameters ?? "unknown"} parameters, received ${params.length}`);
    }
    const bound = params.map(bindParam);
    return { sql: definition.sql, params: bound };
  }
  decodeRow<N extends RowQueryName>(name: N, input: unknown): QueryRow<N> {
    try {
      return Schema.decodeUnknownSync(rowSchemas[name], { onExcessProperty: "error" })(input) as QueryRow<N>;
    } catch (cause) {
      throw new DatabaseError(`queries: invalid ${name} row`, cause);
    }
  }
  decodeRows<N extends RowQueryName>(name: N, rows: readonly unknown[]): readonly QueryRow<N>[] {
    return rows.map((row) => this.decodeRow(name, row));
  }
  private prepareEffect(name: QueryName, params: readonly SQLValue[]): Effect.Effect<{ readonly sql: string; readonly params: readonly SQLBoundValue[] }, DatabaseError> {
    return Effect.try({ try: () => this.prepare(name, params), catch: (cause) => cause instanceof DatabaseError ? cause : new DatabaseError("queries: parameter binding failed", cause) });
  }
  private decodeEffect<N extends RowQueryName>(name: N, input: unknown): Effect.Effect<QueryRow<N>, DatabaseError> {
    return Effect.try({ try: () => this.decodeRow(name, input), catch: (cause) => cause instanceof DatabaseError ? cause : new DatabaseError(`queries: invalid ${name} row`, cause) });
  }
  all<N extends RowQueryName>(tx: Transaction, name: N, params: readonly SQLValue[] = []): Effect.Effect<readonly QueryRow<N>[], DatabaseError> {
    return Effect.flatMap(this.prepareEffect(name, params), ({ sql, params: bound }) => Effect.flatMap(tx.all(sql, bound), (rows) => Effect.forEach(rows, (row) => this.decodeEffect(name, row))));
  }
  get<N extends RowQueryName>(tx: Transaction, name: N, params: readonly SQLValue[] = []): Effect.Effect<QueryRow<N> | null, DatabaseError> {
    return Effect.flatMap(this.prepareEffect(name, params), ({ sql, params: bound }) => Effect.flatMap(tx.get(sql, bound), (row) => row === null ? Effect.succeed(null) : this.decodeEffect(name, row)));
  }
  required<N extends RowQueryName>(tx: Transaction, name: N, params: readonly SQLValue[] = []): Effect.Effect<QueryRow<N>, DatabaseError> {
    return Effect.flatMap(this.get(tx, name, params), (row) => row === null ? Effect.fail(new DatabaseError(`queries: missing ${name} row`)) : Effect.succeed(row));
  }
  run(tx: Transaction, name: WriteQueryName, params: readonly SQLValue[] = []): Effect.Effect<bigint, DatabaseError> {
    return Effect.flatMap(this.prepareEffect(name, params), ({ sql, params: bound }) => Effect.map(tx.run(sql, bound), (result) => result.changes));
  }
  count(tx: Transaction, name: CountQueryName, params: readonly SQLValue[] = []): Effect.Effect<bigint, DatabaseError> {
    return Effect.map(this.required(tx, name, params), (row) => row["COUNT(*)"]);
  }
  allSync<N extends RowQueryName>(tx: SyncTransaction, name: N, params: readonly SQLValue[] = []): readonly QueryRow<N>[] {
    const { sql, params: bound } = this.prepare(name, params);
    return this.decodeRows(name, tx.all(sql, bound));
  }
  getSync<N extends RowQueryName>(tx: SyncTransaction, name: N, params: readonly SQLValue[] = []): QueryRow<N> | null {
    const { sql, params: bound } = this.prepare(name, params);
    const row = tx.get(sql, bound);
    return row === null ? null : this.decodeRow(name, row);
  }
  requiredSync<N extends RowQueryName>(tx: SyncTransaction, name: N, params: readonly SQLValue[] = []): QueryRow<N> {
    const row = this.getSync(tx, name, params);
    if (row === null) throw new DatabaseError(`queries: missing ${name} row`);
    return row;
  }
  runSync(tx: SyncTransaction, name: WriteQueryName, params: readonly SQLValue[] = []): bigint {
    const { sql, params: bound } = this.prepare(name, params);
    return tx.run(sql, bound).changes;
  }
  countSync(tx: SyncTransaction, name: CountQueryName, params: readonly SQLValue[] = []): bigint {
    return this.requiredSync(tx, name, params)["COUNT(*)"];
  }
}

export const QueryFiles = ["store.sql", "cart.sql", "catalog_read.sql", "catalog_write.sql", "catalog_verify.sql"] as const;

/** Builds the single query authority from already-read SQL sources. */
export function buildStorefrontQueries(sources: ReadonlyMap<string, string>): StorefrontQueries {
  const known = new Set<string>([...Object.keys(rowSchemas), ...writeQueries]);
  const definitions = new Map<QueryName, QueryDefinition>();
  for (const file of QueryFiles) {
    const source = sources.get(file);
    if (source === undefined) throw new DatabaseError(`queries: missing ${file}`);
    const markers = [...source.matchAll(/^-- name: ([A-Za-z][A-Za-z0-9]*) :(one|many|exec|execrows)\s*$/gm)];
    for (const [index, marker] of markers.entries()) {
      const name = marker[1] ?? "", kind = marker[2];
      if (!known.has(name) || definitions.has(name as QueryName) || (kind !== "one" && kind !== "many" && kind !== "exec" && kind !== "execrows")) throw new DatabaseError(`queries: unknown or duplicate ${name}`);
      const raw = source.slice((marker.index ?? 0) + marker[0].length, markers[index + 1]?.index ?? source.length).trim();
      const parameters = inspectQuerySQL(raw);
      definitions.set(name as QueryName, { sql: raw, parameters, kind });
    }
  }
  for (const name of known) if (!definitions.has(name as QueryName)) throw new DatabaseError(`queries: missing ${name}`);
  return new StorefrontQueries(definitions);
}
