export const ImageKinds = ["jpeg", "png", "webp"] as const;
export type ImageKind = (typeof ImageKinds)[number];

const contentTypes = { jpeg: "image/jpeg", png: "image/png", webp: "image/webp" } as const satisfies Record<ImageKind, string>;
const extensions = { jpeg: "jpg", png: "png", webp: "webp" } as const satisfies Record<ImageKind, string>;

export const ContentTypes = Object.freeze(Object.values(contentTypes));

export function contentTypeOf(kind: ImageKind): string {
  return contentTypes[kind];
}

export function extensionOf(kind: ImageKind): string {
  return extensions[kind];
}

export function kindOfContentType(contentType: string): ImageKind | null {
  return ImageKinds.find((kind) => contentTypes[kind] === contentType) ?? null;
}

export function kindOfExtension(extension: string): ImageKind | null {
  return ImageKinds.find((kind) => extensions[kind] === extension) ?? null;
}

const idPattern = "[1-9][0-9]{0,18}";
const keyPattern = new RegExp(`^m/(${idPattern})/([0-9a-f]{64})\\.(jpg|png|webp)$`);
const publicPattern = new RegExp(`^/media/(${idPattern})/([0-9a-f]{64})\\.(jpg|png|webp)$`);
const MaxInt64 = 9223372036854775807n;

export interface MediaAddress {
  readonly id: bigint;
  readonly sha256: string;
  readonly kind: ImageKind;
}

function addressOf(match: RegExpExecArray | null): MediaAddress | null {
  if (match === null) return null;
  const id = BigInt(match[1]!);
  const kind = kindOfExtension(match[3]!);
  return id > MaxInt64 || kind === null ? null : { id, sha256: match[2]!, kind };
}

export function mediaKey(address: MediaAddress): string {
  return `m/${address.id}/${address.sha256}.${extensions[address.kind]}`;
}

export function parseMediaKey(key: string): MediaAddress | null {
  return addressOf(keyPattern.exec(key));
}

export function publicMediaPath(address: MediaAddress): string {
  return `/media/${address.id}/${address.sha256}.${extensions[address.kind]}`;
}

export function parsePublicMediaPath(path: string): MediaAddress | null {
  return addressOf(publicPattern.exec(path));
}

export function adminMediaPath(address: MediaAddress): string {
  return `/admin${publicMediaPath(address)}`;
}
