import { isNonblank } from "../catalog/scalars.ts";
import type { AuditRecord } from "./audit.ts";
import { applyTransition, assertStockInvariant, StockRejections, type StockLevel } from "./inventory.ts";
import { MaxActorLength, MaxReasonLength, MaxStockQuantity } from "./limits.ts";

export interface StockRow extends StockLevel {
  readonly revision: bigint;
}

export interface StockRead {
  readonly variantExists: boolean;
  readonly row: StockRow | null;
}

export type StockCommand =
  | { readonly kind: "track"; readonly variantId: bigint; readonly onHand: bigint; readonly reason: string }
  | { readonly kind: "adjust"; readonly variantId: bigint; readonly delta: bigint; readonly reason: string; readonly expectedRevision: bigint | null }
  | { readonly kind: "restock"; readonly variantId: bigint; readonly quantity: bigint; readonly restockable: bigint; readonly reason: string }
  | { readonly kind: "hold" | "release_hold" | "allocate" | "allocate_late" | "cancel_allocation" | "ship"; readonly variantId: bigint; readonly quantity: bigint };

export interface StockContext {
  readonly nowSeconds: bigint;
  readonly actor: string;
}

export const StockCommandRejections = [
  ...StockRejections,
  "unknown_variant",
  "already_tracked",
  "untracked",
  "stale_revision",
  "invalid_reason",
  "invalid_actor",
] as const;
export type StockCommandRejection = (typeof StockCommandRejections)[number];

export interface StockAdjustmentRecord {
  readonly variantId: bigint;
  readonly kind: "track" | "adjust" | "restock";
  readonly delta: bigint;
  readonly onHandAfter: bigint;
  readonly reason: string;
  readonly actor: string;
  readonly createdAt: bigint;
}

export type StockWrite =
  | { readonly kind: "insert"; readonly variantId: bigint; readonly level: StockLevel }
  | { readonly kind: "update"; readonly variantId: bigint; readonly level: StockLevel };

export type StockLevelRecord = StockRow & { readonly variantId: bigint };

export type StockDecision =
  | {
    readonly ok: true;
    readonly writes: readonly StockWrite[];
    readonly adjustments: readonly StockAdjustmentRecord[];
    readonly audit: readonly AuditRecord[];
    readonly levels: readonly StockLevelRecord[];
  }
  | { readonly ok: false; readonly rejection: StockCommandRejection; readonly variantId: bigint; readonly commandIndex: number };

function validReason(reason: string): boolean {
  return reason.length <= MaxReasonLength && isNonblank(reason);
}

function validActor(actor: string): boolean {
  return actor.length >= 1 && actor.length <= MaxActorLength && isNonblank(actor) && !/[\u0000-\u001f\u007f]/.test(actor);
}

const AuditActionByKind = { track: "stock.track", adjust: "stock.adjust", restock: "stock.restock" } as const;

export function decideStock(
  reads: ReadonlyMap<bigint, StockRead>,
  commands: readonly StockCommand[],
  context: StockContext,
): StockDecision {
  const working = new Map<bigint, StockLevel | null>();
  const originals = new Map<bigint, StockRow | null>();
  const adjustments: StockAdjustmentRecord[] = [];
  const pendingAudit: { readonly record: Omit<AuditRecord, "entityRevision">; readonly variantId: bigint }[] = [];
  const rejected = (rejection: StockCommandRejection, variantId: bigint, commandIndex: number): StockDecision => ({ ok: false, rejection, variantId, commandIndex });

  if (!validActor(context.actor)) return rejected("invalid_actor", commands[0]?.variantId ?? 0n, 0);

  for (const [commandIndex, command] of commands.entries()) {
    const { variantId } = command;
    const read = reads.get(variantId);
    if (read === undefined) throw new RangeError(`commerce: variant ${variantId} was not read before deciding`);
    if (!read.variantExists) return rejected("unknown_variant", variantId, commandIndex);
    if (!originals.has(variantId)) {
      originals.set(variantId, read.row);
      if (read.row !== null) assertStockInvariant(read.row);
      working.set(variantId, read.row === null ? null : { onHand: read.row.onHand, held: read.row.held, allocated: read.row.allocated });
    }
    const current = working.get(variantId) ?? null;

    if (command.kind === "track") {
      if (!validReason(command.reason)) return rejected("invalid_reason", variantId, commandIndex);
      if (current !== null) return rejected("already_tracked", variantId, commandIndex);
      if (command.onHand < 0n) return rejected("negative_on_hand", variantId, commandIndex);
      if (command.onHand > MaxStockQuantity) return rejected("above_maximum", variantId, commandIndex);
      const level = { onHand: command.onHand, held: 0n, allocated: 0n };
      assertStockInvariant(level);
      working.set(variantId, level);
      adjustments.push({ variantId, kind: "track", delta: command.onHand, onHandAfter: command.onHand, reason: command.reason, actor: context.actor, createdAt: context.nowSeconds });
      pendingAudit.push({ variantId, record: { actor: context.actor, action: AuditActionByKind.track, entityKind: "variant", entityId: variantId.toString(), summary: `tracked with on_hand ${command.onHand}: ${command.reason}` } });
      continue;
    }

    if (current === null) {
      if (command.kind === "adjust" || command.kind === "restock") return rejected("untracked", variantId, commandIndex);
      continue;
    }

    if (command.kind === "adjust") {
      if (!validReason(command.reason)) return rejected("invalid_reason", variantId, commandIndex);
      const original = originals.get(variantId) ?? null;
      if (command.expectedRevision !== null && original !== null && command.expectedRevision !== original.revision) return rejected("stale_revision", variantId, commandIndex);
    }
    if (command.kind === "restock" && !validReason(command.reason)) return rejected("invalid_reason", variantId, commandIndex);

    const outcome = applyTransition(
      current,
      command.kind === "adjust" ? { kind: "adjust", delta: command.delta }
        : command.kind === "restock" ? { kind: "restock", quantity: command.quantity, restockable: command.restockable }
        : { kind: command.kind, quantity: command.quantity },
    );
    if (!outcome.ok) return rejected(outcome.rejection, variantId, commandIndex);
    working.set(variantId, outcome.level);

    if (command.kind === "adjust" || command.kind === "restock") {
      const delta = command.kind === "adjust" ? command.delta : command.quantity;
      adjustments.push({ variantId, kind: command.kind, delta, onHandAfter: outcome.level.onHand, reason: command.reason, actor: context.actor, createdAt: context.nowSeconds });
      pendingAudit.push({ variantId, record: { actor: context.actor, action: AuditActionByKind[command.kind], entityKind: "variant", entityId: variantId.toString(), summary: `${command.kind} ${delta > 0n ? "+" : ""}${delta}, on_hand ${outcome.level.onHand}: ${command.reason}` } });
    }
  }

  const writes: StockWrite[] = [];
  const levels: StockLevelRecord[] = [];
  const revisions = new Map<bigint, bigint>();
  for (const [variantId, original] of originals) {
    const level = working.get(variantId) ?? null;
    if (level === null) continue;
    if (original === null) {
      writes.push({ kind: "insert", variantId, level });
      revisions.set(variantId, 1n);
      levels.push({ variantId, ...level, revision: 1n });
    } else if (level.onHand !== original.onHand || level.held !== original.held || level.allocated !== original.allocated) {
      writes.push({ kind: "update", variantId, level });
      revisions.set(variantId, original.revision + 1n);
      levels.push({ variantId, ...level, revision: original.revision + 1n });
    } else {
      levels.push({ variantId, ...original });
    }
  }
  const audit = pendingAudit.map(({ record, variantId }) => ({ ...record, entityRevision: revisions.get(variantId) ?? originals.get(variantId)?.revision ?? null }));
  return { ok: true, writes, adjustments, audit, levels };
}
