import type { StockLevelView, StockViewModel } from "./operations.ts";
import type { StockCommandRejection } from "../commerce/stock.ts";
import { fragments, html, type Html } from "./html.ts";
import { adminPath } from "../routes/admin.ts";
import { operationsStatusRows } from "../commerce/operations_status.ts";
import type { OperationsStatus } from "../commerce/work_operations.ts";

export interface Notice {
  readonly kind: "info" | "error";
  readonly message: string;
}

export interface FieldErrors {
  readonly [field: string]: string | undefined;
}

export function layout(title: string, signedInAs: string | null, body: Html, head: Html | null = null): Html {
  return html`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>${title}</title>
${head}
</head>
<body>
<header>
<p><a href="${adminPath("admin-home")}">Store admin</a>${signedInAs === null ? "" : html` - signed in as ${signedInAs}`}</p>
${signedInAs === null ? "" : html`<nav aria-label="Admin"><a href="${adminPath("admin-products")}">Products</a> <a href="${adminPath("admin-orders")}">Orders</a> <a href="${adminPath("admin-collections")}">Collections</a> <a href="${adminPath("admin-pages")}">Pages</a> <a href="${adminPath("admin-settings")}">Settings</a> <a href="${adminPath("admin-operations")}">Operations</a></nav>`}
${signedInAs === null ? "" : signOutForm()}
</header>
<main>
<h1>${title}</h1>
${body}
</main>
</body>
</html>
`;
}

function signOutForm(): Html {
  return html`<form method="post" action="${adminPath("admin-sign-out")}"><button type="submit">Sign out</button></form>`;
}

export function noticeBlock(notice: Notice | null): Html {
  if (notice === null) return html``;
  return html`<p role="${notice.kind === "error" ? "alert" : "status"}">${notice.message}</p>`;
}

export function signInPage(notice: Notice | null): Html {
  return layout("Sign in", null, html`${noticeBlock(notice)}<p><a href="${adminPath("admin-sign-in")}">Sign in</a></p>`);
}

export function unauthorizedPage(principal: { readonly issuer: string; readonly subject: string }): Html {
  return layout("Not authorized", `${principal.subject}`, html`<p>This identity is signed in but is not an owner of this store. Ask the store operator to add it.</p>
<dl><dt>Issuer</dt><dd>${principal.issuer}</dd><dt>Subject</dt><dd>${principal.subject}</dd></dl>`);
}

export function homePage(shopId: string, principalLabel: string): Html {
  return layout("Store admin", principalLabel, html`<p>Store <strong>${shopId}</strong>.</p>`);
}

export function operationsPage(status: OperationsStatus, principalLabel: string): Html {
  const rows = operationsStatusRows(status).map((row) => html`<tr><th scope="row">${row.label}</th><td>${row.count}</td><td>${row.count === 0 ? "" : row.oldest}</td></tr>`);
  return layout("Operations", principalLabel, html`${status.held ? html`<p role="alert">Processing is held after a restore. Run <code>nanoshop ops reconcile</code>, then <code>nanoshop ops resume</code>.</p>` : html``}
<p>Counted exactly from this store's records when the page loaded.</p>
<table><thead><tr><th scope="col">Backlog</th><th scope="col">Count</th><th scope="col">Oldest</th></tr></thead><tbody>${rows}</tbody></table>`);
}

export function messagePage(title: string, message: string, principalLabel: string | null): Html {
  return layout(title, principalLabel, html`<p>${message}</p>`);
}

export interface StockFormState {
  readonly view: StockViewModel;
  readonly principalLabel: string;
  readonly formToken: string;
  readonly revision: bigint;
  readonly input: { readonly delta: string; readonly reason: string };
  readonly errors: FieldErrors;
  readonly notice: Notice | null;
  readonly conflict: StockLevelView | null;
}

function levelSummary(level: StockLevelView): Html {
  return html`<dl><dt>On hand</dt><dd>${level.onHand}</dd><dt>Held</dt><dd>${level.held}</dd><dt>Allocated</dt><dd>${level.allocated}</dd><dt>Revision</dt><dd>${level.revision}</dd></dl>`;
}

export function fieldError(errors: FieldErrors, field: string): Html {
  const message = errors[field];
  return message === undefined ? html`` : html`<p id="${field}-error" role="alert">${message}</p>`;
}

export function stockPage(state: StockFormState): Html {
  const { view } = state;
  const name = view.variantTitle === null ? view.productTitle : `${view.productTitle} - ${view.variantTitle}`;
  const history = view.adjustments.length === 0
    ? html`<p>No stock changes yet.</p>`
    : html`<ul>${fragments(view.adjustments.map((entry) => html`<li><time datetime="${new Date(Number(entry.createdAt) * 1000).toISOString()}">${new Date(Number(entry.createdAt) * 1000).toISOString()}</time><br>${entry.kind} ${entry.delta > 0n ? "+" : ""}${entry.delta}, on hand after: ${entry.onHandAfter}<br>${entry.reason} (by ${entry.actor})</li>`))}</ul>`;
  const audit = view.audit.length === 0
    ? html``
    : html`<h2>Audit</h2><ul>${fragments(view.audit.map((entry) => html`<li>${entry.action} by ${entry.actor} at revision ${entry.entityRevision ?? "-"}: ${entry.summary}</li>`))}</ul>`;
  const form = view.level === null
    ? html`<p>This variant is not tracked, so it is always available. Track it to count stock: enter what is on hand now.</p>
<form method="post" action="${adminPath("admin-stock-track", [view.variantId.toString()])}">
<input type="hidden" name="form_token" value="${state.formToken}">
<p><label>Starting stock on hand <input name="on_hand" inputmode="numeric" autocomplete="off" value="${state.input.delta}" aria-describedby="on_hand-error" required></label></p>
${fieldError(state.errors, "on_hand")}
<p><label>Reason <input name="reason" maxlength="400" autocomplete="off" value="${state.input.reason}" aria-describedby="reason-error" required></label></p>
${fieldError(state.errors, "reason")}
<button type="submit">Track stock</button>
</form>`
    : html`${levelSummary(view.level)}
<form method="post" action="${adminPath("admin-stock-adjust", [view.variantId.toString()])}">
<input type="hidden" name="form_token" value="${state.formToken}">
<input type="hidden" name="revision" value="${state.revision}">
<p><label>Change in on-hand stock (use a minus sign to remove) <input name="delta" inputmode="numeric" autocomplete="off" value="${state.input.delta}" aria-describedby="delta-error" required></label></p>
${fieldError(state.errors, "delta")}
<p><label>Reason <input name="reason" maxlength="400" autocomplete="off" value="${state.input.reason}" aria-describedby="reason-error" required></label></p>
${fieldError(state.errors, "reason")}
<button type="submit">Adjust stock</button>
</form>`;
  const conflict = state.conflict === null || view.level === null
    ? html``
    : html`<section aria-label="Conflict"><h2>Compare</h2><div><h3>Your input</h3><dl><dt>Change</dt><dd>${state.input.delta}</dd><dt>Reason</dt><dd>${state.input.reason}</dd></dl></div><div><h3>Current values</h3>${levelSummary(state.conflict)}</div></section>`;
  return layout(`Stock: ${name}`, state.principalLabel, html`${noticeBlock(state.notice)}${conflict}${form}<h2>History</h2>${history}${audit}`);
}

export function describeRejection(rejection: StockCommandRejection): { readonly field: "delta" | "reason" | null; readonly message: string } {
  switch (rejection) {
    case "invalid_reason": return { field: "reason", message: "Enter a reason of at most 500 characters." };
    case "negative_on_hand": return { field: "delta", message: "On-hand stock cannot go below zero." };
    case "would_oversell": return { field: "delta", message: "That would leave less on hand than is held or allocated for orders." };
    case "above_maximum": return { field: "delta", message: "That is above the largest stock quantity allowed (1,000,000,000)." };
    case "invalid_quantity": return { field: "delta", message: "Enter a whole number that is not zero." };
    case "untracked": return { field: null, message: "This variant is not tracked." };
    default: return { field: "delta", message: "That stock change is not allowed." };
  }
}

export function continuePage(target: string): Html {
  return html`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<meta http-equiv="refresh" content="0; url=${target}">
<title>Signed in</title>
</head>
<body>
<main>
<h1>Signed in</h1>
<p><a href="${target}">Continue to the store admin</a></p>
</main>
</body>
</html>
`;
}
