import { addMinor } from "./money.ts";
import type { TaxPolicy, TaxRate } from "./policy.ts";
import { UsRegions } from "./shipping.ts";

export const PpmDenominator = 1_000_000n;

export type TaxPolicyProblem =
  | { readonly kind: "unknown_region"; readonly region: string }
  | { readonly kind: "duplicate_region"; readonly region: string }
  | { readonly kind: "rate_out_of_range"; readonly region: string };

export function validateTaxPolicy(policy: TaxPolicy): readonly TaxPolicyProblem[] {
  if (policy.mode === "no_tax_collected") return [];
  const problems: TaxPolicyProblem[] = [];
  const seen = new Set<string>();
  for (const rate of policy.rates) {
    if (!UsRegions.has(rate.region)) problems.push({ kind: "unknown_region", region: rate.region });
    else if (seen.has(rate.region)) problems.push({ kind: "duplicate_region", region: rate.region });
    seen.add(rate.region);
    if (rate.ratePpm < 0n || rate.ratePpm > PpmDenominator) problems.push({ kind: "rate_out_of_range", region: rate.region });
  }
  return problems;
}

export function roundHalfUpPpm(amountMinor: bigint, ratePpm: bigint): bigint {
  if (ratePpm < 0n || ratePpm > PpmDenominator) throw new RangeError("commerce: tax rate outside 0 to 1,000,000 ppm");
  return (addMinor(amountMinor, 0n) * ratePpm + PpmDenominator / 2n) / PpmDenominator;
}

export type TaxTarget =
  | { readonly kind: "line"; readonly lineIndex: number }
  | { readonly kind: "shipping" };

export interface TaxLine {
  readonly target: TaxTarget;
  readonly taxableMinor: bigint;
  readonly ratePpm: bigint;
  readonly taxMinor: bigint;
}

export interface TaxableAmounts {
  readonly lineTotalsMinor: readonly bigint[];
  readonly shippingMinor: bigint;
}

export type TaxResult =
  | { readonly ok: true; readonly lines: readonly TaxLine[]; readonly totalMinor: bigint }
  | { readonly ok: false; readonly block: { readonly reason: "tax_region_unsupported"; readonly region: string } };

function rateFor(rates: readonly TaxRate[], region: string): TaxRate | undefined {
  return rates.find((rate) => rate.region === region);
}

export function computeTax(policy: TaxPolicy, region: string, amounts: TaxableAmounts): TaxResult {
  let ratePpm = 0n;
  let taxesLines = false;
  let taxesShipping = false;
  if (policy.mode === "rate_table") {
    const rate = rateFor(policy.rates, region);
    if (rate === undefined) return { ok: false, block: { reason: "tax_region_unsupported", region } };
    ratePpm = rate.ratePpm;
    taxesLines = rate.taxesLines;
    taxesShipping = rate.taxesShipping;
  }
  const lines: TaxLine[] = amounts.lineTotalsMinor.map((total, lineIndex) => {
    const taxableMinor = taxesLines ? total : 0n;
    return { target: { kind: "line", lineIndex }, taxableMinor, ratePpm, taxMinor: roundHalfUpPpm(taxableMinor, ratePpm) };
  });
  const shippingTaxable = taxesShipping ? amounts.shippingMinor : 0n;
  lines.push({ target: { kind: "shipping" }, taxableMinor: shippingTaxable, ratePpm, taxMinor: roundHalfUpPpm(shippingTaxable, ratePpm) });
  let totalMinor = 0n;
  for (const line of lines) totalMinor = addMinor(totalMinor, line.taxMinor);
  return { ok: true, lines, totalMinor };
}

export function allocateLargestRemainder(totalMinor: bigint, weights: readonly bigint[]): readonly bigint[] {
  if (totalMinor < 0n) throw new RangeError("commerce: allocation total must not be negative");
  let weightSum = 0n;
  for (const weight of weights) {
    if (weight < 0n) throw new RangeError("commerce: allocation weight must not be negative");
    weightSum += weight;
  }
  if (weightSum === 0n) throw new RangeError("commerce: allocation weights must have a positive sum");
  const shares = weights.map((weight) => (totalMinor * weight) / weightSum);
  const remainders = weights.map((weight, index) => ({ index, remainder: (totalMinor * weight) % weightSum }));
  remainders.sort((left, right) => (left.remainder === right.remainder ? left.index - right.index : left.remainder > right.remainder ? -1 : 1));
  let leftover = totalMinor - shares.reduce((sum, share) => sum + share, 0n);
  for (const { index } of remainders) {
    if (leftover === 0n) break;
    shares[index] = (shares[index] ?? 0n) + 1n;
    leftover -= 1n;
  }
  return shares;
}

export interface RefundTaxRequest {
  readonly lineTaxMinor: bigint;
  readonly orderedQuantity: bigint;
  readonly alreadyRefundedQuantity: bigint;
  readonly refundQuantity: bigint;
}

export function refundTaxForQuantity(request: RefundTaxRequest): bigint {
  const { lineTaxMinor, orderedQuantity, alreadyRefundedQuantity, refundQuantity } = request;
  if (orderedQuantity <= 0n || alreadyRefundedQuantity < 0n || refundQuantity < 0n || alreadyRefundedQuantity + refundQuantity > orderedQuantity) {
    throw new RangeError("commerce: refund quantity outside ordered quantity");
  }
  const base = lineTaxMinor / orderedQuantity;
  const extra = lineTaxMinor % orderedQuantity;
  const end = alreadyRefundedQuantity + refundQuantity;
  const extraInRange = (end < extra ? end : extra) - alreadyRefundedQuantity;
  return refundQuantity * base + (extraInRange > 0n ? extraInRange : 0n);
}
