import { MaxStockQuantity } from "./limits.ts";

export interface StockLevel {
  readonly onHand: bigint;
  readonly held: bigint;
  readonly allocated: bigint;
}

export function sellable(level: StockLevel): bigint {
  return level.onHand - level.held - level.allocated;
}

export class InventoryInvariantError extends Error {
  readonly _tag = "InventoryInvariantError";
  readonly operation = "inventory.invariant";
  constructor(message: string, options?: { readonly cause?: unknown }) { super(`inventory: ${message}`, options); }
}

export function assertStockInvariant(level: StockLevel): void {
  for (const [name, value] of [["on_hand", level.onHand], ["held", level.held], ["allocated", level.allocated]] as const) {
    if (value < 0n || value > MaxStockQuantity) throw new InventoryInvariantError(`${name} ${value} is outside 0..${MaxStockQuantity}`);
  }
  if (sellable(level) < 0n) throw new InventoryInvariantError(`sellable ${sellable(level)} is negative`);
}

export type StockTransition =
  | { readonly kind: "hold"; readonly quantity: bigint }
  | { readonly kind: "release_hold"; readonly quantity: bigint }
  | { readonly kind: "allocate"; readonly quantity: bigint }
  | { readonly kind: "allocate_late"; readonly quantity: bigint }
  | { readonly kind: "cancel_allocation"; readonly quantity: bigint }
  | { readonly kind: "ship"; readonly quantity: bigint }
  | { readonly kind: "restock"; readonly quantity: bigint; readonly restockable: bigint }
  | { readonly kind: "adjust"; readonly delta: bigint };

export const StockRejections = [
  "invalid_quantity",
  "insufficient_stock",
  "hold_missing",
  "allocation_missing",
  "restock_exceeds_returned",
  "above_maximum",
  "negative_on_hand",
  "would_oversell",
] as const;
export type StockRejection = (typeof StockRejections)[number];

export type TransitionOutcome =
  | { readonly ok: true; readonly level: StockLevel }
  | { readonly ok: false; readonly rejection: StockRejection };

const reject = (rejection: StockRejection): TransitionOutcome => ({ ok: false, rejection });

function accept(level: StockLevel): TransitionOutcome {
  assertStockInvariant(level);
  return { ok: true, level };
}

function validQuantity(quantity: bigint): boolean {
  return quantity >= 1n && quantity <= MaxStockQuantity;
}

export function applyTransition(level: StockLevel, transition: StockTransition): TransitionOutcome {
  assertStockInvariant(level);
  if (transition.kind === "adjust") {
    const { delta } = transition;
    if (delta === 0n || delta < -MaxStockQuantity || delta > MaxStockQuantity) return reject("invalid_quantity");
    const onHand = level.onHand + delta;
    if (onHand < 0n) return reject("negative_on_hand");
    if (onHand > MaxStockQuantity) return reject("above_maximum");
    const next = { ...level, onHand };
    return sellable(next) < 0n ? reject("would_oversell") : accept(next);
  }
  const { quantity } = transition;
  if (!validQuantity(quantity)) return reject("invalid_quantity");
  switch (transition.kind) {
    case "hold":
      return sellable(level) < quantity ? reject("insufficient_stock") : accept({ ...level, held: level.held + quantity });
    case "release_hold":
      return level.held < quantity ? reject("hold_missing") : accept({ ...level, held: level.held - quantity });
    case "allocate":
      return level.held < quantity ? reject("hold_missing") : accept({ ...level, held: level.held - quantity, allocated: level.allocated + quantity });
    case "allocate_late":
      return sellable(level) < quantity ? reject("insufficient_stock") : accept({ ...level, allocated: level.allocated + quantity });
    case "cancel_allocation":
      return level.allocated < quantity ? reject("allocation_missing") : accept({ ...level, allocated: level.allocated - quantity });
    case "ship":
      return level.allocated < quantity ? reject("allocation_missing") : accept({ ...level, allocated: level.allocated - quantity, onHand: level.onHand - quantity });
    case "restock":
      if (quantity > transition.restockable) return reject("restock_exceeds_returned");
      return level.onHand + quantity > MaxStockQuantity ? reject("above_maximum") : accept({ ...level, onHand: level.onHand + quantity });
  }
}
