import { BadInput } from "../web/decode.ts";
import { sha256Hex } from "./hash.ts";
import { inspectImage, type InspectedImage } from "./inspect.ts";
import { CardRendition, DetailRendition, MaxOriginalBytes, MaxOriginalEdge, MaxOriginalPixels, MaxRequestBytes } from "./limits.ts";

export type UploadRole = "original" | "card" | "detail";

export interface UploadForm {
  readonly formToken: string;
  readonly revision: string;
  readonly productId: string;
  readonly alt: string;
  readonly original: File | null;
  readonly card: File | null;
  readonly detail: File | null;
}

const textFields = ["form_token", "revision", "product_id", "alt"] as const;
const fileFields = ["original", "card", "detail"] as const;
const MaxTextBytes = 2048;
const encoder = new TextEncoder();

function isMultipart(contentType: string): boolean {
  return /^multipart\/form-data\s*;/i.test(contentType) && /boundary=/i.test(contentType);
}

async function readBounded(request: Request, signal: AbortSignal): Promise<Uint8Array<ArrayBuffer>> {
  const declared = request.headers.get("content-length");
  if (declared !== null && Number(declared) > MaxRequestBytes) throw new BadInput("The upload is larger than 10 MiB.");
  const reader = request.body?.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  if (reader !== undefined) {
    for (;;) {
      signal.throwIfAborted();
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MaxRequestBytes) {
        await reader.cancel();
        throw new BadInput("The upload is larger than 10 MiB.");
      }
      chunks.push(value);
    }
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return bytes;
}

/** Reads a multipart upload form of at most 10 MiB whose fields are exactly the known set, each at most once. */
export async function readUploadForm(request: Request, signal: AbortSignal): Promise<UploadForm> {
  signal.throwIfAborted();
  if (new URL(request.url).search !== "") throw new BadInput("Form submissions take no query parameters.");
  const contentType = request.headers.get("content-type") ?? "";
  if (!isMultipart(contentType)) throw new BadInput("Submit this form from the store admin.");
  const bytes = await readBounded(request, signal);
  let data: FormData;
  try {
    data = await new Response(bytes, { headers: { "content-type": contentType } }).formData();
  } catch {
    throw new BadInput("The upload could not be read.");
  }
  const texts = new Map<string, string>();
  const files = new Map<string, File | null>();
  for (const [name, value] of data) {
    if (texts.has(name) || files.has(name)) throw new BadInput(`Parameter ${JSON.stringify(name)} was given more than once.`);
    if ((textFields as readonly string[]).includes(name)) {
      if (typeof value !== "string" || encoder.encode(value).length > MaxTextBytes || /[\u0000-\u001f\u007f-\u009f\ud800-\udfff]/u.test(value)) {
        throw new BadInput(`Parameter ${JSON.stringify(name)} is not valid text.`);
      }
      texts.set(name, value);
    } else if ((fileFields as readonly string[]).includes(name)) {
      if (typeof value === "string") {
        if (value !== "") throw new BadInput(`Parameter ${JSON.stringify(name)} must be a file.`);
        files.set(name, null);
      } else {
        files.set(name, value.size === 0 && value.name === "" ? null : value);
      }
    } else {
      throw new BadInput(`Unexpected parameter ${JSON.stringify(name)}.`);
    }
  }
  return {
    formToken: texts.get("form_token") ?? "",
    revision: texts.get("revision") ?? "",
    productId: texts.get("product_id") ?? "",
    alt: (texts.get("alt") ?? "").trim(),
    original: files.get("original") ?? null,
    card: files.get("card") ?? null,
    detail: files.get("detail") ?? null,
  };
}

export interface PreparedFile {
  readonly image: InspectedImage;
  readonly sha256: string;
}

export type PreparedUpload =
  | { readonly ok: true; readonly detail: PreparedFile; readonly card: PreparedFile | null }
  | { readonly ok: false; readonly message: string };

const units = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 });
const kib = (bytes: number): string => `${units.format(bytes / 1024)} KiB`;

function judgeEdges(image: InspectedImage, role: UploadRole): string | null {
  const longest = Math.max(image.width, image.height);
  if (role === "original") {
    if (longest > MaxOriginalEdge) return `The image is ${image.width} by ${image.height} pixels; the longest side may be at most ${MaxOriginalEdge}. Resize it and upload it again.`;
    if (image.width * image.height > MaxOriginalPixels) return `The image has ${units.format((image.width * image.height) / 1_000_000)} megapixels; at most 16 are accepted. Resize it and upload it again.`;
    return null;
  }
  const limit = role === "card" ? CardRendition : DetailRendition;
  return longest > limit.maxEdge ? `The ${role} rendition is ${image.width} by ${image.height} pixels; its longest side may be at most ${limit.maxEdge}.` : null;
}

async function prepareOne(file: File, role: UploadRole): Promise<PreparedFile | string> {
  const limit = role === "original" ? MaxOriginalBytes : role === "card" ? CardRendition.maxBytes : DetailRendition.maxBytes;
  if (file.size > limit) return `The ${role === "original" ? "file" : `${role} rendition`} is ${kib(file.size)}; at most ${kib(limit)} is accepted. ${role === "original" ? "Compress or resize it and upload it again." : ""}`.trim();
  const inspected = inspectImage(new Uint8Array(await file.arrayBuffer()));
  if (!inspected.ok) return inspected.message;
  if (role !== "original" && inspected.image.kind === "png") return `The ${role} rendition must be a JPEG or WebP image.`;
  const edges = judgeEdges(inspected.image, role);
  if (edges !== null) return edges;
  return { image: inspected.image, sha256: await sha256Hex(inspected.image.bytes) };
}

/**
 * Validates the files of an upload without decoding pixels: one original, or
 * both a card and a detail rendition. The server never transforms pixels, so
 * a lone original serves as both renditions.
 */
export async function prepareUpload(form: UploadForm): Promise<PreparedUpload> {
  const renditions = form.card !== null || form.detail !== null;
  if (form.original !== null && renditions) return { ok: false, message: "Send either one image or both renditions, not both." };
  if (form.original === null && !renditions) return { ok: false, message: "Choose an image to upload." };
  if (form.original !== null) {
    const detail = await prepareOne(form.original, "original");
    return typeof detail === "string" ? { ok: false, message: detail } : { ok: true, detail, card: null };
  }
  if (form.card === null || form.detail === null) return { ok: false, message: "Both the card and the detail rendition are needed." };
  const card = await prepareOne(form.card, "card");
  if (typeof card === "string") return { ok: false, message: card };
  const detail = await prepareOne(form.detail, "detail");
  return typeof detail === "string" ? { ok: false, message: detail } : { ok: true, detail, card };
}
