import type { QuantityRequest } from "./cancel.ts";
import { MaxOrderLines } from "./cancel.ts";
import { MaxReasonLength } from "./limits.ts";
import type { PaymentState } from "./payment.ts";
import { refundTaxForQuantity } from "./tax.ts";

export const RefundStates = ["pending", "requires_action", "succeeded", "failed", "canceled"] as const;
export type RefundState = (typeof RefundStates)[number];

export const MaxRefundMinor = 999_999_999_999n;

export function refundCounts(state: RefundState): boolean {
  return state === "pending" || state === "requires_action" || state === "succeeded";
}

export function refundSettled(state: RefundState): boolean {
  return state === "succeeded" || state === "failed" || state === "canceled";
}

export function canObserveRefund(from: RefundState, to: RefundState): boolean {
  if (from === to) return false;
  if (from === "failed" || from === "canceled") return false;
  if (from === "succeeded") return to === "failed";
  return true;
}

export interface RefundLineFacts {
  readonly position: bigint;
  readonly orderedQuantity: bigint;
  readonly unitPriceMinor: bigint;
  readonly lineTaxMinor: bigint;
  readonly refundedQuantity: bigint;
}

export interface RefundOrderFacts {
  readonly paymentState: PaymentState;
  readonly capturedMinor: bigint;
  readonly activeRefundedMinor: bigint;
  readonly shippingMinor: bigint;
  readonly shippingTaxMinor: bigint;
  readonly activeShippingRefundedMinor: bigint;
  readonly activeShippingTaxRefundedMinor: bigint;
  readonly lines: readonly RefundLineFacts[];
}

export interface RefundRequest {
  readonly lines: readonly QuantityRequest[];
  readonly shipping: boolean;
  readonly reason: string;
}

export const RefundRejections = [
  "not_captured", "invalid_reason", "empty_refund", "too_many_lines", "unknown_line", "duplicate_line", "invalid_quantity", "exceeds_line_quantity",
  "no_shipping_left", "exceeds_balance",
] as const;
export type RefundRejection = (typeof RefundRejections)[number];

export interface RefundPlanLine {
  readonly position: bigint;
  readonly quantity: bigint;
  readonly itemMinor: bigint;
  readonly taxMinor: bigint;
}

export interface RefundPlan {
  readonly amountMinor: bigint;
  readonly itemsMinor: bigint;
  readonly itemTaxMinor: bigint;
  readonly shippingMinor: bigint;
  readonly shippingTaxMinor: bigint;
  readonly lines: readonly RefundPlanLine[];
}

export type RefundDecision =
  | { readonly ok: true; readonly plan: RefundPlan }
  | { readonly ok: false; readonly rejection: RefundRejection };

export function refundableMinor(order: Pick<RefundOrderFacts, "capturedMinor" | "activeRefundedMinor">): bigint {
  return order.capturedMinor - order.activeRefundedMinor;
}

export function validRefundReason(reason: string): boolean {
  return reason.length >= 1 && reason.length <= MaxReasonLength && reason.trim() === reason && !/[\u0000-\u001f\u007f]/u.test(reason);
}

export function decideRefund(order: RefundOrderFacts, request: RefundRequest): RefundDecision {
  if (order.paymentState !== "captured") return { ok: false, rejection: "not_captured" };
  if (!validRefundReason(request.reason)) return { ok: false, rejection: "invalid_reason" };
  if (request.lines.length > MaxOrderLines) return { ok: false, rejection: "too_many_lines" };
  if (request.lines.length === 0 && !request.shipping) return { ok: false, rejection: "empty_refund" };
  const byPosition = new Map(order.lines.map((line) => [line.position, line]));
  const seen = new Set<bigint>();
  const lines: RefundPlanLine[] = [];
  let itemsMinor = 0n;
  let itemTaxMinor = 0n;
  for (const wanted of request.lines) {
    const line = byPosition.get(wanted.position);
    if (line === undefined) return { ok: false, rejection: "unknown_line" };
    if (seen.has(wanted.position)) return { ok: false, rejection: "duplicate_line" };
    seen.add(wanted.position);
    if (wanted.quantity < 1n) return { ok: false, rejection: "invalid_quantity" };
    if (wanted.quantity + line.refundedQuantity > line.orderedQuantity) return { ok: false, rejection: "exceeds_line_quantity" };
    const itemMinor = line.unitPriceMinor * wanted.quantity;
    const taxMinor = refundTaxForQuantity({
      lineTaxMinor: line.lineTaxMinor, orderedQuantity: line.orderedQuantity, alreadyRefundedQuantity: line.refundedQuantity, refundQuantity: wanted.quantity,
    });
    lines.push({ position: wanted.position, quantity: wanted.quantity, itemMinor, taxMinor });
    itemsMinor += itemMinor;
    itemTaxMinor += taxMinor;
  }
  let shippingMinor = 0n;
  let shippingTaxMinor = 0n;
  if (request.shipping) {
    shippingMinor = order.shippingMinor - order.activeShippingRefundedMinor;
    shippingTaxMinor = order.shippingTaxMinor - order.activeShippingTaxRefundedMinor;
    if (shippingMinor + shippingTaxMinor === 0n) return { ok: false, rejection: "no_shipping_left" };
  }
  const amountMinor = itemsMinor + itemTaxMinor + shippingMinor + shippingTaxMinor;
  if (amountMinor < 1n) return { ok: false, rejection: "empty_refund" };
  if (amountMinor > refundableMinor(order) || amountMinor > MaxRefundMinor) return { ok: false, rejection: "exceeds_balance" };
  return { ok: true, plan: { amountMinor, itemsMinor, itemTaxMinor, shippingMinor, shippingTaxMinor, lines } };
}

export interface ExternalRefundFit {
  readonly paymentState: PaymentState;
  readonly capturedMinor: bigint;
  readonly activeRefundedMinor: bigint;
  readonly amountMinor: bigint;
}

export function externalRefundFits(facts: ExternalRefundFit): boolean {
  return facts.paymentState === "captured" && facts.amountMinor >= 1n && facts.amountMinor <= facts.capturedMinor - facts.activeRefundedMinor;
}
