import { AssertionError, verifyAssertion, type AssertionVerifier, type VerifiedAssertion } from "./assertion.ts";
import type { SignInPurpose } from "./cookie.ts";

/**
 * The seam a production identity adapter plugs into. Nothing past it sees an
 * adapter-specific type: a completed sign-in is a verified principal, the time
 * it authenticated, and the nonce that bound it to the browser that started it.
 */
export interface Authenticator {
  begin(request: { readonly audience: string; readonly nonce: string; readonly purpose: SignInPurpose }): string;
  complete(callback: URL, expected: { readonly audience: string; readonly nowSeconds: number }): Promise<VerifiedAssertion>;
}

export function testAuthenticator(options: { readonly issuerOrigin: string; readonly verifier: AssertionVerifier }): Authenticator {
  return {
    begin: ({ audience, nonce, purpose }) => {
      const url = new URL("/authorize", options.issuerOrigin);
      url.searchParams.set("aud", audience);
      url.searchParams.set("nonce", nonce);
      url.searchParams.set("purpose", purpose);
      return url.href;
    },
    complete: async (callback, expected) => {
      const assertion = callback.searchParams.get("assertion");
      if (assertion === null) throw new AssertionError("malformed");
      return await verifyAssertion(assertion, options.verifier, expected);
    },
  };
}
