import { emailSearchDigest } from "../commerce/keyed_digest.ts";
import { get, run, type Program } from "./program.ts";

export function* searchDigestOf(email: string): Program<Uint8Array> {
  const key = yield* get("GetOrderSearchKey", []);
  if (key === null) throw new Error("orders: the order search key is missing");
  return emailSearchDigest(key.key, email);
}

export function* indexOrderEmail(orderId: bigint): Program<void> {
  const order = yield* get("GetOrderContactEmail", [orderId]);
  if (order === null) throw new Error(`orders: order ${orderId} does not exist`);
  yield* run("SetOrderEmailDigest", [yield* searchDigestOf(order.contact_email), orderId]);
}
