import type { Mutation } from "../admin/guard.ts";
import { all, audit, get, run, stock, type Program } from "../admin/program.ts";
import type { LineFulfillment } from "./fulfillment.ts";
import { queueShipment } from "./email_program.ts";
import { decideShipment, type ShipmentRejection } from "./fulfillment_ship.ts";
import type { PaymentState } from "./payment.ts";

export interface ShipChange {
  readonly number: bigint;
  readonly expectedRevision: bigint;
  readonly lines: readonly { readonly position: bigint; readonly quantity: bigint }[];
  readonly carrier: string;
  readonly trackingNumber: string | null;
  readonly trackingUrl: string | null;
}

export interface ShipContext {
  readonly actor: string;
  readonly nowSeconds: bigint;
}

export type ShipRefusal =
  | { readonly kind: "not_found" }
  | { readonly kind: "stale" }
  | { readonly kind: "rejected"; readonly rejection: ShipmentRejection };

export interface RecordedShipment {
  readonly orderId: bigint;
  readonly orderNumber: bigint;
  readonly sequence: bigint;
  readonly nowSeconds: bigint;
}

export type ShipOutcome = Mutation<{ readonly sequence: bigint }, ShipRefusal>;

const refused = (refusal: ShipRefusal): ShipOutcome => ({ applied: false, result: refusal });

export function* afterShipmentRecorded(shipment: RecordedShipment): Program<void> {
  yield* queueShipment(shipment.orderId, shipment.sequence, shipment.nowSeconds);
}

export function lineFulfillmentOf(row: { readonly quantity: bigint; readonly shipped: bigint; readonly canceled: bigint; readonly returned: bigint; readonly restocked: bigint }): LineFulfillment {
  return { ordered: row.quantity, shipped: row.shipped, canceled: row.canceled, returned: row.returned, restocked: row.restocked };
}

export function* shipEffect(change: ShipChange, context: ShipContext): Program<ShipOutcome> {
  const order = yield* get("GetOrderDetail", [change.number]);
  if (order === null) return refused({ kind: "not_found" });
  if (order.revision !== change.expectedRevision) return refused({ kind: "stale" });
  const exceptions = yield* all("ListOrderExceptions", [order.id]);
  const lineRows = yield* all("ListOrderLineStates", [order.id]);
  const reservations = yield* all("ListAttemptReservations", [order.attempt_id]);
  const trackedVariants = new Set(reservations.filter((reservation) => reservation.tracked === 1n).map((reservation) => reservation.variant_id));
  const decision = decideShipment(
    {
      paymentState: order.payment_state as PaymentState,
      reviewOpen: exceptions.some((entry) => entry.kind === "review" && entry.state === "open"),
      lines: lineRows.map((row) => ({ position: row.position, variantId: row.variant_id, tracked: trackedVariants.has(row.variant_id), fulfillment: lineFulfillmentOf(row) })),
    },
    change,
  );
  if (!decision.ok) return refused({ kind: "rejected", rejection: decision.rejection });

  const tracked = decision.lines.filter((line) => line.tracked);
  if (tracked.length > 0) {
    const shipped = yield* stock(tracked.map((line) => ({ kind: "ship" as const, variantId: line.variantId, quantity: line.quantity })), { nowSeconds: context.nowSeconds, actor: context.actor });
    if (shipped.outcome === "rejected") throw new Error(`fulfillment: shipping order ${order.number} was rejected by inventory (${shipped.rejection})`);
  }

  yield* run("InsertShipment", [order.id, change.carrier, change.trackingNumber, change.trackingUrl, context.actor, context.nowSeconds, order.id]);
  const sequence = (yield* get("GetShipmentSequence", [order.id]))?.sequence ?? 0n;
  for (const line of decision.lines) {
    yield* run("InsertShipmentLine", [line.position, line.quantity, order.id, sequence]);
    yield* run("AddLineShipped", [line.quantity, order.id, line.position]);
  }
  if ((yield* run("BumpOrderRevision", [order.id, order.revision])) !== 1n) throw new Error(`fulfillment: order ${order.number} changed during shipment`);

  const titles = new Map(lineRows.map((row) => [row.position, row.title]));
  const summary = `shipment ${sequence} via ${change.carrier}: ${decision.lines.map((line) => `${line.quantity} x ${titles.get(line.position) ?? "item"}`).join(", ")}`.slice(0, 1000);
  yield* audit({ actor: context.actor, action: "fulfillment.create", entityKind: "order", entityId: order.id.toString(), entityRevision: order.revision + 1n, summary }, context.nowSeconds);
  yield* afterShipmentRecorded({ orderId: order.id, orderNumber: order.number, sequence, nowSeconds: context.nowSeconds });
  return { applied: true, result: { sequence } };
}
