import { ADMIN_ROUTES, type AdminRouteName } from "../../routes/admin.ts";
import { ROUTES, type RouteName } from "../../routes/routes.ts";
import { COMMERCE_EXCEPTIONS, RPC_METHODS, type CommerceException, type OperationName, type RpcMethod } from "../../observe/operations.ts";

export type RequestOperation = `request.${RouteName}` | `request.${AdminRouteName}` | "request.unmatched";

export const COMMERCE_RPC_METHODS = ["commerceCommand", "commerceQuery"] as const;
export type CommerceRpcMethod = (typeof COMMERCE_RPC_METHODS)[number];

export type ErrorOperation =
  | Extract<OperationName, RequestOperation | "catalog.load" | "catalog.rejected" | `store.rpc.${RpcMethod}`>
  | `store.rpc.${CommerceRpcMethod}`
  | "store.alarm"
  | CommerceException;

export type CaughtReporter = (operation: ErrorOperation, error: unknown) => void;

export interface InvocationObserver {
  readonly markInvocation: () => void;
  readonly reportCaught: CaughtReporter;
}

const ROUTE_SEGMENTS = (Object.keys(ROUTES) as RouteName[]).map((name) => ({
  name,
  segments: ROUTES[name].pattern.slice(1).split("/"),
}));

const ADMIN_ROUTE_SEGMENTS = (Object.keys(ADMIN_ROUTES) as AdminRouteName[]).map((name) => ({
  name,
  segments: ADMIN_ROUTES[name].pattern.slice(1).split("/"),
}));

export function errorOperations(): readonly ErrorOperation[] {
  return [
    ...(Object.keys(ROUTES) as RouteName[]).map((name) => `request.${name}` as const),
    ...(Object.keys(ADMIN_ROUTES) as AdminRouteName[]).map((name) => `request.${name}` as const),
    "request.unmatched",
    "catalog.load",
    "catalog.rejected",
    ...RPC_METHODS.map((method) => `store.rpc.${method}` as const),
    ...COMMERCE_RPC_METHODS.map((method) => `store.rpc.${method}` as const),
    "store.alarm",
    ...COMMERCE_EXCEPTIONS,
  ];
}

export function requestOperation(pathname: string): RequestOperation {
  const segments = pathname.slice(1).split("/");
  for (const route of ADMIN_ROUTE_SEGMENTS) {
    if (
      route.segments.length === segments.length &&
      route.segments.every((expected, index) => {
        const actual = segments[index];
        return expected.startsWith("{") ? actual !== "" : actual === expected;
      })
    ) {
      return `request.${route.name}`;
    }
  }
  for (const route of ROUTE_SEGMENTS) {
    if (
      route.segments.length === segments.length &&
      route.segments.every((expected, index) => {
        const actual = segments[index];
        return expected.startsWith("{") ? actual !== "" : actual === expected;
      })
    ) {
      return `request.${route.name}`;
    }
  }
  return "request.unmatched";
}
