import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const NullableText = Schema.NullOr(Text);

export const orderRowSchemas = {
  ListOrders: Schema.Struct({
    number: Integer, placed_at: Integer, contact_email: Text, currency_code: Text, currency_exponent: Integer, total_minor: Integer, fulfillment: Text, fulfillment_status: Text,
    payment_state: Text, open_exceptions: Integer, item_count: Integer,
  }),
  GetOrderDetail: Schema.Struct({
    id: Integer, number: Integer, revision: Integer, attempt_id: Integer, contact_email: Text, currency_code: Text, currency_exponent: Integer, fulfillment: Text, fulfillment_status: Text,
    recipient: NullableText, line1: NullableText, line2: NullableText, city: NullableText, region: NullableText, postal_code: NullableText, country: NullableText,
    shipping_zone: NullableText, merchandise_minor: Integer, shipping_minor: Integer, shipping_tax_minor: Integer, tax_minor: Integer, total_minor: Integer,
    allocation: Text, placed_at: Integer, payment_intent_id: Text, payment_state: Text, amount_authorized_minor: Integer, amount_captured_minor: Integer,
  }),
  ListOrderLineStates: Schema.Struct({
    position: Integer, variant_id: Integer, title: Text, variant_label: Text, unit_price_minor: Integer, quantity: Integer, line_total_minor: Integer,
    tax_minor: Integer, shipped: Integer, canceled: Integer, returned: Integer, restocked: Integer,
  }),
  ListOrderShipments: Schema.Struct({ id: Integer, sequence: Integer, carrier: Text, tracking_number: NullableText, tracking_url: NullableText, actor: Text, shipped_at: Integer }),
  ListOrderShipmentLines: Schema.Struct({ fulfillment_id: Integer, position: Integer, quantity: Integer }),
  ListOrderNotes: Schema.Struct({ id: Integer, body: Text, actor: Text, created_at: Integer }),
  ListOrderTimeline: Schema.Struct({ id: Integer, actor: Text, action: Text, summary: Text, created_at: Integer }),
  ListOrderRefunds: Schema.Struct({ id: Integer, state: Text, amount_minor: Integer, reason: Text, failure_reason: NullableText, created_at: Integer }),
  GetShipmentSequence: Schema.Struct({ sequence: Integer }),
  GetOrderSearchKey: Schema.Struct({ key: Schema.instanceOf(Uint8Array) }),
  GetOrderContactEmail: Schema.Struct({ contact_email: Text }),
} as const;

export const orderWriteQueries = [
  "InsertShipment", "InsertShipmentLine", "AddLineShipped", "BumpOrderRevision", "InsertOrderNote", "SetOrderEmailDigest",
] as const;
