import type { AdminBackend } from "../admin/backend.ts";
import { CreateSessionKind } from "../checkout/program.ts";
import type { HostedSessionCreator } from "../checkout/session_creator.ts";
import type { CheckoutSession, PaymentIntent, StripeClient, StripeEvent } from "../stripe/index.ts";
import { CancellationReasons, isOutcomeUnknown, StripeApiError } from "../stripe/index.ts";
import { holdIsPinned } from "./attempt.ts";
import { IdempotencyWindowSeconds, needsReconciliation } from "./operation.ts";
import type { IntentFacts } from "./payment.ts";
import type { AttemptPaymentView, AuthorizeOutcome } from "./payment_operations.ts";
import { CancelIntentKind, CaptureKind, HoldExpiryKind, PaymentReconcileKind } from "./payment_program.ts";
import { refundEventHandler, refundWork } from "./refund_handlers.ts";
import { RefundKind } from "./refund_program.ts";
import { WorkError } from "./work.ts";
import { asWorkError, ProviderEventHandlers, type ProviderEventContext } from "./work_kinds.ts";
import type { WorkContext, WorkHandler, WorkRegistry } from "./work_runner.ts";

export const PaymentReconcileIntervalSeconds = 15 * 60;
export const SearchPageLimit = 10;

export interface PaymentSettings {
  readonly tenantId: string;
  readonly livemode: boolean;
}

export interface PaymentDependencies {
  readonly settings: PaymentSettings;
  readonly stripe: () => StripeClient;
  readonly sessions: HostedSessionCreator;
  readonly checkoutOrigin: string;
}

interface Run {
  readonly backend: AdminBackend;
  readonly nowSeconds: () => number;
  readonly signal: AbortSignal | undefined;
}

function message(error: unknown): string {
  return (error instanceof Error ? error.message : String(error)).slice(0, 500);
}

function isRejection(error: unknown): boolean {
  return error instanceof StripeApiError && !isOutcomeUnknown(error) && !error.isIdempotencyMismatch && [400, 402, 404].includes(error.status);
}

function optionalPayloadField(payload: string, field: string): string | null {
  let parsed: unknown;
  try { parsed = JSON.parse(payload); } catch (cause) { throw new WorkError("permanent", "work payload is not JSON", { cause }); }
  const value = typeof parsed === "object" && parsed !== null ? (parsed as Record<string, unknown>)[field] : undefined;
  return typeof value === "string" ? value : null;
}

function payloadField(payload: string, field: string): string {
  let parsed: unknown;
  try { parsed = JSON.parse(payload); } catch (cause) { throw new WorkError("permanent", "work payload is not JSON", { cause }); }
  const value = typeof parsed === "object" && parsed !== null ? (parsed as Record<string, unknown>)[field] : undefined;
  if (typeof value !== "string") throw new WorkError("permanent", `work payload has no ${field}`);
  return value;
}

async function intentFacts(stripe: StripeClient, intent: PaymentIntent, usedPaymentMethodType: string | null): Promise<IntentFacts> {
  const review = intent.reviewId === null ? null : await stripe.retrieveReview(intent.reviewId);
  return {
    id: intent.id,
    status: intent.status,
    amountCapturable: intent.amountCapturable,
    amountReceived: intent.amountReceived,
    currency: intent.currency,
    livemode: intent.livemode,
    captureMethod: intent.captureMethod,
    paymentMethodTypes: intent.paymentMethodTypes,
    usedPaymentMethodType,
    metadataTenant: intent.metadata["nanoshop_tenant"] ?? null,
    metadataAttempt: intent.metadata["nanoshop_attempt"] ?? null,
    reviewId: intent.reviewId,
    reviewOpen: review?.open === true,
  };
}

export async function retrieveFacts(stripe: StripeClient, intentId: string): Promise<IntentFacts> {
  const intent = await stripe.retrievePaymentIntent(intentId);
  return await intentFacts(stripe, intent, intent.usedPaymentMethodType);
}

async function authorize(run: Run, settings: PaymentSettings, attemptRef: string, facts: IntentFacts): Promise<AuthorizeOutcome> {
  const result = await run.backend.command({
    kind: "payment.authorize", tenantId: settings.tenantId, livemode: settings.livemode, attemptRef, intent: facts, nowSeconds: run.nowSeconds(),
  }, run.signal);
  return result.outcome;
}

function ownAttempt(settings: PaymentSettings, metadata: Readonly<Record<string, string>>): string | null {
  const attempt = metadata["nanoshop_attempt"];
  return metadata["nanoshop_tenant"] === settings.tenantId && attempt !== undefined && /^[0-9a-f]{32}$/.test(attempt) ? attempt : null;
}

async function processIntentById(run: Run, settings: PaymentSettings, stripe: StripeClient, intentId: string): Promise<void> {
  const facts = await retrieveFacts(stripe, intentId);
  const payment = await run.backend.query({ kind: "payment.intent", paymentIntentId: intentId }, run.signal);
  if (payment.payment !== null) {
    await run.backend.command({ kind: "payment.observe", intent: facts, nowSeconds: run.nowSeconds() }, run.signal);
    return;
  }
  const attemptRef = facts.metadataTenant === settings.tenantId ? facts.metadataAttempt : null;
  if (attemptRef === null || !/^[0-9a-f]{32}$/.test(attemptRef)) return;
  await authorize(run, settings, attemptRef, facts);
}

async function processSession(run: Run, settings: PaymentSettings, stripe: StripeClient, session: CheckoutSession): Promise<AuthorizeOutcome | null> {
  const attemptRef = ownAttempt(settings, session.metadata);
  if (attemptRef === null || session.clientReferenceId !== attemptRef || session.paymentIntentId === null) return null;
  return await authorize(run, settings, attemptRef, await retrieveFacts(stripe, session.paymentIntentId));
}

async function attemptView(run: Run, attemptRef: string): Promise<AttemptPaymentView> {
  const { attempt } = await run.backend.query({ kind: "payment.attempt", attemptRef }, run.signal);
  if (attempt === null) throw new WorkError("permanent", `attempt ${attemptRef} does not exist`);
  return attempt;
}

type SessionOutcome = { readonly kind: "recorded"; readonly sessionId: string } | { readonly kind: "absent" } | { readonly kind: "stopped" };

async function settle(run: Run, opKind: "create_session" | "capture" | "cancel_pi" | "expire_session", subject: string, to: "succeeded" | "failed" | "unknown" | "blocked", detail: { readonly providerObjectId?: string; readonly error?: string; readonly attemptRef?: string } = {}): Promise<void> {
  await run.backend.command({
    kind: "payment.op.settle", opKind, subject, to, providerObjectId: detail.providerObjectId ?? null, error: detail.error ?? null, attemptRef: detail.attemptRef ?? null, nowSeconds: run.nowSeconds(),
  }, run.signal);
}

async function createSession(run: Run, dependencies: PaymentDependencies, view: AttemptPaymentView): Promise<SessionOutcome> {
  const begun = await run.backend.command({ kind: "payment.op.begin", tenantId: dependencies.settings.tenantId, opKind: "create_session", subject: view.ref, nowSeconds: run.nowSeconds() }, run.signal);
  if (begun.outcome !== "started") return { kind: "stopped" };
  let session;
  try {
    session = await dependencies.sessions.create({ attemptRef: view.ref, idempotencyKey: begun.operation.key, quote: view.quote, acceptedAtSeconds: Number(view.acceptedAt) });
  } catch (error) {
    if (isRejection(error)) {
      await settle(run, "create_session", view.ref, "failed", { error: message(error) });
      if (!withinKeyWindow(begun.operation.createdAt, run.nowSeconds())) return { kind: "stopped" };
      await run.backend.command({ kind: "payment.release", attemptRef: view.ref, nowSeconds: run.nowSeconds() }, run.signal);
      return { kind: "absent" };
    }
    if (error instanceof StripeApiError && error.isIdempotencyMismatch) {
      await settle(run, "create_session", view.ref, "blocked", { error: message(error), attemptRef: view.ref });
      return { kind: "stopped" };
    }
    if (isOutcomeUnknown(error)) await settle(run, "create_session", view.ref, "unknown", { error: message(error) });
    throw asWorkError(error);
  }
  if (new URL(session.url).origin !== dependencies.checkoutOrigin) {
    await settle(run, "create_session", view.ref, "blocked", { error: "the hosted session URL is outside the configured Checkout origin", attemptRef: view.ref });
    return { kind: "stopped" };
  }
  await run.backend.command({
    kind: "checkout.session.record", attemptRef: view.ref, sessionId: session.sessionId, sessionUrl: session.url, sessionExpiresAt: session.expiresAtSeconds, nowSeconds: run.nowSeconds(),
  }, run.signal);
  return { kind: "recorded", sessionId: session.sessionId };
}

function withinKeyWindow(createdAt: number, nowSeconds: number): boolean {
  return nowSeconds - createdAt < IdempotencyWindowSeconds;
}

function createSessionWork(dependencies: PaymentDependencies): WorkHandler {
  return async (item, context) => {
    const view = await attemptView(context, payloadField(item.payload, "attempt"));
    if (view.sessionId !== null) return;
    if (view.createSession !== null && !withinKeyWindow(view.createSession.createdAt, context.nowSeconds())) return;
    if (view.state === "accepted" || (view.state === "superseded" && view.createSession !== null && needsReconciliation(view.createSession.state))) {
      await createSession(context, dependencies, view);
    }
  };
}

async function searchForAttempt(run: Run, dependencies: PaymentDependencies, view: AttemptPaymentView): Promise<"resolved" | "absent" | "blocked"> {
  let page;
  try {
    page = await dependencies.stripe().searchPaymentIntents({ query: `metadata['nanoshop_attempt']:'${view.ref}'`, limit: SearchPageLimit });
  } catch (error) {
    if (error instanceof StripeApiError && !isOutcomeUnknown(error)) {
      await run.backend.command({ kind: "payment.block", attemptRef: view.ref, exception: "operation_blocked", objectId: `search:${view.ref}`, detail: `PaymentIntent Search failed (${error.code ?? error.status}); the attempt has no session id and needs operator review`, nowSeconds: run.nowSeconds() }, run.signal);
      return "blocked";
    }
    throw asWorkError(error);
  }
  let resolved = false;
  for (const intent of page.data) {
    if (intent.metadata["nanoshop_tenant"] !== dependencies.settings.tenantId) continue;
    const outcome = await authorize(run, dependencies.settings, view.ref, await retrieveFacts(dependencies.stripe(), intent.id));
    if (outcome !== "canceled" && outcome !== "not_yet" && outcome !== "foreign") resolved = true;
  }
  return resolved ? "resolved" : "absent";
}

async function resolveCompleted(run: Run, dependencies: PaymentDependencies, view: AttemptPaymentView, session: CheckoutSession): Promise<void> {
  const outcome = await processSession(run, dependencies.settings, dependencies.stripe(), session);
  if (outcome === "canceled") {
    await run.backend.command({ kind: "payment.release", attemptRef: view.ref, nowSeconds: run.nowSeconds() }, run.signal);
    return;
  }
  if (outcome === null || outcome === "not_yet" || outcome === "foreign" || outcome === "not_found") {
    await run.backend.command({ kind: "payment.block", attemptRef: view.ref, exception: "unmapped_state", objectId: session.id, detail: `the Checkout Session is complete but its payment could not be verified (${outcome ?? "no PaymentIntent"})`, nowSeconds: run.nowSeconds() }, run.signal);
  }
}

async function expireSession(run: Run, dependencies: PaymentDependencies, view: AttemptPaymentView, sessionId: string): Promise<void> {
  const stripe = dependencies.stripe();
  let session = await stripe.retrieveCheckoutSession(sessionId);
  if (session.status === "open") {
    const begun = await run.backend.command({ kind: "payment.op.begin", tenantId: dependencies.settings.tenantId, opKind: "expire_session", subject: view.ref, nowSeconds: run.nowSeconds() }, run.signal);
    if (begun.outcome === "blocked") return;
    if (begun.outcome === "started") {
      try {
        session = await stripe.expireCheckoutSession(sessionId, begun.operation.key);
      } catch (error) {
        if (isOutcomeUnknown(error)) {
          await settle(run, "expire_session", view.ref, "unknown", { error: message(error) });
          throw asWorkError(error);
        }
        if (!isRejection(error)) throw asWorkError(error);
        await settle(run, "expire_session", view.ref, "failed", { error: message(error) });
        session = await stripe.retrieveCheckoutSession(sessionId);
      }
    }
  }
  if (session.status === "expired") {
    await settle(run, "expire_session", view.ref, "succeeded", { providerObjectId: sessionId });
    await run.backend.command({ kind: "payment.release", attemptRef: view.ref, nowSeconds: run.nowSeconds() }, run.signal);
    return;
  }
  if (session.status === "complete") {
    await resolveCompleted(run, dependencies, view, session);
    return;
  }
  throw new WorkError("retryable", `checkout session ${sessionId} is still open after the expire request`);
}

function holdExpiryWork(dependencies: PaymentDependencies): WorkHandler {
  return async (item, context) => {
    let view = await attemptView(context, payloadField(item.payload, "attempt"));
    if (!holdIsPinned(view.state) || view.state === "blocked") return;
    if (BigInt(context.nowSeconds()) < view.holdReleaseAfter) throw new WorkError("retryable", `the hold of attempt ${view.ref} is not due until ${view.holdReleaseAfter}`);
    if (view.sessionId === null) {
      const create = view.createSession;
      if (create !== null && create.state === "blocked") return;
      if (create === null || (create.state === "failed" && withinKeyWindow(create.createdAt, context.nowSeconds()))) {
        await context.backend.command({ kind: "payment.release", attemptRef: view.ref, nowSeconds: context.nowSeconds() }, context.signal);
        return;
      }
      if (withinKeyWindow(create.createdAt, context.nowSeconds())) {
        const created = await createSession(context, dependencies, view);
        if (created.kind !== "recorded") return;
        view = await attemptView(context, view.ref);
        if (!holdIsPinned(view.state) || view.sessionId === null) return;
      } else {
        const searched = await searchForAttempt(context, dependencies, view);
        if (searched === "absent") await context.backend.command({ kind: "payment.release", attemptRef: view.ref, nowSeconds: context.nowSeconds() }, context.signal);
        return;
      }
    }
    await expireSession(context, dependencies, view, view.sessionId!);
  };
}

function captureWork(dependencies: PaymentDependencies): WorkHandler {
  return async (item, context) => {
    const intentId = payloadField(item.payload, "intent");
    const { payment } = await context.backend.query({ kind: "payment.intent", paymentIntentId: intentId }, context.signal);
    if (payment === null) throw new WorkError("permanent", `no payment exists for PaymentIntent ${intentId}`);
    if (payment.state === "captured" || payment.state === "voided" || payment.state === "in_review") return;
    const stripe = dependencies.stripe();
    const observed = await context.backend.command({ kind: "payment.observe", intent: await retrieveFacts(stripe, intentId), nowSeconds: context.nowSeconds() }, context.signal);
    if (observed.outcome !== "capturable" || observed.state === "in_review") return;
    const begun = await context.backend.command({ kind: "payment.capture.begin", tenantId: dependencies.settings.tenantId, paymentIntentId: intentId, nowSeconds: context.nowSeconds() }, context.signal);
    if (begun.outcome !== "capture") return;
    let captured: PaymentIntent;
    try {
      captured = await stripe.capturePaymentIntent(intentId, { amountToCapture: begun.amountMinor }, begun.key);
    } catch (error) {
      if (isOutcomeUnknown(error)) {
        await settle(context, "capture", intentId, "unknown", { error: message(error) });
        throw asWorkError(error);
      }
      const after = await retrieveFacts(stripe, intentId);
      const observed = await context.backend.command({ kind: "payment.observe", intent: after, nowSeconds: context.nowSeconds() }, context.signal);
      if (observed.outcome === "capturable") await settle(context, "capture", intentId, "blocked", { error: message(error) });
      return;
    }
    await context.backend.command({ kind: "payment.observe", intent: await intentFacts(stripe, captured, null), nowSeconds: context.nowSeconds() }, context.signal);
  };
}

function cancelIntentWork(dependencies: PaymentDependencies): WorkHandler {
  return async (item, context) => {
    const intentId = payloadField(item.payload, "intent");
    const attemptRef = payloadField(item.payload, "attempt");
    const requested = optionalPayloadField(item.payload, "reason");
    const cancellationReason = CancellationReasons.find((candidate) => candidate === requested) ?? "abandoned";
    const stripe = dependencies.stripe();
    const facts = await retrieveFacts(stripe, intentId);
    if (facts.status === "canceled") {
      await settle(context, "cancel_pi", intentId, "succeeded", { providerObjectId: intentId, attemptRef });
      await observeCanceled(context, facts);
      return;
    }
    if (facts.status !== "requires_capture") {
      await settle(context, "cancel_pi", intentId, "blocked", { error: `the PaymentIntent is ${facts.status} and cannot be canceled`, attemptRef });
      return;
    }
    const begun = await context.backend.command({ kind: "payment.op.begin", tenantId: dependencies.settings.tenantId, opKind: "cancel_pi", subject: intentId, nowSeconds: context.nowSeconds() }, context.signal);
    if (begun.outcome !== "started") return;
    try {
      await stripe.cancelPaymentIntent(intentId, { cancellationReason }, begun.operation.key);
    } catch (error) {
      if (isOutcomeUnknown(error)) {
        await settle(context, "cancel_pi", intentId, "unknown", { error: message(error) });
        throw asWorkError(error);
      }
      const after = await retrieveFacts(stripe, intentId);
      if (after.status !== "canceled") {
        await settle(context, "cancel_pi", intentId, "blocked", { error: message(error), attemptRef });
        return;
      }
    }
    await settle(context, "cancel_pi", intentId, "succeeded", { providerObjectId: intentId, attemptRef });
    await observeCanceled(context, await retrieveFacts(stripe, intentId));
  };
}

async function observeCanceled(run: Run, facts: IntentFacts): Promise<void> {
  const { payment } = await run.backend.query({ kind: "payment.intent", paymentIntentId: facts.id }, run.signal);
  if (payment !== null) await run.backend.command({ kind: "payment.observe", intent: facts, nowSeconds: run.nowSeconds() }, run.signal);
}

async function reconcile(_item: unknown, context: WorkContext): Promise<void> {
  await context.backend.command({ kind: "payment.sweep", nowSeconds: context.nowSeconds() }, context.signal);
}

function classified(handler: WorkHandler): WorkHandler {
  return async (item, context) => {
    try {
      return await handler(item, context);
    } catch (error) {
      throw asWorkError(error);
    }
  };
}

export function registerPaymentKinds(registry: WorkRegistry, dependencies: PaymentDependencies): WorkRegistry {
  return registry
    .register(CreateSessionKind, classified(createSessionWork(dependencies)))
    .register(HoldExpiryKind, classified(holdExpiryWork(dependencies)))
    .register(CaptureKind, classified(captureWork(dependencies)))
    .register(CancelIntentKind, classified(cancelIntentWork(dependencies)))
    .register(RefundKind, classified(refundWork(dependencies)))
    .register(PaymentReconcileKind, reconcile, { periodicSeconds: PaymentReconcileIntervalSeconds });
}

function eventRun(context: ProviderEventContext): Run {
  return { backend: context.backend, nowSeconds: context.nowSeconds, signal: context.signal };
}

function objectString(event: StripeEvent, field: string): string | null {
  const value = event.object[field];
  return typeof value === "string" ? value : null;
}

export function paymentEventHandlers(settings: PaymentSettings): ProviderEventHandlers {
  const onSession = async (event: StripeEvent, context: ProviderEventContext): Promise<void> => {
    await processSession(eventRun(context), settings, context.stripe, await context.stripe.retrieveCheckoutSession(event.objectId));
  };
  const onIntent = async (event: StripeEvent, context: ProviderEventContext): Promise<void> => {
    await processIntentById(eventRun(context), settings, context.stripe, event.objectId);
  };
  const acknowledge = async (): Promise<void> => {};
  const onReview = async (event: StripeEvent, context: ProviderEventContext): Promise<void> => {
    const review = await context.stripe.retrieveReview(event.objectId);
    if (review.paymentIntentId === null) return;
    await context.backend.command({ kind: "payment.review", paymentIntentId: review.paymentIntentId, reviewId: review.id, open: review.open, closedReason: review.closedReason, nowSeconds: context.nowSeconds() }, context.signal);
  };
  const onDispute = async (event: StripeEvent, context: ProviderEventContext): Promise<void> => {
    const dispute = await context.stripe.retrieveDispute(event.objectId);
    if (dispute.paymentIntentId === null) return;
    const open = !["won", "lost"].includes(dispute.status);
    await context.backend.command({
      kind: "payment.flag", paymentIntentId: dispute.paymentIntentId, exception: "dispute", objectId: dispute.id, open,
      detail: `dispute ${dispute.status} (${dispute.reason}) for ${dispute.amount} ${dispute.currency}; respond in the Stripe dashboard`, nowSeconds: context.nowSeconds(),
    }, context.signal);
  };
  const onFraudWarning = async (event: StripeEvent, context: ProviderEventContext): Promise<void> => {
    const intentId = objectString(event, "payment_intent");
    if (intentId === null) return;
    await context.backend.command({
      kind: "payment.flag", paymentIntentId: intentId, exception: "early_fraud_warning", objectId: event.objectId, open: true,
      detail: `early fraud warning (${objectString(event, "fraud_type") ?? "unspecified"}); review in the Stripe dashboard`, nowSeconds: context.nowSeconds(),
    }, context.signal);
  };
  const onRefund = refundEventHandler();
  return new ProviderEventHandlers()
    .on("checkout.session.completed", onSession)
    .on("checkout.session.async_payment_succeeded", onSession)
    .on("checkout.session.async_payment_failed", onSession)
    .on("checkout.session.expired", acknowledge)
    .on("payment_intent.amount_capturable_updated", onIntent)
    .on("payment_intent.succeeded", onIntent)
    .on("payment_intent.canceled", onIntent)
    .on("payment_intent.payment_failed", acknowledge)
    .on("refund.created", onRefund)
    .on("refund.updated", onRefund)
    .on("refund.failed", onRefund)
    .on("charge.dispute.created", onDispute)
    .on("charge.dispute.updated", onDispute)
    .on("charge.dispute.closed", onDispute)
    .on("radar.early_fraud_warning.created", onFraudWarning)
    .on("review.opened", onReview)
    .on("review.closed", onReview);
}
