import { buildAdminQueries } from "../admin/queries.ts";
import type { ProgramQueries } from "../admin/program.ts";
import { buildCommerceQueries } from "../commerce/queries.ts";
import type { Program } from "../dsl/program.ts";
import { MigrationRunner, type Migration } from "../storefront/migrations.ts";
import { buildStorefrontQueries, type StorefrontQueries } from "../storefront/queries.ts";

export interface EmbeddedPayments {
  readonly mode: "test" | "live";
  readonly apiBase: string | null;
}

export interface EmbeddedEmail {
  readonly from: string;
  readonly replyTo: string | null;
  readonly apiBase: string | null;
}

export interface EmbeddedPersistenceBundle {
  readonly queries: Readonly<Record<string, string>>;
  readonly commerceQueries?: Readonly<Record<string, string>>;
  readonly adminQueries?: Readonly<Record<string, string>>;
  readonly migrations: readonly Migration[];
  readonly originHost?: string;
  readonly shop?: EmbeddedShop;
  readonly payments?: EmbeddedPayments | null;
  readonly email?: EmbeddedEmail | null;
}

export interface EmbeddedShop {
  readonly tenantId: string;
  readonly origin: string;
}

export interface EmbeddedRevisionManifest {
  readonly id: string;
  readonly themeName: string;
  readonly themeIdentity: string;
  readonly settingsIdentity: string;
  readonly stylesheetUrl: string;
  readonly pages: Readonly<Record<string, Program>>;
}

export interface EmbeddedTenantManifest {
  readonly id: string;
  readonly workerName: string;
  readonly origin: { readonly scheme: "http" | "https"; readonly host: string };
  readonly imageHosts: readonly string[];
  readonly contractIdentity: string;
  readonly revision: EmbeddedRevisionManifest;
}

let activeBundle: {
  readonly queries: StorefrontQueries;
  readonly migrations: MigrationRunner;
  readonly program: ProgramQueries | null;
  readonly originHost: string | null;
  readonly shop: EmbeddedShop | null;
  readonly payments: EmbeddedPayments | null;
  readonly email: EmbeddedEmail | null;
} | null = null;

export function setEmbeddedPersistenceBundle(bundle: EmbeddedPersistenceBundle): void {
  activeBundle = {
    queries: buildStorefrontQueries(new Map(Object.entries(bundle.queries))),
    migrations: new MigrationRunner(bundle.migrations),
    originHost: bundle.originHost ?? null,
    shop: bundle.shop ?? null,
    payments: bundle.payments ?? null,
    email: bundle.email ?? null,
    program: bundle.commerceQueries === undefined || bundle.adminQueries === undefined
      ? null
      : { commerce: buildCommerceQueries(new Map(Object.entries(bundle.commerceQueries))), admin: buildAdminQueries(new Map(Object.entries(bundle.adminQueries))) },
  };
}

export function getEmbeddedPersistenceBundle(): {
  readonly queries: StorefrontQueries;
  readonly migrations: MigrationRunner;
} {
  if (activeBundle === null) {
    throw new Error("cloudflare: persistence bundle has not been initialized");
  }
  return activeBundle;
}

export function getEmbeddedProgramQueries(): ProgramQueries {
  if (activeBundle?.program == null) {
    throw new Error("cloudflare: commerce and admin queries are not part of this bundle");
  }
  return activeBundle.program;
}

export function getEmbeddedOriginHost(): string | null {
  return activeBundle?.originHost ?? null;
}

export function getEmbeddedPayments(): EmbeddedPayments | null {
  return activeBundle?.payments ?? null;
}

export function getEmbeddedEmail(): EmbeddedEmail | null {
  return activeBundle?.email ?? null;
}

export function getEmbeddedShop(): EmbeddedShop {
  const shop = activeBundle?.shop ?? null;
  if (shop === null) throw new Error("cloudflare: the shop identity is not part of this bundle");
  return shop;
}
