import { markInvocation } from "./stats/cloudflare/mark.ts";
import { reportError } from "./stats/producer/report.ts";
import type { CaughtReporter, ErrorOperation, InvocationObserver } from "./operations.ts";

export { markInvocation };

export const reportCaught: CaughtReporter = (operation, error) => {
  reportError<ErrorOperation>(operation, error);
};

export const statsObserver: InvocationObserver = { markInvocation, reportCaught };
