import { mayResend, UnknownWindowSeconds, type EmailKind, type EmailState } from "../commerce/email.ts";
import { adminPath } from "../routes/admin.ts";
import { fragments, html, type Html } from "./html.ts";
import type { OrderDetailView } from "./orders_operations.ts";
import { fieldError, type FieldErrors } from "./pages.ts";

export const EmailKindLabels: Readonly<Record<EmailKind, string>> = {
  order_confirmation: "Order confirmation",
  shipment: "Shipment",
  cancellation_voided: "Cancellation (authorization released)",
  cancellation_items: "Cancellation (items)",
  refund: "Refund",
  late_void: "Payment not completed",
  access_link: "Order link requested by the customer",
};

export const EmailStateLabels: Readonly<Record<EmailState, string>> = {
  queued: "Waiting to send",
  sending: "Sending",
  sent: "Sent",
  failed: "Failed",
  unknown: "Delivery unconfirmed",
};

export const emailPurpose = (number: bigint): string => `order.email:${number}`;
export const accessPurpose = (number: bigint): string => `order.access:${number}`;

export interface EmailsState {
  readonly view: OrderDetailView;
  readonly emailToken: string;
  readonly accessToken: string;
  readonly nowSeconds: bigint;
  readonly errors: FieldErrors;
}

function stamp(seconds: bigint): string {
  return `${new Date(Number(seconds) * 1000).toISOString().slice(0, 16).replace("T", " ")} UTC`;
}

export function emailsSection(state: EmailsState): Html {
  const { view } = state;
  const resendable = view.emails.filter((message) => mayResend(message.state, message.firstAttemptAt, state.nowSeconds));
  const list = view.emails.length === 0
    ? html`<p>No emails have been queued for this order.</p>`
    : html`<ul class="cards">${fragments(view.emails.map((message) => html`<li>
<p><strong>${EmailKindLabels[message.kind]}</strong> ${badge(EmailStateLabels[message.state])} ${stamp(message.createdAt)}</p>
${message.lastError === null || message.state === "sent" ? html`` : html`<p class="counts">${message.lastError}</p>`}
${message.state === "unknown" && !mayResend(message.state, message.firstAttemptAt, state.nowSeconds) ? html`<p class="counts">Sending is retried automatically for ${UnknownWindowSeconds / 3600} hours after the first attempt; after that you can resend it here.</p>` : html``}
</li>`))}</ul>`;
  const resend = resendable.length === 0
    ? html``
    : html`<form method="post" action="${adminPath("admin-order-email", [view.number.toString()])}">
<input type="hidden" name="form_token" value="${state.emailToken}">
<fieldset><legend>Resend an email</legend>
<p>A failed email, or one with no delivery confirmation after ${UnknownWindowSeconds / 3600} hours, can be sent again. The customer may then receive it twice.</p>
<label for="email-message">Email</label><select id="email-message" name="message">${fragments(resendable.map((message) => html`<option value="${message.id}">${EmailKindLabels[message.kind]} (${EmailStateLabels[message.state]}, ${stamp(message.createdAt)})</option>`))}</select>${fieldError(state.errors, "email")}
<p><button type="submit">Resend</button></p>
</fieldset>
</form>`;
  const revoke = html`<form method="post" action="${adminPath("admin-order-access-revoke", [view.number.toString()])}">
<input type="hidden" name="form_token" value="${state.accessToken}">
<fieldset><legend>Customer order links</legend>
<p>Every link emailed to the customer shows this order without a sign-in. Revoking them stops all of them. The customer can ask for a new link from the shop's order lookup page.</p>
<p><button type="submit">Revoke all customer links</button></p>
</fieldset>
</form>`;
  return html`<h2>Customer emails</h2>
${list}
${resend}
${revoke}`;
}

function badge(label: string): Html {
  return html`<span class="badge">${label}</span>`;
}
