import { MaxActiveHoldsCeiling, MinActiveHolds } from "../commerce/limits.ts";
import type { ShippingPolicy, TaxPolicy } from "../commerce/policy.ts";
import { validateShippingPolicy } from "../commerce/shipping.ts";
import { validateTaxPolicy } from "../commerce/tax.ts";
import type { Mutation } from "./guard.ts";
import { all, audit, get, run, type Program } from "./program.ts";
import type { PolicyProblemView, SettingsChange, SettingsViewModel } from "./settings_operations.ts";

export interface SettingsContext {
  readonly actor: string;
  readonly nowSeconds: bigint;
}

type Refusal = { readonly kind: "stale" } | { readonly kind: "rejected"; readonly problems: readonly PolicyProblemView[] };
type Outcome = Mutation<{ readonly version: bigint }, Refusal>;

const applied = (version: bigint): Outcome => ({ applied: true, result: { version } });
const stale: Outcome = { applied: false, result: { kind: "stale" } };
const rejected = (problems: readonly PolicyProblemView[]): Outcome => ({ applied: false, result: { kind: "rejected", problems } });
const flag = (value: boolean): bigint => (value ? 1n : 0n);

function* provenance(entityKind: "tax_policy" | "shipping_policy", version: bigint, createdAt: bigint): Program<{ readonly createdAt: bigint; readonly createdBy: string | null }> {
  const events = yield* all("ListRecentAuditEvents", [entityKind, version.toString()]);
  return { createdAt, createdBy: events.at(-1)?.actor ?? null };
}

export function* settingsViewProgram(): Program<SettingsViewModel> {
  const store = yield* get("GetCatalogStore", []);
  const row = (yield* get("GetSettingsRow", []))!;
  const taxRow = yield* get("GetSettingsTaxPolicy", []);
  let tax: SettingsViewModel["tax"] = null;
  if (taxRow !== null) {
    const rates = taxRow.mode === "rate_table" ? yield* all("ListTaxRates", [taxRow.version]) : [];
    tax = {
      version: taxRow.version,
      ...(yield* provenance("tax_policy", taxRow.version, taxRow.created_at)),
      mode: taxRow.mode === "rate_table" ? "rate_table" : "no_tax_collected",
      rates: rates.map((rate) => ({ region: rate.region, ratePpm: rate.rate_ppm, taxesLines: rate.taxes_lines === 1n, taxesShipping: rate.taxes_shipping === 1n })),
    };
  }
  const shippingRow = yield* get("GetSettingsShippingPolicy", []);
  let shipping: SettingsViewModel["shipping"] = null;
  if (shippingRow !== null) {
    const zones = yield* all("ListShippingZones", [shippingRow.version]);
    const regions = yield* all("ListShippingZoneRegions", [shippingRow.version]);
    shipping = {
      version: shippingRow.version,
      ...(yield* provenance("shipping_policy", shippingRow.version, shippingRow.created_at)),
      originRegion: shippingRow.origin_region,
      freeShippingThresholdMinor: shippingRow.free_shipping_threshold_minor,
      localPickup: shippingRow.local_pickup === 1n,
      zones: zones.map((zone) => ({ name: zone.name, flatRateMinor: zone.flat_rate_minor, regions: regions.filter((region) => region.zone_name === zone.name).map((region) => region.region) })),
    };
  }
  return {
    currency: store === null ? null : { code: store.currency_code, exponent: Number(store.currency_exponent) },
    checkout: { paused: row.checkout_paused === 1n, maxActiveHolds: row.max_active_holds, revision: row.revision },
    tax,
    shipping,
  };
}

function* updateCheckout(change: Extract<SettingsChange, { action: "checkout.update" }>, context: SettingsContext): Program<Outcome> {
  const row = (yield* get("GetSettingsRow", []))!;
  if (row.revision !== change.expectedRevision) return stale;
  if (change.maxActiveHolds < BigInt(MinActiveHolds) || change.maxActiveHolds > BigInt(MaxActiveHoldsCeiling)) {
    return rejected([{ kind: "holds_out_of_range", subject: null }]);
  }
  const wasPaused = row.checkout_paused === 1n;
  if (wasPaused === change.paused && row.max_active_holds === change.maxActiveHolds) return applied(row.revision);
  yield* run("UpdateShopSettings", [flag(change.paused), change.maxActiveHolds, row.revision]);
  const revision = row.revision + 1n;
  const entry = { actor: context.actor, entityKind: "shop_settings", entityId: "1", entityRevision: revision } as const;
  if (wasPaused !== change.paused) {
    yield* audit({ ...entry, action: change.paused ? "checkout.pause" : "checkout.resume", summary: change.paused ? "paused new quotes and acceptances" : "resumed quotes and acceptances" }, context.nowSeconds);
  }
  if (row.max_active_holds !== change.maxActiveHolds) {
    yield* audit({ ...entry, action: "checkout.holds", summary: `max active holds ${row.max_active_holds} to ${change.maxActiveHolds}` }, context.nowSeconds);
  }
  return applied(revision);
}

function* saveTax(change: Extract<SettingsChange, { action: "tax.save" }>, context: SettingsContext): Program<Outcome> {
  const current = yield* get("GetSettingsTaxPolicy", []);
  if ((current?.version ?? 0n) !== change.expectedVersion) return stale;
  const version = change.expectedVersion + 1n;
  const policy: TaxPolicy = change.policy.mode === "no_tax_collected" ? { mode: "no_tax_collected", version } : { mode: "rate_table", version, rates: change.policy.rates };
  const problems = validateTaxPolicy(policy);
  if (problems.length > 0) return rejected(problems.map((problem) => ({ kind: problem.kind, subject: problem.region })));
  yield* run("InsertTaxPolicy", [version, policy.mode, context.nowSeconds]);
  if (policy.mode === "rate_table") {
    for (const rate of policy.rates) yield* run("InsertTaxRate", [version, rate.region, rate.ratePpm, flag(rate.taxesLines), flag(rate.taxesShipping)]);
  }
  const summary = policy.mode === "rate_table" ? `rate table with ${policy.rates.length} regions` : "no tax collected";
  yield* audit({ actor: context.actor, action: "tax.policy_save", entityKind: "tax_policy", entityId: version.toString(), entityRevision: version, summary }, context.nowSeconds);
  return applied(version);
}

function* saveShipping(change: Extract<SettingsChange, { action: "shipping.save" }>, context: SettingsContext): Program<Outcome> {
  const current = yield* get("GetSettingsShippingPolicy", []);
  if ((current?.version ?? 0n) !== change.expectedVersion) return stale;
  const version = change.expectedVersion + 1n;
  const policy: ShippingPolicy = { version, ...change.policy };
  const problems = validateShippingPolicy(policy);
  if (problems.length > 0) {
    return rejected(problems.map((problem) => ({ kind: problem.kind, subject: problem.kind === "unknown_origin_region" ? null : problem.kind === "duplicate_zone" ? problem.zone : problem.kind === "amount_out_of_range" ? problem.zone : problem.region })));
  }
  yield* run("InsertShippingPolicy", [version, policy.originRegion, policy.freeShippingThresholdMinor, flag(policy.localPickup), context.nowSeconds]);
  for (const [position, zone] of policy.zones.entries()) {
    yield* run("InsertShippingZone", [version, zone.name, zone.flatRateMinor, BigInt(position)]);
    for (const region of zone.regions) yield* run("InsertShippingZoneRegion", [version, region, zone.name]);
  }
  const summary = `origin ${policy.originRegion}, ${policy.zones.length} zones${policy.localPickup ? ", local pickup" : ""}`;
  yield* audit({ actor: context.actor, action: "shipping.policy_save", entityKind: "shipping_policy", entityId: version.toString(), entityRevision: version, summary }, context.nowSeconds);
  return applied(version);
}

export function settingsEffect(change: SettingsChange, context: SettingsContext): Program<Outcome> {
  switch (change.action) {
    case "checkout.update": return updateCheckout(change, context);
    case "tax.save": return saveTax(change, context);
    case "shipping.save": return saveShipping(change, context);
  }
}
