export const TOKEN_BYTES = 32;
export const LIFETIME_MS = 30 * 24 * 60 * 60 * 1000;
export const MAX_QUANTITY = 99;
export const MAX_LINES = 100;
export const COOKIE_NAME = "__Host-nanoshop_session";
export const DEV_COOKIE_NAME = "nanoshop_dev_session";

function encode(bytes: Uint8Array): string {
  return btoa(String.fromCharCode(...bytes)).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
}

export function newToken(): string {
  return encode(crypto.getRandomValues(new Uint8Array(TOKEN_BYTES)));
}

export function encodeToken(bytes: Uint8Array): string {
  if (bytes.length !== TOKEN_BYTES) throw new Error("Token must be 32 bytes");
  return encode(bytes);
}

export function parseToken(raw: string): string | null {
  if (!/^[A-Za-z0-9_-]{43}$/.test(raw)) return null;
  const bytes = Uint8Array.from(atob(raw.replaceAll("-", "+").replaceAll("_", "/") + "="), (c) => c.charCodeAt(0));
  return bytes.length === TOKEN_BYTES && encode(bytes) === raw ? raw : null;
}

export async function tokenDigest(token: string): Promise<Uint8Array> {
  if (parseToken(token) === null) throw new Error("Malformed session token");
  const bytes = Uint8Array.from(atob(token.replaceAll("-", "+").replaceAll("_", "/") + "="), (c) => c.charCodeAt(0));
  return new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
}

export function readToken(headers: Headers, localHTTP: boolean): string | null {
  const name = localHTTP ? DEV_COOKIE_NAME : COOKIE_NAME;
  const values: string[] = [];
  for (const part of (headers.get("cookie") ?? "").split(";")) {
    const separator = part.indexOf("=");
    if (separator < 0 || part.slice(0, separator).trim() !== name) continue;
    const raw = part.slice(separator + 1).trim();
    values.push(raw.startsWith('"') && raw.endsWith('"') ? raw.slice(1, -1) : raw);
  }
  if (values.length !== 1) return null;
  return parseToken(values[0]!);
}

export function sessionCookie(token: string, expires: Date, localHTTP: boolean, now = Date.now()): string {
  if (parseToken(token) === null || !Number.isFinite(expires.getTime())) throw new Error("Invalid session cookie");
  const name = localHTTP ? DEV_COOKIE_NAME : COOKIE_NAME;
  const age = Math.max(0, Math.floor((expires.getTime() - now) / 1000));
  return `${name}=${token}; Path=/; Expires=${expires.toUTCString()}; Max-Age=${age}; HttpOnly${localHTTP ? "" : "; Secure"}; SameSite=Lax`;
}
