import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const NullableText = Schema.NullOr(Text);
const PageState = Schema.Struct({
  kind: Text, blocks: Text, revision: Integer, updated_at: Integer,
  reviewed_by: NullableText, reviewed_revision: Schema.NullOr(Integer), reviewed_at: Schema.NullOr(Integer),
});

export const shopRowSchemas = {
  GetShopIdentity: Schema.Struct({ name: Text, description: Text, contact_email: NullableText, contact_phone: NullableText, revision: Integer, updated_at: Integer }),
  ListShopPageStates: PageState,
  GetShopPageState: PageState,
} as const;

export const shopWriteQueries = ["UpdateShopName", "UpdateShopProfile", "UpdateShopPage", "UpsertShopPageReview"] as const;
