export const CheckoutActor = "checkout";
export const CreateSessionKind = "create_session";
export const CreateSessionDelaySeconds = 20n;
export const createSessionKey = (attemptRef: string): string => `${CreateSessionKind}:${attemptRef}`;

type PriceResult = { readonly ok: true; readonly quote: Quote } | { readonly ok: false; readonly block: CheckoutBlock };

const noBlockDetail = { region: null, title: null, amountProblem: null, problems: [] } as const;

function toBlock(block: QuoteBlock): CheckoutBlock {
  switch (block.reason) {
    case "address_invalid": return { ...noBlockDetail, reason: block.reason, problems: block.problems.map((entry) => ({ field: entry.field, problem: entry.problem })) };
    case "destination_unsupported":
    case "tax_region_unsupported": return { ...noBlockDetail, reason: block.reason, region: block.region };
    case "amount_not_purchasable": return { ...noBlockDetail, reason: block.reason, amountProblem: block.problem };
    case "invalid_line": return { ...noBlockDetail, reason: block.reason };
    default: return { ...noBlockDetail, reason: block.reason };
  }
}

function* readPolicies(): Program<{ readonly tax: TaxPolicy | null; readonly shipping: ShippingPolicy | null }> {
  const taxRow = yield* get("GetCurrentTaxPolicy", []);
  let tax: TaxPolicy | null = null;
  if (taxRow !== null) {
    if (taxRow.mode === "no_tax_collected") tax = { mode: "no_tax_collected", version: taxRow.version };
    else {
      const rates = yield* all("ListTaxRates", [taxRow.version]);
      tax = { mode: "rate_table", version: taxRow.version, rates: rates.map((rate) => ({ region: rate.region, ratePpm: rate.rate_ppm, taxesLines: rate.taxes_lines === 1n, taxesShipping: rate.taxes_shipping === 1n })) };
    }
  }
  const shippingRow = yield* get("GetCurrentShippingPolicy", []);
  let shipping: ShippingPolicy | null = null;
  if (shippingRow !== null) {
    const zones = yield* all("ListShippingZones", [shippingRow.version]);
    const regions = yield* all("ListShippingZoneRegions", [shippingRow.version]);
    shipping = {
      version: shippingRow.version,
      originRegion: shippingRow.origin_region,
      zones: zones.map((zone) => ({ name: zone.name, flatRateMinor: zone.flat_rate_minor, regions: regions.filter((region) => region.zone_name === zone.name).map((region) => region.region) })),
      freeShippingThresholdMinor: shippingRow.free_shipping_threshold_minor,
      localPickup: shippingRow.local_pickup === 1n,
    };
  }
  return { tax, shipping };
}

interface CartRead {
  readonly lines: readonly (QuoteLineInput & { readonly status: "available" | "sold-out" | "unpublished" })[];
}

function* readCart(hash: Uint8Array): Program<CartRead> {
  const rows = yield* all("ListCheckoutCartLines", [hash]);
  const labelRows = yield* all("ListCheckoutCartLabels", [hash]);
  return {
    lines: rows.map((row) => {
      const values = labelRows.filter((label) => label.variant_id === row.variant_id).map((label) => label.value);
      return {
        productId: row.product_id,
        variantId: row.variant_id,
        title: row.product_title,
        variantLabel: variantLabel(row.variant_title, values) ?? "",
        unitPriceMinor: row.price_minor,
        quantity: row.quantity,
        status: row.product_status !== "active" ? "unpublished" : row.available === 1n ? "available" : "sold-out",
      };
    }),
  };
}

function lineInput(line: CartRead["lines"][number]): QuoteLineInput {
  return { productId: line.productId, variantId: line.variantId, title: line.title, variantLabel: line.variantLabel, unitPriceMinor: line.unitPriceMinor, quantity: line.quantity };
}

function* priceCart(hash: Uint8Array, cartRevision: bigint, fulfillment: Fulfillment, revision: bigint, nowSeconds: bigint): Program<PriceResult> {
  const cart = yield* readCart(hash);
  const unavailable = cart.lines.find((line) => line.status !== "available");
  if (unavailable !== undefined) return { ok: false, block: { ...noBlockDetail, reason: "line_unavailable", title: unavailable.title } };
  const store = yield* get("GetCatalogStore", []);
  if (store === null) throw new Error("checkout: store row is missing");
  const policies = yield* readPolicies();
  const built = buildQuote({
    revision,
    cartRevision,
    lines: cart.lines.map(lineInput),
    fulfillment,
    currency: store.currency_code,
    taxPolicy: policies.tax,
    shippingPolicy: policies.shipping,
    nowSeconds,
  });
  return built.ok ? { ok: true, quote: built.quote } : { ok: false, block: toBlock(built.block) };
}

function* liveCartRevision(hash: Uint8Array, nowSeconds: bigint): Program<bigint | null> {
  const row = yield* get("GetCheckoutSession", [hash, nowSeconds]);
  return row === null ? null : row.cart_revision;
}

type QuoteRow = AdminQueryRow<"GetQuoteByRef">;

function fulfillmentOf(row: QuoteRow): Fulfillment {
  if (row.fulfillment === "pickup") return { kind: "pickup" };
  return {
    kind: "ship",
    address: addressOf(row),
  };
}

export function addressOf(row: Pick<QuoteRow, "recipient" | "line1" | "line2" | "city" | "region" | "postal_code" | "country">): ShippingAddress {
  return { recipient: row.recipient ?? "", line1: row.line1 ?? "", line2: row.line2, city: row.city ?? "", region: row.region ?? "", postalCode: row.postal_code ?? "", country: row.country ?? "" };
}

export function* storedQuote(ref: string): Program<{ readonly row: QuoteRow; readonly quote: Quote } | null> {
  const row = yield* get("GetQuoteByRef", [ref]);
  if (row === null) return null;
  const lineRows = yield* all("ListQuoteLines", [row.id]);
  const taxRows = yield* all("ListQuoteTaxLines", [row.id]);
  const lines: QuoteLine[] = lineRows.map((line) => ({
    productId: line.product_id,
    variantId: line.variant_id,
    title: line.title,
    variantLabel: line.variant_label,
    unitPriceMinor: line.unit_price_minor,
    quantity: line.quantity,
    lineTotalMinor: line.line_total_minor,
  }));
  const taxLines: TaxLine[] = taxRows.map((tax) => ({
    target: tax.line_index === null ? { kind: "shipping" } : { kind: "line", lineIndex: Number(tax.line_index) },
    taxableMinor: tax.taxable_minor,
    ratePpm: tax.rate_ppm,
    taxMinor: tax.tax_minor,
  }));
  const service: ShippingService = row.fulfillment === "pickup" ? { kind: "pickup" } : { kind: "flat_rate", zone: row.shipping_zone ?? "" };
  const quote: Quote = {
    revision: row.revision,
    cartRevision: row.cart_revision,
    currency: row.currency_code,
    lines,
    fulfillment: fulfillmentOf(row),
    shippingService: service,
    shippingFreeByThreshold: row.shipping_free_by_threshold === 1n,
    taxMode: row.tax_mode === "rate_table" ? "rate_table" : "no_tax_collected",
    taxLines,
    merchandiseMinor: row.merchandise_minor,
    shippingMinor: row.shipping_minor,
    taxMinor: row.tax_minor,
    totalMinor: row.total_minor,
    taxPolicyVersion: row.tax_policy_version,
    shippingPolicyVersion: row.shipping_policy_version,
    createdAtSeconds: row.created_at,
    expiresAtSeconds: row.expires_at,
  };
  return { row, quote };
}

export function quoteView(ref: string, email: string, quote: Quote): QuoteView {
  return {
    ref,
    revision: quote.revision,
    email,
    fulfillment: quote.fulfillment.kind === "pickup" ? { kind: "pickup" } : { kind: "ship", address: quote.fulfillment.address },
    shippingZone: quote.shippingService.kind === "flat_rate" ? quote.shippingService.zone : null,
    shippingFreeByThreshold: quote.shippingFreeByThreshold,
    taxMode: quote.taxMode,
    currency: quote.currency,
    lines: quote.lines.map((line) => ({ title: line.title, variantLabel: line.variantLabel, unitPriceMinor: line.unitPriceMinor, quantity: line.quantity, lineTotalMinor: line.lineTotalMinor })),
    taxLines: quote.taxLines.map((tax) => ({ lineIndex: tax.target.kind === "line" ? BigInt(tax.target.lineIndex) : null, taxableMinor: tax.taxableMinor, ratePpm: tax.ratePpm, taxMinor: tax.taxMinor })),
    merchandiseMinor: quote.merchandiseMinor,
    shippingMinor: quote.shippingMinor,
    taxMinor: quote.taxMinor,
    totalMinor: quote.totalMinor,
    createdAt: quote.createdAtSeconds,
    expiresAt: quote.expiresAtSeconds,
  };
}

function* saveQuote(ref: string, hash: Uint8Array, email: string, quote: Quote): Program<void> {
  const address = quote.fulfillment.kind === "ship" ? quote.fulfillment.address : null;
  yield* run("InsertQuote", [
    ref, hash, quote.revision, quote.cartRevision, quote.currency, email, quote.fulfillment.kind,
    address?.recipient ?? null, address?.line1 ?? null, address?.line2 ?? null, address?.city ?? null, address?.region ?? null,
    address?.postalCode ?? null, address?.country ?? null, quote.shippingService.kind === "flat_rate" ? quote.shippingService.zone : null,
    quote.shippingFreeByThreshold ? 1n : 0n, quote.taxMode, quote.merchandiseMinor, quote.shippingMinor, quote.taxMinor, quote.totalMinor,
    quote.taxPolicyVersion, quote.shippingPolicyVersion, quote.createdAtSeconds, quote.expiresAtSeconds,
  ]);
  for (const [position, line] of quote.lines.entries()) {
    yield* run("InsertQuoteLine", [BigInt(position), line.productId, line.variantId, line.title, line.variantLabel, line.unitPriceMinor, line.quantity, line.lineTotalMinor, ref]);
  }
  for (const [position, tax] of quote.taxLines.entries()) {
    yield* run("InsertQuoteTaxLine", [BigInt(position), tax.target.kind === "line" ? BigInt(tax.target.lineIndex) : null, tax.taxableMinor, tax.ratePpm, tax.taxMinor, ref]);
  }
}

const contactBlock: CheckoutBlock = { ...noBlockDetail, reason: "contact_invalid", problems: [{ field: "email", problem: "invalid_format" }] };

type NewQuoteResult = Extract<CheckoutCommandResult, { readonly kind: "checkout.quote" }>;

function* newQuote(sessionDigest: string, quoteRef: string, email: string, fulfillment: Fulfillment, nowSeconds: number): Program<NewQuoteResult> {
  const hash = digestBytes(sessionDigest);
  const now = BigInt(nowSeconds);
  const settings = yield* get("GetShopSettings", []);
  if (settings === null) throw new Error("checkout: shop settings row is missing");
  if (settings.checkout_paused === 1n) return { kind: "checkout.quote", outcome: "paused" };
  const cartRevision = yield* liveCartRevision(hash, now);
  if (cartRevision === null) return { kind: "checkout.quote", outcome: "no_cart" };
  if (!validEmail(email)) return { kind: "checkout.quote", outcome: "blocked", block: contactBlock };
  const latest = yield* get("GetLatestQuoteRevision", [hash]);
  const priced = yield* priceCart(hash, cartRevision, fulfillment, (latest?.revision ?? 0n) + 1n, now);
  if (!priced.ok) return { kind: "checkout.quote", outcome: priced.block.reason === "empty_cart" ? "no_cart" : "blocked", ...(priced.block.reason === "empty_cart" ? {} : { block: priced.block }) } as NewQuoteResult;
  yield* saveQuote(quoteRef, hash, email, priced.quote);
  return { kind: "checkout.quote", outcome: "quoted", quoteRef };
}

function* requote(command: Extract<CheckoutCommand, { kind: "checkout.requote" }>): Program<CheckoutCommandResult> {
  const stored = yield* storedQuote(command.fromQuoteRef);
  if (stored === null || !sameDigest(stored.row.session_hash, command.sessionDigest)) return { kind: "checkout.requote", outcome: "not_found" };
  const result = yield* newQuote(command.sessionDigest, command.quoteRef, stored.row.contact_email, stored.quote.fulfillment, command.nowSeconds);
  return { ...result, kind: "checkout.requote" } as CheckoutCommandResult;
}

function sameDigest(bytes: Uint8Array, hex: string): boolean {
  return bytes.length * 2 === hex.length && [...bytes].every((byte, index) => byte.toString(16).padStart(2, "0") === hex.slice(index * 2, index * 2 + 2));
}

function* accept(command: Extract<CheckoutCommand, { kind: "checkout.accept" }>): Program<CheckoutCommandResult> {
  const hash = digestBytes(command.sessionDigest);
  const now = BigInt(command.nowSeconds);
  const stored = yield* storedQuote(command.quoteRef);
  if (stored === null || !sameDigest(stored.row.session_hash, command.sessionDigest)) return { kind: "checkout.accept", outcome: "not_found" };
  const view = quoteView(stored.row.ref, stored.row.contact_email, stored.quote);
  const existing = yield* get("GetAttemptForQuote", [stored.row.id]);
  if (existing !== null) {
    return { kind: "checkout.accept", outcome: "accepted", attemptRef: existing.ref, state: existing.state as AttemptState, replay: true, sessionUrl: existing.provider_session_url, quote: view };
  }
  const settings = yield* get("GetShopSettings", []);
  if (settings === null) throw new Error("checkout: shop settings row is missing");
  if (settings.checkout_paused === 1n) return { kind: "checkout.accept", outcome: "paused" };
  if (quoteIsExpired(stored.quote, now)) return { kind: "checkout.accept", outcome: "expired" };
  const cartRevision = yield* liveCartRevision(hash, now);
  if (cartRevision === null) return { kind: "checkout.accept", outcome: "changed", mismatch: "cart_revision" };
  const recomputed = yield* priceCart(hash, cartRevision, stored.quote.fulfillment, stored.quote.revision, stored.quote.createdAtSeconds);
  if (!recomputed.ok) return { kind: "checkout.accept", outcome: "blocked", block: recomputed.block };
  const comparison = compareQuotes(stored.quote, recomputed.quote);
  if (!comparison.same) return { kind: "checkout.accept", outcome: "changed", mismatch: comparison.mismatch };
  const pinned = yield* get("CountPinnedAttempts", []);
  if (!hasHoldCapacity(pinned?.n ?? 0n, Number(settings.max_active_holds))) return { kind: "checkout.accept", outcome: "holds_full" };

  const tracked = new Map<bigint, boolean>();
  for (const line of stored.quote.lines) {
    const level = yield* stockRead(line.variantId);
    tracked.set(line.variantId, level !== null && level.on_hand !== null);
  }
  const held = yield* stock(stored.quote.lines.map((line) => ({ kind: "hold", variantId: line.variantId, quantity: line.quantity })), { nowSeconds: now, actor: CheckoutActor });
  if (held.outcome === "rejected") {
    const line = stored.quote.lines.find((candidate) => candidate.variantId === held.variantId);
    if (held.rejection === "insufficient_stock") return { kind: "checkout.accept", outcome: "insufficient_stock", title: line?.title ?? "" };
    return { kind: "checkout.accept", outcome: "blocked", block: { ...noBlockDetail, reason: "line_unavailable", title: line?.title ?? null } };
  }

  const previous = yield* get("GetActiveAttemptForSession", [hash]);
  if (previous !== null) yield* run("SupersedeAttempt", [now, previous.id]);
  const holdReleaseAfter = holdExpiresAt(now + QuoteLifetimeSeconds);
  yield* run("InsertAttempt", [command.attemptRef, stored.row.id, hash, now, holdReleaseAfter, now]);
  for (const line of stored.quote.lines) {
    yield* run("InsertReservation", [line.variantId, line.quantity, tracked.get(line.variantId) === true ? 1n : 0n, now, command.attemptRef]);
  }
  yield* insertOperation(command.tenantId, "create_session", command.attemptRef, "in_flight", now);
  yield* run("InsertWorkItem", [CreateSessionKind, createSessionKey(command.attemptRef), JSON.stringify({ attempt: command.attemptRef }), now + CreateSessionDelaySeconds, now, now]);
  yield* run("InsertWorkItem", [HoldExpiryKind, holdExpiryKey(command.attemptRef), JSON.stringify({ attempt: command.attemptRef }), holdReleaseAfter, now, now]);
  return { kind: "checkout.accept", outcome: "accepted", attemptRef: command.attemptRef, state: "accepted", replay: false, sessionUrl: null, quote: view };
}

function* recordSession(command: Extract<CheckoutCommand, { kind: "checkout.session.record" }>): Program<CheckoutCommandResult> {
  const now = BigInt(command.nowSeconds);
  const holdReleaseAfter = holdExpiresAt(BigInt(command.sessionExpiresAt));
  const changed = yield* run("RecordAttemptSession", [command.sessionId, command.sessionUrl, BigInt(command.sessionExpiresAt), holdReleaseAfter, now, command.attemptRef]);
  if (changed === 0n) return { kind: "checkout.session.record", outcome: "not_recorded" };
  yield* run("SucceedWorkItem", [now, createSessionKey(command.attemptRef)]);
  yield* run("SetPendingWorkDue", [holdReleaseAfter, now, holdExpiryKey(command.attemptRef)]);
  const operation = yield* get("GetOperation", ["create_session", command.attemptRef]);
  if (operation !== null && operation.state !== "succeeded" && canTransitionOperation(operation.state as ProviderOperationState, "succeeded")) {
    yield* run("SetOperationState", ["succeeded", operation.attempts, command.sessionId, null, now, operation.id, operation.state]);
  }
  const attempt = yield* get("GetAttemptByRef", [command.attemptRef]);
  return { kind: "checkout.session.record", outcome: attempt?.state === "handed_off" ? "handed_off" : "not_recorded" };
}

export function* checkoutCommandProgram(command: CheckoutCommand): Program<CheckoutCommandResult> {
  switch (command.kind) {
    case "checkout.quote": return yield* newQuote(command.sessionDigest, command.quoteRef, command.email, command.fulfillment, command.nowSeconds);
    case "checkout.requote": return yield* requote(command);
    case "checkout.accept": return yield* accept(command);
    case "checkout.session.record": return yield* recordSession(command);
  }
}

function* quoteViewProgram(query: Extract<CheckoutQuery, { kind: "checkout.quote_view" }>): Program<Extract<CheckoutQueryResult, { kind: "checkout.quote_view" }>> {
  const hash = digestBytes(query.sessionDigest);
  const now = BigInt(query.nowSeconds);
  const stored = yield* storedQuote(query.quoteRef);
  if (stored === null || !sameDigest(stored.row.session_hash, query.sessionDigest)) return { kind: "checkout.quote_view", view: null };
  const quote = quoteView(stored.row.ref, stored.row.contact_email, stored.quote);
  const attempt = yield* get("GetAttemptForQuote", [stored.row.id]);
  const base = { quote, attemptRef: attempt?.ref ?? null, attemptState: (attempt?.state ?? null) as AttemptState | null, sessionUrl: attempt?.provider_session_url ?? null };
  if (attempt !== null) return { kind: "checkout.quote_view", view: { ...base, status: "accepted", mismatch: null } };
  if (quoteIsExpired(stored.quote, now)) return { kind: "checkout.quote_view", view: { ...base, status: "expired", mismatch: null } };
  const cartRevision = yield* liveCartRevision(hash, now);
  if (cartRevision === null) return { kind: "checkout.quote_view", view: { ...base, status: "changed", mismatch: "cart_revision" } };
  const recomputed = yield* priceCart(hash, cartRevision, stored.quote.fulfillment, stored.quote.revision, stored.quote.createdAtSeconds);
  if (!recomputed.ok) return { kind: "checkout.quote_view", view: { ...base, status: "changed", mismatch: recomputed.block.reason } };
  const comparison = compareQuotes(stored.quote, recomputed.quote);
  return { kind: "checkout.quote_view", view: { ...base, status: comparison.same ? "open" : "changed", mismatch: comparison.same ? null : comparison.mismatch } };
}

function* formProgram(query: Extract<CheckoutQuery, { kind: "checkout.form" }>): Program<Extract<CheckoutQueryResult, { kind: "checkout.form" }>> {
  const hash = digestBytes(query.sessionDigest);
  const settings = yield* get("GetShopSettings", []);
  const store = yield* get("GetCatalogStore", []);
  if (settings === null || store === null) throw new Error("checkout: store or shop settings row is missing");
  const cartRevision = yield* liveCartRevision(hash, BigInt(query.nowSeconds));
  const cart = cartRevision === null ? { lines: [] } : yield* readCart(hash);
  const policies = yield* readPolicies();
  return {
    kind: "checkout.form",
    paused: settings.checkout_paused === 1n,
    ready: policies.tax !== null && policies.shipping !== null,
    offersPickup: policies.shipping?.localPickup === true,
    regions: [...new Set((policies.shipping?.zones ?? []).flatMap((zone) => zone.regions))].sort(),
    currency: store.currency_code,
    lines: cart.lines.map((line) => ({ title: line.title, variantLabel: line.variantLabel === "" ? null : line.variantLabel, quantity: line.quantity, unitPriceMinor: line.unitPriceMinor, status: line.status })),
  };
}

function* attemptViewProgram(query: Extract<CheckoutQuery, { kind: "checkout.attempt_view" }>): Program<Extract<CheckoutQueryResult, { kind: "checkout.attempt_view" }>> {
  const attempt = yield* get("GetAttemptByRef", [query.attemptRef]);
  if (attempt === null) return { kind: "checkout.attempt_view", view: null };
  const quote = yield* get("GetQuoteByRef", [attempt.quote_ref]);
  const lines = yield* all("ListQuoteLines", [attempt.quote_id]);
  const order = yield* get("GetOrderForAttempt", [attempt.id]);
  return {
    kind: "checkout.attempt_view",
    view: {
      ref: attempt.ref,
      state: attempt.state as AttemptState,
      sessionUrl: attempt.provider_session_url,
      currency: quote?.currency_code ?? "",
      totalMinor: attempt.total_minor,
      orderNumber: order?.number ?? null,
      lines: lines.map((line) => ({ title: line.title, variantLabel: line.variant_label, unitPriceMinor: line.unit_price_minor, quantity: line.quantity, lineTotalMinor: line.line_total_minor })),
    },
  };
}

export function* checkoutQueryProgram(query: CheckoutQuery): Program<CheckoutQueryResult> {
  switch (query.kind) {
    case "checkout.form": return yield* formProgram(query);
    case "checkout.quote_view": return yield* quoteViewProgram(query);
    case "checkout.attempt_view": return yield* attemptViewProgram(query);
  }
}
