import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const NullableText = Schema.NullOr(Text);
const NullableInteger = Schema.NullOr(Integer);
const Digest = Schema.instanceOf(Uint8Array);

export const checkoutRowSchemas = {
  GetCheckoutSession: Schema.Struct({ cart_revision: Integer }),
  GetShopSettings: Schema.Struct({ checkout_paused: Integer, max_active_holds: Integer }),
  GetCurrentTaxPolicy: Schema.Struct({ version: Integer, mode: Text }),
  ListTaxRates: Schema.Struct({ region: Text, rate_ppm: Integer, taxes_lines: Integer, taxes_shipping: Integer }),
  GetCurrentShippingPolicy: Schema.Struct({ version: Integer, origin_region: Text, free_shipping_threshold_minor: NullableInteger, local_pickup: Integer }),
  ListShippingZones: Schema.Struct({ name: Text, flat_rate_minor: Integer }),
  ListShippingZoneRegions: Schema.Struct({ zone_name: Text, region: Text }),
  ListCheckoutCartLines: Schema.Struct({ variant_id: Integer, product_id: Integer, quantity: Integer, product_title: Text, variant_title: NullableText, price_minor: Integer, available: Integer, product_status: Text }),
  ListCheckoutCartLabels: Schema.Struct({ variant_id: Integer, value: Text }),
  GetLatestQuoteRevision: Schema.Struct({ revision: Integer }),
  GetQuoteByRef: Schema.Struct({
    id: Integer, ref: Text, session_hash: Digest, revision: Integer, cart_revision: Integer, currency_code: Text, contact_email: Text, fulfillment: Text,
    recipient: NullableText, line1: NullableText, line2: NullableText, city: NullableText, region: NullableText, postal_code: NullableText, country: NullableText, shipping_zone: NullableText,
    shipping_free_by_threshold: Integer, tax_mode: Text, merchandise_minor: Integer, shipping_minor: Integer, tax_minor: Integer, total_minor: Integer,
    tax_policy_version: Integer, shipping_policy_version: Integer, created_at: Integer, expires_at: Integer,
  }),
  ListQuoteLines: Schema.Struct({ product_id: Integer, variant_id: Integer, title: Text, variant_label: Text, unit_price_minor: Integer, quantity: Integer, line_total_minor: Integer }),
  ListQuoteTaxLines: Schema.Struct({ line_index: NullableInteger, taxable_minor: Integer, rate_ppm: Integer, tax_minor: Integer }),
  GetAttemptForQuote: Schema.Struct({ id: Integer, ref: Text, state: Text, provider_session_url: NullableText }),
  GetActiveAttemptForSession: Schema.Struct({ id: Integer, ref: Text, state: Text }),
  CountPinnedAttempts: Schema.Struct({ n: Integer }),
  GetAttemptByRef: Schema.Struct({ id: Integer, ref: Text, state: Text, provider_session_url: NullableText, quote_ref: Text, quote_id: Integer, total_minor: Integer, accepted_at: Integer }),
} as const;

export const checkoutWriteQueries = [
  "InsertQuote", "InsertQuoteLine", "InsertQuoteTaxLine", "InsertAttempt", "SupersedeAttempt", "InsertReservation",
  "InsertWorkItem", "RecordAttemptSession", "SucceedWorkItem",
] as const;
