import type { BlobStore } from "../media/blob.ts";
import { kindOfContentType, mediaKey, parseMediaKey } from "../media/format.ts";
import { MaintenanceBatch } from "../media/limits.ts";
import type { AdminBackend } from "./backend.ts";
import type { CollectedMedia } from "./media_operations.ts";

export interface MediaMaintenanceInput {
  readonly backend: AdminBackend;
  readonly blobs: BlobStore;
  readonly nowSeconds: number;
  readonly orphanCursor?: string | null;
  readonly signal?: AbortSignal;
}

export interface MediaMaintenanceReport {
  readonly expiredPending: number;
  readonly collected: number;
  readonly orphanBlobs: number;
  readonly orphanCursor: string | null;
}

const MaxRounds = 20;
const OrphanPages = 10;

async function deleteBlobs(blobs: BlobStore, removed: readonly CollectedMedia[]): Promise<void> {
  for (const item of removed) {
    const kind = kindOfContentType(item.contentType);
    if (kind === null) throw new Error(`media: stored content type ${JSON.stringify(item.contentType)} is not an image type`);
    await blobs.delete(mediaKey({ id: item.id, sha256: item.sha256, kind }));
  }
}

/**
 * One bounded pass of media upkeep for a tenant, for a job to call. It deletes
 * pending uploads older than one hour, deletes ready media that no product
 * image or other reference holds and that became ready more than seven days
 * ago, and removes stored blobs that have no index row (left by an interrupted
 * deletion). Rows go first and blobs after, so a failure between them leaves a
 * blob for the orphan scan, never a row without its blob. The orphan scan reads
 * at most ten pages of keys per pass; feed `orphanCursor` back to continue.
 */
export async function runMediaMaintenance(input: MediaMaintenanceInput): Promise<MediaMaintenanceReport> {
  const { backend, blobs, nowSeconds, signal } = input;
  let expiredPending = 0;
  let collected = 0;
  for (let round = 0; round < MaxRounds; round++) {
    const { removed } = await backend.command({ kind: "media.expire", nowSeconds }, signal);
    await deleteBlobs(blobs, removed);
    expiredPending += removed.length;
    if (removed.length < MaintenanceBatch) break;
  }
  for (let round = 0; round < MaxRounds; round++) {
    const { removed } = await backend.command({ kind: "media.collect", nowSeconds }, signal);
    await deleteBlobs(blobs, removed);
    collected += removed.length;
    if (removed.length < MaintenanceBatch) break;
  }
  let orphanBlobs = 0;
  let cursor = input.orphanCursor ?? null;
  for (let pages = 0; pages < OrphanPages; pages++) {
    const page = await blobs.list("m/", cursor);
    const addresses = page.keys.flatMap((key) => {
      const address = parseMediaKey(key);
      return address === null ? [] : [address];
    });
    if (addresses.length > 0) {
      const { orphans } = await backend.command({ kind: "media.orphans", ids: [...new Set(addresses.map((address) => address.id))] }, signal);
      const orphaned = new Set(orphans);
      for (const address of addresses) {
        if (!orphaned.has(address.id)) continue;
        await blobs.delete(mediaKey(address));
        orphanBlobs++;
      }
    }
    cursor = page.next;
    if (cursor === null) break;
  }
  return { expiredPending, collected, orphanBlobs, orphanCursor: cursor };
}
