import type { StateMachine } from "./machine.ts";

export type AttemptState =
  | "quoted"
  | "accepted"
  | "handed_off"
  | "authorized"
  | "expired"
  | "superseded"
  | "voided_late"
  | "blocked";

export const AttemptMachine: StateMachine<AttemptState> = {
  initial: "quoted",
  edges: {
    quoted: ["accepted"],
    accepted: ["handed_off", "authorized", "superseded", "expired", "voided_late", "blocked"],
    handed_off: ["authorized", "expired", "superseded", "voided_late", "blocked"],
    superseded: ["authorized", "expired", "voided_late", "blocked"],
    expired: ["authorized", "voided_late", "blocked"],
    blocked: ["authorized", "expired", "superseded", "voided_late"],
    authorized: [],
    voided_late: [],
  },
};

export function holdIsPinned(state: AttemptState): boolean {
  return state === "accepted" || state === "handed_off" || state === "superseded" || state === "blocked";
}
