import { reauthRequired } from "../identity/policy.ts";
import { principalId } from "../identity/principal.ts";
import { adminPath } from "../routes/admin.ts";
import { newToken, parseToken, tokenDigest } from "../session/session.ts";
import { BadInput } from "../web/decode.ts";
import type { AdminBackend } from "./backend.ts";
import { readCatalogForm, type FormValues } from "./catalog_form.ts";
import type { Html } from "./html.ts";
import { digestHex, type AdminSessionView } from "./operations.ts";
import { type FieldErrors, type Notice } from "./pages.ts";
import { page, redirect } from "./response.ts";
import {
  describeShippingProblems, describeTaxProblems, parseShippingForm, parseTaxForm, shippingFormFromFields, shippingFormFromView,
  taxFormFromFields, taxFormFromView, MaxShippingZones, SortedRegions,
} from "./settings_form.ts";
import type { PolicyProblemView, SettingsChange, SettingsViewModel } from "./settings_operations.ts";
import { checkoutInputFromView, settingsPage, shippingPage, taxPage, type CheckoutInput, type SettingsPageBase } from "./settings_pages.ts";

export interface SettingsAuth {
  readonly session: AdminSessionView;
  readonly digest: string;
  readonly label: string;
}

export interface SettingsHandlerOptions {
  readonly backend: AdminBackend;
  readonly nowSeconds: () => number;
  readonly clearCookies: () => readonly string[];
}

export interface SettingsHandler {
  handle(name: string, request: Request, auth: SettingsAuth, signal: AbortSignal): Promise<Response | null>;
}

interface Drawing {
  readonly view: SettingsViewModel;
  readonly formToken: string;
  readonly notice: Notice | null;
  readonly errors: FieldErrors;
  readonly conflict: boolean;
}

interface Screen {
  readonly purpose: string;
  readonly path: string;
  render(drawing: Drawing, base: SettingsPageBase): Html;
}

const versionShape = /^(?:0|[1-9][0-9]{0,18})$/;
const MaxInt64 = 9223372036854775807n;
const holdsShape = /^[1-9][0-9]{0,5}$/;
const checkoutKeys = new Set(["form_token", "revision", "paused", "max_active_holds"]);
const taxKeys = new Set(["form_token", "version", "mode", ...SortedRegions.flatMap((region) => [`rate_${region}`, `lines_${region}`, `shipping_${region}`])]);
const shippingKeys = new Set([
  "form_token", "version", "origin", "threshold", "pickup",
  ...Array.from({ length: MaxShippingZones }, (_, slot) => [`zone_${slot}_name`, `zone_${slot}_rate`, `zone_${slot}_regions`]).flat(),
]);

function parseInteger(fields: FormValues, name: string, what: string): bigint {
  const raw = fields.get(name) ?? "";
  if (!versionShape.test(raw) || BigInt(raw) > MaxInt64) throw new BadInput(`The form is missing its ${what}.`);
  return BigInt(raw);
}

export function createSettingsHandler(options: SettingsHandlerOptions): SettingsHandler {
  const { backend } = options;
  const now = (): number => options.nowSeconds();

  const checkoutScreen = (input: CheckoutInput | null): Screen => ({
    purpose: "settings.checkout", path: adminPath("admin-settings"),
    render: (drawing, base) => settingsPage({ ...base, input: input ?? checkoutInputFromView(drawing.view), conflict: drawing.conflict }),
  });
  const taxScreen = (echo: ReturnType<typeof taxFormFromFields> | null): Screen => ({
    purpose: "settings.tax", path: adminPath("admin-settings-tax"),
    render: (drawing, base) => taxPage({ ...base, form: echo ?? taxFormFromView(drawing.view.tax), conflict: drawing.conflict }),
  });
  const shippingScreen = (echo: ReturnType<typeof shippingFormFromFields> | null): Screen => ({
    purpose: "settings.shipping", path: adminPath("admin-settings-shipping"),
    render: (drawing, base) => shippingPage({ ...base, form: echo ?? shippingFormFromView(drawing.view.shipping, drawing.view.currency?.exponent ?? 2), conflict: drawing.conflict }),
  });

  async function draw(request: Request, auth: SettingsAuth, screen: Screen, signal: AbortSignal, shown: { readonly status: number; readonly token: string | null; readonly notice: Notice | null; readonly errors: FieldErrors; readonly conflict: boolean }): Promise<Response> {
    let formToken = shown.token;
    let view: SettingsViewModel;
    if (formToken === null) {
      formToken = newToken();
      view = (await backend.command({ kind: "settings.form", tokenDigest: digestHex(await tokenDigest(formToken)), sessionDigest: auth.digest, purpose: screen.purpose, nowSeconds: now() }, signal)).view;
    } else {
      view = (await backend.query({ kind: "settings.view" }, signal)).view;
    }
    const drawing: Drawing = { view, formToken, notice: shown.notice, errors: shown.errors, conflict: shown.conflict };
    return page(request, shown.status, screen.render(drawing, { principalLabel: auth.label, formToken, view, notice: shown.notice, errors: shown.errors }));
  }

  const error = (message: string): Notice => ({ kind: "error", message });
  const unverified = error("This form could not be verified. Review the current values and submit again.");
  const spent = error("This form was already submitted or has expired, so nothing was changed. Review the current values and submit again if needed.");
  const changed = error("This changed after you opened the form, so nothing was changed. Compare the values and submit again.");

  async function view(request: Request, auth: SettingsAuth, screen: Screen, signal: AbortSignal): Promise<Response> {
    const saved = new URL(request.url).searchParams.get("saved") === "1";
    return await draw(request, auth, screen, signal, { status: 200, token: null, notice: saved ? { kind: "info", message: "Saved." } : null, errors: {}, conflict: false });
  }

  async function submit(
    request: Request, auth: SettingsAuth, screen: Screen, signal: AbortSignal, formToken: string, change: SettingsChange,
    describe: (problems: readonly PolicyProblemView[]) => FieldErrors,
  ): Promise<Response> {
    if (reauthRequired(auth.session.authenticatedAt, now())) {
      return redirect(`${adminPath("admin-reauth")}?return=${encodeURIComponent(screen.path)}`);
    }
    const outcome = await backend.command({
      kind: "settings.mutate", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: screen.purpose,
      actor: principalId(auth.session), nowSeconds: now(), change,
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${screen.path}?saved=1`);
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "token_invalid": return await draw(request, auth, screen, signal, { status: 409, token: null, notice: spent, errors: {}, conflict: true });
      case "stale": return await draw(request, auth, screen, signal, { status: 409, token: formToken, notice: changed, errors: {}, conflict: true });
      case "rejected": return await draw(request, auth, screen, signal, { status: 422, token: formToken, notice: error("The change was refused. Fix the highlighted fields and submit again."), errors: describe(outcome.problems), conflict: false });
    }
  }

  async function saveCheckout(request: Request, auth: SettingsAuth, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => checkoutKeys.has(key), signal);
    const input: CheckoutInput = { paused: fields.get("paused") === "on", maxActiveHolds: (fields.get("max_active_holds") ?? "").trim() };
    const screen = checkoutScreen(input);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, screen, signal, { status: 409, token: null, notice: unverified, errors: {}, conflict: true });
    const expectedRevision = parseInteger(fields, "revision", "revision");
    if (!holdsShape.test(input.maxActiveHolds)) {
      return await draw(request, auth, screen, signal, { status: 422, token: formToken, notice: error("Fix the highlighted fields and submit again."), errors: { max_active_holds: "Enter a whole number from 50 to 500." }, conflict: false });
    }
    const change: SettingsChange = { action: "checkout.update", expectedRevision, paused: input.paused, maxActiveHolds: BigInt(input.maxActiveHolds) };
    return await submit(request, auth, screen, signal, formToken, change, () => ({ max_active_holds: "Enter a whole number from 50 to 500." }));
  }

  async function saveTax(request: Request, auth: SettingsAuth, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => taxKeys.has(key), signal);
    const form = taxFormFromFields(fields);
    const screen = taxScreen(form);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, screen, signal, { status: 409, token: null, notice: unverified, errors: {}, conflict: true });
    const expectedVersion = parseInteger(fields, "version", "version");
    const parsed = parseTaxForm(form);
    if (!parsed.ok) return await draw(request, auth, screen, signal, { status: 422, token: formToken, notice: error("Fix the highlighted fields and submit again."), errors: parsed.errors, conflict: false });
    return await submit(request, auth, screen, signal, formToken, { action: "tax.save", expectedVersion, policy: parsed.policy }, describeTaxProblems);
  }

  async function saveShipping(request: Request, auth: SettingsAuth, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => shippingKeys.has(key), signal);
    const form = shippingFormFromFields(fields);
    const screen = shippingScreen(form);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, screen, signal, { status: 409, token: null, notice: unverified, errors: {}, conflict: true });
    const expectedVersion = parseInteger(fields, "version", "version");
    const current = (await backend.query({ kind: "settings.view" }, signal)).view;
    const parsed = parseShippingForm(form, current.currency?.exponent ?? 2);
    if (!parsed.ok) return await draw(request, auth, screen, signal, { status: 422, token: formToken, notice: error("Fix the highlighted fields and submit again."), errors: parsed.errors, conflict: false });
    return await submit(request, auth, screen, signal, formToken, { action: "shipping.save", expectedVersion, policy: parsed.policy }, (problems) => describeShippingProblems(problems, parsed));
  }

  return {
    async handle(name, request, auth, signal) {
      switch (name) {
        case "admin-settings": return await view(request, auth, checkoutScreen(null), signal);
        case "admin-settings-checkout": return await saveCheckout(request, auth, signal);
        case "admin-settings-tax": return await view(request, auth, taxScreen(null), signal);
        case "admin-settings-tax-save": return await saveTax(request, auth, signal);
        case "admin-settings-shipping": return await view(request, auth, shippingScreen(null), signal);
        case "admin-settings-shipping-save": return await saveShipping(request, auth, signal);
        default: return null;
      }
    },
  };
}
