export const PaymentLabels: Readonly<Record<PaymentState, string>> = {
  authorized: "Authorized",
  in_review: "In review",
  capture_pending: "Capturing",
  capture_unknown: "Capture unconfirmed",
  captured: "Paid",
  void_unknown: "Void unconfirmed",
  voided: "Voided",
};

export const FulfillmentLabels: Readonly<Record<FulfillmentStatus, string>> = {
  unfulfilled: "Unfulfilled",
  partially_fulfilled: "Partially fulfilled",
  fulfilled: "Fulfilled",
  canceled: "Canceled",
};

const BlockMessages: Readonly<Record<ShipmentBlock, string>> = {
  payment_not_captured: "This order cannot ship yet because its payment has not been captured. Capture runs automatically once the stock is allocated.",
  review_open: "This order cannot ship while a Stripe Radar review is open. Shipping unblocks after the review is approved in the Stripe dashboard.",
};

const TimelineLabels: Readonly<Record<string, string>> = {
  "order.place": "Order placed",
  "payment.capture": "Payment captured",
  "payment.void": "Authorization canceled",
  "payment.exception": "Payment issue",
  "fulfillment.create": "Shipment recorded",
  "order.note": "Note added",
  "order.cancel": "Items canceled",
  "order.return": "Return recorded",
  "order.restock": "Items restocked",
  "refund.request": "Refund requested",
  "refund.settle": "Refund update",
  "refund.record": "Refund recorded from Stripe",
  "email.resend": "Email resent",
  "order.access_revoke": "Customer links revoked",
};

export function stamp(seconds: bigint): string {
  return `${new Date(Number(seconds) * 1000).toISOString().slice(0, 16).replace("T", " ")} UTC`;
}

function isoStamp(seconds: bigint): string {
  return new Date(Number(seconds) * 1000).toISOString();
}

function money(minor: bigint, view: { readonly currency: string; readonly exponent: number }): string {
  return formatMoney(minor, view.currency, view.exponent);
}

function actorLabel(actor: string): string {
  const separator = actor.lastIndexOf("#");
  return separator < 0 ? actor : actor.slice(separator + 1);
}

function when(seconds: bigint): Html {
  return html`<time datetime="${isoStamp(seconds)}">${stamp(seconds)}</time>`;
}

function orderPath(number: bigint): string {
  return adminPath("admin-order", [number.toString()]);
}

export interface OrderFilterInput {
  readonly number: string;
  readonly email: string;
  readonly from: string;
  readonly to: string;
  readonly payment: string;
  readonly fulfillment: string;
}

export const EmptyFilterInput: OrderFilterInput = { number: "", email: "", from: "", to: "", payment: "", fulfillment: "" };

function option(value: string, label: string, selected: string): Html {
  return html`<option value="${value}"${value === selected ? html` selected` : html``}>${label}</option>`;
}

function badge(text: string): Html {
  return html`<span class="badge">${text}</span>`;
}

export function listQuery(input: OrderFilterInput, before: bigint | null): string {
  const params = new URLSearchParams();
  for (const [name, value] of Object.entries(input)) if (value !== "") params.set(name, value);
  if (before !== null) params.set("before", before.toString());
  const text = params.toString();
  return text === "" ? adminPath("admin-orders") : `${adminPath("admin-orders")}?${text}`;
}

export function ordersListPage(state: {
  readonly principalLabel: string;
  readonly input: OrderFilterInput;
  readonly errors: FieldErrors;
  readonly rows: readonly OrderListRow[];
  readonly next: bigint | null;
  readonly filter: OrderListFilter | null;
}): Html {
  const { input } = state;
  const filtered = Object.values(input).some((value) => value !== "");
  const form = html`<form method="get" action="${adminPath("admin-orders")}" class="filters">
<div><label for="f-number">Order number</label><input id="f-number" name="number" inputmode="numeric" autocomplete="off" value="${input.number}" aria-describedby="number-error">${fieldError(state.errors, "number")}</div>
<div><label for="f-email">Customer email (exact match)</label><input id="f-email" name="email" type="email" autocomplete="off" value="${input.email}" aria-describedby="email-error">${fieldError(state.errors, "email")}</div>
<div><label for="f-from">Placed from (UTC date)</label><input id="f-from" name="from" type="date" value="${input.from}" aria-describedby="from-error">${fieldError(state.errors, "from")}</div>
<div><label for="f-to">Placed through (UTC date)</label><input id="f-to" name="to" type="date" value="${input.to}" aria-describedby="to-error">${fieldError(state.errors, "to")}</div>
<div><label for="f-payment">Payment</label><select id="f-payment" name="payment">${option("", "Any", input.payment)}${fragments(Object.entries(PaymentLabels).map(([value, label]) => option(value, label, input.payment)))}</select>${fieldError(state.errors, "payment")}</div>
<div><label for="f-fulfillment">Fulfillment</label><select id="f-fulfillment" name="fulfillment">${option("", "Any", input.fulfillment)}${fragments(Object.entries(FulfillmentLabels).map(([value, label]) => option(value, label, input.fulfillment)))}</select>${fieldError(state.errors, "fulfillment")}</div>
<div><button type="submit">Filter orders</button></div>
</form>${filtered ? html`<p><a href="${adminPath("admin-orders")}">Clear filters</a></p>` : html``}`;
  const cards = state.filter === null
    ? html``
    : state.rows.length === 0
      ? html`<p>${filtered ? "No orders match these filters." : "No orders yet."}</p>`
      : html`<ul class="cards">${fragments(state.rows.map((row) => html`<li>
<p><a href="${orderPath(row.number)}"><strong>Order #${row.number}</strong></a> ${when(row.placedAt)}</p>
<p>${row.contactEmail}</p>
<p>${money(row.totalMinor, row)} - ${row.itemCount} ${row.itemCount === 1n ? "item" : "items"}${row.fulfillment === "pickup" ? " - pickup" : ""}</p>
<p>${badge(PaymentLabels[row.paymentState])}${badge(FulfillmentLabels[row.fulfillmentStatus])}${row.openExceptions > 0n ? badge(`${row.openExceptions} open ${row.openExceptions === 1n ? "issue" : "issues"}`) : html``}</p>
</li>`))}</ul>`;
  const older = state.next === null ? html`` : html`<p><a href="${listQuery(input, state.next)}">Older orders</a></p>`;
  return layout("Orders", state.principalLabel, html`${form}${cards}${older}`, stylesheetLink);
}

export interface ShipInput {
  readonly quantities: ReadonlyMap<string, string>;
  readonly carrier: string;
  readonly trackingNumber: string;
  readonly trackingUrl: string;
}

export function shipInputFor(view: OrderDetailView): ShipInput {
  return {
    quantities: new Map(view.lines.map((line) => [`qty_${line.position}`, unfulfilled(lineFulfillmentOf(line)).toString()])),
    carrier: view.fulfillment === "pickup" ? "Local pickup" : "",
    trackingNumber: "",
    trackingUrl: "",
  };
}

export interface OrderPageState {
  readonly view: OrderDetailView;
  readonly principalLabel: string;
  readonly shipToken: string;
  readonly noteToken: string;
  readonly emailToken: string;
  readonly accessToken: string;
  readonly nowSeconds: bigint;
  readonly ship: ShipInput;
  readonly noteInput: string;
  readonly actionTokens: Readonly<Record<OrderAction, string>>;
  readonly actionInputs: Readonly<Partial<Record<OrderAction, ActionInput>>>;
  readonly needsReauth: boolean;
  readonly errors: FieldErrors;
  readonly notice: Notice | null;
  readonly conflict: boolean;
}

function addressBlock(view: OrderDetailView): Html {
  const { address } = view;
  if (address === null) return html`<p>Local pickup. No shipping address.</p>`;
  return html`<p>${address.recipient}<br>${address.line1}<br>${address.line2 === null || address.line2 === "" ? html`` : html`${address.line2}<br>`}${address.city}, ${address.region} ${address.postalCode}<br>${address.country}</p>`;
}

function trackingLink(shipment: OrderDetailView["shipments"][number]): Html {
  const url = shipment.trackingUrl;
  const label = shipment.trackingNumber ?? "Track shipment";
  if (url !== null && validTrackingUrl(url)) return html`<a href="${url}" rel="noopener noreferrer">${label}</a>`;
  return shipment.trackingNumber === null ? html`No tracking number` : html`${shipment.trackingNumber}`;
}

function shipForm(state: OrderPageState): Html {
  const { view, ship } = state;
  const open = view.lines.filter((line) => unfulfilled(lineFulfillmentOf(line)) > 0n);
  if (view.shipBlock !== null) return html`<p role="status">${BlockMessages[view.shipBlock]}</p>`;
  if (open.length === 0) return html`<p role="status">${view.fulfillmentStatus === "canceled" ? "Every item on this order was canceled." : "Every item on this order has shipped."}</p>`;
  return html`<form method="post" action="${orderPath(view.number)}">
<input type="hidden" name="form_token" value="${state.shipToken}">
<input type="hidden" name="revision" value="${view.revision}">
<fieldset><legend>${view.fulfillment === "pickup" ? "Hand over items" : "Ship items"}</legend>
${fieldError(state.errors, "quantities")}
<ul class="cards">${fragments(open.map((line) => {
    const remaining = unfulfilled(lineFulfillmentOf(line));
    const field = `qty_${line.position}`;
    return html`<li><label for="${field}">${line.title}${line.variantLabel === "" ? "" : ` - ${line.variantLabel}`}: quantity to send (${remaining} left)</label>
<input id="${field}" class="quantity" name="${field}" inputmode="numeric" autocomplete="off" value="${ship.quantities.get(field) ?? ""}" aria-describedby="${field}-error">${fieldError(state.errors, field)}</li>`;
  }))}</ul>
<label for="carrier">Carrier</label><input id="carrier" name="carrier" maxlength="60" autocomplete="off" value="${ship.carrier}" aria-describedby="carrier-error" required>${fieldError(state.errors, "carrier")}
<label for="tracking_number">Tracking number (optional)</label><input id="tracking_number" name="tracking_number" maxlength="100" autocomplete="off" value="${ship.trackingNumber}" aria-describedby="tracking_number-error">${fieldError(state.errors, "tracking_number")}
<label for="tracking_url">Tracking link (optional, https://...)</label><input id="tracking_url" name="tracking_url" type="url" maxlength="500" autocomplete="off" value="${ship.trackingUrl}" aria-describedby="tracking_url-error">${fieldError(state.errors, "tracking_url")}
<p><button type="submit">${view.fulfillment === "pickup" ? "Mark as handed over" : "Mark as shipped"}</button></p>
</fieldset>
</form>`;
}

function conflictBlock(state: OrderPageState): Html {
  if (!state.conflict) return html``;
  const { view, ship } = state;
  return html`<section aria-label="Conflict"><h2>Compare</h2><div class="compare">
<div><h3>Your input</h3><ul>${fragments(view.lines.map((line) => html`<li>${line.title}: send ${ship.quantities.get(`qty_${line.position}`) ?? "0"}</li>`))}</ul><p>Carrier: ${ship.carrier}</p></div>
<div><h3>Current values</h3><ul>${fragments(view.lines.map((line) => html`<li>${line.title}: ${unfulfilled(lineFulfillmentOf(line))} left to send</li>`))}</ul></div>
</div></section>`;
}

export function orderPage(state: OrderPageState): Html {
  const { view } = state;
  const open = view.exceptions.filter((entry) => entry.state === "open");
  const issues = open.length === 0
    ? html``
    : html`<section aria-label="Open issues"><h2>Open issues</h2><ul>${fragments(open.map((entry) => html`<li role="alert"><strong>${entry.kind.replaceAll("_", " ")}</strong>: ${entry.detail} (opened ${when(entry.openedAt)})</li>`))}</ul></section>`;
  const lines = html`<ul class="cards">${fragments(view.lines.map((line) => html`<li>
<p><strong>${line.title}</strong>${line.variantLabel === "" ? "" : ` - ${line.variantLabel}`}</p>
<p>${line.quantity} x ${money(line.unitPriceMinor, view)} = ${money(line.lineTotalMinor, view)}</p>
<p class="counts">Shipped ${line.shipped} - Canceled ${line.canceled} - Returned ${line.returned} - Restocked ${line.restocked}</p>
</li>`))}</ul>`;
  const shipments = view.shipments.length === 0
    ? html`<p>Nothing has shipped yet.</p>`
    : html`<ul class="cards">${fragments(view.shipments.map((shipment) => html`<li>
<p><strong>Shipment ${shipment.sequence}</strong> via ${shipment.carrier} ${when(shipment.shippedAt)}</p>
<p>${trackingLink(shipment)}</p>
<p class="counts">${shipment.lines.map((line) => `${line.quantity} x ${view.lines.find((candidate) => candidate.position === line.position)?.title ?? "item"}`).join(", ")} (recorded by ${actorLabel(shipment.actor)})</p>
<p><a href="${adminPath("admin-order-slip", [view.number.toString()])}?shipment=${shipment.sequence}">Packing slip for this shipment</a></p>
</li>`))}</ul>`;
  const refunds = view.refunds.length === 0
    ? html``
    : html`<h2>Refunds</h2><ul>${fragments(view.refunds.map((refund) => html`<li>${money(refund.amountMinor, view)} - ${refundLabel(refund.state)}${refund.failureReason === null ? "" : ` (${refund.failureReason})`}: ${refund.reason}</li>`))}</ul>`;
  const notes = view.notes.length === 0
    ? html`<p>No notes yet.</p>`
    : html`<ul class="cards">${fragments(view.notes.map((note) => html`<li><p class="note">${note.body}</p><p class="counts">${actorLabel(note.actor)} ${when(note.createdAt)}</p></li>`))}</ul>`;
  const timeline = html`<ol>${fragments(view.timeline.map((entry) => html`<li>${when(entry.createdAt)} <strong>${TimelineLabels[entry.action] ?? entry.action}</strong> by ${actorLabel(entry.actor)}: ${entry.summary}</li>`))}</ol>`;
  return layout(`Order #${view.number}`, state.principalLabel, html`${noticeBlock(state.notice)}${conflictBlock(state)}
<p><a href="${adminPath("admin-orders")}">All orders</a> - <a href="${adminPath("admin-order-slip", [view.number.toString()])}">Packing slip</a></p>
<dl class="facts">
<dt>Placed</dt><dd>${when(view.placedAt)}${view.allocation === "late" ? " (late authorization, stock allocated after the hold expired)" : ""}</dd>
<dt>Customer</dt><dd>${view.contactEmail}</dd>
<dt>Payment</dt><dd>${PaymentLabels[view.payment.state]}</dd>
<dt>Fulfillment</dt><dd>${FulfillmentLabels[view.fulfillmentStatus]}</dd>
</dl>
${issues}
<h2>Items</h2>
${lines}
<h2>${view.fulfillment === "pickup" ? "Hand over" : "Fulfill"}</h2>
${shipForm(state)}
<h2>Shipments</h2>
${shipments}
<h2>${view.fulfillment === "pickup" ? "Pickup" : "Ship to"}</h2>
${addressBlock(view)}
${view.shippingZone === null ? html`` : html`<p>Shipping zone: ${view.shippingZone}</p>`}
<h2>Payment</h2>
<dl class="facts">
<dt>Items</dt><dd>${money(view.merchandiseMinor, view)}</dd>
<dt>Shipping</dt><dd>${money(view.shippingMinor, view)}</dd>
<dt>Tax</dt><dd>${money(view.taxMinor, view)}</dd>
<dt>Total</dt><dd>${money(view.totalMinor, view)}</dd>
<dt>Captured</dt><dd>${money(view.payment.capturedMinor, view)} of ${money(view.payment.authorizedMinor, view)} authorized</dd>
<dt>Stripe payment</dt><dd><code>${view.payment.intentId}</code></dd>
</dl>
${refunds}
${actionsSection({ view, tokens: state.actionTokens, inputs: state.actionInputs, errors: state.errors, needsReauth: state.needsReauth })}
${emailsSection({ view, emailToken: state.emailToken, accessToken: state.accessToken, nowSeconds: state.nowSeconds, errors: state.errors })}
<h2>Merchant notes</h2>
<p>Notes are private to the store admin.</p>
${notes}
<form method="post" action="${adminPath("admin-order-note", [view.number.toString()])}">
<input type="hidden" name="form_token" value="${state.noteToken}">
<label for="note">Add a note</label><textarea id="note" name="note" rows="3" maxlength="2000" aria-describedby="note-error">${state.noteInput}</textarea>${fieldError(state.errors, "note")}
<p><button type="submit">Add note</button></p>
</form>
<h2>History</h2>
${timeline}`, stylesheetLink);
}

function refundLabel(state: string): string {
  switch (state) {
    case "succeeded": return "Refunded";
    case "pending": return "Refund pending";
    case "requires_action": return "Refund needs action";
    case "failed": return "Refund failed";
    case "canceled": return "Refund canceled";
    default: return state;
  }
}

export function packingSlipPage(view: OrderDetailView, shipmentSequence: bigint | null): Html {
  const shipment = shipmentSequence === null ? null : view.shipments.find((candidate) => candidate.sequence === shipmentSequence) ?? null;
  const items = shipment === null
    ? view.lines.map((line) => ({ title: line.title, variantLabel: line.variantLabel, quantity: line.quantity }))
    : shipment.lines.flatMap((entry) => {
      const line = view.lines.find((candidate) => candidate.position === entry.position);
      return line === undefined ? [] : [{ title: line.title, variantLabel: line.variantLabel, quantity: entry.quantity }];
    });
  return html`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>Packing slip - Order #${view.number}</title>
${stylesheetLink}
</head>
<body class="slip">
<p class="noprint"><a href="${orderPath(view.number)}">Back to order</a>. Use your browser's print command to print this slip.</p>
<h1>Packing slip - Order #${view.number}</h1>
<p>Placed ${when(view.placedAt)}</p>
<h2>${view.fulfillment === "pickup" ? "Pickup" : "Ship to"}</h2>
${addressBlock(view)}
${shipment === null ? html`` : html`<p>Shipment ${shipment.sequence} via ${shipment.carrier}${shipment.trackingNumber === null ? "" : `, tracking ${shipment.trackingNumber}`}</p>`}
<h2>Items</h2>
<ul>${fragments(items.map((item) => html`<li><strong>${item.quantity} x</strong> ${item.title}${item.variantLabel === "" ? "" : ` - ${item.variantLabel}`}</li>`))}</ul>
</body>
</html>
`;
}
