import { reauthRequired } from "../identity/policy.ts";
import { principalId } from "../identity/principal.ts";
import { adminPath } from "../routes/admin.ts";
import { newToken, parseToken, tokenDigest } from "../session/session.ts";
import { InfoKinds, isInfoKind, type InfoKind } from "../storefront/info.ts";
import { BadInput } from "../web/decode.ts";
import type { AdminBackend } from "./backend.ts";
import { readCatalogForm, type FormValues } from "./catalog_form.ts";
import type { Html } from "./html.ts";
import { digestHex, type AdminSessionView } from "./operations.ts";
import { type FieldErrors, type Notice } from "./pages.ts";
import {
  blockSlotsFromFields, blockSlotsFromView, describeIdentityRejections, describePageRejections, identityFromFields, identityFromView, PageFormKeys, parsePageSlots,
  type BlockSlot, type IdentityForm,
} from "./pages_shop_form.ts";
import type { ShopChange, ShopViewModel } from "./pages_shop_operations.ts";
import { identityPage, pageEditPage, pagesListPage, type ShopPageBase } from "./pages_shop_pages.ts";
import { messagePage } from "./pages.ts";
import { page, redirect } from "./response.ts";

export interface ShopAuth {
  readonly session: AdminSessionView;
  readonly digest: string;
  readonly label: string;
}

export interface ShopHandlerOptions {
  readonly backend: AdminBackend;
  readonly nowSeconds: () => number;
  readonly clearCookies: () => readonly string[];
}

export interface ShopHandler {
  handle(name: string, params: ReadonlyMap<string, string>, request: Request, auth: ShopAuth, signal: AbortSignal): Promise<Response | null>;
}

interface Drawing {
  readonly view: ShopViewModel;
  readonly formToken: string;
  readonly notice: Notice | null;
  readonly errors: FieldErrors;
  readonly conflict: boolean;
}

interface Screen {
  readonly purpose: string;
  readonly path: string;
  render(drawing: Drawing, base: ShopPageBase): Html;
}

const revisionShape = /^(?:0|[1-9][0-9]{0,18})$/;
const MaxInt64 = 9223372036854775807n;
const identityKeys = new Set(["form_token", "revision", "name", "description", "contact_email", "contact_phone"]);

function parseRevision(fields: FormValues): bigint {
  const raw = fields.get("revision") ?? "";
  if (!revisionShape.test(raw) || BigInt(raw) > MaxInt64) throw new BadInput("The form is missing its revision.");
  return BigInt(raw);
}

export function createShopHandler(options: ShopHandlerOptions): ShopHandler {
  const { backend } = options;
  const now = (): number => options.nowSeconds();

  const identityScreen = (echo: IdentityForm | null): Screen => ({
    purpose: "shop.identity", path: adminPath("admin-settings-identity"),
    render: (drawing, base) => identityPage({ ...base, form: echo ?? identityFromView(drawing.view), conflict: drawing.conflict }),
  });
  const pageScreen = (kind: InfoKind, echo: readonly BlockSlot[] | null): Screen => ({
    purpose: `shop.page:${kind}`, path: adminPath("admin-page", [kind]),
    render: (drawing, base) => {
      const current = drawing.view.pages.find((candidate) => candidate.kind === kind);
      if (current === undefined) throw new Error(`shop: page ${kind} is missing`);
      return pageEditPage({ ...base, kind, page: current, slots: echo ?? blockSlotsFromView(current.blocks), conflict: drawing.conflict });
    },
  });

  const noStore = (request: Request, principalLabel: string): Response => page(request, 409, messagePage("Shop identity", "Load a catalog first: the shop has no store record yet.", principalLabel));

  async function draw(request: Request, auth: ShopAuth, screen: Screen, signal: AbortSignal, shown: { readonly status: number; readonly token: string | null; readonly notice: Notice | null; readonly errors: FieldErrors; readonly conflict: boolean }): Promise<Response> {
    let formToken = shown.token;
    let view: ShopViewModel | null;
    if (formToken === null) {
      formToken = newToken();
      view = (await backend.command({ kind: "shop.form", tokenDigest: digestHex(await tokenDigest(formToken)), sessionDigest: auth.digest, purpose: screen.purpose, nowSeconds: now() }, signal)).view;
    } else {
      view = (await backend.query({ kind: "shop.view" }, signal)).view;
    }
    if (view === null) return noStore(request, auth.label);
    const drawing: Drawing = { view, formToken, notice: shown.notice, errors: shown.errors, conflict: shown.conflict };
    return page(request, shown.status, screen.render(drawing, { principalLabel: auth.label, formToken, view, notice: shown.notice, errors: shown.errors }));
  }

  const error = (message: string): Notice => ({ kind: "error", message });
  const unverified = error("This form could not be verified. Review the current values and submit again.");
  const spent = error("This form was already submitted or has expired, so nothing was changed. Review the current values and submit again if needed.");
  const changed = error("This changed after you opened the form, so nothing was changed. Compare the values and submit again.");

  async function show(request: Request, auth: ShopAuth, screen: Screen, signal: AbortSignal): Promise<Response> {
    const url = new URL(request.url).searchParams;
    const notice: Notice | null = url.get("saved") === "1" ? { kind: "info", message: "Saved." } : url.get("reviewed") === "1" ? { kind: "info", message: "Marked as reviewed." } : null;
    return await draw(request, auth, screen, signal, { status: 200, token: null, notice, errors: {}, conflict: false });
  }

  async function submit(
    request: Request, auth: ShopAuth, screen: Screen, signal: AbortSignal, formToken: string, change: ShopChange, done: "saved" | "reviewed",
    describe: (rejections: Extract<Awaited<ReturnType<AdminBackend["command"]>>, { kind: "shop.mutate"; outcome: "rejected" }>["rejections"]) => FieldErrors,
  ): Promise<Response> {
    if (reauthRequired(auth.session.authenticatedAt, now())) {
      return redirect(`${adminPath("admin-reauth")}?return=${encodeURIComponent(screen.path)}`);
    }
    const outcome = await backend.command({
      kind: "shop.mutate", sessionDigest: auth.digest, formTokenDigest: digestHex(await tokenDigest(formToken)), purpose: screen.purpose,
      actor: principalId(auth.session), nowSeconds: now(), change,
    }, signal);
    switch (outcome.outcome) {
      case "applied": return redirect(`${screen.path}?${done}=1`);
      case "session_invalid": return redirect(adminPath("admin-home"), options.clearCookies());
      case "token_invalid": return await draw(request, auth, screen, signal, { status: 409, token: null, notice: spent, errors: {}, conflict: true });
      case "stale": return await draw(request, auth, screen, signal, { status: 409, token: formToken, notice: changed, errors: {}, conflict: true });
      case "missing_store": return noStore(request, auth.label);
      case "rejected": return await draw(request, auth, screen, signal, { status: 422, token: formToken, notice: error("The change was refused. Fix the highlighted fields and submit again."), errors: describe(outcome.rejections), conflict: false });
    }
  }

  async function saveIdentity(request: Request, auth: ShopAuth, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => identityKeys.has(key), signal);
    const form = identityFromFields(fields);
    const screen = identityScreen(form);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, screen, signal, { status: 409, token: null, notice: unverified, errors: {}, conflict: true });
    const change: ShopChange = {
      action: "identity.save", expectedRevision: parseRevision(fields), name: form.name, description: form.description,
      contactEmail: form.contactEmail === "" ? null : form.contactEmail, contactPhone: form.contactPhone === "" ? null : form.contactPhone,
    };
    return await submit(request, auth, screen, signal, formToken, change, "saved", describeIdentityRejections);
  }

  async function savePage(request: Request, auth: ShopAuth, kind: InfoKind, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => key === "form_token" || key === "revision" || PageFormKeys.test(key), signal);
    const slots = blockSlotsFromFields(fields);
    const screen = pageScreen(kind, slots);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, screen, signal, { status: 409, token: null, notice: unverified, errors: {}, conflict: true });
    const parsed = parsePageSlots(slots);
    const change: ShopChange = { action: "page.save", kind, expectedRevision: parseRevision(fields), blocks: parsed.blocks };
    return await submit(request, auth, screen, signal, formToken, change, "saved", (rejections) => describePageRejections(rejections, parsed.slotOf));
  }

  async function reviewPage(request: Request, auth: ShopAuth, kind: InfoKind, signal: AbortSignal): Promise<Response> {
    const fields = await readCatalogForm(request, (key) => key === "form_token" || key === "revision", signal);
    const screen = pageScreen(kind, null);
    const formToken = parseToken(fields.get("form_token") ?? "");
    if (formToken === null) return await draw(request, auth, screen, signal, { status: 409, token: null, notice: unverified, errors: {}, conflict: true });
    const change: ShopChange = { action: "page.review", kind, expectedRevision: parseRevision(fields) };
    return await submit(request, auth, screen, signal, formToken, change, "reviewed", (rejections) => describePageRejections(rejections, []));
  }

  async function list(request: Request, auth: ShopAuth, signal: AbortSignal): Promise<Response> {
    const view = (await backend.query({ kind: "shop.view" }, signal)).view;
    if (view === null) return noStore(request, auth.label);
    return page(request, 200, pagesListPage({ principalLabel: auth.label, view, notice: null }));
  }

  function kindOf(params: ReadonlyMap<string, string>): InfoKind | null {
    const kind = params.get("kind") ?? "";
    return isInfoKind(kind) ? kind : null;
  }

  return {
    async handle(name, params, request, auth, signal) {
      switch (name) {
        case "admin-settings-identity": return await show(request, auth, identityScreen(null), signal);
        case "admin-settings-identity-save": return await saveIdentity(request, auth, signal);
        case "admin-pages": return await list(request, auth, signal);
        case "admin-page":
        case "admin-page-save":
        case "admin-page-review": {
          const kind = kindOf(params);
          if (kind === null) return page(request, 404, messagePage("Not found", `No such page. Pages are: ${InfoKinds.join(", ")}.`, auth.label));
          if (name === "admin-page") return await show(request, auth, pageScreen(kind, null), signal);
          return name === "admin-page-save" ? await savePage(request, auth, kind, signal) : await reviewPage(request, auth, kind, signal);
        }
        default: return null;
      }
    },
  };
}
