import type { BlobReader } from "../media/blob.ts";
import { contentTypeOf, mediaKey, parsePublicMediaPath } from "../media/format.ts";
import { mediaResponse } from "../media/serve.ts";
import type { AdminBackend } from "./backend.ts";
import { adminHeaders, page } from "./response.ts";
import { messagePage } from "./pages.ts";

export interface AdminAsset {
  readonly file: string;
  readonly contentType: string;
  readonly body: Uint8Array<ArrayBuffer>;
}

export interface MediaHandlerOptions {
  readonly backend: AdminBackend;
  readonly blobs: BlobReader;
}

export interface MediaHandler {
  serveMedia(params: ReadonlyMap<string, string>, request: Request, label: string, signal: AbortSignal): Promise<Response>;
}

/**
 * Serves stored media to a signed-in owner whatever its publication state, so
 * the admin can show drafts. The tenant's own store and index are the only
 * places it looks, so another shop's media ids are simply absent.
 */
export function createMediaHandler(options: MediaHandlerOptions): MediaHandler {
  return {
    async serveMedia(params, request, label, signal) {
      const notFound = (): Response => page(request, 404, messagePage("Not found", "That page does not exist.", label));
      const address = parsePublicMediaPath(`/media/${params.get("media_id") ?? ""}/${params.get("file") ?? ""}`);
      if (address === null) return notFound();
      const { asset } = await options.backend.query({ kind: "media.asset", mediaId: address.id }, signal);
      if (asset === null || asset.state !== "ready" || asset.sha256 !== address.sha256 || asset.contentType !== contentTypeOf(address.kind)) return notFound();
      const object = await options.blobs.get(mediaKey(address));
      const response = object === null ? null : mediaResponse(request, address, object, "admin", adminHeaders(null));
      return response ?? notFound();
    },
  };
}

export function assetResponse(request: Request, asset: AdminAsset): Response {
  const headers = adminHeaders(asset.contentType);
  headers.set("Content-Length", String(asset.body.length));
  return new Response(request.method === "HEAD" ? null : asset.body.slice(), { status: 200, headers });
}
