const encoder = new TextEncoder();
const closeHead = encoder.encode("</head>");

export interface HeadMeta {
  readonly path: string;
  readonly indexable: boolean;
  readonly title: string;
  readonly description: string | null;
  readonly type: "website" | "product";
  readonly image: string | null;
  readonly structured: unknown;
}

export interface ProductOffer {
  readonly name: string;
  readonly description: string;
  readonly path: string;
  readonly images: readonly string[];
  readonly vendor: string | null;
  readonly sku: string;
  readonly price: string;
  readonly currency: string;
  readonly available: boolean;
}

export const MaxMetaDescriptionLength = 160;

export function escapeAttribute(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case "\"": return "&quot;";
      default: return "&#39;";
    }
  });
}

/** Serializes a value for a script element: markup and line-separator characters cannot end or confuse the element. */
export function encodeJsonLd(value: unknown): string {
  const text = JSON.stringify(value);
  if (text === undefined) throw new TypeError("seo: structured data is not JSON encodable");
  return text.replace(/[<>&\u2028\u2029]/g, (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`);
}

export function metaDescription(text: string): string | null {
  const flat = text.replace(/\s+/g, " ").trim();
  if (flat === "") return null;
  const characters = [...flat];
  return characters.length <= MaxMetaDescriptionLength ? flat : `${characters.slice(0, MaxMetaDescriptionLength - 1).join("").trimEnd()}…`;
}

export function productStructuredData(offer: ProductOffer, origin: string): unknown {
  return {
    "@context": "https://schema.org",
    "@type": "Product",
    name: offer.name,
    sku: offer.sku,
    url: origin + offer.path,
    ...(offer.description === "" ? {} : { description: offer.description }),
    ...(offer.images.length === 0 ? {} : { image: offer.images.map((image) => absoluteUrl(image, origin)) }),
    ...(offer.vendor === null ? {} : { brand: { "@type": "Brand", name: offer.vendor } }),
    offers: {
      "@type": "Offer",
      url: origin + offer.path,
      price: offer.price,
      priceCurrency: offer.currency,
      availability: offer.available ? "https://schema.org/InStock" : "https://schema.org/OutOfStock",
    },
  };
}

function absoluteUrl(url: string, origin: string): string {
  return url.startsWith("/") ? origin + url : url;
}

export function headFragment(meta: HeadMeta | null, origin: string, siteName: string): string {
  if (meta === null || !meta.indexable) return `<meta name="robots" content="noindex">\n`;
  const tag = (property: string, content: string): string => `<meta property="${property}" content="${escapeAttribute(content)}">\n`;
  const url = origin + meta.path;
  let out = `<link rel="canonical" href="${escapeAttribute(url)}">\n`;
  if (meta.description !== null) out += `<meta name="description" content="${escapeAttribute(meta.description)}">\n`;
  out += tag("og:site_name", siteName) + tag("og:type", meta.type === "product" ? "product" : "website") + tag("og:title", meta.title) + tag("og:url", url);
  if (meta.description !== null) out += tag("og:description", meta.description);
  if (meta.image !== null) out += tag("og:image", absoluteUrl(meta.image, origin));
  if (meta.structured !== null) out += `<script type="application/ld+json">${encodeJsonLd(meta.structured)}</script>\n`;
  return out;
}

export function injectHead(body: Uint8Array, fragment: string): Uint8Array {
  const limit = body.length - closeHead.length;
  let at = -1;
  for (let index = 0; index <= limit && at < 0; index++) {
    if (body[index] !== closeHead[0]) continue;
    let matched = true;
    for (let offset = 1; offset < closeHead.length; offset++) {
      if (body[index + offset] !== closeHead[offset]) { matched = false; break; }
    }
    if (matched) at = index;
  }
  if (at < 0) return body;
  const extra = encoder.encode(fragment);
  const out = new Uint8Array(body.length + extra.length);
  out.set(body.subarray(0, at), 0);
  out.set(extra, at);
  out.set(body.subarray(at), at + extra.length);
  return out;
}

export function sitemapXml(origin: string, paths: readonly string[]): string {
  const urls = paths.map((path) => `<url><loc>${escapeAttribute(origin + path)}</loc></url>`).join("");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls}</urlset>\n`;
}

export const RobotsDisallowed = ["/admin", "/checkout", "/orders", "/cart", "/webhooks"] as const;

export function robotsTxt(origin: string): string {
  return `User-agent: *\n${RobotsDisallowed.map((path) => `Disallow: ${path}\n`).join("")}Sitemap: ${origin}/sitemap.xml\n`;
}
