import { FormTokenLifetimeSeconds, sessionStatus } from "../identity/policy.ts";
import { get, run, type Program } from "./program.ts";

export function digestBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let index = 0; index < bytes.length; index++) bytes[index] = Number.parseInt(hex.slice(index * 2, index * 2 + 2), 16);
  return bytes;
}

export function digestHex(bytes: Uint8Array): string {
  return [...bytes].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

export function* sessionIsLive(sessionDigest: string, nowSeconds: number): Program<boolean> {
  const session = yield* get("GetAdminSession", [digestBytes(sessionDigest)]);
  return session !== null && sessionStatus({ expiresAt: Number(session.expires_at), lastSeenAt: Number(session.last_seen_at) }, nowSeconds) === "valid";
}

export function* checkBinding(binding: FormTokenBinding): Program<"valid" | "session_invalid" | "token_invalid"> {
  if (!(yield* sessionIsLive(binding.sessionDigest, binding.nowSeconds))) return "session_invalid";
  const token = yield* get("GetFormToken", [digestBytes(binding.tokenDigest), digestBytes(binding.sessionDigest)]);
  return token === null || token.purpose !== binding.purpose || Number(token.expires_at) <= binding.nowSeconds ? "token_invalid" : "valid";
}

export interface FormTokenBinding {
  readonly sessionDigest: string;
  readonly tokenDigest: string;
  readonly purpose: string;
  readonly nowSeconds: number;
}

export type Mutation<Applied, Refused> =
  | { readonly applied: true; readonly result: Applied }
  | { readonly applied: false; readonly result: Refused };

export type GuardedMutation<Applied, Refused> =
  | { readonly outcome: "session_invalid" | "token_invalid" }
  | { readonly outcome: "done"; readonly mutation: Mutation<Applied, Refused> };

/**
 * Runs one admin effect inside the caller's transaction. The effect runs only
 * for a live session and an unspent token bound to the same session and
 * purpose, and the token is spent in the same transaction only when the effect
 * applied, so a refused effect leaves the form usable and an applied one can
 * never repeat.
 */
export function* guardedMutation<Applied, Refused>(
  binding: FormTokenBinding,
  effect: () => Program<Mutation<Applied, Refused>>,
): Program<GuardedMutation<Applied, Refused>> {
  const checked = yield* checkBinding(binding);
  if (checked !== "valid") return { outcome: checked };
  const mutation = yield* effect();
  if (mutation.applied) yield* run("DeleteFormToken", [digestBytes(binding.tokenDigest)]);
  return { outcome: "done", mutation };
}


export function* issueFormToken(token: { readonly tokenDigest: string; readonly sessionDigest: string; readonly purpose: string; readonly nowSeconds: number }): Program<boolean> {
  const sessionDigest = digestBytes(token.sessionDigest);
  const session = yield* get("GetAdminSession", [sessionDigest]);
  if (session === null) return false;
  yield* run("DeleteExpiredFormTokens", [sessionDigest, BigInt(token.nowSeconds)]);
  yield* run("TrimFormTokens", [sessionDigest, sessionDigest]);
  yield* run("InsertFormToken", [digestBytes(token.tokenDigest), sessionDigest, token.purpose, BigInt(token.nowSeconds), BigInt(token.nowSeconds + FormTokenLifetimeSeconds)]);
  return true;
}
