import { blockIssues, decodeBlocks, encodeBlocks, InfoKinds, InfoTitles, validContactEmail, validContactPhone, validDescription, validShopName } from "../storefront/info.ts";
import type { Mutation } from "./guard.ts";
import { all, audit, get, run, type Program } from "./program.ts";
import type { ShopChange, ShopPageView, ShopRejection, ShopViewModel } from "./pages_shop_operations.ts";

export interface ShopContext {
  readonly actor: string;
  readonly nowSeconds: bigint;
}

type Refusal =
  | { readonly kind: "stale" }
  | { readonly kind: "missing_store" }
  | { readonly kind: "rejected"; readonly rejections: readonly ShopRejection[] };
type Outcome = Mutation<{ readonly revision: bigint }, Refusal>;

const applied = (revision: bigint): Outcome => ({ applied: true, result: { revision } });
const stale: Outcome = { applied: false, result: { kind: "stale" } };
const rejected = (rejections: readonly ShopRejection[]): Outcome => ({ applied: false, result: { kind: "rejected", rejections } });

export type PageReadiness = "empty" | "unreviewed" | "review_outdated" | "ready";

export function pageReadiness(page: Pick<ShopPageView, "blocks" | "revision" | "review">): PageReadiness {
  if (page.blocks.length === 0) return "empty";
  if (page.review === null) return "unreviewed";
  return page.review.revision === page.revision ? "ready" : "review_outdated";
}

export function readinessGaps(pages: readonly ShopPageView[]): readonly { readonly kind: ShopPageView["kind"]; readonly title: string; readonly readiness: Exclude<PageReadiness, "ready"> }[] {
  return pages.flatMap((page) => {
    const readiness = pageReadiness(page);
    return readiness === "ready" ? [] : [{ kind: page.kind, title: InfoTitles[page.kind], readiness }];
  });
}

export function* shopViewProgram(): Program<ShopViewModel | null> {
  const identity = yield* get("GetShopIdentity", []);
  if (identity === null) return null;
  const states = yield* all("ListShopPageStates", []);
  const pages = InfoKinds.map((kind): ShopPageView => {
    const state = states.find((candidate) => candidate.kind === kind);
    if (state === undefined) throw new Error(`shop: page ${kind} is missing`);
    return {
      kind,
      blocks: decodeBlocks(state.blocks),
      revision: state.revision,
      updatedAt: state.updated_at,
      review: state.reviewed_by === null || state.reviewed_revision === null || state.reviewed_at === null ? null : { by: state.reviewed_by, revision: state.reviewed_revision, at: state.reviewed_at },
    };
  });
  return {
    name: identity.name, description: identity.description, contactEmail: identity.contact_email, contactPhone: identity.contact_phone,
    revision: identity.revision, updatedAt: identity.updated_at, pages,
  };
}

function* saveIdentity(change: Extract<ShopChange, { action: "identity.save" }>, context: ShopContext): Program<Outcome> {
  const current = yield* get("GetShopIdentity", []);
  if (current === null) return { applied: false, result: { kind: "missing_store" } };
  if (current.revision !== change.expectedRevision) return stale;
  const problems: ShopRejection[] = [];
  if (!validShopName(change.name)) problems.push({ subject: "name", kind: change.name.trim() === "" ? "empty" : "invalid" });
  if (!validDescription(change.description)) problems.push({ subject: "description", kind: "invalid" });
  if (change.contactEmail !== null && !validContactEmail(change.contactEmail)) problems.push({ subject: "contact_email", kind: "invalid" });
  if (change.contactPhone !== null && !validContactPhone(change.contactPhone)) problems.push({ subject: "contact_phone", kind: "invalid" });
  if (problems.length > 0) return rejected(problems);
  const changed = [
    ...(current.name === change.name ? [] : ["name"]),
    ...(current.description === change.description ? [] : ["description"]),
    ...(current.contact_email === change.contactEmail ? [] : ["email"]),
    ...(current.contact_phone === change.contactPhone ? [] : ["phone"]),
  ];
  if (changed.length === 0) return applied(current.revision);
  if (current.name !== change.name) yield* run("UpdateShopName", [change.name]);
  yield* run("UpdateShopProfile", [change.description, change.contactEmail, change.contactPhone, context.nowSeconds, current.revision]);
  const revision = current.revision + 1n;
  yield* audit({ actor: context.actor, action: "shop.identity_save", entityKind: "shop_profile", entityId: "1", entityRevision: revision, summary: `changed ${changed.join(", ")}` }, context.nowSeconds);
  return applied(revision);
}

function* savePage(change: Extract<ShopChange, { action: "page.save" }>, context: ShopContext): Program<Outcome> {
  const state = yield* get("GetShopPageState", [change.kind]);
  if (state === null) throw new Error(`shop: page ${change.kind} is missing`);
  if (state.revision !== change.expectedRevision) return stale;
  const issues = blockIssues(change.blocks);
  if (issues.length > 0) return rejected(issues.map((issue) => ({ subject: issue.problem === "page_too_long" || issue.problem === "too_many_blocks" ? "page" : `block_${issue.index}`, kind: issue.problem })));
  const blocks = encodeBlocks(change.blocks);
  if (blocks === state.blocks) return applied(state.revision);
  yield* run("UpdateShopPage", [blocks, context.nowSeconds, change.kind, state.revision]);
  const revision = state.revision + 1n;
  yield* audit({ actor: context.actor, action: "shop.page_save", entityKind: "shop_page", entityId: change.kind, entityRevision: revision, summary: `${InfoTitles[change.kind]}: ${change.blocks.length} blocks` }, context.nowSeconds);
  return applied(revision);
}

function* reviewPage(change: Extract<ShopChange, { action: "page.review" }>, context: ShopContext): Program<Outcome> {
  const state = yield* get("GetShopPageState", [change.kind]);
  if (state === null) throw new Error(`shop: page ${change.kind} is missing`);
  if (state.revision !== change.expectedRevision) return stale;
  if (decodeBlocks(state.blocks).length === 0) return rejected([{ subject: "page", kind: "nothing_to_review" }]);
  yield* run("UpsertShopPageReview", [change.kind, state.revision, context.actor, context.nowSeconds]);
  yield* audit({ actor: context.actor, action: "shop.page_review", entityKind: "shop_page", entityId: change.kind, entityRevision: state.revision, summary: `${InfoTitles[change.kind]} reviewed at revision ${state.revision}` }, context.nowSeconds);
  return applied(state.revision);
}

export function shopEffect(change: ShopChange, context: ShopContext): Program<Outcome> {
  switch (change.action) {
    case "identity.save": return saveIdentity(change, context);
    case "page.save": return savePage(change, context);
    case "page.review": return reviewPage(change, context);
  }
}
