import { Schema } from "effect";

export const CatalogVersion = 1;
export const MaxInt64 = 9223372036854775807n;
export const MaxImportBytes = 32 << 20;
export const MaxProducts = 20000;
export const MaxCollections = 2000;
export const MaxMembersPerCollect = 20000;
export const MaxOptionsPerProduct = 8;
export const MaxValuesPerOption = 100;
export const MaxVariantsPerProduct = 500;
export const MaxImagesPerProduct = 50;
export const MaxDetailsPerProduct = 20;
export const MaxDimension = 1 << 30;
export const MaxLabelBytes = 1 << 10;
export const MaxProseBytes = 16 << 10;
export const MaxURLBytes = 2 << 10;

/** Unicode White_Space excludes the byte-order mark and includes next-line. */
export function isNonblank(value: string): boolean {
  return /[^\u0009-\u000d\u0020\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]/.test(value);
}

function parseDecimal(value: string, kind: "id" | "money"): bigint {
  if (!/^(?:0|[1-9][0-9]*)$/.test(value)) throw new Error(`catalog: ${kind} ${JSON.stringify(value)} is not a canonical decimal string`);
  // Bound length before BigInt parsing to keep adversarial scalar work small.
  if (value.length > 19) throw new Error(`catalog: ${kind} exceeds signed int64`);
  const result = BigInt(value);
  if (result > MaxInt64) throw new Error(`catalog: ${kind} exceeds signed int64`);
  if (kind === "id" && result === 0n) throw new Error("catalog: id is not positive");
  return result;
}
export function parseID(value: string): bigint { return parseDecimal(value, "id"); }
export function parseMoney(value: string): bigint { return parseDecimal(value, "money"); }

const decimalCheck = (kind: "id" | "money") => Schema.makeFilter<string>((value) => {
  try { parseDecimal(value, kind); return true; }
  catch (error) { return error instanceof Error ? error.message : `invalid ${kind}`; }
});
export const IDSchema = Schema.String.check(decimalCheck("id")).pipe(Schema.brand("CatalogID"));
export const MoneySchema = Schema.String.check(decimalCheck("money")).pipe(Schema.brand("CatalogMoney"));
export type ID = typeof IDSchema.Type;
export type Money = typeof MoneySchema.Type;
export const idFromString = Schema.decodeUnknownSync(IDSchema);
export const moneyFromString = Schema.decodeUnknownSync(MoneySchema);

export function moneyAdd(left: Money, right: Money): Money {
  const sum = parseMoney(left) + parseMoney(right);
  if (sum > MaxInt64) throw new Error("catalog: money overflow");
  return moneyFromString(sum.toString());
}
export function moneyMul(price: Money, quantity: bigint): Money {
  if (quantity < 0n) throw new Error("catalog: negative quantity");
  if (quantity > MaxInt64) throw new Error("catalog: quantity exceeds signed int64");
  const total = parseMoney(price) * quantity;
  if (total > MaxInt64) throw new Error("catalog: money overflow");
  return moneyFromString(total.toString());
}
