import { Effect } from "effect";
import { decodeCatalog } from "../catalog/encode.ts";
import { lookupCurrency } from "../catalog/money.ts";
import { parseID, parseMoney } from "../catalog/scalars.ts";
import { validateCatalog } from "../catalog/validate.ts";
import type { Catalog } from "../catalog/schema.ts";
import { DatabaseError, type DatabaseBackend, type SyncTransaction, type Transaction } from "./persistence.ts";
import { StorefrontQueries } from "./queries.ts";

export class CatalogInputError extends Error { readonly _tag = "CatalogInputError"; }
export interface ImportSummary {
  readonly products: number; readonly variants: number; readonly images: number; readonly collections: number; readonly members: number;
  readonly replaced: boolean; readonly sessionsCleared: bigint; readonly cartLinesCleared: bigint;
}

export interface CommercialRecords { readonly variantReferences: bigint; readonly boundRows: bigint; }

/**
 * Replacement deletes every product, so it is refused while any commercial
 * record refers to one. The records are whatever the migrations list in
 * `commercial_variant_references` and `currency_bound_rows`; a later migration
 * that appends its table to those views extends this refusal with no change here.
 */
export function replaceRefusal(records: CommercialRecords): string | null {
  const parts: string[] = [];
  if (records.variantReferences > 0n) parts.push("variants are referenced by commercial records (stock history, reservations, orders, payments)");
  if (records.boundRows > 0n) parts.push("quotes or orders exist");
  if (parts.length === 0) return null;
  return `catalog: --replace refused: ${parts.join(" and ")}. Update the catalog in place with \`nanoshop catalog import --apply\`, archive products, or reset a disposable local shop with --disposable-reset --confirm <tenant>`;
}

export function isLocalhostHost(host: string): boolean {
  const hostname = host.replace(/:[0-9]+$/, "");
  return hostname === "localhost" || hostname.endsWith(".localhost");
}

export function disposableResetRefusal(input: { readonly tenantId: string; readonly host: string; readonly confirm: string }): string | null {
  const hostname = input.host.replace(/:[0-9]+$/, "");
  if (!hostname.endsWith(".localhost")) return `--disposable-reset only applies to a *.localhost shop; ${JSON.stringify(input.host)} is not one`;
  if (input.confirm !== input.tenantId) return `--disposable-reset erases the shop's catalog, stock history, orders, sessions, and admin records; type the tenant ID back with --confirm ${input.tenantId}`;
  return null;
}

export function assertReplaceAllowedSync(tx: SyncTransaction, queries: StorefrontQueries): void {
  const row = queries.requiredSync(tx, "CountCommercialRecords");
  const refusal = replaceRefusal({ variantReferences: row.variant_references, boundRows: row.bound_rows });
  if (refusal !== null) throw new CatalogInputError(refusal);
}

export function assertReplaceAllowed(tx: Transaction, queries: StorefrontQueries): Effect.Effect<void, DatabaseError | CatalogInputError> {
  return Effect.flatMap(queries.required(tx, "CountCommercialRecords"), (row) => {
    const refusal = replaceRefusal({ variantReferences: row.variant_references, boundRows: row.bound_rows });
    return refusal === null ? Effect.void : Effect.fail(new CatalogInputError(refusal));
  });
}

export function parseAndValidateCatalog(input: string | Uint8Array, imageHosts: readonly string[]): Catalog {
  try {
    const catalog = decodeCatalog(input);
    validateCatalog(catalog, imageHosts);
    return catalog;
  } catch (cause) {
    throw new CatalogInputError(cause instanceof Error ? cause.message : String(cause));
  }
}

export function verifyImportSync(tx: SyncTransaction, queries: StorefrontQueries): void {
  if (queries.countSync(tx, "CountStore") !== 1n) throw new DatabaseError("catalog: final transaction requires exactly one store");
  const store = queries.requiredSync(tx, "GetStore");
  try {
    lookupCurrency(store.currency_code, Number(store.currency_exponent));
  } catch (cause) {
    throw new DatabaseError("catalog: invalid final currency", cause);
  }
  for (const product of queries.allSync(tx, "ProductImportStats")) {
    if (product.variants === 0n || (product.options === 0n && product.variants !== 1n)) throw new DatabaseError("catalog: invalid final variant coverage");
  }
  for (const option of queries.allSync(tx, "OptionImportStats")) {
    if (option.opt_values === 0n) throw new DatabaseError("catalog: invalid final option value coverage");
  }
  for (const variant of queries.allSync(tx, "VariantImportStats")) {
    if (variant.selections !== variant.options) throw new DatabaseError("catalog: invalid final variant selections");
  }
  const tuples = new Map<bigint, { product: bigint; selections: string[] }>();
  for (const selection of queries.allSync(tx, "ListVariantSelections")) {
    const tuple = tuples.get(selection.variant_id) ?? { product: selection.product_id, selections: [] };
    tuple.selections.push(`${selection.option_id}:${selection.option_value_id}`);
    tuples.set(selection.variant_id, tuple);
  }
  const seen = new Set<string>();
  for (const tuple of tuples.values()) {
    const key = `${tuple.product}/${tuple.selections.sort().join("\x00")}`;
    if (seen.has(key)) throw new DatabaseError("catalog: duplicate final selection tuple");
    seen.add(key);
  }
}

export function writeCatalogSync(tx: SyncTransaction, queries: StorefrontQueries, catalog: Catalog, replace: boolean): ImportSummary {
  const existing = queries.countSync(tx, "CountStore");
  if (existing > 1n) throw new DatabaseError("catalog: more than one store row");
  if (existing === 1n && !replace) throw new CatalogInputError("catalog: store already has a catalog; use --replace (clears all sessions and cart items)");
  const replaced = existing === 1n && replace;
  if (replaced) assertReplaceAllowedSync(tx, queries);
  const sessionsCleared = replaced ? queries.countSync(tx, "CountSessions") : 0n;
  const cartLinesCleared = replaced ? queries.countSync(tx, "CountCartItems") : 0n;
  if (replaced) {
    for (const name of ["DeleteAllSessions", "DeleteAllProducts", "DeleteAllCollections", "DeleteStore"] as const) queries.runSync(tx, name);
  }
  queries.runSync(tx, "InsertStore", [catalog.store.name, catalog.store.currencyCode, BigInt(catalog.store.currencyExponent)]);
  let variants = 0, images = 0, members = 0;
  for (const product of catalog.products) {
    const productID = parseID(product.id);
    queries.runSync(tx, "InsertProduct", [productID, product.handle, product.title, product.vendor, product.description, product.status]);
    for (const [position, detail] of product.details.entries()) queries.runSync(tx, "InsertProductDetail", [productID, detail.key, detail.title, detail.body, BigInt(position)]);
    for (const [position, option] of product.options.entries()) {
      const optionID = parseID(option.id);
      queries.runSync(tx, "InsertProductOption", [optionID, productID, option.name, BigInt(position)]);
      for (const [valuePosition, value] of option.values.entries()) queries.runSync(tx, "InsertProductOptionValue", [parseID(value.id), optionID, value.value, BigInt(valuePosition)]);
    }
    for (const [position, variant] of product.variants.entries()) {
      const variantID = parseID(variant.id);
      queries.runSync(tx, "InsertProductVariant", [variantID, productID, variant.title, parseMoney(variant.priceMinor), variant.available ? 1n : 0n, BigInt(position)]);
      for (const selection of variant.selections) queries.runSync(tx, "InsertVariantOptionValue", [variantID, productID, parseID(selection.optionId), parseID(selection.valueId)]);
      variants++;
    }
    for (const [position, image] of product.images.entries()) {
      queries.runSync(tx, "InsertProductImage", [parseID(image.id), productID, image.url, image.altText, image.width === null ? null : BigInt(image.width), image.height === null ? null : BigInt(image.height), BigInt(position)]);
      images++;
    }
  }
  for (const collection of catalog.collections) {
    const collectionID = parseID(collection.id);
    queries.runSync(tx, "InsertCollection", [collectionID, collection.handle, collection.title, collection.description, collection.status]);
    for (const [position, productID] of collection.products.entries()) {
      queries.runSync(tx, "InsertCollectionProduct", [collectionID, parseID(productID), BigInt(position)]);
      members++;
    }
  }
  verifyImportSync(tx, queries);
  return { products: catalog.products.length, variants, images, collections: catalog.collections.length, members, replaced, sessionsCleared, cartLinesCleared };
}

export function verifyImport(tx: Transaction, queries: StorefrontQueries): Effect.Effect<void, DatabaseError> {
  return Effect.gen(function* () {
    if ((yield* queries.count(tx, "CountStore")) !== 1n) return yield* Effect.fail(new DatabaseError("catalog: final transaction requires exactly one store"));
    const store = yield* queries.required(tx, "GetStore");
    yield* Effect.try({ try: () => lookupCurrency(store.currency_code, Number(store.currency_exponent)), catch: (cause) => new DatabaseError("catalog: invalid final currency", cause) });
    for (const product of yield* queries.all(tx, "ProductImportStats")) if (product.variants === 0n || (product.options === 0n && product.variants !== 1n)) return yield* Effect.fail(new DatabaseError("catalog: invalid final variant coverage"));
    for (const option of yield* queries.all(tx, "OptionImportStats")) if (option.opt_values === 0n) return yield* Effect.fail(new DatabaseError("catalog: invalid final option value coverage"));
    for (const variant of yield* queries.all(tx, "VariantImportStats")) if (variant.selections !== variant.options) return yield* Effect.fail(new DatabaseError("catalog: invalid final variant selections"));
    const tuples = new Map<bigint, { product: bigint; selections: string[] }>();
    for (const selection of yield* queries.all(tx, "ListVariantSelections")) {
      const tuple = tuples.get(selection.variant_id) ?? { product: selection.product_id, selections: [] };
      tuple.selections.push(`${selection.option_id}:${selection.option_value_id}`);
      tuples.set(selection.variant_id, tuple);
    }
    const seen = new Set<string>();
    for (const tuple of tuples.values()) {
      const key = `${tuple.product}/${tuple.selections.sort().join("\x00")}`;
      if (seen.has(key)) return yield* Effect.fail(new DatabaseError("catalog: duplicate final selection tuple"));
      seen.add(key);
    }
  });
}

/** Replacement clears catalog and sessions together, preventing reused IDs from reinterpreting carts. */
export function loadCatalog(database: DatabaseBackend, queries: StorefrontQueries, input: string | Uint8Array, imageHosts: readonly string[], replace: boolean): Effect.Effect<ImportSummary, DatabaseError | CatalogInputError> {
  return Effect.flatMap(Effect.try({ try: () => parseAndValidateCatalog(input, imageHosts), catch: (cause) => cause instanceof CatalogInputError ? cause : new CatalogInputError(cause instanceof Error ? cause.message : String(cause)) }), (catalog) => database.write((tx) => Effect.gen(function* () {
    const existing = yield* queries.count(tx, "CountStore");
    if (existing > 1n) return yield* Effect.fail(new DatabaseError("catalog: more than one store row"));
    if (existing === 1n && !replace) return yield* Effect.fail(new CatalogInputError("catalog: store already has a catalog; use --replace (clears all sessions and cart items)"));
    const replaced = existing === 1n && replace;
    if (replaced) yield* assertReplaceAllowed(tx, queries);
    const sessionsCleared = replaced ? yield* queries.count(tx, "CountSessions") : 0n;
    const cartLinesCleared = replaced ? yield* queries.count(tx, "CountCartItems") : 0n;
    if (replaced) for (const name of ["DeleteAllSessions", "DeleteAllProducts", "DeleteAllCollections", "DeleteStore"] as const) yield* queries.run(tx, name);
    yield* queries.run(tx, "InsertStore", [catalog.store.name, catalog.store.currencyCode, BigInt(catalog.store.currencyExponent)]);
    let variants = 0, images = 0, members = 0;
    for (const product of catalog.products) {
      const productID = parseID(product.id);
      yield* queries.run(tx, "InsertProduct", [productID, product.handle, product.title, product.vendor, product.description, product.status]);
      for (const [position, detail] of product.details.entries()) yield* queries.run(tx, "InsertProductDetail", [productID, detail.key, detail.title, detail.body, BigInt(position)]);
      for (const [position, option] of product.options.entries()) {
        const optionID = parseID(option.id);
        yield* queries.run(tx, "InsertProductOption", [optionID, productID, option.name, BigInt(position)]);
        for (const [valuePosition, value] of option.values.entries()) yield* queries.run(tx, "InsertProductOptionValue", [parseID(value.id), optionID, value.value, BigInt(valuePosition)]);
      }
      for (const [position, variant] of product.variants.entries()) {
        const variantID = parseID(variant.id);
        yield* queries.run(tx, "InsertProductVariant", [variantID, productID, variant.title, parseMoney(variant.priceMinor), variant.available ? 1n : 0n, BigInt(position)]);
        for (const selection of variant.selections) yield* queries.run(tx, "InsertVariantOptionValue", [variantID, productID, parseID(selection.optionId), parseID(selection.valueId)]);
        variants++;
      }
      for (const [position, image] of product.images.entries()) {
        yield* queries.run(tx, "InsertProductImage", [parseID(image.id), productID, image.url, image.altText, image.width === null ? null : BigInt(image.width), image.height === null ? null : BigInt(image.height), BigInt(position)]);
        images++;
      }
    }
    for (const collection of catalog.collections) {
      const collectionID = parseID(collection.id);
      yield* queries.run(tx, "InsertCollection", [collectionID, collection.handle, collection.title, collection.description, collection.status]);
      for (const [position, productID] of collection.products.entries()) { yield* queries.run(tx, "InsertCollectionProduct", [collectionID, parseID(productID), BigInt(position)]); members++; }
    }
    yield* verifyImport(tx, queries);
    return { products: catalog.products.length, variants, images, collections: catalog.collections.length, members, replaced, sessionsCleared, cartLinesCleared };
  })));
}
