import { Schema } from "effect";
import { parseStrictJSON } from "../json/strict.ts";
import { CatalogSchema, type Catalog } from "./schema.ts";
import { MaxImportBytes } from "./scalars.ts";

const decode = Schema.decodeUnknownSync(CatalogSchema, { onExcessProperty: "error" });
export function decodeCatalog(input: string | Uint8Array): Catalog {
  const bytes = typeof input === "string" ? new TextEncoder().encode(input).length : input.length;
  if (bytes > MaxImportBytes) throw new Error(`catalog: import of ${bytes} bytes exceeds limit ${MaxImportBytes}`);
  return decode(parseStrictJSON(input, { integersOnly: true }));
}

function ordered(catalog: Catalog): Catalog {
  // Reconstruct every record in authority order, independently of input key order.
  return {
    version: catalog.version,
    store: { name: catalog.store.name, currencyCode: catalog.store.currencyCode, currencyExponent: catalog.store.currencyExponent },
    products: catalog.products.map((p) => ({
      id: p.id, handle: p.handle, title: p.title, vendor: p.vendor, description: p.description, status: p.status,
      details: p.details.map((d) => ({ key: d.key, title: d.title, body: d.body })),
      options: p.options.map((o) => ({ id: o.id, name: o.name, values: o.values.map((v) => ({ id: v.id, value: v.value })) })),
      variants: p.variants.map((v) => ({ id: v.id, title: v.title, priceMinor: v.priceMinor, available: v.available, selections: v.selections.map((s) => ({ optionId: s.optionId, valueId: s.valueId })) })),
      images: p.images.map((i) => ({ id: i.id, url: i.url, altText: i.altText, width: i.width, height: i.height })),
    })),
    collections: catalog.collections.map((c) => ({ id: c.id, handle: c.handle, title: c.title, description: c.description, status: c.status, products: c.products })),
  };
}
function serialize(catalog: Catalog, pretty: boolean): string {
  return JSON.stringify(ordered(decode(catalog)), null, pretty ? 2 : undefined)
    .replace(/[<>&\u2028\u2029]/g, (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`);
}
export function encodeCatalog(catalog: Catalog): string { return serialize(catalog, false); }
/** Canonical fixture bytes include two-space indentation and a final newline. */
export function marshalCanonical(catalog: Catalog): Uint8Array {
  return new TextEncoder().encode(serialize(catalog, true) + "\n");
}
