import type { StateMachine } from "./machine.ts";

export const PaymentStates = ["authorized", "in_review", "capture_pending", "capture_unknown", "captured", "void_unknown", "voided"] as const;
export type PaymentState = (typeof PaymentStates)[number];

export const PaymentMachine: StateMachine<PaymentState> = {
  initial: "authorized",
  edges: {
    authorized: ["in_review", "capture_pending", "void_unknown", "voided"],
    in_review: ["authorized", "capture_pending", "void_unknown", "voided"],
    capture_pending: ["captured", "capture_unknown", "authorized", "voided"],
    capture_unknown: ["captured", "authorized", "voided"],
    void_unknown: ["voided", "authorized"],
    captured: [],
    voided: [],
  },
};

export function paymentPath(from: PaymentState, to: PaymentState): readonly PaymentState[] | null {
  if (from === to) return [];
  const previous = new Map<PaymentState, PaymentState>();
  const queue: PaymentState[] = [from];
  while (queue.length > 0) {
    const state = queue.shift()!;
    for (const next of PaymentMachine.edges[state]) {
      if (next === from || previous.has(next)) continue;
      previous.set(next, state);
      if (next === to) {
        const path: PaymentState[] = [to];
        for (let step = state; step !== from; step = previous.get(step)!) path.unshift(step);
        return path;
      }
      queue.push(next);
    }
  }
  return null;
}

export const IntentStatuses = ["requires_payment_method", "requires_confirmation", "requires_action", "processing", "requires_capture", "canceled", "succeeded"] as const;
export type IntentStatus = (typeof IntentStatuses)[number];

export interface IntentFacts {
  readonly id: string;
  readonly status: IntentStatus;
  readonly amountCapturable: bigint;
  readonly amountReceived: bigint;
  readonly currency: string;
  readonly livemode: boolean;
  readonly captureMethod: string;
  readonly paymentMethodTypes: readonly string[];
  readonly usedPaymentMethodType: string | null;
  readonly metadataTenant: string | null;
  readonly metadataAttempt: string | null;
  readonly reviewId: string | null;
  readonly reviewOpen: boolean;
}

export interface AuthorizationExpectation {
  readonly tenantId: string;
  readonly attemptRef: string;
  readonly totalMinor: bigint;
  readonly currency: string;
  readonly livemode: boolean;
}

export const AuthorizationMismatches = ["metadata", "status", "amount", "currency", "livemode", "payment_method", "capture_method"] as const;
export type AuthorizationMismatch = (typeof AuthorizationMismatches)[number];

export type AuthorizationVerdict =
  | { readonly kind: "foreign" }
  | { readonly kind: "not_yet" }
  | { readonly kind: "canceled" }
  | { readonly kind: "verified"; readonly captured: boolean }
  | { readonly kind: "mismatch"; readonly mismatches: readonly AuthorizationMismatch[]; readonly cancelable: boolean };

const notYetAuthorized: readonly IntentStatus[] = ["requires_payment_method", "requires_confirmation", "requires_action", "processing"];

export function verifyAuthorization(intent: IntentFacts, expected: AuthorizationExpectation): AuthorizationVerdict {
  if (intent.metadataTenant !== expected.tenantId) return { kind: "foreign" };
  if (notYetAuthorized.includes(intent.status)) return { kind: "not_yet" };
  if (intent.status === "canceled") return { kind: "canceled" };
  const mismatches: AuthorizationMismatch[] = [];
  if (intent.metadataAttempt !== expected.attemptRef) mismatches.push("metadata");
  const captured = intent.status === "succeeded";
  if (intent.status !== "requires_capture" && !captured) mismatches.push("status");
  if ((captured ? intent.amountReceived : intent.amountCapturable) !== expected.totalMinor) mismatches.push("amount");
  if (intent.currency !== expected.currency.toLowerCase()) mismatches.push("currency");
  if (intent.livemode !== expected.livemode) mismatches.push("livemode");
  if (intent.paymentMethodTypes.length !== 1 || intent.paymentMethodTypes[0] !== "card" || intent.usedPaymentMethodType !== "card") mismatches.push("payment_method");
  if (intent.captureMethod !== "manual") mismatches.push("capture_method");
  if (mismatches.length === 0) return { kind: "verified", captured };
  return { kind: "mismatch", mismatches, cancelable: intent.status === "requires_capture" };
}

export type ObservedPayment =
  | { readonly kind: "captured"; readonly amountMinor: bigint }
  | { readonly kind: "voided" }
  | { readonly kind: "capturable" }
  | { readonly kind: "unmapped" };

export function observePayment(intent: Pick<IntentFacts, "status" | "amountReceived">): ObservedPayment {
  if (intent.status === "succeeded" && intent.amountReceived > 0n) return { kind: "captured", amountMinor: intent.amountReceived };
  if (intent.status === "canceled") return { kind: "voided" };
  if (intent.status === "requires_capture") return { kind: "capturable" };
  return { kind: "unmapped" };
}
