import { adminPath } from "../routes/admin.ts";
import { InfoKinds, InfoTitles, MaxDescriptionBytes, MaxShopNameBytes, type InfoKind } from "../storefront/info.ts";
import { fragments, html, type Html } from "./html.ts";
import { fieldError, layout, noticeBlock, type FieldErrors, type Notice } from "./pages.ts";
import { pageReadiness, readinessGaps, type PageReadiness } from "./pages_shop.ts";
import { blockSlotsFromView, SlotLabels, SlotTypes, visibleSlots, type BlockSlot, type IdentityForm } from "./pages_shop_form.ts";
import type { ShopPageView, ShopViewModel } from "./pages_shop_operations.ts";

export interface ShopPageBase {
  readonly principalLabel: string;
  readonly formToken: string;
  readonly view: ShopViewModel;
  readonly notice: Notice | null;
  readonly errors: FieldErrors;
}

const stamp = (seconds: bigint): string => new Date(Number(seconds) * 1000).toISOString();

const ReadinessLabels: Readonly<Record<PageReadiness, string>> = {
  empty: "Not written yet",
  unreviewed: "Written, not reviewed",
  review_outdated: "Edited since it was reviewed",
  ready: "Reviewed",
};

export function identityPage(state: ShopPageBase & { readonly form: IdentityForm; readonly conflict: boolean }): Html {
  const { view, form } = state;
  const conflict = state.conflict
    ? html`<section aria-label="Conflict"><h2>Compare</h2><div><h3>Your input</h3>${identitySummary(form)}</div><div><h3>Current values</h3>${identitySummary({ name: view.name, description: view.description, contactEmail: view.contactEmail ?? "", contactPhone: view.contactPhone ?? "" })}</div></section>`
    : html``;
  return layout("Shop identity", state.principalLabel, html`<p><a href="${adminPath("admin-settings")}">Settings</a></p>${noticeBlock(state.notice)}${conflict}
<p>Shown in the page header, the footer, and the descriptions search engines and link previews use. Last saved <time datetime="${stamp(view.updatedAt)}">${view.updatedAt === 0n ? "never" : stamp(view.updatedAt)}</time>.</p>
<form method="post" action="${adminPath("admin-settings-identity-save")}">
<input type="hidden" name="form_token" value="${state.formToken}">
<input type="hidden" name="revision" value="${view.revision}">
<p><label>Shop name <input name="name" maxlength="${MaxShopNameBytes}" autocomplete="off" value="${form.name}" aria-describedby="name-error" required></label></p>
${fieldError(state.errors, "name")}
<p><label>Short description, at most ${MaxDescriptionBytes} characters <input name="description" maxlength="${MaxDescriptionBytes}" autocomplete="off" value="${form.description}" aria-describedby="description-error"></label></p>
${fieldError(state.errors, "description")}
<p><label>Contact email, shown to shoppers <input name="contact_email" type="email" autocomplete="off" value="${form.contactEmail}" aria-describedby="contact_email-error"></label></p>
${fieldError(state.errors, "contact_email")}
<p><label>Contact phone, shown to shoppers <input name="contact_phone" type="tel" autocomplete="off" value="${form.contactPhone}" aria-describedby="contact_phone-error"></label></p>
${fieldError(state.errors, "contact_phone")}
<button type="submit">Save identity</button>
</form>`);
}

function identitySummary(form: IdentityForm): Html {
  const show = (value: string): string => (value === "" ? "(empty)" : value);
  return html`<dl><dt>Name</dt><dd>${show(form.name)}</dd><dt>Description</dt><dd>${show(form.description)}</dd><dt>Email</dt><dd>${show(form.contactEmail)}</dd><dt>Phone</dt><dd>${show(form.contactPhone)}</dd></dl>`;
}

export function pagesListPage(state: Omit<ShopPageBase, "formToken" | "errors">): Html {
  const gaps = readinessGaps(state.view.pages);
  const summary = gaps.length === 0
    ? html`<p>Every page is written and reviewed.</p>`
    : html`<p><strong>${gaps.length} of ${InfoKinds.length} pages need your attention before the shop is ready to sell.</strong> Write each page yourself and mark it reviewed once you have read it. The shop supplies no legal text.</p>`;
  const rows = state.view.pages.map((page) => html`<li><a href="${adminPath("admin-page", [page.kind])}">${InfoTitles[page.kind]}</a>: ${ReadinessLabels[pageReadiness(page)]}${page.blocks.length > 0 ? html` (public at <a href="/pages/${page.kind}">/pages/${page.kind}</a>)` : html``}</li>`);
  return layout("Pages", state.principalLabel, html`${noticeBlock(state.notice)}${summary}<ul>${fragments(rows)}</ul>
<p><a href="${adminPath("admin-settings-identity")}">Shop identity and contact</a></p>`);
}

function slotMarkup(slot: BlockSlot, index: number, errors: FieldErrors): Html {
  return html`<fieldset><legend>Block ${index + 1}</legend>
<p><label>Kind <select name="block_${index}_type">${fragments(SlotTypes.map((type) => html`<option value="${type}"${type === slot.type ? html` selected` : html``}>${SlotLabels[type]}</option>`))}</select></label></p>
<p><label>Text<br><textarea name="block_${index}_text" rows="${slot.type === "paragraph" ? 5 : 3}" aria-describedby="block_${index}_text-error">${slot.text}</textarea></label></p>
${fieldError(errors, `block_${index}_text`)}
</fieldset>`;
}

function pageSummary(slots: readonly BlockSlot[]): Html {
  const filled = slots.filter((slot) => slot.text.trim() !== "");
  return filled.length === 0
    ? html`<p>(empty)</p>`
    : html`<ol>${fragments(filled.map((slot) => html`<li>${SlotLabels[slot.type]}: ${slot.text}</li>`))}</ol>`;
}

export function pageEditPage(state: ShopPageBase & { readonly kind: InfoKind; readonly page: ShopPageView; readonly slots: readonly BlockSlot[]; readonly conflict: boolean }): Html {
  const { page, slots } = state;
  const title = InfoTitles[state.kind];
  const readiness = pageReadiness(page);
  const conflict = state.conflict
    ? html`<section aria-label="Conflict"><h2>Compare</h2><div><h3>Your input</h3>${pageSummary(slots)}</div><div><h3>Current values</h3>${pageSummary(blockSlotsFromView(page.blocks))}</div></section>`
    : html``;
  const review = page.review === null ? "Not reviewed yet." : `Last reviewed by ${page.review.by} on ${stamp(page.review.at)}${page.review.revision === page.revision ? "." : `, before the latest edit (revision ${page.review.revision} of ${page.revision}).`}`;
  const reviewForm = page.blocks.length === 0
    ? html`<p>Write the page before marking it reviewed.</p>`
    : html`<form method="post" action="${adminPath("admin-page-review", [state.kind])}">
<input type="hidden" name="form_token" value="${state.formToken}">
<input type="hidden" name="revision" value="${page.revision}">
<button type="submit">${readiness === "ready" ? "Mark reviewed again" : "I have read this page and it is correct"}</button>
</form>`;
  return layout(title, state.principalLabel, html`<p><a href="${adminPath("admin-pages")}">Pages</a></p>${noticeBlock(state.notice)}${conflict}
<p>Status: ${ReadinessLabels[readiness]}. ${review}</p>
${fieldError(state.errors, "page")}
<form method="post" action="${adminPath("admin-page-save", [state.kind])}">
<input type="hidden" name="form_token" value="${state.formToken}">
<input type="hidden" name="revision" value="${page.revision}">
<p>A page is a list of blocks: paragraphs, headings, and bulleted lists. Text is shown exactly as typed; there is no formatting language. Clear a block's text to remove it. A page with no blocks is not published.</p>
${fragments(Array.from({ length: visibleSlots(slots) }, (_, index) => slotMarkup(slots[index] ?? { type: "paragraph", text: "" }, index, state.errors)))}
<button type="submit">Save page</button>
</form>
<h2>Merchant review</h2>
<p>Saving an edit clears the review. The shop writes no policy for you: you are responsible for what these pages say.</p>
${reviewForm}`);
}
