import type { AdminBackend } from "../admin/backend.ts";
import type { AdminCommand, AdminCommandResult } from "../admin/operations.ts";
import { InventoryInvariantError } from "../commerce/inventory.ts";
import { StripeApiError, StripeDecodeError, StripeTransportError } from "../stripe/errors.ts";
import type { CheckoutRejection, CommerceException, CommerceOperation, OperationHook } from "./operations.ts";

export type CommerceExceptionReporter = (exception: CommerceException, error: unknown) => void;

const exceptionNames: Readonly<Record<CommerceException, string>> = {
  "payment.unknown": "PaymentOutcomeUnknown",
  "payment.blocked": "PaymentOperationBlocked",
  "work.dead": "WorkDeadLettered",
  "inventory.invariant": "InventoryInvariantError",
  "email.failed": "EmailDeliveryFailed",
  "provider.error": "ProviderError",
};

export class CommerceExceptionError extends Error {
  readonly exception: CommerceException;
  constructor(exception: CommerceException, message: string) {
    super(message);
    this.name = exceptionNames[exception];
    this.exception = exception;
  }
}

const rejection: Readonly<Record<string, CheckoutRejection>> = {
  paused: "paused",
  no_cart: "no-cart",
  not_found: "not-found",
  blocked: "blocked",
  expired: "expired",
  holds_full: "holds-full",
  changed: "changed",
  insufficient_stock: "insufficient-stock",
};

function rejected(outcome: string): CommerceOperation {
  const reason = rejection[outcome];
  if (reason === undefined) throw new Error(`observe: checkout outcome ${JSON.stringify(outcome)} has no rejection class`);
  return `checkout.rejected.${reason}`;
}

export function commerceOperations(command: AdminCommand, result: AdminCommandResult): readonly CommerceOperation[] {
  switch (result.kind) {
    case "checkout.quote":
    case "checkout.requote":
      return [result.outcome === "quoted" ? "checkout.quote" : rejected(result.outcome)];
    case "checkout.accept":
      if (result.outcome === "accepted") return ["checkout.accept"];
      return result.outcome === "insufficient_stock" ? [rejected(result.outcome), "inventory.conflict"] : [rejected(result.outcome)];
    case "checkout.session.record":
      return result.outcome === "handed_off" ? ["payment.handoff"] : [];
    case "payment.authorize":
      return result.outcome === "placed" || result.outcome === "placed_late" ? ["payment.authorize"] : [];
    case "payment.op.settle":
      return command.kind === "payment.op.settle" && command.opKind === "capture" && command.to === "succeeded" && result.changed ? ["payment.capture"] : [];
    case "webhook.ingest":
      return [result.outcome === "stored" ? "webhook.accepted" : "webhook.duplicate"];
    case "order.refund":
      return result.outcome === "applied" ? ["refund.request"] : [];
    case "order.ship":
      return result.outcome === "applied" ? ["fulfillment.create"] : [];
    case "media.reserve":
      return result.outcome === "reserved" ? ["media.upload"] : [];
    case "stock.adjust":
      return result.outcome === "stale" ? ["inventory.conflict"] : [];
    default:
      return [];
  }
}

export function commerceExceptions(command: AdminCommand, result: AdminCommandResult): readonly CommerceExceptionError[] {
  switch (result.kind) {
    case "payment.op.settle":
      if (command.kind !== "payment.op.settle" || !result.changed) return [];
      if (command.to === "unknown") return [new CommerceExceptionError("payment.unknown", `a ${command.opKind} operation has an unknown provider outcome`)];
      if (command.to === "blocked") return [new CommerceExceptionError("payment.blocked", `a ${command.opKind} operation is blocked`)];
      return [];
    case "payment.block":
      return result.outcome === "blocked" ? [new CommerceExceptionError("payment.blocked", "a checkout attempt's payment is blocked")] : [];
    case "work.fail":
      return result.outcome === "dead" ? [new CommerceExceptionError("work.dead", "a work item was dead-lettered after its last attempt")] : [];
    case "work.claim":
      return result.dead > 0 ? [new CommerceExceptionError("work.dead", `${result.dead} expired work items were dead-lettered`)] : [];
    case "email.settle":
      return command.kind === "email.settle" && command.state === "failed" && result.changed ? [new CommerceExceptionError("email.failed", "a transactional email failed permanently")] : [];
    default:
      return [];
  }
}

export function thrownException(error: unknown): CommerceException | null {
  for (let cause = error, depth = 0; cause instanceof Error && depth < 8; cause = cause.cause, depth += 1) {
    if (cause instanceof InventoryInvariantError) return "inventory.invariant";
    if (cause instanceof StripeApiError || cause instanceof StripeTransportError || cause instanceof StripeDecodeError) return "provider.error";
  }
  return null;
}

export function observeCommerceBackend(backend: AdminBackend, operation: OperationHook): AdminBackend {
  return {
    async command(command, signal) {
      const result = await backend.command(command, signal);
      for (const name of commerceOperations(command, result)) operation(name, {});
      return result;
    },
    query: (query, signal) => backend.query(query, signal),
  };
}
