export interface SearchDocument { readonly title: string; readonly vendor: string; readonly description: string; }
/** Lowercase each scalar independently, then strip canonical non-spacing marks. */
export function fold(value: string): string { return Array.from(value, (character) => character.toLowerCase()).join("").normalize("NFD").replace(/\p{Mn}/gu, ""); }
function gram(bytes: Uint8Array, offset: number): number { return (bytes[offset] ?? 0) * 65536 + (bytes[offset + 1] ?? 0) * 256 + (bytes[offset + 2] ?? 0); }
function contains(doc: SearchDocument, needle: string): boolean { return doc.title.includes(needle) || doc.vendor.includes(needle) || doc.description.includes(needle); }
export function relevance(doc: SearchDocument, needle: string): number {
  if (doc.title.startsWith(needle)) return 0;
  if (doc.title.includes(" " + needle)) return 1;
  if (doc.title.includes(needle)) return 2;
  if (doc.vendor.includes(needle)) return 3;
  return 4;
}
/** UTF-8 trigram postings narrow candidates; literal substring verification owns matches. */
export class SearchIndex {
  readonly documents: readonly SearchDocument[];
  private readonly grams: ReadonlyMap<number, { readonly offset: number; readonly length: number }>;
  private readonly postings: Uint32Array;
  readonly estimatedBytes: number;
  constructor(documents: readonly SearchDocument[]) {
    this.documents = documents.map((doc) => ({ title: fold(doc.title), vendor: fold(doc.vendor), description: fold(doc.description) }));
    const encoder = new TextEncoder();
    const lists = new Map<number, number[]>();
    let textBytes = 0;
    for (const [index, doc] of this.documents.entries()) {
      const seen = new Set<number>();
      for (const field of [doc.title, doc.vendor, doc.description]) {
        const bytes = encoder.encode(field); textBytes += field.length * 2;
        for (let offset = 0; offset + 3 <= bytes.length; offset++) seen.add(gram(bytes, offset));
      }
      for (const key of seen) { const list = lists.get(key) ?? []; list.push(index); lists.set(key, list); }
    }
    let total = 0;
    for (const list of lists.values()) total += list.length;
    this.postings = new Uint32Array(total);
    const spans = new Map<number, { offset: number; length: number }>();
    let offset = 0;
    for (const [key, list] of lists) { spans.set(key, { offset, length: list.length }); this.postings.set(list, offset); offset += list.length; }
    this.grams = spans;
    this.estimatedBytes = this.postings.byteLength + spans.size * 64 + textBytes + documents.length * 64;
  }
  matches(needle: string): readonly number[] {
    const bytes = new TextEncoder().encode(needle);
    let candidates: readonly number[];
    if (bytes.length < 3) candidates = this.documents.map((_, index) => index);
    else {
      const spans: Array<{ readonly offset: number; readonly length: number }> = [];
      const seen = new Set<number>();
      for (let offset = 0; offset + 3 <= bytes.length; offset++) {
        const key = gram(bytes, offset);
        if (seen.has(key)) continue;
        seen.add(key);
        const span = this.grams.get(key);
        if (span === undefined) return [];
        spans.push(span);
      }
      spans.sort((a, b) => a.length - b.length);
      const first = spans[0];
      if (first === undefined) return [];
      let intersection = Array.from(this.postings.subarray(first.offset, first.offset + first.length));
      for (const span of spans.slice(1)) {
        const next: number[] = [], list = this.postings.subarray(span.offset, span.offset + span.length);
        let j = 0;
        for (const index of intersection) {
          while ((list[j] ?? Infinity) < index) j++;
          if (list[j] === index) next.push(index);
        }
        intersection = next;
        if (intersection.length === 0) break;
      }
      candidates = intersection;
    }
    return candidates.filter((index) => { const doc = this.documents[index]; return doc !== undefined && contains(doc, needle); });
  }
}
