import { StripeMaxAmountMinor } from "./version.ts";
import { StripeDecodeError } from "./errors.ts";

export type Decoder<T> = (value: unknown, path: string) => T;

type JsonRecord = Readonly<Record<string, unknown>>;

function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

export function fail(path: string, expected: string, value: unknown): never {
  throw new StripeDecodeError(path, `expected ${expected}, got ${describe(value)}`);
}

export function asRecord(value: unknown, path: string): JsonRecord {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return fail(path, "object", value);
  return value as JsonRecord;
}

export const str: Decoder<string> = (value, path) => typeof value === "string" ? value : fail(path, "string", value);
export const bool: Decoder<boolean> = (value, path) => typeof value === "boolean" ? value : fail(path, "boolean", value);

export const int: Decoder<number> = (value, path) =>
  typeof value === "number" && Number.isSafeInteger(value) ? value : fail(path, "integer", value);

export const amount: Decoder<bigint> = (value, path) => {
  if (typeof value !== "number" || !Number.isSafeInteger(value)) return fail(path, "integer amount", value);
  const parsed = BigInt(value);
  if (parsed < 0n || parsed > StripeMaxAmountMinor) throw new StripeDecodeError(path, `amount ${parsed} outside 0..${StripeMaxAmountMinor}`);
  return parsed;
};

export function nullable<T>(inner: Decoder<T>): Decoder<T | null> {
  return (value, path) => value === null ? null : inner(value, path);
}

export function nullableOrAbsent<T>(inner: Decoder<T>): Decoder<T | null> {
  return (value, path) => value === null || value === undefined ? null : inner(value, path);
}

export function oneOf<const T extends readonly string[]>(allowed: T): Decoder<T[number]> {
  return (value, path) => {
    if (typeof value !== "string" || !allowed.includes(value)) return fail(path, `one of ${allowed.join("|")}`, value);
    return value;
  };
}

export function literal<const T extends string>(expected: T): Decoder<T> {
  return (value, path) => value === expected ? expected : fail(path, JSON.stringify(expected), value);
}

export function array<T>(inner: Decoder<T>): Decoder<readonly T[]> {
  return (value, path) => {
    if (!Array.isArray(value)) return fail(path, "array", value);
    return value.map((item, index) => inner(item, `${path}[${index}]`));
  };
}

export const metadata: Decoder<Readonly<Record<string, string>>> = (value, path) => {
  const record = asRecord(value, path);
  const out: Record<string, string> = Object.create(null) as Record<string, string>;
  for (const [key, entry] of Object.entries(record)) out[key] = str(entry, `${path}.${key}`);
  return out;
};

type Shape = Readonly<Record<string, readonly [wire: string, decode: Decoder<unknown>]>>;
type Decoded<S extends Shape> = { readonly [K in keyof S]: S[K][1] extends Decoder<infer T> ? T : never };

export function object<S extends Shape>(shape: S): Decoder<Decoded<S>> {
  return (value, path) => {
    const record = asRecord(value, path);
    const out: Record<string, unknown> = {};
    for (const [name, [wire, decode]] of Object.entries(shape)) out[name] = decode(record[wire], `${path}.${wire}`);
    return out as Decoded<S>;
  };
}

export function field<T>(wire: string, decode: Decoder<T>): readonly [string, Decoder<T>] {
  return [wire, decode];
}

export function parseJson(text: string, status: number | null): unknown {
  try {
    return JSON.parse(text);
  } catch {
    throw new StripeDecodeError("$", "body is not JSON", status);
  }
}
