import { Effect, Schema } from "effect";
import { CatalogVersion, IDSchema, MaxImportBytes, parseID } from "../catalog/scalars.ts";
import { CatalogSchema, type Catalog, type Detail } from "../catalog/schema.ts";
import { validateCatalog } from "../catalog/validate.ts";
import { parseStrictJSON } from "../json/strict.ts";
import { MAX_QUANTITY } from "../session/session.ts";
import {
  clearMedia,
  CommerceStateTables,
  exportCommerce,
  importCommerce,
  importMedia,
  runSqlEffect,
  runSqlSync,
  validateCommerceState,
  type CommerceState,
} from "../commerce/export.ts";
import { assertReplaceAllowed, assertReplaceAllowedSync, CatalogInputError, verifyImport, writeCatalogSync, type ImportSummary } from "../storefront/import.ts";
import { DatabaseError, type DatabaseBackend, type SQLRow, type SyncTransaction, type Transaction } from "../storefront/persistence.ts";
import type { StorefrontQueries } from "../storefront/queries.ts";

const Hex64Schema = Schema.String.check(
  Schema.makeFilter<string>((value) => /^[0-9a-f]{64}$/.test(value) || "must be a 64-character lowercase hex digest"),
);
const NonNegativeInt64StringSchema = Schema.String.check(
  Schema.makeFilter<string>((value) => {
    if (!/^(?:0|[1-9][0-9]{0,18})$/.test(value)) return "must be a canonical non-negative int64 string";
    try {
      const parsed = BigInt(value);
      return (parsed >= 0n && parsed <= 9223372036854775807n) || "exceeds signed int64";
    } catch {
      return "invalid int64";
    }
  }),
);
const CartQuantitySchema = Schema.Number.check(
  Schema.makeFilter<number>(
    (value) => (Number.isSafeInteger(value) && value >= 1 && value <= MAX_QUANTITY) || `must be 1..${MAX_QUANTITY}`,
  ),
);

export const ExportedCartItemSchema = Schema.Struct({
  variantId: IDSchema,
  quantity: CartQuantitySchema,
  addedAt: NonNegativeInt64StringSchema,
});

export const ExportedSessionSchema = Schema.Struct({
  tokenHash: Hex64Schema,
  createdAt: NonNegativeInt64StringSchema,
  expiresAt: NonNegativeInt64StringSchema,
  items: Schema.Array(ExportedCartItemSchema),
});

export const ExportedTenantStateSchema = Schema.Struct({
  version: Schema.Literal(2),
  catalog: CatalogSchema,
  sessions: Schema.Array(ExportedSessionSchema),
  commerce: Schema.Unknown,
});

export type ExportedTenantState = Omit<typeof ExportedTenantStateSchema.Type, "commerce"> & { readonly commerce: CommerceState };

const decodeStateSchema = Schema.decodeUnknownSync(ExportedTenantStateSchema, { onExcessProperty: "error" });

function orderedCatalog(catalog: Catalog): Catalog {
  return {
    version: catalog.version,
    store: {
      name: catalog.store.name,
      currencyCode: catalog.store.currencyCode,
      currencyExponent: catalog.store.currencyExponent,
    },
    products: catalog.products.map((product) => ({
      id: product.id,
      handle: product.handle,
      title: product.title,
      vendor: product.vendor,
      description: product.description,
      status: product.status,
      details: product.details.map((detail) => ({
        key: detail.key,
        title: detail.title,
        body: detail.body,
      })),
      options: product.options.map((option) => ({
        id: option.id,
        name: option.name,
        values: option.values.map((val) => ({ id: val.id, value: val.value })),
      })),
      variants: product.variants.map((variant) => ({
        id: variant.id,
        title: variant.title,
        priceMinor: variant.priceMinor,
        available: variant.available,
        selections: variant.selections.map((sel) => ({ optionId: sel.optionId, valueId: sel.valueId })),
      })),
      images: product.images.map((image) => ({
        id: image.id,
        url: image.url,
        altText: image.altText,
        width: image.width,
        height: image.height,
      })),
    })),
    collections: catalog.collections.map((collection) => ({
      id: collection.id,
      handle: collection.handle,
      title: collection.title,
      description: collection.description,
      status: collection.status,
      products: [...collection.products],
    })),
  };
}

function orderedState(state: ExportedTenantState): ExportedTenantState {
  const sortedSessions = [...state.sessions]
    .map((session) => ({
      tokenHash: session.tokenHash,
      createdAt: session.createdAt,
      expiresAt: session.expiresAt,
      items: [...session.items].map((item) => ({
        variantId: item.variantId,
        quantity: item.quantity,
        addedAt: item.addedAt,
      })),
    }))
    .sort((left, right) => (left.tokenHash < right.tokenHash ? -1 : left.tokenHash > right.tokenHash ? 1 : 0));
  return {
    version: 2,
    catalog: orderedCatalog(state.catalog),
    sessions: sortedSessions,
    commerce: state.commerce,
  };
}

export function decodeTenantState(input: string | Uint8Array, imageHosts: readonly string[]): ExportedTenantState {
  const byteLength = typeof input === "string" ? new TextEncoder().encode(input).byteLength : input.byteLength;
  if (byteLength > MaxImportBytes) {
    throw new CatalogInputError(`state: import of ${byteLength} bytes exceeds limit ${MaxImportBytes}`);
  }
  try {
    const parsed = parseStrictJSON(input, { integersOnly: true });
    const decoded = decodeStateSchema(parsed);
    const state: ExportedTenantState = { ...decoded, commerce: validateCommerceState(decoded.commerce) };
    validateCatalog(state.catalog, imageHosts);
    const seenSessions = new Set<string>();
    for (const session of state.sessions) {
      if (seenSessions.has(session.tokenHash)) {
        throw new CatalogInputError(`state: duplicate session ${session.tokenHash}`);
      }
      seenSessions.add(session.tokenHash);
      if (BigInt(session.expiresAt) <= BigInt(session.createdAt)) {
        throw new CatalogInputError(`state: session ${session.tokenHash} expiresAt must exceed createdAt`);
      }
      const seenVariants = new Set<string>();
      for (const item of session.items) {
        if (seenVariants.has(item.variantId)) {
          throw new CatalogInputError(`state: duplicate variant ${item.variantId} in session ${session.tokenHash}`);
        }
        seenVariants.add(item.variantId);
      }
    }
    return orderedState(state);
  } catch (cause) {
    if (cause instanceof CatalogInputError) throw cause;
    throw new CatalogInputError(cause instanceof Error ? cause.message : String(cause));
  }
}

function commerceJSON(commerce: CommerceState): string {
  const tables = CommerceStateTables.map((table) => {
    const rows = commerce[table.name] ?? [];
    if (rows.length === 0) return `    ${JSON.stringify(table.name)}: []`;
    return `    ${JSON.stringify(table.name)}: [\n${rows.map((row) => `      ${JSON.stringify(row)}`).join(",\n")}\n    ]`;
  });
  return `  "commerce": {\n${tables.join(",\n")}\n  }`;
}

export function marshalTenantState(state: ExportedTenantState): Uint8Array {
  const { commerce, ...document } = orderedState(state);
  const head = JSON.stringify(document, null, 2);
  const json = `${head.slice(0, -2)},\n${commerceJSON(commerce)}\n}`.replace(
    /[<>&\u2028\u2029]/g,
    (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`,
  );
  return new TextEncoder().encode(`${json}\n`);
}

function strCell(row: SQLRow, column: string): string {
  const val = row[column];
  if (typeof val !== "string") throw new DatabaseError(`state: expected string column ${column}`);
  return val;
}

function nullableStrCell(row: SQLRow, column: string): string | null {
  const val = row[column];
  if (val === null) return null;
  if (typeof val !== "string") throw new DatabaseError(`state: expected nullable string column ${column}`);
  return val;
}

function hexToBytes(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let idx = 0; idx < hex.length; idx += 2) {
    bytes[idx / 2] = Number.parseInt(hex.slice(idx, idx + 2), 16);
  }
  return bytes;
}

interface RawStateRows {
  readonly store: SQLRow | null;
  readonly products: readonly SQLRow[];
  readonly details: readonly SQLRow[];
  readonly options: readonly SQLRow[];
  readonly optionValues: readonly SQLRow[];
  readonly variants: readonly SQLRow[];
  readonly selections: readonly SQLRow[];
  readonly images: readonly SQLRow[];
  readonly collections: readonly SQLRow[];
  readonly members: readonly SQLRow[];
  readonly sessions: readonly SQLRow[];
  readonly cartItems: readonly SQLRow[];
}

const EXPORT_QUERIES = {
  store: "SELECT name, currency_code, CAST(currency_exponent AS TEXT) AS currency_exponent FROM store WHERE id = 1",
  products: "SELECT CAST(id AS TEXT) AS id, handle, title, vendor, description, status FROM products ORDER BY id ASC",
  details: "SELECT CAST(product_id AS TEXT) AS product_id, key, title, body FROM product_details ORDER BY product_id ASC, position ASC",
  options: "SELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id, name FROM product_options ORDER BY product_id ASC, position ASC",
  optionValues: "SELECT CAST(id AS TEXT) AS id, CAST(option_id AS TEXT) AS option_id, value FROM product_option_values ORDER BY option_id ASC, position ASC",
  variants: "SELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id, title, CAST(price_minor AS TEXT) AS price_minor, CAST(available AS TEXT) AS available FROM product_variants ORDER BY product_id ASC, position ASC",
  selections: "SELECT CAST(vov.variant_id AS TEXT) AS variant_id, CAST(vov.option_id AS TEXT) AS option_id, CAST(vov.option_value_id AS TEXT) AS option_value_id FROM variant_option_values vov JOIN product_options po ON po.id = vov.option_id AND po.product_id = vov.product_id ORDER BY vov.variant_id ASC, po.position ASC",
  images: "SELECT CAST(id AS TEXT) AS id, CAST(product_id AS TEXT) AS product_id, url, alt_text, CAST(width AS TEXT) AS width, CAST(height AS TEXT) AS height FROM product_images ORDER BY product_id ASC, position ASC",
  collections: "SELECT CAST(id AS TEXT) AS id, handle, title, description, status FROM collections ORDER BY id ASC",
  members: "SELECT CAST(collection_id AS TEXT) AS collection_id, CAST(product_id AS TEXT) AS product_id FROM collection_products ORDER BY collection_id ASC, position ASC",
  sessions: "SELECT lower(hex(token_hash)) AS token_hash, CAST(created_at AS TEXT) AS created_at, CAST(expires_at AS TEXT) AS expires_at FROM sessions ORDER BY lower(hex(token_hash)) ASC",
  cartItems: "SELECT lower(hex(session_hash)) AS session_hash, CAST(variant_id AS TEXT) AS variant_id, CAST(quantity AS TEXT) AS quantity, CAST(added_at AS TEXT) AS added_at FROM cart_items ORDER BY lower(hex(session_hash)) ASC, added_at ASC, variant_id ASC",
} as const;

function buildExportedState(raw: RawStateRows, commerce: CommerceState): ExportedTenantState {
  if (raw.store === null) throw new DatabaseError("state: no store row; load a catalog first");
  const detailsByProduct = new Map<string, Detail[]>();
  for (const row of raw.details) {
    const productId = strCell(row, "product_id");
    const list = detailsByProduct.get(productId) ?? [];
    list.push({ key: strCell(row, "key"), title: strCell(row, "title"), body: strCell(row, "body") });
    detailsByProduct.set(productId, list);
  }
  const valuesByOption = new Map<string, Array<{ id: string; value: string }>>();
  for (const row of raw.optionValues) {
    const optionId = strCell(row, "option_id");
    const list = valuesByOption.get(optionId) ?? [];
    list.push({ id: strCell(row, "id"), value: strCell(row, "value") });
    valuesByOption.set(optionId, list);
  }
  const optionsByProduct = new Map<string, Array<{ id: string; name: string; values: Array<{ id: string; value: string }> }>>();
  for (const row of raw.options) {
    const optionId = strCell(row, "id");
    const productId = strCell(row, "product_id");
    const list = optionsByProduct.get(productId) ?? [];
    list.push({
      id: optionId,
      name: strCell(row, "name"),
      values: valuesByOption.get(optionId) ?? [],
    });
    optionsByProduct.set(productId, list);
  }
  const selectionsByVariant = new Map<string, Array<{ optionId: string; valueId: string }>>();
  for (const row of raw.selections) {
    const variantId = strCell(row, "variant_id");
    const list = selectionsByVariant.get(variantId) ?? [];
    list.push({ optionId: strCell(row, "option_id"), valueId: strCell(row, "option_value_id") });
    selectionsByVariant.set(variantId, list);
  }
  const variantsByProduct = new Map<
    string,
    Array<{ id: string; title: string | null; priceMinor: string; available: boolean; selections: Array<{ optionId: string; valueId: string }> }>
  >();
  for (const row of raw.variants) {
    const variantId = strCell(row, "id");
    const productId = strCell(row, "product_id");
    const list = variantsByProduct.get(productId) ?? [];
    list.push({
      id: variantId,
      title: nullableStrCell(row, "title"),
      priceMinor: strCell(row, "price_minor"),
      available: strCell(row, "available") === "1",
      selections: selectionsByVariant.get(variantId) ?? [],
    });
    variantsByProduct.set(productId, list);
  }
  const imagesByProduct = new Map<
    string,
    Array<{ id: string; url: string; altText: string; width: number | null; height: number | null }>
  >();
  for (const row of raw.images) {
    const productId = strCell(row, "product_id");
    const widthRaw = nullableStrCell(row, "width");
    const heightRaw = nullableStrCell(row, "height");
    const list = imagesByProduct.get(productId) ?? [];
    list.push({
      id: strCell(row, "id"),
      url: strCell(row, "url"),
      altText: strCell(row, "alt_text"),
      width: widthRaw === null ? null : Number(widthRaw),
      height: heightRaw === null ? null : Number(heightRaw),
    });
    imagesByProduct.set(productId, list);
  }
  const products = raw.products.map((row) => {
    const id = strCell(row, "id");
    return {
      id,
      handle: strCell(row, "handle"),
      title: strCell(row, "title"),
      vendor: nullableStrCell(row, "vendor"),
      description: strCell(row, "description"),
      status: strCell(row, "status"),
      details: detailsByProduct.get(id) ?? [],
      options: optionsByProduct.get(id) ?? [],
      variants: variantsByProduct.get(id) ?? [],
      images: imagesByProduct.get(id) ?? [],
    };
  });
  const membersByCollection = new Map<string, string[]>();
  for (const row of raw.members) {
    const collectionId = strCell(row, "collection_id");
    const list = membersByCollection.get(collectionId) ?? [];
    list.push(strCell(row, "product_id"));
    membersByCollection.set(collectionId, list);
  }
  const collections = raw.collections.map((row) => {
    const id = strCell(row, "id");
    return {
      id,
      handle: strCell(row, "handle"),
      title: strCell(row, "title"),
      description: strCell(row, "description"),
      status: strCell(row, "status"),
      products: membersByCollection.get(id) ?? [],
    };
  });
  const itemsBySession = new Map<string, Array<{ variantId: string; quantity: number; addedAt: string }>>();
  for (const row of raw.cartItems) {
    const sessionHash = strCell(row, "session_hash");
    const list = itemsBySession.get(sessionHash) ?? [];
    list.push({
      variantId: strCell(row, "variant_id"),
      quantity: Number(strCell(row, "quantity")),
      addedAt: strCell(row, "added_at"),
    });
    itemsBySession.set(sessionHash, list);
  }
  const sessions = raw.sessions.map((row) => {
    const tokenHash = strCell(row, "token_hash");
    return {
      tokenHash,
      createdAt: strCell(row, "created_at"),
      expiresAt: strCell(row, "expires_at"),
      items: itemsBySession.get(tokenHash) ?? [],
    };
  });
  const decoded = decodeStateSchema({
    version: 2,
    commerce: null,
    catalog: {
      version: CatalogVersion,
      store: {
        name: strCell(raw.store, "name"),
        currencyCode: strCell(raw.store, "currency_code"),
        currencyExponent: Number(strCell(raw.store, "currency_exponent")),
      },
      products,
      collections,
    },
    sessions,
  });
  const storedImageHosts = [
    ...new Set(
      decoded.catalog.products.flatMap((product) =>
        product.images
          .map((image) => {
            if (!image.url.startsWith("https://")) return "";
            try {
              return new URL(image.url).hostname;
            } catch {
              return "";
            }
          })
          .filter((host) => host !== ""),
      ),
    ),
  ];
  validateCatalog(decoded.catalog, storedImageHosts);
  return orderedState({ ...decoded, commerce });
}

export function exportTenantStateSync(tx: SyncTransaction): ExportedTenantState {
  return buildExportedState(
    {
      store: tx.get(EXPORT_QUERIES.store),
      products: tx.all(EXPORT_QUERIES.products),
      details: tx.all(EXPORT_QUERIES.details),
      options: tx.all(EXPORT_QUERIES.options),
      optionValues: tx.all(EXPORT_QUERIES.optionValues),
      variants: tx.all(EXPORT_QUERIES.variants),
      selections: tx.all(EXPORT_QUERIES.selections),
      images: tx.all(EXPORT_QUERIES.images),
      collections: tx.all(EXPORT_QUERIES.collections),
      members: tx.all(EXPORT_QUERIES.members),
      sessions: tx.all(EXPORT_QUERIES.sessions),
      cartItems: tx.all(EXPORT_QUERIES.cartItems),
    },
    runSqlSync(tx, exportCommerce()),
  );
}

export function exportTenantStateEffect(database: DatabaseBackend): Effect.Effect<ExportedTenantState, DatabaseError> {
  return database.read((tx: Transaction) =>
    Effect.gen(function* () {
      const store = yield* tx.get(EXPORT_QUERIES.store);
      const products = yield* tx.all(EXPORT_QUERIES.products);
      const details = yield* tx.all(EXPORT_QUERIES.details);
      const options = yield* tx.all(EXPORT_QUERIES.options);
      const optionValues = yield* tx.all(EXPORT_QUERIES.optionValues);
      const variants = yield* tx.all(EXPORT_QUERIES.variants);
      const selections = yield* tx.all(EXPORT_QUERIES.selections);
      const images = yield* tx.all(EXPORT_QUERIES.images);
      const collections = yield* tx.all(EXPORT_QUERIES.collections);
      const members = yield* tx.all(EXPORT_QUERIES.members);
      const sessions = yield* tx.all(EXPORT_QUERIES.sessions);
      const cartItems = yield* tx.all(EXPORT_QUERIES.cartItems);
      const commerce = yield* runSqlEffect(tx, exportCommerce());
      return yield* Effect.try({
        try: () =>
          buildExportedState(
            {
              store,
              products,
              details,
              options,
              optionValues,
              variants,
              selections,
              images,
              collections,
              members,
              sessions,
              cartItems,
            },
            commerce,
          ),
        catch: (cause) => (cause instanceof DatabaseError ? cause : new DatabaseError("state: failed to export state", cause)),
      });
    }),
  );
}

export function writeTenantStateSync(
  tx: SyncTransaction,
  queries: StorefrontQueries,
  state: ExportedTenantState,
  replace: boolean,
): ImportSummary {
  const existing = queries.countSync(tx, "CountStore");
  if (existing > 1n) throw new DatabaseError("catalog: more than one store row");
  if (existing === 1n && !replace) {
    throw new CatalogInputError("catalog: store already has a catalog; use --replace (clears all sessions and cart items)");
  }
  const replaced = existing === 1n && replace;
  if (replaced) assertReplaceAllowedSync(tx, queries);
  const sessionsCleared = replaced ? queries.countSync(tx, "CountSessions") : 0n;
  const cartLinesCleared = replaced ? queries.countSync(tx, "CountCartItems") : 0n;
  if (replaced) {
    for (const name of ["DeleteAllSessions", "DeleteAllProducts", "DeleteAllCollections", "DeleteStore"] as const) queries.runSync(tx, name);
    runSqlSync(tx, clearMedia());
  }
  runSqlSync(tx, importMedia(state.commerce));
  const summary = writeCatalogSync(tx, queries, state.catalog, false);
  for (const session of state.sessions) {
    const hash = hexToBytes(session.tokenHash);
    queries.runSync(tx, "InsertSession", [hash, BigInt(session.createdAt), BigInt(session.expiresAt)]);
    for (const item of session.items) {
      queries.runSync(tx, "UpsertCartItem", [hash, parseID(item.variantId), BigInt(item.quantity), BigInt(item.addedAt)]);
    }
  }
  runSqlSync(tx, importCommerce(state.commerce));
  return { ...summary, replaced, sessionsCleared, cartLinesCleared };
}

export function importTenantStateEffect(
  database: DatabaseBackend,
  queries: StorefrontQueries,
  input: string | Uint8Array,
  imageHosts: readonly string[],
  replace: boolean,
): Effect.Effect<ImportSummary, DatabaseError | CatalogInputError> {
  return Effect.flatMap(
    Effect.try({
      try: () => decodeTenantState(input, imageHosts),
      catch: (cause) => (cause instanceof CatalogInputError ? cause : new CatalogInputError(cause instanceof Error ? cause.message : String(cause))),
    }),
    (state) =>
      database.write((tx) =>
        Effect.gen(function* () {
          const existing = yield* queries.count(tx, "CountStore");
          if (existing > 1n) return yield* Effect.fail(new DatabaseError("catalog: more than one store row"));
          if (existing === 1n && !replace) {
            return yield* Effect.fail(
              new CatalogInputError("catalog: store already has a catalog; use --replace (clears all sessions and cart items)"),
            );
          }
          const replaced = existing === 1n && replace;
          if (replaced) yield* assertReplaceAllowed(tx, queries);
          const sessionsCleared = replaced ? yield* queries.count(tx, "CountSessions") : 0n;
          const cartLinesCleared = replaced ? yield* queries.count(tx, "CountCartItems") : 0n;
          if (replaced) {
            for (const name of ["DeleteAllSessions", "DeleteAllProducts", "DeleteAllCollections", "DeleteStore"] as const) {
              yield* queries.run(tx, name);
            }
            yield* runSqlEffect(tx, clearMedia());
          }
          yield* runSqlEffect(tx, importMedia(state.commerce));
          yield* queries.run(tx, "InsertStore", [
            state.catalog.store.name,
            state.catalog.store.currencyCode,
            BigInt(state.catalog.store.currencyExponent),
          ]);
          let variants = 0,
            images = 0,
            members = 0;
          for (const product of state.catalog.products) {
            const productID = parseID(product.id);
            yield* queries.run(tx, "InsertProduct", [
              productID,
              product.handle,
              product.title,
              product.vendor,
              product.description,
              product.status,
            ]);
            for (const [position, detail] of product.details.entries()) {
              yield* queries.run(tx, "InsertProductDetail", [
                productID,
                detail.key,
                detail.title,
                detail.body,
                BigInt(position),
              ]);
            }
            for (const [position, option] of product.options.entries()) {
              const optionID = parseID(option.id);
              yield* queries.run(tx, "InsertProductOption", [optionID, productID, option.name, BigInt(position)]);
              for (const [valuePosition, value] of option.values.entries()) {
                yield* queries.run(tx, "InsertProductOptionValue", [
                  parseID(value.id),
                  optionID,
                  value.value,
                  BigInt(valuePosition),
                ]);
              }
            }
            for (const [position, variant] of product.variants.entries()) {
              const variantID = parseID(variant.id);
              yield* queries.run(tx, "InsertProductVariant", [
                variantID,
                productID,
                variant.title,
                BigInt(variant.priceMinor),
                variant.available ? 1n : 0n,
                BigInt(position),
              ]);
              for (const selection of variant.selections) {
                yield* queries.run(tx, "InsertVariantOptionValue", [
                  variantID,
                  productID,
                  parseID(selection.optionId),
                  parseID(selection.valueId),
                ]);
              }
              variants++;
            }
            for (const [position, image] of product.images.entries()) {
              yield* queries.run(tx, "InsertProductImage", [
                parseID(image.id),
                productID,
                image.url,
                image.altText,
                image.width === null ? null : BigInt(image.width),
                image.height === null ? null : BigInt(image.height),
                BigInt(position),
              ]);
              images++;
            }
          }
          for (const collection of state.catalog.collections) {
            const collectionID = parseID(collection.id);
            yield* queries.run(tx, "InsertCollection", [
              collectionID,
              collection.handle,
              collection.title,
              collection.description,
              collection.status,
            ]);
            for (const [position, productID] of collection.products.entries()) {
              yield* queries.run(tx, "InsertCollectionProduct", [collectionID, parseID(productID), BigInt(position)]);
              members++;
            }
          }
          for (const session of state.sessions) {
            const hash = hexToBytes(session.tokenHash);
            yield* queries.run(tx, "InsertSession", [hash, BigInt(session.createdAt), BigInt(session.expiresAt)]);
            for (const item of session.items) {
              yield* queries.run(tx, "UpsertCartItem", [
                hash,
                parseID(item.variantId),
                BigInt(item.quantity),
                BigInt(item.addedAt),
              ]);
            }
          }
          yield* runSqlEffect(tx, importCommerce(state.commerce));
          yield* verifyImport(tx, queries);
          return {
            products: state.catalog.products.length,
            variants,
            images,
            collections: state.catalog.collections.length,
            members,
            replaced,
            sessionsCleared,
            cartLinesCleared,
          };
        }),
      ),
  );
}
