import { MaxStockQuantity } from "./limits.ts";

export interface LineFulfillment {
  readonly ordered: bigint;
  readonly shipped: bigint;
  readonly canceled: bigint;
  readonly returned: bigint;
  readonly restocked: bigint;
}

export type FulfillmentRejection =
  | "invalid_quantity"
  | "exceeds_unfulfilled"
  | "exceeds_shipped"
  | "exceeds_returned";

export type FulfillmentOutcome =
  | { readonly ok: true; readonly line: LineFulfillment }
  | { readonly ok: false; readonly rejection: FulfillmentRejection };

export type FulfillmentAction = "ship" | "cancel" | "return" | "restock";

export const FulfillmentStatuses = ["unfulfilled", "partially_fulfilled", "fulfilled", "canceled"] as const;
export type FulfillmentStatus = (typeof FulfillmentStatuses)[number];

export function newLine(ordered: bigint): LineFulfillment {
  if (ordered < 1n || ordered > MaxStockQuantity) throw new RangeError("commerce: ordered quantity out of range");
  return { ordered, shipped: 0n, canceled: 0n, returned: 0n, restocked: 0n };
}

export function unfulfilled(line: LineFulfillment): bigint {
  return line.ordered - line.shipped - line.canceled;
}

export function restockable(line: LineFulfillment): bigint {
  return line.returned - line.restocked;
}

export function applyFulfillment(line: LineFulfillment, action: FulfillmentAction, quantity: bigint): FulfillmentOutcome {
  if (quantity < 1n || quantity > MaxStockQuantity) return { ok: false, rejection: "invalid_quantity" };
  switch (action) {
    case "ship":
      return quantity > unfulfilled(line) ? { ok: false, rejection: "exceeds_unfulfilled" } : { ok: true, line: { ...line, shipped: line.shipped + quantity } };
    case "cancel":
      return quantity > unfulfilled(line) ? { ok: false, rejection: "exceeds_unfulfilled" } : { ok: true, line: { ...line, canceled: line.canceled + quantity } };
    case "return":
      return quantity > line.shipped - line.returned ? { ok: false, rejection: "exceeds_shipped" } : { ok: true, line: { ...line, returned: line.returned + quantity } };
    case "restock":
      return quantity > restockable(line) ? { ok: false, rejection: "exceeds_returned" } : { ok: true, line: { ...line, restocked: line.restocked + quantity } };
  }
}

export function fulfillmentStatus(lines: readonly LineFulfillment[]): FulfillmentStatus {
  if (lines.length === 0) throw new RangeError("commerce: an order has at least one line");
  let ordered = 0n, shipped = 0n, canceled = 0n;
  for (const line of lines) { ordered += line.ordered; shipped += line.shipped; canceled += line.canceled; }
  if (canceled === ordered) return "canceled";
  if (shipped === 0n) return "unfulfilled";
  return shipped + canceled === ordered ? "fulfilled" : "partially_fulfilled";
}
