import { MaxCollections, MaxProducts } from "../catalog/scalars.ts";
import type { CartPage } from "../contracts/views.ts";
import {
  buildCartPage,
  prepareAddCart,
  prepareCartRead,
  prepareRemoveCart,
  prepareSetCart,
  type NewSession,
} from "../storefront/cart.ts";
import {
  CatalogSnapshot,
  MaxPublishedRows,
  MaxPublishedTextBytes,
  type CatalogRows,
} from "../storefront/catalog.ts";
import { CatalogTooLargeError } from "../storefront/errors.ts";
import type { OperationHook, RpcMethod } from "../observe/operations.ts";
import type { CaughtReporter } from "./observe/operations.ts";
import { DatabaseError } from "../storefront/persistence.ts";
import type { QueryRow, StorefrontQueries } from "../storefront/queries.ts";
import type { TenantStore as WebTenantStore } from "../web/tenant.ts";
import {
  catalogVersion,
  unwrapRpcResult,
  type AddCartRpcRequest,
  type AddCartRpcResponse,
  type ImportSummaryRpc,
  type RawCatalogPayload,
  type ReadCartRpcRequest,
  type ReadCartRpcResponse,
  type RemoveCartRpcRequest,
  type RpcResult,
  type SetCartRpcRequest,
  type SyncCatalogRpcResponse,
} from "./rpc.ts";

export const MaxIsolateCatalogSnapshotBytes = 32 << 20;
export const CatalogFreshnessMs = 5_000;

export interface TenantStoreRpcStub {
  migrate(nowSeconds?: number): Promise<RpcResult<readonly number[]>>;
  verifyMigrations(): Promise<RpcResult<void>>;
  catalogGeneration(): Promise<RpcResult<string>>;
  syncCatalog(knownVersion: string | null): Promise<RpcResult<SyncCatalogRpcResponse>>;
  readCart(request: ReadCartRpcRequest): Promise<RpcResult<ReadCartRpcResponse>>;
  addToCart(request: AddCartRpcRequest): Promise<RpcResult<AddCartRpcResponse>>;
  setCartQuantity(request: SetCartRpcRequest): Promise<RpcResult<void>>;
  removeCartItem(request: RemoveCartRpcRequest): Promise<RpcResult<void>>;
  beginImport(replace: boolean): Promise<RpcResult<string>>;
  appendImportChunk(importId: string, chunk: Uint8Array): Promise<RpcResult<void>>;
  commitImport(importId: string, imageHosts: readonly string[]): Promise<RpcResult<ImportSummaryRpc>>;
  abortImport(importId: string): Promise<RpcResult<void>>;
  importCatalog(
    chunks: readonly Uint8Array[],
    imageHosts: readonly string[],
    replace: boolean,
  ): Promise<RpcResult<ImportSummaryRpc>>;
  exportState(): Promise<RpcResult<Uint8Array>>;
  importState(
    bytes: Uint8Array,
    imageHosts: readonly string[],
    replace: boolean,
  ): Promise<RpcResult<ImportSummaryRpc>>;
}

function validatePublishedFootprint(
  footprint: QueryRow<"GetPublishedCatalogFootprint">,
  maxSnapshotBytes: number,
): void {
  const counts = [
    footprint.products,
    footprint.variants,
    footprint.selections,
    footprint.option_values,
    footprint.images,
    footprint.details,
    footprint.collections,
    footprint.members,
  ];
  if (
    counts.some((count) => count < 0n) ||
    footprint.text_bytes < 0n ||
    footprint.products > BigInt(MaxProducts) ||
    footprint.collections > BigInt(MaxCollections) ||
    counts.reduce((left, right) => left + right, 0n) > BigInt(MaxPublishedRows) ||
    footprint.text_bytes > BigInt(MaxPublishedTextBytes) ||
    Number(footprint.text_bytes) * 4 > maxSnapshotBytes
  ) {
    throw new CatalogTooLargeError("published row or text footprint");
  }
}

export function buildSnapshotFromRawPayload(
  queries: StorefrontQueries,
  payload: RawCatalogPayload,
  maxSnapshotBytes = MaxIsolateCatalogSnapshotBytes,
): CatalogSnapshot {
  const footprint = queries.decodeRow("GetPublishedCatalogFootprint", payload.footprint);
  validatePublishedFootprint(footprint, maxSnapshotBytes);
  const generation = queries.decodeRow("GetCatalogGeneration", { generation: payload.generation }).generation;
  const stockVersion = queries.decodeRow("GetCatalogVersions", { generation: payload.generation, stock_version: payload.stockVersion }).stock_version;
  const store = queries.decodeRow("GetStore", payload.store);
  const rows: CatalogRows = {
    products: payload.products.map((row) => queries.decodeRow("ListPublishedProducts", row)),
    variants: payload.variants.map((row) => queries.decodeRow("ListPublishedVariants", row)),
    selections: payload.selections.map((row) => queries.decodeRow("ListPublishedSelections", row)),
    options: payload.options.map((row) => queries.decodeRow("ListPublishedOptionValues", row)),
    images: payload.images.map((row) => queries.decodeRow("ListPublishedImages", row)),
    details: payload.details.map((row) => queries.decodeRow("ListPublishedDetails", row)),
    collections: payload.collections.map((row) => queries.decodeRow("ListPublishedCollections", row)),
    members: payload.members.map((row) => queries.decodeRow("ListPublishedMembers", row)),
    profile: queries.decodeRow("GetShopProfile", payload.profile),
    pages: payload.pages.map((row) => queries.decodeRow("ListShopPages", row)),
    redirects: payload.redirects.map((row) => queries.decodeRow("ListPublishedRedirects", row)),
  };
  let snapshot: CatalogSnapshot;
  try {
    snapshot = new CatalogSnapshot(generation, stockVersion, store, rows, footprint);
  } catch (cause) {
    if (cause instanceof CatalogTooLargeError || cause instanceof DatabaseError) throw cause;
    throw new DatabaseError(cause instanceof Error ? cause.message : "storefront: catalog construction failed", cause);
  }
  if (snapshot.estimatedBytes > maxSnapshotBytes) {
    throw new CatalogTooLargeError(
      `estimated isolate snapshot ${snapshot.estimatedBytes} bytes exceeds ${maxSnapshotBytes}`,
    );
  }
  return snapshot;
}

export interface CloudflareTenantStoreOptions {
  readonly now?: () => Date;
  readonly maxSnapshotBytes?: number;
  readonly catalogFreshnessMs?: number;
  readonly reportCaught?: CaughtReporter;
  readonly operation?: OperationHook;
}

export class CloudflareTenantStore implements WebTenantStore {
  private readonly stubProvider: () => TenantStoreRpcStub;
  private readonly queries: StorefrontQueries;
  private readonly now: () => Date;
  private readonly maxSnapshotBytes: number;
  private readonly catalogFreshnessMs: number;
  private readonly reportCaught: CaughtReporter | undefined;
  private readonly operation: OperationHook | undefined;
  private current: CatalogSnapshot | null = null;
  private confirmedAtMs = 0;
  private inflightSync: Promise<CatalogSnapshot> | null = null;

  constructor(
    stubProvider: () => TenantStoreRpcStub,
    queries: StorefrontQueries,
    options: CloudflareTenantStoreOptions = {},
  ) {
    this.stubProvider = stubProvider;
    this.queries = queries;
    this.now = options.now ?? (() => new Date());
    this.maxSnapshotBytes = options.maxSnapshotBytes ?? MaxIsolateCatalogSnapshotBytes;
    this.catalogFreshnessMs = options.catalogFreshnessMs ?? 0;
    this.reportCaught = options.reportCaught;
    this.operation = options.operation;
  }

  private async rpc<T>(method: RpcMethod, call: () => Promise<RpcResult<T>>): Promise<T> {
    const started = performance.now();
    let ok = 0;
    try {
      const result = await call();
      ok = result.ok ? 1 : 0;
      return unwrapRpcResult(result);
    } finally {
      this.operation?.(`store.rpc.${method}`, { durationMs: Math.round(performance.now() - started), ok });
    }
  }

  private snapshotFrom(payload: RawCatalogPayload): CatalogSnapshot {
    const started = performance.now();
    try {
      const snapshot = buildSnapshotFromRawPayload(this.queries, payload, this.maxSnapshotBytes);
      this.operation?.("catalog.load", { rows: snapshot.rowCount, textBytes: snapshot.textBytes, estimatedBytes: snapshot.estimatedBytes, durationMs: Math.round(performance.now() - started) });
      return snapshot;
    } catch (error) {
      if (error instanceof CatalogTooLargeError) this.operation?.("catalog.rejected", {});
      this.reportCaught?.(error instanceof CatalogTooLargeError ? "catalog.rejected" : "catalog.load", error);
      throw error;
    }
  }

  private knownVersion(): string | null {
    return this.current === null ? null : catalogVersion(this.current.generation, this.current.stockVersion);
  }

  residentSnapshot(): CatalogSnapshot | null {
    return this.current;
  }

  evictSnapshot(): void {
    this.current = null;
  }

  private publish(snapshot: CatalogSnapshot): CatalogSnapshot {
    this.confirmedAtMs = this.now().getTime();
    if (this.current === null || this.current.cacheVersion <= snapshot.cacheVersion) {
      this.current = snapshot;
    }
    return this.current;
  }

  async catalog(signal?: AbortSignal): Promise<CatalogSnapshot> {
    signal?.throwIfAborted();
    if (this.current !== null) {
      const elapsedMs = this.now().getTime() - this.confirmedAtMs;
      if (elapsedMs >= 0 && elapsedMs < this.catalogFreshnessMs) {
        this.operation?.("catalog.unchanged", {});
        return this.current;
      }
    }
    return await this.syncCatalog(signal);
  }

  private async syncCatalog(signal?: AbortSignal): Promise<CatalogSnapshot> {
    this.inflightSync ??= this.fetchCatalog().finally(() => {
      this.inflightSync = null;
    });
    const snapshot = await this.inflightSync;
    signal?.throwIfAborted();
    return snapshot;
  }

  private async fetchCatalog(): Promise<CatalogSnapshot> {
    const knownVersion = this.knownVersion();
    const response = await this.rpc("syncCatalog", () => this.stubProvider().syncCatalog(knownVersion));
    if (response.unchanged) {
      if (this.current !== null && this.knownVersion() === response.version) {
        this.confirmedAtMs = this.now().getTime();
        this.operation?.("catalog.unchanged", {});
        return this.current;
      }
      const fallback = await this.rpc("syncCatalog", () => this.stubProvider().syncCatalog(null));
      if (fallback.unchanged) {
        throw new DatabaseError("cloudflare: unexpected unchanged response on cold sync");
      }
      return this.publish(this.snapshotFrom(fallback.payload));
    }
    const snapshot = this.snapshotFrom(response.payload);
    return this.publish(snapshot);
  }

  async cart(
    token: string | null,
    signal?: AbortSignal,
  ): Promise<{ readonly page: CartPage; readonly catalog: CatalogSnapshot }> {
    signal?.throwIfAborted();
    const prepared = await prepareCartRead(token, this.now());
    signal?.throwIfAborted();
    const knownVersion = this.knownVersion();
    const response = await this.rpc("readCart", () =>
      this.stubProvider().readCart({
        tokenHash: prepared.tokenHash,
        nowSeconds: prepared.nowSeconds.toString(),
        knownVersion,
      }),
    );
    signal?.throwIfAborted();
    let catalog: CatalogSnapshot;
    if (response.payload !== null) {
      catalog = this.publish(this.snapshotFrom(response.payload));
    } else if (this.current !== null && this.knownVersion() === response.version) {
      this.confirmedAtMs = this.now().getTime();
      catalog = this.current;
    } else {
      catalog = await this.syncCatalog(signal);
    }
    const cartRows = response.cartRows.map((row) => this.queries.decodeRow("ListCartLines", row));
    const selectionRows = response.selectionRows.map((row) =>
      this.queries.decodeRow("ListVariantSelectionLabels", row),
    );
    return {
      page: buildCartPage(catalog, cartRows, selectionRows),
      catalog,
    };
  }

  async addToCart(
    token: string | null,
    variantID: bigint,
    quantity: number,
    signal?: AbortSignal,
  ): Promise<NewSession | null> {
    signal?.throwIfAborted();
    const prepared = await prepareAddCart(token, variantID, quantity, this.now());
    signal?.throwIfAborted();
    const response = await this.rpc("addToCart", () =>
      this.stubProvider().addToCart({
        tokenHash: prepared.tokenHash,
        variantID: prepared.variantID.toString(),
        quantity: prepared.quantity,
        nowSeconds: prepared.nowSeconds.toString(),
        freshToken: prepared.freshSession.token,
        freshExpiresMs: prepared.freshSession.expires.getTime(),
        freshHash: prepared.freshHash,
        expiresSeconds: prepared.expiresSeconds.toString(),
      }),
    );
    if (response.session === null) return null;
    return {
      token: response.session.token,
      expires: new Date(response.session.expiresMs),
    };
  }

  async setCartQuantity(
    token: string | null,
    variantID: bigint,
    quantity: number,
    signal?: AbortSignal,
  ): Promise<void> {
    signal?.throwIfAborted();
    const prepared = await prepareSetCart(token, variantID, quantity, this.now());
    signal?.throwIfAborted();
    await this.rpc("setCartQuantity", () =>
      this.stubProvider().setCartQuantity({
        tokenHash: prepared.tokenHash,
        variantID: prepared.variantID.toString(),
        quantity: prepared.quantity,
        nowSeconds: prepared.nowSeconds.toString(),
      }),
    );
  }

  async removeCartItem(token: string | null, variantID: bigint, signal?: AbortSignal): Promise<void> {
    if (token === null) return;
    signal?.throwIfAborted();
    const prepared = await prepareRemoveCart(token, variantID, this.now());
    signal?.throwIfAborted();
    await this.rpc("removeCartItem", () =>
      this.stubProvider().removeCartItem({
        tokenHash: prepared.tokenHash,
        variantID: prepared.variantID.toString(),
        nowSeconds: prepared.nowSeconds.toString(),
      }),
    );
  }
}
