export const MaxAttempts = 8;
export const LeaseSeconds = 120;
export const ClaimBatch = 8;
export const BackoffBaseSeconds = 10;
export const BackoffCapSeconds = 3600;
export const MaxErrorLength = 500;

export const WorkStates = ["pending", "leased", "succeeded", "dead"] as const;
export type WorkState = (typeof WorkStates)[number];

export const FailureClasses = ["retryable", "permanent", "blocked"] as const;
export type FailureClass = (typeof FailureClasses)[number];

export interface WorkFailure {
  readonly failureClass: FailureClass;
  readonly message: string;
}

export class WorkError extends Error {
  readonly _tag = "WorkError";
  readonly failureClass: FailureClass;
  constructor(failureClass: FailureClass, message: string, options?: ErrorOptions) {
    super(message, options);
    this.failureClass = failureClass;
  }
}

export type ClaimDecision =
  | { readonly kind: "run"; readonly attempts: number; readonly leaseExpiresAt: number }
  | { readonly kind: "dead"; readonly failure: WorkFailure };

export type FailureDecision =
  | { readonly state: "pending"; readonly nextRunAt: number }
  | { readonly state: "dead" };

export function backoffSeconds(attempts: number): number {
  if (!Number.isInteger(attempts) || attempts < 1) throw new RangeError("work: backoff needs a completed attempt count of at least 1");
  return Math.min(BackoffCapSeconds, BackoffBaseSeconds * 2 ** Math.min(attempts - 1, 20));
}

export function decideClaim(attemptsSoFar: number, nowSeconds: number): ClaimDecision {
  if (attemptsSoFar >= MaxAttempts) {
    return { kind: "dead", failure: { failureClass: "retryable", message: `gave up after ${attemptsSoFar} attempts without a recorded outcome` } };
  }
  return { kind: "run", attempts: attemptsSoFar + 1, leaseExpiresAt: nowSeconds + LeaseSeconds };
}

export function decideFailure(attempts: number, failureClass: FailureClass, nowSeconds: number): FailureDecision {
  if (failureClass !== "retryable" || attempts >= MaxAttempts) return { state: "dead" };
  return { state: "pending", nextRunAt: nowSeconds + backoffSeconds(attempts) };
}

export function clampError(message: string): string {
  return message.length <= MaxErrorLength ? message : `${message.slice(0, MaxErrorLength - 3)}...`;
}

export function failureOf(error: unknown): WorkFailure {
  if (error instanceof WorkError) return { failureClass: error.failureClass, message: clampError(error.message) };
  return { failureClass: "retryable", message: clampError(error instanceof Error ? error.message : String(error)) };
}
