import { MaintenanceBatch, GraceSeconds, MaxMediaAssets, MaxPendingMedia, PendingTtlSeconds } from "../media/limits.ts";
import { kindOfContentType, publicMediaPath, type MediaAddress } from "../media/format.ts";
import { MaxImagesPerProduct } from "../catalog/scalars.ts";
import { checkBinding } from "./guard.ts";
import type { AdminCommand, AdminCommandResult, AdminQuery, AdminQueryResult } from "./operations.ts";
import { all, get, run, type Program } from "./program.ts";
import type { AdminQueryRow } from "./queries.ts";

function addressOf(row: Pick<AdminQueryRow<"GetMediaAsset">, "id" | "sha256" | "content_type">): MediaAddress {
  const kind = kindOfContentType(row.content_type);
  if (kind === null) throw new Error(`media: stored content type ${JSON.stringify(row.content_type)} is not an image type`);
  return { id: row.id, sha256: row.sha256, kind };
}

export function pathOfAsset(row: Pick<AdminQueryRow<"GetMediaAsset">, "id" | "sha256" | "content_type">): string {
  return publicMediaPath(addressOf(row));
}

type Reserve = Extract<AdminCommand, { kind: "media.reserve" }>;

export function* reserveMedia(command: Reserve): Program<AdminCommandResult> {
  const checked = yield* checkBinding({ sessionDigest: command.sessionDigest, tokenDigest: command.formTokenDigest, purpose: command.purpose, nowSeconds: command.nowSeconds });
  if (checked !== "valid") return { kind: "media.reserve", outcome: checked };
  const product = yield* get("GetCatalogProduct", [command.productId]);
  if (product === null) return { kind: "media.reserve", outcome: "rejected", rejection: "unknown_product" };
  if (product.revision !== command.expectedRevision) return { kind: "media.reserve", outcome: "stale" };
  if ((yield* get("CountCatalogProductImages", [command.productId]))!.n >= BigInt(MaxImagesPerProduct)) return { kind: "media.reserve", outcome: "rejected", rejection: "image_limit" };
  const live = (yield* get("CountPendingMedia", [BigInt(command.nowSeconds - PendingTtlSeconds)]))!.n;
  if (live + BigInt(command.files.length) > BigInt(MaxPendingMedia)) return { kind: "media.reserve", outcome: "rejected", rejection: "too_many_pending" };
  const total = (yield* get("CountMediaAssets", []))!.n;
  if (total + BigInt(command.files.length) > BigInt(MaxMediaAssets)) return { kind: "media.reserve", outcome: "rejected", rejection: "library_full" };
  const first = (yield* get("NextMediaId", []))!.id;
  const ids: bigint[] = [];
  for (const [index, file] of command.files.entries()) {
    const id = first + BigInt(index);
    yield* run("InsertPendingMedia", [id, file.sha256, file.bytes, file.width, file.height, file.contentType, BigInt(command.nowSeconds)]);
    ids.push(id);
  }
  return { kind: "media.reserve", outcome: "reserved", ids };
}

function removed(rows: readonly Pick<AdminQueryRow<"GetMediaAsset">, "id" | "sha256" | "content_type">[]): readonly { readonly id: bigint; readonly sha256: string; readonly contentType: string }[] {
  return rows.map((row) => ({ id: row.id, sha256: row.sha256, contentType: row.content_type }));
}

export function* expirePendingMedia(nowSeconds: number): Program<AdminCommandResult> {
  const rows = yield* all("ListExpiredPendingMedia", [BigInt(nowSeconds - PendingTtlSeconds)]);
  for (const row of rows) yield* run("DeleteMediaAsset", [row.id]);
  return { kind: "media.expire", removed: removed(rows) };
}

/**
 * Deletes ready media that nothing references and that became ready more than
 * the grace period ago. The reference check is the media_references view and
 * the delete guard trigger built on it, so a new kind of reference extends
 * that one view and nothing here.
 */
export function* collectUnreferencedMedia(nowSeconds: number): Program<AdminCommandResult> {
  const rows = yield* all("ListUnreferencedMedia", [BigInt(nowSeconds - GraceSeconds)]);
  for (const row of rows) yield* run("DeleteMediaAsset", [row.id]);
  return { kind: "media.collect", removed: removed(rows) };
}

export function* findOrphans(ids: readonly bigint[]): Program<AdminCommandResult> {
  if (ids.length > MaintenanceBatch) throw new RangeError("media: too many ids");
  const orphans: bigint[] = [];
  for (const id of ids) if ((yield* get("GetMediaAsset", [id])) === null) orphans.push(id);
  return { kind: "media.orphans", orphans };
}

export function* mediaAssetView(query: Extract<AdminQuery, { kind: "media.asset" }>): Program<Extract<AdminQueryResult, { kind: "media.asset" }>> {
  const row = yield* get("GetMediaAsset", [query.mediaId]);
  if (row === null) return { kind: "media.asset", asset: null };
  if (row.state !== "pending" && row.state !== "ready") throw new Error(`media: stored state ${JSON.stringify(row.state)} is not a media state`);
  return { kind: "media.asset", asset: { sha256: row.sha256, contentType: row.content_type, state: row.state } };
}
