import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const NullableText = Schema.NullOr(Text);
const NullableInteger = Schema.NullOr(Integer);
const Digest = Schema.instanceOf(Uint8Array);

export const emailRowSchemas = {
  GetEmailMessage: Schema.Struct({
    id: Integer, kind: Text, order_id: NullableInteger, attempt_id: NullableInteger, subject_id: Integer, generation: Integer, state: Text, attempts: Integer,
    first_attempt_at: NullableInteger, last_attempt_at: NullableInteger, provider_id: NullableText, last_error: NullableText, created_at: Integer,
  }),
  GetEmailMessageBySubject: Schema.Struct({ id: Integer, generation: Integer }),
  GetNewestEmailMessage: Schema.Struct({ id: Integer, generation: Integer }),
  ListOrderEmails: Schema.Struct({
    id: Integer, kind: Text, generation: Integer, state: Text, attempts: Integer, first_attempt_at: NullableInteger, last_error: NullableText, created_at: Integer,
  }),
  GetEmailOrder: Schema.Struct({
    id: Integer, number: Integer, contact_email: Text, currency_code: Text, currency_exponent: Integer, shop_name: Text, fulfillment: Text,
    city: NullableText, region: NullableText, total_minor: Integer,
  }),
  GetEmailAttempt: Schema.Struct({ id: Integer, contact_email: Text, currency_code: Text, currency_exponent: Integer, shop_name: Text, total_minor: Integer }),
  GetEmailRefund: Schema.Struct({ amount_minor: Integer }),
  GetOrderRevisionById: Schema.Struct({ revision: Integer }),
  GetOrderAccessGrant: Schema.Struct({ order_id: Integer, number: Integer }),
  GetOrderLookupTarget: Schema.Struct({ id: Integer, email_digest: Schema.NullOr(Digest) }),
  CountOrderLookups: Schema.Struct({ n: Integer }),
} as const;

export const emailWriteQueries = [
  "InsertEmailMessage", "BeginEmailAttempt", "SettleEmailMessage", "ExpireUnknownEmail", "RequeueEmailMessage", "InsertOrderAccess", "RevokeOrderAccess",
  "InsertOrderLookup", "DeleteStaleOrderLookups",
] as const;
