import type { CheckoutLineInput, CreateCheckoutSessionParams, StripeClient } from "../stripe/index.ts";
import { routePath } from "../routes/routes.ts";
import type { HostedSession, HostedSessionCreator, HostedSessionRequest } from "./session_creator.ts";

export const HostedSessionLifetimeSeconds = 30 * 60;
export const HostedSessionStartMarginSeconds = 60;

export interface StripeSessionShop {
  readonly tenantId: string;
  readonly origin: string;
}

function percent(ratePpm: bigint): string {
  return `${Number(ratePpm) / 10000}%`;
}

export function hostedSessionParams(request: HostedSessionRequest, shop: StripeSessionShop): CreateCheckoutSessionParams {
  const quote = request.quote;
  const lines: CheckoutLineInput[] = quote.lines.map((line) => ({
    name: line.variantLabel === "" ? line.title : `${line.title} (${line.variantLabel})`,
    unitAmount: line.unitPriceMinor,
    quantity: Number(line.quantity),
  }));
  if (quote.shippingMinor > 0n) lines.push({ name: quote.shippingZone === null ? "Shipping" : `Shipping to ${quote.shippingZone}`, unitAmount: quote.shippingMinor, quantity: 1 });
  const taxByRate = new Map<bigint, bigint>();
  for (const tax of quote.taxLines) if (tax.taxMinor > 0n) taxByRate.set(tax.ratePpm, (taxByRate.get(tax.ratePpm) ?? 0n) + tax.taxMinor);
  for (const [rate, amount] of taxByRate) lines.push({ name: `Tax at ${percent(rate)}`, unitAmount: amount, quantity: 1 });
  const total = lines.reduce((sum, line) => sum + line.unitAmount * BigInt(line.quantity), 0n);
  if (total !== quote.totalMinor) throw new Error(`checkout: hosted session lines total ${total}, the accepted quote totals ${quote.totalMinor}`);
  const attemptUrl = `${shop.origin}${routePath("checkout-attempt", [request.attemptRef])}`;
  return {
    currency: quote.currency.toLowerCase(),
    lines,
    customerEmail: quote.email,
    successUrl: attemptUrl,
    cancelUrl: attemptUrl,
    expiresAt: request.acceptedAtSeconds + HostedSessionLifetimeSeconds + HostedSessionStartMarginSeconds,
    clientReferenceId: request.attemptRef,
    metadata: { nanoshop_tenant: shop.tenantId, nanoshop_attempt: request.attemptRef },
  };
}

export class StripeHostedSessionCreator implements HostedSessionCreator {
  readonly #stripe: () => StripeClient;
  readonly #shop: StripeSessionShop;

  constructor(stripe: () => StripeClient, shop: StripeSessionShop) {
    this.#stripe = stripe;
    this.#shop = shop;
  }

  async create(request: HostedSessionRequest): Promise<HostedSession> {
    const session = await this.#stripe().createCheckoutSession(hostedSessionParams(request, this.#shop), request.idempotencyKey);
    if (session.url === null) throw new Error(`checkout: hosted session ${session.id} has no payment page URL`);
    if (session.clientReferenceId !== request.attemptRef) throw new Error(`checkout: hosted session ${session.id} belongs to another attempt`);
    return { sessionId: session.id, url: session.url, expiresAtSeconds: session.expiresAt };
  }
}
