import { all, get, run, type Program } from "../admin/program.ts";
import { StalledRefundSeconds, type Backlog, type ClaimedWorkItem } from "./work_operations.ts";
import type { WorkCommandSchemas, WorkQuerySchemas, WorkQueryResultSchemas, WorkResultSchemas } from "./work_operations.ts";
import { clampError, decideClaim, decideFailure } from "./work.ts";

export const RetentionSeconds = 30 * 24 * 3600;
export const ProviderEventKind = "provider_event";
export const providerEventKey = (eventId: string): string => `${ProviderEventKind}:${eventId}`;

export type WorkCommand = (typeof WorkCommandSchemas)[number]["Type"];
export type WorkQuery = (typeof WorkQuerySchemas)[number]["Type"];
export type WorkCommandResult = (typeof WorkResultSchemas)[number]["Type"];
export type WorkQueryResult = (typeof WorkQueryResultSchemas)[number]["Type"];

type Of<C extends WorkCommand["kind"]> = Extract<WorkCommand, { readonly kind: C }>;

function* claim(command: Of<"work.claim">): Program<WorkCommandResult> {
  const now = BigInt(command.nowSeconds);
  const rows = yield* all("ListClaimableWork", [now, now, BigInt(command.limit)]);
  const items: ClaimedWorkItem[] = [];
  let dead = 0;
  for (const row of rows) {
    const before = Number(row.attempts);
    const decision = decideClaim(before, command.nowSeconds);
    if (decision.kind === "dead") {
      const killed = yield* run("KillWorkItem", [decision.failure.failureClass, clampError(decision.failure.message), now, row.id, BigInt(before)]);
      if (killed > 0n) dead += 1;
      continue;
    }
    const claimed = yield* run("ClaimWorkItem", [BigInt(decision.attempts), command.owner, BigInt(decision.leaseExpiresAt), now, row.id, BigInt(before), now, now]);
    if (claimed > 0n) items.push({ id: row.id, kind: row.kind, key: row.unique_key, payload: row.payload, attempts: decision.attempts });
  }
  return { kind: "work.claim", items, dead };
}

function* complete(command: Of<"work.complete">): Program<WorkCommandResult> {
  const now = BigInt(command.nowSeconds);
  const changed = command.reschedule === null
    ? yield* run("CompleteWorkItem", [now, command.id, command.owner, BigInt(command.attempts)])
    : yield* run("RescheduleWorkItem", [BigInt(command.reschedule.at), command.reschedule.payload, now, command.id, command.owner, BigInt(command.attempts)]);
  return { kind: "work.complete", outcome: changed > 0n ? "completed" : "lost" };
}

function* fail(command: Of<"work.fail">): Program<WorkCommandResult> {
  const now = BigInt(command.nowSeconds);
  const decision = decideFailure(command.attempts, command.failureClass, command.nowSeconds);
  const nextRunAt = decision.state === "pending" ? decision.nextRunAt : command.nowSeconds;
  const changed = yield* run("FailWorkItem", [decision.state, BigInt(nextRunAt), command.failureClass, clampError(command.message), now, command.id, command.owner, BigInt(command.attempts)]);
  if (changed === 0n) return { kind: "work.fail", outcome: "lost", nextRunAt: null };
  return decision.state === "pending" ? { kind: "work.fail", outcome: "retry", nextRunAt: decision.nextRunAt } : { kind: "work.fail", outcome: "dead", nextRunAt: null };
}

export function* markProviderEventProcessed(eventId: string, nowSeconds: number): Program<boolean> {
  return (yield* run("MarkProviderEventProcessed", [BigInt(nowSeconds), eventId])) > 0n;
}

export function* workCommandProgram(command: WorkCommand): Program<WorkCommandResult> {
  const now = BigInt(command.nowSeconds);
  switch (command.kind) {
    case "work.claim": return yield* claim(command);
    case "work.complete": return yield* complete(command);
    case "work.fail": return yield* fail(command);
    case "work.requeue": return { kind: "work.requeue", requeued: (yield* run("RequeueWorkItem", [now, now, command.id])) > 0n };
    case "work.ensure_periodic": {
      let created = 0;
      for (const item of command.items) if ((yield* run("EnsureWorkItem", [item.kind, item.key, "{}", now, now, now])) > 0n) created += 1;
      return { kind: "work.ensure_periodic", created };
    }
    case "work.purge": {
      const cutoff = BigInt(Math.max(0, command.nowSeconds - RetentionSeconds));
      return { kind: "work.purge", bodies: yield* run("PurgeProviderEventBodies", [now, cutoff]), items: yield* run("DeleteSucceededWork", [cutoff]) };
    }
    case "restore.reconciled": {
      const marked = (yield* run("MarkRestoreReconciled", [JSON.stringify({ reconciledAt: command.nowSeconds }), now])) > 0n;
      return { kind: "restore.reconciled", marked };
    }
    case "restore.resume": {
      const hold = yield* get("GetRestoreHold", []);
      if (hold === null) return { kind: "restore.resume", outcome: "not_held" };
      if (reconciledAtOf(hold.payload) === null) return { kind: "restore.resume", outcome: "unreconciled" };
      yield* run("ReleaseRestoreHold", []);
      return { kind: "restore.resume", outcome: "resumed" };
    }
    case "work.event_processed": return { kind: "work.event_processed", marked: yield* markProviderEventProcessed(command.eventId, command.nowSeconds) };
    case "webhook.ingest": {
      const stored = yield* run("InsertProviderEvent", [command.eventId, command.eventType, command.objectId, BigInt(command.eventCreatedAt), now, command.subscribed ? null : now, command.rawBody]);
      if (stored === 0n) return { kind: "webhook.ingest", outcome: "duplicate" };
      if (command.subscribed) yield* run("EnsureWorkItem", [ProviderEventKind, providerEventKey(command.eventId), JSON.stringify({ event: command.eventId }), now, now, now]);
      return { kind: "webhook.ingest", outcome: "stored" };
    }
  }
}

function reconciledAtOf(payload: string): number | null {
  const parsed: unknown = JSON.parse(payload);
  const value = typeof parsed === "object" && parsed !== null ? (parsed as Record<string, unknown>)["reconciledAt"] : undefined;
  return typeof value === "number" && Number.isSafeInteger(value) ? value : null;
}

export function* workQueryProgram(query: WorkQuery): Program<WorkQueryResult> {
  switch (query.kind) {
    case "operations.status": {
      const now = BigInt(query.nowSeconds);
      const row = yield* get("GetOperationsStatus", [now, now, now, now, now - BigInt(StalledRefundSeconds)]);
      if (row === null) throw new Error("work: GetOperationsStatus returned no row");
      const backlog = (count: bigint, since: bigint | null): Backlog => ({ count: Number(count), oldestAgeSeconds: since === null ? null : Math.max(0, query.nowSeconds - Number(since)) });
      return {
        kind: "operations.status",
        nowSeconds: query.nowSeconds,
        status: {
          held: row.held > 0n,
          pendingPayments: backlog(row.pending_payments, row.pending_payments_since),
          unknownOperations: backlog(row.unknown_operations, row.unknown_operations_since),
          unprocessedEvents: backlog(row.unprocessed_events, row.unprocessed_events_since),
          dueWork: backlog(row.due_work, row.due_work_since),
          deadWork: backlog(row.dead_work, row.dead_work_since),
          openRefunds: backlog(row.open_refunds, row.open_refunds_since),
          stalledRefunds: Number(row.stalled_refunds),
        },
      };
    }
    case "restore.targets": {
      const hold = yield* get("GetRestoreHold", []);
      const payments = yield* all("ListRestorePayments", []);
      const refunds = yield* all("ListRestoreRefunds", []);
      return {
        kind: "restore.targets",
        held: hold !== null,
        reconciledAt: hold === null ? null : reconciledAtOf(hold.payload),
        payments: payments.map((row) => ({ intentId: row.payment_intent_id, state: row.state })),
        refunds: refunds.map((row) => ({ id: row.id, intentId: row.payment_intent_id, state: row.state })),
      };
    }
    case "work.next": {
      const row = yield* get("GetNextWorkAt", []);
      return { kind: "work.next", nextAt: row?.next_at == null ? null : Number(row.next_at) };
    }
    case "work.dead": {
      const rows = yield* all("ListDeadWork", []);
      return {
        kind: "work.dead",
        items: rows.map((row) => ({
          id: row.id, kind: row.kind, key: row.unique_key, attempts: Number(row.attempts), failureClass: row.failure_class as "retryable" | "permanent" | "blocked" | null,
          lastError: row.last_error, updatedAt: Number(row.updated_at),
        })),
      };
    }
    case "work.provider_event": {
      const row = yield* get("GetProviderEvent", [query.eventId]);
      return {
        kind: "work.provider_event",
        event: row === null ? null : {
          eventId: row.stripe_event_id, eventType: row.event_type, objectId: row.object_id, eventCreatedAt: Number(row.event_created_at),
          receivedAt: Number(row.received_at), processedAt: row.processed_at === null ? null : Number(row.processed_at),
        },
      };
    }
  }
}
