export class StripeConfigError extends Error {
  readonly _tag = "StripeConfigError";
  constructor(message: string) { super(`stripe: ${message}`); }
}

export class StripeApiError extends Error {
  readonly _tag = "StripeApiError";
  readonly status: number;
  readonly errorType: string;
  readonly code: string | null;
  readonly param: string | null;
  readonly requestId: string | null;
  constructor(status: number, errorType: string, code: string | null, param: string | null, requestId: string | null, message: string) {
    super(`stripe: ${status} ${errorType}${code === null ? "" : `/${code}`}: ${message}`);
    this.status = status;
    this.errorType = errorType;
    this.code = code;
    this.param = param;
    this.requestId = requestId;
  }

  get isIdempotencyMismatch(): boolean { return this.errorType === "idempotency_error"; }
}

export class StripeTransportError extends Error {
  readonly _tag = "StripeTransportError";
  readonly kind: "timeout" | "network";
  constructor(kind: "timeout" | "network", method: string, path: string, options?: ErrorOptions) {
    super(`stripe: ${kind} calling ${method} ${path}`, options);
    this.kind = kind;
  }
}

export class StripeDecodeError extends Error {
  readonly _tag = "StripeDecodeError";
  readonly path: string;
  readonly detail: string;
  readonly status: number | null;
  constructor(path: string, detail: string, status: number | null = null) {
    super(`stripe: undecodable response at ${path}: ${detail}`);
    this.path = path;
    this.detail = detail;
    this.status = status;
  }
}

export type StripeFailure = StripeApiError | StripeTransportError | StripeDecodeError;

export function isOutcomeUnknown(error: unknown): boolean {
  if (error instanceof StripeTransportError) return true;
  if (error instanceof StripeDecodeError) return error.status !== null && error.status >= 200 && error.status < 300;
  if (error instanceof StripeApiError) return error.status >= 500 || error.status === 409 || error.status === 429;
  return false;
}
