const RecordedEventTypes = [
  "checkout.session.completed", "payment_intent.amount_capturable_updated", "payment_intent.succeeded", "payment_intent.canceled", "review.opened",
] as const;

export class TenantStore extends ReleaseTenantStore {
  #calls = 0;
  #marked = false;

  protected override providerEventHandlers(settings: PaymentSettings): ProviderEventHandlers {
    if ((this.env as unknown as Readonly<Record<string, unknown>>)[TEST_RECORD_EVENTS_BINDING] !== "1") return super.providerEventHandlers(settings);
    const handlers = new ProviderEventHandlers();
    for (const type of RecordedEventTypes) {
      handlers.on(type, async (event) => {
        this.runWriteTransaction((tx) => { tx.run("INSERT INTO test_handled (label) VALUES (?)", [`${event.type}:${event.id}`]); });
      });
    }
    return handlers;
  }

  protected override workRegistry(): WorkRegistry {
    const registry = super.workRegistry();
    if (!this.#marked) {
      this.#marked = true;
      registry.register("test_marker", async (item) => {
        this.runWriteTransaction((tx) => { tx.run("INSERT INTO test_handled (label) VALUES (?)", [`marker:${item.key}`]); });
      });
    }
    return registry;
  }

  async testAlarm(): Promise<RpcResult<number | null>> {
    const alarm = await this.ctx.storage.getAlarm();
    return wrapRpcResult(() => alarm);
  }

  async testDeleteAlarm(): Promise<RpcResult<void>> {
    await this.ctx.storage.deleteAlarm();
    return wrapRpcResult(() => undefined);
  }

  override async commerceCommand(requestText: string): Promise<RpcResult<string>> {
    this.#calls++;
    return await super.commerceCommand(requestText);
  }

  override async commerceQuery(requestText: string): Promise<RpcResult<string>> {
    this.#calls++;
    return await super.commerceQuery(requestText);
  }

  async testCommerceCalls(reset: boolean): Promise<RpcResult<number>> {
    return wrapRpcResult(() => {
      const calls = this.#calls;
      if (reset) this.#calls = 0;
      return calls;
    });
  }

  async testExec(script: string): Promise<RpcResult<void>> {
    return wrapRpcResult(() => {
      this.runWriteTransaction((tx) => {
        this.ensureMigrationsVerified(tx);
        tx.script(script);
      });
    });
  }

  async testQuery(sql: string, params: readonly SQLValue[] = []): Promise<RpcResult<readonly SQLRow[]>> {
    return wrapRpcResult(() => this.runReadTransaction((tx) => tx.all(sql, params)));
  }
}

export type TestAdminEnv = Readonly<Record<string, unknown>> & { readonly TENANT_STORE: { idFromName(name: string): unknown; get(id: unknown): unknown }; readonly MEDIA: R2BucketLike };

export const testAdminMount = (blobs: (env: TestAdminEnv, tenantId: string) => BlobStore) => (access: AdminMountAccess): AdminMount => {
  let handler: Promise<AdminMount> | undefined;
  const build = async (): Promise<AdminMount> => {
    const env = access.env() as unknown as TestAdminEnv;
    const raw = env[TEST_IDENTITY_BINDING];
    if (typeof raw !== "string") throw new Error(`cloudflare test entry: the ${TEST_IDENTITY_BINDING} binding is missing`);
    const binding = JSON.parse(raw) as TestIdentityBinding;
    if (!validIssuer(binding.issuerOrigin)) throw new Error("cloudflare test entry: invalid test issuer");
    const verifier = { issuer: binding.issuerOrigin, keys: new Map([[binding.kid, await importAssertionKey(binding.publicJwk)]]) };
    const rawUploader = env[TEST_UPLOADER_BINDING];
    const uploader = typeof rawUploader === "string" ? (JSON.parse(rawUploader) as TestUploaderBinding) : null;
    return createAdminHandler({
      tenantId: access.manifest.id,
      origin: `${access.manifest.origin.scheme}://${access.manifest.origin.host}`,
      localHTTP: access.manifest.origin.scheme === "http",
      grants: { owners: binding.owners, operators: binding.operators },
      authenticator: testAuthenticator({ issuerOrigin: binding.issuerOrigin, verifier }),
      backend: cloudflareAdminBackend(() => env.TENANT_STORE.get(env.TENANT_STORE.idFromName(access.manifest.id)) as CommerceRpcStub),
      blobs: blobs(env, access.manifest.id),
      ...(uploader === null ? {} : { uploader: { file: uploader.file, contentType: uploader.contentType, body: new TextEncoder().encode(uploader.code) } }),
    });
  };
  return { handle: async (input) => await (handler ??= build()).then((mount) => mount.handle(input)) };
};

export function createCloudflareWorker(manifest: EmbeddedTenantManifest): CloudflareTenantWorker {
  return createTenantWorker(manifest, statsObserver, undefined, testAdminMount((env) => r2BlobStore(env.MEDIA)));
}
