import type { QuoteView } from "./operations.ts";

export interface HostedSessionRequest {
  readonly attemptRef: string;
  readonly idempotencyKey: string;
  readonly quote: QuoteView;
  readonly acceptedAtSeconds: number;
}

export interface HostedSession {
  readonly sessionId: string;
  readonly url: string;
  readonly expiresAtSeconds: number;
}

export interface HostedSessionCreator {
  create(request: HostedSessionRequest): Promise<HostedSession>;
}

export const StripeCheckoutOrigin = "https://checkout.stripe.com";
export const SimulatorCheckoutHost = "stripe-sim.localhost";

export function checkoutOrigin(apiBase: string | null): string {
  if (apiBase === null) return StripeCheckoutOrigin;
  const url = new URL(apiBase);
  return `${url.protocol}//${SimulatorCheckoutHost}${url.port === "" ? "" : `:${url.port}`}`;
}
