import { LIFETIME_MS, encodeToken, parseToken } from "../session/session.ts";
import { hmacSha256, sha256 } from "./keyed_digest.ts";

export const MinAccessKeyLength = 32;
export const OrderCookieName = "__Host-nanoshop_order";
export const DevOrderCookieName = "nanoshop_dev_order";

const encoder = new TextEncoder();

export interface AccessCredential {
  readonly token: string;
  readonly digestHex: string;
}

export function accessCredential(key: string, messageId: bigint, generation: bigint): AccessCredential {
  if (key.length < MinAccessKeyLength) throw new RangeError(`order access key must be at least ${MinAccessKeyLength} characters`);
  const bytes = hmacSha256(encoder.encode(key), encoder.encode(`order-access\0${messageId}\0${generation}`));
  return { token: encodeToken(bytes), digestHex: [...sha256(bytes)].map((byte) => byte.toString(16).padStart(2, "0")).join("") };
}

export async function presentedDigestHex(token: string): Promise<string | null> {
  if (parseToken(token) === null) return null;
  const bytes = Uint8Array.from(atob(token.replaceAll("-", "+").replaceAll("_", "/") + "="), (character) => character.charCodeAt(0));
  return [...sha256(bytes)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

export function readOrderToken(headers: Headers, localHTTP: boolean): string | null {
  const name = localHTTP ? DevOrderCookieName : OrderCookieName;
  const values: string[] = [];
  for (const part of (headers.get("cookie") ?? "").split(";")) {
    const separator = part.indexOf("=");
    if (separator < 0 || part.slice(0, separator).trim() !== name) continue;
    values.push(part.slice(separator + 1).trim());
  }
  return values.length === 1 ? parseToken(values[0]!) : null;
}

export function orderCookie(token: string, localHTTP: boolean, now = Date.now()): string {
  if (parseToken(token) === null) throw new Error("Invalid order access cookie");
  const expires = new Date(now + LIFETIME_MS);
  const name = localHTTP ? DevOrderCookieName : OrderCookieName;
  return `${name}=${token}; Path=/; Expires=${expires.toUTCString()}; Max-Age=${Math.floor(LIFETIME_MS / 1000)}; HttpOnly${localHTTP ? "" : "; Secure"}; SameSite=Lax`;
}
