import { Schema } from "effect";
import { Integer } from "../storefront/queries.ts";

const Text = Schema.String;
const Count = Schema.Struct({ n: Integer });
const Collectable = Schema.Struct({ id: Integer, sha256: Text, content_type: Text });
const ImageSlot = Schema.Struct({ id: Integer, position: Integer });

export const mediaRowSchemas = {
  CountMediaAssets: Count,
  CountPendingMedia: Count,
  NextMediaId: Schema.Struct({ id: Integer }),
  GetMediaAsset: Schema.Struct({
    id: Integer, sha256: Text, bytes: Integer, width: Integer, height: Integer, content_type: Text, state: Text,
    created_at: Integer, ready_at: Schema.NullOr(Integer), card_id: Schema.NullOr(Integer),
  }),
  ListExpiredPendingMedia: Collectable,
  ListUnreferencedMedia: Collectable,
  CatalogNextImagePosition: Schema.Struct({ position: Integer }),
  CountCatalogProductImages: Count,
  GetCatalogProductImage: Schema.Struct({ id: Integer, product_id: Integer, position: Integer, media_id: Schema.NullOr(Integer) }),
  GetCatalogImageAbove: ImageSlot,
  GetCatalogImageBelow: ImageSlot,
} as const;

export const mediaWriteQueries = [
  "InsertPendingMedia", "MarkMediaReady", "DeleteMediaAsset", "InsertCatalogMediaImage", "DeleteCatalogProductImage",
  "SetCatalogImageAlt", "SetCatalogImagePosition",
] as const;
