export interface Compressor {
  gzip(body: Uint8Array, level: "default" | "best-speed"): Promise<Uint8Array>;
  brotli(body: Uint8Array, quality: 1 | 5): Promise<Uint8Array>;
}
export type CachePolicy = "public" | "private";
export interface ResponseInput {
  readonly status: number;
  readonly contentType?: string;
  readonly cache: CachePolicy;
  readonly body?: Uint8Array;
  readonly headers?: Headers;
}
export interface CompressionOptions { readonly compressor?: Compressor; readonly cached?: boolean; readonly gzip?: boolean; readonly brotli?: boolean }
type Coding = "" | "gzip" | "br";

// Each response owns its bytes; neither cache readers nor transport adapters can mutate them.
export class PreparedResponse {
  readonly status: number;
  readonly contentType: string;
  readonly cache: CachePolicy;
  readonly etag: string;
  readonly #body: Uint8Array;
  readonly #gzip: Uint8Array | undefined;
  readonly #brotli: Uint8Array | undefined;
  readonly #headers: Headers;
  constructor(input: ResponseInput, gzipBody?: Uint8Array, brotliBody?: Uint8Array, etag = "") {
    this.status = input.status;
    this.contentType = input.contentType ?? "";
    this.cache = input.cache;
    this.#body = input.body?.slice() ?? new Uint8Array();
    this.#gzip = gzipBody?.slice();
    this.#brotli = brotliBody?.slice();
    this.#headers = new Headers(input.headers);
    this.etag = etag;
    Object.freeze(this);
  }
  get byteLength(): number { return this.#body.length + (this.#gzip?.length ?? 0) + (this.#brotli?.length ?? 0) + this.etag.length; }
  get body(): Uint8Array<ArrayBuffer> { return this.#body.slice(); }
  get headers(): Headers { return new Headers(this.#headers); }
  get hasCompressed(): boolean { return this.#gzip !== undefined || this.#brotli !== undefined; }
  hasRepresentation(coding: Coding): boolean { return coding === "" || (coding === "gzip" ? this.#gzip !== undefined : this.#brotli !== undefined); }
  representation(coding: Coding): Uint8Array<ArrayBuffer> | undefined {
    return (coding === "gzip" ? this.#gzip : coding === "br" ? this.#brotli : this.#body)?.slice();
  }
}

async function compress(body: Uint8Array, coding: "gzip" | "br", cached: boolean, compressor: Compressor): Promise<Uint8Array | undefined> {
  const result = coding === "gzip"
    ? await compressor.gzip(body, cached ? "default" : "best-speed")
    : await compressor.brotli(body, cached ? 5 : 1);
  return result.length > body.length * 9 / 10 ? undefined : new Uint8Array(result);
}
function requiredCompressor(options: CompressionOptions): Compressor {
  if (options.compressor === undefined) throw new Error("compression requested without a compressor");
  return options.compressor;
}
export function compressible(contentType: string): boolean {
  return ["text/", "application/json", "image/svg+xml"].some((prefix) => contentType.startsWith(prefix));
}
export async function weakETag(body: Uint8Array): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", body.slice()));
  const encoded = btoa(String.fromCharCode(...digest.slice(0, 18))).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
  return `W/"${encoded}"`;
}
export function etagMatches(header: string | null, etag: string): boolean {
  if (header === null || header === "") return false;
  const expected = etag.replace(/^W\//, "");
  return header.split(",").some((part) => part.trim() === "*" || part.trim().replace(/^W\//, "") === expected);
}
export function acceptsEncoding(headers: Headers, encoding: "gzip" | "br"): boolean {
  for (const item of (headers.get("accept-encoding") ?? "").split(",")) {
    const semicolon = item.indexOf(";");
    const coding = (semicolon < 0 ? item : item.slice(0, semicolon)).trim();
    if (coding.toLowerCase() !== encoding) continue;
    const params = semicolon < 0 ? "" : item.slice(semicolon + 1).trim();
    if (params === "") return true;
    const canonical = params.replaceAll(" ", "");
    if (!canonical.startsWith("q=")) return false;
    const raw = canonical.slice(2);
    const quality = Number(raw);
    return /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(raw) && quality > 0 && quality <= 1;
  }
  return false;
}
export async function prepareResponse(input: ResponseInput, options: CompressionOptions = {}): Promise<PreparedResponse> {
  const body = input.body?.slice() ?? new Uint8Array();
  const ownedInput = { ...input, body, headers: new Headers(input.headers) };
  const eligible = body.length >= 1024 && compressible(input.contentType ?? "");
  const cached = options.cached ?? false;
  const wantGzip = eligible && (options.gzip ?? cached);
  const wantBrotli = eligible && (options.brotli ?? cached);
  let gzipBody: Uint8Array | undefined;
  let brotliBody: Uint8Array | undefined;
  if (wantGzip || wantBrotli) {
    const compressor = requiredCompressor(options);
    [gzipBody, brotliBody] = await Promise.all([
      wantGzip ? compress(body, "gzip", cached, compressor) : undefined,
      wantBrotli ? compress(body, "br", cached, compressor) : undefined,
    ]);
  }
  const etag = input.status === 200 && input.cache === "public" ? await weakETag(body) : "";
  return new PreparedResponse(ownedInput, gzipBody, brotliBody, etag);
}

function selectedCoding(request: Request, prepared: PreparedResponse): Coding {
  if (acceptsEncoding(request.headers, "br") && prepared.hasRepresentation("br")) return "br";
  if (acceptsEncoding(request.headers, "gzip") && prepared.hasRepresentation("gzip")) return "gzip";
  return "";
}
export function responseFor(request: Request, prepared: PreparedResponse, base?: Headers): Response {
  const headers = new Headers(base);
  const specific = prepared.headers;
  specific.forEach((value, key) => { if (key !== "set-cookie") headers.set(key, value); });
  for (const cookie of specific.getSetCookie()) headers.append("Set-Cookie", cookie);
  if (prepared.contentType !== "") headers.set("Content-Type", prepared.contentType);
  headers.set("Cache-Control", prepared.cache === "private" ? "private, no-store" : "no-cache");
  if (prepared.hasCompressed) headers.append("Vary", "Accept-Encoding");
  if (prepared.etag !== "") {
    headers.set("ETag", prepared.etag);
    if (prepared.status === 200 && etagMatches(request.headers.get("if-none-match"), prepared.etag)) {
      headers.delete("content-length");
      headers.delete("content-encoding");
      return new Response(null, { status: 304, headers });
    }
  }
  const coding = selectedCoding(request, prepared);
  const body = prepared.representation(coding)!;
  if (coding !== "") headers.set("Content-Encoding", coding);
  headers.set("Content-Length", String(body.length));
  return new Response(request.method === "HEAD" || [204, 205, 304].includes(prepared.status) ? null : body, { status: prepared.status, headers });
}

export interface AssetInput {
  readonly body: Uint8Array; readonly contentType: string; readonly etag: string; readonly immutable: boolean;
  readonly gzip?: Uint8Array; readonly brotli?: Uint8Array;
}
export class AssetRepresentation {
  readonly etag: string;
  readonly immutable: boolean;
  readonly response: PreparedResponse;
  constructor(input: AssetInput) {
    this.etag = input.etag;
    this.immutable = input.immutable;
    this.response = new PreparedResponse({ status: 200, contentType: input.contentType, cache: "public", body: input.body }, input.gzip, input.brotli);
    Object.freeze(this);
  }
}
interface ByteRange { readonly start: number; readonly end: number }
function ranges(raw: string, size: number): readonly ByteRange[] {
  if (!raw.startsWith("bytes=")) throw new Error("Invalid range");
  const result: ByteRange[] = [];
  let noOverlap = false;
  const number = (value: string): bigint => {
    if (!/^\+?[0-9]+$/.test(value)) throw new Error("Invalid range");
    const parsed = BigInt(value);
    if (parsed > 9223372036854775807n) throw new Error("Invalid range");
    return parsed;
  };
  for (const part of raw.slice(6).split(",")) {
    const trimmed = part.trim();
    if (trimmed === "") continue;
    const separator = trimmed.indexOf("-");
    if (separator < 0) throw new Error("Invalid range");
    const rawStart = trimmed.slice(0, separator).trim();
    const rawEnd = trimmed.slice(separator + 1).trim();
    if (rawStart === "") {
      const count = number(rawEnd);
      result.push({ start: count > BigInt(size) ? 0 : size - Number(count), end: size - 1 });
      continue;
    }
    const start = number(rawStart);
    if (start >= BigInt(size)) { noOverlap = true; continue; }
    const end = rawEnd === "" ? BigInt(size - 1) : number(rawEnd);
    if (end < start) throw new Error("Invalid range");
    result.push({ start: Number(start), end: end >= BigInt(size) ? size - 1 : Number(end) });
  }
  if (noOverlap && result.length === 0 && size > 0) throw new Error("Range does not overlap");
  return result;
}

export function assetResponse(request: Request, asset: AssetRepresentation, base?: Headers): Response {
  const headers = new Headers(base);
  if (request.method !== "GET" && request.method !== "HEAD") {
    headers.set("Allow", "GET, HEAD");
    return new Response("Method Not Allowed\n", { status: 405, headers });
  }
  if (new URL(request.url).search !== "") return new Response("404 page not found\n", { status: 404, headers });
  const prepared = asset.response;
  headers.set("Content-Type", prepared.contentType);
  headers.set("Cache-Control", asset.immutable ? "public, max-age=31536000, immutable" : "public, max-age=300");
  const rangeHeader = request.headers.get("range") ?? "";
  const coding = rangeHeader === "" ? selectedCoding(request, prepared) : "";
  const etag = coding === "" ? asset.etag : asset.etag.replace(/"$/, `-${coding}"`);
  headers.set("ETag", etag);
  if (prepared.hasCompressed) headers.append("Vary", "Accept-Encoding");
  if (coding === "") {
    const ifMatch = request.headers.get("if-match");
    if (ifMatch !== null && ifMatch !== "*" && !ifMatch.split(",").some((part) => part.trim() === etag && !part.trim().startsWith("W/"))) return new Response(null, { status: 412, headers });
  }
  if (etagMatches(request.headers.get("if-none-match"), etag)) return new Response(null, { status: 304, headers });
  if (coding !== "") headers.set("Content-Encoding", coding);
  let body = prepared.representation(coding)!;
  let status = 200;
  if (coding === "") {
    headers.set("Accept-Ranges", "bytes");
    const ifRange = request.headers.get("if-range");
    if (rangeHeader !== "" && (ifRange === null || ifRange === etag)) {
      let requested: readonly ByteRange[];
      try { requested = ranges(rangeHeader, body.length); } catch {
        headers.set("Content-Range", `bytes */${body.length}`);
        return new Response(request.method === "HEAD" ? null : "invalid range\n", { status: 416, headers });
      }
      const total = requested.reduce((sum, range) => sum + range.end - range.start + 1, 0);
      if (total <= body.length && requested.length === 1) {
        const range = requested[0]!;
        headers.set("Content-Range", `bytes ${range.start}-${range.end}/${body.length}`);
        body = body.slice(range.start, range.end + 1);
        status = 206;
      } else if (total <= body.length && requested.length > 1) {
        const boundary = "nanoshop-" + crypto.randomUUID();
        const encoder = new TextEncoder();
        const chunks: Uint8Array[] = [];
        for (const range of requested) {
          chunks.push(encoder.encode(`--${boundary}\r\nContent-Range: bytes ${range.start}-${range.end}/${body.length}\r\nContent-Type: ${prepared.contentType}\r\n\r\n`), body.slice(range.start, range.end + 1), encoder.encode("\r\n"));
        }
        chunks.push(encoder.encode(`--${boundary}--\r\n`));
        const multipart = new Uint8Array(chunks.reduce((sum, chunk) => sum + chunk.length, 0));
        let offset = 0;
        for (const chunk of chunks) { multipart.set(chunk, offset); offset += chunk.length; }
        body = multipart;
        headers.set("Content-Type", `multipart/byteranges; boundary=${boundary}`);
        status = 206;
      }
    }
  }
  headers.set("Content-Length", String(body.length));
  return new Response(request.method === "HEAD" ? null : body, { status, headers });
}

export class PageTooLarge extends Error { constructor() { super("Rendered page exceeds limit"); this.name = "PageTooLarge"; } }
export class BoundedRenderBuffer {
  readonly #maximum: number;
  readonly #chunks: Uint8Array[] = [];
  #size = 0;
  constructor(maximum = 4 << 20) { this.#maximum = maximum; }
  write(value: string | Uint8Array): void {
    const bytes = typeof value === "string" ? new TextEncoder().encode(value) : value;
    if (this.#size + bytes.length > this.#maximum) throw new PageTooLarge();
    this.#chunks.push(bytes.slice());
    this.#size += bytes.length;
  }
  bytes(): Uint8Array {
    const result = new Uint8Array(this.#size);
    let offset = 0;
    for (const chunk of this.#chunks) { result.set(chunk, offset); offset += chunk.length; }
    return result;
  }
}
