import { newToken, parseToken } from "../session/session.ts";
import { decodeBase64Url, encodeBase64Url } from "./assertion.ts";
import { AdminSessionAbsoluteSeconds, SignInStateSeconds } from "./policy.ts";

export const ADMIN_COOKIE_NAME = "__Host-nanoshop_admin";
export const DEV_ADMIN_COOKIE_NAME = "nanoshop_dev_admin";
export const SIGN_IN_STATE_COOKIE_NAME = "__Host-nanoshop_admin_state";
export const DEV_SIGN_IN_STATE_COOKIE_NAME = "nanoshop_dev_admin_state";

export function adminCookieName(localHTTP: boolean): string {
  return localHTTP ? DEV_ADMIN_COOKIE_NAME : ADMIN_COOKIE_NAME;
}

function stateCookieName(localHTTP: boolean): string {
  return localHTTP ? DEV_SIGN_IN_STATE_COOKIE_NAME : SIGN_IN_STATE_COOKIE_NAME;
}

function readCookie(headers: Headers, name: string): string | null {
  const values: string[] = [];
  for (const part of (headers.get("cookie") ?? "").split(";")) {
    const separator = part.indexOf("=");
    if (separator < 0 || part.slice(0, separator).trim() !== name) continue;
    values.push(part.slice(separator + 1).trim());
  }
  return values.length === 1 ? values[0]! : null;
}

function attributes(localHTTP: boolean, sameSite: "Strict" | "Lax", maxAge: number): string {
  return `Path=/; Max-Age=${maxAge}; HttpOnly${localHTTP ? "" : "; Secure"}; SameSite=${sameSite}`;
}

export function readAdminToken(headers: Headers, localHTTP: boolean): string | null {
  const raw = readCookie(headers, adminCookieName(localHTTP));
  return raw === null ? null : parseToken(raw);
}

export function adminSessionCookie(token: string, localHTTP: boolean): string {
  if (parseToken(token) === null) throw new Error("identity: invalid admin session token");
  return `${adminCookieName(localHTTP)}=${token}; ${attributes(localHTTP, "Strict", AdminSessionAbsoluteSeconds)}`;
}

export function clearedAdminCookie(localHTTP: boolean): string {
  return `${adminCookieName(localHTTP)}=; ${attributes(localHTTP, "Strict", 0)}`;
}

export type SignInPurpose = "sign-in" | "reauth";
export interface SignInState {
  readonly nonce: string;
  readonly purpose: SignInPurpose;
  readonly returnTo: string;
  readonly sessionDigest: string | null;
}

export function newSignInState(purpose: SignInPurpose, returnTo: string, sessionDigest: string | null = null): SignInState {
  if ((purpose === "reauth") !== (sessionDigest !== null)) throw new Error("identity: only a re-authentication names a session");
  return { nonce: newToken(), purpose, returnTo, sessionDigest };
}

export function signInStateCookie(state: SignInState, localHTTP: boolean): string {
  const value = `${state.nonce}.${state.purpose}.${encodeBase64Url(new TextEncoder().encode(state.returnTo))}.${state.sessionDigest ?? "-"}`;
  return `${stateCookieName(localHTTP)}=${value}; ${attributes(localHTTP, "Lax", SignInStateSeconds)}`;
}

export function clearedSignInStateCookie(localHTTP: boolean): string {
  return `${stateCookieName(localHTTP)}=; ${attributes(localHTTP, "Lax", 0)}`;
}

export function readSignInState(headers: Headers, localHTTP: boolean): SignInState | null {
  const raw = readCookie(headers, stateCookieName(localHTTP));
  if (raw === null) return null;
  const parts = raw.split(".");
  if (parts.length !== 4) return null;
  const [nonce, purpose, encodedReturn, digest] = parts as [string, string, string, string];
  if (parseToken(nonce) === null || (purpose !== "sign-in" && purpose !== "reauth")) return null;
  const sessionDigest = digest === "-" ? null : digest;
  if ((purpose === "reauth") !== (sessionDigest !== null) || (sessionDigest !== null && !/^[0-9a-f]{64}$/.test(sessionDigest))) return null;
  const bytes = decodeBase64Url(encodedReturn);
  if (bytes === null) return null;
  try {
    return { nonce, purpose, returnTo: new TextDecoder("utf-8", { fatal: true }).decode(bytes), sessionDigest };
  } catch {
    return null;
  }
}
