import type { Effect } from "effect";

export type SQLValue = null | string | number | bigint | Uint8Array;
export type SQLBoundValue = null | string | Uint8Array;
export type SQLRow = Readonly<Record<string, SQLValue>>;

export class DatabaseError extends Error {
  readonly _tag = "DatabaseError";
  constructor(message: string, cause?: unknown) { super(message, { cause }); this.name = "DatabaseError"; }
}

/** Persistence callbacks receive only their pinned transaction, never a pool. */
export interface Transaction {
  all(sql: string, params?: readonly SQLValue[]): Effect.Effect<readonly SQLRow[], DatabaseError>;
  get(sql: string, params?: readonly SQLValue[]): Effect.Effect<SQLRow | null, DatabaseError>;
  run(sql: string, params?: readonly SQLValue[]): Effect.Effect<{ readonly changes: bigint; readonly lastInsertRowid: bigint }, DatabaseError>;
  script(sql: string): Effect.Effect<void, DatabaseError>;
}

export interface SyncTransaction {
  all(sql: string, params?: readonly SQLValue[]): readonly SQLRow[];
  get(sql: string, params?: readonly SQLValue[]): SQLRow | null;
  run(sql: string, params?: readonly SQLValue[]): { readonly changes: bigint; readonly lastInsertRowid: bigint };
  script(sql: string): void;
}

export interface DatabaseBackend {
  read<A, E, R>(operation: (transaction: Transaction) => Effect.Effect<A, E, R>): Effect.Effect<A, E | DatabaseError, R>;
  write<A, E, R>(operation: (transaction: Transaction) => Effect.Effect<A, E, R>): Effect.Effect<A, E | DatabaseError, R>;
}

export interface MigrationVerifier<DB extends DatabaseBackend = DatabaseBackend> {
  verify(database: DB): Effect.Effect<void, DatabaseError>;
}
